// Booking domain constants and planning helpers live in ./assets/booking-core.js.
let laserDragActive = false;
let laserDragScrollRaf = null;
let laserDragLastY = 0;
let laserPointerDrag = null;
let laserDragDropTarget = null;
let laserUnplaceDropTarget = null;
let laserDragSuppressClickUntil = 0;
let bowlingPointerDrag = null;
let bowlingDragDropTarget = null;
let bowlingDragPreviewEls = [];
let bowlingDragSuppressClickUntil = 0;
let bowlingDragSaveSeq = 0;
const bowlingDragLatestSeqByReservation = {};
let statusSaveSeq = 0;
const statusSaveLatestSeqByReservation = {};
let activitySaveSeq = 0;
const activitySaveLatestSeqByReservation = {};
const pendingReservationWriteIds = new Set();
let planningMoveNoticeTimer = null;
let planningMoveSelection = null;
const PLANNING_MOVE_HOLD_MS = 1000;
function planningMoveSessionKey(){return JSON.stringify([state.view,state.staffAuthSession?.member?.id,state.staffAuthSession?.expiresAt,state.staffAuthSession?.token]);}

// A held booking stays selected after release. Cards toggle the selected lanes;
// dragging any selected card drops the selected group directly.
function selectPlanningMove(type, reservationId, sourceLane = null, sourceStart = null, unitKey = null) {
  if(planningMoveSelection?.saving)return;
  const reservation = state.reservations.find(r => Number(r.id) === Number(reservationId));
  if (!reservation || reservation.status === 'cancelled') return;
  cancelPlanningMove(false,true);
  const windowLanes=type==='bowling'?getBowlingWindowsFromReservation(reservation).flatMap(item=>item.lanes||[]):[];
  const sourceLanes = type === 'bowling' ? [...new Set(windowLanes.length?windowLanes:reservation.lanes||[])].map(Number).sort((a,b)=>a-b) : [];
  planningMoveSelection = { type, reservationId: Number(reservationId), sourceLane, sourceStart, unitKey, sourceLanes, allLanes: sourceLanes.slice(), date: state.currentDate, centerId: getCurrentStaffCenterId(), sessionKey:planningMoveSessionKey(), version: reservation.updatedAt, targetLane: null, targetStart: null, saving: false };
  bowlingDragSuppressClickUntil = laserDragSuppressClickUntil = Date.now() + 600;
  renderPlanningMoveSelection();
}

function renderPlanningMoveSelection() {
  document.getElementById('planningMoveSelection')?.remove();
  refreshPlanningMoveHighlights();
}

function refreshPlanningMoveHighlights() {
  const s=planningMoveSelection;if(!s)return;
  if(!s.saving&&(state.currentDate!==s.date||getCurrentStaffCenterId()!==s.centerId||planningMoveSessionKey()!==s.sessionKey)){cancelPlanningMove(false);return;}
  document.querySelectorAll('.is-move-selected,.is-move-deselected').forEach(el=>{el.classList.remove('is-move-selected','is-move-deselected');el.removeAttribute('aria-pressed');});
  document.querySelectorAll(s.type==='bowling'?`.booking[data-booking-res-id="${s.reservationId}"]`:`[data-laser-res-id="${s.reservationId}"][data-laser-unit="${s.unitKey}"]`).forEach(el=> { const selected=s.type==='laser'||s.sourceLanes.includes(Number(el.dataset.bookingLane)); el.classList.add(selected?'is-move-selected':'is-move-deselected');el.setAttribute('aria-pressed',String(selected)); });
}

function cancelPlanningMove(restoreFocus = true, preserveGesture = false) {
  const s = planningMoveSelection;
  if (s?.saving) return;
  if(!preserveGesture){
    clearTimeout(bowlingPointerDrag?.holdTimer);clearTimeout(laserPointerDrag?.holdTimer);
    cancelBowlingPointerDrag();cancelLaserPointerDrag();
    document.removeEventListener('mousemove',onBowlingPointerMove,true);document.removeEventListener('mouseup',onBowlingPointerUp,true);
    document.removeEventListener('mousemove',onLaserPointerMove,true);document.removeEventListener('mouseup',onLaserPointerUp,true);
    window.PinlaneTouchDrag?.interrompre();
  }
  planningMoveSelection = null;
  document.getElementById('planningMoveSelection')?.remove();
  document.querySelectorAll('.is-move-selected,.is-move-deselected').forEach(el=>{el.classList.remove('is-move-selected','is-move-deselected');el.removeAttribute('aria-pressed');});
  clearBowlingDragDropTarget(); clearLaserDragDropTarget();
  if(restoreFocus&&s) document.querySelector(s.type==='bowling'?`.booking[data-booking-res-id="${s.reservationId}"]`:`[data-laser-res-id="${s.reservationId}"][data-laser-unit="${s.unitKey}"]`)?.focus({preventScroll:true});
}
function togglePlanningMoveLane(lane, checked) { const s=planningMoveSelection;if(!s||s.saving)return;s.sourceLanes=s.allLanes.filter(l=>l===lane?checked:s.sourceLanes.includes(l));renderPlanningMoveSelection(); }
function setPlanningMoveTime(value) { const s=planningMoveSelection;if(!s||s.saving)return;const time=timeToNum(value);if(!/^\d{2}:\d{2}$/.test(value)||!Number.isFinite(time))return;s.targetStart=time;renderPlanningMoveSelection(); }
function setPlanningMoveTargetLane(value) { const s=planningMoveSelection;if(!s||s.saving)return;s.targetLane=Number(value)||null;renderPlanningMoveSelection(); }
async function commitPlanningMoveSelection() {
  const s=planningMoveSelection;if(!s||s.saving||(!s.unplace&&s.targetStart===null))return;
  const reservation=state.reservations.find(r=>Number(r.id)===s.reservationId);
  if(!reservation||state.currentDate!==s.date||getCurrentStaffCenterId()!==s.centerId||planningMoveSessionKey()!==s.sessionKey||reservation.updatedAt!==s.version) { cancelPlanningMove();showPlanningMoveNotice('Planning actualisé','La réservation ou le jour a changé. Sélectionnez à nouveau l’activité.');return; }
  if(s.type==='laser'&&!s.unplace){
    const window=getLaserWindowsFromReservation(reservation).find(item=>laserBlockUnitKey(item)===s.unitKey);
    if(window&&Math.abs(Number(window.start)-s.targetStart)<.001)return false;
  }
  s.saving=true;renderPlanningMoveSelection();
  let ok = false;
  try { ok = s.type==='laser' ? s.unplace ? await unscheduleLaserPass(s.reservationId,s.unitKey) : await scheduleLaserPass(s.reservationId,s.unitKey,s.targetStart) : await scheduleBowlingSelection(s); }
  finally { s.saving=false;delete s.unplace; if (ok || state.currentDate !== s.date || getCurrentStaffCenterId() !== s.centerId) cancelPlanningMove(); else { const current = state.reservations.find(r=>Number(r.id)===s.reservationId); if(current) s.version=current.updatedAt; renderPlanningMoveSelection(); } }
}
async function scheduleBowlingSelection(s) {
  const sessionKey = () => JSON.stringify([state.view, state.staffAuthSession?.member?.id, state.staffAuthSession?.expiresAt, state.staffAuthSession?.token]);
  const contextCenter = getCurrentStaffCenterId(), contextDate = state.currentDate, contextSession = sessionKey();
  const currentContext = () => getCurrentStaffCenterId() === contextCenter && state.currentDate === contextDate && sessionKey() === contextSession;
  const reservation=state.reservations.find(r=>Number(r.id)===s.reservationId);
  if(!reservation||!s.sourceLanes.length||!s.targetLane)return;
  const lanes=s.sourceLanes.map((lane,index)=>s.laneMapping ? Number(s.laneMapping[lane]) : s.targetLane+index);
  if(lanes.some(l=>l<1||l>getAvailabilityLaneCount()||state.laneStatuses[l]==='maintenance')) {showPlanningMoveNotice('Pistes indisponibles','Choisissez une autre piste de départ.');return;}
  const duration=getBowlingDurationForReservation(reservation)||Number(reservation.duration||1);
  const check=validateSlotWindow(reservation.date,numToTime(s.targetStart),duration,{allowPastStart:true});
  if(!check.ok){showPlanningMoveNotice('Déplacement impossible',check.message);return;}
  const laneMapping=Object.fromEntries(s.sourceLanes.map((lane,index)=>[lane,lanes[index]]));
  try {
    const payload=await envoyerDeplacementActivite(reservation,{activityId:'bowling',startTime:numToTime(s.targetStart),sourceLanes:s.sourceLanes,lanes,laneMapping});
    if (!currentContext()) return true;
    const before=getBowlingWindowsFromReservation(reservation),after=getBowlingWindowsFromReservation(payload.reservation);
    const first=Math.min(...before.filter(w=>(w.lanes||[]).some(l=>s.sourceLanes.includes(Number(l)))).map(w=>w.start));
    const delta=s.targetStart-first;
    const verified=before.every(w=>(w.lanes||[]).every(lane=>after.some(a=>
      (a.lanes||[]).includes(s.sourceLanes.includes(Number(lane))?laneMapping[lane]:Number(lane))
      &&Math.abs(a.start-(w.start+(s.sourceLanes.includes(Number(lane))?delta:0)))<.001
      &&Math.abs(a.duration-w.duration)<.001)));
    if(!verified)throw new Error('Le serveur n’a pas confirmé les pistes sélectionnées. Actualisez le planning avant de réessayer.');
    upsertReservationInState(payload.reservation);markReservationMutation(reservation.id,payload.reservation,['lanes','opsPlan']);save();renderStaffData();
    showPlanningMoveNotice('Bowling déplacé',`${s.sourceLanes.length} piste${s.sourceLanes.length>1?'s':''} · ${formatClockDisplay(s.targetStart)}`,'success');
    return true;
  } catch(error) {if(!currentContext())return false;if(error.reservation)upsertReservationInState(error.reservation);renderStaffData();showPlanningMoveNotice('Bowling non déplacé',error.message||'Ce créneau est indisponible.');return false;}
}
document.addEventListener('keydown',event=> {if(event.key==='Escape'&&planningMoveSelection&&!planningMoveSelection.saving){event.preventDefault();event.stopPropagation();cancelPlanningMove();}},true);
document.addEventListener('click',event=> {
  const s=planningMoveSelection;if(!s)return;
  const card=event.target.closest(s.type==='bowling'?'.booking[data-booking-res-id]':'[data-laser-res-id][data-laser-unit]');
  if(card&&Number(s.type==='bowling'?card.dataset.bookingResId:card.dataset.laserResId)===s.reservationId){
    event.preventDefault();event.stopPropagation();
    if(s.saving||Date.now()<(s.type==='bowling'?bowlingDragSuppressClickUntil:laserDragSuppressClickUntil))return;
    if(s.type==='bowling')togglePlanningMoveLane(Number(card.dataset.bookingLane),!s.sourceLanes.includes(Number(card.dataset.bookingLane)));
    else cancelPlanningMove(false);
    return;
  }
  if(!s.saving)cancelPlanningMove(false);
},true);
function laserTimeFromPoint(row,clientY) {const start=Number(row.dataset.laserTimeStart);const rect=row.getBoundingClientRect();return Math.round((start+Math.min(.499,Math.max(0,(clientY-rect.top)/rect.height*.5)))*12)/12;}
function planningMoveKey(event,type,id,lane=null,start=null,unit=null) { if(event.key==='m'||event.key==='M'){event.preventDefault();event.stopPropagation();selectPlanningMove(type,id,lane,start,unit);} }

function showPlanningMoveNotice(title, message = '', tone = 'warning') {
  if (typeof document === 'undefined') return;
  let notice = document.getElementById('planningMoveNotice');
  if (!notice) {
    notice = document.createElement('div');
    notice.id = 'planningMoveNotice';
    notice.setAttribute('role', 'status');
    notice.setAttribute('aria-live', 'polite');
    document.body.appendChild(notice);
  }

  notice.className = `planning-move-notice ${tone || 'warning'}`;
  notice.innerHTML = `
    <span class="planning-move-notice-dot" aria-hidden="true"></span>
    <span class="planning-move-notice-copy">
      <strong>${escapeHtml(title || 'Planning')}</strong>
      ${message ? `<small>${escapeHtml(message)}</small>` : ''}
    </span>
  `;
  notice.classList.remove('is-visible');
  if (typeof requestAnimationFrame === 'function') {
    requestAnimationFrame(() => notice.classList.add('is-visible'));
  } else {
    notice.classList.add('is-visible');
  }
  clearTimeout(planningMoveNoticeTimer);
  // LE TEMPS D AFFICHAGE SUIT LA LONGUEUR DU TEXTE. 3,6 s etaient fixes, quel
  // que soit le message : le refus de deplacement fait ~45 mots, soit environ
  // 13 s de lecture a 200 mots/minute. Movsar, 2026-08-26 : « on a pas le temps
  // de lire ici la notif ». Une confirmation courte garde son passage rapide ;
  // un refus qui explique quoi faire reste le temps d etre lu, plafonne pour ne
  // pas encombrer l ecran. La notice est en pointer-events: none : la rallonger
  // ne bloque aucun clic.
  const mots = String(`${title || ''} ${message || ''}`).trim().split(/\s+/).filter(Boolean).length;
  const duree = tone === 'success'
    ? 1900
    : Math.min(14000, Math.max(4000, Math.round(mots * 300)));
  planningMoveNoticeTimer = setTimeout(() => {
    notice.classList.remove('is-visible');
  }, duree);
}

window.showPlanningMoveNotice = showPlanningMoveNotice;

function getReservationWriteKey(id) {
  return String(Number(id));
}

// Registre des mutations optimistes en attente : id -> { fields, expected,
// signatures, deadline }. Il protège UNIQUEMENT les champs modifiés localement
// (statut, ou géométrie drag-drop lanes/startTime/opsPlan) contre l'écrasement
// par un snapshot serveur en retard (cohérence éventuelle de /api/staff-state).
// La protection tombe dès que le serveur reflète la valeur attendue, ou après un
// délai de grâce (garde-fou anti-blocage si le serveur diverge réellement).
const PENDING_MUTATION_GRACE_MS = 9000;
const pendingReservationMutations = new Map();
// Mutations réellement en vol (requête PATCH non résolue) : id -> Map<field, sig>.
// Sert à éviter le double-envoi pour un même couple (réservation, champ).
const reservationInFlightMutations = new Map();

function reservationFieldSignature(reservation, field) {
  if (!reservation) return undefined;
  switch (field) {
    case 'status':
      return String(reservation.status || '');
    case 'paymentMethod':
      return String(reservation.paymentMethod || '');
    case 'startTime':
      return String(reservation.startTime || '');
    case 'lanes':
      return (reservation.lanes || []).map(Number).filter(Number.isFinite).sort((a, b) => a - b).join(',');
    case 'opsPlan':
      return JSON.stringify((reservation.opsPlan?.resourceBlocks || []).map(block => [
        block.resourceType,
        block.startTime,
        block.endTime,
        (block.lanes || []).map(Number),
        block.players
      ]));
    default:
      return JSON.stringify(reservation[field] ?? null);
  }
}

function cloneReservationField(reservation, field) {
  const value = reservation ? reservation[field] : undefined;
  if (Array.isArray(value)) return value.slice();
  return value;
}

function markReservationMutation(id, reservation, fields) {
  const key = getReservationWriteKey(id);
  const expected = {};
  const signatures = {};
  fields.forEach(field => {
    expected[field] = cloneReservationField(reservation, field);
    signatures[field] = reservationFieldSignature(reservation, field);
  });
  pendingReservationMutations.set(key, {
    fields: fields.slice(),
    expected,
    signatures,
    deadline: Date.now() + PENDING_MUTATION_GRACE_MS
  });
  pendingReservationWriteIds.add(key);
}

function clearReservationMutation(id) {
  const key = getReservationWriteKey(id);
  pendingReservationMutations.delete(key);
  pendingReservationWriteIds.delete(key);
}

function reservationMatchesMutation(reservation, entry) {
  return entry.fields.every(field => reservationFieldSignature(reservation, field) === entry.signatures[field]);
}

function applyExpectedMutationFields(serverReservation, entry) {
  const merged = { ...serverReservation };
  entry.fields.forEach(field => {
    merged[field] = Array.isArray(entry.expected[field]) ? entry.expected[field].slice() : entry.expected[field];
  });
  return merged;
}

function isReservationMutationInFlight(id, field, signature) {
  const fields = reservationInFlightMutations.get(getReservationWriteKey(id));
  return !!fields && fields.get(field) === signature;
}

function setReservationMutationInFlight(id, field, signature) {
  const key = getReservationWriteKey(id);
  let fields = reservationInFlightMutations.get(key);
  if (!fields) {
    fields = new Map();
    reservationInFlightMutations.set(key, fields);
  }
  fields.set(field, signature);
}

function clearReservationMutationInFlight(id, field) {
  const key = getReservationWriteKey(id);
  const fields = reservationInFlightMutations.get(key);
  if (!fields) return;
  fields.delete(field);
  if (!fields.size) reservationInFlightMutations.delete(key);
}

// Compat : anciennes API basées sur un simple Set d'ids. Le registre riche
// ci-dessus reste la source de vérité pour la fusion de snapshot.
function markReservationWritePending(id) {
  pendingReservationWriteIds.add(getReservationWriteKey(id));
}

function clearReservationWritePending(id) {
  clearReservationMutation(id);
}

function isReservationWritePending(id) {
  return pendingReservationWriteIds.has(getReservationWriteKey(id));
}

function scrollLaserDragBy(deltaY) {
  const activeWrap = bowlingPointerDrag
    ? document.getElementById('planningGridWrap')
    : laserPointerDrag
      ? document.getElementById('laserPlanningGridWrap')
      : null;
  // L'auto-scroll de bord ne pilote QUE la grille quand elle défile en interne
  // (mode plein écran comptoir : le wrap a une hauteur bornée + overflow:auto).
  // En mode normal, le défilement vertical du planning EST celui de la PAGE :
  // y retomber (ancien comportement) happait toute la page vers le haut dès que
  // le curseur passait dans la zone de bord pendant un glisser : « ça me remet
  // tout en haut ». On ne touche donc jamais au scroll de page pendant le drag :
  // la vue reste là où Movsar l'a laissée. (Cf. journal 2026-07-12.)
  if (activeWrap && activeWrap.scrollHeight > activeWrap.clientHeight) {
    activeWrap.scrollTop += deltaY;
    return;
  }
  // Le Laser en plein écran ne défile pas dans le wrap (overflow hidden) mais
  // dans sa timeline : c'est elle qui suit le doigt ou la souris au bord. Sur
  // téléphone, la file est au-dessus et la timeline dessous ; sans ça, une
  // partie ne pouvait se poser que sur les tranches déjà visibles.
  const agenda = laserPointerDrag && activeWrap ? activeWrap.querySelector('.laser-agenda') : null;
  if (agenda && agenda.scrollHeight > agenda.clientHeight) agenda.scrollTop += deltaY;
}

function stopLaserDragAutoScroll() {
  if (laserDragScrollRaf) cancelAnimationFrame(laserDragScrollRaf);
  laserDragScrollRaf = null;
}

function runLaserDragAutoScroll() {
  if (!laserDragActive) {
    stopLaserDragAutoScroll();
    return;
  }
  const edge = 96;
  const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
  let delta = 0;
  if (laserDragLastY > 0 && laserDragLastY < edge) {
    delta = -Math.ceil(((edge - laserDragLastY) / edge) * 24);
  } else if (viewportHeight && laserDragLastY > viewportHeight - edge) {
    delta = Math.ceil(((laserDragLastY - (viewportHeight - edge)) / edge) * 24);
  }
  // Au-dessus de la file « Parties à placer », le geste vise la file (retirer
  // la partie du planning) : la timeline voisine ne défile pas sous le bord.
  // Sur tablette en plein écran, la file longe tout le bas de l écran, et y
  // déposer une partie faisait filer la timeline jusqu au soir.
  if (delta && !laserUnplaceDropTarget) scrollLaserDragBy(delta);
  laserDragScrollRaf = requestAnimationFrame(runLaserDragAutoScroll);
}

function startLaserDragAutoScroll(clientY) {
  laserDragLastY = clientY || laserDragLastY;
  if (!laserDragScrollRaf) laserDragScrollRaf = requestAnimationFrame(runLaserDragAutoScroll);
}

function getLaserDropTargetFromPoint(clientX, clientY) {
  const element = document.elementFromPoint(clientX, clientY);
  const row = element?.closest?.('.laser-agenda-row[data-laser-time-start]');
  if (row && !getPlanningWindow(state.currentDate).closed) {
    row.dataset.laserDropStart = laserTimeFromPoint(row, clientY);
    delete row.dataset.laserDropEnd;
    return row;
  }
  return null;
}

// La colonne « Parties à placer » devient une cible de dépôt : glisser une carte
// déjà placée dessus dé-planifie la partie (elle repart dans la file « à placer »).
function getLaserUnplaceDropFromPoint(clientX, clientY) {
  const element = document.elementFromPoint(clientX, clientY);
  return element?.closest?.('.laser-pass-queue') || null;
}

function setLaserDragDropTarget(target) {
  if (laserDragDropTarget && laserDragDropTarget !== target) {
    laserDragDropTarget.classList.remove('is-drop-target');
  }
  laserDragDropTarget = target;
  if (laserDragDropTarget) laserDragDropTarget.classList.add('is-drop-target');
}

function clearLaserDragDropTarget() {
  if (laserDragDropTarget) laserDragDropTarget.classList.remove('is-drop-target');
  laserDragDropTarget = null;
}

function setLaserUnplaceDropTarget(target) {
  if (laserUnplaceDropTarget && laserUnplaceDropTarget !== target) {
    laserUnplaceDropTarget.classList.remove('is-unplace-target');
  }
  laserUnplaceDropTarget = target;
  if (laserUnplaceDropTarget) laserUnplaceDropTarget.classList.add('is-unplace-target');
}

function clearLaserUnplaceDropTarget() {
  if (laserUnplaceDropTarget) laserUnplaceDropTarget.classList.remove('is-unplace-target');
  laserUnplaceDropTarget = null;
}

function onLaserDocumentDragOver(event) {
  if (!laserDragActive) return;
  startLaserDragAutoScroll(event.clientY);
}

function onLaserDragWheel(event) {
  if (!laserDragActive) return;
  event.preventDefault();
  scrollLaserDragBy(event.deltaY);
}

// OU POSER LE FANTOME. A la souris, en bas a droite du curseur, comme toujours.
// Au doigt, AU-DESSUS et centre : en bas a droite, le doigt et la main le
// cachent, et on deposerait a l aveugle (voir startLaserPassTouchDrag).
function dragGhostTransform(drag, clientX, clientY) {
  if (drag && drag.touch) {
    const top = Math.max(4, clientY - (drag.ghostH || 0) - 20);
    return `translate3d(${clientX - (drag.ghostW || 0) / 2}px, ${top}px, 0)`;
  }
  return `translate3d(${clientX + 14}px, ${clientY + 14}px, 0)`;
}

function measureDragGhost(drag, ghost) {
  if (!drag || !ghost) return;
  drag.ghostW = ghost.offsetWidth;
  drag.ghostH = ghost.offsetHeight;
}

function createLaserDragGhost(sourceEl, event) {
  const rect = sourceEl.getBoundingClientRect();
  const ghost = sourceEl.cloneNode(true);
  ghost.classList.add('laser-drag-ghost');
  ghost.style.width = `${rect.width}px`;
  ghost.style.left = '0px';
  ghost.style.top = '0px';
  document.body.appendChild(ghost);
  measureDragGhost(laserPointerDrag, ghost);
  ghost.style.transform = dragGhostTransform(laserPointerDrag, event.clientX, event.clientY);
  return ghost;
}

function updateLaserPointerGhost(event) {
  if (!laserPointerDrag?.ghost) return;
  laserPointerDrag.ghost.style.transform = dragGhostTransform(laserPointerDrag, event.clientX, event.clientY);
}

function startLaserPointerDragMode(event) {
  if (!laserPointerDrag || laserPointerDrag.dragging) return;
  laserPointerDrag.dragging = true;
  laserPointerDrag.sourceEl.classList.add('is-dragging');
  laserPointerDrag.ghost = createLaserDragGhost(laserPointerDrag.sourceEl, event);
  laserDragActive = true;
  laserDragLastY = event.clientY || 0;
  document.body.classList.add('laser-dragging');
  document.addEventListener('wheel', onLaserDragWheel, { passive: false });
  startLaserDragAutoScroll(laserDragLastY);
}

function onLaserPointerMove(event) {
  if (!laserPointerDrag) return;
  const distance = Math.hypot(event.clientX - laserPointerDrag.startX, event.clientY - laserPointerDrag.startY);
  if(distance>=5) clearTimeout(laserPointerDrag.holdTimer);
  if (!laserPointerDrag.dragging && distance >= 5) startLaserPointerDragMode(event);
  if (!laserPointerDrag.dragging) return;
  event.preventDefault();
  event.stopPropagation();
  laserPointerDrag.lastX = event.clientX;
  laserPointerDrag.lastY = event.clientY;
  updateLaserPointerGhost(event);
  startLaserDragAutoScroll(event.clientY);
  const slotTarget = getLaserDropTargetFromPoint(event.clientX, event.clientY);
  setLaserDragDropTarget(slotTarget);
  if(laserPointerDrag.ghost){
    let destination=laserPointerDrag.ghost.querySelector('.laser-drag-destination');
    if(!destination){destination=document.createElement('small');destination.className='laser-drag-destination';laserPointerDrag.ghost.appendChild(destination);}
    const row=slotTarget?.closest('.laser-agenda-row');
    destination.textContent=slotTarget?`Vers ${formatClockDisplay(row?laserTimeFromPoint(row,event.clientY):Number(slotTarget.dataset.laserDropStart))}`:'Choisissez un créneau';
  }
  // Sinon, survole-t-on la file « Parties à placer » ? (dépôt = dé-planifier)
  setLaserUnplaceDropTarget(slotTarget ? null : getLaserUnplaceDropFromPoint(event.clientX, event.clientY));
}

function endLaserPointerDragVisuals(drag) {
  laserDragActive = false;
  stopLaserDragAutoScroll();
  document.body.classList.remove('laser-dragging');
  document.removeEventListener('wheel', onLaserDragWheel);
  drag.sourceEl.classList.remove('is-dragging');
  if (drag.ghost) drag.ghost.remove();
}

// Un geste interrompu (second doigt, appel entrant) : la carte revient, rien
// n est depose.
function cancelLaserPointerDrag() {
  const drag = laserPointerDrag;
  laserPointerDrag = null;
  if(drag?.held)laserDragSuppressClickUntil=Date.now()+350;
  if (!drag || !drag.dragging) return;
  endLaserPointerDragVisuals(drag);
  clearLaserDragDropTarget();
  clearLaserUnplaceDropTarget();
}

function onLaserPointerUp(event) {
  if (!laserPointerDrag) return;
  const drag = laserPointerDrag;
  clearTimeout(drag.holdTimer);
  const wasDragging = drag.dragging;
  laserPointerDrag = null;
  document.removeEventListener('mousemove', onLaserPointerMove, true);
  document.removeEventListener('mouseup', onLaserPointerUp, true);
  if (!wasDragging) {if(drag.held)bowlingDragSuppressClickUntil=laserDragSuppressClickUntil=Date.now()+350;return;}
  event.preventDefault();
  event.stopPropagation();
  laserDragSuppressClickUntil = Date.now() + 350;
  endLaserPointerDragVisuals(drag);
  const unplaceZone = getLaserUnplaceDropFromPoint(event.clientX, event.clientY);
  const target = getLaserDropTargetFromPoint(event.clientX, event.clientY) || laserDragDropTarget;
  clearLaserDragDropTarget();
  clearLaserUnplaceDropTarget();
  // Dépôt sur la file « Parties à placer » → on retire la partie du planning.
  if (unplaceZone) {
    const selection=planningMoveSelection;
    if(selection?.type==='laser'&&selection.reservationId===Number(drag.reservationId)&&selection.unitKey===drag.unitKey){selection.unplace=true;commitPlanningMoveSelection();return;}
    unscheduleLaserPass(drag.reservationId, drag.unitKey);
    return;
  }
  if (!target) {
    showPlanningMoveNotice('Aucun lancement choisi', 'Déposez la carte sur une ligne Laser Game disponible, ou sur « Parties à placer » pour la retirer du planning.', 'warning');
    return;
  }
  const row=target.closest('.laser-agenda-row');
  const targetStart=row?laserTimeFromPoint(row,event.clientY):Number(target.dataset.laserDropStart);
  const s=planningMoveSelection;
  if(s?.type==='laser'&&s.reservationId===Number(drag.reservationId)&&s.unitKey===drag.unitKey){s.targetStart=targetStart;commitPlanningMoveSelection();}
  else scheduleLaserPass(drag.reservationId, drag.unitKey, targetStart);
}

function createLaserPointerDrag(sourceEl, reservationId, unitKey, point, touch) {
  return {
    reservationId,
    unitKey,
    sourceEl,
    touch: Boolean(touch),
    startX: point.clientX,
    startY: point.clientY,
    lastX: point.clientX,
    lastY: point.clientY,
    dragging: false,
    ghost: null
  };
}

function startLaserPassPointerDrag(event, reservationId, unitKey) {
  if(planningMoveSelection?.saving)return;
  if(planningMoveSelection&&(planningMoveSelection.type!=='laser'||planningMoveSelection.reservationId!==Number(reservationId)||planningMoveSelection.unitKey!==unitKey))cancelPlanningMove(false);
  if (event.button !== 0) return;
  event.stopPropagation();
  laserPointerDrag = createLaserPointerDrag(event.currentTarget, reservationId, unitKey, event, false);
  const drag = laserPointerDrag;
  drag.holdTimer = setTimeout(() => {
    if(laserPointerDrag!==drag||drag.dragging||!drag.sourceEl.isConnected)return;
    if(!planningMoveSelection)selectPlanningMove('laser',reservationId,null,null,unitKey);
    drag.held=true;
  },PLANNING_MOVE_HOLD_MS);
  document.addEventListener('mousemove', onLaserPointerMove, true);
  document.addEventListener('mouseup', onLaserPointerUp, true);
}

// AU DOIGT (2026-09-11) : un appui long leve la carte, le doigt la deplace, le
// relacher la depose (assets/pinlane-touch-drag.js). La suite passe par les
// memes fonctions que la souris : fantome, cible, defilement du bord, depot.
function startLaserPassTouchDrag(event, reservationId, unitKey) {
  if(planningMoveSelection?.saving)return;
  if(planningMoveSelection&&(planningMoveSelection.type!=='laser'||planningMoveSelection.reservationId!==Number(reservationId)||planningMoveSelection.unitKey!==unitKey))cancelPlanningMove(false);
  if (!window.PinlaneTouchDrag) return;
  const sourceEl = event.currentTarget;
  window.PinlaneTouchDrag.demarrer(event, {
    lever(point) {
      laserPointerDrag = createLaserPointerDrag(sourceEl, reservationId, unitKey, point, true);
      startLaserPointerDragMode(point);
    },
    bouger: onLaserPointerMove,
    deposer: onLaserPointerUp,
    maintienLong() {if(!planningMoveSelection)selectPlanningMove('laser',reservationId,null,null,unitKey);if(laserPointerDrag)laserPointerDrag.held=true;},
    annuler(etaitLeve) { if (etaitLeve) cancelLaserPointerDrag(); }
  }, { maintienMs: planningMoveSelection ? 80 : 280, maintienLongMs: PLANNING_MOVE_HOLD_MS - 280 });
}

// LES GESTIONNAIRES TACTILES D UNE CARTE DU PLANNING. Poses sur la carte
// elle-meme : un geste tactile lui reste adresse meme si le planning se
// redessine pendant le glisser.
function onPlanningTouchMove(event) { if (window.PinlaneTouchDrag) window.PinlaneTouchDrag.bouger(event); }
function onPlanningTouchEnd(event) { if (window.PinlaneTouchDrag) window.PinlaneTouchDrag.finir(event); }
function onPlanningTouchCancel(event) { if (window.PinlaneTouchDrag) window.PinlaneTouchDrag.interrompre(event); }
function onPlanningTouchMenu(event) { if (window.PinlaneTouchDrag) window.PinlaneTouchDrag.menu(event); }

function planningTouchAttrs(startCall) {
  return `ontouchstart="${startCall}" ontouchmove="onPlanningTouchMove(event)" ontouchend="onPlanningTouchEnd(event)" ontouchcancel="onPlanningTouchCancel(event)" oncontextmenu="onPlanningTouchMenu(event)"`;
}

function shouldIgnoreLaserPassClick(event) {
  if(planningMoveSelection){event.preventDefault();event.stopPropagation();return true;}
  if (Date.now() > laserDragSuppressClickUntil) return false;
  event.preventDefault();
  event.stopPropagation();
  return true;
}

function getBowlingBlockMinutes(block, key) {
  const raw = Number(block?.[key]);
  if (Number.isFinite(raw)) return raw;
  const timeKey = key === 'start' ? 'startTime' : 'endTime';
  return hourToMinuteInt(timeToNum(block?.[timeKey] || '00:00'));
}

function getBowlingDropTargetFromPoint(clientX, clientY) {
  const laneCols = [...document.querySelectorAll('#planningGridWrap .lane-col')];
  for (const laneCol of laneCols) {
    const laneRect = laneCol.getBoundingClientRect();
    if (clientX < laneRect.left || clientX > laneRect.right) continue;
    const cells = [...laneCol.querySelectorAll('.slot-cell.clickable[data-bowling-drop-lane]')];
    const cell = cells.find(item => {
      const rect = item.getBoundingClientRect();
      return clientY >= rect.top && clientY <= rect.bottom;
    });
    if (cell) return cell;
  }
  return null;
}

function setBowlingDragDropTarget(target) {
  if (bowlingDragDropTarget && bowlingDragDropTarget !== target) {
    bowlingDragDropTarget.classList.remove('is-drop-target');
    bowlingDragDropTarget.classList.remove('invalid');
  }
  bowlingDragDropTarget = target;
  if (bowlingDragDropTarget) bowlingDragDropTarget.classList.add('is-drop-target');
  renderBowlingDragPreview(target);
}

function clearBowlingDragDropTarget() {
  if (bowlingDragDropTarget) {
    bowlingDragDropTarget.classList.remove('is-drop-target');
    bowlingDragDropTarget.classList.remove('invalid');
  }
  bowlingDragDropTarget = null;
  clearBowlingDragPreview();
}

function clearBowlingDragPreview() {
  bowlingDragPreviewEls.forEach(el => el.remove());
  bowlingDragPreviewEls = [];
}

function getBowlingDragSourceWindow(reservation, sourceLaneValue, sourceStartValue) {
  const sourceLane = Number(sourceLaneValue);
  const sourceStart = Number(sourceStartValue);
  const windows = getBowlingWindowsFromReservation(reservation);
  return windows.find(window =>
    window.lanes.includes(sourceLane) &&
    (!Number.isFinite(sourceStart) || Math.abs(Number(window.start) - sourceStart) < 0.01)
  ) || windows.find(window => window.lanes.includes(sourceLane)) || windows[0] || null;
}

function getBowlingDragTargetPlan(target) {
  if (!target || !bowlingPointerDrag) return null;
  const reservation = state.reservations.find(item => Number(item.id) === Number(bowlingPointerDrag.reservationId));
  if (!reservation) return null;
  const targetLane = Number(target.dataset.bowlingDropLane);
  const targetStart = Number(target.dataset.bowlingDropStart);
  const duration = getBowlingDurationForReservation(reservation) || Number(reservation.duration || 1);
  const startTime = numToTime(targetStart);
  const sourceWindow = getBowlingDragSourceWindow(reservation, bowlingPointerDrag.sourceLane, bowlingPointerDrag.sourceStart);
  const selection=planningMoveSelection;
  if(selection?.type==='bowling'&&selection.reservationId===Number(reservation.id)) {
    const selected=selection.sourceLanes;
    const windows=getBowlingWindowsFromReservation(reservation);
    const laneOffset=targetLane-Number(bowlingPointerDrag.sourceLane);
    const timeOffset=targetStart-Number(sourceWindow?.start??targetStart);
    const lanes=selected.map(lane=>lane+laneOffset);
    const moved=windows.flatMap(window=> {
      const kept=window.lanes.filter(lane=>!selected.includes(Number(lane)));
      const movedLanes=window.lanes.filter(lane=>selected.includes(Number(lane))).map(lane=>Number(lane)+laneOffset);
      return [...(kept.length?[{...window,lanes:kept}]:[]),...(movedLanes.length?[{...window,start:window.start+timeOffset,end:window.end+timeOffset,lanes:movedLanes,selectedMove:true}]:[])];
    });
    let message='';
    if(!selected.length||lanes.some(lane=>lane<1||lane>getAvailabilityLaneCount()||state.laneStatuses[lane]==='maintenance'))message='Pistes indisponibles';
    for(const window of moved) {
      const check=validateSlotWindow(reservation.date,numToTime(window.start),window.duration,{allowPastStart:true});
      if(!check.ok){message=check.message;break;}
      const occupied=getOccupiedLanes(reservation.date,numToTime(window.start),window.duration,reservation.id);
      if(window.lanes.some(lane=>occupied.has(lane))){message='Conflit avec une réservation';break;}
    }
    if(moved.some((window,index)=>moved.slice(index+1).some(other=>window.lanes.some(lane=>other.lanes.includes(lane))&&overlap(window.start,window.duration,other.start,other.duration))))message='Une piste à laisser en place occupe ce créneau';
    return {reservation,targetLane,targetStart,duration,lanes,valid:!message,message:message||`Pistes ${lanes.join(', ')}`,previewWindows:moved.filter(window=>window.selectedMove)};
  }
  const currentLanes = [...new Set(getBowlingWindowsFromReservation(reservation).flatMap(window => window.lanes || []))].map(Number).sort((a,b) => a-b);
  const requiredCount = Math.max(currentLanes.length, getBowlingCapacityPlan(Number(sourceWindow && sourceWindow.players) || getReservationActivityPlayers(reservation, 'bowling'), getFreeCount(reservation.date, startTime, duration, reservation.id), duration * 60).requiredCount);
  const slotCheck = validateSlotWindow(reservation.date, startTime, duration, { allowPastStart: true });
  if (!slotCheck.ok) {
    return { reservation, targetLane, targetStart, duration, lanes: [targetLane], valid: false, message: slotCheck.message };
  }
  const lanes = getTargetBowlingLanes(
    requiredCount,
    targetLane,
    reservation.date,
    startTime,
    duration,
    reservation.id,
    currentLanes,
    bowlingPointerDrag.sourceLane,
    Boolean(bowlingPointerDrag.splitLane)
  );
  if (!lanes || lanes.length < requiredCount) {
    return { reservation, targetLane, targetStart, duration, lanes: [targetLane], valid: false, message: `${requiredCount} piste${requiredCount > 1 ? 's' : ''} indisponible${requiredCount > 1 ? 's' : ''}` };
  }
  const firstStart = Math.min(...getBowlingWindowsFromReservation(reservation).map(window => Number(window.start)));
  const groupStart = Number(targetStart) - (Number(sourceWindow?.start ?? firstStart) - firstStart);
  const movedOpsPlan = moveBowlingOpsPlan(reservation, groupStart, lanes, duration);
  const conflicts = lanesConflict(reservation.date, startTime, duration, lanes, reservation.id, movedOpsPlan);
  return {
    reservation,
    targetLane,
    targetStart,
    duration,
    lanes,
    valid: conflicts.length === 0,
    message: conflicts.length ? 'Conflit avec une réservation' : `Pistes ${lanes.join(', ')}`
  };
}

function renderBowlingDragPreview(target) {
  clearBowlingDragPreview();
  if (!target) return;
  const plan = getBowlingDragTargetPlan(target);
  if (!plan) return;
  target.classList.toggle('invalid', !plan.valid);
  const config = getPlanningWindow(plan.reservation.date);
  if (!config || config.closed) return;
  const planningBox = document.getElementById('planningBox');
  const computed = planningBox ? getComputedStyle(planningBox) : null;
  const hourHeight = parseFloat(computed?.getPropertyValue('--planning-hour-h')) || 48;
  const headerHeight = parseFloat(computed?.getPropertyValue('--planning-header-h')) || 46;
  const previews=plan.previewWindows||[{start:plan.targetStart,duration:plan.duration,lanes:plan.lanes?.length?plan.lanes:[plan.targetLane]}];
  previews.forEach(window=>window.lanes.forEach(lane => {
    const top = (window.start - config.open) * hourHeight + headerHeight + 3;
    const height = Math.max(28, (Number(window.duration) * hourHeight) - 6);
    const laneCol = document.querySelector(`#planningGridWrap .lane-col[data-lane="${Number(lane)}"]`);
    if (!laneCol) return;
    const preview = document.createElement('div');
    preview.className = `bowling-drop-preview${plan.valid ? '' : ' invalid'}`;
    preview.style.top = `${top}px`;
    preview.style.height = `${height}px`;
    preview.innerHTML = `
      <strong>${formatClockDisplay(window.start)}</strong>
      <span>${escapeHtml(plan.valid ? `Piste ${lane}` : plan.message)}</span>
    `;
    laneCol.appendChild(preview);
    bowlingDragPreviewEls.push(preview);
  }));
  if(bowlingPointerDrag?.ghost){
    let destination=bowlingPointerDrag.ghost.querySelector('.bowling-drag-destination');
    if(!destination){destination=document.createElement('small');destination.className='bowling-drag-destination';bowlingPointerDrag.ghost.appendChild(destination);}
    destination.textContent=plan.valid?`${formatClockDisplay(plan.targetStart)} · ${plan.lanes.length} piste${plan.lanes.length>1?'s':''}`:plan.message;
  }
}

function getTargetBowlingLanes(requiredCount, targetLane, date, startTime, duration, ignoreId, currentLanes = [], sourceLane = null, splitLane = false) {
  const occupied = getOccupiedLanes(date, startTime, duration, ignoreId);
  const laneCount = getAvailabilityLaneCount();
  const isAvailable = lane => lane >= 1 && lane <= laneCount && state.laneStatuses[lane] !== 'maintenance' && !occupied.has(lane);
  const target = Number(targetLane);
  const count = Math.max(1, Number(requiredCount || 1));
  if (count === 1) return isAvailable(target) ? [target] : null;

  const current = [...new Set((currentLanes || []).map(Number).filter(lane => lane >= 1 && lane <= laneCount))].sort((a, b) => a - b);
  const source = Number(sourceLane);
  if (current.length >= count && Number.isFinite(source) && current.includes(source)) {
    if (splitLane) {
      const replaced = current.map(lane => lane === source ? target : lane);
      const candidate = [...new Set(replaced)].sort((a, b) => a - b);
      if (candidate.length === count && candidate.every(isAvailable)) return candidate;
    } else {
      const preservedOffsets = current.slice(0, count).map(lane => lane - source);
      const candidate = [...new Set(preservedOffsets.map(offset => target + offset))].sort((a, b) => a - b);
      if (candidate.length === count && candidate.every(isAvailable)) return candidate;

      const sourceIndex = Math.max(0, current.slice(0, count).indexOf(source));
      const firstLane = Math.max(1, Math.min(laneCount - count + 1, target - sourceIndex));
      const compactCandidate = Array.from({ length: count }, (_, idx) => firstLane + idx);
      if (compactCandidate.includes(target) && compactCandidate.every(isAvailable)) return compactCandidate;
    }
  }

  const available = [];
  for (let lane = 1; lane <= laneCount; lane += 1) {
    if (isAvailable(lane)) available.push(lane);
  }
  if (available.length < count) return null;
  const byDistance = lane => Math.abs(lane - target);
  if (isAvailable(target)) {
    const others = available
      .filter(lane => lane !== target)
      .sort((left, right) => byDistance(left) - byDistance(right) || left - right);
    return [target, ...others.slice(0, count - 1)].sort((a, b) => a - b);
  }
  return available
    .sort((left, right) => byDistance(left) - byDistance(right) || left - right)
    .slice(0, count)
    .sort((a, b) => a - b);
}

function summarizePlanTimes(resourceBlocks = []) {
  const timed = resourceBlocks
    .map(block => ({
      block,
      start: getBowlingBlockMinutes(block, 'start'),
      end: getBowlingBlockMinutes(block, 'end')
    }))
    .filter(item => Number.isFinite(item.start) && Number.isFinite(item.end) && item.end > item.start);
  if (!timed.length) return {};
  const start = Math.min(...timed.map(item => item.start));
  const end = Math.max(...timed.map(item => item.end));
  const bowling = timed.find(item => item.block.resourceType === 'bowling_lane');
  const laser = timed.find(item => item.block.resourceType === 'laser_arena');
  return {
    startTime: minuteIntToTime(start),
    endTime: minuteIntToTime(end),
    totalMinutes: end - start,
    firstBowlingTime: bowling?.block?.startTime || (bowling ? minuteIntToTime(bowling.start) : ''),
    firstLaserTime: laser?.block?.startTime || (laser ? minuteIntToTime(laser.start) : '')
  };
}

function moveBowlingOpsPlan(reservation, targetStart, targetLanes, duration) {
  if (!Array.isArray(reservation.opsPlan?.resourceBlocks)) return reservation.opsPlan || null;
  const targetStartMinutes = hourToMinuteInt(targetStart);
  const bowlingBlocks = reservation.opsPlan.resourceBlocks.filter(block => block.resourceType === 'bowling_lane');
  if (!bowlingBlocks.length) return reservation.opsPlan;
  const firstStart = Math.min(...bowlingBlocks.map(block => getBowlingBlockMinutes(block, 'start')));
  const delta = targetStartMinutes - firstStart;
  const moveStep = step => {
    if (step.resourceType !== 'bowling_lane' && step.activityId !== 'bowling') return step;
    const start = getBowlingBlockMinutes(step, 'start') + delta;
    const oldStart = getBowlingBlockMinutes(step, 'start');
    const oldEnd = getBowlingBlockMinutes(step, 'end');
    const minutes = Math.max(1, oldEnd - oldStart || Math.round(Number(duration || reservation.duration || 1) * 60));
    const end = start + minutes;
    return {
      ...step,
      start,
      end,
      startTime: minuteIntToTime(start),
      endTime: minuteIntToTime(end),
      durationMinutes: minutes,
      lanes: step.resourceType === 'bowling_lane' ? targetLanes : step.lanes,
      ...(step.resourceType === 'bowling_lane' ? { bowlingCapacity: getBowlingCapacityPlan(Number(step.players) || getReservationActivityPlayers(reservation, 'bowling'), getFreeCount(reservation.date, minuteIntToTime(start), minutes / 60, reservation.id), minutes).bowlingCapacity } : {}),
    };
  };
  const timeline = Array.isArray(reservation.opsPlan.timeline) ? reservation.opsPlan.timeline.map(moveStep) : reservation.opsPlan.timeline;
  const resourceBlocks = reservation.opsPlan.resourceBlocks.map(moveStep);
  const planTimes = summarizePlanTimes(resourceBlocks);
  return {
    ...reservation.opsPlan,
    ...planTimes,
    assignedLanes: targetLanes,
    timeline,
    resourceBlocks,
  };
}

async function scheduleBowlingDrag(reservationId, targetLane, targetStart, sourceLaneValue = null, sourceStartValue = null, splitLane = false) {
  const reservation = state.reservations.find(item => Number(item.id) === Number(reservationId));
  if (!reservation) return;
  const s=planningMoveSelection;
  if(s?.type==='bowling'&&s.reservationId===Number(reservationId)) {
    if(s.saving||!s.sourceLanes.includes(Number(sourceLaneValue)))return false;
    const windows=getBowlingWindowsFromReservation(reservation);
    const first=Math.min(...windows.filter(w=>w.lanes.some(l=>s.sourceLanes.includes(Number(l)))).map(w=>Number(w.start)));
    const source=getBowlingDragSourceWindow(reservation,sourceLaneValue,sourceStartValue);
    s.targetStart=Number(targetStart)-(Number(source?.start??first)-first);
    s.targetLane=Number(targetLane);
    s.laneMapping=Object.fromEntries(s.sourceLanes.map(l=>[l,l+Number(targetLane)-Number(sourceLaneValue)]));
    if(Math.abs(s.targetStart-first)<.001&&s.sourceLanes.every(l=>s.laneMapping[l]===l))return false;
    return commitPlanningMoveSelection();
  }
  // The modifier gesture and explicit selection share the same subset contract.
  // Moving one lane must never shift the other lanes' service times.
  if(splitLane && Number.isInteger(Number(sourceLaneValue)) && Number(sourceLaneValue)>0) {
    const windows=getBowlingWindowsFromReservation(reservation),source=getBowlingDragSourceWindow(reservation,sourceLaneValue,sourceStartValue);
    const first=Math.min(...windows.filter(w=>w.lanes.includes(Number(sourceLaneValue))).map(w=>Number(w.start)));
    return scheduleBowlingSelection({ reservationId:Number(reservationId), sourceLanes:[Number(sourceLaneValue)], targetLane:Number(targetLane), targetStart:Number(targetStart)-(Number(source?.start??first)-first) });
  }
  const duration = getBowlingDurationForReservation(reservation) || Number(reservation.duration || 1);
  const startTime = numToTime(Number(targetStart));
  const sourceLane = Number(sourceLaneValue);
  const sourceWindow = getBowlingDragSourceWindow(reservation, sourceLaneValue, sourceStartValue);
  const currentLanes = [...new Set(getBowlingWindowsFromReservation(reservation).flatMap(window => window.lanes || []))].map(Number).sort((a,b) => a-b);
  const requiredCount = Math.max(currentLanes.length, getBowlingCapacityPlan(Number(sourceWindow && sourceWindow.players) || getReservationActivityPlayers(reservation, 'bowling'), getFreeCount(reservation.date, startTime, duration, reservation.id), duration * 60).requiredCount);
  const slotCheck = validateSlotWindow(reservation.date, startTime, duration, { allowPastStart: true });
  if (!slotCheck.ok) {
    showPlanningMoveNotice('Déplacement impossible', slotCheck.message || 'Ce créneau ne peut pas être utilisé.', 'warning');
    return;
  }
  const lanes = getTargetBowlingLanes(requiredCount, targetLane, reservation.date, startTime, duration, reservation.id, currentLanes, sourceLane, splitLane);
  if (!lanes || lanes.length < requiredCount) {
    showPlanningMoveNotice(
      'Conflit de pistes',
      `Il faut ${requiredCount} piste${requiredCount > 1 ? 's' : ''} libre${requiredCount > 1 ? 's' : ''} sur ce créneau.`,
      'warning'
    );
    return;
  }
  const bowlingBlocks = (reservation.opsPlan?.resourceBlocks || []).filter(block => block.resourceType === 'bowling_lane');
  const firstStart = bowlingBlocks.length ? Math.min(...bowlingBlocks.map(block => getBowlingBlockMinutes(block, 'start'))) / 60 : timeToNum(reservation.startTime);
  const sourceStart = sourceWindow ? Number(sourceWindow.start) : firstStart;
  const groupStart = Number(targetStart) - (sourceStart - firstStart);
  const movedOpsPlan = moveBowlingOpsPlan(reservation, groupStart, lanes, duration);
  if (lanesConflict(reservation.date, numToTime(groupStart), duration, lanes, reservation.id, movedOpsPlan).length) {
    showPlanningMoveNotice('Conflit détecté', 'Une autre réservation occupe déjà une piste ou un horaire de bowling.', 'warning');
    return;
  }
  const requestKey = Number(reservation.id);
  const requestSeq = ++bowlingDragSaveSeq;
  bowlingDragLatestSeqByReservation[requestKey] = requestSeq;
  const isLatestRequest = () => bowlingDragLatestSeqByReservation[requestKey] === requestSeq;
  try {
    const laneMapping = splitLane ? Object.fromEntries(currentLanes.map(lane => [lane, lane === sourceLane ? Number(targetLane) : lane])) : null;
    if (laneMapping && valeurReservationComparable(Object.values(laneMapping).sort((a,b) => a-b)) !== valeurReservationComparable([...lanes].sort((a,b) => a-b))) {
      showPlanningMoveNotice('Piste non déplacée', 'Cette piste ne peut pas être déplacée seule ici. Choisissez une piste libre ou déplacez le groupe entier.', 'warning');
      return;
    }
    const payload = await envoyerDeplacementActivite(reservation, { activityId: 'bowling', startTime: numToTime(groupStart), lanes, ...(laneMapping ? { laneMapping } : {}) });
    if (!isLatestRequest()) return;
    const savedBlocks = (payload.reservation.opsPlan?.resourceBlocks || []).filter(block => block.resourceType === 'bowling_lane');
    const savedStart = savedBlocks.length ? Math.min(...savedBlocks.map(block => getBowlingBlockMinutes(block, 'start'))) : NaN;
    const savedLanes = [...new Set(savedBlocks.flatMap(block => block.lanes || []))].map(Number).sort((a,b) => a-b);
    if (Math.abs(savedStart - hourToMinuteInt(groupStart)) > 1 || !Number.isFinite(savedStart)
      || valeurReservationComparable(savedLanes) !== valeurReservationComparable([...lanes].sort((a,b) => a-b))) {
      throw new Error('Le placement de bowling sauvegardé ne correspond pas au déplacement. Actualisez le planning.');
    }
    upsertReservationInState(payload.reservation);
    markReservationMutation(requestKey, payload.reservation, ['lanes', 'opsPlan']);
    save();
    renderStaffData();
    toast(`Bowling déplacé à ${formatClockDisplay(Number(targetStart))} piste${lanes.length > 1 ? 's' : ''} ${lanes.join(', ')}`);
  } catch (error) {
    if (!isLatestRequest()) return;
    if (error.reservation) upsertReservationInState(error.reservation);
    clearReservationMutation(requestKey);
    renderStaffData();
    showPlanningMoveNotice('Bowling non déplacé', error.message || 'Le serveur a refusé ce placement. Les autres activités restent à leur horaire.', 'warning');
  } finally {
    if (isLatestRequest()) delete bowlingDragLatestSeqByReservation[requestKey];
  }
}

function setBowlingSourceDragging(reservationId, active) {
  document.querySelectorAll(`.booking[data-booking-res-id="${Number(reservationId)}"]`).forEach(el => {
    const selected=planningMoveSelection?.type==='bowling'&&planningMoveSelection.reservationId===Number(reservationId)?planningMoveSelection.sourceLanes.includes(Number(el.dataset.bookingLane)):true;
    el.classList.toggle('is-dragging', active&&selected);
  });
}

function createBowlingDragGhost(sourceEl, event) {
  const reservation = state.reservations.find(item => Number(item.id) === Number(bowlingPointerDrag?.reservationId));
  const rect = sourceEl.getBoundingClientRect();
  const ghost = document.createElement('div');
  ghost.className = `bowling-drag-ghost-card ${reservation ? getReservationHighlightClasses(reservation) : ''}`;
  ghost.style.width = `${Math.max(220, Math.min(360, rect.width))}px`;
  const label = 'Bowling';
  const selected=planningMoveSelection?.type==='bowling'&&planningMoveSelection.reservationId===Number(reservation?.id)?planningMoveSelection.sourceLanes:null;
  const lanes = (selected||reservation?.lanes)?.length ? `Pistes ${(selected||reservation.lanes).join(', ')}` : 'Affectation libre';
  const sourceWindow = reservation ? getBowlingDragSourceWindow(reservation, bowlingPointerDrag?.sourceLane, bowlingPointerDrag?.sourceStart) : null;
  const isMultiLane = (sourceWindow?.lanes?.length || reservation?.lanes?.length || 0) > 1;
  const dragMode = selected ? lanes : isMultiLane ? (bowlingPointerDrag?.splitLane ? 'Piste seule' : 'Groupe de pistes') : lanes;
  // Sans clavier, la piste seule s obtient en restant immobile une fois la
  // carte levee (setBowlingTouchSplitLane) : le fantome le dit au doigt.
  const hint = selected || !isMultiLane ? ''
    : !bowlingPointerDrag?.touch ? 'Shift/Ctrl : piste seule'
      : bowlingPointerDrag.splitLane ? '' : 'Maintenez 1 s pour sélectionner les pistes';
  ghost.innerHTML = `
    <strong>${escapeHtml(reservation?.name || 'Réservation')}</strong>
    <span>${escapeHtml(label)}</span>
    <small class="bowling-drag-mode">${escapeHtml(dragMode)}</small>
    ${hint ? `<small class="bowling-drag-hint">${escapeHtml(hint)}</small>` : ''}
  `;
  document.body.appendChild(ghost);
  measureDragGhost(bowlingPointerDrag, ghost);
  ghost.style.transform = dragGhostTransform(bowlingPointerDrag, event.clientX, event.clientY);
  return ghost;
}

function updateBowlingPointerGhost(event) {
  if (!bowlingPointerDrag?.ghost) return;
  bowlingPointerDrag.ghost.style.transform = dragGhostTransform(bowlingPointerDrag, event.clientX, event.clientY);
}

function startBowlingPointerDragMode(event) {
  if (!bowlingPointerDrag || bowlingPointerDrag.dragging) return;
  bowlingPointerDrag.dragging = true;
  setBowlingSourceDragging(bowlingPointerDrag.reservationId, true);
  bowlingPointerDrag.ghost = createBowlingDragGhost(bowlingPointerDrag.sourceEl, event);
  laserDragActive = true;
  laserDragLastY = event.clientY || 0;
  document.body.classList.add('bowling-dragging');
  document.addEventListener('wheel', onLaserDragWheel, { passive: false });
  startLaserDragAutoScroll(laserDragLastY);
}

function onBowlingPointerMove(event) {
  if (!bowlingPointerDrag) return;
  const distance = Math.hypot(event.clientX - bowlingPointerDrag.startX, event.clientY - bowlingPointerDrag.startY);
  if(distance>=5)clearTimeout(bowlingPointerDrag.holdTimer);
  if (!bowlingPointerDrag.dragging && distance >= 5) startBowlingPointerDragMode(event);
  if (!bowlingPointerDrag.dragging) return;
  event.preventDefault();
  event.stopPropagation();
  bowlingPointerDrag.lastX = event.clientX;
  bowlingPointerDrag.lastY = event.clientY;
  updateBowlingPointerGhost(event);
  startLaserDragAutoScroll(event.clientY);
  setBowlingDragDropTarget(getBowlingDropTargetFromPoint(event.clientX, event.clientY));
}

function endBowlingPointerDragVisuals(drag) {
  laserDragActive = false;
  stopLaserDragAutoScroll();
  document.body.classList.remove('bowling-dragging');
  document.removeEventListener('wheel', onLaserDragWheel);
  setBowlingSourceDragging(drag.reservationId, false);
  if (drag.ghost) drag.ghost.remove();
}

// Un geste interrompu : la carte revient, rien n est depose.
function cancelBowlingPointerDrag() {
  const drag = bowlingPointerDrag;
  bowlingPointerDrag = null;
  if(drag?.held)bowlingDragSuppressClickUntil=Date.now()+350;
  if (!drag || !drag.dragging) return;
  endBowlingPointerDragVisuals(drag);
  clearBowlingDragDropTarget();
}

function onBowlingPointerUp(event) {
  if (!bowlingPointerDrag) return;
  const drag = bowlingPointerDrag;
  clearTimeout(drag.holdTimer);
  const wasDragging = drag.dragging;
  const candidateTarget=wasDragging?getBowlingDropTargetFromPoint(event.clientX,event.clientY)||bowlingDragDropTarget:null;
  const candidatePlan=candidateTarget?getBowlingDragTargetPlan(candidateTarget):null;
  bowlingPointerDrag = null;
  document.removeEventListener('mousemove', onBowlingPointerMove, true);
  document.removeEventListener('mouseup', onBowlingPointerUp, true);
  if (!wasDragging) {if(drag.held)bowlingDragSuppressClickUntil=laserDragSuppressClickUntil=Date.now()+350;return;}
  event.preventDefault();
  event.stopPropagation();
  bowlingDragSuppressClickUntil = Date.now() + 350;
  endBowlingPointerDragVisuals(drag);
  const target = getBowlingDropTargetFromPoint(event.clientX, event.clientY) || bowlingDragDropTarget;
  clearBowlingDragDropTarget();
  if (!target) {
    showPlanningMoveNotice('Aucun créneau choisi', 'Déposez la carte sur une cellule piste/heure disponible.', 'warning');
    return;
  }
  if(planningMoveSelection?.type==='bowling'&&candidatePlan&&!candidatePlan.valid){showPlanningMoveNotice('Déplacement impossible',candidatePlan.message);return;}
  scheduleBowlingDrag(
    drag.reservationId,
    Number(target.dataset.bowlingDropLane),
    Number(target.dataset.bowlingDropStart),
    drag.sourceLane,
    drag.sourceStart,
    Boolean(drag.splitLane)
  );
}

function createBowlingPointerDrag(sourceEl, reservationId, sourceLane, sourceStart, point, splitLane, touch) {
  return {
    reservationId,
    sourceLane,
    sourceStart,
    splitLane: Boolean(splitLane),
    touch: Boolean(touch),
    sourceEl,
    startX: point.clientX,
    startY: point.clientY,
    lastX: point.clientX,
    lastY: point.clientY,
    dragging: false,
    ghost: null
  };
}

function startBowlingBookingPointerDrag(event, reservationId, sourceLane = null, sourceStart = null) {
  if(planningMoveSelection?.saving)return;
  if(planningMoveSelection&&(planningMoveSelection.type!=='bowling'||planningMoveSelection.reservationId!==Number(reservationId)))cancelPlanningMove(false);
  if(planningMoveSelection&&!planningMoveSelection.sourceLanes.includes(Number(sourceLane)))return;
  if (event.button !== 0) return;
  event.stopPropagation();
  bowlingPointerDrag = createBowlingPointerDrag(
    event.currentTarget, reservationId, sourceLane, sourceStart, event,
    event.shiftKey || event.altKey || event.ctrlKey || event.metaKey, false
  );
  const drag=bowlingPointerDrag;
  drag.holdTimer=setTimeout(()=>{
    if(bowlingPointerDrag!==drag||drag.dragging||!drag.sourceEl.isConnected)return;
    if(!planningMoveSelection)selectPlanningMove('bowling',reservationId,sourceLane,sourceStart);
    drag.held=true;
  },PLANNING_MOVE_HOLD_MS);
  document.addEventListener('mousemove', onBowlingPointerMove, true);
  document.addEventListener('mouseup', onBowlingPointerUp, true);
}

// LA PISTE SEULE, SANS CLAVIER. A la souris, Shift ou Ctrl au moment de
// saisir la carte deplace une seule piste d un groupe. Au doigt, il n y a pas
// de touche : la carte levee qui reste immobile BOWLING_TOUCH_SPLIT_MS de plus
// passe en piste seule, le fantome l annonce, et le glisser qui suit fait
// exactement ce que fait la souris avec Shift (meme calcul de pistes).
const BOWLING_TOUCH_SPLIT_MS = 900;

function isBowlingDragMultiLane(drag) {
  const reservation = drag && state.reservations.find(item => Number(item.id) === Number(drag.reservationId));
  if (!reservation) return false;
  const sourceWindow = getBowlingDragSourceWindow(reservation, drag.sourceLane, drag.sourceStart);
  return (sourceWindow?.lanes?.length || reservation.lanes?.length || 0) > 1;
}

function setBowlingTouchSplitLane(point) {
  const drag = bowlingPointerDrag;
  if (!drag || !drag.touch || drag.splitLane || !isBowlingDragMultiLane(drag)) return;
  drag.splitLane = true;
  const mode = drag.ghost && drag.ghost.querySelector('.bowling-drag-mode');
  if (mode) mode.textContent = 'Piste seule';
  const hint = drag.ghost && drag.ghost.querySelector('.bowling-drag-hint');
  if (hint) hint.remove();
  if (drag.ghost) {
    measureDragGhost(drag, drag.ghost);
    if (point) drag.ghost.style.transform = dragGhostTransform(drag, point.clientX, point.clientY);
  }
  if (bowlingDragDropTarget) setBowlingDragDropTarget(bowlingDragDropTarget);
}

// AU DOIGT : voir startLaserPassTouchDrag.
function startBowlingBookingTouchDrag(event, reservationId, sourceLane = null, sourceStart = null) {
  if(planningMoveSelection?.saving)return;
  if(planningMoveSelection&&(planningMoveSelection.type!=='bowling'||planningMoveSelection.reservationId!==Number(reservationId)))cancelPlanningMove(false);
  if(planningMoveSelection&&!planningMoveSelection.sourceLanes.includes(Number(sourceLane)))return;
  if (!window.PinlaneTouchDrag) return;
  const sourceEl = event.currentTarget;
  window.PinlaneTouchDrag.demarrer(event, {
    lever(point) {
      bowlingPointerDrag = createBowlingPointerDrag(sourceEl, reservationId, sourceLane, sourceStart, point, false, true);
      startBowlingPointerDragMode(point);
    },
    maintienLong() {if(!planningMoveSelection)selectPlanningMove('bowling',reservationId,sourceLane,sourceStart);if(bowlingPointerDrag)bowlingPointerDrag.held=true;},
    bouger: onBowlingPointerMove,
    deposer: onBowlingPointerUp,
    annuler(etaitLeve) { if (etaitLeve) cancelBowlingPointerDrag(); }
  }, { maintienMs: planningMoveSelection ? 80 : 280, maintienLongMs: PLANNING_MOVE_HOLD_MS - 280 });
}

function shouldIgnoreBowlingDragClick(event) {
  if(planningMoveSelection){event.preventDefault();event.stopPropagation();return true;}
  if (Date.now() > bowlingDragSuppressClickUntil) return false;
  event.preventDefault();
  event.stopPropagation();
  return true;
}

function onLaserPassDragStart(event, reservationId, unitKey) {
  event.stopPropagation();
  event.dataTransfer.setData('text/plain', JSON.stringify({ type: 'laser-pass', reservationId, unitKey }));
  event.dataTransfer.effectAllowed = 'move';
  laserDragActive = true;
  laserDragLastY = event.clientY || 0;
  document.body.classList.add('laser-dragging');
  event.currentTarget.classList.add('is-dragging');
  document.addEventListener('dragover', onLaserDocumentDragOver);
  document.addEventListener('wheel', onLaserDragWheel, { passive: false });
  startLaserDragAutoScroll(laserDragLastY);
}

function onLaserPassDragEnd(event) {
  laserDragActive = false;
  stopLaserDragAutoScroll();
  document.body.classList.remove('laser-dragging');
  event.currentTarget.classList.remove('is-dragging');
  clearLaserDragDropTarget();
  document.querySelectorAll('.laser-session-slot.is-drop-target').forEach(el => el.classList.remove('is-drop-target'));
  document.removeEventListener('dragover', onLaserDocumentDragOver);
  document.removeEventListener('wheel', onLaserDragWheel);
}

function onLaserPassDragOver(event) {
  event.preventDefault();
  event.dataTransfer.dropEffect = 'move';
  startLaserDragAutoScroll(event.clientY);
}

function onLaserPassDragEnter(event) {
  event.preventDefault();
  setLaserDragDropTarget(event.currentTarget);
}

function onLaserPassDragLeave(event) {
  if (laserDragDropTarget === event.currentTarget) clearLaserDragDropTarget();
}

function onLaserPassDrop(event, targetStart, targetEnd = null) {
  event.preventDefault();
  clearLaserDragDropTarget();
  const raw = event.dataTransfer.getData('text/plain');
  if (!raw) return;
  try {
    const data = JSON.parse(raw);
    if (data.type !== 'laser-pass') return;
    const selection=planningMoveSelection;
    if(selection?.type==='laser'&&selection.reservationId===Number(data.reservationId)&&selection.unitKey===(data.unitKey??data.passIndex)){
      const row=event.currentTarget.closest('.laser-agenda-row');
      selection.targetStart=row?laserTimeFromPoint(row,event.clientY):Number(targetStart);
      commitPlanningMoveSelection();return;
    }
    scheduleLaserPass(data.reservationId, data.unitKey ?? data.passIndex, Number(targetStart), targetEnd === null ? null : Number(targetEnd));
  } catch (error) {
    toast('Déplacement Laser Game impossible.');
  }
}

function getOccupiedLanes(date, startTime, duration, ignoreId) {
  const reqStart = typeof startTime === 'string' ? timeToNum(startTime) : startTime;
  const occupied = new Set();
  state.reservations.forEach(r => {
    if (r.id === ignoreId) return;
    if (r.date === date && r.status !== 'cancelled' && (r.lanes || []).length > 0) {
      getBowlingWindowsFromReservation(r).forEach(window => {
        if (overlap(reqStart, Number(duration), window.start, window.duration)) {
          window.lanes.forEach(l => occupied.add(l));
        }
      });
    }
  });
  return occupied;
}

function getFreeCount(date, startTime, duration, ignoreId) {
  const occ = getOccupiedLanes(date, startTime, duration, ignoreId);
  const laneCount = getAvailabilityLaneCount();
  let count = 0;
  for (let i = 1; i <= laneCount; i++) if (!occ.has(i) && state.laneStatuses[i] !== 'maintenance') count++;
  return count;
}

function allocateLanes(n, date, startTime, duration, ignoreId) {
  if (n === 0) return [];
  const occ = getOccupiedLanes(date, startTime, duration, ignoreId);
  const laneCount = getAvailabilityLaneCount();
  const pairs = getAvailabilityLanePairs(laneCount);
  const avail = [];
  for (let i = 1; i <= laneCount; i++) if (!occ.has(i) && state.laneStatuses[i] !== 'maintenance') avail.push(i);
  if (avail.length < n) return null;
  if (n === 1) {
    for (const pair of pairs) {
      if (avail.includes(pair[0]) && !avail.includes(pair[1])) return [pair[0]];
      if (!avail.includes(pair[0]) && avail.includes(pair[1])) return [pair[1]];
    }
    return [avail[0]];
  }
  if (n === 2) {
    for (const pair of pairs) if (avail.includes(pair[0]) && avail.includes(pair[1])) return pair;
  }
  avail.sort((a, b) => a - b);
  for (let i = 0; i <= avail.length - n; i++) {
    const group = [avail[i]];
    let ok = true;
    for (let j = 1; j < n; j++) {
      if (avail[i + j] === group[group.length - 1] + 1) group.push(avail[i + j]);
      else { ok = false; break; }
    }
    if (ok) return group;
  }
  return avail.slice(0, n);
}

// Alloue N pistes libres en GARDANT les pistes déjà choisies (« graines »),
// puis complète avec les pistes libres restantes. Sert quand un groupe déborde
// de la piste pré-remplie depuis une case du planning : l'extension inclut
// toujours la piste cliquée.
function allocateLanesIncludingSeed(n, seedLanes, date, startTime, duration, ignoreId) {
  if (n <= 0) return [];
  const occ = getOccupiedLanes(date, startTime, duration, ignoreId);
  const laneCount = getAvailabilityLaneCount();
  const isFree = (l) => l >= 1 && l <= laneCount && !occ.has(l) && state.laneStatuses[l] !== 'maintenance';
  const avail = [];
  for (let i = 1; i <= laneCount; i++) if (isFree(i)) avail.push(i);
  if (avail.length < n) return null;
  const result = [...new Set((seedLanes || []).map(Number))].filter(isFree).slice(0, n);
  const chosen = new Set(result);
  for (const lane of avail) {
    if (result.length >= n) break;
    if (!chosen.has(lane)) { result.push(lane); chosen.add(lane); }
  }
  return result.length >= n ? result.sort((a, b) => a - b) : null;
}

function getBowlingCandidateWindows(startTime, duration, lanes, opsPlan = null) {
  const fallbackStart = typeof startTime === 'string' ? timeToNum(startTime) : Number(startTime || 0);
  const fallbackDuration = Number(duration || 0);
  const fallbackLanes = (lanes || []).map(Number).filter(Number.isFinite);
  const blocks = Array.isArray(opsPlan?.resourceBlocks)
    ? opsPlan.resourceBlocks.filter(block => block.resourceType === 'bowling_lane')
    : [];
  if (blocks.length) {
    return blocks.map(block => {
      const start = readBlockHour(block, 'start', fallbackStart);
      const end = readBlockHour(block, 'end', start + ((Number(block.durationMinutes) || (fallbackDuration * 60)) / 60));
      const blockLanes = (block.lanes?.length ? block.lanes : fallbackLanes).map(Number).filter(Number.isFinite);
      return {
        start,
        end,
        duration: Math.max(0, end - start),
        lanes: blockLanes,
      };
    }).filter(window => window.duration > 0 && window.lanes.length > 0);
  }
  return [{
    start: fallbackStart,
    end: fallbackStart + fallbackDuration,
    duration: fallbackDuration,
    lanes: fallbackLanes,
  }];
}

function lanesConflict(date, startTime, duration, lanes, ignoreId, candidateOpsPlan = null) {
  if (!Array.isArray(lanes) || !lanes.length) return [];
  const candidateWindows = getBowlingCandidateWindows(startTime, duration, lanes, candidateOpsPlan);
  return state.reservations.filter(r =>
    r.id !== ignoreId &&
    r.date === date &&
    r.status !== 'cancelled' &&
    candidateWindows.some(candidate =>
      getBowlingWindowsFromReservation(r).some(window =>
        overlap(candidate.start, candidate.duration, window.start, window.duration) &&
        window.lanes.some(l => candidate.lanes.includes(l))
      )
    )
  );
}

function getLaserAvailability(date, startTime, duration, pax, ignoreId) {
  const players = Number(pax || 0);
  // ON NE VALIDE QUE CE QUI SERA REELLEMENT POSE : la partie 1 et ses vagues.
  // Les parties suivantes ne sont pas placees a la creation (elles attendent
  // dans la file « a placer » et sont controlees au moment ou le staff les
  // pose, par checkManualLaserPassPlacement). Les valider ici exigeait 3 h
  // d arene CONTIGUE pour un groupe de 70 en 2 parties, et faisait donc
  // disparaitre des heures de depart parfaitement libres (Movsar 2026-08-26 :
  // « pour 70 personnes ca met 48/30, il doit pouvoir scinder »).
  const candidateWindows = getLaserCandidateWindows(
    typeof startTime === 'string' ? startTime : numToTime(startTime),
    duration,
    players
  ).filter(window => Number(window.countIndex || 1) === 1);
  const waveCount = Math.max(...candidateWindows.map(window => Number(window.groupWaveCount || 1)), 1);
  // La capacite du centre affiche, jamais la constante : une arene de 20
  // postes ne partage pas 30 places, et Gembloux fait tourner six lancements
  // la ou Libramont n en fait tourner qu un.
  const postesArene = getAvailabilityLaserCapacity();
  const lancementsMax = getAvailabilityLaserParallelLaunches();
  let tightestRemaining = postesArene;
  let maxPlayersTotal = 0;
  let sharedNow = false;
  let ok = true;
  let message = '';

  const normalizeKey = value => Math.round(Number(value) * 60);
  const laserWindowsForDate = () => state.reservations
    .filter(r => r.id !== ignoreId && r.date === date && r.status !== 'cancelled')
    .flatMap(getLaserWindowsFromReservation);

  for (const candidate of candidateWindows) {
    const overlappingWindows = laserWindowsForDate()
      .filter(window => overlap(candidate.start, candidate.duration, window.start, window.duration));

    // Le serveur (ops-engine.findJoinableLaserSession) fusionne une nouvelle
    // demande avec une session laser existante compatible : capacité libre et
    // depart/fin a +/-15 min. On reproduit cette logique cote modale, sinon une
    // session partageable (ex. 18/30 joueurs) etait comptee comme un 2e
    // lancement parallele et affichee « complet » alors qu'il reste des places.
    const candidateStartMin = normalizeKey(candidate.start);
    const candidateEndMin = normalizeKey(candidate.end);
    const sessions = new Map();
    overlappingWindows.forEach(window => {
      const key = `${normalizeKey(window.start)}-${normalizeKey(window.end)}`;
      const entry = sessions.get(key) || { start: window.start, end: window.end, players: 0 };
      entry.players += Number(window.players || window.reservation?.pax || 0);
      sessions.set(key, entry);
    });
    const joinable = [...sessions.values()]
      .filter(session =>
        session.players + Number(candidate.players || 0) <= postesArene
        && Math.abs(normalizeKey(session.start) - candidateStartMin) <= 15
        && Math.abs(normalizeKey(session.end) - candidateEndMin) <= 15)
      .sort((a, b) => Math.abs(normalizeKey(a.start) - candidateStartMin) - Math.abs(normalizeKey(b.start) - candidateStartMin))[0] || null;

    const effStart = joinable ? joinable.start : candidate.start;
    const effEnd = joinable ? joinable.end : candidate.end;
    const effDuration = joinable ? Math.max(0, effEnd - effStart) : candidate.duration;
    const overlapping = joinable
      ? laserWindowsForDate().filter(window => overlap(effStart, effDuration, window.start, window.duration))
      : overlappingWindows;

    const sessionKey = `${normalizeKey(effStart)}-${normalizeKey(effEnd)}`;
    const sessionKeys = new Set(overlapping.map(window => `${normalizeKey(window.start)}-${normalizeKey(window.end)}`));
    const joinsExistingSession = sessionKeys.has(sessionKey);
    const launchCount = sessionKeys.size + (joinsExistingSession ? 0 : 1);
    const playersBefore = overlapping.reduce((sum, window) => sum + Number(window.players || window.reservation?.pax || 0), 0);
    const playersTotal = playersBefore + Number(candidate.players || 0);
    maxPlayersTotal = Math.max(maxPlayersTotal, playersTotal);
    tightestRemaining = Math.min(tightestRemaining, Math.max(0, postesArene - playersTotal));
    sharedNow = sharedNow || (playersBefore > 0 && joinsExistingSession);
    // DEUX CAUSES DISTINCTES, DEUX MESSAGES. Un total brut « 48/30 » laisse
    // croire que le groupe entier ne rentre pas, alors que le moteur l a deja
    // scinde en vagues : ce qui coince, c est UNE vague sur UN lancement. Et
    // une arene deja occupee par un lancement non joignable n a rien a voir
    // avec un manque de places (Movsar 2026-08-26).
    const heureLancement = formatClockDisplay(effStart);
    const vagueIndex = Number(candidate.groupWaveIndex || 1);
    const vagueTotal = Number(candidate.groupWaveCount || 1);
    const situeVague = vagueTotal > 1
      ? ` (vague ${vagueIndex}/${vagueTotal}, ${Number(candidate.players || 0)} joueurs)`
      : '';
    if (launchCount > lancementsMax) {
      ok = false;
      message = lancementsMax > 1
        ? `L'arène fait déjà tourner ${lancementsMax} lancements à ${heureLancement}, son maximum. Choisissez un autre départ.`
        : `L'arène tourne déjà à ${heureLancement} : un seul lancement à la fois. Choisissez un autre départ.`;
      break;
    }
    if (playersTotal > postesArene) {
      ok = false;
      const restantes = Math.max(0, postesArene - playersBefore);
      message = `Lancement de ${heureLancement} : ${playersBefore} joueur${playersBefore > 1 ? 's' : ''} déjà inscrit${playersBefore > 1 ? 's' : ''}, il reste ${restantes} place${restantes > 1 ? 's' : ''}${situeVague}. Décalez le départ.`;
      break;
    }
  }
  // Le laser se joue a deux au moins (minPax du laser_game au catalogue du
  // centre, servi par /api/public-booking-meta) : sous ce minimum, aucun
  // depart ne vaut, quelle que soit l arene.
  const minimumLaser = Math.trunc(Number((getCenterActivity('laser_game') || {}).minPax) || 0);
  if (minimumLaser > 1 && players > 0 && players < minimumLaser) {
    ok = false;
    message = `Le laser game se joue à ${minimumLaser} joueurs minimum.`;
  }

  return {
    ok,
    playersBefore: 0,
    playersTotal: maxPlayersTotal,
    groupPlayers: players,
    waveCount,
    splitGroup: waveCount > 1,
    remainingPlaces: Math.max(0, tightestRemaining),
    sharedNow,
    mayShare: maxPlayersTotal < postesArene,
    message: ok ? '' : message
  };
}

function parseLaneInput(value = '') {
  const laneCount = getAvailabilityLaneCount();
  return [...new Set(String(value).split(',').map(s => Number(s.trim())).filter(n => n > 0 && n <= laneCount))].sort((a, b) => a - b);
}

function formatLaneInput(lanes = []) {
  return lanes.length ? lanes.join(',') : '';
}

function getSuggestedEditLanes(requiredCount, date, startTime, duration, ignoreId, currentValue = '') {
  if (!requiredCount) return [];
  const occupied = getOccupiedLanes(date, startTime, duration, ignoreId);
  const laneCount = getAvailabilityLaneCount();
  const available = new Set();
  for (let i = 1; i <= laneCount; i++) {
    if (!occupied.has(i) && state.laneStatuses[i] !== 'maintenance') available.add(i);
  }

  const kept = parseLaneInput(currentValue).filter(l => available.has(l));
  // LE STAFF PEUT DONNER PLUS DE PISTES QUE LE MINIMUM (corrige 2026-08-20,
  // Movsar : « tout ce que je modifie pour les heures et les pistes ça modifie
  // rien »). Ce `.slice(0, requiredCount)` tronquait le choix au minimum
  // calcule : cocher les pistes 5 et 6 en plus de la 1 renvoyait [1], et le
  // staff voyait ses clics disparaitre a l'enregistrement. Un groupe de 4 qui
  // veut trois pistes cote a cote est un choix REALISABLE, donc il se respecte.
  // Le minimum, lui, reste un plancher : `saveEdit` complete et le dit quand il
  // en manque. Le serveur accepte deja ce choix (verifie sur le vrai handler :
  // lanes [1,5,6] envoyees, [1,5,6] ecrites), c'est le client qui l'ecrasait.
  if (kept.length >= requiredCount) return kept;

  if (requiredCount === 2 && kept.length === 1) {
    const pair = getAvailabilityLanePairs(laneCount).find(group => group.includes(kept[0]));
    const mate = pair ? pair.find(l => l !== kept[0]) : null;
    if (mate && available.has(mate)) return [kept[0], mate].sort((a, b) => a - b);
  }

  // COMPLETER N'EST PAS REMPLACER. Il manque des pistes pour l'effectif : on
  // AJOUTE a celles que le staff a cochees au lieu de repartir d'une allocation
  // neuve, qui jetait son choix (piste 5 cochee, [1,2] enregistrees).
  if (kept.length) {
    const extended = allocateLanesIncludingSeed(requiredCount, kept, date, startTime, duration, ignoreId);
    if (extended) return extended;
  }

  const allocated = allocateLanes(requiredCount, date, startTime, duration, ignoreId);
  return allocated ? [...allocated].sort((a, b) => a - b) : null;
}

function refreshEditPreview() {
  if (!state.selectedRes || !state.editState) return;
  const e = state.editState;
  const meta = `${getReservationLabel(state.selectedRes)} · ${e.startTime || '--:--'} · ${e.lanesStr ? `pistes ${e.lanesStr}` : 'hors piste'}`;
  const nameEl = document.getElementById('editSummaryName');
  const metaEl = document.getElementById('editSummaryMeta');
  const paxEl = document.getElementById('editSummaryPax');
  const durationEl = document.getElementById('editSummaryDuration');
  const assignEl = document.getElementById('editAssignmentValue');
  const laneInput = document.getElementById('editLanesInput');
  if (nameEl) nameEl.textContent = e.name || 'Réservation';
  // Le prix du dossier adapte suit le nombre de joueurs et la duree, sans
  // re-rendre : c est la meme regle que le conseil de pistes juste en
  // dessous (Movsar : « le prix ne change pas quand on augmente de joueur »).
  majEditPrixEstime();
  if (metaEl) metaEl.textContent = meta;
  // LE CONSEIL SUIT LA FRAPPE. Le formulaire n'est pas re-rendu pendant la
  // saisie (ça volerait le focus), donc tout texte DERIVE de l'etat doit etre
  // rafraichi ici. Sans cette ligne, le conseil affichait le minimum de
  // l'ancien effectif : « 4 pistes pour 23 joueurs » alors que le champ disait
  // deja 12. Meme famille que la ligne d'etat de la reservation rapide
  // (journal 186), et meme parade : rappeler la MEME fonction, aucune regle
  // recopiee.
  const adviceEl = document.getElementById('editLanesHint');
  if (adviceEl) adviceEl.textContent = editLaneAdvice(state.selectedRes, e);
  if (paxEl) paxEl.textContent = e.pax || 0;
  if (durationEl) durationEl.textContent = formatDurationLabel(e.duration || 0);
  if (assignEl) assignEl.textContent = e.lanesStr || 'Hors piste';
  if (laneInput && document.activeElement !== laneInput) laneInput.value = e.lanesStr || '';
}

function syncEditLaneAssignment() {
  if (!state.selectedRes || !state.editState) return null;
  const requiresLanes = reservationNeedsLanes(state.selectedRes.type, state.selectedRes.formuleId);
  if (!requiresLanes) {
    state.editState.lanesStr = '';
    refreshEditPreview();
    return [];
  }
  // Un autre jour : la console n a pas ses dossiers, le serveur attribue les
  // pistes a l enregistrement (changerJourEdition).
  if (state.editState.date && state.editState.date !== state.selectedRes.date) {
    refreshEditPreview();
    return null;
  }
  const requiredCount = getEditBowlingCapacityNeed(state.selectedRes, state.editState).requiredCount;
  const duration = Number(state.editState.duration || state.selectedRes.duration || 0);
  const suggested = getSuggestedEditLanes(requiredCount, state.selectedRes.date, state.editState.startTime, duration, state.selectedRes.id, state.editState.lanesStr);
  if (suggested) state.editState.lanesStr = formatLaneInput(suggested);
  refreshEditPreview();
  return suggested;
}

function setEditField(field, value, syncLanes = false) {
  if (!state.editState) return;
  if (state.editError) setEditError('');
  state.editState[field] = value;
  if (field === 'pax' && state.editState.programmeEdite) {
    const programme = state.editState.programmeEdite;
    if (programme.laser_game?.extraLaser && Number(value) < programme.laser_game.extraLaser.participants) { delete programme.laser_game.extraLaser; toast('La partie supplémentaire est retirée : son effectif dépassait le nouveau groupe.'); }
    Object.values(programme.othersOptions || {}).forEach(options => { if (options.upsell && Number(value) < options.upsell.participants) { delete options.upsell; toast('Offre retirée du devis : le nouvel effectif est tarifé au catalogue.'); } });
  }
  if (syncLanes) syncEditLaneAssignment();
  else refreshEditPreview();
  if (field === 'pax' && state.editState.programmeEdite) {
    // Refresh derived activity limits without replacing the input being typed.
    document.querySelectorAll('.dossier-activity[data-edit-activity]').forEach(row => {
      const counter = row.querySelector('.dossier-activity-count');
      if (counter) counter.outerHTML = renderActivityParticipantsControl(row.dataset.editActivity, 'edit', true);
    });
  }
}

function setEditLanes(value) {
  if (!state.editState) return;
  state.editState.lanesStr = value;
  refreshEditPreview();
}

// Bascule d'une piste depuis le selecteur. La source de verite reste
// `lanesStr`, le format que le reste du formulaire lit deja : on ne cree pas un
// second etat pour les memes pistes, sinon les deux divergent au premier oubli.
function getEditLaneNumbers() {
  return String(state.editState?.lanesStr || '')
    .split(',')
    .map(part => Number(String(part).trim()))
    .filter(lane => Number.isFinite(lane) && lane >= 1);
}

function toggleEditLane(lane) {
  if (!state.editState) return;
  if (state.editError) setEditError('');
  const choisies = new Set(getEditLaneNumbers());
  if (choisies.has(lane)) choisies.delete(lane);
  else choisies.add(lane);
  state.editState.lanesStr = [...choisies].sort((a, b) => a - b).join(',');
  const bouton = document.querySelector(`.lane-picker .lane-chip[onclick="toggleEditLane(${lane})"]`);
  if (bouton) {
    const actif = choisies.has(lane);
    bouton.classList.toggle('is-on', actif);
    bouton.setAttribute('aria-pressed', actif ? 'true' : 'false');
  }
  refreshEditPreview();
}
window.toggleEditLane = toggleEditLane;

