function sortReservations(list = []) {
  return [...list].sort((a, b) => {
    if (a.date !== b.date) return a.date.localeCompare(b.date);
    const timeDelta = timeToNum(a.startTime) - timeToNum(b.startTime);
    if (timeDelta !== 0) return timeDelta;
    return Number(a.id) - Number(b.id);
  });
}

// Reconcilie le cache mensuel (source des compteurs du calendrier Reservations)
// avec le snapshot serveur d'un jour poll : sans ca, une resa supprimee ou
// deplacee cote serveur restait dans le cache (fusion par union d'id) et gonflait
// le compteur de la case ("15 resa" affiche alors que le clic charge le reel).
// On remplace les entrees du cache pour CETTE date par la liste serveur du jour.
function reconcileMonthCacheForDate(dateStr, reservations) {
  if (!staffReservationsDataCache.loaded) return;
  const others = (staffReservationsDataCache.reservations || []).filter(r => r.date !== dateStr);
  staffReservationsDataCache = {
    ...staffReservationsDataCache,
    reservations: [...others, ...(reservations || [])]
  };
}

function replaceReservationsForDate(dateStr, reservations) {
  const others = state.reservations.filter(r => r.date !== dateStr);
  const serverList = reservations || [];
  reconcileMonthCacheForDate(dateStr, serverList);
  if (!pendingReservationMutations.size) {
    state.reservations = sortReservations([...others, ...serverList]);
    return false;
  }
  const now = Date.now();
  const serverKeys = new Set(serverList.map(r => getReservationWriteKey(r.id)));
  // Rendu VRAI quand une valeur du serveur a ete masquee par une ecriture
  // locale encore en vol : la journee montree n est pas celle du serveur, sa
  // revision ne doit pas etre retenue (voir syncDateReservations).
  let masque = false;
  // 1) Fusion champ par champ : pour chaque résa du snapshot serveur qui a une
  //    mutation en attente, on protège UNIQUEMENT les champs mutés localement
  //    tant que le serveur n'a pas confirmé la valeur attendue (ou tant que le
  //    délai de grâce n'est pas dépassé). Les autres champs (donc les
  //    changements faits par un autre poste) passent normalement.
  const merged = serverList.map(serverReservation => {
    const key = getReservationWriteKey(serverReservation.id);
    const entry = pendingReservationMutations.get(key);
    if (!entry) return serverReservation;
    if (reservationMatchesMutation(serverReservation, entry) || now >= entry.deadline) {
      pendingReservationMutations.delete(key);
      pendingReservationWriteIds.delete(key);
      return serverReservation;
    }
    masque = true;
    return applyExpectedMutationFields(serverReservation, entry);
  });
  // 2) Résas absentes du snapshot serveur (création/déplacement pas encore visible)
  //    mais avec une mutation en attente : on conserve la version locale.
  const pendingMissing = state.reservations.filter(r => {
    if (r.date !== dateStr) return false;
    const key = getReservationWriteKey(r.id);
    if (serverKeys.has(key)) return false;
    const entry = pendingReservationMutations.get(key);
    if (!entry) return false;
    if (now >= entry.deadline) {
      pendingReservationMutations.delete(key);
      pendingReservationWriteIds.delete(key);
      return false;
    }
    return true;
  });
  state.reservations = sortReservations([...others, ...merged, ...pendingMissing]);
  return masque || pendingMissing.length > 0;
}

function upsertReservationInState(reservation) {
  const next = state.reservations.filter(r => r.id !== reservation.id);
  next.push(reservation);
  state.reservations = sortReservations(next);
  syncReservationIntoMonthCache(reservation);
}

function removeReservationFromState(id) {
  state.reservations = state.reservations.filter(r => r.id !== id);
  removeReservationFromMonthCache(id);
}

// Store partagé : les pages qui lisent le cache mensuel (Réservations v2,
// Utilitaires, Clients) reflètent IMMÉDIATEMENT chaque mutation locale au lieu
// d'attendre le bouton « Actualiser » : indispensable pour les suppressions,
// que le merge par id ne peut pas faire disparaître du cache.
function syncReservationIntoMonthCache(reservation) {
  if (!staffReservationsDataCache.loaded || !reservation) return;
  const rows = (staffReservationsDataCache.reservations || []).filter(r => String(r.id) !== String(reservation.id));
  rows.push(reservation);
  staffReservationsDataCache = { ...staffReservationsDataCache, reservations: rows };
}

function removeReservationFromMonthCache(id) {
  if (!staffReservationsDataCache.loaded) return;
  staffReservationsDataCache = {
    ...staffReservationsDataCache,
    reservations: (staffReservationsDataCache.reservations || []).filter(r => String(r.id) !== String(id))
  };
}

// LE RAFRAICHISSEMENT N'ECRASE PLUS UNE SAISIE EN COURS (corrige 2026-08-19).
// Movsar, sur capture de l'onglet Modifier : « rien ne fonctionne ça
// fonctionne vrm pas ». Diagnostic mesure au harnais : le poll (~1,2 s)
// appelait cette fonction, qui reconstruisait `editState` DEPUIS le serveur,
// sans condition. Le champ gardait ce que le staff avait tape (le DOM n'est
// pas re-rendu), mais l'etat repartait des valeurs d'origine : l'enregistrement
// renvoyait donc la reservation INCHANGEE, avec un « Réservation mise à jour »
// parfaitement mensonger. Une course que le poll gagnait presque toujours, ce
// qui donnait « ça ne marche jamais ».
//
// Regle : tant que l'onglet Modifier est ouvert, la saisie appartient a
// l'humain. On rafraichit `selectedRes` (les faits du serveur, qui servent
// l'onglet Infos et les gardes de conflit), on ne touche pas a `editState`.
function hydrateSelectedReservation() {
  if (!state.selectedRes) return;
  const fresh = state.reservations.find(r => r.id === state.selectedRes.id);
  if (!fresh) {
    closePos();
    return;
  }
  state.selectedRes = fresh;
  if (state.activeTab === 'modifier' && state.editState) return;
  state.editState = etatEditionDepuis(fresh);
}

function buildReservationApiPayload(reservation, overrides = {}) {
  const requiresLanes = overrides.requiresLanes ?? reservationNeedsLanes(reservation.type, reservation.formuleId);
  const laneCount = overrides.laneCount ?? (requiresLanes ? ((reservation.lanes || []).length || getRequiredLaneCount(reservation.type, getReservationActivityPlayers(reservation, 'bowling'), reservation.formuleId)) : 0);
  const channel = overrides.channel || reservation.channel || 'staff';
  return {
    ...reservation,
    ...overrides,
    // Canal public : le centre vient de la ligne d'installation (?center=),
    // jamais du centre de la session staff, qui n'existe pas chez le visiteur.
    centerId: overrides.centerId || reservation.centerId || reservation.center_id
      || (channel === 'public' ? getTunnelCenterId() : getCurrentStaffCenterId()),
    laneCount,
    requiresLanes,
    channel,
    allowPastStart: channel === 'staff' && Boolean(overrides.allowPastStart ?? reservation.allowPastStart)
  };
}

// ── DEUX POSTES, UNE RESERVATION (2026-09-25) ────────────────────────────────
//
// Movsar : « plusieurs ecrans, plusieurs PC, plusieurs personnes ». Chaque
// ecriture de reservation envoie le dossier ENTIER (buildReservationApiPayload),
// pris dans la copie de CET ecran : un poste qui avait la fiche ouverte depuis
// une minute renvoyait le statut, les pistes ou la note d il y a une minute, et
// effacait en silence ce qu un collegue venait d y changer.
//
// Une action est donc une FONCTION (`appliquer` : dossier -> dossier), pas un
// dossier fige. Elle part avec la version sur laquelle on l a calculee
// (baseUpdatedAt, controlee par updateReservation dans lib/database.js). Si le
// serveur repond 409, le dossier a change entre-temps : l action est rejouee
// sur la version actuelle, qui garde ce que l autre a fait. Un seul cas
// s arrete : l action IMPOSE une valeur (un statut, une heure, un nombre de
// joueurs) a un champ que l autre a change autrement. On n ecrase pas : l ecran
// montre la version actuelle et la personne decide. Une action qui COMPOSE
// (ajouter un supplement, recalculer un prix) se rejoue simplement.
const CHAMPS_RESERVATION_ECRITS = ['name', 'phone', 'email', 'date', 'startTime', 'duration', 'totalDuration', 'lanes', 'pax', 'status', 'basePrice', 'price', 'type', 'formuleId', 'label', 'occasion', 'extras', 'paymentMethod', 'notes', 'opsPlan', 'validationStatus', 'activityProgress', 'program', 'centerId'];
const LIBELLES_CHAMPS_RESERVATION = {
  name: 'le nom',
  phone: 'le téléphone',
  email: 'l’e-mail',
  date: 'la date',
  startTime: 'l’heure',
  duration: 'la durée',
  totalDuration: 'la durée',
  lanes: 'les pistes',
  pax: 'le nombre de joueurs',
  status: 'le statut',
  price: 'le prix',
  type: 'l’activité',
  formuleId: 'la formule',
  label: 'la formule',
  occasion: 'l’occasion',
  extras: 'les suppléments',
  paymentMethod: 'le paiement',
  notes: 'la note',
  opsPlan: 'le placement au planning',
  validationStatus: 'la validation',
  activityProgress: 'le suivi des activités',
  program: 'le programme',
  centerId: 'le centre'
};

// Deux valeurs pareilles pour un humain le sont ici : 8 et « 8 », [3] et
// ["3"], null et chaine vide, les memes cles dans un autre ordre.
function valeurReservationComparable(valeur) {
  if (valeur === null || valeur === undefined || valeur === '') return '';
  if (typeof valeur === 'number') return Number.isFinite(valeur) ? String(valeur) : '';
  if (typeof valeur === 'boolean') return String(valeur);
  if (typeof valeur === 'string') {
    const texte = valeur.trim();
    return /^-?\d+(\.\d+)?$/.test(texte) ? String(Number(texte)) : texte;
  }
  if (Array.isArray(valeur)) return JSON.stringify(valeur.map(valeurReservationComparable));
  if (typeof valeur === 'object') {
    return JSON.stringify(Object.keys(valeur).sort()
      .map((cle) => [cle, valeurReservationComparable(valeur[cle])])
      .filter((paire) => paire[1] !== ''));
  }
  return String(valeur);
}

function champsReservationModifies(avant, apres) {
  return CHAMPS_RESERVATION_ECRITS.filter((champ) => valeurReservationComparable(avant ? avant[champ] : undefined)
    !== valeurReservationComparable(apres ? apres[champ] : undefined));
}

function libellesChampsReservation(champs) {
  return [...new Set((champs || []).map((champ) => LIBELLES_CHAMPS_RESERVATION[champ]).filter(Boolean))].join(', ');
}

function conflitReservation(courante, champs, message) {
  const libelles = libellesChampsReservation(champs);
  const error = new Error(message || `La réservation a changé entre-temps${libelles ? ` (${libelles})` : ''}. L’écran est à jour : refaites l’action si elle tient toujours.`);
  error.conflit = true;
  error.reservation = courante;
  error.champs = champs || [];
  return error;
}

// LES ECRITURES D UN POSTE SUR UN MEME DOSSIER PARTENT L UNE APRES L AUTRE.
// Deux glisser-deposer rapides, ou « Arrivé » puis « Payé » : la seconde
// s applique a ce que la premiere a produit. Sans cette file, elle partait
// avec la version d avant la premiere et le serveur la prenait pour une
// modification venue d ailleurs. (Carte creee a la demande : une fonction est
// hissee, une constante ne l est pas.)
function fileEcrituresReservation() {
  if (!fileEcrituresReservation.carte) fileEcrituresReservation.carte = new Map();
  return fileEcrituresReservation.carte;
}

function enchainerEcritureReservation(id, ecrire) {
  const file = fileEcrituresReservation();
  const cle = String(id);
  const precedente = file.get(cle) || Promise.resolve(null);
  const tache = precedente.then((derniere) => ecrire(derniere));
  const suite = tache.then((payload) => (payload && payload.reservation) || null, () => null);
  file.set(cle, suite);
  suite.then(() => { if (file.get(cle) === suite) file.delete(cle); });
  return tache;
}

// Un déplacement d'activité est une intention ciblée, jamais une copie du dossier.
// Le serveur conserve les autres activités et refuse une version devenue ancienne.
function envoyerDeplacementActivite(avant, activityMove) {
  return enchainerEcritureReservation(avant.id, async (derniere) => {
    const base = derniere && String(derniere.id) === String(avant.id) ? derniere : avant;
    let payload;
    try {
      payload = await apiRequest(API_ENDPOINTS.staffReservations, {
        method: 'PATCH',
        body: JSON.stringify({ id: base.id, centerId: base.centerId || base.center_id || getCurrentStaffCenterId(), baseUpdatedAt: base.updatedAt, activityMove })
      });
    } catch (error) {
      if (error.status === 409 && error.payload?.reservation) {
        throw conflitReservation(error.payload.reservation, ['opsPlan'], 'Le planning a changé sur un autre poste. Vérifiez sa position actuelle puis refaites le déplacement.');
      }
      throw error;
    }
    const saved = payload?.reservation;
    const receipt = payload?.activityMove;
    const cible = block => activityMove.activityId === 'bowling'
      ? block.resourceType === 'bowling_lane' || block.activityId === 'bowling'
      : (block.resourceType === 'laser_arena' || block.activityId === 'laser_game') && laserBlockUnitKey(block) === activityMove.unitKey;
    const autres = plan => (plan?.resourceBlocks || []).filter(block => !cible(block));
    const invariants = ['date', 'startTime', 'duration', 'totalDuration', 'pax', 'price', 'basePrice', 'extras', 'program', 'status', 'activityProgress'];
    const ancienPlanExplicite = Boolean(base.opsPlan?.resourceBlocks?.length);
    const conforme = saved && String(saved.id) === String(base.id)
      && String(saved.centerId || saved.center_id) === String(base.centerId || base.center_id || getCurrentStaffCenterId())
      && receipt?.activityId === activityMove.activityId && receipt.unchangedActivities === true
      && (activityMove.activityId !== 'laser_game' || receipt.unitKey === activityMove.unitKey)
      && invariants.every(key => valeurReservationComparable(saved[key]) === valeurReservationComparable(base[key]))
      && (!ancienPlanExplicite || valeurReservationComparable(autres(saved.opsPlan)) === valeurReservationComparable(autres(base.opsPlan)))
      && (!Array.isArray(base.opsPlan?.timeline) || valeurReservationComparable((saved.opsPlan?.timeline || []).filter(block => !cible(block))) === valeurReservationComparable(base.opsPlan.timeline.filter(block => !cible(block))));
    if (!conforme) throw new Error('Le serveur n’a pas confirmé un déplacement limité à cette activité. Actualisez le planning avant de réessayer.');
    return payload;
  });
}

function envoyerModificationReservation(avant, appliquer, overrides = {}) {
  return enchainerEcritureReservation(avant.id, async (derniere) => {
    // Une ecriture de CE poste vient d aboutir sur ce dossier : on part de ce
    // que le serveur en a fait, pas de l ecran d avant.
    const base = derniere && String(derniere.id) === String(avant.id) ? derniere : avant;
    const apres = appliquer(base);
    // Des options qui dependent du dossier (le nombre de pistes d une partie
    // laser) se recalculent sur la version envoyee, pas sur celle d avant.
    const optionsPour = (reservation) => (typeof overrides === 'function' ? overrides(reservation) : overrides);
    const envoyer = (version, reservation) => apiRequest(API_ENDPOINTS.staffReservations, {
      method: 'PATCH',
      body: JSON.stringify({
        ...buildReservationApiPayload(reservation, optionsPour(reservation)),
        ...(version ? { baseUpdatedAt: version } : {})
      })
    });
    try {
      return await envoyer(base.updatedAt, apres);
    } catch (error) {
      const courante = error && error.status === 409 && error.payload ? error.payload.reservation : null;
      if (!courante) throw error;
      const miens = champsReservationModifies(base, apres);
      const leurs = champsReservationModifies(base, courante);
      const rejouee = appliquer(courante);
      // Dispute : l action pose la MEME valeur quelle que soit la version (elle
      // l impose), et l autre y avait mis autre chose.
      const disputes = miens.filter((champ) => leurs.includes(champ)
        && valeurReservationComparable(rejouee[champ]) === valeurReservationComparable(apres[champ])
        && valeurReservationComparable(rejouee[champ]) !== valeurReservationComparable(courante[champ]));
      if (disputes.length) throw conflitReservation(courante, disputes);
      try {
        const payload = await envoyer(courante.updatedAt, rejouee);
        payload.changeEntreTemps = libellesChampsReservation(leurs.filter((champ) => !miens.includes(champ)));
        return payload;
      } catch (second) {
        const encore = second && second.status === 409 && second.payload ? second.payload.reservation : null;
        if (encore) throw conflitReservation(encore, [], 'La réservation change en ce moment ailleurs. L’écran est à jour : réessayez dans un instant.');
        throw second;
      }
    }
  });
}

// L EDITION PART D UNE VERSION CONNUE. Ce que la personne a change se mesure
// contre le dossier tel qu il etait a l ouverture du formulaire (`origine`),
// jamais contre l ecran rafraichi pendant qu elle tapait ; `base` est la
// version que le serveur controlera (l origine, ou la version montree apres un
// conflit). Rangee a cote de l etat d edition, sans rien ajouter a ce qui est
// envoye au serveur.
function departsEdition() {
  if (!departsEdition.carte) departsEdition.carte = new WeakMap();
  return departsEdition.carte;
}

function etatEditionDepuis(reservation) {
  const etat = { ...reservation };
  etat.lanesStr = (reservation.lanes || []).join(', ');
  departsEdition().set(etat, { origine: { ...reservation }, base: { ...reservation } });
  return etat;
}

// CE QUI DECIDE D'UN RE-RENDU, C'EST CE QUI SE DESSINE, PAS L'HORODATAGE.
//
// Cette projection portait `updatedAt`, un champ que la console n'affiche
// NULLE PART : il ne servait que de fourre-tout « quelque chose a bouge cote
// serveur ». Consequence visible au comptoir : un clic sur Arrive / Paye /
// Confirme appliquait l'etat optimiste (1er rendu), puis l'echo serveur
// revenait ~300 ms plus tard avec un `updatedAt` neuf, la signature changeait
// alors que le PIXEL etait identique, et la liste entiere se redessinait une
// deuxieme fois. Movsar voyait un double clic la ou il y en avait un seul.
//
// On compare donc ce qui compte : les champs REELLEMENT dessines par
// renderReservationRow / les cartes du planning (identite, horaire, ressource,
// tags). `updatedAt` sort ; `name`, `phone`, `notes`, `occasion` et `label`
// entrent, parce qu'ils se dessinent et qu'ils n'etaient couverts que par
// ricochet, via `updatedAt`.
// Les coches comptent par activite faite, pas par leur horodatage : l echo du
// serveur porte son heure a lui, la meme minute affichee, et ne doit rien
// repeindre (meme regle que toggleFormulaActivity, « une coche, un rendu »).
function empreinteCoches(progression) {
  return Object.keys(progression || {}).filter(cle => progression[cle] && progression[cle].done).sort().join(',');
}

function reservationRenderSignature(r) {
  return {
    id: Number(r.id),
    status: r.status,
    startTime: r.startTime,
    duration: Number(r.duration) || 0,
    pax: Number(r.pax) || 0,
    price: Number(r.price) || 0,
    type: r.type || 'bowling',
    formuleId: r.formuleId || '',
    opsPlanKey: JSON.stringify((r.opsPlan?.resourceBlocks || []).map(block => [block.resourceType, block.startTime, block.endTime, block.lanes, block.players])),
    guestOpsKey: JSON.stringify(r.opsPlan?.guestOps || {}),
    lanes: (r.lanes || []).map(Number),
    paymentMethod: r.paymentMethod || '',
    name: r.name || '',
    phone: r.phone || '',
    label: r.label || '',
    occasion: r.occasion || '',
    notes: r.notes || '',
    // Se dessinent depuis le 2026-09-28 : l etat « À vérifier » / « Valider »
    // (isReservationAwaitingReview) et les activites d une visite avec leurs
    // durees. Absents, valider une demande ne redessinait pas sa ligne.
    validationStatus: r.validationStatus || '',
    programKey: JSON.stringify((r.program?.items || []).map(item => [item.activityId, item.minutes, item.games, item.duration, item.sessions, item.sessionMinutes, item.units, item.hours, item.participants, item.upsell, item.extraLaser])),
    // Se dessinent aussi (2026-10-08) : les coches d activite (« Fait », « En
    // cours », le passage a « À clôturer »), l absence notee (« Pas venus »),
    // le montant reellement encaisse et les accompagnants. Absents, la coche
    // ou le « Pas venu » d un autre poste attendaient le tic d une minute, et
    // le « Pas venu » de ce poste-ci ne redessinait rien.
    activityProgress: empreinteCoches(r.activityProgress),
    absentAt: r.absentAt || '',
    amountPaid: r.amountPaid ?? null,
    discountReason: r.discountReason || '',
    companions: Number(r.companions) || 0
  };
}

function getCurrentStaffReservationsForUi() {
  return todaysReservations().map(reservationRenderSignature);
}

// LES HORAIRES RETENUS PAR UN CLIENT EN TRAIN DE RESERVER EN LIGNE (table
// slot_holds, 2026-09-30). staff-state les sert A PART (`holds`) : ce ne sont
// pas des reservations, ils n entrent ni dans les listes, ni dans les
// chiffres, ni dans le stockage du poste. Ils prennent pourtant vraiment la
// place (le serveur refuse une reservation qui les chevauche) : le planning
// les dessine donc en attente, avec l heure a laquelle ils se liberent sans
// confirmation. Un blocage echu disparait au rendu suivant, sans attendre le
// serveur ; le pouls (domaine `jour`) fait relire la journee quand un blocage
// arrive, se convertit ou echoit.
const blocagesEnLigne = new Map();
function memoriserBlocagesEnLigne(centerId, dateStr, liste) {
  blocagesEnLigne.set(`${centerId}:${dateStr}`, Array.isArray(liste) ? liste.filter(b => b && b.blocage) : []);
}
function getBlocagesEnLigne(dateStr = state.currentDate) {
  const maintenant = Date.now();
  return (blocagesEnLigne.get(`${getCurrentStaffCenterId()}:${dateStr}`) || [])
    .filter(b => Date.parse(b.blocage.expiresAt) > maintenant);
}
function heureLiberationBlocage(blocage) {
  const t = new Date(blocage.blocage.expiresAt);
  return Number.isNaN(t.getTime()) ? '' : t.toLocaleTimeString('fr-BE', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Brussels' });
}
function texteBlocageEnLigne(blocage) {
  const heure = heureLiberationBlocage(blocage);
  return `Réservation en ligne en cours${heure ? ` : sans confirmation, la place se libère à ${heure}` : ''}.`;
}

function getStaffDataSignature(dateStr = state.currentDate) {
  const reservations = dateStr === state.currentDate
    ? getCurrentStaffReservationsForUi()
    : state.reservations
        .filter(r => r.date === dateStr && r.status !== 'cancelled')
        .map(reservationRenderSignature);
  return JSON.stringify({
    date: dateStr,
    staffResourceView: state.staffResourceView || 'all',
    reservations,
    blocagesEnLigne: getBlocagesEnLigne(dateStr).map(b => `${b.id}@${b.blocage.expiresAt}`),
    laneStatuses: state.laneStatuses,
    searchTerm: state.searchTerm || '',
    staffStatusFilter: state.staffStatusFilter || 'all',
    planningExpanded: !!state.staffPlanningExpanded
  });
}

function getSelectedReservationSignature() {
  if (!state.selectedRes) return '';
  return JSON.stringify({
    id: state.selectedRes.id,
    status: state.selectedRes.status,
    startTime: state.selectedRes.startTime,
    duration: state.selectedRes.duration,
    pax: state.selectedRes.pax,
    price: state.selectedRes.price,
    lanes: state.selectedRes.lanes || [],
    paymentMethod: state.selectedRes.paymentMethod || '',
    // La fiche dit « Cette demande attend votre validation » et « Valider »
    // tant que la demande attend : la valider doit la redessiner.
    validationStatus: state.selectedRes.validationStatus || '',
    // Ce que la fiche montre aussi (2026-10-08) : son mot, qui suit l heure
    // (« À venir » puis « En retard »), et tout ce qu un autre poste peut
    // changer sous ses yeux.
    moment: getStaffDashboardStatusMeta(state.selectedRes).label,
    name: state.selectedRes.name || '',
    phone: state.selectedRes.phone || '',
    notes: state.selectedRes.notes || '',
    activityProgress: empreinteCoches(state.selectedRes.activityProgress),
    absentAt: state.selectedRes.absentAt || '',
    amountPaid: state.selectedRes.amountPaid ?? null,
    discountReason: state.selectedRes.discountReason || '',
    activeTab: state.activeTab,
    editState: state.editState ? {
      name: state.editState.name,
      phone: state.editState.phone,
      startTime: state.editState.startTime,
      duration: state.editState.duration,
      pax: state.editState.pax,
      lanesStr: state.editState.lanesStr,
      status: state.editState.status
    } : null
  });
}

// ── LE RE-RENDU D UNE PAGE DEJA OUVERTE EST INVISIBLE (2026-08-25, Movsar :
// « mets une condition generale : pour tout changement, pas de refresh
// visible »). Tant que la surface affichee ne change pas (meme page, meme
// vue, meme jour, meme centre), tout repaint (poll, clic d etat, coche
// d activite) passe par repaintKeepingScroll : defilement conserve, zero
// animation rejouee. Une NAVIGATION (autre page, autre jour) reste un rendu
// frais, avec ses animations d arrivee.
let staffRepaintLastKey = '';
function staffRepaintKey() {
  return [
    getStaffMenuPage(),
    getStaffResourceView(),
    state.currentDate,
    typeof getActiveOpsCenterId === 'function' ? getActiveOpsCenterId() : ''
  ].join('|');
}

function renderStaffData() {
  // Le lot s ouvre AVANT repaintKeepingScroll : sa classe is-repaint salit le
  // style de toute la console, et une lecture de position faite apres la
  // recalculerait pour rien (voir ouvrirLotDefilement).
  avecLotDefilement(() => {
    const staffRoot = document.getElementById('staffView');
    const key = staffRepaintKey();
    const isRepaint = staffRoot && !staffRoot.classList.contains('hidden') && staffRepaintLastKey === key;
    staffRepaintLastKey = key;
    if (isRepaint) {
      repaintKeepingScroll(staffRoot, () => renderStaffDataInner());
      return;
    }
    renderStaffDataInner();
  });
}

function renderStaffDataInner() {
  return avecLotDefilement(renderStaffDataPage);
}

function renderStaffDataPage() {
  // Fusion Clients+Groupes : « groups » n'est plus une page, tout état legacy
  // (onglet sauvegardé, hash) retombe sur Clients, segment « À venir ».
  if (getStaffMenuPage() === 'groups') {
    state.staffMenuPage = 'clients';
    state.staffClientSegment = 'avenir';
    save();
  }
  const dayReservations = todaysReservations();
  renderStaffShell(dayReservations);
  if (isStaffDashboardActive()) {
    renderStaffDashboard(dayReservations);
    return;
  }
  if (isStaffReservationsActive()) {
    renderStaffReservationsPage();
    return;
  }
  if (isStaffClientsActive()) {
    renderStaffClientsPage();
    return;
  }
  if (isStaffPricingActive()) {
    renderStaffPricingPage();
    return;
  }
  if (isStaffEmailsActive()) {
    renderStaffEmailsPage();
    return;
  }
  if (isStaffCampaignsActive()) {
    renderStaffCampaignsPage();
    return;
  }
  if (isStaffUtilityActive()) {
    renderStaffUtilityPage();
    return;
  }
  renderKpis();
  const view = getStaffResourceView();
  syncStaffResourceTabs(dayReservations, view);
  renderPlanning();
  renderLaserPlanning();
  renderGlobalPlanningSurface();
  renderTable();
}

function applyOptimisticReservation(reservation, options = {}) {
  if (!reservation) return { liste: false, fiche: false };
  const beforeData = state.view === 'staff' ? getStaffDataSignature() : '';
  const beforeSelected = getSelectedReservationSignature();
  upsertReservationInState(reservation);
  if (state.selectedRes && state.selectedRes.id === reservation.id) {
    state.selectedRes = reservation;
    if (options.preserveEditState) {
      state.editState = etatEditionDepuis(reservation);
    }
  }
  save();
  // Dit ce qu il a deja repeint : un geste qui repeint aussi de lui-meme ne
  // refait que le reste (« une coche, un rendu »).
  const peint = { liste: false, fiche: false };
  if (state.view === 'staff' && beforeData !== getStaffDataSignature()) { renderStaffData(); peint.liste = true; }
  if (state.selectedRes && state.selectedRes.id === reservation.id && beforeSelected !== getSelectedReservationSignature()) { renderPos(); peint.fiche = true; }
  return peint;
}

function removeOptimisticReservation(id) {
  const beforeData = state.view === 'staff' ? getStaffDataSignature() : '';
  removeReservationFromState(id);
  if (state.selectedRes && state.selectedRes.id === id) {
    closePos();
  }
  save();
  if (state.view === 'staff' && beforeData !== getStaffDataSignature()) renderStaffData();
}

function normalizeStaffCenterId(value, fallback = 'libramont') {
  const raw = String(value || fallback).trim();
  const clean = raw
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
  if (!clean) return fallback;
  if (['libramont', 'gembloux', 'ciney'].includes(clean)) return clean;
  if (clean.includes('gembloux')) return 'gembloux';
  if (clean.includes('ciney')) return 'ciney';
  if (
    clean.includes('libramont')
    || clean === 'fun galaxy centre'
    || clean === 'fun galaxy center'
    || clean === 'fungalaxy centre'
    || clean === 'fungalaxy center'
    || clean === 'fun galaxy'
    || clean === 'fungalaxy'
    || clean === 'admin'
    || clean === 'pinlane'
  ) {
    return 'libramont';
  }
  // Tout autre slug bien forme est un centre LEGITIME (deuxieme client et
  // suivants) : il passe tel quel, comme cote serveur (lib/staff-auth.js).
  // Rabattre l'inconnu sur 'libramont' faisait signer les exports et les
  // lectures du staff d'un autre client avec le centre du premier.
  const slug = raw.toLowerCase();
  if (PUBLIC_CENTER_ID_PATTERN.test(slug)) return slug;
  return fallback;
}

// LE CENTRE QUE SERT LE TUNNEL PUBLIC.
//
// embed.js pose `?center=<slug>` sur l'iframe qu'il installe chez le client.
// Personne ne lisait ce parametre : tout retombait sur normalizeStaffCenterId,
// qui ne connait que les trois centres Fun Galaxy et rabat tout le reste sur
// 'libramont'. Un deuxieme client colle la ligne d'installation et reserve chez
// Fun Galaxy.
//
// On lit donc le slug de l'URL, borne exactement comme le serveur
// (CENTER_ID_PATTERN, lib/center-config.js). Aucune liste blanche ici : le
// serveur reste seul juge de l'existence du centre, sinon on recree le meme
// mur pour le troisieme client. Slug absent ou mal forme = comportement
// historique (le centre de la session staff).
const PUBLIC_CENTER_ID_PATTERN = /^[a-z][a-z0-9-]{1,40}$/;
let publicCenterIdFromUrl;
function getUrlCenterId() {
  if (publicCenterIdFromUrl !== undefined) return publicCenterIdFromUrl;
  publicCenterIdFromUrl = '';
  try {
    // L'ADRESSE PAR CENTRE d'abord (2026-08-18) : « /reserver/libramont »
    // est la page personnelle du centre, generee par le seul fait que le
    // centre existe (le slug EST la cle : catalogue, marque, horaires
    // suivent tout seuls via public-booking-meta). La query ?center= reste
    // acceptee : c'est le contrat historique d'embed.js.
    const path = String(window.location.pathname || '').toLowerCase();
    const pathMatch = path.match(/^\/reserver\/([a-z][a-z0-9-]{1,40})\/?$/);
    if (pathMatch && PUBLIC_CENTER_ID_PATTERN.test(pathMatch[1])) {
      publicCenterIdFromUrl = pathMatch[1];
      return publicCenterIdFromUrl;
    }
    const params = new URLSearchParams(window.location.search || '');
    const raw = String(params.get('center') || params.get('centerId') || '').trim().toLowerCase();
    if (PUBLIC_CENTER_ID_PATTERN.test(raw)) publicCenterIdFromUrl = raw;
  } catch (error) {
    publicCenterIdFromUrl = '';
  }
  return publicCenterIdFromUrl;
}

// LA DEMONSTRATION PINLANE : le tunnel quand l adresse ne nomme personne.
//
// `/reserver` sans centre servait le tunnel de Fun Galaxy Libramont, marque,
// telephone et adresse mail compris (mesure en production, 2026-09-18). Un
// visiteur qui arrive la n a rien demande a ce centre, et une integration qui
// oublie `data-center` dans embed.js lui faisait meme afficher les PRIX d un
// autre client.
//
// L entree est retenue au PREMIER appel, comme le slug juste au-dessus :
// l application reecrit l adresse (`/reserver/gembloux` devient `/reserver`),
// donc relire le chemin plus tard ferait basculer sur la demonstration un
// visiteur venu avec son centre.
const PUBLIC_DEMO_CENTER_ID = 'demo';
let publicEntreeSansCentre;
function ouvertSurLeTunnelSansCentre() {
  if (publicEntreeSansCentre !== undefined) return publicEntreeSansCentre;
  publicEntreeSansCentre = false;
  try {
    const chemin = String(window.location.pathname || '').toLowerCase().replace(/\/+$/, '');
    publicEntreeSansCentre = chemin === '/reserver';
  } catch (error) {
    publicEntreeSansCentre = false;
  }
  return publicEntreeSansCentre;
}

// Le centre du TUNNEL (catalogue, horaires, creneaux, POST de reservation).
// L'URL fait autorite quand elle porte un centre ; sinon, `/reserver` ouvert
// sans session sert la demonstration, et tout le reste garde le centre de la
// session staff, qui est ce que le tunnel interne utilise.
function getTunnelCenterId() {
  const deLAdresse = getUrlCenterId();
  if (deLAdresse) return deLAdresse;
  // Une session staff annule la demonstration : un membre de l equipe qui
  // clique « Réserver » veut voir SON centre, pas la vitrine du produit.
  const connecte = typeof hasSavedAuth === 'function' && hasSavedAuth();
  if (!connecte && ouvertSurLeTunnelSansCentre()) return PUBLIC_DEMO_CENTER_ID;
  return getCurrentStaffCenterId();
}

function getCurrentStaffCenterId() {
  const normalized = normalizeStaffCenterId(state?.adminCenterId);
  if (state?.adminCenterId && state.adminCenterId !== normalized) {
    state.adminCenterId = normalized;
    save();
  }
  return normalized;
}

function getStaffSessionToken() {
  if (window.PinlaneStaffAuthSession?.getToken) {
    const token = window.PinlaneStaffAuthSession.getToken(state?.staffAuthSession);
    if (token) return token;
  }
  const session = state?.staffAuthSession;
  if (session?.cookieBacked) return '';
  if (session?.token && (!session.expiresAt || new Date(session.expiresAt).getTime() > Date.now())) {
    return session.token;
  }
  try {
    const parsed = window.PinlaneStorage?.getJson
      ? window.PinlaneStorage.getJson(AUTH_KEY, null)
      : JSON.parse(localStorage.getItem(AUTH_KEY) || 'null');
    if (!parsed?.token) return '';
    if (parsed.expiresAt && new Date(parsed.expiresAt).getTime() <= Date.now()) return '';
    return parsed.token;
  } catch (error) {
    return '';
  }
}

function isProtectedStaffApi(url = '') {
  if (window.PinlaneApiClient?.isProtectedStaffApi) {
    return window.PinlaneApiClient.isProtectedStaffApi(url);
  }
  const value = String(url || '');
  return [
    API_ENDPOINTS.staffAuth,
    API_ENDPOINTS.staffReservations,
    API_ENDPOINTS.staffState,
    API_ENDPOINTS.staffLanes,
    API_ENDPOINTS.adminRange,
    API_ENDPOINTS.ops,
    API_ENDPOINTS.simulation,
    API_ENDPOINTS.marketingAgents
  ].some(endpoint => endpoint && value.includes(endpoint));
}

function staffAuthHeaders(headers = {}) {
  const token = getStaffSessionToken();
  if (window.PinlaneApiClient?.staffAuthHeaders) {
    return window.PinlaneApiClient.staffAuthHeaders(headers, token);
  }
  return token ? { ...headers, 'X-Staff-Session': token } : headers;
}

async function apiRequest(url, options = {}) {
  if (window.PinlaneApiClient?.request) {
    return window.PinlaneApiClient.request(url, options, {
      getSessionToken: getStaffSessionToken,
      onUnauthorized: () => {
        if (typeof clearStaffAuthSession === 'function') clearStaffAuthSession();
        if (typeof applyAuthState === 'function') applyAuthState();
      },
      origin: window.location.origin
    });
  }
  const requestUrl = typeof url === 'string' && url.startsWith('/')
    ? `${window.location.origin}${url}`
    : url;
  const baseHeaders = {
    'Content-Type': 'application/json',
    ...(options.headers || {})
  };
  const headers = isProtectedStaffApi(url) ? staffAuthHeaders(baseHeaders) : baseHeaders;
  const response = await fetch(requestUrl, {
    ...options,
    cache: 'no-store',
    credentials: 'same-origin',
    headers
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok || payload.ok === false) {
    if (response.status === 401 && isProtectedStaffApi(url) && typeof clearStaffAuthSession === 'function') {
      clearStaffAuthSession();
      if (typeof applyAuthState === 'function') applyAuthState();
    }
    const error = new Error(payload.message || 'Erreur serveur.');
    error.payload = payload;
    error.status = response.status;
    error.url = requestUrl;
    throw error;
  }
  return payload;
}

// ── Telemetrie d'erreurs console (staff uniquement) ─────────────────────────
// Quand une erreur JS non rattrapee frappe la console d'un membre du staff,
// elle part vers logClientError : le fondateur la voit dans Plateforme >
// Incidents AVANT qu'on la lui signale. Contraintes non negociables :
// jamais de reentrance (une erreur du rapporteur ne se rapporte pas), dedupe
// locale, plafond par session d'onglet, et echec toujours silencieux.
const CLIENT_ERROR_REPORT = { seen: new Set(), sent: 0, max: 10, busy: false };
function reportClientError(payload) {
  if (CLIENT_ERROR_REPORT.busy || CLIENT_ERROR_REPORT.sent >= CLIENT_ERROR_REPORT.max) return;
  if (typeof getStaffSessionToken !== 'function' || !getStaffSessionToken()) return;
  const message = String(payload.message || '').slice(0, 500);
  if (!message) return;
  const key = `${message}|${payload.source || ''}|${payload.lineno || 0}`;
  if (CLIENT_ERROR_REPORT.seen.has(key)) return;
  CLIENT_ERROR_REPORT.seen.add(key);
  CLIENT_ERROR_REPORT.sent += 1;
  CLIENT_ERROR_REPORT.busy = true;
  try {
    apiRequest('/api/ops?action=logClientError', {
      method: 'POST',
      body: JSON.stringify({
        action: 'logClientError',
        page: typeof getStaffMenuPage === 'function' ? getStaffMenuPage() : '',
        message,
        source: String(payload.source || '').slice(0, 300),
        lineno: Number(payload.lineno) || 0,
        colno: Number(payload.colno) || 0,
        stack: String(payload.stack || '').slice(0, 2000),
      }),
    }).catch(() => {}).finally(() => { CLIENT_ERROR_REPORT.busy = false; });
  } catch (error) {
    CLIENT_ERROR_REPORT.busy = false;
  }
}
window.addEventListener('error', (event) => {
  reportClientError({
    message: event.message,
    source: event.filename,
    lineno: event.lineno,
    colno: event.colno,
    stack: event.error && event.error.stack,
  });
});
window.addEventListener('unhandledrejection', (event) => {
  const reason = event.reason;
  reportClientError({
    message: (reason && reason.message) || String(reason || 'promesse rejetee'),
    source: 'unhandledrejection',
    stack: reason && reason.stack,
  });
});

function getRemoteSyncBaseDelay() {
  // Cadence de synchro serveur. Volontairement modérée : chaque tick interroge
  // la base (staff-state). À 1,2 s on générait ~72k requêtes/jour/onglet et on
  // saturait le quota de transfert Neon. 4 s reste largement temps réel pour un
  // planning (les requêtes conditionnelles renvoient 304 quasi vide si rien n'a
  // changé), tout en divisant la charge par ~3.
  // Le pouls (assets/ops-live.js) voit en deux secondes toute modification de
  // la journee affichee et relit aussitot ce planning : tant qu il vit, cette
  // lecture-ci n est plus qu un filet, espace a 15 s. S il se tait (erreur
  // reseau, onglet ouvert avant un deploiement), elle reprend ses 4 s.
  if (state.view === 'staff') return typeof window.pinlanePoulsVivant === 'function' && window.pinlanePoulsVivant() ? 15000 : 4000;
  if (state.view === 'admin') return 20000;
  return 20000;
}

function getRemoteSyncDelay() {
  const baseDelay = getRemoteSyncBaseDelay();
  const pauseRemaining = Math.max(0, remoteSyncPausedUntil - Date.now());
  if (pauseRemaining) return Math.max(baseDelay, pauseRemaining);
  if (!remoteSyncFailureCount) return baseDelay;
  return Math.min(60000, baseDelay * Math.pow(2, Math.min(remoteSyncFailureCount, 5)));
}

function getRemoteSyncErrorMessage(error) {
  return String(error?.message || error?.status || 'remote-sync-error');
}

function isStaticApiFailure(error) {
  const message = getRemoteSyncErrorMessage(error).toLowerCase();
  return Number(error?.status) === 404 || message.includes('file not found') || message.includes('not found');
}

function markRemoteSyncSuccess() {
  remoteSyncFailureCount = 0;
  remoteSyncPausedUntil = 0;
  remoteSyncLastFailure = '';
  remoteSyncDownSince = 0;
  updateRemoteSyncIndicator();
}

function markRemoteSyncFailure(error) {
  remoteSyncFailureCount += 1;
  remoteSyncLastFailure = getRemoteSyncErrorMessage(error);
  if (!remoteSyncDownSince) remoteSyncDownSince = Date.now();
  updateRemoteSyncIndicator();
  if (isStaticApiFailure(error)) {
    remoteSyncPausedUntil = Date.now() + 5 * 60 * 1000;
    return;
  }
  if (remoteSyncFailureCount >= 3) {
    remoteSyncPausedUntil = Date.now() + Math.min(2 * 60 * 1000, 15000 * remoteSyncFailureCount);
  }
}

// Signal de panne du poll temps réel (pill du dashboard staff) : dégradé
// discret dès 2 échecs consécutifs, données déclarées périmées dès 6 échecs
// (le backoff espace alors les tentatives), retour auto au vert au succès.
function getRemoteSyncIndicator() {
  if (remoteSyncFailureCount >= 6) {
    const since = new Date(remoteSyncDownSince || Date.now()).toLocaleTimeString('fr-BE', { hour: '2-digit', minute: '2-digit' });
    return { tone: 'stale', label: `Données périmées depuis ${since}` };
  }
  if (remoteSyncFailureCount >= 2) return { tone: 'warning', label: 'Reconnexion…' };
  return { tone: 'live', label: 'Données en temps réel' };
}

function updateRemoteSyncIndicator() {
  const indicator = getRemoteSyncIndicator();
  // LA LISTE DU JOUR LE DIT AUSSI (2026-10-08) : le signal ne vivait que sur
  // l accueil, et la liste d a cote de la caisse pouvait rester figee sans
  // rien montrer. Rien quand tout va bien ; « Reconnexion… » puis « Données
  // périmées depuis 15:02 » sinon.
  const liste = document.getElementById('tableSyncState');
  if (liste) {
    const enPanne = indicator.tone !== 'live';
    if (liste.hidden === enPanne) liste.hidden = !enPanne;
    if (liste.textContent !== (enPanne ? indicator.label : '')) liste.textContent = enPanne ? indicator.label : '';
    liste.classList.toggle('is-stale', indicator.tone === 'stale');
  }
  const dot = document.querySelector('.dash-live-dot');
  if (!dot) return;
  dot.classList.toggle('warning', indicator.tone === 'warning');
  dot.classList.toggle('stale', indicator.tone === 'stale');
  const label = dot.nextElementSibling;
  if (label) label.textContent = indicator.label;
}

function escapeHtml(value = '') {
  return String(value ?? '').replace(/[&<>"']/g, char => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  }[char]));
}

function escapeJsString(value = '') {
  return String(value ?? '')
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\r?\n/g, ' ');
}

function formatOpsTimestamp(value) {
  if (!value) return 'Non planifié';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return 'Non planifié';
  return date.toLocaleString('fr-BE', {
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit'
  });
}

function getOpsTemplateLabel(templateId = '') {
  const id = String(templateId || '');
  // Les 13 modèles réellement envoyés en prod. Sans entrée ici, la colonne
  // « Modèle » affichait l'identifiant technique brut (`delay_staff_attention`)
  // à la directrice.
  const labels = {
    request_received: 'Demande reçue',
    confirmation: 'Confirmation client',
    reminder_48h: 'Rappel avant la venue',
    reminder_day_sms: 'Rappel SMS du jour',
    post_visit_followup: 'Merci post-visite',
    // « J-30 » est du jargon de marketeur : illisible pour une gerante, et il
    // s'affiche dans la colonne « Modele » de la file, sur l'ecran Emails.
    birthday_j30: 'Rappel anniversaire',
    reactivation: 'Réactivation dormants',
    relance_dormant: 'Relance client',
    staff_review_request: 'Réservation à valider',
    staff_alert: 'Alerte staff',
    delay_staff_attention: 'Retard : décision staff',
    delay_update: 'Ajustement horaire client',
    delay_change: 'Changement annoncé au client',
    client_thanks: 'Remerciement client',
    campaign_1: 'Campagne',
    studio_direct: 'Message direct',
    inbound_email: 'Mail reçu'
  };
  if (labels[id]) return labels[id];
  // Envois de test du staff : `test_<séquence>`.
  if (id.startsWith('test_')) return `Test : ${labels[id.slice(5)] || id.slice(5)}`;
  // Familles à suffixe variable : sans ces retombées, la colonne « Modèle »
  // montrait l'identifiant technique brut (`campaign_3`, `client_confirmation`)
  // à la directrice, surtout visible depuis la vue « Envois manuels ».
  if (id.startsWith('campaign_')) return 'Campagne';
  if (id.startsWith('studio_')) return 'Message direct';
  if (id.startsWith('relance_')) return 'Relance client';
  if (id.startsWith('client_')) return 'Message client';
  if (id.startsWith('custom_')) return 'Séquence personnalisée';
  return id || 'Message';
}

/* ── Pourquoi un mail n'est pas parti, en français ─────────────────────────
   `last_error` est le message brut du fournisseur, en anglais et écrit pour un
   développeur. Tel quel, il ne dit pas à la directrice ce qu'elle doit FAIRE.
   Chaque entrée traduit la cause ET donne le geste de réparation. Le message
   brut reste affiché en dessous : on traduit, on ne cache pas.
   ─────────────────────────────────────────────────────────────────────── */
const STAFF_EMAIL_FAILURE_RULES = [
  {
    match: /only send testing emails to your own email address|verify a domain/i,
    label: 'Domaine d\'envoi pas encore vérifié',
    fix: 'Le compte d\'envoi est en mode test : il n\'accepte que l\'adresse du propriétaire du compte. Tant que le domaine du centre n\'est pas vérifié chez le fournisseur, aucun mail ne peut partir vers un client.'
  },
  {
    match: /invalid `?to`? field|invalid recipient|no recipients|destinataire manquant/i,
    label: 'Adresse email du client invalide',
    fix: 'L\'adresse enregistrée sur la réservation n\'est pas une adresse valide (faute de frappe, champ vide). Corrigez-la sur la fiche client, puis renvoyez.'
  },
  {
    match: /rate limit|too many requests|429/i,
    label: 'Trop d\'envois d\'un coup',
    fix: 'Le fournisseur a bridé le rythme d\'envoi. Les mails repartent d\'eux-mêmes un peu plus tard ; vous pouvez aussi renvoyer manuellement.'
  },
  {
    match: /api[_ ]?key|unauthorized|401|403|forbidden/i,
    label: 'Clé d\'envoi refusée',
    fix: 'La clé du service d\'envoi est absente, expirée ou révoquée. C\'est un réglage technique : rien ne partira tant qu\'elle n\'est pas remise en place.'
  },
  {
    match: /bounce|mailbox (not found|unavailable)|does not exist|550/i,
    label: 'Boîte du client inexistante',
    fix: 'Le serveur du client a refusé le message : l\'adresse n\'existe plus. Demandez la bonne adresse avant de renvoyer.'
  },
  {
    match: /timeout|ETIMEDOUT|ECONNRESET|ENOTFOUND|network|fetch failed/i,
    label: 'Le service d\'envoi n\'a pas répondu',
    fix: 'Incident réseau passager côté fournisseur. Un renvoi suffit en général.'
  },
  {
    match: /configuration|manquant|non configur/i,
    label: 'Canal pas configuré',
    fix: 'Le canal (email ou SMS) n\'a pas de configuration valide sur ce centre.'
  }
];

function getStaffEmailFailureReason(row = {}) {
  const raw = String(row.lastError || '').trim();
  if (!raw) {
    return { label: 'Cause inconnue', fix: 'Le fournisseur n\'a pas donné de raison. Renvoyez le message : si l\'échec se répète, la cause sera enregistrée.', raw: '' };
  }
  const rule = STAFF_EMAIL_FAILURE_RULES.find(entry => entry.match.test(raw));
  if (rule) return { label: rule.label, fix: rule.fix, raw };
  return { label: 'Échec d\'envoi', fix: 'Message renvoyé par le service d\'envoi, texte d\'origine ci-dessous.', raw };
}

// Échecs regroupés par cause, la plus fréquente d'abord. Agrégé côté client sur
// les lignes déjà chargées : aucune requête ni permission supplémentaire.
function getStaffEmailFailureGroups(rows = []) {
  const groups = new Map();
  rows.filter(row => row.statusKind === 'failed').forEach(row => {
    const reason = getStaffEmailFailureReason(row);
    const entry = groups.get(reason.label) || { label: reason.label, fix: reason.fix, count: 0, raw: reason.raw };
    entry.count += 1;
    groups.set(reason.label, entry);
  });
  return [...groups.values()].sort((a, b) => b.count - a.count);
}

// Liste des centres SCOPEE au tenant (action ops=menuCenters, filtree serveur).
// C'est la SOURCE de verite du switcher de centre et des cartes centre : un
// client n'y voit que ses centres, le proprietaire (owner=true) tous les
// centres avec clientId/clientName pour les grouper. Tant qu'elle n'est pas
// chargee, on retombe sur knowledge.centers (deja scope serveur) puis sur les
// replis statiques : aucune de ces sources ne provient d'un autre tenant.
let scopedCentersCache = { loaded: false, loading: false, error: '', centers: [], owner: false };

async function loadMenuCenters(force = false) {
  if (scopedCentersCache.loading) return;
  if (scopedCentersCache.loaded && !force) return;
  if (!hasSavedAuth()) return;
  scopedCentersCache.loading = true;
  try {
    const response = await apiRequest(`${API_ENDPOINTS.ops}?action=menuCenters`);
    scopedCentersCache = {
      loaded: true,
      loading: false,
      error: '',
      centers: Array.isArray(response.centers) ? response.centers : [],
      owner: !!response.owner
    };
    if (typeof window.renderStaffMenu === 'function') window.renderStaffMenu();
  } catch (error) {
    scopedCentersCache.loading = false;
    scopedCentersCache.error = error?.message || 'Lecture des centres impossible.';
  }
}
if (typeof window !== 'undefined') window.loadMenuCenters = loadMenuCenters;

// ---- CHANGER DE CENTRE, C'EST TOUT RECHARGER -------------------------------
//
// Un cache qui survit à la bascule affiche les chiffres du centre précédent
// sous le nom du nouveau : c'est le pire des états, parce qu'il est crédible.
// Certains de ces caches portent une clé qui contient le centre et se
// rechargent seuls ; d'autres n'en ont AUCUNE (opsAdminCache,
// adminDashboardCache, la config d'établissement, les blocs de disponibilité,
// les séries du jour) et gardaient indéfiniment les données du centre quitté.
// La fuite la plus fine était `knowledge` : loadAdminDashboard le reprenait du
// cache précédent quand l'instantané du nouveau centre n'en portait pas, et
// c'est lui qui nomme les centres et décrit leurs ressources.
//
// On ne les met pas à jour : on les VIDE. Tous les écrans appellent leur
// load*(false) au rendu, donc vider suffit à déclencher un vrai chargement, et
// l'écran montre son état de chargement au lieu d'anciens chiffres.
//
// Ce qui n'est PAS vidé : scopedCentersCache (la liste des centres du tenant ne
// dépend pas du centre choisi) et la session.
function resetCenterScopedCaches() {
  opsAdminCache = {
    communications: [], samples: [], suggestions: [], events: [],
    agentStack: null, opsHealth: null, simulation: null,
    loaded: false, loading: false, lastLoadedAt: ''
  };
  adminDashboardCache = {
    loading: false, loaded: false, error: '', snapshot: null, knowledge: null,
    communications: [], suggestions: [], events: [], samples: [],
    agentStack: null, opsHealth: null, simulation: null, lastLoadedAt: ''
  };
  adminSnapshotCache = {};
  adminSnapshotLoadingKeys = {};
  adminOpsCacheByCenter = {};
  adminOpsLoadingByCenter = {};
  opsAdminLastAutoLoadAt = 0;
  staffClientDataCache = { key: '', loading: false, loaded: false, error: '', reservations: [], syncedAt: '', loadedAt: 0 };
  staffReservationsDataCache = { key: '', loading: false, loaded: false, error: '', reservations: [], syncedAt: '', loadedAt: 0 };
  staffClientCommsCache = { key: '', loading: false, loaded: false, error: '', items: [], loadedAt: 0 };
  staffCustomRequestsCache = { key: '', loading: false, loaded: false, error: '', items: [], loadedAt: 0 };
  staffCenterConfigCache = { loaded: false, loading: false, error: '', centers: [], activities: [] };
  availabilityBlocksCache = { loaded: false, loading: false, error: '', blocks: [] };
  if (staffDaySeriesCache && typeof staffDaySeriesCache.clear === 'function') staffDaySeriesCache.clear();
  // LE CATALOGUE EFFECTIF du centre : les formules et les activites servies par
  // public-booking-meta. Sans cette remise a zero, le formulaire de reservation
  // de la console proposait le catalogue du centre PRECEDENT, et le repli
  // statique de booking-core (les 14 formules Fun Galaxy) reprenait la main.
  if (typeof window !== 'undefined') window.__pinlaneDisplayFormules = null;
  if (typeof setCenterActivities === 'function') setCenterActivities([]);
  // Le CATALOGUE TARIFAIRE de la console (page Tarifs & formules, onglet
  // Offres d'Etablissement) vit dans staff-pages-v2.js, charge apres ce
  // fichier : meme passage par la fonction qu'il expose. Sans cette ligne il
  // survivait a la bascule, et Fun Galaxy affichait les formules de N4 sous
  // son propre nom (capture Movsar, 2026-08-21). La base, elle, etait intacte.
  if (typeof window !== 'undefined' && typeof window.pevResetCatalogCache === 'function') window.pevResetCatalogCache();
  // Les trois caches de la Direction vivent dans admin-console.js, chargé après
  // ce fichier : on passe par la fonction qu'il expose plutôt que d'y toucher.
  if (typeof window !== 'undefined' && typeof window.resetDirectionCaches === 'function') window.resetDirectionCaches();
}
if (typeof window !== 'undefined') window.resetCenterScopedCaches = resetCenterScopedCaches;

function getScopedCenters() {
  return scopedCentersCache.loaded && scopedCentersCache.centers.length ? scopedCentersCache.centers : null;
}

// ---- LE CATALOGUE DU SOCLE N'APPARTIENT QU'AUX CENTRES DU SOCLE ------------
//
// booking-core.js porte les 14 formules de Fun Galaxy en dur (FORMULE 1,
// MATIN MALIN, HAPPY LASER AND GAME...). C'etait le repli de TOUT centre tant
// que le catalogue serveur n'avait pas repondu : la console de N4 proposait
// donc les formules de Fun Galaxy a la reservation, alors que N4 en a quatre a
// lui. Un repli qui montre le catalogue d'un autre client n'est pas un repli,
// c'est une fuite d'affichage.
//
// Ce repli reste legitime pour les centres du FICHIER (libramont, gembloux,
// ciney) : ces formules SONT les leurs. Pour tout autre centre, tant que le
// serveur n'a pas repondu, la bonne reponse est « rien » : une liste vide se
// corrige a la seconde suivante, un catalogue etranger se vend au telephone.
const FILE_SEED_CENTER_IDS = ['libramont', 'gembloux', 'ciney'];

function getEffectiveCatalogFormules() {
  const served = Array.isArray(window.__pinlaneDisplayFormules) ? window.__pinlaneDisplayFormules : null;
  if (served && served.length) return served;
  if (served) return []; // le serveur a repondu « aucune formule » : on le dit
  // getTunnelCenterId, pas le centre staff : dans le tunnel public l'adresse
  // fait autorite, et c'est le seul endroit ou les deux peuvent diverger.
  const centerId = typeof getTunnelCenterId === 'function' ? getTunnelCenterId() : getActiveOpsCenterId();
  return FILE_SEED_CENTER_IDS.includes(centerId) ? FORMULES : [];
}
if (typeof window !== 'undefined') window.getEffectiveCatalogFormules = getEffectiveCatalogFormules;

function isCenterScopeOwner() {
  return !!scopedCentersCache.owner;
}

function getAdminCenters() {
  // Repli statique = SEULEMENT le centre courant de la session (jamais la liste
  // codee en dur des 3 centres Fun Galaxy). Fun Galaxy y retrouve son centre
  // avec ses ressources ; un autre tenant obtient une liste vide plutot que les
  // noms Fun Galaxy en flash avant que la liste scopee serveur reponde.
  return getScopedCenters()
    || (adminDashboardCache.knowledge?.centers?.length
      ? adminDashboardCache.knowledge.centers
      : ADMIN_CENTER_FALLBACKS.filter(center => center.id === state.adminCenterId));
}

function getAdminCenter(centerId = state.adminCenterId) {
  // Repli NEUTRE pour un centre inconnu de toute liste : jamais la fiche du
  // premier client (un centre X recevait le nom et les ressources de Fun
  // Galaxy Libramont le temps que sa liste scopee reponde).
  return getAdminCenters().find(center => center.id === centerId)
    || ADMIN_CENTER_FALLBACKS.find(center => center.id === centerId)
    || { id: centerId || '', name: '', status: 'active', resources: {} };
}

// Le NOM du centre courant pour les surfaces staff (objets d'email, exports).
// Vide tant qu'aucune liste ne l'a donne : un libelle neutre vaut mieux que
// le nom d'un autre client.
function getCurrentStaffCenterName() {
  const center = getAdminCenter();
  return String((center && center.name) || '').trim();
}

function getActiveOpsCenterId() {
  return state.adminCenterId || 'libramont';
}

// UN MONTANT EST UN SEUL MOT. L espace ordinaire qui separait le nombre du
// symbole autorisait le navigateur a couper la ligne entre les deux : sur la
// liste du jour en 1440 (« piste 3, 5 · 308 » puis « € » seul en dessous) et
// sur quatre montants du mobile 390, le symbole partait a la ligne suivante et
// le chiffre le plus regarde de la ligne se relisait deux fois. U+202F est
// l espace fine INSECABLE : meme typographie francaise, coupure impossible.
// Un montant au centime (« 9,33 € »), entier quand il l est (« 26 € »).
function formatMoneyCentimes(value) {
  const amount = Math.round((Number(value) || 0) * 100) / 100;
  const entier = Number.isInteger(amount);
  return `${new Intl.NumberFormat('fr-BE', { minimumFractionDigits: entier ? 0 : 2, maximumFractionDigits: 2 }).format(amount)} €`;
}

function formatMoney(value) {
  const amount = Math.round(Number(value) || 0);
  return `${new Intl.NumberFormat('fr-BE', { maximumFractionDigits: 0 }).format(amount)} €`;
}

function formatAdminPercent(value) {
  const safe = Number.isFinite(Number(value)) ? Number(value) : 0;
  return `${Math.max(0, Math.round(safe))}%`;
}

function startOfWeek(dateStr) {
  const d = parseLocalDate(dateStr);
  const day = d.getDay();
  const diff = day === 0 ? -6 : 1 - day;
  d.setDate(d.getDate() + diff);
  return toLocalDateStr(d);
}

function startOfMonth(dateStr) {
  const d = parseLocalDate(dateStr);
  d.setDate(1);
  return toLocalDateStr(d);
}

function endOfMonth(dateStr) {
  const d = parseLocalDate(dateStr);
  d.setMonth(d.getMonth() + 1, 0);
  return toLocalDateStr(d);
}

function startOfYear(dateStr) {
  const d = parseLocalDate(dateStr);
  d.setMonth(0, 1);
  return toLocalDateStr(d);
}

function endOfYear(dateStr) {
  const d = parseLocalDate(dateStr);
  d.setMonth(11, 31);
  return toLocalDateStr(d);
}

function getDateRangeDays(startDate, endDate) {
  const days = [];
  let cursor = startDate;
  while (cursor <= endDate && days.length < 370) {
    days.push(cursor);
    cursor = addDays(cursor, 1);
  }
  return days;
}

// Direction/admin console renderers live in ./assets/admin-console.js.
// Ops communications, agent stack and simulation renderers live in ./assets/ops-console.js.
// Au-dela, une lecture de la journee est abandonnee : la boucle reessaie.
const STAFF_SYNC_TIMEOUT_MS = 15000;

// LA FICHE OUVERTE SUIT LE SERVEUR ET L HEURE (2026-10-08). Le poll
// rafraichissait selectedRes (hydrateSelectedReservation) sans jamais
// redessiner la fiche : un autre poste pointait « Arrivé », la liste disait
// « Sur place » et la fiche ouverte « À venir », et son bouton « Arrivé »
// sortait sans rien dire. Elle se redessine quand ce qu elle montre a change
// depuis sa derniere peinture (le dossier et son mot), sauf pendant une
// saisie : onglet Modifier, ou un champ de la fiche qui a le focus. Elle
// rattrape au tour suivant.
let ficheFaitsPeints = '';
function getFicheFaitsSignature() {
  const r = state.selectedRes;
  return r ? JSON.stringify([reservationRenderSignature(r), getStaffDashboardStatusMeta(r).label]) : '';
}
function repeindreFicheSiChangee() {
  const overlay = document.getElementById('posOverlay');
  if (!state.selectedRes || !overlay || overlay.classList.contains('hidden')) return false;
  if (state.activeTab === 'modifier') return false;
  if (getFicheFaitsSignature() === ficheFaitsPeints) return false;
  const actif = document.activeElement;
  if (actif && overlay.contains(actif) && actif.matches('input, textarea, select, [contenteditable="true"]')) return false;
  renderPos();
  return true;
}

async function syncDateReservations(dateStr, opts = {}) {
  if (!dateStr) return false;
  // UNE JOURNEE DEMANDEE PENDANT UNE LECTURE EN VOL N EST PLUS PERDUE
  // (campagne du 2026-09-29). Elle etait abandonnee en silence : deux clics
  // sur « jour suivant », et le second jour restait sans ses dossiers jusqu au
  // tour suivant de la boucle (4 s mesurees sur le banc, 15 s quand le pouls
  // vit) ; un changement de centre gardait le planning de l ancien. Elle part
  // des que la lecture courante rend la main, et qui l attend recoit sa vraie
  // reponse. Rendu et toast : il suffit qu un demandeur les veuille.
  if (remoteSyncBusy) {
    const deja = remoteSyncEnAttente.get(dateStr);
    const attente = deja || { opts: { ...opts }, resolveurs: [] };
    if (deja) {
      attente.opts.silent = Boolean(deja.opts.silent && opts.silent);
      attente.opts.skipRender = Boolean(deja.opts.skipRender && opts.skipRender);
    }
    remoteSyncEnAttente.set(dateStr, attente);
    return new Promise((resolve) => attente.resolveurs.push(resolve));
  }
  // Le parcours public n'a pas de session staff : staff-state repondrait 401
  // (vu en prod au changement de date du tunnel). Meme regle que la boucle de
  // sync (plus bas) : en vue client sans session, on ne demande rien.
  if (state.view === 'client' && !hasSavedAuth()) return false;
  remoteSyncBusy = true;
  // UNE LECTURE QUI NE REPOND PAS NE FIGE PLUS LA JOURNEE (2026-10-08). Sans
  // delai, un fetch pendu (wifi du centre) gardait remoteSyncBusy : la boucle,
  // le reveil de la tablette et les clics attendaient en file, et la liste
  // restait figee sans le dire.
  const delaiLecture = new AbortController();
  const minuteurLecture = setTimeout(() => delaiLecture.abort(), STAFF_SYNC_TIMEOUT_MS);
  try {
    const beforeData = state.view === 'staff' && state.currentDate === dateStr ? getStaffDataSignature(dateStr) : '';
    const centerId = encodeURIComponent(getCurrentStaffCenterId());
    const revisionKey = `${centerId}:${dateStr}`;
    const knownRevision = staffRevisionByDate[revisionKey];
    const syncHeaders = staffAuthHeaders(knownRevision ? { 'If-None-Match': knownRevision } : {});
    const response = await fetch(`${API_ENDPOINTS.staffState}?date=${encodeURIComponent(dateStr)}&centerId=${centerId}`, {
      cache: 'no-store',
      headers: syncHeaders,
      signal: delaiLecture.signal
    });
    // Le centre a change pendant la lecture : cette reponse est celle de
    // l ancien, elle ne remplace pas la journee du nouveau, relue juste apres.
    if (encodeURIComponent(getCurrentStaffCenterId()) !== centerId) {
      if (!remoteSyncEnAttente.has(dateStr)) remoteSyncEnAttente.set(dateStr, { opts: { ...opts }, resolveurs: [] });
      return false;
    }
    if (response.status === 304) {
      staffSyncAtByDate[revisionKey] = Date.now();
      markRemoteSyncSuccess();
      return false;
    }
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || payload.ok === false) {
      const error = new Error(payload.message || 'Erreur serveur.');
      error.status = response.status;
      throw error;
    }
    // LE MODE SECOURS N EST PAS UNE JOURNEE VIDE (2026-10-08). Base
    // indisponible, staff-state repond 200 avec `reservations: []` et
    // `degraded: true` : la console effacait la journee et fermait la fiche
    // ouverte. C est une panne : on garde ce qu on a, et on le dit.
    if (payload.degraded) {
      const error = new Error(payload.storageMessage || 'Données temps réel temporairement indisponibles.');
      error.status = 503;
      throw error;
    }
    const nextRevision = response.headers.get('ETag') || payload.revision || '';
    const changed = nextRevision !== knownRevision;
    // Baseline connu (pas le 1er sync) + IDs déjà en mémoire AVANT remplacement :
    // sert à repérer les résas réellement nouvelles venues du serveur.
    const hadBaseline = Boolean(knownRevision);
    const beforeResIds = new Set(state.reservations.filter(r => r.date === dateStr).map(r => r.id));
    staffSyncAtByDate[revisionKey] = Date.now();
    const masque = replaceReservationsForDate(dateStr, payload.reservations || []);
    memoriserBlocagesEnLigne(getCurrentStaffCenterId(), dateStr, payload.holds);
    if (payload.laneStatuses) state.laneStatuses = payload.laneStatuses;
    if (payload.laneMaintenance) state.laneMaintenance = payload.laneMaintenance;
    // Classification client/groupe du centre (seuils groupe + formules annif),
    // servie par le poll : pilote isGroup/hasBirthday/tiers côté Clients & Groupes.
    if (payload.classification) state.staffClassification = payload.classification;
    // Le seuil de retard du centre (Etablissement > Regles), meme chemin.
    if (payload.accueil) state.staffAccueil = payload.accueil;
    hydrateSelectedReservation();
    save();
    // LA REVISION SE RETIENT APRES LE RENDU, ET SEULEMENT SI L ECRAN MONTRE LA
    // VERSION DU SERVEUR (2026-10-08). Retenue avant, un rendu qui plantait
    // (compte comme une panne reseau) laissait la journee a moitie dessinee,
    // et les 304 suivants ne la redessinaient plus jamais. Une ecriture
    // locale encore en vol qui masquait la valeur d un autre poste (la garde
    // de 9 s) faisait pareil : la valeur ecrasee, puis 304 jusqu au prochain
    // changement. Dans ces deux cas la lecture suivante redemande tout.
    // La lecture d avant n a pas ete montree (rendu plante, valeur masquee) :
    // la journee en memoire est deja la bonne, avant et apres se ressemblent,
    // il faut redessiner quand meme.
    const aMontrer = String(knownRevision || '').startsWith('a-relire:');
    let rendu = true;
    try {
      if (!opts.skipRender && changed && state.view === 'staff' && state.currentDate === dateStr) {
        const afterData = getStaffDataSignature(dateStr);
        if (beforeData !== afterData || aMontrer) renderStaffData();
      }
      if (!opts.skipRender) repeindreFicheSiChangee();
    } catch (erreurRendu) {
      rendu = false;
      console.error('[sync] rendu de la journée', erreurRendu);
    }
    staffRevisionByDate[revisionKey] = masque || !rendu ? `a-relire:${nextRevision}` : nextRevision;
    // La fenetre Reserver ouverte sur cette journee refait son plan : un
    // autre poste vient peut-etre de prendre la place qu elle annoncait.
    if (changed && typeof rvJourneeChangee === 'function') rvJourneeChangee(dateStr);
    // Notif + son pour toute NOUVELLE réservation du jour même reçue du serveur
    // (site public / autre poste). Les créations locales sont déjà dans l'état
    // avant le poll → jamais notifiées ici. Skip au 1er sync (baseline).
    if (changed && hadBaseline && state.view === 'staff' && dateStr === todayStr()) {
      const arrivees = (payload.reservations || [])
        .filter(r => r && !beforeResIds.has(r.id) && r.status !== 'cancelled' && r.status !== 'rejected');
      // On MARQUE avant de re-rendre : sinon la ligne et le bloc du planning se
      // dessinent sans leur signal et l'arrivee passe inapercue jusqu'au poll
      // suivant.
      if (arrivees.length && typeof PinlaneMotion !== 'undefined') {
        PinlaneMotion.marquerNeuves(arrivees.map(r => r.id));
        if (state.currentDate === dateStr && !opts.skipRender) renderStaffData();
      }
      arrivees.forEach(r => notifyNewReservation(r));
    }
    markRemoteSyncSuccess();
    return changed;
  } catch (error) {
    markRemoteSyncFailure(error);
    if (!opts.silent) toast(error.name === 'AbortError' ? 'Le serveur ne répond pas. Nouvel essai dans quelques secondes.' : (error.message || 'Synchronisation impossible.'));
    return false;
  } finally {
    clearTimeout(minuteurLecture);
    remoteSyncBusy = false;
    relancerLaJourneeEnAttente();
  }
}

// La journee affichee passe d abord : c est celle que la personne regarde.
function relancerLaJourneeEnAttente() {
  if (!remoteSyncEnAttente.size) return;
  const dates = [...remoteSyncEnAttente.keys()];
  const suivante = dates.includes(state.currentDate) ? state.currentDate : dates[0];
  const { opts, resolveurs } = remoteSyncEnAttente.get(suivante);
  remoteSyncEnAttente.delete(suivante);
  syncDateReservations(suivante, opts).catch(() => false).then((resultat) => resolveurs.forEach((resolve) => resolve(resultat)));
}

// ── LE DIRECT : UNE MODIFICATION FAITE AILLEURS EST VUE ICI (2026-09-25) ──────
//
// Movsar : « plusieurs ecrans, plusieurs PC, plusieurs personnes : si quelqu un
// fait une modif, peu importe ce que c est, tout le monde doit le voir en
// instantane ». assets/ops-live.js lit le pouls toutes les deux secondes (une
// empreinte par domaine, lib/database.js getOpsPulse) et, pour les domaines
// qui ont bouge, appelle d abord invalidateLiveSyncCaches, puis, si personne
// n ecrit, la page affichee (getLiveSyncPages). Ce bloc dit, pour chaque cache
// de la console, quels domaines il montre et sur quelles pages :
//   - affiche, il est RELU par la page, qui garde ce qu elle montre pendant la
//     lecture (pas d ecran vide, pas de squelette qui clignote) ;
//   - ailleurs, il est OUBLIE et se relira quand sa page s ouvrira : rien
//     n est demande au serveur pour un ecran que personne ne regarde.
// Ce que la barre laterale montre sur toutes les pages (demandes en attente,
// centres, droits de la personne connectee) est relu quelle que soit la page.
const LIVE_SYNC_DOMAINES = ['communications', 'suggestions', 'evenements', 'prises', 'reservations', 'jour', 'pistes', 'blocages', 'demandes', 'catalogue', 'config', 'equipe', 'notes', 'courrier'];
// La journee affichee (ses reservations et ses pistes, servies ensemble par
// staff-state) et les pages qui la montrent.
const LIVE_SYNC_JOURNEE = ['jour', 'pistes'];
const LIVE_SYNC_PAGES_JOURNEE = ['dashboard', 'planning', 'arrivals', 'formules', 'lanes', 'laserGame', 'settings'];

// « jour:2026-09-25 » est de la famille « jour » ; « * » (un serveur d avant les
// domaines) vaut tous les domaines.
function liveSyncFamilles(changes) {
  const familles = new Set();
  (Array.isArray(changes) ? changes : []).forEach((nom) => {
    const texte = String(nom || '');
    if (texte === '*') { LIVE_SYNC_DOMAINES.forEach((domaine) => familles.add(domaine)); return; }
    familles.add(texte.includes(':') ? texte.slice(0, texte.indexOf(':')) : texte);
  });
  return familles;
}

function getLiveSyncPageName() {
  return state.view === 'staff' && hasSavedAuth() ? getStaffMenuPage() : '';
}

function getLiveSyncDate() {
  return state.view === 'staff' ? String(state.currentDate || '') : '';
}

// Les caches de la console. `enCours` : une lecture partie AVANT le changement
// rendrait l ancien etat ; la page attend qu elle revienne (le pouls repasse
// deux secondes plus tard) au lieu de la doubler.
function getLiveSyncCaches() {
  return [
    {
      domaines: ['reservations', 'jour'], pages: ['reservations'],
      enCours: () => staffReservationsDataCache.loading,
      oublier: () => { staffReservationsDataCache = { key: '', loading: false, loaded: false, error: '', reservations: [], syncedAt: '', loadedAt: 0 }; },
      relire: () => loadStaffReservationsData(true),
    },
    {
      domaines: ['reservations'], pages: ['clients', 'groups', 'contacts', 'prices', 'campaigns'],
      enCours: () => staffClientDataCache.loading,
      oublier: () => { staffClientDataCache = { key: '', loading: false, loaded: false, error: '', reservations: [], syncedAt: '', loadedAt: 0 }; },
      relire: () => loadStaffClientData(true),
    },
    {
      domaines: ['communications'], pages: ['clients', 'groups'],
      enCours: () => staffClientCommsCache.loading,
      oublier: () => { staffClientCommsCache = { key: '', loading: false, loaded: false, error: '', items: [], loadedAt: 0 }; },
      relire: () => loadStaffClientComms(true),
    },
    {
      // Le badge « demandes » de la barre laterale est sur toutes les pages.
      // Un mail recu peut remettre une demande a traiter (le client a
      // repondu) : la file se relit aussi sur « communications ».
      domaines: ['demandes', 'communications'], partout: true,
      enCours: () => staffCustomRequestsCache.loading,
      relire: () => loadStaffCustomRequests(true),
    },
    {
      // Le fil de la demande ouverte : un mail parti ou recu s y lit aussitot.
      domaines: ['communications'], pages: ['requests'],
      enCours: () => { const item = getStaffRequestSelectedItem(); const fil = item ? staffRequestThreads[String(item.id)] : null; return Boolean(fil && fil.loading); },
      oublier: () => { staffRequestThreads = {}; },
      relire: () => { const item = getStaffRequestSelectedItem(); if (item) loadStaffRequestThread(item.id, true); },
    },
    {
      // L etude du dossier ouvert suit le planning, les fermetures et la
      // configuration : elle devient « a relire », et se relit au rendu.
      domaines: ['reservations', 'blocages', 'config'], pages: ['requests'],
      enCours: () => { const item = getStaffRequestSelectedItem(); const etude = item ? staffRequestStudies[String(item.id)] : null; return Boolean(etude && etude.loading); },
      oublier: () => markStaffRequestStudiesStale(),
      relire: () => { markStaffRequestStudiesStale(); renderStaffRequestsIfOpen(); },
    },
    {
      // La page Secours relit ses derniers envois quand la journee ou la
      // configuration change.
      domaines: ['reservations', 'config'], pages: ['secours'],
      enCours: () => secoursEtatCache.loading,
      oublier: () => { secoursEtatCache = { ...secoursEtatCache, loaded: false }; },
      relire: () => loadSecoursEtat(true),
    },
    {
      domaines: ['blocages'], pages: ['planning', 'laserGame', 'establishment'],
      enCours: () => availabilityBlocksCache.loading,
      oublier: () => { availabilityBlocksCache = { loaded: false, loading: false, error: '', blocks: [] }; },
      relire: () => loadAvailabilityBlocks(true),
    },
    {
      domaines: ['config'], pages: ['dashboard', 'planning', 'arrivals', 'formules', 'lanes', 'laserGame', 'establishment'],
      enCours: () => staffCenterConfigCache.loading,
      oublier: () => { staffCenterConfigCache = { loaded: false, loading: false, error: '', centers: [], activities: [] }; },
      relire: () => loadStaffCenterConfig(true),
    },
    {
      // Les noms et l etat des centres, dans le selecteur de la barre laterale.
      domaines: ['config'], partout: true,
      enCours: () => scopedCentersCache.loading,
      relire: () => loadMenuCenters(true),
    },
    {
      // Le catalogue et les horaires servis au tiroir de reservation rapide,
      // ouvrable depuis toutes les pages.
      domaines: ['catalogue', 'config'], partout: true,
      enCours: () => false,
      relire: () => loadCenterScheduleConfig(),
    },
    {
      domaines: ['equipe'], partout: true,
      enCours: () => false,
      relire: () => refreshStaffAccessForLiveSync(),
    },
    {
      // La boite de l accueil : l heure de lecture seule est remise a zero, ce
      // qu elle montre reste affiche pendant la relecture.
      domaines: ['communications', 'courrier'], pages: ['dashboard'],
      enCours: () => dashInbox.loading,
      oublier: () => { dashInbox.at = 0; },
      relire: () => { dashInbox.at = 0; ensureDashInbox(); },
    },
    {
      domaines: ['reservations'], pages: ['dashboard'],
      enCours: () => false,
      oublier: () => { staffDaySeriesCache.forEach((entry) => { entry.at = 0; }); },
      relire: () => {
        staffDaySeriesCache.forEach((entry) => { entry.at = 0; });
        ensureStaffDaySeries(addDays(state.currentDate, -Math.max(0, Number(state.dashRevenueOffset) || 0)));
      },
    },
    {
      domaines: ['communications', 'suggestions', 'evenements', 'prises', 'courrier'], pages: ['emails', 'establishment'],
      enCours: () => opsAdminCache.loading,
      oublier: () => { opsAdminLastAutoLoadAt = 0; opsAdminCache.loaded = false; },
      relire: () => {
        // La page Emails v4 lit aussi des conversations et une vue globale,
        // hors de la console : elle les relit elle-meme.
        if (isStaffEmailsActive() && typeof window.pv2EmailsSurSynchro === 'function') window.pv2EmailsSurSynchro();
        requestOpsAdminLoad(true);
      },
    },
  ];
}

function invalidateLiveSyncCaches(changes) {
  const familles = liveSyncFamilles(changes);
  const page = getLiveSyncPageName();
  getLiveSyncCaches().forEach((cache) => {
    if (cache.partout || !cache.domaines.some((domaine) => familles.has(domaine))) return;
    // Affiche, il est relu par la page, apres les gardes de saisie.
    if ((cache.pages || []).includes(page)) return;
    cache.oublier();
  });
  // Une autre date deja visitee n est plus « fraiche » : on la relira en y
  // allant, au lieu de la croire a jour.
  if (['jour', 'pistes', 'reservations'].some((domaine) => familles.has(domaine))) staffSyncAtByDate = {};
  if (typeof window.pv2Direct === 'function') window.pv2Direct(familles, page, false);
}

function rechargerLaPagePourLeDirect(page, changes) {
  const familles = liveSyncFamilles(changes);
  const concerne = (domaines) => domaines.some((domaine) => familles.has(domaine));
  const caches = getLiveSyncCaches().filter((cache) => concerne(cache.domaines) && (cache.partout || (cache.pages || []).includes(page)));
  const journee = LIVE_SYNC_PAGES_JOURNEE.includes(page) && concerne(LIVE_SYNC_JOURNEE);
  if (caches.some((cache) => cache.enCours()) || (journee && remoteSyncBusy)) return false;
  caches.forEach((cache) => cache.relire());
  if (journee) syncDateReservations(state.currentDate, { silent: true });
  if (typeof window.pv2Direct === 'function') window.pv2Direct(familles, page, true);
  return true;
}

// Chaque page du centre et ce qu elle montre. Les pages plateforme (cockpit)
// ne sont pas dans le pouls d un centre.
function getLiveSyncPages() {
  const caches = getLiveSyncCaches();
  const pages = {};
  STAFF_MENU_PAGES.forEach((page) => {
    if (page.startsWith('cockpit')) return;
    const domaines = new Set();
    caches.forEach((cache) => {
      if (cache.partout || (cache.pages || []).includes(page)) cache.domaines.forEach((domaine) => domaines.add(domaine));
    });
    if (LIVE_SYNC_PAGES_JOURNEE.includes(page)) LIVE_SYNC_JOURNEE.forEach((domaine) => domaines.add(domaine));
    // Les caches de staff-pages-v2 (catalogue tarifaire, notes, sequences,
    // campagnes) : pv2Direct les relit ; leurs domaines comptent pour la page.
    if (['prices', 'establishment'].includes(page)) { domaines.add('catalogue'); domaines.add('config'); }
    if (['clients', 'groups'].includes(page)) domaines.add('notes');
    if (['emails', 'campaigns'].includes(page)) { domaines.add('courrier'); domaines.add('config'); }
    pages[page] = {
      domaines: [...domaines],
      // Le formulaire d Etablissement garde sa saisie dans ses champs : on ne
      // le reconstruit pas tant qu il est ouvert.
      brouillon: page === 'establishment' ? () => Boolean(state.establishmentEditing) : undefined,
      recharger: (changes) => rechargerLaPagePourLeDirect(page, changes),
    };
  });
  return pages;
}

window.getLiveSyncPageName = getLiveSyncPageName;
window.getLiveSyncDate = getLiveSyncDate;
window.getLiveSyncPages = getLiveSyncPages;
window.invalidateLiveSyncCaches = invalidateLiveSyncCaches;

function scheduleRemoteSync() {
  clearTimeout(remoteSyncTimer);
  const delay = getRemoteSyncDelay();
  remoteSyncTimer = setTimeout(async () => {
    if (remoteSyncPausedUntil && Date.now() < remoteSyncPausedUntil) {
      scheduleRemoteSync();
      return;
    }
    // Onglet caché : on ne consomme AUCUN data transfer Neon (le timer reste armé
    // mais ne fait pas d'aller-retour). Au retour, le handler visibilitychange
    // déclenche un fetch différentiel immédiat (If-None-Match => 304 vide si RAS).
    if (typeof document !== 'undefined' && document.visibilityState === 'hidden') {
      scheduleRemoteSync();
      return;
    }
    // Le mode client (parcours public) n'a pas de session staff : il ne doit
    // PAS interroger les endpoints protégés (staff-state → 401). Ses créneaux
    // sont chargés à la demande via public-availability. On arrête donc la
    // boucle de sync ; setView() la relance quand on passe en staff/admin.
    if (state.view === 'client') return;
    if ((state.view === 'staff' || state.view === 'admin') && !hasSavedAuth()) {
      scheduleRemoteSync();
      return;
    }
    // C14 : la console peut être en cours d'injection au premier tick admin.
    if (state.view === 'admin') { if (typeof loadAdminDashboard === 'function') await loadAdminDashboard(true); }
    else await syncDateReservations(state.currentDate, { silent: true });
    scheduleRemoteSync();
  }, delay);
}

function loadState() {
  try {
    const storedState = window.PinlaneStorage?.getJson
      ? window.PinlaneStorage.getJson(STORAGE_KEY, null)
      : JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
    if (storedState) {
      // Les collections du serveur repartent VIDES a chaque chargement, meme si
      // une ancienne version les avait ecrites dans ce navigateur : c'est la
      // migration des postes deja ouverts. Le premier poll (immediat) les
      // remplit avec ce que le serveur confirme, et rien d'autre.
      return {
        ...storedState,
        reservations: [],
        laneStatuses: Array.from({ length: TOTAL_LANES }).reduce((acc, unused, index) => ({ ...acc, [index + 1]: 'active' }), {}),
      };
    }
  } catch (error) {}
  const today = todayStr();
  return {
    view: 'client',
    // AUCUNE reservation par defaut. Quatre lignes de demonstration etaient
    // ecrites en dur ici (« Sophie Renard », « Marc Dubois »…) : sur un poste
    // neuf, ou apres un vidage du navigateur, le planning affichait des clients
    // qui n'existent pas - et ils restaient a l'ecran si le serveur ne repondait
    // pas. Une console de gestion ne montre que ce que le serveur a confirme.
    reservations: [],
    laneStatuses: Array.from({ length: TOTAL_LANES }).reduce((acc, _, i) => ({ ...acc, [i + 1]: 'active' }), {}),
    isHolidayMode: false,
    currentDate: today,
    searchTerm: '',
    step: 1,
    booking: {
      name:'', phone:'', email:'', pax:4,
      date: today,
      type:'bowling', formuleId:'', duration:1, totalDuration:1, laneCount:1, startTime:'',
      // Mode de composition + activites cochees. Le bowling coche par defaut :
      // le formulaire s'ouvre exactement comme avant, sur un bowling d'une heure.
      mode: 'carte',
      activities: { bowling: { duration: 1 } },
      allocatedLanes: [],
      // Programme normalise par public-availability. Il porte le prix serveur
      // affiche au recap final ; le POST sera malgre tout recalcule a nouveau.
      serverProgram: null,
      preference: createDefaultFormulaPreference(),
      pauseMinutes: 0,
      opsPlan: null
    },
    selectedRes: null,
    activeTab: 'details',
    editState: null,
    availableSlots: [],
    staffPlanningExpanded: false,
    staffLaserPlanningExpanded: false,
    staffTableExpanded: false,
    staffGlobalExpanded: false,
    staffResourceView: 'bowling',
    staffStatusFilter: 'all',
    staffTheme: 'dark',
    opsPanelTab: 'activity',
    adminCenterId: 'libramont',
    adminDate: today,
    adminPeriod: 'day',
    adminTab: 'overview',
    adminCockpitMode: 'today',
    staffPricingFilter: 'all',
    staffPricingQuery: '',
    staffPricingSelectedId: '',
    staffEmailFilter: 'all',
    staffEmailOriginFilter: 'all',
    staffEmailQuery: '',
    staffEmailTemplateFilter: 'all',
    staffEmailSelectedId: '',
    staffMenuCollapsed: false,
    staffMenuPage: 'planning'
  };
}

// LA DATE DE TRAVAIL N EST PAS UNE PREFERENCE. Une console laissee ouverte
// un autre jour rouvrait sur SA date en l annoncant « Aujourd hui » : le
// 2026-08-22, localStorage portait encore currentDate 2026-07-29, adminDate
// 2026-07-21 et staffReservationsSelectedDate 2026-07-28. Dix ecrans
// (dashboard, les trois plannings, formules, arrivees, sessions, evenements,
// pistes, laser) affichaient le 29 juillet avec le badge « Aujourd hui », et
// « + Reservation » ecrivait le client de passage a cette date la.
//
// On ramene donc a aujourd hui toute date de travail DEJA PASSEE, et elle
// seule. Une date FUTURE est gardee : preparer le planning de la semaine
// prochaine puis rafraichir sa page ne doit pas renvoyer le responsable a
// aujourd hui.
function reconcileWorkingDates(target) {
  if (!target || typeof target !== 'object') return target;
  const today = todayStr();
  const stale = value => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && value < today;
  if (stale(target.currentDate)) target.currentDate = today;
  if (stale(target.adminDate)) target.adminDate = today;
  if (stale(target.staffReservationsSelectedDate)) target.staffReservationsSelectedDate = today;
  if (target.booking && stale(target.booking.date)) target.booking.date = today;
  // Le mois du selecteur derive de la date de travail : il ne peut pas rester
  // sur un mois que plus aucune date ne designe.
  if (typeof target.staffReservationsMonth === 'string' && /^\d{4}-\d{2}$/.test(target.staffReservationsMonth)
    && target.staffReservationsMonth < today.slice(0, 7)) {
    target.staffReservationsMonth = today.slice(0, 7);
  }
  return target;
}

