// Permissions de niveau PLATEFORME : jamais conférées par un rôle verrouillé
// (Direction = tous les droits DU CENTRE, pas ceux de la plateforme). Miroir
// exact de la règle serveur (sessionHasPermission, lib/staff-auth.js) : le
// serveur reste l'autorité, ce Set ne fait que cacher l'entrée de menu aux
// non-porteurs.
const PLATFORM_STAFF_PERMISSIONS = new Set(['platform.admin']);

function normalizeStaffSession(rawSession) {
  if (window.PinlaneStaffAuthSession?.normalize) {
    return window.PinlaneStaffAuthSession.normalize(rawSession, getCurrentStaffCenterId());
  }
  if (!rawSession || typeof rawSession !== 'object') return null;
  const token = rawSession.token || '';
  const cookieBacked = Boolean(rawSession.cookieBacked || !token);
  if (!token && !cookieBacked) return null;
  const expiresAt = rawSession.expiresAt || '';
  if (expiresAt && new Date(expiresAt).getTime() <= Date.now()) return null;
  return {
    token,
    cookieBacked,
    centerId: rawSession.centerId || getCurrentStaffCenterId(),
    expiresAt,
    member: rawSession.member || null,
    role: rawSession.role || null,
    permissions: Array.isArray(rawSession.permissions) ? rawSession.permissions : []
  };
}

function readStoredStaffSession() {
  try {
    const parsed = window.PinlaneStorage?.getJson
      ? window.PinlaneStorage.getJson(AUTH_KEY, null)
      : JSON.parse(localStorage.getItem(AUTH_KEY) || 'null');
    return normalizeStaffSession(parsed);
  } catch (error) {
    return null;
  }
}

function storeStaffAuthSession(session) {
  const normalized = normalizeStaffSession(session);
  if (!normalized) return false;
  state.staffAuthSession = normalized;
  state.adminCenterId = normalized.centerId || state.adminCenterId || 'libramont';
  if (window.PinlaneStorage?.setJson) window.PinlaneStorage.setJson(AUTH_KEY, normalized);
  else {
    try { localStorage.setItem(AUTH_KEY, JSON.stringify(normalized)); } catch (error) {}
  }
  isAuthenticated = true;
  return true;
}

function clearStaffAuthSession() {
  state.staffAuthSession = null;
  state.staffAccessControl = null;
  isAuthenticated = false;
  if (window.PinlaneStorage?.remove) window.PinlaneStorage.remove(AUTH_KEY);
  else {
    try { localStorage.removeItem(AUTH_KEY); } catch (error) {}
  }
}

function hasSavedAuth() {
  const session = normalizeStaffSession(state.staffAuthSession) || readStoredStaffSession();
  if (!session) {
    clearStaffAuthSession();
    return false;
  }
  state.staffAuthSession = session;
  isAuthenticated = true;
  return true;
}

function canUseStaffPermission(permission) {
  const session = normalizeStaffSession(state.staffAuthSession) || readStoredStaffSession();
  if (!session) return false;
  const permissions = new Set(session.permissions || []);
  const has = item => {
    if (PLATFORM_STAFF_PERMISSIONS.has(item)) return permissions.has(item);
    if (session.role?.locked) return true;
    return permissions.has(item);
  };
  if (Array.isArray(permission)) return permission.some(has);
  return has(permission);
}

function canUseStaffPage(page) {
  if (!hasSavedAuth()) return false;
  const rawPage = String(page || 'planning').trim();
  const cleanPage = normalizeStaffMenuPage(rawPage);
  if (cleanPage !== rawPage) return false;
  const required = STAFF_PAGE_PERMISSION_MAP[cleanPage];
  if (!required) return false;
  return canUseStaffPermission(required);
}

function getFirstAllowedStaffPage() {
  const candidates = ['dashboard', 'planning', 'reservations', 'arrivals', 'clients', 'emails', 'campaigns', 'users', 'settings'];
  return candidates.find(page => canUseStaffPage(page)) || 'dashboard';
}

function guardStaffPage() {
  if (state.view !== 'staff') return true;
  if (!hasSavedAuth()) return false;
  const page = getStaffMenuPage();
  if (canUseStaffPage(page)) return true;
  const fallback = getFirstAllowedStaffPage();
  state.staffMenuPage = fallback;
  save();
  toast('Accès non autorisé pour ce rôle.');
  return false;
}

async function loadStaffAuthSession(options = {}) {
  try {
    const demande = getCurrentStaffCenterId();
    const centerId = encodeURIComponent(demande);
    const payload = await apiRequest(`${API_ENDPOINTS.staffAuth}?centerId=${centerId}`, {
      method: 'GET',
      headers: staffAuthHeaders()
    });
    if (!payload.authenticated || !payload.session) {
      clearStaffAuthSession();
      return false;
    }
    applyStaffAuthPayload(payload, demande);
    // Charge la liste des centres SCOPEE au tenant des que la session est prete,
    // pour que le switcher n'affiche jamais un centre d'un autre client (meme
    // avant l'ouverture de la Direction). Non bloquant.
    loadMenuCenters(true);
    return true;
  } catch (error) {
    if (!options.silent) toast(error.message || 'Session staff invalide.');
    clearStaffAuthSession();
    return false;
  }
}

// La session et l equipe servies par api/staff-auth, posees dans l etat. Une
// seule ecriture pour la connexion (loadStaffAuthSession) et pour le direct
// (refreshStaffAccessForLiveSync).
function applyStaffAuthPayload(payload, demande) {
  storeStaffAuthSession(payload.session);
  // LE CENTRE CHOISI SURVIT AU RECHARGEMENT (2026-08-21).
  // Movsar : « quand je vais sur Fun Galaxy Libramont et que je reload la
  // page, je rearrive sur N4 Bowling ». api/staff-auth rend TOUJOURS la
  // session du centre de CONNEXION : son parametre centerId ne sert qu'a
  // controler l'acces et a charger le bon accessControl, jamais a deplacer
  // la session. storeStaffAuthSession ecrasait donc le centre memorise par
  // celui du code, a chaque demarrage.
  //
  // Le serveur a deja tranche l'AUTORISATION : sans le droit centers.switch
  // sur ce centre il aurait repondu 403, et on serait dans le catch. Arrive
  // ici, le centre demande est legitime : le choix explicite gagne, comme
  // sur le chemin de la bascule (assets/staff-menu.js).
  if (demande && payload.session && demande !== payload.session.centerId) {
    state.adminCenterId = demande;
    state.establishmentCenterId = demande;
  }
  if (payload.accessControl) state.staffAccessControl = payload.accessControl;
  save();
}

// L EQUIPE ET LES DROITS, RELUS PAR LE DIRECT. Un membre ajoute, un role
// modifie ou un acces bloque sur un autre poste est vu ici : la page Equipe
// suit, et la barre laterale montre les droits du moment. Jamais de
// deconnexion sur une panne reseau (loadStaffAuthSession efface la session sur
// toute erreur : juste a la connexion, pas pour une relecture de fond). Seul un
// serveur qui REPOND que la session n est plus valide ferme l acces.
async function refreshStaffAccessForLiveSync() {
  const demande = getCurrentStaffCenterId();
  let payload = null;
  try {
    payload = await apiRequest(`${API_ENDPOINTS.staffAuth}?centerId=${encodeURIComponent(demande)}`, {
      method: 'GET',
      headers: staffAuthHeaders()
    });
  } catch (error) {
    return false;
  }
  if (payload && payload.authenticated === false) {
    clearStaffAuthSession();
    applyAuthState();
    return false;
  }
  if (!payload || !payload.session) return false;
  applyStaffAuthPayload(payload, demande);
  applyAuthState();
  if (state.view === 'staff' && getStaffMenuPage() === 'users') renderStaffUtilityPage();
  return true;
}

function applyAuthState() {
  const locked = (state.view === 'staff' || state.view === 'admin') && !hasSavedAuth();
  document.body.classList.toggle('auth-locked', locked);
  const overlay = document.getElementById('authOverlay');
  const logoutBtn = document.getElementById('logoutBtn');
  if (overlay) overlay.classList.toggle('hidden', !locked);
  if (logoutBtn) logoutBtn.classList.toggle('hidden', !hasSavedAuth());
  // A1 : bouton header « Direction » masqué pour un rôle sans direction.view
  // (visible hors session : il mène au login, re-vérifié après connexion).
  const adminBtn = document.getElementById('btnAdmin');
  if (adminBtn) adminBtn.classList.toggle('hidden', !canOpenAdminView());
  // Le menu latéral n'est reconstruit qu'au chargement de page : sans ça, un
  // changement de rôle (directrice → manager) garde les catégories de l'ancien
  // rôle jusqu'à un refresh manuel. On le rebâtit à chaque transition d'auth
  // (login/logout) : reconstruction DOM pure, aucune requête serveur.
  if (typeof window.renderStaffMenu === 'function') window.renderStaffMenu();
  if (!locked) document.body.style.overflow = state.view === 'staff' && (state.staffPlanningExpanded || state.staffLaserPlanningExpanded || state.staffTableExpanded || state.staffGlobalExpanded) ? 'hidden' : '';
}

function openSaasAccess(target = 'staff') {
  if (!getStaffSessionToken() && !state.staffAuthSession?.cookieBacked) clearStaffAuthSession();
  setView(target);
}

function initAuthMotion() {
  const overlay = document.getElementById('authOverlay');
  const card = overlay?.querySelector('.auth-card.auth-card-single');
  if (!overlay || !card || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  let frame = 0;
  let nextEvent = null;
  const resetMotion = () => {
    card.classList.remove('auth-motion-active');
    card.style.setProperty('--auth-tilt-x', '0deg');
    card.style.setProperty('--auth-tilt-y', '0deg');
    card.style.setProperty('--auth-logo-x', '0px');
    card.style.setProperty('--auth-logo-y', '0px');
  };

  overlay.addEventListener('pointermove', event => {
    nextEvent = event;
    if (frame) return;
    frame = requestAnimationFrame(() => {
      frame = 0;
      const rect = card.getBoundingClientRect();
      const px = Math.min(Math.max((nextEvent.clientX - rect.left) / rect.width, 0), 1);
      const py = Math.min(Math.max((nextEvent.clientY - rect.top) / rect.height, 0), 1);
      overlay.style.setProperty('--auth-overlay-x', `${nextEvent.clientX}px`);
      overlay.style.setProperty('--auth-overlay-y', `${nextEvent.clientY}px`);
      card.style.setProperty('--auth-x', `${Math.round(px * 100)}%`);
      card.style.setProperty('--auth-y', `${Math.round(py * 100)}%`);
      card.style.setProperty('--auth-tilt-x', `${((px - .5) * 3.2).toFixed(2)}deg`);
      card.style.setProperty('--auth-tilt-y', `${((.5 - py) * 2.4).toFixed(2)}deg`);
      card.style.setProperty('--auth-logo-x', `${((px - .5) * 5).toFixed(1)}px`);
      card.style.setProperty('--auth-logo-y', `${((py - .5) * 4).toFixed(1)}px`);
      card.classList.add('auth-motion-active');
    });
  });
  overlay.addEventListener('pointerleave', resetMotion);
  overlay.addEventListener('blur', resetMotion, true);
}

initAuthMotion();

function getFriendlyLoginErrorMessage(loginError) {
  const message = String(loginError?.message || '').toLowerCase();
  if (message.includes('data transfer quota') || (message.includes('quota') && message.includes('exceeded'))) {
    return 'Base de données temporairement limitée. Réessayez avec le code propriétaire, ou relancez après la migration.';
  }
  return loginError?.message || 'Code incorrect.';
}

async function submitLogin(ev) {
  ev.preventDefault();
  const error = document.getElementById('authError');
  const submitBtn = ev.target?.querySelector('button[type="submit"]');
  const code = String(document.getElementById('loginPass')?.value || document.getElementById('loginUser')?.value || '').trim();
  if (!code) {
    if (error) error.textContent = 'Entre le code staff.';
    return;
  }
  if (error) error.textContent = '';
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.textContent = 'Connexion...';
  }
  try {
    const payload = await apiRequest(API_ENDPOINTS.staffAuth, {
      method: 'POST',
      body: JSON.stringify({
        action: 'login',
        centerId: getCurrentStaffCenterId(),
        code
      })
    });
    storeStaffAuthSession(payload.session);
    // LE CENTRE SUIT LE CODE. Le serveur ouvre la session sur le centre du
    // code, qui n'est pas forcement le dernier centre consulte : sans cette
    // ligne, l'ecran resterait sur un centre que la session ne couvre pas et
    // toutes les lectures suivantes partiraient au mauvais endroit.
    if (payload.session?.centerId) state.adminCenterId = payload.session.centerId;
    if (payload.accessControl) state.staffAccessControl = payload.accessControl;
    save();
    // Une nouvelle session n herite rien de la precedente : c est peut-etre
    // quelqu un d autre, sur un autre centre, sur le meme navigateur.
    resetCenterScopedCaches();
    // La liste des centres du tenant se charge ICI aussi, pas seulement a la
    // restauration de session (loadStaffAuthSession). Sans cet appel, le
    // switcher retombait sur le repli statique des 3 centres Fun Galaxy filtre
    // par le centre courant : pour un centre ne dans la console (n4-bowling,
    // mi12) ce repli est VIDE, et le menu s ouvrait sans aucun centre.
    loadMenuCenters(true);
    // Et le catalogue du centre de la session : sans lui, le formulaire de
    // reservation retomberait sur le socle fichier, qui est celui de Fun Galaxy.
    loadCenterScheduleConfig();
    applyAuthState();
    if (state.view === 'staff') {
      guardStaffPage();
      await syncDateReservations(state.currentDate, { silent: true, skipRender: true });
      renderStaff();
    } else if (state.view === 'admin') {
      // A1 : le rôle fraîchement connecté doit avoir direction.view pour
      // rester sur la console Direction : sinon retour vue staff.
      if (!canOpenAdminView()) {
        setView('staff');
      } else {
        // C14 : les consoles ne sont pas chargées quand la vue admin n'a
        // affiché que l'écran de login : injection avant le premier rendu.
        await ensureAdminConsolesLoaded();
        await loadAdminDashboard(true);
        renderAdminDashboard();
      }
    }
    toast('Connexion Pinlane active.');
  } catch (loginError) {
    clearStaffAuthSession();
    if (error) error.textContent = getFriendlyLoginErrorMessage(loginError);
  } finally {
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = 'Se connecter';
    }
  }
}

async function logout() {
  try {
    await apiRequest(API_ENDPOINTS.staffAuth, {
      method: 'POST',
      headers: staffAuthHeaders(),
      body: JSON.stringify({ action: 'logout', centerId: getCurrentStaffCenterId() })
    });
  } catch (error) {}
  clearStaffAuthSession();
  closePos();
  setView('client');
  applyAuthState();
}

function syncOpsSidebar() {
  if (typeof window.syncStaffMenuState === 'function') {
    window.syncStaffMenuState();
  }
  const resource = typeof getStaffResourceView === 'function'
    ? getStaffResourceView()
    : (state.staffResourceView || 'bowling');
  const planningMenuActive = state.view === 'staff' && getStaffMenuPage() === 'planning';
  document.querySelectorAll('[data-ops-view]').forEach(item => {
    item.classList.toggle('active', item.dataset.opsView === state.view);
  });
  document.querySelectorAll('[data-ops-resource]').forEach(item => {
    item.classList.toggle('active', planningMenuActive && item.dataset.opsResource === resource);
  });
}

// A1 : la console Direction exige `direction.view` (même mécanique que
// guardStaffPage). Un rôle connecté sans cette permission est renvoyé sur la
// vue staff ; non connecté, la vue admin reste atteignable pour afficher le
// login (le refus est re-vérifié après connexion dans submitLogin).
function canOpenAdminView() {
  return !hasSavedAuth() || canUseStaffPermission('direction.view');
}

// C14 : admin-console.js (~92 Ko) et ops-console.js (~75 Ko) ne sont plus
// chargés au boot pour tous les profils. Injection dynamique à la première
// ouverture de la vue admin (après le garde canOpenAdminView) et, pour
// ops-console seul, au premier besoin Ops côté staff (page Emails, dashboard,
// réglages). Promesse partagée : une seule balise <script> par fichier.
const ADMIN_CONSOLE_SRC = '/assets/admin-console.js?v=20261006encaisse';
const OPS_CONSOLE_SRC = '/assets/ops-console.js?v=20260925h';
const ADMIN_DATA_SRC = '/assets/admin-data.js?v=20261003b';
const ADMIN_MAIL_SRC = '/assets/admin-mail.js?v=20260925e';
// Les declarations inertes de l'index gardent l'ordre et les versions en un
// seul endroit. Aucun de ces modules n'est demande pour la vue publique.
const STAFF_CONSOLE_SOURCES = Array.from(document.querySelectorAll('script[data-staff-console]'), script => script.getAttribute('src'));
const dynamicConsoleScripts = {};
let staffConsolesPromise = null;
let staffConsolesReady = false;
let consoleViewRequest = 0;

function loadConsoleScriptOnce(src) {
  if (!dynamicConsoleScripts[src]) {
    dynamicConsoleScripts[src] = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = src;
      script.onload = () => resolve();
      script.onerror = () => {
        delete dynamicConsoleScripts[src];
        script.remove();
        reject(new Error(`Script indisponible : ${src}`));
      };
      document.head.appendChild(script);
    });
  }
  return dynamicConsoleScripts[src];
}

function ensureStaffConsolesLoaded() {
  if (!staffConsolesPromise) {
    // Une dependance executee avant la suivante, y compris apres un retry.
    // Les scripts deja charges restent en cache ; seul le fichier en panne
    // est reinjecte. Deux demandes partagent toute la sequence.
    staffConsolesPromise = STAFF_CONSOLE_SOURCES.reduce(
      (pending, src) => pending.then(() => loadConsoleScriptOnce(src)),
      Promise.resolve()
    ).then(() => { staffConsolesReady = true; }).catch(error => {
      staffConsolesPromise = null;
      throw error;
    });
  }
  return staffConsolesPromise;
}

function ensureAdminConsolesLoaded() {
  return ensureStaffConsolesLoaded().then(() =>
    [ADMIN_CONSOLE_SRC, OPS_CONSOLE_SRC, ADMIN_DATA_SRC, ADMIN_MAIL_SRC].reduce(
      (pending, src) => pending.then(() => loadConsoleScriptOnce(src)),
      Promise.resolve()
    )
  );
}

function ensureOpsConsoleLoaded() {
  return loadConsoleScriptOnce(OPS_CONSOLE_SRC);
}

// C14 : si l'injection échoue, l'UI statique de #adminView (onclick vers des
// fonctions du bundle absent) serait un piège à ReferenceError : on la laisse
// neutralisée (pointer-events) et on pose un panneau d'erreur avec retry ;
// la promesse rejetée étant purgée du cache, setView('admin') relance une
// vraie injection.
function clearAdminConsoleLoadError() {
  const panel = document.getElementById('adminConsoleLoadError');
  if (panel) panel.remove();
}

function renderAdminConsoleLoadError(adminRoot) {
  if (!adminRoot) {
    toast('Console direction indisponible (script non chargé).');
    return;
  }
  adminRoot.style.pointerEvents = 'none';
  clearAdminConsoleLoadError();
  const panel = document.createElement('div');
  panel.id = 'adminConsoleLoadError';
  panel.className = 'admin-load-error';
  panel.setAttribute('role', 'alert');
  panel.innerHTML = `
    <div>
      <strong>Console direction indisponible</strong>
      <p>Le module n'a pas pu être chargé (connexion instable ?). Vos données ne sont pas affectées.</p>
    </div>
    <button type="button" class="admin-btn" onclick="setView('admin')">Réessayer</button>`;
  adminRoot.prepend(panel);
}

// Point d'entrée unique du besoin Ops côté staff : charge ops-console.js au
// premier appel puis délègue à loadOpsAdmin (définie par le script injecté).
function requestOpsAdminLoad(force = false) {
  ensureOpsConsoleLoaded()
    .then(() => loadOpsAdmin(force))
    .catch(() => toast('Console Ops indisponible (script non chargé).'));
}

// « Envoyer la file » depuis la page Emails staff : même garantie de chargement.
function requestOpsDispatch() {
  ensureOpsConsoleLoaded()
    .then(() => dispatchOpsEmails())
    .catch(() => toast('Console Ops indisponible (script non chargé).'));
}

function setView(v) {
  const request = ++consoleViewRequest;
  // Le voile de demarrage (index.html) meurt ici : des qu'une vue est
  // reellement appliquee, il n'a plus de raison d'etre. Premiere ligne, avant
  // tout retour anticipe, sinon un refus d'acces le laisserait colle.
  document.documentElement.removeAttribute('data-boot');
  document.body.classList.remove('entry-mode');
  const entryView = document.getElementById('entryView');
  if (entryView) entryView.classList.add('hidden');
  if (v === 'admin' && !canOpenAdminView()) {
    toast('Accès non autorisé pour ce rôle.');
    v = 'staff';
  }
  const viewChanged = state.view !== v;
  state.view = v;
  // L'URL suit la vue. push seulement quand on CHANGE de vue : le bouton Retour
  // ramene alors a la vue precedente, sans empiler une entree par re-rendu.
  syncViewUrl(v, { push: viewChanged });
  document.body.classList.toggle('client-mode', v === 'client');
  document.body.classList.toggle('staff-mode', v === 'staff' || v === 'admin');
  document.body.classList.toggle('admin-mode', v === 'admin');
  // Les notifs « nouvelle réservation » sont réservées au poste staff : on purge
  // dès qu'on quitte cette vue (jamais rien qui traîne sur le parcours client).
  if (v !== 'staff') clearNewResNotifs();
  document.getElementById('clientView').classList.toggle('hidden', v !== 'client');
  document.getElementById('staffView').classList.toggle('hidden', v !== 'staff');
  document.getElementById('adminView').classList.toggle('hidden', v !== 'admin');
  document.getElementById('btnClient').classList.toggle('active', v === 'client');
  document.getElementById('btnStaff').classList.toggle('active', v === 'staff');
  document.getElementById('btnAdmin').classList.toggle('active', v === 'admin');
  document.getElementById('nav').style.display = v === 'client' ? 'flex' : 'none';
  document.getElementById('clientDemoAccess').classList.toggle('hidden', v !== 'client');
  syncOpsSidebar();
  applyStaffTheme();
  // OPS-07 : le login reste disponible pendant le chargement. Les autres
  // callers peuvent rendre leur contenu, mais aucun controle partiel ne
  // devient utilisable avant l'arrivee de toutes ses dependances.
  const needsStaff = v === 'staff' || v === 'admin';
  const staffRoot = document.getElementById('staffView');
  const adminRoot = document.getElementById('adminView');
  const sidebar = document.querySelector('[data-staff-menu-root]');
  let status = document.getElementById('staffConsoleLoadStatus');
  if (status && !needsStaff) { status.remove(); status = null; }
  if (needsStaff && !staffConsolesReady) {
    for (const root of [staffRoot, adminRoot]) {
      if (root) { root.style.display = 'none'; root.inert = true; }
    }
    if (sidebar) sidebar.inert = true;
    if (!status) {
      status = document.createElement('div');
      status.id = 'staffConsoleLoadStatus';
      staffRoot.before(status);
    }
    // UN CHARGEMENT N EST PAS UNE PANNE : il portait la classe d erreur (cadre
    // et fond rouges) pendant chaque ouverture normale de la console. Il a sa
    // propre forme, calme ; le rouge ne vient qu avec un vrai echec.
    status.className = 'staff-console-loading';
    status.setAttribute('role', 'status');
    status.innerHTML = '<span class="staff-console-spinner" aria-hidden="true"></span><span>Chargement de la console…</span>';
    applyAuthState();
    ensureStaffConsolesLoaded().then(() => {
      if (request !== consoleViewRequest || state.view !== v) return;
      setView(v);
    }).catch(() => {
      if (request !== consoleViewRequest || state.view !== v) return;
      status.className = 'admin-load-error';
      status.setAttribute('role', 'alert');
      status.innerHTML = `<div><strong>Console indisponible</strong>
        <p>Le module n'a pas pu être chargé. Réessayez pour ouvrir la console.</p></div>`;
      const retry = document.createElement('button');
      retry.type = 'button';
      retry.className = 'admin-btn';
      retry.textContent = 'Réessayer';
      retry.addEventListener('click', () => setView(state.view));
      status.appendChild(retry);
    });
    scheduleRemoteSync();
    save();
    return;
  }
  if (staffConsolesReady) {
    if (status) status.remove();
    for (const root of [staffRoot, adminRoot]) {
      if (root) { root.style.display = ''; root.inert = false; }
    }
    if (sidebar) sidebar.inert = false;
  }
  if ((v === 'staff' || v === 'admin') && !hasSavedAuth()) {
    if (v === 'staff') renderStaffShell(todaysReservations());
    applyAuthState();
    scheduleRemoteSync();
    save();
    return;
  }
  if (v === 'staff') {
    guardStaffPage();
    renderStaff();
    syncDateReservations(state.currentDate, { silent: true });
  }
  else if (v === 'admin') {
    if (!state.adminDate) state.adminDate = todayStr();
    document.body.style.overflow = '';
    // C14 : le rendu admin ne démarre qu'une fois les deux consoles injectées
    // (couvre aussi le deep-link #admin/... au boot, qui passe par setView).
    const adminRoot = document.getElementById('adminView');
    clearAdminConsoleLoadError();
    if (adminRoot) adminRoot.style.pointerEvents = 'none';
    ensureAdminConsolesLoaded()
      .then(() => {
        if (request !== consoleViewRequest || state.view !== 'admin') return;
        if (adminRoot) adminRoot.style.pointerEvents = '';
        renderAdminDashboard();
        loadAdminDashboard(false);
      })
      .catch(() => {
        if (request !== consoleViewRequest) return;
        if (state.view !== 'admin') {
          if (adminRoot) adminRoot.style.pointerEvents = '';
          return;
        }
        renderAdminConsoleLoadError(adminRoot);
      });
  }
  else document.body.style.overflow = '';
  scheduleRemoteSync();
  save();
}

function syncRouteFromHash() {
  // La section Emails fait partie de l'adresse : sans elle dans la
  // comparaison, le bouton Retour entre deux sections ne re-rendait rien.
  const before = [
    state.view,
    state.staffMenuPage,
    state.staffResourceView,
    state.staffEmailsSection,
    state.adminTab
  ].join('|');
  applyInitialRouteFromHash();
  const after = [
    state.view,
    state.staffMenuPage,
    state.staffResourceView,
    state.staffEmailsSection,
    state.adminTab
  ].join('|');
  if (before === after) return;
  closePos();
  closeQuickBook();
  setView(state.view);
  applyAuthState();
}

function initClient() {
  if (isPastBusinessDate(state.booking.date)) state.booking.date = todayStr();
  state.booking.type = normalizeBookingType(state.booking.type);
  if (state.booking.type !== 'formule') state.booking.formuleId = '';
  if (state.booking.type === 'bowling' && !DURATION_OPTIONS.some(option => Number(option.value) === Number(state.booking.duration))) {
    state.booking.duration = 1;
  }
  if (state.booking.type === 'bowling') {
    state.booking.totalDuration = Number(state.booking.duration || 1);
    state.booking.laneCount = getRequiredLaneCount('bowling', state.booking.pax, '');
    state.booking.preference = createDefaultFormulaPreference();
  }
  if (state.booking.type === 'laser' && !LASER_GAME_OPTIONS.some(option => Number(option.value) === Number(state.booking.duration))) {
    state.booking.duration = LASER_GAME_OPTIONS[0].value;
  }
  if (state.booking.type === 'laser') {
    state.booking.totalDuration = Number(state.booking.duration) * getLaserWaveCount(state.booking.pax);
    state.booking.laneCount = 0;
    state.booking.preference = createDefaultFormulaPreference();
  }
  syncBookingTypeUi();
  document.getElementById('fDate').value = state.booking.date;
  document.getElementById('fDate').min = todayStr();
  applyBookingDateHorizon();
  document.getElementById('fPax').value = state.booking.pax;
  document.getElementById('fDate').addEventListener('change', e => {
    const nextDate = e.target.value;
    // UNE DATE EN COURS DE FRAPPE N'EST PAS UNE DATE PASSEE.
    // Un champ `type="date"` emet `change` a chaque segment saisi au clavier :
    // en tapant l'annee chiffre par chiffre, la valeur vaut un instant
    // « 0002-08-20 », qui est bien anterieure a aujourd'hui. L'ancien code
    // criait alors « Cette date est deja passee. Choisissez aujourd'hui » ET
    // remettait le champ a aujourd'hui, donc il se battait contre la frappe :
    // impossible de saisir une date a la main. Une valeur incomplete est
    // desormais IGNOREE, sans message et sans remise a zero. Signale par Movsar
    // le 2026-08-20, capture a l'appui, sur le tunnel embarque de N4.
    const complete = /^\d{4}-\d{2}-\d{2}$/.test(nextDate) && Number(nextDate.slice(0, 4)) >= 1000;
    if (!complete) return;
    if (isPastBusinessDate(nextDate)) {
      state.booking.date = todayStr();
      e.target.value = state.booking.date;
      showAlert('Cette date est déjà passée. Choisissez aujourd’hui ou une date future.');
    } else {
      state.booking.date = nextDate;
    }
    // Le verdict de l'ancienne date ne dit plus rien de la nouvelle : on l'efface
    // AVANT de peindre, sinon un "Fermé" (ou un "Ouvert") de la veille survit.
    if (typeof setCenterDayStatus === 'function') setCenterDayStatus(null);
    clearBookingAlternatives();
    state.booking.formuleId = '';
    state.booking.startTime = '';
    state.booking.totalDuration = state.booking.type === 'laser'
      ? Number(state.booking.duration) * getLaserWaveCount(state.booking.pax)
      : state.booking.duration;
    state.booking.preference = createDefaultFormulaPreference();
    state.booking.pauseMinutes = 0;
    state.booking.opsPlan = null;
    // Verdict du jour demande au serveur AVANT de peindre : updateSchedHint
    // affichera "Vérification des horaires..." tant qu'il n'a pas repondu,
    // jamais un "Ouvert" que la reponse va contredire.
    loadCenterScheduleConfig(state.booking.date);
    updateSchedHint();
    syncBookingTypeUi();
    // Le tarif d'un centre qui vend AUX PARTIES depend du JOUR : la liste se
    // repeint avec la date, sinon le client voit le prix de la veille.
    renderDurations();
    renderFormules();
    renderFormulaPreferences();
    updatePaxAlert();
    save();
    syncDateReservations(state.booking.date, { silent: true, skipRender: true });
  });
  document.getElementById('fPax').addEventListener('input', e => {
    // Le champ porte min=1 et max=120, mais seules les fleches les respectaient :
    // « 500 » tape au clavier traversait tout le tunnel (prix, pistes, heures)
    // avant d etre plafonne en silence par le serveur. Le plafond se voit ici.
    const borne = Math.min(Number(e.target.max) || 120, Math.max(Number(e.target.min) || 1, Number(e.target.value) || 1));
    if (e.target.value !== '' && Number(e.target.value) !== borne) e.target.value = String(borne);
    state.booking.pax = borne;
    clearBookingAlternatives();
    state.booking.formuleId = '';
    state.booking.startTime = '';
    state.booking.totalDuration = state.booking.type === 'laser'
      ? Number(state.booking.duration) * getLaserWaveCount(state.booking.pax)
      : state.booking.duration;
    state.booking.preference = createDefaultFormulaPreference();
    state.booking.pauseMinutes = 0;
    state.booking.opsPlan = null;
    updatePaxAlert();
    // Le nombre de joueurs entre dans le prix de presque tout : les activites
    // facturees par personne (minigolf, playground), et le bowling dont le
    // nombre de PISTES s'en deduit. Sans ce rafraichissement, le total restait
    // celui du nombre de joueurs precedent, le client voyait un montant qui
    // ne bougeait pas en ajoutant du monde. Le champ « date » appelait deja
    // cette chaine ; le champ « joueurs » ne l'appelait pas.
    syncBookingTypeUi();
    renderFormules();
    renderFormulaPreferences();
    save();
  });
  renderDurations();
  renderLaserOptions();
  updateSchedHint();
  updatePaxAlert();
  renderFormules();
  renderFormulaPreferences();
  bindCardTilt();
  bindKeyboardCare();
  // Demarre TOUJOURS a l'etape 1 (et synchronise le DOM avec state.step) : sinon
  // un state.step persiste (ex. 4) affichait l'etape 4 dans la barre de progression
  // alors que le contenu montrait l'etape 1 -> desynchro visible sur le formulaire.
  // Synchronisation d'ouverture : ni mouvement ni vol de focus, personne n'a
  // encore rien demandé.
  goStep(1, { animate: false, focus: false });
  // La venue repart TOUJOURS de sa premiere question : l etape n est pas
  // persistee, revenir au tunnel ne doit pas laisser le client devant la
  // question du groupe sans avoir vu celle du jour.
  if (typeof setVenueStage === 'function') setVenueStage('date');
}

// Stepper tactile du nombre de joueurs (boutons +/- mobile). On reste sur le
// champ #fPax comme source de vérité : on modifie sa valeur puis on rejoue son
// listener 'input' existant (pas de duplication de logique de recalcul).
function stepPax(delta) {
  const input = document.getElementById('fPax');
  if (!input) return;
  const min = Number(input.min) || 1;
  const max = Number(input.max) || 120;
  const next = Math.min(max, Math.max(min, (Number(input.value) || min) + delta));
  input.value = String(next);
  input.dispatchEvent(new Event('input', { bubbles: true }));
}

function renderDurations() {
  const g = document.getElementById('durGrid');
  const label = document.querySelector('#bowlingBlock .tunable-label');
  // Ce centre vend-il AUX PARTIES, par personne ? La reponse est une DONNEE DE
  // CENTRE (center.booking.bowlingPricing), pas une constante du produit : le
  // bloc change alors de nature, pas seulement de prix. Sans cette donnee, tout
  // se passe exactement comme avant.
  const games = typeof getBowlingGameOptions === 'function' ? getBowlingGameOptions(state.booking.date, { pax: Math.max(1, Number(state.booking.pax) || 1), laneCount: getRequiredLaneCount('bowling', Math.max(1, Number(state.booking.pax) || 1), '') }) : null;
  if (games) {
    if (label) label.innerHTML = 'Nombre de parties <span class="tunable-sub">par personne, chaussures comprises</span>';
    if (!games.length) {
      g.innerHTML = '<p class="dur-empty">Aucun tarif publié pour ce jour.</p>';
      return;
    }
    // Une duree qui n'est plus proposee ce jour-la ne doit pas rester
    // selectionnee : le client paierait pour une option qui n'existe pas.
    if (!games.some(o => Number(o.value) === Number(state.booking.duration))) {
      state.booking.duration = games[0].value;
      state.booking.totalDuration = games[0].value;
    }
    g.innerHTML = games.map(o => `
      <button type="button" class="dur-pill ${Number(state.booking.duration) === Number(o.value) ? 'active' : ''}" onclick="setDuration(${o.value})">
        ${o.label}
        <span class="price">${o.price}€ / pers</span>
      </button>
    `).join('');
    return;
  }
  if (label) label.innerHTML = 'Durée de jeu <span class="tunable-sub">par piste</span>';
  g.innerHTML = DURATION_OPTIONS.map(o => `
    <button type="button" class="dur-pill ${state.booking.duration === o.value ? 'active' : ''}" onclick="setDuration(${o.value})">
      ${o.label}
      <span class="price">${o.price}€ / piste</span>
    </button>
  `).join('');
}

function setDuration(v) { state.booking.duration = v; state.booking.totalDuration = v; renderDurations(); save(); }

function renderLaserOptions() {
  const grid = document.getElementById('laserGrid');
  if (!grid) return;
  grid.innerHTML = LASER_GAME_OPTIONS.map(option => `
    <button type="button" class="dur-pill laser-pill ${Number(state.booking.duration) === Number(option.value) ? 'active' : ''}" onclick="setLaserDuration(${option.value})">
      ${option.label}
      <span class="price">${option.price}€ / pers</span>
      <small>${option.games * 20} min de jeu + briefing</small>
    </button>
  `).join('');
}

function setLaserDuration(v) {
  state.booking.duration = Number(v);
  state.booking.totalDuration = Number(v) * getLaserWaveCount(state.booking.pax);
  state.booking.startTime = '';
  state.booking.opsPlan = null;
  renderLaserOptions();
  save();
}

// Bloc d'etat du jour. Asymetrie VOULUE : ouvert = une ligne (aucune decision a
// prendre), tout ce qui empeche ou limite une reservation = un bloc borde. C'est
// la forme, pas la nuance de couleur, qui porte l'info a deux metres.
function renderDayStatusBlock(variant, title, copy) {
  const icon = variant === 'is-closed'
    ? '<circle cx="12" cy="12" r="10"/><line x1="8" y1="8" x2="16" y2="16"/><line x1="16" y1="8" x2="8" y2="16"/>'
    : '<circle cx="12" cy="12" r="10"/><path d="M12 8v5"/><path d="M12 16h.01"/>';
  return `<div class="day-status ${variant}">
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icon}</svg>
    <span class="day-status-copy"><strong>${escapeHtml(title)}</strong><span>${escapeHtml(copy)}</span></span>
  </div>`;
}

function formatBookingDateLong(dateStr) {
  try {
    return parseLocalDate(dateStr).toLocaleDateString('fr-BE', { weekday: 'long', day: 'numeric', month: 'long' });
  } catch (error) { return dateStr; }
}

// '16:00' -> '16h', '16:30' -> '16h30'
function formatClockShort(hhmm) {
  const parts = String(hhmm || '').split(':');
  const h = Number(parts[0]);
  const m = parts[1] || '';
  return Number(m) ? `${h}h${m}` : `${h}h`;
}

function updateSchedHint() {
  // La revelation du programme suit le meme verdict que le badge d'horaires :
  // meme lecture d'etat, au meme moment, quel que soit le chemin de sortie.
  if (typeof syncProgressiveReveal === 'function') syncProgressiveReveal();
  const el = document.getElementById('schedHint');
  if (!el) return;
  const dayStatus = typeof getCenterDayStatusFor === 'function' ? getCenterDayStatusFor(state.booking.date) : null;
  // day.schedule fait foi quand il est la (calcul serveur) : cela supprime la
  // dependance a la grille en dur pour les centres dont defaultSchedule n'est
  // pas encore renseigne.
  const sch = getSchedule(state.booking.date, state.isHolidayMode);
  const context = getSpecialOpeningContext(state.booking.date, state.isHolidayMode);

  if (isPastBusinessDate(state.booking.date)) {
    el.innerHTML = '<span class="closed">Date passée - réservations terminées</span>';
    return;
  }
  if (dayStatus && dayStatus.open === false) {
    const jour = formatBookingDateLong(state.booking.date);
    const titre = dayStatus.closedLabel === 'Fermé exceptionnellement ce jour'
      ? `Fermé exceptionnellement le ${jour}`
      : `Fermé le ${jour}`;
    el.innerHTML = renderDayStatusBlock('is-closed', titre, 'Le centre n’ouvre pas ce jour. Choisissez une autre date.');
    return;
  }
  if (!sch) {
    el.innerHTML = '<span class="closed">Fermé ce jour</span>';
    return;
  }
  // Verdict serveur en vol pour cette date : on ne promet rien tant qu'il n'a
  // pas repondu. Annoncer "Ouvert" puis se dedire une demi-seconde plus tard,
  // c'est exactement le faux "Ouvert" qu'on corrige.
  if (typeof isCenterDayPending === 'function' && isCenterDayPending(state.booking.date)) {
    el.innerHTML = '<span class="sched-checking">Vérification des horaires...</span>';
    return;
  }
  const holiday = context.active && context.label ? `<span class="sched-holiday">${escapeHtml(context.label)}</span>` : '';
  const windows = dayStatus && Array.isArray(dayStatus.closedWindows) ? dayStatus.closedWindows : [];
  if (windows.length) {
    const coupure = windows.map(w => `de ${formatClockShort(w.start)} à ${formatClockShort(w.end)}`).join(' et ');
    el.innerHTML = renderDayStatusBlock(
      'is-partial',
      `Ouvert ${sch.label}, fermé ${coupure}`,
      `Aucune réservation possible ${coupure} ce jour.`
    );
    return;
  }
  // L'HEURE QU'IL EST COMPTE. Le badge lisait l'horaire du jour sans regarder
  // la pendule : a 22h30, un centre ferme depuis 30 min affichait encore
  // « Ouvert 10h - 22h » (Movsar, capture). Sur AUJOURD'HUI, il dit donc ce
  // qui est vrai maintenant ; sur une date future, la plage reste la bonne
  // reponse (« quand est-ce ouvert ce jour-la ? »).
  // UN SEUL cas change la reponse : la journee est FINIE. Avant l'ouverture,
  // la journee est encore devant (on reserve pour 14h a 8h du matin), donc le
  // badge garde sa plage ; c'est APRES l'heure de fermeture qu'annoncer
  // « Ouvert » devient un mensonge (Movsar, capture a 22h passees).
  const isToday = typeof todayStr === 'function' && state.booking.date === todayStr();
  const now = isToday && typeof currentTimeDecimal === 'function' ? currentTimeDecimal() : null;
  if (now != null && Number.isFinite(Number(sch.close)) && now >= Number(sch.close)) {
    el.innerHTML = `<span class="closed">Fermé pour aujourd’hui</span><span class="sched-note">ouvrait ${escapeHtml(sch.label)}</span>${holiday}`;
    return;
  }
  el.innerHTML = `<span class="open">Ouvert ${sch.label}</span>${holiday}`;
}

// --- REVELATION PROGRESSIVE DE L'ETAPE 1 (2026-08-18, demande Movsar) -------
// D'abord la venue seule ; le PROGRAMME s'ouvre quand la date tient (jour
// ouvert) ; le RESUME (total) s'ouvre des qu'un choix existe. Chaque
// ouverture joue la revelation liquide (CSS lq-reveal). Le verdict en vol
// (verification serveur) ne replie JAMAIS un bloc deja ouvert : un ecran qui
// bat au rythme du reseau est pire qu'un ecran patient.
function setRevealState(element, shouldShow) {
  if (!element) return;
  element.classList.add('lq-revealable');
  // L'etat se lit sur is-folded SEUL : un bloc jamais synchronise (aucune
  // classe) est un bloc AFFICHE, et le premier repli doit le plier vraiment.
  // Corollaire voulu : un bloc affiche des le boot ne rejoue pas d'ouverture
  // (la cascade d'arrivee de l'etape suffit, pas de theatre au chargement).
  const isShown = !element.classList.contains('is-folded');
  if (shouldShow === isShown) return;
  if (shouldShow) {
    element.classList.remove('is-folded');
    // Reflow volontaire : l'animation d'ouverture rejoue a CHAQUE ouverture.
    void element.offsetWidth;
    element.classList.add('is-revealed');
    // La question du bloc qui s ouvre s ecrit mot a mot, en meme temps que le
    // bloc se deploie : les deux mouvements appartiennent au meme geste.
    const question = element.querySelector('.s1-what-head .panel-title');
    if (question) revelerQuestion(question);
  } else {
    element.classList.remove('is-revealed');
    element.classList.add('is-folded');
  }
}

// Le GESTE d'ouverture : la venue se valide d'un bouton, et c'est ce clic qui
// deploie le programme (animation VECUE a chaque parcours, meme quand la date
// par defaut est valide). Le choix survit au rechargement (state.booking).
// Retour a la page venue (ligne de rappel du telephone) : le programme se
// replie, la venue redevient la page courante. Les choix d'activites du
// client restent en memoire, rien ne se perd.
// PAGE PAR PAGE : chaque page de l etape 1 demarre en HAUT. Sur les ecrans
// courts le corps d etape defile ; le geste qui mene au bouton laisse un
// scroll residuel, et la page suivante s ouvrait decalee (ligne de rappel
// hors champ, vu en prod WebKit a 320x520 le 2026-08-18).
function resetStepOneScroll() {
  const body = document.querySelector('#clientView .step1-body');
  if (body) body.scrollTop = 0;
}

function reopenVenue() {
  state.booking.venueConfirmed = false;
  save();
  if (typeof showMobileOptionsPage === 'function') showMobileOptionsPage(false);
  syncProgressiveReveal();
  resetStepOneScroll();
}

// Le fil de contexte garde les trois decisions qui expliquent le parcours.
// Il ne recalcule rien : il reformule uniquement l etat deja valide par le
// moteur et ramene a l ecran qui possede la decision.
function bookingContextChoiceLabel() {
  const booking = state && state.booking ? state.booking : {};
  const mode = normalizeBookingMode(booking.mode);
  if (mode === 'formule' && booking.formuleId) {
    const formule = typeof resolveDisplayFormule === 'function' ? resolveDisplayFormule(booking.formuleId) : null;
    return formule && formule.name ? formule.name : 'Formule choisie';
  }
  const activities = typeof getChosenActivities === 'function' ? getChosenActivities() : [];
  if (!activities.length) return 'À composer';
  if (activities.length === 1) return activities[0].name || '1 activité';
  return `${activities[0].name || 'Activités'} + ${activities.length - 1}`;
}

function syncBookingContext() {
  const root = document.getElementById('bookingContext');
  if (!root || !state || !state.booking) return;
  const booking = state.booking;
  const dateNode = document.getElementById('bookingContextDate');
  const paxNode = document.getElementById('bookingContextPax');
  const choiceNode = document.getElementById('bookingContextChoice');
  let dateLabel = 'À choisir';
  if (booking.date) {
    try {
      dateLabel = parseLocalDate(booking.date).toLocaleDateString('fr-BE', { weekday: 'short', day: 'numeric', month: 'short' });
    } catch (error) { dateLabel = booking.date; }
  }
  if (dateNode) dateNode.textContent = dateLabel;
  const pax = Math.max(1, Number(booking.pax) || 1);
  if (paxNode) paxNode.textContent = `${pax} personne${pax > 1 ? 's' : ''}`;
  if (choiceNode) choiceNode.textContent = bookingContextChoiceLabel();
  const body = document.querySelector('#clientView .step1-body');
  const venueOpen = Number(state.step) === 1 && Boolean(body && body.classList.contains('is-solo'));
  root.classList.toggle('is-muted', venueOpen);
}

function editBookingContext(part) {
  const target = part === 'pax' ? 'pax' : 'date';
  if (part === 'choice') {
    state.booking.venueConfirmed = true;
    goStep(1);
    if (typeof showMobileOptionsPage === 'function') showMobileOptionsPage(false);
    syncProgressiveReveal();
    return;
  }
  goStep(1);
  reopenVenue();
  setVenueStage(target);
}

function toggleContactExtras(forceOpen) {
  const button = document.getElementById('contactMore');
  const extras = document.getElementById('contactExtras');
  if (!button || !extras) return;
  const currentlyOpen = button.getAttribute('aria-expanded') === 'true';
  const open = typeof forceOpen === 'boolean' ? forceOpen : !currentlyOpen;
  button.setAttribute('aria-expanded', open ? 'true' : 'false');
  extras.classList.toggle('is-collapsed', !open);
  if (open) {
    const first = extras.querySelector('button, input, textarea');
    if (first && typeof first.focus === 'function') first.focus({ preventScroll: true });
  } else if (extras.contains(document.activeElement)) {
    button.focus({ preventScroll: true });
  }
}

// LA VENUE POSE DEUX QUESTIONS, UNE PAR ECRAN (2026-08-27). Movsar : « meme la
// toute premiere page pour mettre date joueur [...] vrm tout doit avoir une
// question qui arrive ». Le jour d abord, le groupe ensuite. L etat n est PAS
// persiste : revenir au tunnel repose toujours la premiere question.
let venueStage = 'date';

function setVenueStage(stage) {
  venueStage = stage === 'pax' ? 'pax' : 'date';
  const corps = document.querySelector('.step1-body');
  if (corps) corps.classList.toggle('is-venue-pax', venueStage === 'pax');
  const libelle = document.getElementById('btnVenueContinueLabel');
  if (libelle) libelle.textContent = venueStage === 'pax' ? 'Voir les activités' : 'Continuer';
  // La question de l ecran qui arrive s ecrit, comme partout ailleurs. Le noeud
  // n est PAS reconstruit entre les deux ecrans (seule une classe bascule) :
  // sans le redemarrage force de revelerQuestion, rien ne rejouerait.
  const question = document.querySelector('.step1-body.is-solo .s1-when .panel-title'
    + (venueStage === 'pax' ? '.s1-q-pax' : '.s1-q-date'));
  if (question && typeof revelerQuestion === 'function') revelerQuestion(question);
  // La reponse de l ecran entre en cascade a chaque bascule.
  const bloc = document.querySelector('.step1-body.is-solo .s1-when');
  if (bloc) {
    bloc.classList.remove('is-arriving');
    void bloc.offsetWidth;
    bloc.classList.add('is-arriving');
  }
  if (venueStage === 'pax') {
    const champ = document.getElementById('fPax');
    // Au clavier physique seulement. Sur un ecran tactile, ce focus ouvrait le
    // clavier numerique A L ARRIVEE sur la question (le tap sur « Continuer »
    // est un geste utilisateur, iOS l honore) : l ecran se retrecissait et le
    // bouton remontait sur le compteur (verdict iPhone, 2026-09-01). Au doigt,
    // le geste est -/+ ; taper dans le champ reste possible, mais choisi.
    if (champ && pointeurFin()) champ.focus({ preventScroll: true });
  }
  // Changer de question, c est avancer : le fil et la barre haute le disent.
  if (typeof updateProgress === 'function') updateProgress();
}

function confirmVenue() {
  const date = state.booking.date;
  const dayStatus = typeof getCenterDayStatusFor === 'function' ? getCenterDayStatusFor(date) : null;
  const dayOpen = !isPastBusinessDate(date)
    && Boolean(getSchedule(date, state.isHolidayMode))
    && !(dayStatus && dayStatus.open === false);
  if (!dayOpen) {
    showAlert('Choisissez une date d’ouverture : le centre est fermé ce jour.');
    return;
  }
  // PREMIER CLIC : le jour est valide, on passe a la question du groupe. La
  // garde de date reste AVANT, sinon on demanderait le nombre de joueurs pour un
  // jour ou le centre est ferme.
  if (venueStage !== 'pax') {
    setVenueStage('pax');
    return;
  }
  state.booking.venueConfirmed = true;
  save();
  syncProgressiveReveal();
  resetStepOneScroll();
}

// Premier passage du boot : la position se POSE, elle ne s'anime pas (le FLIP
// jouerait le repli de la venue au chargement, du theatre que personne n'a
// demande).
let revealBooted = false;

// LA QUESTION S ECRIT, ELLE N APPARAIT PAS D UN BLOC. Chaque mot est enveloppe
// dans un masque et monte a son tour (CSS : .q-word + q-word-rise, decalage
// pose par --i). Movsar, 2026-08-26 : « il faut que le texte apparaisse d une
// maniere trop stylee ».
// Le texte lu reste EXACTEMENT le meme : les mots sont remis avec leurs
// espaces, donc textContent, les lecteurs d ecran et les gates qui cherchent
// « Que souhaitez-vous faire ? » voient la meme phrase qu avant.
function revelerQuestion(element) {
  if (!element) return;
  // LA PHRASE MEMORISEE NE DOIT PAS FIGER UN TITRE QUI CHANGE. La source servait
  // toujours en priorite : un titre pose par le JS APRES un premier decoupage
  // (l ecran des heures ecrit « À quelle heure ? » par-dessus « Horaire
  // disponible ») se voyait remettre l ancienne phrase au rendu suivant. Elle ne
  // sert donc que si l element est ENCORE decoupe ; des qu il a ete reecrit,
  // c est son texte courant qui fait foi.
  const dejaDecoupe = Boolean(element.querySelector && element.querySelector('.q-word'));
  const phrase = ((dejaDecoupe ? element.dataset.questionSource : '') || element.textContent || '').trim();
  if (!phrase) return;
  // La phrase d origine est gardee : sans elle, un second passage decouperait
  // du markup deja decoupe et empilerait les spans a l infini.
  element.dataset.questionSource = phrase;
  const mots = phrase.split(/\s+/).filter(Boolean);
  // LE DERNIER MOT N ARRIVE JAMAIS TROP TARD. Le decalage etait fixe (70 ms
  // par mot) : sur une question de huit mots, le dernier partait 490 ms apres
  // le premier, et la phrase se trainait. Le PAS s adapte donc au nombre de
  // mots pour que l ecriture complete tienne dans 200 ms, quel que soit la
  // longueur - c est le plafond que visit-motion-check mesure, et il vaut
  // aussi pour l oeil. Les questions courtes gardent leur rythme (70 ms).
  const pas = mots.length > 1 ? Math.min(70, Math.floor(200 / (mots.length - 1))) : 0;
  element.style.setProperty('--q-pas', `${pas}ms`);
  element.innerHTML = mots
    .map((mot, index) => `<span class="q-word" style="--i:${index}"><span>${escapeHtml(mot)}</span></span>`)
    .join(' ');
  // Le redemarrage force : sans lui, revenir sur l ecran ne rejoue rien
  // (l animation est deja consideree comme terminee sur ces noeuds).
  element.classList.remove('q-reveal');
  void element.offsetWidth;
  element.classList.add('q-reveal');
  // L ANIMATION SE RETIRE QUAND ELLE A FINI. Elle etait posee en
  // `fill: both` et restait accrochee a chaque mot pour toujours : le
  // navigateur continuait de compter l amplitude du deplacement dans le
  // debordement du masque, qui annoncait donc 99 px de contenu pour 54 px de
  // boite alors que le mot etait sagement en place (mesure 2026-08-31 ;
  // c est ce que le gate one-screen voyait comme du texte coupe). En
  // retirant la classe a la fin, il ne reste plus une seule animation vivante
  // sur les mots : le masque redevient une simple boite, et le tunnel porte
  // quelques dizaines d animations en moins a chaque ecran.
  // Un jeton par passage : si la question est REJOUEE avant la fin (retour en
  // arriere, bascule de sous-ecran), l ecouteur du passage precedent ne doit
  // pas couper l animation du nouveau.
  const jeton = String(Number(element.dataset.questionRun || 0) + 1);
  element.dataset.questionRun = jeton;
  const masques = element.querySelectorAll('.q-word > span');
  const dernier = masques[masques.length - 1];
  if (dernier) {
    dernier.addEventListener('animationend', () => {
      if (element.dataset.questionRun === jeton) element.classList.remove('q-reveal');
    }, { once: true });
  }
}

function syncProgressiveReveal() {
  const what = document.getElementById('s1What');
  if (!what) return;
  // Plier ou deplier le programme fait changer de question : le fil suit.
  if (typeof updateProgress === 'function') setTimeout(updateProgress, 0);
  const date = state.booking.date;
  const dayStatus = typeof getCenterDayStatusFor === 'function' ? getCenterDayStatusFor(date) : null;
  const pending = typeof isCenterDayPending === 'function' && isCenterDayPending(date);
  const dayOpen = !isPastBusinessDate(date)
    && Boolean(getSchedule(date, state.isHolidayMode))
    && !(dayStatus && dayStatus.open === false)
    && state.booking.venueConfirmed === true;
  // En vol : on garde l'etat courant (ni ouverture ni repli sur une promesse).
  if (!pending) {
    // SEQUENCE CENTREE : la venue vit seule au milieu tant que la date ne
    // tient pas (.is-solo sur le corps d'etape). Quand elle se met a tenir,
    // le liquide la DECALE vers sa colonne : FLIP (position mesuree avant et
    // apres, trajet rejoue en transform avec le ressort), pendant que le
    // programme se deploie a la place liberee (lq-reveal).
    const body = document.querySelector('#clientView .step1-body');
    const when = document.querySelector('#clientView .s1-when');
    const wasSolo = Boolean(body && body.classList.contains('is-solo'));
    const willBeSolo = !dayOpen;
    // L'etat solo se lit aussi sur l'etape entiere : le pied d'ecran masque
    // son CTA global tant que le programme n'existe pas.
    const stepRoot = document.getElementById('step1');
    if (stepRoot) stepRoot.classList.toggle('is-solo', willBeSolo);
    if (body && when && wasSolo !== willBeSolo && revealBooted && !prefersReducedMotion() && Number(state.step) === 1) {
      const before = when.getBoundingClientRect();
      setRevealState(what, dayOpen);
      body.classList.toggle('is-solo', willBeSolo);
      const after = when.getBoundingClientRect();
      const dx = before.left - after.left;
      const dy = before.top - after.top;
      if (Math.abs(dx) > 2 || Math.abs(dy) > 2) {
        when.style.transition = 'none';
        when.style.transform = `translate(${dx}px, ${dy}px)`;
        void when.offsetWidth;
        when.style.transition = 'transform 0.95s var(--lq-spring)';
        when.style.transform = '';
        setTimeout(() => {
          when.style.removeProperty('transition');
          when.style.removeProperty('transform');
        }, 1050);
      }
    } else {
      setRevealState(what, dayOpen);
      if (body) body.classList.toggle('is-solo', willBeSolo);
    }
  }
  revealBooted = true;
  // L'etat d'attente : une ligne fine sous la venue dit POURQUOI le programme
  // n'est pas la et ce qui l'ouvrira. Elle vit exactement quand il est plie.
  const placeholder = document.getElementById('s1WhatPlaceholder');
  if (placeholder) placeholder.hidden = !what.classList.contains('is-folded');
  // PAGE PAR PAGE telephone (2026-08-18) : programme ouvert, la venue se
  // resume en une ligne tapable (le panneau complet est masque par le CSS
  // <= 640, l'ecran entier revient aux activites). Le contenu se remplit ici
  // pour suivre CHAQUE changement de date ou de groupe.
  const venueLine = document.getElementById('s1VenueLine');
  if (venueLine) {
    const lineText = document.getElementById('s1VenueLineText');
    if (lineText) lineText.textContent = venueSummaryLabel();
    venueLine.hidden = what.classList.contains('is-folded');
  }
  // Le resume : des qu'un choix existe dans le mode courant.
  const mode = normalizeBookingMode(state.booking.mode);
  const hasChoice = mode === 'carte'
    ? (typeof getChosenActivities === 'function' && getChosenActivities().length > 0)
    : Boolean(state.booking.formuleId);
  setRevealState(document.getElementById('programSummary'), mode === 'carte' && hasChoice);
  // Le dock telephone depend du repli du programme : il se resynchronise ICI,
  // quel que soit l'ordre des rendus qui ont mene a ce verdict (un dock qui
  // parle d'allocation devant un programme plie a ete observe au navigateur).
  if (typeof syncStatusDock === 'function') syncStatusDock();
  // La barre haute telephone lit la page courante (venue ou activites) : elle
  // suit chaque bascule d'is-solo, pas seulement les changements d'etape.
  if (typeof syncMobileTopbar === 'function') syncMobileTopbar();
}

// --- DOCK D'ETAT TELEPHONE ---------------------------------------------------
// Miroir flottant des messages d'allocation (paxAlert) et d'activite fermee
// (typeAlert) : sur telephone ils quittent le flux (CSS) et vivent ici,
// au-dessus du pied d'ecran, toujours visibles. Le dock ne s'exprime qu'a
// l'etape 1 : ces messages n'existent que la.
function syncStatusDock() {
  const dock = document.getElementById('stepStatusDock');
  if (!dock) return;
  const onStepOne = Number(state.step) === 1;
  // Programme replie (jour ferme, date passee) : l'allocation de pistes ne
  // decrit rien que le client puisse composer, le dock se tait.
  const what = document.getElementById('s1What');
  const programOpen = Boolean(what && !what.classList.contains('is-folded'));
  const pax = document.getElementById('paxAlert');
  const type = document.getElementById('typeAlert');
  // LE DOCK NE PARLE QUE POUR PREVENIR (2026-09-01). La phrase d allocation
  // (« Pour 4 personnes, nous reservons 1 piste... Vous choisirez l heure a
  // l etape suivante ») occupait 55 px sous le CTA de chaque ecran d activites
  // pour decrire ce que l ecran suivant fait de lui-meme ; la page options
  // dit deja « 1 heure · 1 piste ». Seuls les avertissements (groupe trop
  // grand, rotation, passages, activite fermee) montent ici.
  const paxPrevient = Boolean(pax && pax.querySelector('[data-prevenir="1"]'));
  const source = (type && type.innerHTML.trim()) ? type : ((paxPrevient && pax.innerHTML.trim()) ? pax : null);
  const html = onStepOne && programOpen && source ? source.innerHTML : '';
  if (dock.innerHTML !== html) dock.innerHTML = html;
  dock.classList.toggle('is-live', Boolean(html));
  // Le dock se pose au-dessus du pied MESURE, pas d'un pied suppose : la
  // sous-barre varie d'un tenant a l'autre (contacts du centre en prod) et un
  // decalage fixe mordait le haut du CTA « Verifier les disponibilites »
  // (vu en prod le 2026-08-18 a 390x844). Mesure au moment ou il parle.
  // EN FLUX depuis le 2026-09-01 : plus aucun offset a mesurer. L ancien
  // calcul posait un style.bottom sur un dock position:fixed ; au moindre
  // clavier ou pied variable, il atterrissait au milieu de l ecran.
  dock.style.removeProperty('bottom');
}

// --- SOIN CLAVIER TELEPHONE (2026-09-01) -------------------------------------
// Trois faits mesures ont dicte cette fonction :
//   1. AUCUN code ne lisait window.visualViewport ni ne reagissait au clavier
//      (0 occurrence sur 24k lignes) : un champ enterre par le retrecissement
//      restait enterre, on tapait a l aveugle (147px sous le bord a 390x480).
//   2. Le defilement natif du navigateur vers le champ focalise ignorait le
//      pied colle en bas : le CTA se peignait sur le bas du champ Email et un
//      tap dans le champ validait le recapitulatif. Les scroll-padding poses
//      dans le CSS guident ce defilement ; ici on le DECLENCHE aux bons
//      moments.
//   3. --tunnel-header-h etait consommee par #alertBox mais definie nulle
//      part : le repli 56px desalignait les alertes de 7 a 23px du vrai
//      header. Elle est posee ici, depuis la mesure reelle.
function bindKeyboardCare() {
  if (document.body.dataset.kbCareBound === '1') return;
  document.body.dataset.kbCareBound = '1';
  const header = document.querySelector('body > header');
  const poseHauteurHeader = () => {
    if (header) document.documentElement.style.setProperty('--tunnel-header-h', `${Math.round(header.getBoundingClientRect().height)}px`);
  };
  poseHauteurHeader();
  window.addEventListener('resize', poseHauteurHeader);
  window.addEventListener('resize', () => { if (typeof poserPlafondAlerte === 'function') poserPlafondAlerte(); });

  const champTexte = (el) => Boolean(el && el.closest && el.closest('#clientView, .bespoke-modal')
    && el.matches('input:not([type=checkbox]):not([type=radio]), textarea, select'));
  const revele = () => {
    document.body.classList.toggle('kb-care-active', window.innerHeight <= 520);
    const el = document.activeElement;
    if (!champTexte(el)) return;
    // 'center' : 'nearest' ne defile PAS quand le champ est deja visible,
    // meme enterre sous un CTA sticky (mesure a 320x300 : tap sur le champ
    // date = tap sur Continuer). Centrer le degage des deux bords ; les
    // scroll-padding gardent la reserve quand le navigateur defile de lui-meme.
    el.scrollIntoView({ block: 'center', behavior: 'auto' });
    // Le formulaire contact est son propre defileur. Avec un pied fixe,
    // scrollIntoView peut juger le champ visible alors qu il touche deja le
    // CTA. On recentre donc dans la hauteur reellement libre, pied exclu.
    const defileur = el.closest('.step-body, .bespoke-body');
    const foot = el.closest('.step')?.querySelector('.step-foot');
    if (defileur && foot && defileur.scrollHeight > defileur.clientHeight) {
      const champ = el.getBoundingClientRect();
      const zone = defileur.getBoundingClientRect();
      const basLibre = Math.min(zone.bottom, foot.getBoundingClientRect().top);
      const centreLibre = zone.top + ((basLibre - zone.top) / 2);
      defileur.scrollTop += (champ.top + (champ.height / 2)) - centreLibre;
    }
  };
  document.addEventListener('focusin', (event) => {
    if (!champTexte(event.target)) return;
    // Deux temps : tout de suite, puis apres que le clavier a retreci la
    // scene (Android redimensionne 150 a 300ms apres le focus).
    requestAnimationFrame(revele);
    setTimeout(revele, 320);
  });
  // iOS ne retrecit que le viewport VISUEL : visualViewport est le seul
  // signal. Android passe aussi par resize. Les deux, amortis.
  if (window.visualViewport) {
    let calme = null;
    window.visualViewport.addEventListener('resize', () => {
      clearTimeout(calme);
      calme = setTimeout(revele, 80);
    });
  }
  window.addEventListener('resize', () => setTimeout(revele, 80));
}

// --- TILT 3D DES CARTES ------------------------------------------------------
// La carte s'incline sous le curseur (max 5 degres), revient a plat au
// depart. Souris uniquement (jamais au toucher), rien en mouvement reduit,
// une seule ecoute deleguee, calee sur la frequence d'affichage.
function bindCardTilt() {
  const host = document.getElementById('clientView');
  if (!host || host.dataset.tiltBound === '1') return;
  host.dataset.tiltBound = '1';
  const MAX_DEG = 7;
  let queued = null;
  const clearTilt = (card) => {
    if (!card) return;
    card.style.removeProperty('--tiltX');
    card.style.removeProperty('--tiltY');
    card.style.removeProperty('--tiltScale');
    card.classList.remove('is-tilting');
  };
  host.addEventListener('pointermove', (event) => {
    if (event.pointerType !== 'mouse' || prefersReducedMotion()) return;
    const card = event.target && event.target.closest ? event.target.closest('.activity-card, .formule-card') : null;
    if (queued) queued.card !== card && clearTilt(queued.card);
    queued = { card, x: event.clientX, y: event.clientY, pending: queued ? queued.pending : false };
    if (queued.pending) return;
    queued.pending = true;
    requestAnimationFrame(() => {
      const current = queued;
      if (!current) return;
      current.pending = false;
      if (!current.card) return;
      const rect = current.card.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      const rx = ((current.y - rect.top) / rect.height - 0.5) * -2 * MAX_DEG;
      const ry = ((current.x - rect.left) / rect.width - 0.5) * 2 * MAX_DEG;
      current.card.style.setProperty('--tiltX', `${rx.toFixed(2)}deg`);
      current.card.style.setProperty('--tiltScale', '1.02');
      current.card.style.setProperty('--tiltY', `${ry.toFixed(2)}deg`);
      current.card.classList.add('is-tilting');
    });
  }, { passive: true });
  host.addEventListener('pointerout', (event) => {
    const card = event.target && event.target.closest ? event.target.closest('.activity-card, .formule-card') : null;
    if (!card) return;
    const next = event.relatedTarget && event.relatedTarget.closest ? event.relatedTarget.closest('.activity-card, .formule-card') : null;
    if (next !== card) clearTilt(card);
  }, { passive: true });
}

// La note du nombre de joueurs REPOND au geste : elle se pose quand elle
// change, et reste strictement immobile quand elle dit la meme chose (elle est
// recalculee a chaque frappe dans le champ).
function updatePaxAlert() {
  const host = document.getElementById('paxAlert');
  const before = host ? host.innerHTML : '';
  renderPaxAlertContent();
  if (host && host.innerHTML !== before && host.firstElementChild) {
    host.firstElementChild.classList.add('is-appearing');
  }
  syncStatusDock();
}

function renderPaxAlertContent() {
  const pax = Number(state.booking.pax) || 0;
  const needed = getRequiredLaneCount(state.booking.type || 'bowling', pax, state.booking.formuleId);
  // Capacite LIVE du centre (config, pas les constantes) : ainsi changer le nombre
  // de pistes ou les joueurs/piste dans Etablissement se reflete ici.
  const maxPerLane = getMaxPerLane();
  const totalLanes = getTotalLanes();
  const impossibleBowlingGroup = state.booking.type !== 'laser' && needed > totalLanes;
  const el = document.getElementById('paxAlert');
  if (pax <= 0) { el.innerHTML = ''; return; }
  if (state.booking.type === 'laser') {
    const waveCount = getLaserWaveCount(pax);
    const waveSize = getBalancedLaserWaveSize(pax);
    const remainingIfEmpty = Math.max(0, getLaserArenaCapacity() - (waveCount > 1 ? waveSize : pax));
    el.innerHTML = `
      <div class="pax-alert ${waveCount > 1 ? 'warning' : ''}" data-prevenir="${waveCount > 1 ? '1' : '0'}">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${waveCount > 1 ? '2.5' : '2'}" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0;margin-top:1px;"><circle cx="12" cy="12" r="10"/><path d="M12 7v5l3 2"/></svg>
        <span>${waveCount > 1 ? `Groupe de <b>${pax} joueurs</b> : nous préparons <b>${waveCount} sessions Laser</b> d'environ ${waveSize} joueurs.` : `Vous réservez <b>${pax} place${pax > 1 ? 's' : ''}</b>. Dans une session vide, il restera <b>${remainingIfEmpty}</b> place${remainingIfEmpty > 1 ? 's' : ''}.`}</span>
      </div>`;
    return;
  }
  // Formule : le nombre de pistes depend de la formule (et de son bowling). Tant
  // qu aucune formule n est choisie (ou qu elle n utilise pas de piste), on
  // n affiche PAS de compte de pistes (evite un absurde "0 pistes cote a cote").
  if (state.booking.type === 'formule' && (!state.booking.formuleId || needed <= 0)) {
    // Le compteur de joueurs est juste au-dessus et l onglet vient d etre
    // choisi : « Vous serez 4 personnes. Choisissez une formule ci-dessous »
    // redisait l ecran (inventaire texte du 2026-09-01).
    el.innerHTML = '';
    return;
  }
  // VISITE : plusieurs activites dans la meme reservation. Le message ne
  // connaissait que le bowling seul, le laser seul et les formules : une
  // visite retombait donc sur le texte du bowling (« nous reservons 2
  // pistes ») sans dire un mot des autres activites cochees. On annonce ici
  // ce que le GROUPE implique, activite par activite, et rien pour celles
  // qui n'imposent aucune contrainte.
  if (normalizeBookingMode(state.booking.mode) === 'carte' && typeof getChosenActivities === 'function') {
    const choisies = getChosenActivities();
    // DES LA PREMIERE ACTIVITE, et non a partir de la deuxieme (2026-08-21).
    // Movsar, capture de Fun Galaxy Libramont : 7 joueurs, SEULES les Arcades
    // cochees, et l'ecran annoncait « nous reservons 0 pistes cote a cote ».
    // Avec une seule activite on retombait sur le texte du bowling seul, qui
    // compte des pistes que rien n'occupe. Le meme garde existait deja pour
    // les formules ; il manquait ici.
    if (choisies.length) {
      const consequences = [];
      const aBowling = choisies.find((a) => a.priceType === 'grid_bowling');
      if (aBowling && needed > 0) {
        // Le client veut savoir comment son groupe se repartit, pas seulement
        // combien de pistes on bloque.
        const parPiste = Math.max(1, Math.ceil(pax / Math.max(1, needed)));
        consequences.push(`<b>${escapeHtml(aBowling.name)}</b> : <b>${needed} piste${needed > 1 ? 's' : ''}</b> réservée${needed > 1 ? 's' : ''} côte à côte, environ <b>${parPiste} joueur${parPiste > 1 ? 's' : ''}</b> par piste.`);
      }
      const aLaser = choisies.find((a) => a.priceType === 'grid_laser');
      if (aLaser) {
        const vagues = getLaserWaveCount(pax);
        const tailles = typeof getBalancedLaserWaveSizes === 'function' ? getBalancedLaserWaveSizes(pax) : [];
        const postes = Math.max(1, Math.trunc(Number(getLaserArenaCapacity()) || 1));
        // LA CAUSE AVANT LA CONSEQUENCE. « 2 sessions » ne veut rien dire tant
        // que le client ignore que l arene compte 30 postes et qu ils sont 49.
        // Les tailles viennent du MEME calcul que le plan (vagues equilibrees),
        // pas d une division refaite ici.
        if (vagues > 1) {
          const reparties = tailles.length === vagues
            ? ` : ${tailles.slice(0, -1).join(', ')} puis ${tailles[tailles.length - 1]} joueurs`
            : '';
          consequences.push(`<b>Laser game</b> : l’arène compte <b>${postes} postes</b> et vous êtes <b>${pax}</b>. Votre groupe jouera en <b>${vagues} sessions</b> qui se suivent${reparties}. Chacune fait le même nombre de parties.`);
        } else {
          consequences.push(`<b>Laser game</b> : l’arène compte <b>${postes} postes</b> et vous êtes <b>${pax}</b>. Tout le groupe joue <b>en une seule session</b>.`);
        }
      }
      // DUCKPIN (2026-08-24) : il a SES pistes (2 a Libramont, servies par le
      // catalogue), sa regle de groupe, et un plafond que le bowling n a pas.
      // La notif comptait les pistes du bowling et ignorait celles-ci.
      const aDuckpin = choisies.find((a) => a.resourceType === 'duckpin_lane');
      if (aDuckpin) {
        // Le calcul du serveur (activityUnitPlan) : les pistes qu il faut, et
        // des tours au-dela de celles du centre (2026-09-28).
        const plan = getActivityUnitPlan({ ...aDuckpin, capacityPerUnit: Number(aDuckpin.capacityPerUnit) || 6 }, pax);
        const nomDuckpin = escapeHtml(aDuckpin.name.toLowerCase());
        if (plan.tours > 1) {
          consequences.push(`<b>${plan.units} pistes</b> de ${nomDuckpin} pour ${pax} joueurs : le centre en a ${plan.atOnce}, le groupe joue en <b>${plan.tours} tours</b>`);
        } else if (plan.units > 1) {
          consequences.push(`<b>${plan.units} pistes</b> de ${nomDuckpin}`);
        }
      }
      // Une installation avec un plafond de joueurs impose ses passages.
      choisies.forEach((activite) => {
        const plafond = Number(activite.maxPax) || 0;
        if (plafond > 0 && pax > plafond) {
          consequences.push(`<b>${Math.ceil(pax / plafond)} passages</b> au ${escapeHtml(activite.name)} (${plafond} joueurs max)`);
        }
      });
      const impossible = aBowling && needed > totalLanes;
      // PREVENIR, PAS DECRIRE (inventaire texte du 2026-09-01). « Vous
      // choisirez l heure de chaque activite a l etape suivante » decrivait
      // l ecran suivant, et « nous reservons 1 piste » redisait la page
      // options (« 1 heure · 1 piste »). Seuls les cas qui CHANGENT la visite
      // (groupe impossible, rotation, passages, sessions) montent au dock du
      // telephone : data-prevenir, lu par syncStatusDock.
      // « 1 session de laser game » est une description, « 2 sessions » un fait
      // qui change la visite (le groupe est coupe en deux).
      // Le drapeau se lit sur les FAITS, plus sur une expression reguliere
      // appliquee au texte affiche : reformuler une phrase ne doit pas
      // eteindre en silence l alerte du telephone.
      const groupeCoupe = Boolean(choisies.find((a) => a.priceType === 'grid_laser')) && getLaserWaveCount(pax) > 1;
      const prevenir = impossible || groupeCoupe || consequences.some((c) => /rotation|passages?/i.test(c));
      // UNE LIGNE PAR CONTRAINTE, sous un titre qui dit l essentiel. La phrase
      // unique separee par des virgules obligeait a tout lire pour comprendre
      // qu une seule activite posait probleme.
      const titre = impossible
        ? `Groupe de ${pax} joueurs : cette visite ne tient pas en une fois`
        : (consequences.length > 1
          ? `Ce que votre groupe de ${pax} personnes implique`
          : `Votre groupe de ${pax} personne${pax > 1 ? 's' : ''}`);
      el.innerHTML = `
        <div class="pax-alert ${impossible || consequences.length ? 'warning' : ''}" data-prevenir="${prevenir ? '1' : '0'}">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${consequences.length ? '2.5' : '2'}" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0;margin-top:1px;"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
          ${impossible
            ? `<span>Groupe de <b>${pax} joueurs</b> : impossible sur ${totalLanes} pistes en même temps. Le staff proposera deux vagues ou un autre horaire.</span>`
            : consequences.length
              ? `<div class="pax-alert-body">
                  <strong class="pax-alert-title">${escapeHtml(titre)}</strong>
                  <ul class="pax-alert-list">${consequences.map((c) => `<li>${c}</li>`).join('')}</ul>
                </div>`
              : `<span><b>${pax} personne${pax > 1 ? 's' : ''}</b>, <b>${choisies.length} activité${choisies.length > 1 ? 's' : ''}</b> : tout tient en une visite.</span>`}
        </div>`;
      return;
    }
    // Aucune activite cochee : le compte de pistes n'a aucun sens, et le
    // client attend surtout de savoir quoi faire ensuite.
    el.innerHTML = `
      <div class="pax-alert">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0;margin-top:1px;"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
        <span>Vous serez <b>${pax} personne${pax > 1 ? 's' : ''}</b>. Choisissez au moins une activité ci-dessus.</span>
      </div>`;
    return;
  }
  if (impossibleBowlingGroup) {
    el.innerHTML = `
      <div class="pax-alert warning">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0;margin-top:1px;"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
        <span>Groupe de <b>${pax} joueurs</b> : impossible sur ${totalLanes} pistes en même temps. Le staff devra proposer deux vagues ou un autre horaire.</span>
      </div>`;
  } else if (pax > maxPerLane) {
    el.innerHTML = `
      <div class="pax-alert warning">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0;margin-top:1px;"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
        <span>Maximum conseillé : <b>${maxPerLane} joueurs par piste</b>. Avec ${pax} joueurs, nous réservons <b>${needed} pistes</b>${pax > totalLanes * maxPerLane ? ' avec répartition serrée validée staff' : ' côte à côte'}.</span>
      </div>`;
  } else {
    el.innerHTML = `
      <div class="pax-alert">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0;margin-top:1px;"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
        <span>Allocation : <b>${needed} piste${needed > 1 ? 's' : ''}</b> (max ${maxPerLane}/piste)</span>
      </div>`;
  }
}

function normalizeBookingType(type) {
  return ['bowling', 'laser', 'formule', 'visite'].includes(type) ? type : 'bowling';
}

// Deux modes seulement : composer sa visite « à la carte », ou prendre une
// formule tout compris. Les anciens types restent acceptes (vieux lien, etat
// sauvegarde) et retombent sur la carte avec la bonne activite cochee.
function normalizeBookingMode(mode) {
  if (mode === 'formule') return 'formule';
  return 'carte';
}

// LE TYPE ENVOYE AU SERVEUR SE DEDUIT de ce qui est coche. Une visite qui ne
// contient qu'une activite planifiee garde son type historique ('bowling' ou
// 'laser') et donc son chemin de disponibilite d'origine : on ne fait passer par
// le chemin 'visite' que ce qui n'existait pas avant.
function deriveBookingType() {
  if (normalizeBookingMode(state.booking.mode) === 'formule') return 'formule';
  const chosen = getChosenActivities();
  if (!chosen.length) return 'bowling';
  if (chosen.some(activity => getBookingActivityParticipants(activity, activity.options) < Number(state.booking.pax))) return 'visite';
  const planned = chosen.filter(item => item.planned);
  if (planned.length === 1 && chosen.length === 1) {
    // PLUSIEURS PARTIES DE LASER = PLUSIEURS RENDEZ-VOUS A PLACER, donc le fil
    // de visite (une etape par partie, une heure par etape). Le parcours direct
    // ne sait proposer QU'UNE heure : la 2e et la 3e partie partaient d'office
    // « sur place », sans que le client puisse choisir. La reservation reste de
    // type laser cote serveur (programReservationType le derive du programme) :
    // rien ne change pour la fiche, les mails ou le planning.
    const laserSeul = planned[0].id === 'laser_game';
    const parties = laserSeul ? Number((planned[0].options || {}).games || 1) : 1;
    if (laserSeul) return parties > 1 ? 'visite' : 'laser';
    return 'bowling';
  }
  return 'visite';
}

// Les activites cochees, dans l'ordre du catalogue du centre.
//
// Le panier se PASSE quand on veut lire un panier qui n'est pas encore celui du
// dossier : un complement de fin de reservation se fait verifier par le serveur
// AVANT d'etre adopte, donc son panier existe un instant sans etre le choix du
// client. Sans argument, la fonction lit exactement ce qu'elle lisait avant.
function getChosenActivities(panierPropose = null) {
  const selection = panierPropose && typeof panierPropose === 'object'
    ? panierPropose
    : (state.booking.activities && typeof state.booking.activities === 'object' ? state.booking.activities : {});
  const catalog = typeof getCenterActivities === 'function' ? getCenterActivities() : [];
  const list = catalog.length ? catalog : [
    { id: 'bowling', name: 'Bowling', planned: true, priceType: 'grid_bowling' },
    { id: 'laser_game', name: 'Laser Game', planned: true, priceType: 'grid_laser' },
  ];
  return list.filter(activity => selection[activity.id]).map(activity => ({ ...activity, options: selection[activity.id] || {} }));
}

function syncBookingTypeUi() {
  const dayStatus = typeof getCenterDayStatusFor === 'function' ? getCenterDayStatusFor(state.booking.date) : null;
  const off = dayStatus && Array.isArray(dayStatus.unavailableActivityIds) ? dayStatus.unavailableActivityIds : [];
  const mode = normalizeBookingMode(state.booking.mode);
  // Une activite fermee ce jour est DECOCHEE : l'ecran ne garde jamais un choix
  // mort, et le client n'arrive pas a l'etape des creneaux avec un programme
  // qui ne peut pas exister.
  if (state.booking.activities && off.length) {
    off.forEach(id => { delete state.booking.activities[id]; });
  }
  state.booking.mode = mode;
  state.booking.type = deriveBookingType();
  document.getElementById('segCarte').classList.toggle('active', mode === 'carte');
  document.getElementById('segFormule').classList.toggle('active', mode === 'formule');
  // La pastille du selecteur GLISSE jusqu'au choix (recette 3) : la classe du
  // conteneur pilote sa position, le CSS fait le mouvement.
  document.getElementById('segCarte').closest('.segmented')?.classList.toggle('is-formule', mode === 'formule');
  const picker = document.getElementById('activityPicker');
  if (picker) picker.classList.toggle('hidden', mode !== 'carte');
  document.getElementById('bowlingBlock').classList.add('hidden');
  document.getElementById('laserBlock').classList.add('hidden');
  document.getElementById('formuleBlock').classList.toggle('hidden', mode !== 'formule');
  renderActivityPicker(off);
  renderTypeAlert(off, dayStatus);
  syncProgressiveReveal();
  syncStatusDock();
}

// La grille d'activites se construit UNE fois, puis ne change que par des
// classes. Les tuiles restent compactes et les reglages des activites cochees
// vivent dans un bloc commun sous la grille. Aucune carte ne peut ainsi imposer
// sa hauteur aux voisines ni creer de trou dans la composition.
function renderActivityPicker(off = []) {
  const host = document.getElementById('activityPicker');
  if (!host) return;
  const catalog = typeof getCenterActivities === 'function' ? getCenterActivities() : [];
  // CATALOGUE VIDE : un panneau litteralement vide (innerHTML de longueur 0)
  // laissait le client devant 400 px de noir, sans un mot ni une piste. Le
  // meme etat d attente que la venue (.s1-placeholder) dit ce qui manque et ou
  // aller. Le libelle de l onglet vient du DOM, jamais d une chaine en dur.
  if (!catalog.length) {
    const ongletFormules = document.getElementById('segFormule');
    const nomFormules = (ongletFormules && ongletFormules.textContent.trim()) || 'Nos Formules';
    host.innerHTML = `<div class="s1-placeholder">
      <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><line x1="12" y1="8" x2="12" y2="12.5"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
      <strong>Aucune activité à la carte pour ce jour</strong>
      <span>Passez par « ${escapeHtml(nomFormules)} », ou dites-nous ce que vous cherchez.</span>
    </div>`;
    activityPickerSignature = '';
    renderProgramSummary();
    syncProgressiveReveal();
    syncStatusDock();
    return;
  }
  // Le PAX fait partie de la signature : le plafond des pastilles d'enfants
  // (plaine de jeux) suit le groupe. Sans lui, un groupe passe de 4 a 6 et le
  // compteur reste borne a 4. Reconstruire au changement de groupe est sans
  // danger : aucun press n'est en cours dans le picker a ce moment-la.
  const paxCeiling = Math.min(12, Math.max(1, Number(state.booking.pax) || 1));
  const signature = `${catalog.map(activity => activity.id).join(',')}|pax:${paxCeiling}`;
  if (signature !== activityPickerSignature) {
    buildActivityPicker(host, catalog);
    activityPickerSignature = signature;
  }
  syncActivityPickerState(off);
  renderProgramSummary();
  // Le choix vient peut-etre de naitre ou de mourir : la revelation du resume
  // et le dock telephone suivent le meme battement que le programme.
  syncProgressiveReveal();
  syncStatusDock();
}

let activityPickerSignature = '';

// Icones en trait, un dessin par activite. Une grille de huit rectangles de
// texte se lit comme un formulaire administratif ; la meme grille avec un objet
// reconnaissable par carte se lit d'un coup d'oeil.
// L objet servi quand le catalogue d un centre porte une activite qu on ne
// connait pas : un plus cercle, jamais un vide.
const ACTIVITY_ICON_FALLBACK = '<path d="M12 2.6a9.4 9.4 0 1 0 0 18.8 9.4 9.4 0 0 0 0-18.8Zm.9 4.6v3.9h3.9a.9.9 0 0 1 0 1.8h-3.9v3.9a.9.9 0 0 1-1.8 0v-3.9H7.2a.9.9 0 0 1 0-1.8h3.9V7.2a.9.9 0 0 1 1.8 0Z"/>';

const ACTIVITY_ICONS = {
  // Boule de bowling : les trois trous en negatif, pas trois points poses.
  bowling: '<path d="M12 2.6a9.4 9.4 0 1 0 0 18.8 9.4 9.4 0 0 0 0-18.8Zm-2.7 5.1a1.35 1.35 0 1 1 0 2.7 1.35 1.35 0 0 1 0-2.7Zm3.9-1.1a1.3 1.3 0 1 1 0 2.6 1.3 1.3 0 0 1 0-2.6Zm-2.2 5.2a1.3 1.3 0 1 1 0 2.6 1.3 1.3 0 0 1 0-2.6Z"/>',
  // Pistolet laser vu de profil, avec sa visee.
  laser_game: '<path d="M3.4 8.2h9.1l1.7-1.9h4.4a1.4 1.4 0 0 1 1.4 1.4v2.5a1.4 1.4 0 0 1-1.4 1.4h-2.2l-1 2.2a2.2 2.2 0 0 1-2 1.3h-1.2l-.9 3.6a1 1 0 0 1-1 .8H8.2a1 1 0 0 1-1-1.2l.7-3.2H5.6A2.2 2.2 0 0 1 3.4 14Z"/><circle cx="17.3" cy="9" r="1"/>',
  // Club, balle et trou : les trois signes du minigolf.
  minigolf_blacklight: '<path d="M9.6 2.6a.95.95 0 0 1 1.9 0v13.6a.95.95 0 0 1-1.9 0Z"/><path d="M11.9 3.1 18.6 5.4a.6.6 0 0 1 0 1.1l-6.7 2.3Z"/><ellipse cx="11.2" cy="18.4" rx="6.4" ry="2.4" opacity=".3"/><circle cx="17.9" cy="16.9" r="2"/>',
  golf_oclock: '<path d="M6.6 2.6a.95.95 0 0 1 1.9 0v14.2a.95.95 0 0 1-1.9 0Z"/><path d="M8.9 3.1 15.2 5.3a.6.6 0 0 1 0 1.1L8.9 8.6Z"/><path d="M16.6 12.4a4.7 4.7 0 1 0 0 9.4 4.7 4.7 0 0 0 0-9.4Zm.5 2.3v2.2l1.5 1a.8.8 0 0 1-.9 1.3l-1.9-1.3a.8.8 0 0 1-.4-.7v-2.5a.85.85 0 0 1 1.7 0Z"/>',
  // Queue et triangle de boules, vus de dessus.
  billards: '<path d="M20.3 2.5a1.3 1.3 0 0 1 1.8 1.8l-1 1-1.8-1.8ZM18.1 4.7l1.8 1.8-7.4 7.4a4.9 4.9 0 0 0-1.8-1.8Z"/><circle cx="7.4" cy="16.6" r="4.9"/><path d="M5 14.2a3.4 3.4 0 0 0 4.8 4.8" fill="none" stroke="currentColor" stroke-width="1.4" opacity=".45"/>',
  // Borne d'arcade : ecran, joystick, deux boutons.
  arcade_time: '<path d="M6.2 2.6h11.6a2.4 2.4 0 0 1 2.4 2.4v11a2.4 2.4 0 0 1-2.4 2.4h-3.1l.5 2.1h1.4a.85.85 0 0 1 0 1.7H7.4a.85.85 0 0 1 0-1.7h1.4l.5-2.1H6.2a2.4 2.4 0 0 1-2.4-2.4V5a2.4 2.4 0 0 1 2.4-2.4Zm.4 2.6v5.9h10.8V5.2Zm2.3 8.2a1.15 1.15 0 1 0 0 2.3 1.15 1.15 0 0 0 0-2.3Zm4 0a1.15 1.15 0 1 0 0 2.3 1.15 1.15 0 0 0 0-2.3Zm3.4 0a1.15 1.15 0 1 0 0 2.3 1.15 1.15 0 0 0 0-2.3Z"/>',
  // Toboggan avec son echelle : la plaine de jeu, pas une abstraction.
  playground: '<path d="M16.4 3.2h1.9v15.9h-1.9Zm4.4 0h1.9v15.9h-1.9Z"/><path d="M17.4 6.4h4.9v1.7h-4.9Zm0 4.1h4.9v1.7h-4.9Zm0 4.1h4.9v1.7h-4.9Z" opacity=".75"/><path d="M16 4.6v2.1c-2.8 1.3-4.6 3.4-5.5 6.4-.6 2-2 3.6-4.2 4.9a.95.95 0 0 1-1-1.6c1.8-1.1 2.9-2.3 3.4-3.9 1.1-3.7 3.5-6.3 7.3-7.9Z"/><path d="M2 20.9h13.4a.95.95 0 0 0 0-1.9H2a.95.95 0 0 0 0 1.9Z"/>',
  // Quilles courtes du duckpin : deux quilles trapues, sa signature.
  duckpin_bowling: '<path d="M8.5 2.4c1.5 0 2.5 1.3 2.5 2.7 0 1.2-.8 2.2-.8 3.2 0 1.6 1.6 2.7 1.6 5.1 0 2.1-1.4 3.4-3.3 3.4S5.2 15.5 5.2 13.4c0-2.4 1.6-3.5 1.6-5.1 0-1-.8-2-.8-3.2 0-1.4 1-2.7 2.5-2.7Z"/><path d="M16.4 5.6c1.3 0 2.1 1.1 2.1 2.3 0 1-.7 1.9-.7 2.7 0 1.4 1.4 2.3 1.4 4.4 0 1.8-1.2 2.9-2.8 2.9s-2.8-1.1-2.8-2.9c0-2.1 1.4-3 1.4-4.4 0-.8-.7-1.7-.7-2.7 0-1.2.8-2.3 2.1-2.3Z" opacity=".8"/><path d="M3.4 20.8h17.2a.9.9 0 0 0 0-1.8H3.4a.9.9 0 0 0 0 1.8Z"/>',
  // Coureur : le Fun Run se vend a la session, l'icone dit le mouvement.
  fun_run: '<path d="M14.6 2.5a2 2 0 1 1 0 4 2 2 0 0 1 0-4Z"/><path d="M12.4 7.6c.9-.5 2-.3 2.7.4l1.9 2 2.5.9a1 1 0 0 1-.7 1.9l-2.9-1.1a1 1 0 0 1-.4-.3l-.7-.7-.8 3 2 2.1a1 1 0 0 1 .3.6l.4 3.6a1 1 0 0 1-2 .2l-.3-3.2-2.8-2.9a1 1 0 0 1-.3-.9l.5-2.7-1.3 1.4-2 3a1 1 0 0 1-1.7-1.1l2.1-3.2a1 1 0 0 1 .2-.2Z"/><path d="M2.6 9.4h4.2a.9.9 0 0 1 0 1.8H2.6a.9.9 0 0 1 0-1.8Zm.6 3.4h3a.9.9 0 0 1 0 1.8h-3a.9.9 0 0 1 0-1.8Z" opacity=".5"/>',
  party_table: '<path d="M11.2 2.2c.6.7 1 1.3 1 1.9a1.2 1.2 0 0 1-2.4 0c0-.6.4-1.2 1-1.9a.3.3 0 0 1 .4 0Z"/><path d="M10.1 5.6h1.8v3.1h-1.8Z"/><path d="M6.6 8.7h8.8a2.4 2.4 0 0 1 2.4 2.4v1.6c-1 0-1.4.9-2.4.9s-1.4-.9-2.4-.9-1.4.9-2.4.9-1.4-.9-2.4-.9-1.4.9-2.4.9v-2.5a2.4 2.4 0 0 1 2.4-2.4Z"/><path d="M4.2 15.1c1 0 1.4-.9 2.4-.9s1.4.9 2.4.9 1.4-.9 2.4-.9 1.4.9 2.4.9 1.4-.9 2.4-.9 1.4.9 2.4.9v3.3a2.4 2.4 0 0 1-2.4 2.4H6.6a2.4 2.4 0 0 1-2.4-2.4Z" opacity=".75"/>',
};

// LA SIGNATURE SE RECADRE DANS LE SVG, JAMAIS PAR LA MISE EN PAGE (2026-09-07).
// Deux tentatives ont ete refusees par les gates, chacune pour une bonne raison.
// Un dessin surdimensionne pose en negatif avec overflow:hidden sur la carte :
// la carte devient une boite qui COUPE son contenu, et le gate un-ecran le lit
// comme de l information qui disparait sans signal. Le meme dessin avec
// clip-path : ca masque la peinture mais ca ne stoppe PAS la propagation du
// debordement, qui remonte jusqu au corps de l etape ; en embarque, ce corps est
// le defileur, donc le cadre se mettait a defiler dans lui-meme au lieu de
// grandir. La seule facon propre : le recadrage vit dans le viewBox et
// l inclinaison dans un <g>, ou rien de tout cela n existe pour la mise en page.
// Le viewBox 19.2 x 18.4 sur 24 montre le haut-gauche de l objet : c est
// exactement le cadrage que donnait le debordement, sans un pixel de trop.
function activitySignMarkup(activityId) {
  const paths = ACTIVITY_ICONS[activityId] || ACTIVITY_ICON_FALLBACK;
  return `<svg viewBox="0 0 19.2 18.4" fill="currentColor" aria-hidden="true"><g transform="rotate(-9 12 12)">${paths}</g></svg>`;
}

function activityIconMarkup(activityId) {
  const paths = ACTIVITY_ICONS[activityId] || ACTIVITY_ICON_FALLBACK;
  return `<svg width="22" height="22" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">${paths}</svg>`;
}

// Tous les blocs de reglages existent des le premier rendu. Cocher une activite
// ne reconstruit ni la grille ni les boutons, ce qui preserve le focus.
// Une activite payee PAR ENFANT (plaine de jeux) se regle en nombre d'enfants :
// 4 adultes + 2 enfants ne paient pas 6 entrees. La detection passe par la
// DONNEE (unitLabel du catalogue), jamais par un id de centre.
function activityCountsChildren(activity) {
  return Boolean(activity && activity.priceType === 'per_pax' && /enfant/i.test(activity.unitLabel || ''));
}

function activityHasConfigurableOptions(activity) { return Boolean(activity); }

function activityConfigHint(activity) {
  if (!activity) return '';
  if (activityCountsChildren(activity)) return 'Combien d’enfants ?';
  if (activity.priceType === 'grid_laser') return 'Combien de parties ?';
  if (activity.priceType === 'per_unit_hour') return 'Combien de tables, et combien de temps ?';
  return 'Combien de temps ?';
}

// Le nom accessible d'une carte d'activite est EXPLICITE (aria-label), jamais
// deduit de la concatenation des spans visuels : un arbre d'accessibilite qui
// rend « button » sans texte interdit de reserver au lecteur d'ecran. Le nom
// porte l'activite et son prix, l'etat coche vit dans aria-pressed.
function activityToggleLabel(activity, { closed = false, pax = 1 } = {}) {
  if (!activity) return '';
  if (closed) return `${activity.name}, fermé ce jour`;
  const hint = activityPriceHint(activity, pax);
  return hint ? `${activity.name}, ${hint}` : activity.name;
}

function buildActivityPicker(host, catalog) {
  const pax = Math.max(1, Number(state.booking.pax) || 1);
  const cards = catalog.map((activity, index) => `
      <div class="activity-card" data-activity="${escapeHtml(activity.id)}" style="--i:${index}">
        <span class="activity-sign" aria-hidden="true">${activitySignMarkup(activity.id)}</span>
        <button type="button" class="activity-toggle" aria-pressed="false" aria-label="${escapeHtml(activityToggleLabel(activity, { pax }))}" onclick="toggleBookingActivity('${escapeHtml(activity.id)}')">
          <span class="activity-icon">${activityIconMarkup(activity.id)}</span>
          <span class="activity-text">
            <span class="activity-name">${escapeHtml(activity.name)}</span>
            <span class="activity-price" data-role="price">${escapeHtml(activityPriceHint(activity, pax))}</span>
            <span class="activity-price-compact" data-role="price-compact" aria-hidden="true">${escapeHtml(activityPriceHintCompact(activity, pax))}</span>
            <span class="activity-note"${activity.note ? ` title="${escapeHtml(activity.note)}"` : ''}>${activity.note ? escapeHtml(activity.note) : ''}</span>
          </span>
          <span class="activity-check" aria-hidden="true">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>
          </span>
        </button>
      </div>`).join('');
  const settings = catalog.filter(activityHasConfigurableOptions).map(activity => `
      <section class="activity-config-row" data-activity-options="${escapeHtml(activity.id)}" aria-label="Réglages ${escapeHtml(activity.name)}" aria-hidden="true">
        <div class="activity-config-row-inner">
          <div class="activity-config-label">
            <span class="activity-config-mark" aria-hidden="true">${activityIconMarkup(activity.id)}</span>
            <span class="activity-config-name">${escapeHtml(activity.name)}</span>
            <span class="activity-config-hint">${escapeHtml(activityConfigHint(activity))}</span>
          </div>
          <div class="activity-config-controls" data-role="options">${renderActivityOptions(activity, state.booking.activities?.[activity.id] || {}, pax)}</div>
        </div>
      </section>`).join('');
  host.innerHTML = `
    <div class="activity-grid" data-role="activity-grid">${cards}</div>
    <div class="activity-configurator" data-role="activity-configurator" aria-hidden="true">
      <button type="button" class="s1-options-back" onclick="showMobileOptionsPage(false)">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="15 18 9 12 15 6"/></svg>
        Modifier les activités
      </button>
      <div class="activity-configurator-head">
        <span class="activity-configurator-title">Réglez votre visite</span>
        <span class="activity-configurator-count" data-role="config-count"></span>
      </div>
      <p class="activity-configurator-lead">Le prix suit vos choix, et rien ne se paie à l’avance.</p>
      <div class="activity-config-list">${settings}</div>
    </div>`;
}

// L'etat, et rien que l'etat : classes, aria, libelles. Aucun noeud n'est
// remplace, donc les transitions CSS partent de la valeur courante au lieu de
// repartir de zero (elles restent interruptibles : on peut cocher/decocher vite
// sans saccade).
// LES DUREES QUI NE RENTRENT PLUS AVANT LA FERMETURE : pastilles verrouillees
// (visibles, jamais retirees du catalogue) et une note qui dit ce qu il reste.
// Rien ne se verrouille quand on ne connait pas l horaire du jour.
function syncOptionsFermeture(optionsRow, activity, chosenOptions, visible = true) {
  if (!optionsRow || !activity) return;
  // Une activite non retenue n a rien a dire : sa rangee est masquee, et une
  // note posee dedans serait quatre fois la meme phrase dans la page.
  if (!visible) {
    const ancienne = optionsRow.querySelector('[data-role="closing-note"]');
    if (ancienne) ancienne.remove();
    return;
  }
  const restant = heuresJusquALaFermeture();
  const heuresDe = (pill) => {
    const key = pill.getAttribute('data-opt');
    const valeur = Number(pill.getAttribute('data-val'));
    if (!Number.isFinite(valeur)) return null;
    if (key === 'duration' || key === 'hours') return valeur;
    if (key === 'minutes') return valeur / 60;
    if (key === 'games') {
      const option = LASER_GAME_OPTIONS.find((item) => Number(item.games) === valeur);
      return option ? Number(option.value) : null;
    }
    return null;
  };
  const durees = [];
  optionsRow.querySelectorAll('[data-opt]').forEach((pill) => {
    const heures = heuresDe(pill);
    if (heures === null) return;
    durees.push(heures);
    const trop = restant !== null && heures > restant + 0.001;
    if (trop) {
      pill.setAttribute('data-too-late', '1');
      pill.setAttribute('title', 'Plus le temps avant la fermeture');
      pill.disabled = true;
    } else {
      pill.removeAttribute('data-too-late');
      pill.removeAttribute('title');
      pill.disabled = false;
    }
  });
  const existante = optionsRow.querySelector('[data-role="closing-note"]');
  const html = noteFermetureOptions(activity.id, durees);
  if (!html) {
    if (existante) existante.remove();
    return;
  }
  if (existante) {
    existante.outerHTML = html;
    return;
  }
  const rangee = optionsRow.querySelector('.activity-option-row');
  if (rangee) rangee.insertAdjacentHTML('afterend', html);
  else optionsRow.insertAdjacentHTML('beforeend', html);
}

function syncActivityPickerState(off = []) {
  const host = document.getElementById('activityPicker');
  if (!host) return;
  const selection = state.booking.activities || (state.booking.activities = {});
  const pax = Math.max(1, Number(state.booking.pax) || 1);
  const optionsRows = new Map([...host.querySelectorAll('[data-activity-options]')]
    .map(row => [row.getAttribute('data-activity-options'), row]));
  let visibleConfigCount = 0;
  host.querySelectorAll('.activity-card').forEach(card => {
    const activityId = card.getAttribute('data-activity');
    const activity = typeof getCenterActivity === 'function' ? getCenterActivity(activityId) : null;
    const chosen = Boolean(selection[activityId]);
    const linePlayers = activity ? getBookingActivityParticipants(activity, selection[activityId] || {}, pax) : pax;
    const closed = off.includes(activityId);
    card.classList.toggle('is-on', chosen && !closed);
    card.classList.toggle('is-off', closed);
    const toggle = card.querySelector('.activity-toggle');
    if (toggle) {
      toggle.setAttribute('aria-pressed', chosen && !closed ? 'true' : 'false');
      toggle.disabled = closed;
      toggle.setAttribute('aria-disabled', closed ? 'true' : 'false');
      // Le nom accessible suit l'etat reel : prix du jour, fermeture du jour.
      const label = activityToggleLabel(activity, { closed, pax });
      if (label && toggle.getAttribute('aria-label') !== label) toggle.setAttribute('aria-label', label);
    }
    const price = card.querySelector('[data-role="price"]');
    if (price && activity) price.textContent = closed ? 'Fermé ce jour' : activityPriceHint(activity, linePlayers);
    const priceCompact = card.querySelector('[data-role="price-compact"]');
    if (priceCompact && activity) priceCompact.textContent = closed ? 'Fermé ce jour' : activityPriceHintCompact(activity, linePlayers);
    const optionsRow = optionsRows.get(activityId);
    if (!optionsRow) return;
    const showOptions = chosen && !closed;
    optionsRow.classList.toggle('is-visible', showOptions);
    optionsRow.setAttribute('aria-hidden', showOptions ? 'false' : 'true');
    if (showOptions) visibleConfigCount += 1;
    if (!showOptions && optionsRow.contains(document.activeElement) && toggle) toggle.focus();
    // Le CTA du telephone dit ou il mene (Continuer vers la page options, ou
    // directement les disponibilites) : il suit chaque coche.
    if (typeof syncStepOneCta === 'function') syncStepOneCta();
    optionsRow.querySelectorAll('button').forEach(button => { button.tabIndex = showOptions ? 0 : -1; });
    // Les options ne sont PAS reecrites : on bascule seulement la pastille
    // active. Les reconstruire a chaque clic detruirait le retour visuel du
    // press en cours et ferait perdre le focus.
    const chosenOptions = selection[activityId] || {};
    // Le defaut depend de la CLE : « 1 » vaut pour une duree de bowling ou un
    // nombre de tables, jamais pour une session de 15 minutes ni pour une
    // activite dont la duree minimale est d'une heure. Un defaut faux
    // n'allume aucune pastille et la carte parait vide. Et le compte d'enfants
    // vaut le GROUPE ENTIER (meme regle que le serveur et que le premier
    // rendu) : avec « 1 », la pastille 1 s'allumait alors que le champ libre
    // affichait 8, deux etats actifs en meme temps.
    const activityDefaut = (key) => {
      if (key === 'minutes') return FUN_RUN_OPTIONS[0].minutes;
      if (key === 'hours') return activityHourChoices(activity || {})[0].hours;
      if (key === 'participants') return Math.min(30, Math.max(1, pax));
      return 1;
    };
    optionsRow.querySelectorAll('[data-opt]').forEach(pill => {
      const key = pill.getAttribute('data-opt');
      const value = Number(pill.getAttribute('data-val'));
      const courant = chosenOptions[key] == null ? activityDefaut(key) : Number(chosenOptions[key]);
      pill.classList.toggle('active', courant === value);
    });
    // CE QUI NE RENTRE PLUS AVANT LA FERMETURE (Movsar, 2026-09-17). La
    // contrainte est VIVANTE : elle depend du jour choisi ET de l heure qu il
    // est. Elle vit donc ici, dans la synchronisation d etat, et pas seulement
    // dans le balisage, qui n est pas reecrit a chaque clic.
    syncOptionsFermeture(optionsRow, activity, chosenOptions, showOptions);
    // Le stepper d'enfants suit la valeur (sans voler une frappe en cours),
    // les boutons -/+ se desactivent aux bornes, la note de prix recalcule.
    if (activity) {
      const bounds = activityParticipantsBounds(activityId, pax);
      const ceiling = bounds.max;
      const current = getBookingActivityParticipants(activity, chosenOptions, pax);
      const field = optionsRow.querySelector('[data-role="participants-input"]');
      if (field) {
        field.max = String(ceiling);
        field.min = String(bounds.min);
        if (document.activeElement !== field) field.value = String(current);
      }
      const minus = optionsRow.querySelector('[data-role="participants-minus"]');
      const plus = optionsRow.querySelector('[data-role="participants-plus"]');
      if (minus) minus.disabled = current <= bounds.min;
      if (plus) plus.disabled = current >= ceiling;
      const note = optionsRow.querySelector('[data-role="participants-note"]');
      const noun = activityCountsChildren(activity) ? 'enfant' : 'joueur';
      if (note) note.textContent = `${current} ${noun}${current > 1 ? 's' : ''} sur ${pax} personnes présentes`;
    }
  });
  const configurator = host.querySelector('[data-role="activity-configurator"]');
  if (configurator) {
    configurator.classList.toggle('is-visible', visibleConfigCount > 0);
    configurator.setAttribute('aria-hidden', visibleConfigCount > 0 ? 'false' : 'true');
  }
  // « 2 reglages actifs » comptait des rangees, pas quelque chose que le client
  // possede. Il lit maintenant ce qu il a a faire, dans ses mots.
  const count = host.querySelector('[data-role="config-count"]');
  if (count) count.textContent = `${visibleConfigCount} activité${visibleConfigCount > 1 ? 's' : ''} à régler`;
}

// Ce qu'on annonce sous le nom : un prix quand le centre l'a saisi, la mention
// honnete "réglé sur place" sinon. Jamais 0 EUR pour "on ne sait pas".
function activityPriceHint(activity, pax) {
  if (!activity) return '';
  if (activity.id === 'arcade_time' && activity.arcadeOffers?.enabled !== false) { const prices=[...(activity.arcadeOffers?.timeOffers||[]),...(activity.arcadeOffers?.creditOffers||[])].filter(o=>o.enabled!==false).map(o=>Number(o.price)).filter(Number.isFinite); if(prices.length) return `dès ${formatMoneyCentimes(Math.min(...prices))} par carte`; }
  if (activity.priceType === 'grid_bowling') {
    // Un centre qui vend AUX PARTIES annonce un prix PAR PERSONNE : « des 6 EUR
    // par personne », jamais « des 20 EUR la piste », qui serait le tarif d un
    // autre centre. Donnee de centre, pas constante du produit.
    const games = typeof getBowlingGameOptions === 'function' ? getBowlingGameOptions(state.booking.date, { pax: Math.max(1, Number(state.booking.pax) || 1), laneCount: getRequiredLaneCount('bowling', Math.max(1, Number(state.booking.pax) || 1), '') }) : null;
    if (games) return games.length ? `dès ${games[0].price}€ par personne` : 'réglé sur place';
    return `dès ${DURATION_OPTIONS[0].price}€ la piste`;
  }
  if (activity.priceType === 'grid_laser') return `dès ${LASER_GAME_OPTIONS[0].price}€ par joueur`;
  if (activity.priceType === 'grid_fun_run') return `dès ${FUN_RUN_OPTIONS[0].price}€ la session`;
  if (activity.priceValue == null) return 'réglé sur place';
  return `${activity.priceValue}€ ${activity.unitLabel || ''}`.trim();
}

// La MEME information en souffle court, pour la carte compacte du telephone :
// « dès 20€/piste » au lieu de « dès 20€ la piste ». Une unite inconnue reste
// telle quelle : mieux vaut long que faux.
function activityPriceHintCompact(activity, pax) {
  const full = activityPriceHint(activity, pax);
  return full
    .replace(' la piste', '/piste')
    .replace(' par piste', '/piste')
    .replace(' la session', '/session')
    .replace(' par session', '/session')
    .replace(' par personne', '/pers.')
    .replace(' par joueur', '/joueur')
    .replace(' par enfant', '/enfant')
    .replace(' par table et par heure', '/table/h');
}

// Les durees vendables d'une activite au temps. Elles se DERIVENT des bornes
// du catalogue au lieu d'etre une liste en dur : c'est ce qui fait qu'un
// billard sans demi-heure (borne basse a 60 min) n'en propose plus, sans
// toucher au tunnel.
// LE NOMBRE D UNITES VENDABLES VIENT DU CATALOGUE (2026-08-31). Une liste
// [1, 2, 3, 4] ecrite dans le code plafonnait TOUT centre a quatre : celui qui
// declare six billards ne pouvait en vendre que quatre, dans le tunnel comme
// au comptoir. Meme classe de defaut que la grille Tarifs du 2026-08-17 : une
// constante figee au deploiement a la place de la donnee du tenant.
function activityUnitChoices(activity) {
  const dotation = Math.trunc(Number(activity && activity.units) || 0);
  // La dotation du centre (reglable dans Etablissement, 50 au plus).
  const max = dotation > 0 ? Math.min(50, dotation) : 4;
  return Array.from({ length: max }, (_, index) => index + 1);
}

function activityHourChoices(activity) {
  const min = Math.max(15, Number(activity.minMinutes) || 60);
  const max = Math.max(min, Number(activity.maxMinutes) || min);
  // Le PAS vient de l'activite : le billard se vend a l'heure pleine, donc ni
  // demi-heure ni 1h30. Une liste en dur ici obligerait a la corriger a
  // chaque activite qui ne se vend pas comme les autres.
  const pas = Math.max(15, Number(activity.stepMinutes) || 30);
  const minutes = [];
  for (let m = min; m <= max; m += pas) minutes.push(m);
  if (!minutes.length) minutes.push(min);
  return minutes.sort((a, b) => a - b).map(m => ({
    hours: m / 60,
    label: m < 60 ? `${m} min` : (m % 60 === 0 ? `${m / 60}h` : `${Math.floor(m / 60)}h${m % 60}`),
  }));
}

// Les options d'une activite. data-opt / data-val servent a
// syncActivityPickerState : il bascule la pastille active SANS reconstruire le
// bloc, donc sans casser le retour au press ni le focus d'un select ouvert.
// LE TEMPS QU IL RESTE AVANT LA FERMETURE, pour la date choisie (Movsar,
// 2026-09-17). Aujourd hui : de la prochaine demie jusqu a la fermeture,
// exactement la borne que la liste des creneaux applique deja
// (filterPastSlotsForDate). Un autre jour : la journee entiere. Rend null
// quand on ne sait pas (jour ferme, horaires absents) : on ne retire alors
// AUCUNE option, on n invente pas une contrainte.
function heuresJusquALaFermeture() {
  if (typeof getSchedule !== 'function') return null;
  const schedule = getSchedule(state.booking.date, state.isHolidayMode);
  if (!schedule || !Number.isFinite(Number(schedule.close))) return null;
  const aujourdhui = typeof todayStr === 'function' && state.booking.date === todayStr();
  const debut = aujourdhui && typeof roundUpHalfHour === 'function' && typeof currentTimeDecimal === 'function'
    ? Math.max(Number(schedule.open), roundUpHalfHour(currentTimeDecimal()))
    : Number(schedule.open);
  return Math.max(0, Number(schedule.close) - debut);
}

// L heure de fermeture, dite comme le client la lit.
function libelleFermetureDuJour() {
  if (typeof getSchedule !== 'function') return '';
  const schedule = getSchedule(state.booking.date, state.isHolidayMode);
  if (!schedule || !Number.isFinite(Number(schedule.close))) return '';
  const close = Number(schedule.close);
  if (close >= 24) return 'minuit';
  return typeof formatClockShort === 'function' ? formatClockShort(numToTime(close)) : numToTime(close);
}

// Les attributs d une option qui ne rentre plus : elle reste VISIBLE (le
// client voit ce que le centre vend) mais elle ne se prend pas.
function attributsOptionTropLongue(heures) {
  const restant = heuresJusquALaFermeture();
  if (restant === null || !(Number(heures) > restant + 0.001)) return '';
  return ' disabled data-too-late="1" title="Plus le temps avant la fermeture"';
}

// LA NOTE SOUS LES OPTIONS : ce qu il reste, et la duree ramenee quand elle
// l a ete. Elle n existe que s il y a quelque chose a dire.
function noteFermetureOptions(activityId, durees) {
  const restant = heuresJusquALaFermeture();
  if (restant === null) return '';
  const ramenee = dureesRamenees.find((item) => item.activityId === activityId);
  const tropLongue = durees.some((heures) => Number(heures) > restant + 0.001);
  if (!tropLongue && !ramenee) return '';
  const fermeture = libelleFermetureDuJour();
  const reste = typeof formatDurationLabel === 'function' ? formatDurationLabel(restant) : `${restant} h`;
  const phrases = [`Il reste ${reste} avant la fermeture${fermeture ? ` (${fermeture})` : ''}.`];
  if (ramenee) phrases.push(`Durée ramenée à ${ramenee.label}.`);
  return `<div class="activity-option-note" data-role="closing-note">${escapeHtml(phrases.join(' '))}</div>`;
}

// LES DUREES RAMENEES a l ouverture de l ecran des reglages et avant de
// verifier les disponibilites : une duree qui ne rentre plus est remplacee
// par la plus longue qui tient, et la note le DIT. Sans ca, le client partait
// avec 2 h de bowling un soir ou il restait 30 min et l ecran suivant
// n avait plus rien a lui proposer.
let dureesRamenees = [];
function ajusterDureesAvantFermeture() {
  const restant = heuresJusquALaFermeture();
  dureesRamenees = [];
  if (restant === null) return false;
  let change = false;
  (typeof getChosenActivities === 'function' ? getChosenActivities() : []).forEach((activity) => {
    const options = (state.booking.activities || {})[activity.id] || {};
    let paliers = [];
    let champ = '';
    if (activity.priceType === 'grid_bowling') {
      const participants = getBookingActivityParticipants(activity, options);
      const parties = typeof getBowlingGameOptions === 'function'
        ? getBowlingGameOptions(state.booking.date, { pax: participants, laneCount: getRequiredLaneCount('bowling', participants, '') })
        : null;
      paliers = (parties && parties.length ? parties : DURATION_OPTIONS).map((option) => ({ valeur: Number(option.value), heures: Number(option.value), label: option.label }));
      champ = 'duration';
    } else if (activity.priceType === 'grid_laser') {
      paliers = LASER_GAME_OPTIONS.map((option) => ({ valeur: Number(option.games), heures: Number(option.value), label: option.label }));
      champ = 'games';
    } else if (activity.priceType === 'grid_fun_run') {
      paliers = FUN_RUN_OPTIONS.map((option) => ({ valeur: Number(option.minutes), heures: Number(option.minutes) / 60, label: option.label }));
      champ = 'minutes';
    } else {
      return;
    }
    const courant = Number(options[champ]) || Number(paliers[0].valeur);
    const palierCourant = paliers.find((palier) => palier.valeur === courant) || paliers[0];
    if (!(palierCourant.heures > restant + 0.001)) return;
    const tiennent = paliers.filter((palier) => palier.heures <= restant + 0.001);
    if (!tiennent.length) return;
    const cible = tiennent[tiennent.length - 1];
    state.booking.activities = state.booking.activities || {};
    state.booking.activities[activity.id] = { ...options, [champ]: cible.valeur };
    dureesRamenees.push({ activityId: activity.id, label: cible.label });
    change = true;
  });
  if (change) save();
  return change;
}

function getBookingActivityParticipants(activity, options = {}, pax = state.booking.pax) {
  const bounds = activityParticipantsBounds(activity.id, pax);
  const requested = options.participants == null ? bounds.max : Number(options.participants);
  return Math.min(bounds.max, Math.max(bounds.min, Number.isFinite(requested) ? Math.trunc(requested) : bounds.max));
}

function renderActivityOptions(activity, options = {}, pax = state.booking.pax) {
  if (!activity) return '';
  const id = escapeHtml(activity.id);
  const bounds = activityParticipantsBounds(activity.id, pax);
  const current = getBookingActivityParticipants(activity, options, pax);
  const children = activityCountsChildren(activity);
  const noun = children ? 'enfant' : 'joueur';
  const counter = `<div class="activity-option-group"><span class="activity-option-legend">${children ? 'Enfants' : 'Joueurs'}</span>
    <div class="child-stepper">
      <button type="button" class="child-step-btn" data-role="participants-minus" aria-label="${escapeHtml(activity.name)} : retirer un ${noun}" ${current <= bounds.min ? 'disabled' : ''} onclick="stepBookingChildren('${id}',-1)">−</button>
      <input type="number" class="input participants-input" data-role="participants-input" min="${bounds.min}" max="${bounds.max}" inputmode="numeric" value="${current}" aria-label="${escapeHtml(activity.name)} : nombre de ${noun}s" oninput="setBookingActivityOption('${id}','participants',this.value)">
      <button type="button" class="child-step-btn" data-role="participants-plus" aria-label="${escapeHtml(activity.name)} : ajouter un ${noun}" ${current >= bounds.max ? 'disabled' : ''} onclick="stepBookingChildren('${id}',1)">+</button>
    </div><div class="activity-option-note" data-role="participants-note">${current} ${noun}${current > 1 ? 's' : ''} sur ${pax} personnes présentes</div></div>`;
  return counter + renderActivityOptionsWithoutParticipants(activity, options, current);
}

function getStaffArcadeOfferDetail(item) {
  const offer = item && item.arcadeOffer;
  if (!offer) return '';
  const cards = Math.max(1, Math.trunc(Number(item.cards) || Number(item.participants) || 1));
  const number = n => Number(n).toLocaleString('fr-BE');
  const amount = offer.mode === 'time'
    ? `${number(offer.minutes)} min par carte`
    : `${number(offer.credits)} crédits + ${number(offer.bonusCredits || 0)} offerts = ${number(offer.totalCredits ?? (Number(offer.credits) + Number(offer.bonusCredits || 0)))} crédits par carte`;
  return `${cards} carte${cards > 1 ? 's' : ''} · ${amount}`;
}

function renderStaffArcadeOptions(activity, options, participants, context) {
  const offers = activity && activity.arcadeOffers;
  if (!offers || offers.enabled === false) { const saved=getArcadeOfferQuote(activity,options,participants); return `<div class="activity-option-note">${escapeHtml(saved ? getStaffArcadeOfferDetail({cards:saved.cards,arcadeOffer:saved.offer}) : 'Tarif à confirmer à l’accueil.')}${saved ? ` · ${formatMoneyCentimes(saved.price)}` : ''}</div>`; }
  const quote = getArcadeOfferQuote(activity, options, participants);
  // Le formulaire classique partage les offres, pas le langage visuel du SaaS.
  if (context === 'booking' && !document.body.classList.contains('staff-mode')) {
    const button = (mode, offer) => `<button type="button" class="qb-dur-btn ${options.arcadeMode === mode && options.arcadeOfferId === offer.id ? 'active' : ''}" onclick="setStaffArcadeOption('${context}','arcadeMode','${escapeHtml(mode)}','${escapeHtml(offer.id)}')">${mode === 'time' ? `${offer.minutes} min à volonté` : `${offer.credits} + ${offer.bonusCredits || 0} crédits`}<small>${formatMoneyCentimes(offer.price)} / carte</small></button>`;
    return `<div class="qb-visit-options"><span class="qb-opt-legend">Au temps</span>${(offers.timeOffers || []).filter(o => o.enabled !== false).map(o => button('time', o)).join('')}</div><div class="qb-visit-options"><span class="qb-opt-legend">En crédits</span>${(offers.creditOffers || []).filter(o => o.enabled !== false).map(o => button('credit', o)).join('')}</div>`
      + (options.arcadeMode === 'credit' ? `<label class="field">Cartes<input class="input" type="number" min="1" max="1000" step="1" value="${quote?.cards || participants}" aria-label="Nombre de cartes Arcades" onchange="setStaffArcadeOption('${context}','cards',this.value)"></label>` : '')
      + `<div class="activity-option-note">${escapeHtml(quote ? getStaffArcadeOfferDetail({cards:quote.cards, arcadeOffer:quote.offer}) : 'Choisissez une offre.')}${quote ? ` · ${formatMoneyCentimes(quote.price)}` : ''}</div>`;
  }
  const button = (mode, offer) => `<button type="button" class="qb-dur-btn dossier-option ${options.arcadeMode === mode && options.arcadeOfferId === offer.id ? 'active' : ''}" onclick="setStaffArcadeOption('${context}','arcadeMode','${escapeHtml(mode)}','${escapeHtml(offer.id)}')"><span>${mode === 'time' ? `${offer.minutes} min à volonté` : `${offer.credits} + ${offer.bonusCredits || 0} crédits`}</span><small>${formatMoneyCentimes(offer.price)} / carte</small></button>`;
  return `<div class="staff-arcade-options"><div class="qb-visit-options staff-option-group"><span class="qb-opt-legend staff-option-label">Au temps</span>${(offers.timeOffers || []).filter(o => o.enabled !== false).map(o => button('time', o)).join('')}</div><div class="qb-visit-options staff-option-group"><span class="qb-opt-legend staff-option-label">En crédits</span>${(offers.creditOffers || []).filter(o => o.enabled !== false).map(o => button('credit', o)).join('')}</div>`
    + (options.arcadeMode === 'credit' ? `<label class="field">Cartes<input class="input" type="number" min="1" max="1000" step="1" value="${quote?.cards || participants}" aria-label="Nombre de cartes Arcades" onchange="setStaffArcadeOption('${context}','cards',this.value)"></label>` : '')
    + `<div class="activity-option-note">${escapeHtml(quote ? getStaffArcadeOfferDetail({cards:quote.cards, arcadeOffer:quote.offer}) : 'Choisissez une offre.')}${quote ? ` · ${formatMoneyCentimes(quote.price)}` : ''}</div></div>`;
}

function setStaffArcadeOption(context, key, value, offerId) {
  let options;
  if (context === 'booking') options = state.booking.activities.arcade_time;
  else if (context === 'edit') options = state.editState.programmeEdite.othersOptions.arcade_time ||= {};
  else options = getQuickVisitOptions('arcade_time');
  if (!options) return;
  delete options.arcadeOffer;
  if (context === 'edit' && options.upsell) { delete options.upsell; toast('Offre retirée du devis : le nouveau choix est tarifé au catalogue.'); }
  if (key === 'cards') options.cards = Math.min(1000, Math.max(1, Math.trunc(Number(value) || 1)));
  else { options.arcadeMode = value; options.arcadeOfferId = offerId; if (value === 'time') delete options.cards; }
  if (context === 'booking') { clearCurrentBookingChoice(); applyChosenActivitiesToBooking(); syncBookingTypeUi(); save(); }
  else if (context === 'edit') renderPos();
  else { syncQuickBookDuration(); renderQuickBook(); }
}

function renderActivityOptionsWithoutParticipants(activity, options, pax) {
  if (!activity) return '';
  const id = escapeHtml(activity.id);
  if (activity.id === 'arcade_time') return renderStaffArcadeOptions(activity, options, pax, 'booking');
  // Grille de pistes : le duckpin la partage avec le bowling (meme tarif, meme
  // regle de joueurs). Piloter par le TYPE et non par l'id, c'est ce qui rend
  // ce partage gratuit.
  if (activity.priceType === 'grid_bowling') {
    const current = Number(options.duration) || 1;
    // Ce centre vend-il AUX PARTIES ? Alors la liste change de NATURE : des
    // parties, un prix par personne, et une duree qui en decoule. Sans cette
    // donnee, tout se passe exactement comme avant (durees, prix par piste).
    const games = typeof getBowlingGameOptions === 'function' ? getBowlingGameOptions(state.booking.date, { pax, laneCount: getRequiredLaneCount('bowling', pax, '') }) : null;
    if (games) {
      if (!games.length) return '<div class="activity-option-row"><span class="activity-option-empty">Aucun tarif publié pour ce jour.</span></div>';
      const rangee = `<div class="activity-option-row">${games.map(option => `
        <button type="button" class="dur-pill sm ${current === Number(option.value) ? 'active' : ''}" data-opt="duration" data-val="${option.value}"${attributsOptionTropLongue(option.value)}
          onclick="setBookingActivityOption('${id}','duration',${option.value})">
          ${option.label}<span class="price">${option.price}€ / pers</span>
        </button>`).join('')}</div>`;
      return rangee;
    }
    const rangee = `<div class="activity-option-row">${DURATION_OPTIONS.map(option => `
      <button type="button" class="dur-pill sm ${current === Number(option.value) ? 'active' : ''}" data-opt="duration" data-val="${option.value}"${attributsOptionTropLongue(option.value)}
        onclick="setBookingActivityOption('${id}','duration',${option.value})">
        ${option.label}<span class="price">${option.price}€ / piste</span>
      </button>`).join('')}</div>`;
    return rangee;
  }
  if (activity.priceType === 'grid_laser') {
    const current = Number(options.games) || 1;
    const rangee = `<div class="activity-option-row">${LASER_GAME_OPTIONS.map(option => `
      <button type="button" class="dur-pill sm ${current === Number(option.games) ? 'active' : ''}" data-opt="games" data-val="${option.games}"${attributsOptionTropLongue(option.value)}
        onclick="setBookingActivityOption('${id}','games',${option.games})">
        ${option.label}<span class="price">${option.price}€ / pers</span>
      </button>`).join('')}</div>`;
    return rangee;
  }
  if (activity.priceType === 'grid_fun_run') {
    const current = Number(options.minutes) || FUN_RUN_OPTIONS[0].minutes;
    const rangee = `<div class="activity-option-row">${FUN_RUN_OPTIONS.map(option => `
      <button type="button" class="dur-pill sm ${current === Number(option.minutes) ? 'active' : ''}" data-opt="minutes" data-val="${option.minutes}"${attributsOptionTropLongue(Number(option.minutes) / 60)}
        onclick="setBookingActivityOption('${id}','minutes',${option.minutes})">
        ${option.label}<span class="price">${option.price}€ / session</span>
      </button>`).join('')}</div>`;
    return rangee;
  }
  if (activity.priceType === 'per_unit_hour') {
    const choix = activityHourChoices(activity);
    const hours = Number(options.hours) || choix[0].hours;
    const units = Math.max(1, Number(options.units) || 1);
    const prixHeure = activity.priceValue;
    // Les listes deroulantes natives sont remplacees par les memes pastilles
    // que le bowling : un seul vocabulaire de choix dans tout l'ecran.
    const duree = `<div class="activity-option-group"><span class="activity-option-legend">Durée</span>
      <div class="activity-option-pills">${choix.map(option => `
        <button type="button" class="dur-pill xs ${Number(hours) === option.hours ? 'active' : ''}" data-opt="hours" data-val="${option.hours}"
          onclick="setBookingActivityOption('${id}','hours',${option.hours})">${option.label}</button>`).join('')}</div></div>`;
    const nombre = `<div class="activity-option-group"><span class="activity-option-legend">Tables</span>
      <div class="activity-option-pills">${activityUnitChoices(activity).map(value => `
        <button type="button" class="dur-pill xs ${units === value ? 'active' : ''}" data-opt="units" data-val="${value}"
          onclick="setBookingActivityOption('${id}','units',${value})">${value}</button>`).join('')}</div></div>`;
    const detail = prixHeure == null ? '' :
      `<div class="activity-option-note">${prixHeure}€ ${escapeHtml(activity.unitLabel || '')}.</div>`;
    return `<div class="activity-option-stack">${nombre}${duree}${detail}</div>`;
  }
  return `<div class="activity-option-note">Accès à votre arrivée, ${activity.priceValue == null ? 'réglé sur place' : 'compris dans le total'}.</div>`;
}

// Le programme est une vraie synthese, pas une phrase concatenee. Le client peut
// comparer les activites et leur reglage sans relire toute une ligne. Le montant
// reste separe, et "A partir de" apparait des qu'un tarif sera regle sur place.
function renderProgramSummary() {
  const host = document.getElementById('programSummary');
  if (!host) return;
  const chosen = getChosenActivities();
  if (!chosen.length || normalizeBookingMode(state.booking.mode) === 'formule') { host.innerHTML = ''; return; }
  const pax = Math.max(1, Number(state.booking.pax) || 1);
  let total = 0;
  let complete = true;
  const items = chosen.map(activity => {
    const options = activity.options || {};
    const pax = getBookingActivityParticipants(activity, options);
    if (activity.priceType === 'grid_bowling') {
      const duration = Number(options.duration) || 1;
      // DUCKPIN : il a SES pistes (units du catalogue, 2 a Libramont) et sa
      // regle de rotation. Ce resume comptait les pistes du BOWLING
      // (ceil(pax/6), jamais plafonne) : a 13 joueurs il affichait 3 pistes
      // et 117 EUR quand le serveur (lib/visit-program.js) facture 2 pistes
      // et 78 EUR, et la notif du MEME ecran disait deja 2 pistes + rotation.
      // Meme calcul que le serveur (activityUnitPlan) : les pistes de tous
      // les tours, chacune jouee et payee ; des tours au-dela de la dotation.
      const planDuckpin = activity.resourceType === 'duckpin_lane'
        ? getActivityUnitPlan({ ...activity, capacityPerUnit: Number(activity.capacityPerUnit) || 6 }, pax)
        : null;
      const lanes = planDuckpin ? planDuckpin.units : splitGroupIntoBowlingServices(pax).reduce((sum, players) => sum + getRequiredLaneCount('bowling', players, ''), 0);
      // Le duckpin se paie A LA PISTE partout, comme le serveur le chiffre
      // (lib/visit-program : bowlingConfig null) : le mode aux parties d un
      // centre ne vaut que pour son bowling.
      const games = !planDuckpin && typeof getBowlingGameOptions === 'function' ? getBowlingGameOptions(state.booking.date, { pax: pax, laneCount: getRequiredLaneCount('bowling', pax, '') }) : null;
      if (games) {
        // AUX PARTIES : c'est le nombre de JOUEURS qui paie, pas le nombre de
        // pistes. Les pistes restent dites, parce que le groupe doit savoir
        // qu'il sera reparti, mais elles ne multiplient plus le prix.
        const option = games.find(item => Number(item.value) === duration) || games[0];
        total += (option?.price || 0) * pax;
        if (!option) complete = false;
        return {
          id: activity.id,
          name: `${activity.name} · ${pax} ${activityCountsChildren(activity) ? 'enfants' : 'joueurs'}`,
          detail: `${option?.label || ''} · ${pax} joueur${pax > 1 ? 's' : ''} · ${lanes} piste${lanes > 1 ? 's' : ''}`,
        };
      }
      const option = DURATION_OPTIONS.find(item => Number(item.value) === duration);
      total += (option?.price || 0) * lanes;
      // Le nombre de pistes se DEDUIT du nombre de joueurs : sans l'ecrire,
      // le total double sans que rien n'explique pourquoi. Les tours aussi.
      const tours = planDuckpin && planDuckpin.tours > 1 ? ` en ${planDuckpin.tours} tours` : '';
      return {
        id: activity.id,
        name: activity.name,
        detail: `${option?.label || ''} · ${lanes} piste${lanes > 1 ? 's' : ''}${tours}`,
      };
    }
    if (activity.priceType === 'grid_laser') {
      const games = Number(options.games) || 1;
      total += (LASER_GAME_OPTIONS.find(option => Number(option.games) === games)?.price || 0) * pax;
      return { id: activity.id, name: activity.name, detail: `${games} partie${games > 1 ? 's' : ''}` };
    }
    if (activity.priceType === 'grid_fun_run') {
      const minutes = Number(options.minutes) || FUN_RUN_OPTIONS[0].minutes;
      const option = FUN_RUN_OPTIONS.find(item => item.minutes === minutes) || FUN_RUN_OPTIONS[0];
      // Un groupe plus grand que l'installation TOURNE (Fun Run : 5 joueurs
      // a la fois) : autant de sessions, autant de fois le prix, et le detail
      // le dit pour que le comptoir et l'ecran comptent pareil.
      const sessions = typeof getActivitySessionCount === 'function' ? getActivitySessionCount(activity, pax) : 1;
      total += option.price * sessions;
      return { id: activity.id, name: activity.name, detail: sessions > 1 ? `${sessions} sessions de ${option.label}` : option.label };
    }
    // Le compte d'enfants declare remplace le groupe entier dans le calcul
    // (meme regle que le serveur : borne au groupe, absent = tout le monde).
    const linePax = getBookingActivityParticipants(activity, options, pax);
    const price = typeof getFreeActivityPrice === 'function'
      // La date et le CRENEAU voyagent avec le prix : un palier borne par
      // l'heure (migration 0043) ne s'applique qu'une fois le creneau choisi,
      // donc le total affiche ne peut que baisser, jamais monter.
      ? getFreeActivityPrice(activity, { ...options, pax: linePax, units: options.units, hours: options.hours, minutes: options.minutes, dateStr: state.booking.date, startTime: state.booking.startTime })
      : null;
    if (price == null) complete = false; else total += price;
    if (activity.id === 'arcade_time') { const q=getArcadeOfferQuote(activity,options,linePax); return {id:activity.id,name:activity.name,detail:q ? getStaffArcadeOfferDetail({cards:q.cards,arcadeOffer:q.offer}) : 'Tarif à confirmer à l’accueil'}; }
    if (activity.priceType === 'per_unit_hour') {
      const units = Math.max(1, Number(options.units) || 1);
      const hourChoices = activityHourChoices(activity);
      const hours = Number(options.hours) || hourChoices[0].hours;
      const durationLabel = hourChoices.find(option => option.hours === hours)?.label || `${hours}h`;
      return {
        id: activity.id,
        name: activity.name,
        detail: `${units} table${units > 1 ? 's' : ''} · ${durationLabel}`,
      };
    }
    if (activityCountsChildren(activity)) {
      return {
        id: activity.id,
        name: activity.name,
        detail: `${linePax} enfant${linePax > 1 ? 's' : ''}`,
      };
    }
    return {
      id: activity.id,
      name: activity.name,
      detail: price == null ? 'À régler sur place' : 'Compris dans le total',
    };
  });
  // La structure n'est ecrite qu'une fois. Ensuite la liste et les valeurs sont
  // actualisees sans rejouer une animation de conteneur a chaque clic.
  let box = host.querySelector('.program-summary');
  if (!box) {
    host.innerHTML = `<div class="program-summary">
      <div class="program-overview">
        <div class="program-summary-head">
          <span class="program-title">Votre programme</span>
          <span class="program-count"></span>
        </div>
        <ul class="program-list"></ul>
      </div>
      <div class="program-price-block">
        <span class="program-total-label"></span>
        <strong class="program-total"></strong>
        <small class="program-total-note"></small>
      </div>
    </div>`;
    box = host.querySelector('.program-summary');
  }
  const list = box.querySelector('.program-list');
  const count = box.querySelector('.program-count');
  const totalLabel = box.querySelector('.program-total-label');
  const totalEl = box.querySelector('.program-total');
  const totalNote = box.querySelector('.program-total-note');
  const roundedTotal = Math.round(total * 100) / 100;
  const nextTotal = complete || roundedTotal > 0 ? `${roundedTotal}€` : 'Sur place';
  const nextValue = `${complete ? '' : 'à partir de '}${nextTotal}`;
  // Cocher une activite doit se VOIR dans le programme : la ligne qui arrive se
  // pose, celles deja la ne bougent pas d'un pixel. Sans ce filtre, chaque clic
  // rejouerait l'animation de toute la liste (meme piege que le motion
  // d'exploitation de la console : ce qui ne change pas reste immobile).
  const previousIds = String(list.dataset.ids || '').split(',').filter(Boolean);
  list.innerHTML = items.map(item => `<li class="program-item${previousIds.includes(item.id) ? '' : ' is-appearing'}" data-activity="${escapeHtml(item.id)}">
    <span class="program-item-name">${escapeHtml(item.name)}</span>
    <span class="program-item-detail">${escapeHtml(item.detail)}</span>
  </li>`).join('');
  list.dataset.ids = items.map(item => item.id).join(',');
  count.textContent = `${items.length} activité${items.length > 1 ? 's' : ''}`;
  totalLabel.textContent = complete ? 'Total' : (roundedTotal > 0 ? 'À partir de' : 'Tarif');
  // « à régler sur place » est TOUJOURS dit (2026-08-18) : rien ne s'encaisse
  // en ligne, et un total nu laissait croire le contraire.
  totalNote.textContent = complete
    ? 'pour cette sélection · à régler sur place'
    : (roundedTotal > 0 ? 'Tout se règle sur place, certaines activités y sont tarifées' : 'Montant confirmé à votre arrivée');
  if (totalEl.getAttribute('data-value') !== nextValue) {
    const previousTotal = totalEl.getAttribute('data-amount') || '';
    totalEl.setAttribute('data-value', nextValue);
    totalEl.setAttribute('data-amount', nextTotal);
    // Le montant ROULE vers sa nouvelle valeur (recette 8, adaptee en
    // transform) : chiffre qui monte quand le prix monte, qui descend quand il
    // baisse. C'est le seul endroit de l'ecran qui repond a « ca me coute
    // combien ? » : il montre la CONSEQUENCE du geste, sans clignoter.
    rollNumberTo(totalEl, previousTotal, nextTotal);
  }
}

// COMPTEUR A ROULEAUX (recette Transitions.dev fournie par Movsar, adaptee) :
// une colonne par CHIFFRE, chaque rouleau porte une piste de chiffres, prend
// un tour d'elan puis se pose sur le sien, en cascade de gauche a droite.
// L'ancien odometre a deux cellules sautait d'un bloc des que la longueur
// changeait (96 vers 108) : c'etait le « bug et moche ». Ce qui n'est pas un
// chiffre (le €) ne bouge pas ; une longueur qui change fait partir les
// colonnes neuves de 0. Mouvement reduit ou valeur non numerique
// (« Sur place ») : la valeur se pose, point.
const REEL_DUR_MS = 900;
const REEL_STAGGER_MS = 90;
const REEL_BLUR_FILTERS = 5;
let reelBlurReady = false;

// Le flou de file est STRICTEMENT vertical : un blur() CSS baverait sur les
// cotes (c'est ecrit dans la recette). Seul feGaussianBlur accepte "0 Y".
// Un filtre par colonne pour que chaque rouleau perde son flou en se posant.
function ensureReelBlurFilters() {
  if (reelBlurReady || typeof document === 'undefined' || !document.body) return;
  const host = document.createElement('div');
  host.setAttribute('aria-hidden', 'true');
  host.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden';
  host.innerHTML = `<svg width="0" height="0">${Array.from({ length: REEL_BLUR_FILTERS }, (_, i) =>
    `<filter id="pl-reel-blur-${i}"><feGaussianBlur stdDeviation="0 0"/></filter>`).join('')}</svg>`;
  document.body.appendChild(host);
  reelBlurReady = true;
}

// Monte vite pendant la phase rapide de la course, retombe a zero pile a
// l'atterrissage. Le rouleau au repos est NET, jamais baveux. Pilote au
// TIMER (30 fps, largement assez pour un flou) et pas en rAF : un onglet
// occulte affame le rAF et le flou resterait fige en pleine valeur.
function decayReelBlur(strip, col, delayMs) {
  const filter = document.querySelector(`#pl-reel-blur-${Math.min(col, REEL_BLUR_FILTERS - 1)} feGaussianBlur`);
  if (!filter || typeof performance === 'undefined') return;
  const start = performance.now() + delayMs;
  const timer = setInterval(() => {
    if (!strip.isConnected) { filter.setAttribute('stdDeviation', '0 0'); clearInterval(timer); return; }
    const t = (performance.now() - start) / REEL_DUR_MS;
    if (t < 0) return;
    const v = t >= 1 ? 0 : 3 * (1 - t) * Math.min(1, t * 5);
    filter.setAttribute('stdDeviation', `0 ${v.toFixed(2)}`);
    if (t >= 1) clearInterval(timer);
  }, 33);
}

function rollNumberTo(el, previousText, nextText) {
  const prevDigits = String(previousText || '').replace(/\D/g, '');
  const nextDigits = String(nextText || '').replace(/\D/g, '');
  if (!previousText || !prevDigits || !nextDigits || prefersReducedMotion()) {
    el.textContent = nextText;
    return;
  }
  const up = (Number(nextDigits) || 0) >= (Number(prevDigits) || 0);
  // Colonne a colonne, alignees par la droite : 96 -> 108 compare 096 a 108.
  const prevPadded = prevDigits.padStart(nextDigits.length, '0').slice(-nextDigits.length);
  ensureReelBlurFilters();
  let digitIndex = 0;
  let html = '';
  for (const ch of String(nextText)) {
    if (!/\d/.test(ch)) { html += `<span>${escapeHtml(ch)}</span>`; continue; }
    const from = Number(prevPadded[digitIndex]);
    const to = Number(ch);
    // Un tour d'elan (10 cellules) + la distance jusqu'au chiffre cible.
    const travel = 10 + ((up ? to - from : from - to) + 10) % 10;
    const cells = [];
    // La piste liste les chiffres DANS L'ORDRE ou la fenetre les traverse.
    // Vers le bas, la meme course se joue a l'envers : la piste part deja
    // deroulee et redescend (les chiffres defilent visuellement vers le bas).
    for (let s = 0; s <= travel; s += 1) cells.push(`<span class="t-reel-digit">${up ? (from + s) % 10 : (to + s) % 10}</span>`);
    html += `<span class="t-reel-col"><span class="t-reel-strip${up ? '' : ' is-down'}" data-col="${digitIndex}" data-travel="${travel}">${cells.join('')}</span></span>`;
    digitIndex += 1;
  }
  // La VRAIE valeur reste lisible pendant tout le spin : la synthese vocale
  // et tout lecteur de texte recoivent le montant pose, jamais la piste de
  // chiffres de l'echafaudage (qui est purement decoratif, donc aria-hidden).
  el.innerHTML = `<span class="visually-hidden">${escapeHtml(nextText)}</span><span class="t-reel" aria-hidden="true">${html}</span>`;
  const strips = [...el.querySelectorAll('.t-reel-strip')];
  strips.forEach((strip) => {
    const col = Number(strip.dataset.col);
    const travel = Number(strip.dataset.travel);
    const down = strip.classList.contains('is-down');
    strip.style.transform = down ? `translateY(calc(${-travel} * var(--reel-cell)))` : 'translateY(0)';
    strip.style.filter = `url(#pl-reel-blur-${Math.min(col, REEL_BLUR_FILTERS - 1)})`;
    // Double rAF : la position de depart doit etre PEINTE avant que la
    // transition ne parte, sinon le rouleau se teleporte.
    requestAnimationFrame(() => requestAnimationFrame(() => {
      strip.style.transition = `transform ${REEL_DUR_MS}ms cubic-bezier(0.16, 1, 0.3, 1) ${col * REEL_STAGGER_MS}ms`;
      strip.style.transform = down ? 'translateY(0)' : `translateY(calc(${-travel} * var(--reel-cell)))`;
    }));
    decayReelBlur(strip, col, col * REEL_STAGGER_MS);
  });
  // La structure de roulement est un echafaudage : une fois tous les rouleaux
  // poses, la valeur redevient du texte simple (rien a nettoyer ensuite).
  const guard = el.getAttribute('data-amount');
  const settleMs = REEL_DUR_MS + REEL_STAGGER_MS * Math.max(0, strips.length - 1) + 80;
  setTimeout(() => {
    if (el.getAttribute('data-amount') === guard) el.textContent = guard;
  }, settleMs);
}

function toggleBookingActivity(activityId) {
  const selection = state.booking.activities || (state.booking.activities = {});
  if (selection[activityId]) {
    delete selection[activityId];
  } else {
    // Le defaut suit le TYPE de tarif, pas l'identifiant : sinon le duckpin,
    // qui vend des pistes comme le bowling, demarrait sans duree.
    const type = (typeof getCenterActivity === 'function' && getCenterActivity(activityId) || {}).priceType || '';
    selection[activityId] = type === 'grid_bowling' ? { duration: 1 }
      : type === 'grid_laser' ? { games: 1 }
      : type === 'grid_fun_run' ? { minutes: FUN_RUN_OPTIONS[0].minutes }
      : activityId === 'arcade_time' ? defaultArcadeOptions(getCenterActivity(activityId)) : {};
  }
  state.booking.mode = 'carte';
  state.booking.formuleId = '';
  clearCurrentBookingChoice();
  clearBookingAlternatives();
  applyChosenActivitiesToBooking();
  syncBookingTypeUi();
  updatePaxAlert();
  save();
}

function setBookingActivityOption(activityId, key, value) {
  const selection = state.booking.activities || (state.booking.activities = {});
  if (!selection[activityId]) selection[activityId] = {};
  selection[activityId][key] = key === 'participants' ? getBookingActivityParticipants(getCenterActivity(activityId) || { id: activityId }, { participants: value }) : Number(value);
  clearCurrentBookingChoice();
  applyChosenActivitiesToBooking();
  syncBookingTypeUi();
  save();
}

// Le stepper -/+ du compte d'enfants. Il lit l'etat (defaut = groupe entier,
// meme regle que le serveur), applique le pas et borne au groupe : le bouton
// n'a pas a connaitre la valeur courante au moment du rendu.
function stepBookingChildren(activityId, delta) {
  const activity = getCenterActivity(activityId) || { id: activityId };
  const options = (state.booking.activities || {})[activityId] || {};
  setBookingActivityOption(activityId, 'participants', getBookingActivityParticipants(activity, options) + Number(delta));
}

function applyChosenActivitiesToBooking() {
  const chosen = getChosenActivities();
  const pax = Math.max(1, Number(state.booking.pax) || 1);
  const bowling = chosen.find(activity => activity.id === 'bowling');
  const laser = chosen.find(activity => activity.id === 'laser_game');
  if (bowling) {
    state.booking.duration = Number(bowling.options.duration) || 1;
    state.booking.laneCount = getRequiredLaneCount('bowling', getBookingActivityParticipants(bowling, bowling.options), '');
  } else if (laser) {
    state.booking.duration = Number(LASER_GAME_OPTIONS.find(option => Number(option.games) === (Number(laser.options.games) || 1))?.value) || 0.5;
    state.booking.laneCount = 0;
    state.booking.allocatedLanes = [];
  }
  state.booking.totalDuration = Math.max(0.5, chosen.reduce((hours, activity) => {
    const options = activity.options || {};
    const players = getBookingActivityParticipants(activity, options);
    if (activity.id === 'bowling') return hours + (Number(options.duration) || 1) * splitGroupIntoBowlingServices(players).length;
    if (activity.priceType === 'grid_bowling') return hours + (Number(options.duration) || 1) * getActivityUnitPlan(activity, players).tours;
    if (activity.priceType === 'grid_laser') return hours + (Number(options.games) || 1) * 0.5 * getLaserWaveCount(players);
    if (activity.priceType === 'grid_fun_run') return hours + (Number(options.minutes) || FUN_RUN_OPTIONS[0].minutes) / 60 * getActivitySessionCount(activity, players);
    if (activity.id === 'arcade_time') { const q=getArcadeOfferQuote(activity,options,players); return hours+(q?.offer.mode==='time' ? Number(q.offer.minutes) : Number(activity.defaultMinutes)||30)/60; }
    if (activity.priceType === 'per_unit_hour') return hours + (Number(options.hours) || activityHourChoices(activity)[0].hours);
    return hours + (Number(activity.defaultMinutes) || 30) / 60;
  }, 0));
  state.booking.preference = createDefaultFormulaPreference();
  state.booking.pauseMinutes = 0;
}

// Le panier envoye au serveur. Il ne porte que des identifiants et des options :
// AUCUN prix. Le montant est recalcule cote serveur, toujours.
//
// Le panier se PASSE pour chiffrer une visite CANDIDATE (un complement qu'on
// fait verifier avant de l'adopter) : c'est le meme code qui compose les deux
// paniers, donc le programme verifie est exactement celui que la confirmation
// enverra.
function buildBookingProgramPayload(panierPropose = null) {
  return getChosenActivities(panierPropose).map(activity => {
    const options = activity.options || {};
    const item = { activityId: activity.id, participants: getBookingActivityParticipants(activity, options) };
    // LES OPTIONS PARTENT SELON LE TYPE TARIFAIRE, PAS SELON UNE LISTE D IDS.
    // Seuls 'bowling' et 'laser_game' etaient nommes ici. Or le DUCKPIN partage
    // le meme type que le bowling (grid_bowling, option `duration`) sans porter
    // son identifiant : sa duree ne partait donc JAMAIS. Le serveur retombait sur
    // 1 heure et facturait 78 EUR la ou 2 h sur 2 pistes valent 156. Le FUN RUN
    // (grid_fun_run, option `minutes`) perdait pareillement son choix : une
    // session de 30 min a 55 EUR arrivait en 15 min a 30 EUR, et le meme panier
    // servait a la confirmation finale - mauvais prix, mauvaise duree, mauvaise
    // promesse au client.
    // Le type est deja porte par le catalogue (getChosenActivities le rend), et
    // le serveur lit deja `duration` et `minutes` : ajouter une activite au
    // catalogue ne doit plus demander de revenir editer une liste d identifiants.
    if (activity.priceType === 'grid_bowling') item.duration = Number(options.duration) || 1;
    if (activity.priceType === 'grid_laser') item.games = Number(options.games) || 1;
    if (activity.priceType === 'grid_fun_run') {
      const parDefaut = (typeof FUN_RUN_OPTIONS !== 'undefined' && FUN_RUN_OPTIONS[0]) ? Number(FUN_RUN_OPTIONS[0].minutes) : 15;
      item.minutes = Number(options.minutes) || parDefaut;
    }
    if (activity.id === 'arcade_time' && options.arcadeMode && options.arcadeOfferId) { item.arcadeMode = options.arcadeMode; item.arcadeOfferId = options.arcadeOfferId; item.cards = options.arcadeMode === 'time' ? item.participants : Math.min(1000, Math.max(1, Math.trunc(Number(options.cards) || item.participants))); }
    if (options.units) item.units = Number(options.units);
    if (options.hours) item.hours = Number(options.hours);
    // Le compte d'enfants declare part au serveur, qui le borne au groupe et
    // recalcule le prix (le navigateur n'est jamais cru sur un montant).

    // L OFFRE D ATTENTE voyage avec la ligne. Le navigateur ne fixe aucun
    // prix : il DEMANDE le tarif d attente, et le serveur ne l applique que
    // si le groupe est vraiment scinde (groupIsSplit, lib/visit-program).
    if (options.waitOffer === true) item.waitOffer = true;
    if (options.upsell) item.upsell = { offerId: options.upsell.offerId, participants: item.participants };
    if (options.extraLaser) item.extraLaser = { offerId: options.extraLaser.offerId, participants: options.extraLaser.participants, games: options.extraLaser.games };
    return item;
  });
}

// Un segment ferme est DESACTIVE (disabled natif : le onclick inline ne part
// pas) ET porte le mot "Fermé". Jamais l'un sans l'autre.
function applySegmentOffState(id, isOff) {
  const btn = document.getElementById(id);
  if (!btn) return;
  btn.classList.toggle('is-off', !!isOff);
  btn.disabled = !!isOff;
  btn.setAttribute('aria-disabled', isOff ? 'true' : 'false');
  let pill = btn.querySelector('.seg-btn-off');
  if (isOff && !pill) {
    pill = document.createElement('span');
    pill.className = 'seg-btn-off';
    pill.textContent = 'Fermé';
    btn.appendChild(pill);
  }
  if (pill) pill.hidden = !isOff;
}

function renderTypeAlert(off, dayStatus) {
  const el = document.getElementById('typeAlert');
  if (!el) return;
  if (!dayStatus || !off.length) { el.innerHTML = ''; return; }
  const labels = { bowling: 'Bowling', laser_game: 'Laser Game' };
  const named = (id) => labels[id]
    || (typeof getCenterActivity === 'function' ? getCenterActivity(id)?.name : '')
    || id;
  const noms = off.map(named).join(' et ');
  const reste = off.length >= 2
    ? 'Les formules sans ces activités restent réservables ce jour.'
    : 'Le reste du centre et les formules restent réservables ce jour.';
  el.innerHTML = renderDayStatusBlock('is-partial', `${noms} fermé${off.length > 1 ? 's' : ''} le ${formatBookingDateLong(dayStatus.date)}`, reste);
}

function clearCurrentBookingChoice() {
  state.availableSlots = [];
  state.booking.startTime = '';
  state.booking.allocatedLanes = [];
  state.booking.opsPlan = null;
}

// setType garde son nom (appele par le HTML et par d'anciens etats sauvegardes)
// mais bascule desormais un MODE : 'carte' (composer sa visite) ou 'formule'.
// Les anciennes valeurs 'bowling' / 'laser' cochent l'activite correspondante.
function setType(t) {
  clearCurrentBookingChoice();
  clearBookingAlternatives();
  if (t === 'formule') {
    state.booking.mode = 'formule';
    // LE CHOIX A LA CARTE SURVIT A UN COUP D OEIL SUR LES FORMULES (2026-09-01).
    // Mesure sur le vrai parcours telephone : trois activites cochees, un tap
    // sur « Nos formules » pour regarder, retour « A la carte » : il ne
    // restait que le bowling, et le recapitulatif ne facturait que lui. Le
    // panier est mis de cote, jamais efface ; le mode formule ne le lit pas.
    const panier = state.booking.activities && typeof state.booking.activities === 'object' ? state.booking.activities : {};
    if (Object.keys(panier).length) state.booking.carteActivities = panier;
    state.booking.activities = {};
  } else {
    state.booking.mode = 'carte';
    state.booking.formuleId = '';
    const panierMisDeCote = state.booking.carteActivities && typeof state.booking.carteActivities === 'object' ? state.booking.carteActivities : null;
    if ((!state.booking.activities || !Object.keys(state.booking.activities).length) && panierMisDeCote && Object.keys(panierMisDeCote).length) {
      state.booking.activities = panierMisDeCote;
    }
    if (!state.booking.activities || !Object.keys(state.booking.activities).length) {
      state.booking.activities = t === 'laser' ? { laser_game: { games: 1 } } : { bowling: { duration: 1 } };
    } else if (t === 'bowling' || t === 'laser') {
      state.booking.activities = t === 'laser' ? { laser_game: { games: 1 } } : { bowling: { duration: 1 } };
    }
    applyChosenActivitiesToBooking();
  }
  syncBookingTypeUi();
  renderFormules();
  renderFormulaPreferences();
  updatePaxAlert();
  save();
}

const ACTIVITY_LABELS = {
  bowling: 'Bowling',
  laser_game: 'Laser Game',
  minigolf_blacklight: 'Mini Golf',
  arcade_time: 'Arcades',
  playground: 'Plaine de jeux',
  party_table: 'Table',
};

// Modèle « Ancres + Liberté » : le client choisit une heure PAR ANCRE
// (bowling, laser), plus d'ordre imposé ni de mode « Fun Galaxy organise /
// Je choisis ». Les activités libres restent un pass sans aucune heure.
// L'heure de CHAQUE partie de laser part avec la demande : c'est la seule facon
// que le serveur valide la combinaison REELLE (parties posees + parties
// laissees sur place) au lieu d'une ancre unique. Rien a dire = rien a envoyer,
// donc l'ancien comportement pour une reservation a une seule partie.
function setLaserPartTimesParam(params, preference) {
  const parties = getBookingLaserPartTimes(preference);
  if (parties.length > 1) params.set('laserGameTimes', JSON.stringify(parties));
}

function createDefaultFormulaPreference(value = {}) {
  const source = value && typeof value === 'object' ? value : {};
  const preferred = source.preferredTimes && typeof source.preferredTimes === 'object' ? source.preferredTimes : {};
  // `laserGameTimes` : UNE HEURE PAR PARTIE de laser, dans l'ordre des parties.
  // Une heure = cette partie est posee au planning ; une case vide = elle se
  // place sur place avec l'equipe. Liste vide = aucune partie choisie encore.
  const parties = Array.isArray(source.laserGameTimes)
    ? source.laserGameTimes.map(item => (typeof item === 'string' ? item : ''))
    : (typeof preferred.laser_game === 'string' && preferred.laser_game ? [preferred.laser_game] : []);
  return {
    arrivalConfidence: source.arrivalConfidence === 'uncertain' ? 'uncertain' : 'normal',
    laserPlacement: source.laserPlacement === 'onsite' ? 'onsite' : 'scheduled',
    laserGameTimes: parties,
    preferredTimes: {
      bowling: typeof preferred.bowling === 'string' ? preferred.bowling : '',
      // L'ancre laser reste la PREMIERE partie posee : tout ce qui lit une
      // heure de laser unique (recap, mails, disponibilite) reste juste.
      laser_game: parties.find(time => time) || (typeof preferred.laser_game === 'string' ? preferred.laser_game : ''),
    },
  };
}

// Combien de parties de laser cette reservation en cours contient. La source
// est le choix du client (options de l'activite) ou, pour une formule, ce que
// le serveur annonce dans les ancres.
function getBookingLaserPartCount() {
  const anchor = (formulaAnchorData?.activities || []).find(activity => activity.activityId === 'laser_game');
  if (anchor) return Math.max(1, Number(anchor.count || 1));
  const laser = getChosenActivities().find(activity => activity.id === 'laser_game');
  return laser ? Math.max(1, Number((laser.options || {}).games || 1)) : 0;
}

// LES HEURES RETENUES POUR LE LASER, triees. Les parties ne se distinguent pas
// entre elles : la 1re est simplement la plus tot. Le client choisit donc des
// HEURES dans une liste, pas des parties numerotees.
function getChosenLaserTimes(preference) {
  return getBookingLaserPartTimes(preference)
    .filter(Boolean)
    .sort((left, right) => timeToNum(left) - timeToNum(right));
}

// Poser la liste des heures retenues : elle remplit les parties dans l'ordre,
// les parties restantes se placent sur place.
function setChosenLaserTimes(preference, heures) {
  const count = getBookingLaserPartCount();
  const triees = [...new Set(heures.filter(Boolean))]
    .sort((left, right) => timeToNum(left) - timeToNum(right))
    .slice(0, count);
  preference.laserGameTimes = Array.from({ length: count }, (_, index) => triees[index] || '');
  preference.preferredTimes.laser_game = triees[0] || '';
  return preference;
}

// La liste d'heures par partie, toujours a la bonne longueur.
function getBookingLaserPartTimes(preference) {
  const count = getBookingLaserPartCount();
  const source = Array.isArray(preference.laserGameTimes) ? preference.laserGameTimes : [];
  return Array.from({ length: count }, (_, index) => source[index] || '');
}

function formulaActivityToken(text = '') {
  return String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function getFormulaActivityIds(formule) {
  if (!formule) return [];
  const detected = [];
  const addDetected = (id) => {
    if (!detected.includes(id)) detected.push(id);
  };
  (formule.desc || []).forEach((line) => {
    const normalized = formulaActivityToken(line);
    if (normalized.includes('cruche') || normalized.includes('boisson') || normalized.includes('biere')) return;
    if (normalized.includes('table privee') || normalized.includes('table anniversaire')) addDetected('party_table');
    if (normalized.includes('plaine')) addDetected('playground');
    if (normalized.includes('minigolf') || normalized.includes('mini golf')) addDetected('minigolf_blacklight');
    if (normalized.includes('bowling')) addDetected('bowling');
    if (normalized.includes('laser')) addDetected('laser_game');
    if (normalized.includes('arcade')) addDetected('arcade_time');
  });
  return detected;
}

function getFormulaActivityCounts(formule) {
  const counts = {};
  const lines = (formule?.desc || []).map(line => formulaActivityToken(line));
  const setCount = (id, count = 1) => {
    counts[id] = Math.max(counts[id] || 0, count);
  };
  lines.forEach((line) => {
    const numberMatch = line.match(/(\d+)\s+(?:partie|parties|entree|entrees|heure|heures|h)\b/);
    const count = numberMatch ? Math.max(1, Number(numberMatch[1])) : 1;
    if (line.includes('bowling')) setCount('bowling', 1);
    if (line.includes('laser')) setCount('laser_game', line.includes('illimite') ? 1 : count);
    if (line.includes('minigolf') || line.includes('mini golf')) setCount('minigolf_blacklight', count);
    if (line.includes('arcade')) setCount('arcade_time', 1);
    if (line.includes('plaine')) setCount('playground', count);
    if (line.includes('table privee') || line.includes('table anniversaire')) setCount('party_table', 1);
  });
  return counts;
}

function getFormulaActivityLabel(formule, activityId) {
  const counts = getFormulaActivityCounts(formule);
  const count = Number(counts[activityId] || 1);
  const label = ACTIVITY_LABELS[activityId] || activityId;
  if (activityId === 'bowling') return `${label} ${formatDurationLabel(getFormuleLaneDuration(formule))}`;
  if (activityId === 'laser_game' && count > 1) return `${label} x${count}`;
  return label;
}

// Classification client d'une formule (miroir du serveur) :
// - ANCRES : bowling et laser uniquement (vraies ressources à créneau).
// - TABLE : au groupe dès l'arrivée, jamais choisie.
// - PASS LIBERTÉ : tout le reste, sans aucune heure.
function getFormulaAnchorIds(formule) {
  return getFormulaActivityIds(formule).filter((id) => ['bowling', 'laser_game'].includes(id));
}

function getFormulaFreePassIds(formule) {
  return getFormulaActivityIds(formule).filter((id) => !['bowling', 'laser_game', 'party_table'].includes(id));
}

function formulaHasPartyTable(formule) {
  return getFormulaActivityIds(formule).includes('party_table');
}

function ensureFormulaPreferences(formule) {
  const preference = createDefaultFormulaPreference(state.booking.preference || {});
  const anchorIds = getFormulaAnchorIds(formule);
  if (!anchorIds.includes('bowling')) preference.preferredTimes.bowling = '';
  if (!anchorIds.includes('laser_game')) preference.preferredTimes.laser_game = '';
  if (!anchorIds.includes('laser_game') || anchorIds.length < 2) preference.laserPlacement = 'scheduled';
  state.booking.preference = preference;
  state.booking.pauseMinutes = 0;
}

// Étape 1 : simple annonce du modèle, le vrai choix (une heure par ancre)
// vit à l'étape Créneau. Plus de mode « Fun Galaxy organise / Je choisis ».
function renderFormulaPreferences() {
  const box = document.getElementById('formulaPrefs');
  const orderEl = document.getElementById('formulaOrderOptions');
  const noteEl = document.getElementById('formulaPreferenceNote');
  if (!box || !orderEl || !noteEl) return;
  const formule = state.booking.type === 'formule' ? resolveDisplayFormule(state.booking.formuleId) : null;
  if (!formule) {
    box.classList.add('hidden');
    orderEl.innerHTML = '';
    noteEl.textContent = '';
    return;
  }
  ensureFormulaPreferences(formule);
  const anchorIds = getFormulaAnchorIds(formule);
  const freeIds = getFormulaFreePassIds(formule);
  const hasTable = formulaHasPartyTable(formule);
  box.classList.remove('hidden');
  noteEl.textContent = anchorIds.length
    ? 'À l’étape suivante, choisissez une heure pour chaque activité à créneau, le reste se vit librement sur place.'
    : 'À l’étape suivante, choisissez simplement votre heure d’arrivée, tout le reste se vit librement sur place.';
  orderEl.innerHTML = `
    <div class="formula-model-preview">
      ${anchorIds.length ? `
      <div class="formula-model-line">
        <span class="formula-model-tag reserved">Heure à choisir</span>
        <span>${anchorIds.map(id => escapeHtml(getFormulaActivityLabel(formule, id))).join(' · ')}</span>
      </div>` : ''}
      ${hasTable ? `
      <div class="formula-model-line">
        <span class="formula-model-tag table">Table</span>
        <span>Table réservée pendant toute la visite</span>
      </div>` : ''}
      ${freeIds.length ? `
      <div class="formula-model-line">
        <span class="formula-model-tag free">Pass liberté</span>
        <span>${freeIds.map(id => escapeHtml(getFormulaActivityLabel(formule, id))).join(' · ')}, à votre rythme, quand vous voulez</span>
      </div>` : ''}
    </div>`;
}

function selectFormule(id) {
  state.booking.formuleId = id;
  clearBookingAlternatives();
  state.booking.startTime = '';
  state.booking.preference = createDefaultFormulaPreference();
  state.booking.opsPlan = null;
  const formule = resolveDisplayFormule(id);
  if (formule) {
    state.booking.duration = getFormuleLaneDuration(formule);
    state.booking.totalDuration = getFormuleTotalDuration(formule);
    ensureFormulaPreferences(formule);
  }
  renderFormules();
  renderFormulaPreferences();
  updatePaxAlert();
  save();
}

// L ECHELLE DES QUESTIONS (2026-08-31). Movsar : « la barre de suivi je la
// trouve mal faite parce que la on a 3 questions et ca reste toujours sur le
// meme point ». C etait exact : le fil se calait sur les 5 SECTIONS du tunnel
// alors que la premiere en pose jusqu a quatre (le jour, le groupe, les
// activites, les options). Le client repondait trois fois et rien ne bougeait.
//
// L echelle ci-dessous est la SEULE verite d avancement : elle liste les
// questions reellement posees, dans l ordre, et dit ou on en est. Le rang de
// l ecran des options n existe que si un reglage existe (une formule n en a
// pas) : sans ce test, le fil promettrait une question qui ne viendra jamais.
function tunnelQuestionRank() {
  const sections = tunnelStepCount();
  const step = Math.min(Math.max(1, Number(state.step) || 1), sections);
  const corps = document.querySelector('#clientView .step1-body');
  const surVenue = Boolean(corps && corps.classList.contains('is-solo'));
  const avecOptions = typeof mobileOptionsAvailable === 'function' && mobileOptionsAvailable();
  const surOptions = !surVenue && typeof onMobileOptionsPage === 'function' && onMobileOptionsPage();
  // Questions de l etape 1 : jour, groupe, activites (+ options si elles
  // existent). Les sections suivantes en posent une chacune.
  const questionsEtape1 = 3 + ((avecOptions || surOptions) ? 1 : 0);
  const total = questionsEtape1 + (sections - 1);
  if (step > 1) return { rang: questionsEtape1 + (step - 1), total };
  if (surVenue) return { rang: venueStage === 'pax' ? 2 : 1, total };
  return { rang: surOptions ? 4 : 3, total };
}

// L avancement 0..1 du fil. Le fil doit rester D ACCORD avec les pastilles :
// il TOUCHE la pastille d une section quand cette section commence, et il
// progresse ENTRE deux pastilles au rythme des questions de la section. Un fil
// cale sur le seul rang de question passerait la pastille 2 alors qu on est
// encore a l etape 1 : le repere et le trait se contrediraient.
function tunnelProgressFraction() {
  const sections = tunnelStepCount();
  const step = Math.min(Math.max(1, Number(state.step) || 1), sections);
  const denominateur = Math.max(1, sections - 1);
  let interne = 0;
  if (step === 1) {
    const { rang, total } = tunnelQuestionRank();
    const questionsEtape1 = Math.max(1, total - (sections - 1));
    interne = Math.min(rang - 1, questionsEtape1 - 1) / questionsEtape1;
  }
  return Math.min(1, Math.max(0, (step - 1 + interne) / denominateur));
}

function updateProgress() {
  const total = tunnelStepCount();
  for (let i = 1; i <= total; i++) {
    const el = document.getElementById('pd' + i);
    // Une pastille peut manquer sans que le parcours soit casse : on ne plante
    // pas la progression pour autant.
    if (!el) continue;
    // TOGGLE, PAS remove-puis-add. L ancienne version retirait la classe pour
    // la remettre a chaque rendu : une animation posee sur .active repartait
    // de zero a chaque appel d updateProgress, meme quand l etape n avait pas
    // bouge. Avec toggle(classe, condition), la classe n est ecrite que si
    // elle change vraiment : l onde d arrivee joue exactement une fois, au
    // moment ou l etape devient courante.
    el.classList.toggle('done', i < state.step);
    el.classList.toggle('active', i === state.step);
  }
  // Le FLUIDE avance jusqu'à la pastille courante : --p vaut 0 à l'étape 1 et
  // 1 à la dernière. Sous filtre gooey, la tête s'étire depuis le remplissage
  // comme une goutte (transition de width, calque .lq-fluid).
  const progress = document.querySelector('#clientView .progress');
  if (progress) progress.style.setProperty('--p', String(tunnelProgressFraction()));
  syncMobileTopbar();
  syncBookingContext();
}

// --- BARRE HAUTE TELEPHONE ---------------------------------------------------
// Refonte mobile 2026-08-18 (option « liste native ») : sous 640 px, la
// progression a pastilles cede sa place a une barre fine retour + titre + rang
// + filet de progression. Elle se lit sur l'ETAT REEL (etape courante, page
// venue ou activites) : elle est juste a chaque rendu, quel que soit l'ordre
// des chemins qui y menent. Au-dessus de 640 px elle est display:none, la
// synchroniser ne coute rien.
// Le resume de la venue en un souffle : « sam. 22 aout · 4 joueurs ».
// Partage entre la ligne de rappel et la barre haute.
function venueSummaryLabel() {
  const pax = Number(state.booking.pax) || 0;
  let dateLabel = state.booking.date || '';
  try {
    dateLabel = parseLocalDate(state.booking.date).toLocaleDateString('fr-BE', { weekday: 'short', day: 'numeric', month: 'short' });
  } catch (error) { /* la date brute reste lisible */ }
  return `${dateLabel} · ${pax} joueur${pax > 1 ? 's' : ''}`;
}

function syncMobileTopbar() {
  const title = document.getElementById('mTopTitle');
  const rank = document.getElementById('mTopRank');
  const back = document.getElementById('mTopBack');
  const fill = document.getElementById('mTopFill');
  if (!title || !rank || !back || !fill) return;
  const step = Number(state.step) || 1;
  const body = document.querySelector('#clientView .step1-body');
  const venuePage = step === 1 && Boolean(body && body.classList.contains('is-solo'));
  const optionsPage = step === 1 && !venuePage && typeof onMobileOptionsPage === 'function' && onMobileOptionsPage();
  const activitiesPage = step === 1 && !venuePage && !optionsPage;
  // Sur la page activites, le titre EST le rappel de venue : il porte le
  // choix (sam. 22 aout · 4 joueurs) et un tap ramene a la page venue. La
  // rangee de rappel separee a cede sa hauteur a la grille (tout voir d'un
  // coup, verdict Movsar 2026-08-18).
  const names = {
    1: venuePage ? 'Votre venue' : (optionsPage ? 'Vos options' : venueSummaryLabel()),
    2: 'Vos horaires',
    3: 'Vos coordonnées',
    4: 'Récapitulatif',
    5: 'Confirmé',
  };
  title.textContent = names[step] || '';
  title.disabled = !activitiesPage;
  title.classList.toggle('is-actionable', activitiesPage);
  if (activitiesPage) {
    title.setAttribute('aria-label', `${venueSummaryLabel()}, modifier votre venue`);
  } else {
    title.removeAttribute('aria-label');
  }
  // LE RANG DIT LA QUESTION, PAS LA SECTION. « 1/5 » restait affiche pendant
  // les quatre questions de l etape 1 : le client repondait et le compteur ne
  // bougeait pas (Movsar, 2026-08-31).
  const { rang, total } = tunnelQuestionRank();
  rank.textContent = `${rang}/${total}`;
  fill.style.width = `${(rang / total) * 100}%`;
  // Le retour n'existe que la ou il mene quelque part : jamais sur la page
  // LE RETOUR EXISTE DES LA DEUXIEME QUESTION. Il etait masque sur TOUTE la
  // page venue : arrive sur « Vous etes combien ? », le client n avait plus
  // aucun chemin vers « Quel jour venez-vous ? » (Movsar, 2026-08-31 : « quand
  // on fait retour on peut pas se rendre jusqu a re modifier la date »). Seule
  // la toute premiere question n a rien derriere elle, et la confirmation
  // ferme le parcours.
  const premiereQuestion = venuePage && venueStage !== 'pax';
  back.hidden = premiereQuestion || step === tunnelStepCount();
}

// Tap sur le titre de la barre haute (page activites) : meme geste que la
// ligne de rappel, retour a la page venue.
function mobileTopTitleTap() {
  const step = Number(state.step) || 1;
  const body = document.querySelector('#clientView .step1-body');
  if (step === 1 && body && !body.classList.contains('is-solo')) reopenVenue();
}

// Le geste du bouton retour de la barre haute : sur la page activites il
// rouvre la venue (meme geste que la ligne de rappel), ailleurs il recule
// d'une etape par le meme chemin que les boutons Retour d'origine.
function mobileTopBack() {
  const step = Number(state.step) || 1;
  if (step === 1) {
    // La venue recule QUESTION par question : le groupe ramene au jour.
    const corps = document.querySelector('#clientView .step1-body');
    if (corps && corps.classList.contains('is-solo')) {
      if (venueStage === 'pax') setVenueStage('date');
      return;
    }
    // Page options -> page activites -> page venue : la chaine du retour.
    if (typeof onMobileOptionsPage === 'function' && onMobileOptionsPage()) {
      showMobileOptionsPage(false);
      return;
    }
    reopenVenue();
    return;
  }
  // LE RETOUR DEPUIS LES HEURES REVIENT A L ECRAN PRECEDENT (Movsar,
  // 2026-09-17 : « quand on fait retour on tombe sur le choix dactivite et
  // pas a la page precedente de base qui est choix des options »).
  if (step === 2) { retourDepuisCreneau(); return; }
  if (step > 1 && step < 5) goStep(step - 1);
}

// L ecran des heures a UN precedent : l ecran des reglages quand la visite en
// a (a la carte, au moins un reglage), sinon le choix des activites. Un seul
// point d entree pour le pied de page et pour la barre haute du telephone.
function retourDepuisCreneau() {
  goStep(1);
  if (typeof mobileOptionsAvailable === 'function' && mobileOptionsAvailable()
    && typeof showMobileOptionsPage === 'function') {
    showMobileOptionsPage(true);
  }
}

// UNE ALERTE APPARTIENT A L ECRAN QUI L A LEVEE. Elle ne s effacait que par un
// delai de 4,5 s : le client qui corrigeait ses champs et passait au
// recapitulatif emmenait avec lui un reproche qui visait un ecran qu il ne
// voyait plus, pose en position fixed par-dessus la barre d etapes (mesure a
// 1440 : encore visible a y=66, hauteur 43 px, opacite 1). Le changement
// d etape la vide donc, et le minuteur de la precedente est annule avec elle -
// sinon il effacerait l alerte de l ecran d arrivee avant l heure.
let alertBoxTimer = null;
function clearAlert() {
  if (alertBoxTimer) { clearTimeout(alertBoxTimer); alertBoxTimer = null; }
  const el = document.getElementById('alertBox');
  if (el) el.innerHTML = '';
}

// L ALERTE NE RECOUVRE PLUS LA BARRE D ETAPES (2026-09-07, Movsar sur la
// video du parcours embarque : « ca devrait s afficher dans un endroit ou ca
// ne cache rien »). Elle etait posee a « hauteur du header + 10 » ; dans un
// embed le header n existe pas, la barre d etapes remonte a sa place, et le
// bandeau rouge se peignait exactement dessus, et on ne voyait plus ou on en
// etait au moment precis ou on venait de se tromper. On ne devine plus la
// place : on MESURE le bas de tout ce qui occupe le haut de la scene (header,
// barre haute telephone, son filet, barre d etapes) et l alerte se pose
// dessous. Le repli CSS reste l ancien calcul, pour le cas ou rien n est
// mesurable.
function poserPlafondAlerte() {
  let bas = 0;
  for (const selecteur of ['body > header', '#clientView .m-topbar', '#clientView .m-top-hairline', '#clientView .progress']) {
    const el = document.querySelector(selecteur);
    if (!el) continue;
    const boite = el.getBoundingClientRect();
    // Un element masque (display:none) mesure 0 : il ne compte pas.
    if (boite.height > 0) bas = Math.max(bas, boite.bottom);
  }
  if (bas > 0) document.documentElement.style.setProperty('--tunnel-alert-top', Math.round(bas + 10) + 'px');
}

function showAlert(msg) {
  const el = document.getElementById('alertBox');
  // Mesure AU MOMENT d afficher : la barre d etapes change de hauteur d un
  // ecran a l autre et disparait sous 640 px.
  poserPlafondAlerte();
  if (alertBoxTimer) { clearTimeout(alertBoxTimer); alertBoxTimer = null; }
  el.innerHTML = `<div class="alert shake"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg> ${escapeHtml(msg)}</div>`;
  alertBoxTimer = setTimeout(() => { alertBoxTimer = null; el.innerHTML = ''; }, 4500);
}

// Erreur au champ (P2-1, DESIGN.md §6) : aria-invalid → bordure --danger
// (pinlane.css) + message 12px role="alert" injecté juste sous le champ.
function clearFieldError(inputId) {
  const input = document.getElementById(inputId);
  if (!input || !input.parentElement) return;
  input.removeAttribute('aria-invalid');
  const message = input.parentElement.querySelector('.field-error-message');
  if (message) message.remove();
}

function setFieldError(inputId, text) {
  const input = document.getElementById(inputId);
  if (!input || !input.parentElement) return;
  input.setAttribute('aria-invalid', 'true');
  let message = input.parentElement.querySelector('.field-error-message');
  if (!message) {
    message = document.createElement('div');
    message.className = 'field-error-message';
    message.setAttribute('role', 'alert');
    input.insertAdjacentElement('afterend', message);
  }
  message.textContent = text;
}

// Purge la proposition d'horaires alternatifs (état + DOM). Appelée dès que le
// contexte de réservation change : nouvelle recherche, reset, changement de
// date/joueurs/activité/formule, réservation confirmée. Sans ça, la carte
// d'alternatives restait affichée indéfiniment dans #alertBox.
function clearBookingAlternatives() {
  if (state.booking) state.booking.alternatives = [];
  const el = document.getElementById('alertBox');
  if (el && el.querySelector('.booking-alternatives')) el.innerHTML = '';
}

function showBookingAlternatives(message, alternatives = []) {
  const el = document.getElementById('alertBox');
  if (!el) return;
  const safeAlternatives = alternatives.slice(0, 5);
  state.booking.alternatives = safeAlternatives;
  el.innerHTML = `
    <div class="alert booking-alternatives">
      <div class="booking-alt-head">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
        <strong>${escapeHtml(message || 'Ce créneau ne tient plus.')}</strong>
      </div>
      <div class="booking-alt-list">
        ${safeAlternatives.map((alternative, index) => `
          <button type="button" class="booking-alt-option" onclick="applyBookingAlternative(${index})">
            <span>${escapeHtml(alternative.summary || `${alternative.date} ${alternative.startTime}`)}</span>
            <small>${escapeHtml(alternative.date || '')} · ${escapeHtml(alternative.validationStatus === 'staff_review' ? 'à vérifier staff' : 'confirmable')}</small>
          </button>
        `).join('')}
      </div>
    </div>`;
}

function applyBookingAlternative(index) {
  const alternative = (state.booking.alternatives || [])[index];
  if (!alternative) return;
  state.booking.date = alternative.date || state.booking.date;
  state.booking.startTime = alternative.startTime || state.booking.startTime;
  state.booking.opsPlan = alternative.opsPlan || null;
  state.booking.allocatedLanes = alternative.lanes || alternative.opsPlan?.assignedLanes || [];
  if (state.booking.type === 'formule' && alternative.opsPlan) {
    // Aligne les ancres choisies sur l'alternative retenue : le serveur
    // revalidera exactement cette combinaison à la confirmation.
    state.booking.preference = createDefaultFormulaPreference({
      ...(state.booking.preference || {}),
      preferredTimes: {
        bowling: alternative.opsPlan.firstBowlingTime || '',
        laser_game: alternative.opsPlan.firstLaserTime || '',
      },
      laserPlacement: alternative.opsPlan.firstLaserTime ? 'scheduled' : (state.booking.preference?.laserPlacement || 'scheduled'),
    });
  }
  save();
  renderRecap();
  // Meme regle que les refus de confirmation : le message part AVEC l etape.
  // L ordre etait deja juste ici ; il n est simplement plus a reinventer.
  goStep(4, { alert: 'Alternative appliquée. Vérifiez le récapitulatif avant confirmation.' });
}

// --- Changement d'étape : la PISTE GLISSE (scène horizontale) ----------------
// Les cinq étapes vivent côte à côte dans `.tunnel-track` ; changer d'étape,
// c'est déplacer la piste (translateX + ressort, variable --tstep). Le sens du
// parcours est raconté par le glissement lui-même, la cascade pose ensuite les
// blocs de l'étape arrivée.
//
// Trois propriétés non négociables :
//  1. l'état (`state.step`) et le DOM de l'étape qui arrive sont corrects DÈS
//     l'appel : rien dans le produit ni dans un gate n'attend une animation ;
//  2. seule la piste bouge (`transform`), aucune hauteur ne s'anime, la page
//     ne défile JAMAIS (elle n'a pas de défilement : une étape = un écran) ;
//  3. les étapes non courantes sont INERTES (`inert` + aria-hidden) : le
//     clavier et le lecteur d'écran ne voient que l'écran affiché.
const STEP_LABELS = { 1: 'Activité', 2: 'Créneau', 3: 'Contact', 4: 'Valider', 5: 'Confirmé' };

// LE NOMBRE D ECRANS SE LIT SUR LA PISTE, IL NE SE RECOPIE PAS. Avant, « 5 »
// etait ecrit en dur a cinq endroits (la liste des ids dans goStep, la boucle
// des pastilles, le diviseur du fluide, le rang « n/5 », le titre accessible) :
// ajouter un ecran demandait de les retrouver tous, et en oublier un donnait une
// progression qui ment sans rien casser de visible. La piste EST la source.
function tunnelStepIds() {
  const track = document.getElementById('tunnelTrack');
  if (!track) return ['step1', 'step2', 'step3', 'step4', 'step5'];
  const ids = Array.from(track.children).map((el) => el.id).filter(Boolean);
  return ids.length ? ids : ['step1', 'step2', 'step3', 'step4', 'step5'];
}
function tunnelStepCount() {
  return tunnelStepIds().length;
}
let stepArrivalTimer = null;

function prefersReducedMotion() {
  return typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
}

// La scene ne defile JAMAIS elle-meme. Sa boite est overflow:hidden, mais un
// scrollIntoView ou le focus d'un champ (clavier de telephone) peut quand meme
// pousser son scrollLeft : toutes les etapes se desaxent alors d'un coup sans
// que l'etat change (mesure 2026-08-18 a 390x844 : step1 rejete a x=-188).
// Le verrou remet zero a chaque tentative, et goStep repart toujours de zero.
let stageScrollLockArmed = false;
function lockStageScroll() {
  const stage = document.querySelector('#clientView .tunnel-stage');
  if (!stage) return;
  stage.scrollLeft = 0;
  stage.scrollTop = 0;
  if (stageScrollLockArmed) return;
  stageScrollLockArmed = true;
  stage.addEventListener('scroll', () => {
    if (stage.scrollLeft) stage.scrollLeft = 0;
    if (stage.scrollTop) stage.scrollTop = 0;
  }, { passive: true });
}

function goStep(n, options = {}) {
  const previous = Number(state.step) || 1;
  const target = document.getElementById('step' + n);
  // LE MESSAGE APPARTIENT A L ECRAN D ARRIVEE, ET CE N EST PLUS A L APPELANT
  // DE LE SAVOIR. Le changement d etape vide l alerte de l ecran qu on quitte :
  // c est la regle, et elle est bonne. Mais trois branches de confirmBooking
  // posaient leur explication AVANT d appeler goStep(2), donc elle etait
  // effacee avant d avoir ete lue - mesure sur le tunnel reel :
  // alertBox.innerHTML.length = 380 apres showAlert, 0 apres goStep(2), et le
  // client renvoye au choix des horaires sans un mot. Un appelant qui a quelque
  // chose a dire SUR l ecran d arrivee le confie desormais a `options.alert` :
  // goStep vide, change d etape, puis pose. Le message survit meme a une etape
  // introuvable (bug de code, pas une raison de laisser le client sans reponse).
  if (!target) { if (options.alert) showAlert(options.alert); return; }
  clearAlert();
  lockStageScroll();
  const reduce = prefersReducedMotion();
  const animate = !reduce && options.animate !== false && previous !== n;

  if (stepArrivalTimer) { clearTimeout(stepArrivalTimer); stepArrivalTimer = null; }
  tunnelStepIds().forEach((id) => {
    const element = document.getElementById(id);
    if (!element) return;
    const current = element === target;
    element.classList.toggle('is-current', current);
    // `inert` coupe clic, focus et lecture d'écran d'un seul attribut : une
    // étape hors champ n'existe pour personne. La courante redevient vivante.
    if (current) {
      element.removeAttribute('inert');
      element.removeAttribute('aria-hidden');
    } else {
      element.setAttribute('inert', '');
      element.setAttribute('aria-hidden', 'true');
      delete element.dataset.arrived;
    }
  });

  // La piste glisse jusqu'à l'étape. Sans animation (reduced motion, boot),
  // la transition est coupée le temps de poser la position. Pendant le voyage,
  // is-travelling rend les étapes voisines visibles en profondeur (CSS).
  const track = document.getElementById('tunnelTrack');
  if (track) {
    if (!animate) track.style.transition = 'none';
    else track.classList.add('is-travelling');
    track.style.setProperty('--tstep', String(n));
    if (!animate) {
      // Reflow volontaire : la position se pose AVANT que la transition revive.
      void track.offsetWidth;
      track.style.removeProperty('transition');
    }
  }

  if (animate) {
    // Signal de cascade : les blocs `.cascade` de l'étape arrivée se posent en
    // ressort. Le signal vit le temps des animations (délai max 135 ms +
    // 500 ms de course), puis s'éteint pour ne jamais rejouer sur un rendu.
    // is-travelling s'éteint au même moment : les voisines redisparaissent.
    target.dataset.arrived = '1';
    // LA QUESTION DE L ECRAN QUI ARRIVE S ECRIT, a chaque arrivee. Le texte
    // monte mot a mot pendant que la piste finit de glisser : les deux
    // mouvements appartiennent au meme geste. Le titre de l etape 1 est traite
    // par setRevealState (il arrive avec l ouverture du bloc, pas avec
    // l etape) ; ici on prend celui des autres ecrans.
    const titreArrive = target.querySelector('.s2-side .panel-title, .s3-side .panel-title, .recap-decision .panel-title, .success-wrap h2');
    if (titreArrive) revelerQuestion(titreArrive);
    stepArrivalTimer = setTimeout(() => {
      stepArrivalTimer = null;
      delete target.dataset.arrived;
      if (track) track.classList.remove('is-travelling');
    }, 700);
  }

  state.step = n;
  const clientView = document.getElementById('clientView');
  if (clientView) clientView.dataset.step = String(n);
  updateProgress();
  // Le focus suit l'étape qui arrive : sans ça, le clavier retombe sur <body>
  // et le parcours est cassé pour qui ne se sert pas d'une souris.
  const heading = document.getElementById('stepHeading');
  if (heading) {
    heading.textContent = `Étape ${n} sur ${tunnelStepCount()} : ${STEP_LABELS[n] || ''}`;
    if (options.focus !== false) heading.focus({ preventScroll: true });
  }
  // Le dock telephone n'a voix qu'a l'etape 1 : il se tait des qu'on la quitte.
  if (typeof syncStatusDock === 'function') syncStatusDock();
  save();
  // L etape d arrivee est en place : c est ici, et seulement ici, que le
  // message de l appelant se pose. Un seul endroit, donc un seul ordre.
  if (options.alert) showAlert(options.alert);
}

function setStep1Busy(isBusy) {
  const btn = document.getElementById('btnStep1');
  if (!btn) return;
  btn.disabled = !!isBusy;
  btn.innerHTML = isBusy
    ? 'Recherche des cr\u00e9neaux...'
    : `Voir les horaires
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>`;
}

// LE SCEAU. Le clic a plus fort enjeu du tunnel accuse reception, travaille,
// puis scelle : le libelle s'efface, un disque se pose, il respire le temps de
// l'appel reseau, et la coche se dessine trait par trait. Le bouton garde sa
// boite : aucune largeur ni hauteur n'est animee, seul son contenu change
// d'etat (recette 4 du catalogue, adaptee exactement comme il le prescrit).
const SEAL_MARKUP = [
  '<span class="btn-label">Confirmer la réservation',
  '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg></span>',
  // Le disque : c'est LUI qui reste quand la pilule se dissout (morph assume).
  '<span class="btn-seal" aria-hidden="true"><span class="btn-seal-disc"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">',
  '<circle class="btn-seal-ring" cx="12" cy="12" r="10" opacity="0.35"/>',
  '<path class="btn-seal-check" d="M19 7.5 10 17l-5-5"/></svg></span></span>',
].join('');

function ensureSealMarkup(button) {
  if (!button || button.querySelector('.btn-seal')) return;
  button.innerHTML = SEAL_MARKUP;
}

function setBookingSubmitBusy(isBusy) {
  const confirmBtn = document.getElementById('btnConfirmBooking');
  const backBtn = document.getElementById('btnStep4Back');
  if (confirmBtn) {
    ensureSealMarkup(confirmBtn);
    confirmBtn.disabled = !!isBusy;
    // Le libelle reste dans le DOM (il porte le nom accessible du bouton) :
    // c'est son opacite qui s'efface, jamais son texte qui disparait.
    confirmBtn.setAttribute('aria-busy', isBusy ? 'true' : 'false');
    confirmBtn.classList.toggle('is-sealing', !!isBusy);
    if (!isBusy) confirmBtn.classList.remove('is-sealed');
  }
  if (backBtn) backBtn.disabled = !!isBusy;
}

// Succes : le disque cesse de respirer, la coche se dessine, puis on quitte.
function sealBookingSubmit() {
  const confirmBtn = document.getElementById('btnConfirmBooking');
  if (!confirmBtn) return Promise.resolve();
  ensureSealMarkup(confirmBtn);
  confirmBtn.classList.remove('is-sealing');
  confirmBtn.classList.add('is-sealed');
  confirmBtn.setAttribute('aria-busy', 'false');
  if (prefersReducedMotion()) return Promise.resolve();
  // 50 ms d'attente + 220 ms de trace : on laisse la coche se finir avant de
  // quitter l'ecran, sinon le sceau ne se voit jamais.
  return new Promise((resolve) => setTimeout(resolve, 320));
}

// --- PAGE OPTIONS DU TELEPHONE ----------------------------------------------
// Verdict Movsar 2026-08-18 : les activites se voient TOUTES d un coup, et les
// reglages (duree, tables, enfants, parties) vivent sur LEUR page, entre les
// activites et les heures : « une autre page dans la page ». Au-dessus de
// 640 px rien ne change, le configurateur reste sous la grille.
function isPhoneLayout() {
  return window.matchMedia && window.matchMedia('(max-width: 640px)').matches;
}

// Un pointeur FIN (souris, pave tactile) ou GROSSIER (doigt) : c est ce qui
// decide si un focus programmatique est un service (le clavier physique
// continue la saisie) ou une nuisance (le clavier virtuel surgit, l ecran se
// retrecit, iOS rouvre un selecteur natif).
function pointeurFin() {
  return !(window.matchMedia && window.matchMedia('(pointer: coarse)').matches);
}

function mobileOptionsAvailable() {
  // La page options n existe qu en mode A LA CARTE : une formule regle sa
  // visite dans son propre flux. Sans ce garde, des reglages carte restes
  // coches detournaient goStep2 d une reservation formule bootee a une
  // largeur telephone (attrape par visit-freedom, matrice 20 joueurs).
  if (normalizeBookingMode(state.booking.mode) !== 'carte') return false;
  return document.querySelectorAll('.activity-config-row.is-visible').length > 0;
}

function onMobileOptionsPage() {
  const stepRoot = document.getElementById('step1');
  return Boolean(stepRoot && stepRoot.classList.contains('is-options'));
}

// L ECRAN DE REGLAGES ANNONCE SA QUESTION comme les autres : elle s ecrit mot
// a mot a l arrivee. Sans ce rappel, le titre existait mais restait fige.
function revelerQuestionReglages() {
  const titre = document.querySelector('#step1.is-options .activity-configurator-title');
  if (titre && typeof revelerQuestion === 'function') revelerQuestion(titre);
}

function showMobileOptionsPage(show) {
  const stepRoot = document.getElementById('step1');
  if (!stepRoot) return;
  // Les durees qui ne rentrent plus avant la fermeture sont ramenees AVANT
  // que l ecran ne s affiche : le client lit la duree qu il aura vraiment.
  if (show && typeof ajusterDureesAvantFermeture === 'function') {
    if (ajusterDureesAvantFermeture() && typeof renderActivityPicker === 'function') renderActivityPicker();
  }
  stepRoot.classList.toggle('is-options', Boolean(show));
  resetStepOneScroll();
  if (show) revelerQuestionReglages();
  if (typeof syncStepOneCta === 'function') syncStepOneCta();
  // updateProgress rafraichit AUSSI la barre haute : l appeler evite que le
  // fil et le rang se contredisent sur l ecran des reglages.
  if (typeof updateProgress === 'function') updateProgress();
  else if (typeof syncMobileTopbar === 'function') syncMobileTopbar();
}

// Le libelle du CTA de l etape 1 dit ou il mene : « Continuer » vers la page
// options quand elle existe, « Verifier les disponibilites » sinon.
function syncStepOneCta() {
  const label = document.getElementById('btnStep1Label');
  if (!label) return;
  // L ECRAN DE REGLAGES N EST PLUS RESERVE AU TELEPHONE. Il existait deja, mais
  // seulement sous 640 px : sur ordinateur, les reglages s empilaient sous la
  // grille d activites, sur le meme ecran. C est une question a part (« combien
  // de temps ? », « combien de parties ? ») : elle a son ecran partout.
  const towardOptions = !onMobileOptionsPage() && mobileOptionsAvailable();
  const text = towardOptions ? 'Continuer' : 'Vérifier les disponibilités';
  if (label.textContent !== text) label.textContent = text;
}

async function goStep2() {
  if (isPastBusinessDate(state.booking.date)) {
    showAlert('Cette date est déjà passée. Vous ne pouvez plus réserver pour ce jour.');
    return;
  }
  // Le premier passage s arrete sur l ecran de reglages si un reglage existe ;
  // le second (depuis cet ecran) continue vers les heures. Vrai a toutes les
  // largeurs depuis le 2026-08-26 : voir syncStepOneCta.
  if (!onMobileOptionsPage() && mobileOptionsAvailable()) {
    showMobileOptionsPage(true);
    return;
  }
  showMobileOptionsPage(false);
  // getSchedule integre desormais le verdict serveur du jour : une fermeture
  // ponctuelle posee depuis le cockpit rend null ici, exactement comme un lundi.
  const schedule = getSchedule(state.booking.date, state.isHolidayMode);
  if (!schedule) { showAlert('Le centre est fermé à cette date. Choisissez une autre date.'); return; }
  const pax = Number(state.booking.pax) || 0;
  if (pax < 1) { showAlert('Nombre de joueurs invalide.'); return; }
  if (normalizeBookingMode(state.booking.mode) === 'carte' && !getChosenActivities().length) {
    showAlert('Choisissez au moins une activité.');
    return;
  }
  if (state.booking.type === 'formule') {
    const formule = resolveDisplayFormule(state.booking.formuleId);
    if (!formule) { showAlert('Sélectionnez une formule.'); return; }
    const availability = getFormuleAvailability(formule, state.booking.date, pax);
    if (!availability.ok) { showAlert(availability.message); return; }
  }
  goStep(2);
  await fetchSlots({ showLoading: true });
}

async function fetchSlots(options = {}) {
  const requestId = ++slotFetchRequestId;
  // Un ancien prix ne doit jamais survivre a une nouvelle recherche. La reponse
  // courante remettra le programme normalise si le type est bien une visite.
  state.booking.serverProgram = null;
  state.booking.bowlingCapacity = null;
  // Meme regle pour les complements de fin de reservation (montee de formule,
  // palier de laser, activite libre) : ils sont chiffres ET juges faisables sur
  // des heures precises. Une carte survivante annoncerait un supplement calcule
  // sur un creneau qui n existe plus.
  formulaComplements = [];
  formulaComplementNotice = { text: '', tone: '' };
  // Et le prix serveur du creneau courant repart de zero avec eux : c est la
  // reference contre laquelle le clic sur une montee verifie le montant promis.
  state.booking.serverPrice = 0;
  if (!options.keepAlternatives) clearBookingAlternatives();
  const formule = state.booking.type === 'formule' ? resolveDisplayFormule(state.booking.formuleId) : null;
  if (options.showLoading !== false) {
    slotLoading = true;
    state.availableSlots = [];
    // Nouvelle recherche assumée (arrivée sur l'étape, autre date) : les pistes
    // repartiront centrées sur l'heure proposée, pas sur un vieux défilement.
    anchorTrackScrollMemory.clear();
    formulaAnchorMobilePage = 0;
    renderSlots(formule);
  }
  setStep1Busy(true);

  try {
    const params = new URLSearchParams({
      date: state.booking.date,
      type: state.booking.type,
      pax: String(Number(state.booking.pax) || 1),
      // Le centre part avec CHAQUE demande de disponibilite : sans lui, l'API
      // retombe sur 'libramont' et affiche les creneaux de Fun Galaxy sur le
      // site d'un autre client.
      centerId: String(typeof getTunnelCenterId === 'function' ? getTunnelCenterId() : 'libramont')
    });
    if (state.booking.type === 'formule') {
      const preference = createDefaultFormulaPreference(state.booking.preference || {});
      params.set('formuleId', state.booking.formuleId || '');
      const chosenTimes = {};
      if (preference.preferredTimes.bowling) chosenTimes.bowling = preference.preferredTimes.bowling;
      if (preference.preferredTimes.laser_game && preference.laserPlacement !== 'onsite') {
        chosenTimes.laser_game = preference.preferredTimes.laser_game;
      }
      if (Object.keys(chosenTimes).length) params.set('preferredTimes', JSON.stringify(chosenTimes));
      if (preference.laserPlacement === 'onsite') params.set('laserPlacement', 'onsite');
      else setLaserPartTimesParam(params, preference);
    } else if (state.booking.type === 'visite') {
      // Le panier part tel quel : le serveur le renormalise et recalcule tout
      // (activites reellement vendues par ce centre, options, prix).
      params.set('program', JSON.stringify(buildBookingProgramPayload()));
      const preference = createDefaultFormulaPreference(state.booking.preference || {});
      const chosenTimes = {};
      if (preference.preferredTimes.bowling) chosenTimes.bowling = preference.preferredTimes.bowling;
      if (preference.preferredTimes.laser_game) chosenTimes.laser_game = preference.preferredTimes.laser_game;
      if (Object.keys(chosenTimes).length) params.set('preferredTimes', JSON.stringify(chosenTimes));
      setLaserPartTimesParam(params, preference);
    } else {
      params.set('duration', String(state.booking.duration));
      if (state.booking.type === 'laser') params.set('laserGames', String(getLaserGameCount(state.booking.duration)));
    }

    const payload = await apiRequest(`${API_ENDPOINTS.publicAvailability || '/api/public-availability'}?${params.toString()}`, {
      method: 'GET'
    });
    if (requestId !== slotFetchRequestId) return;

    slotLoadFailed = false;
    state.availableSlots = filterPastSlotsForDate(payload.slots || [], state.booking.date);
    formulaAnchorData = payload.anchors || null;
    formulaAnchorMessage = state.availableSlots.length ? '' : (payload.message || '');
    formulaAnchorSuggestions = Array.isArray(payload.suggestions) ? payload.suggestions : [];
    formulaComplements = Array.isArray(payload.complements) ? payload.complements : [];
    // LE PRIX AUTORITAIRE DU CRENEAU, tel que le serveur vient de le calculer.
    // C est le seul endroit du parcours ou un montant est PROMIS avant d etre
    // applique : sans cette reference, le clic sur une montee n aurait rien a
    // quoi confronter le montant de sa carte.
    state.booking.serverPrice = Number(payload.price) || 0;
    resetFormulaProgramChoice();
    adoptDefaultFormulaAnchors();
    state.booking.laneCount = Number(payload.laneCount || 0);
    state.booking.duration = Number(payload.duration || state.booking.duration || 0);
    state.booking.totalDuration = state.booking.type === 'laser'
      ? Number(state.booking.duration || 0.5) * getLaserWaveCount(state.booking.pax)
      : Number(payload.totalDuration || payload.duration || state.booking.totalDuration || 0);
    state.booking.serverProgram = state.booking.type === 'visite'
      && payload.program && Array.isArray(payload.program.items)
      ? payload.program
      : null;
    state.booking.opsPlan = null;
  } catch (error) {
    if (requestId !== slotFetchRequestId) return;
    state.availableSlots = [];
    formulaAnchorData = null;
    formulaAnchorMessage = '';
    formulaAnchorSuggestions = [];
    formulaComplements = [];
    // Panne serveur ≠ zéro créneau : renderSlots affiche l'état d'erreur
    // dédié (role="alert" + bouton Réessayer), pas l'état vide.
    slotLoadFailed = true;
    slotLoadFailedMessage = error.message || '';
  }

  if (requestId !== slotFetchRequestId) return;
  slotLoading = false;
  // `render: false` : l'appelant (revalidation en place) décide lui-même de la
  // mise à jour du DOM : deux rendus complets dos à dos faisaient clignoter.
  if (options.render !== false) renderSlots(formule);
  setStep1Busy(false);
}

function describeSlotPlan(plan) {
  if (!plan) return '';
  const bits = [];
  if (plan.firstBowlingTime) bits.push(`Bowling ${plan.firstBowlingTime}`);
  if (plan.firstLaserTime) bits.push(`Laser ${plan.firstLaserTime}`);
  if (plan.endTime) bits.push(`fin ${plan.endTime}`);
  if (!bits.length && plan.staffSummary) return plan.staffSummary.split('|').slice(0, 2).join(' · ');
  return bits.join(' · ');
}

// Heure d'une ancre dans un créneau : jamais les étapes « flexible » (pass
// liberté), qui n'ont pas d'horaire propre.
function getFormulaSlotActivityTime(slot, activityId) {
  const plan = slot?.opsPlan || {};
  if (activityId === 'bowling' && plan.firstBowlingTime) return plan.firstBowlingTime;
  if (activityId === 'laser_game' && plan.firstLaserTime) return plan.firstLaserTime;
  const item = (plan.timeline || []).find(step => step.activityId === activityId && !step.flexible);
  return item?.startTime || '';
}

// --- Picker formule « Ancres + Liberté » -------------------------------------
// Une ligne par ANCRE (Bowling, Laser) avec ses chips d'heures :00/:30. Le
// serveur pré-sélectionne une combinaison valide (zéro friction) ; chaque
// ancre reste modifiable indépendamment, avec revalidation serveur en direct.
// La table suit l'arrivée (jamais choisie) et le pass liberté n'affiche
// JAMAIS d'heure : ni ici, ni au récap, ni dans le mail.
let formulaArrivalChoice = '';      // formules sans ancre : heure d'arrivée
let formulaAnchorData = null;       // bloc `anchors` renvoyé par le serveur
let formulaAnchorMessage = '';      // message de refus de combinaison
let formulaAnchorSuggestions = [];  // combinaisons proches proposées
let formulaAnchorBusy = false;      // revalidation en cours
let formulaAdviceSignature = '';    // avis de confort deja entre en scene
let formulaAdviceDismissed = '';    // avis que le client a choisi d ecarter
let formulaJustPicked = null;       // heure qui vient d'etre retenue (capsule)
// COMPLEMENTS DE FIN DE RESERVATION (2026-09-04, deux generateurs de plus le
// 2026-09-05). Trois generateurs cote serveur, une seule forme de carte ici :
// la montee de formule pour le tunnel des formules, le palier de laser et
// l activite libre pour celui des visites a la carte. Le serveur les calcule
// AVEC le creneau retenu et les envoie dans la meme reponse : aucun
// aller-retour de plus. Elles ne survivent jamais a une nouvelle recherche de
// creneau (fetchSlots les remet a zero), sinon le recapitulatif proposerait un
// complement chiffre sur des heures que le client vient de changer.
let formulaComplements = [];        // cartes servies par le serveur
let formulaComplementBusy = '';     // formule dont le clic est en cours
// La derniere phrase dite au client sur ces cartes (« ajoutee », « plus
// disponible »). Elle vit hors du DOM parce que renderRecap reconstruit
// #recapList entier : ecrite dans le noeud seul, elle disparaissait au rendu
// suivant, c est-a-dire exactement quand elle sert.
let formulaComplementNotice = { text: '', tone: '' };

function resetFormulaProgramChoice() {
  formulaArrivalChoice = '';
}

function formulaHasAnchorUi() {
  return Boolean(formulaAnchorData && Array.isArray(formulaAnchorData.activities) && formulaAnchorData.activities.length);
}

// Défaut zéro friction : à l'arrivée sur l'étape, la combinaison valide
// proposée par le serveur est pré-sélectionnée : chaque ancre reste modifiable.
function adoptDefaultFormulaAnchors() {
  // Une VISITE composée à la carte a exactement les mêmes ancres qu'une
  // formule : elle mérite la même proposition d'ouverture. Tant que cette
  // condition exigeait « formule », le client arrivait sur l'écran sans
  // aucune heure retenue.
  if (!['formule', 'visite'].includes(state.booking.type) || !formulaHasAnchorUi()) return;
  const preference = createDefaultFormulaPreference(state.booking.preference || {});
  let changed = false;
  formulaAnchorData.activities.forEach((activity) => {
    if (activity.activityId === 'laser_game' && preference.laserPlacement === 'onsite') return;
    // UNE LISTE VIDEE PAR LE CLIENT N'EST PAS UNE LISTE JAMAIS TOUCHEE.
    // Cette proposition d'ouverture reposait l'heure par defaut a CHAQUE
    // revalidation : le client retirait sa derniere heure de laser, et elle
    // revenait toute seule au retour du serveur. Son geste etait annule sans
    // un mot.
    // La distinction est deja ecrite dans createDefaultFormulaPreference :
    // laserGameTimes vaut [] tant que rien n'a ete choisi, et un tableau a la
    // longueur des parties (cases vides comprises) des que le client y a
    // touche. On ne propose donc que sur le premier cas.
    if (activity.activityId === 'laser_game'
      && Array.isArray(preference.laserGameTimes) && preference.laserGameTimes.length) return;
    const fallback = formulaAnchorData.defaultTimes?.[activity.activityId] || '';
    if (!preference.preferredTimes[activity.activityId] && fallback) {
      preference.preferredTimes[activity.activityId] = fallback;
      // La proposition d'ouverture pose la PREMIERE partie de laser ; les
      // suivantes restent libres tant que le client ne les place pas.
      if (activity.activityId === 'laser_game') {
        const parties = getBookingLaserPartTimes(preference);
        parties[0] = fallback;
        preference.laserGameTimes = parties;
      }
      changed = true;
    }
  });
  if (changed) {
    state.booking.preference = preference;
    save();
  }
}

function getCurrentFormulaAnchorSelection() {
  const preference = createDefaultFormulaPreference(state.booking.preference || {});
  const times = {};
  (formulaAnchorData?.activities || []).forEach((activity) => {
    if (activity.activityId === 'laser_game' && preference.laserPlacement === 'onsite') return;
    times[activity.activityId] = preference.preferredTimes[activity.activityId] || '';
  });
  return { preference, times };
}

function formulaSlotMatchesTimes(slot, times) {
  return Object.entries(times || {}).every(([activityId, time]) => {
    if (!time) return false;
    const planTimes = slot?.opsPlan?.anchorPlan?.times;
    if (planTimes && planTimes[activityId]) return planTimes[activityId] === time;
    return getFormulaSlotActivityTime(slot, activityId) === time;
  });
}

function getCurrentFormulaAnchorSlotIndex() {
  const { times } = getCurrentFormulaAnchorSelection();
  return (state.availableSlots || []).findIndex((slot) => formulaSlotMatchesTimes(slot, times));
}

// Un clic = UNE réponse par phase, jamais une reconstruction. Phase 1 (tout de
// suite) : l'état choisi se pose en place et la zone de statut passe en
// vérification. Phase 2 (réponse serveur) : seuls les éléments qui ont changé
// sont réécrits. Le rendu complet ne reste que pour un VRAI changement de
// structure (ordre des activités, liste d'heures, panne).
// COMPOSEUR TELEPHONE : UNE PAGE PAR CRENEAU (2026-08-24, Movsar : « si sur
// mobile on doit swiper en haut ou en bas pour tout voir, c est echoue »).
// Deux activites reservees = deux pages ; une heure posee sur un choix
// unique avance d elle-meme ; le multi-parties garde son bouton Continuer ;
// le conseil, le pass liberte et VALIDER vivent sur la DERNIERE page.
// Au-dela de 640 px, rien ne change : ces attributs restent inertes.
let formulaAnchorMobilePage = 0;

function isMobileAnchorPaging() {
  try { return window.matchMedia('(max-width: 640px)').matches; } catch (error) { return false; }
}

// L ordre des pages est l ordre CATALOGUE (bowling avant laser), jamais
// l ordre des heures choisies : changer une heure ne rebat plus les pages
// sous les doigts (2026-08-24, Movsar : « laser en 1er et pas bowling...
// on comprend pas, ca bouge d un coup »).
function getMobileAnchorActivities() {
  return formulaAnchorData?.activities || [];
}

function setFormulaAnchorMobilePage(next, options = {}) {
  const pages = getMobileAnchorActivities();
  const count = pages.length;
  formulaAnchorMobilePage = Math.max(0, Math.min(Math.max(0, count - 1), Math.trunc(Number(next) || 0)));
  const picker = document.querySelector('#slotList .formula-anchor-picker');
  if (!picker) return;
  picker.setAttribute('data-mobile-page', String(formulaAnchorMobilePage));
  if (formulaAnchorMobilePage >= count - 1) picker.setAttribute('data-mobile-last', '1');
  else picker.removeAttribute('data-mobile-last');
  const titleActivity = picker.querySelector('[data-role="anchor-mobile-activity"]');
  if (titleActivity && pages[formulaAnchorMobilePage]) titleActivity.textContent = pages[formulaAnchorMobilePage].label || '';
  const titleCount = picker.querySelector('[data-role="anchor-mobile-count"]');
  if (titleCount) titleCount.textContent = `Activité ${formulaAnchorMobilePage + 1} sur ${count}`;
  const heroBox = picker.querySelector('[data-role="anchor-mobile-hero"]');
  if (heroBox) {
    const heroUrl = getTenantActivityImage(pages[formulaAnchorMobilePage]?.activityId);
    if (heroUrl) { heroBox.style.backgroundImage = `url('${heroUrl}')`; heroBox.removeAttribute('data-empty'); }
    else { heroBox.style.backgroundImage = ''; heroBox.setAttribute('data-empty', '1'); }
  }
  // Le bouton d avance ANNONCE ou il mene : « Continuer · Laser Game ».
  const nextLabel = picker.querySelector('[data-role="anchor-mobile-next-label"]');
  if (nextLabel) nextLabel.textContent = pages[formulaAnchorMobilePage + 1]?.label || '';
  // La page qui arrive GLISSE : le changement se voit, il ne teleporte
  // pas (2026-08-24, Movsar : « ca bouge d un coup, on comprend pas »).
  const direction = Number(options.direction) || 0;
  if (direction && !prefersReducedMotion()) {
    const incoming = picker.querySelector(`.visit-rail-step[data-mobile-index="${formulaAnchorMobilePage}"]`);
    if (incoming) {
      incoming.classList.remove('is-page-from-right', 'is-page-from-left');
      void incoming.offsetWidth;
      incoming.classList.add(direction > 0 ? 'is-page-from-right' : 'is-page-from-left');
    }
  }
  // Le nouvel ecran demarre en haut de sa zone.
  const zone = document.querySelector('#clientView .s2-slots');
  if (zone) zone.scrollTop = 0;
}

function formulaAnchorMobileBack() { setFormulaAnchorMobilePage(formulaAnchorMobilePage - 1, { direction: -1 }); }
function formulaAnchorMobileNext() { setFormulaAnchorMobilePage(formulaAnchorMobilePage + 1, { direction: 1 }); }

// « Commencer par le Laser Game » (2026-08-25, Movsar) : l activite de la
// 2e page prend l heure de DEPART de la visite, la 1re s enchaine juste
// apres. Les heures disent l ordre reel ; le moteur revalide comme pour
// n importe quel choix. Offert seulement quand la visite a DEUX ancres :
// au-dela, l ordre se compose page par page.
async function formulaAnchorStartWithNext() {
  const acts = getMobileAnchorActivities();
  if (acts.length !== 2) return;
  const [first, second] = acts;
  const preference = createDefaultFormulaPreference(state.booking.preference || {});
  const startTime = preference.preferredTimes[first.activityId]
    || formulaAnchorData?.defaultTimes?.[first.activityId]
    || anchorOkTimes(first)[0]?.time || '';
  const secondItem = startTime ? anchorOkTimes(second).find((item) => item.time >= startTime) : anchorOkTimes(second)[0];
  if (!secondItem) { setFormulaAnchorMobilePage(1, { direction: 1 }); return; }
  preference.preferredTimes[second.activityId] = secondItem.time;
  if (second.activityId === 'laser_game') {
    preference.laserPlacement = 'scheduled';
    setChosenLaserTimes(preference, [secondItem.time]);
  }
  const secondEnd = timeToNum(secondItem.time) * 60 + Number(second.durationMinutes || 60);
  const firstItem = anchorOkTimes(first).find((item) => timeToNum(item.time) * 60 >= secondEnd);
  if (firstItem) {
    preference.preferredTimes[first.activityId] = firstItem.time;
    if (first.activityId === 'laser_game') {
      preference.laserPlacement = 'scheduled';
      setChosenLaserTimes(preference, [firstItem.time]);
    }
  }
  state.booking.preference = preference;
  state.booking.startTime = '';
  state.booking.opsPlan = null;
  save();
  setFormulaAnchorMobilePage(1, { direction: 1 });
  await revalidateFormulaAnchors();
}

async function revalidateFormulaAnchors() {
  const formule = state.booking.type === 'formule' ? resolveDisplayFormule(state.booking.formuleId) : null;
  formulaAnchorBusy = true;
  if (!syncFormulaAnchorUi(formule, { busy: true })) renderSlots(formule);
  await fetchSlots({ showLoading: false, render: false });
  formulaAnchorBusy = false;
  if (!syncFormulaAnchorUi(formule, { busy: false })) renderSlots(formule);
}

// `decaler` : l heure demandee gagne, et les autres activites se replacent
// autour d elle (le moteur les pose automatiquement quand aucune heure n est
// retenue pour elles). C est la reponse au chevauchement : on deplace, on ne
// refuse pas (entretien Seb, 2026-09-17).
async function setFormulaAnchorTime(activityId, time, decaler = false) {
  const preference = createDefaultFormulaPreference(state.booking.preference || {});
  if (decaler) {
    // ON NE DEPLACE QUE CE QUI CHEVAUCHE. Liberer toutes les autres heures
    // ferait perdre au client un choix qui ne genait personne : trois parties
    // de laser posees, dont une seule tombe sur l heure demandee.
    const ancres = (typeof formulaAnchorData === 'object' && formulaAnchorData && formulaAnchorData.activities) || [];
    const moi = ancres.find((item) => item.activityId === activityId) || null;
    const debut = timeToNum(time) * 60;
    const fin = debut + Number((moi && moi.durationMinutes) || 0);
    const chevauche = (heure, minutes) => {
      if (!heure) return false;
      const d = timeToNum(heure) * 60;
      return d < fin && d + Number(minutes || 0) > debut;
    };
    Object.keys(preference.preferredTimes || {}).forEach((id) => {
      if (id === activityId) return;
      const autre = ancres.find((item) => item.activityId === id) || null;
      if (chevauche(preference.preferredTimes[id], autre && autre.durationMinutes)) preference.preferredTimes[id] = '';
    });
    // Les PARTIES de laser posees occupent leur place comme une heure retenue :
    // celles qui tombent sur l heure demandee la liberent, les autres restent.
    if (activityId !== 'laser_game' && Array.isArray(preference.laserGameTimes) && preference.laserGameTimes.length) {
      const laser = ancres.find((item) => item.activityId === 'laser_game') || null;
      const gardees = preference.laserGameTimes.filter((heure) => heure && !chevauche(heure, laser && laser.durationMinutes));
      preference.laserGameTimes = gardees;
      preference.preferredTimes.laser_game = gardees[0] || '';
    }
  }
  const parties = activityId === 'laser_game' ? getBookingLaserPartCount() : 1;
  // PLUSIEURS PARTIES : la liste est un choix MULTIPLE. Un clic ajoute l'heure,
  // un clic sur une heure deja retenue la retire. Le compte ne depasse jamais
  // le nombre de parties achetees.
  if (activityId === 'laser_game' && parties > 1) {
    const retenues = getChosenLaserTimes(preference);
    const deja = retenues.includes(time);
    if (!deja && retenues.length >= parties) return;
    const suivantes = deja ? retenues.filter(item => item !== time) : [...retenues, time];
    setChosenLaserTimes(preference, suivantes);
    // RETIRER LA DERNIERE HEURE NE VERROUILLE PAS LA LISTE (2026-08-21).
    // Movsar : « quand on decoche tous les choix on peut plus refaire de
    // choix ». Cette ligne basculait laserPlacement sur 'onsite' des que la
    // liste se vidait, et 'onsite' DESACTIVE toutes les pastilles. Quand la
    // visite n'a qu'une seule ancre (laser seul), la case « je place sur
    // place » n'est meme pas rendue (laserOnSiteAvailable exige 2 ancres) :
    // le client se retrouvait devant un ecran mort, sans aucun moyen de
    // revenir. Une vente perdue pour un clic de trop.
    //
    // Une liste VIDE en mode 'scheduled' dit deja la bonne chose : rien
    // n'est pose, l'equipe placera les parties selon l'affluence (c'est le
    // texte « avec l'equipe » rendu par renderVisitRailStep, et le serveur
    // recoit une liste vide qu'il place librement). 'onsite' reste ce qu'il
    // doit etre : une DECISION du client via sa case, jamais un effet de
    // bord d'un declic.
    if (suivantes.length) preference.laserPlacement = 'scheduled';
    formulaJustPicked = deja ? null : { activityId, time };
  } else {
    if (preference.preferredTimes[activityId] === time && preference.laserPlacement !== 'onsite') {
      // Taper l heure deja retenue ne fait RIEN de plus : on n avance
      // jamais de page tout seul (2026-08-24, Movsar : « on doit confirmer
      // l heure, pas rediriger direct »). Le bouton Continuer annonce la
      // suite et porte le geste.
      return;
    }
    // La pastille qui vient d'etre choisie ressort UNE fois, DES le clic : le
    // client voit ou son clic a atterri sans attendre le reseau (recette 6).
    formulaJustPicked = { activityId, time };
    preference.preferredTimes[activityId] = time;
    if (activityId === 'laser_game') {
      preference.laserPlacement = 'scheduled';
      preference.laserGameTimes = [time];
    }
  }
  state.booking.preference = preference;
  state.booking.startTime = '';
  state.booking.opsPlan = null;
  save();
  await revalidateFormulaAnchors();
  // Taper une heure la POSE, point. L avance vers le creneau suivant est
  // un geste explicite (bouton « Continuer · <activite suivante> ») : un
  // ecran qui bouge tout seul n explique jamais pourquoi (2026-08-24).
}

function getDefaultLaserTimeAfterBowling(preference) {
  const laser = (formulaAnchorData?.activities || []).find((activity) => activity.activityId === 'laser_game');
  if (!laser) return '';
  const fallback = formulaAnchorData?.defaultTimes?.laser_game || anchorOkTimes(laser)[0]?.time || '';
  const bowlingTime = preference.preferredTimes.bowling;
  const bowling = (formulaAnchorData?.activities || []).find((activity) => activity.activityId === 'bowling');
  if (!bowlingTime || !bowling) return fallback;
  const bowlingEnd = timeToNum(bowlingTime) * 60 + Number(bowling.durationMinutes || 60);
  // >= la fin PILE : le defaut enchaine, il ne vend pas 30 minutes d attente
  // (meme regle que le moteur depuis le 2026-08-24).
  const next = anchorOkTimes(laser).find((item) => timeToNum(item.time) * 60 >= bowlingEnd);
  return next?.time || fallback;
}

async function setFormulaLaserPlacement(placement) {
  const preference = createDefaultFormulaPreference(state.booking.preference || {});
  const next = placement === 'onsite' ? 'onsite' : 'scheduled';
  if (preference.laserPlacement === next) return;
  preference.laserPlacement = next;
  const parties = getBookingLaserPartTimes(preference);
  if (next === 'onsite') {
    preference.laserGameTimes = parties.map(() => '');
    preference.preferredTimes.laser_game = '';
  } else {
    // Retour au mode « je choisis » : seule la 1re partie reprend une heure par
    // defaut, les suivantes restent libres tant que le client ne les pose pas.
    const premiere = getDefaultLaserTimeAfterBowling(preference);
    preference.laserGameTimes = parties.map((_, index) => (index === 0 ? premiere : ''));
    preference.preferredTimes.laser_game = premiere;
  }
  state.booking.preference = preference;
  state.booking.startTime = '';
  state.booking.opsPlan = null;
  save();
  await revalidateFormulaAnchors();
}

async function applyFormulaAnchorSuggestion(index) {
  const suggestion = (formulaAnchorSuggestions || [])[index];
  if (!suggestion || !suggestion.times) return;
  const preference = createDefaultFormulaPreference(state.booking.preference || {});
  Object.entries(suggestion.times).forEach(([activityId, time]) => {
    if (Object.prototype.hasOwnProperty.call(preference.preferredTimes, activityId)) {
      preference.preferredTimes[activityId] = time;
    }
  });
  // UNE SUGGESTION PORTE SUR LES ANCRES, DONC SUR LA 1re PARTIE DE LASER. Sans
  // cette ligne, la liste par partie gardait l'heure REFUSEE (elle prime sur
  // l'ancre) et la suggestion ne changeait rien : le client cliquait « ces
  // horaires fonctionnent » et restait bloque sur le meme refus.
  if (suggestion.times.laser_game) {
    const parties = getBookingLaserPartTimes(preference);
    if (parties.length) {
      parties[0] = suggestion.times.laser_game;
      preference.laserGameTimes = parties;
    }
    preference.laserPlacement = 'scheduled';
  }
  state.booking.preference = preference;
  save();
  await revalidateFormulaAnchors();
}

async function resetFormulaAnchorChoices() {
  state.booking.preference = createDefaultFormulaPreference();
  state.booking.startTime = '';
  state.booking.opsPlan = null;
  save();
  await revalidateFormulaAnchors();
}

// LES RENDEZ-VOUS LASER, UNE SEULE FOIS POUR TOUT LE TUNNEL.
//
// Un groupe plus grand que l arene passe en plusieurs VAGUES, et toutes les
// vagues d une meme partie portent le meme `countIndex` (lib/ops-engine.js).
// Les deux ecrans qui annoncaient l heure s en remettaient a cette cle et n en
// gardaient qu une : la carte de visite gardait la DERNIERE vague, le
// recapitulatif de validation la PREMIERE. Un groupe de 49 lisait donc 11:30
// d un cote et 11:00 de l autre, apres avoir choisi 11:00.
//
// Ici la cle est la paire (partie, vague) : chaque passage compte. Et quand le
// groupe passe en plusieurs fois, le rang de vague est DIT, parce qu une
// moitie du groupe doit savoir qu elle passe apres l autre. Les deux nombres
// viennent du bloc (`groupWaveIndex`, `groupWaveCount`), rien n est estime.
function rendezVousLaser(blocks) {
  const passages = [...new Map((Array.isArray(blocks) ? blocks : [])
    .filter((block) => block.resourceType === 'laser_arena' && block.startTime)
    .map((block) => [`${Number(block.countIndex || 1)}.${Number(block.groupWaveIndex || 1)}`, block]))
    .values()]
    .sort((gauche, droite) => (Number(gauche.countIndex || 1) - Number(droite.countIndex || 1))
      || (Number(gauche.groupWaveIndex || 1) - Number(droite.groupWaveIndex || 1)));
  const parties = new Set(passages.map((block) => Number(block.countIndex || 1))).size;
  return passages.map((block, index) => {
    const vagues = Number(block.groupWaveCount || 1);
    const precisions = [];
    if (parties > 1) precisions.push(`partie ${Number(block.countIndex || index + 1)}`);
    if (vagues > 1) precisions.push(`groupe ${Number(block.groupWaveIndex || 1)} sur ${vagues}`);
    return {
      heure: block.startTime,
      texte: `Laser Game ${block.startTime}${precisions.length ? ` (${precisions.join(', ')})` : ''}`,
    };
  });
}

// L AVANCE D ARRIVEE D UN PLAN, en minutes : dix par defaut, et ZERO EST UNE
// VALEUR (2026-10-13) : la premiere activite ouvre la journee, le groupe vient
// a son heure. `arrivalMinutes || 10` lui faisait dire « 10 min avant ».
function avanceDArrivee(plan) {
  const brut = plan ? plan.arrivalMinutes : null;
  if (brut === null || brut === undefined || brut === '' || !Number.isFinite(Number(brut))) return 10;
  return Math.max(0, Math.round(Number(brut)));
}

// Carte « votre visite » : les rendez-vous (ancres), la table dès l'arrivée et
// le pass liberté : sans aucune heure pour les activités libres.
function renderFormulaVisitSummary(slot, formule) {
  const plan = slot?.opsPlan;
  if (!plan) return '';
  const blocks = Array.isArray(plan.resourceBlocks) ? plan.resourceBlocks : [];
  const bowlingBlock = blocks.find(block => block.resourceType === 'bowling_lane');
  const tableBlock = blocks.find(block => block.resourceType === 'party_table');
  // L ORDRE DU RESUME EST CELUI DE LA VISITE, PAS CELUI DU CATALOGUE
  // (2026-09-07, Movsar : « cite simplement, a chaque fois, les activites qui
  // sont en premier »). Le bowling etait pousse en tete quoi qu il arrive :
  // avec un bowling a 14h30 et un laser a 14h, la ligne annoncait
  // « Bowling 14:30 · Laser Game 14:00 », soit l inverse de ce que le client
  // va vivre, juste sous un fil qui, lui, affichait le bon ordre.
  const rendezVous = [];
  if (bowlingBlock?.startTime) rendezVous.push({ heure: bowlingBlock.startTime, texte: `Bowling ${bowlingBlock.startTime}` });
  // CHAQUE PARTIE POSEE EST UN RENDEZ-VOUS, ET CHAQUE VAGUE AUSSI : un client
  // qui place sa partie 1 a 15h et sa partie 3 a 19h validait un recapitulatif
  // qui taisait son deuxieme choix, et un groupe scinde en deux vagues n en
  // lisait qu une. Le calcul vit dans `rendezVousLaser`, partage avec le
  // recapitulatif de validation : c est la meme heure des deux cotes.
  rendezVous.push(...rendezVousLaser(blocks));
  // Les heures sont en HH:MM : l ordre alphabetique EST l ordre chronologique.
  rendezVous.sort((gauche, droite) => String(gauche.heure).localeCompare(String(droite.heure)));
  const appointments = rendezVous.map((item) => item.texte);
  const arrivalTime = plan.arrivalTime || '';
  const arrivalMinutes = avanceDArrivee(plan);

  const remainingLaser = Number(plan.laserPassPlan?.remainingGames || 0);
  const rows = [];
  // L ORDRE EST CELUI DE LA VISITE : on arrive, puis on joue. L arrivee etait
  // en deuxieme, sous les rendez-vous, alors que c est la premiere chose que le
  // client doit faire et la seule heure qu il doit retenir.
  if (arrivalTime) {
    rows.push(`<div class="visit-line"><span class="visit-tag arrival">Arrivée</span><span><strong>${escapeHtml(arrivalTime)}</strong>, ${arrivalMinutes > 0 ? `soit ${arrivalMinutes} min avant le début` : 'à l’heure du début'}</span></div>`);
  }
  if (appointments.length) {
    rows.push(`<div class="visit-line"><span class="visit-tag reserved">Vos rendez-vous</span><strong>${appointments.map(escapeHtml).join(' · ')}</strong></div>`);
  }
  if (tableBlock || formulaAnchorData?.hasTable || (formule && formulaHasPartyTable(formule))) {
    rows.push(`<div class="visit-line"><span class="visit-tag table">Table</span><span>Table prête à votre arrivée${arrivalTime ? ` (${escapeHtml(arrivalTime)})` : ''}</span></div>`);
  }
  if (remainingLaser > 0) {
    rows.push(`<div class="visit-line"><span class="visit-tag laser">Laser</span><span>${remainingLaser} partie${remainingLaser > 1 ? 's' : ''} à placer sur place avec l'équipe</span></div>`);
  }
  // CE QUI SE VIT SANS HORAIRE EST LA DERNIERE LIGNE DE LA VISITE, pas un
  // second panneau. La regle de 2026-09-07 (« ne pas le dire deux fois ») est
  // tenue MIEUX qu avant : il n y a plus qu un seul endroit qui le dit.
  rows.push(ligneSansHoraire(formule));
  return `<div class="formula-visit-summary">${rows.filter(Boolean).join('')}</div>`;
}

// --- Hiérarchie des heures ---------------------------------------------------
// 26 à 27 pastilles par activité, toutes identiques : rien ne distinguait une
// heure d'une autre et la page faisait 1732 px sur un téléphone (mesure du
// 2026-08-15). Les heures se rangent donc en trois moments de journée, et un
// seul moment est déplié : celui qui contient l'heure retenue. Aucune heure
// n'est retirée, chaque moment annonce sa plage ET son nombre d'heures.
const ANCHOR_PERIODS = [
  { key: 'matin', label: 'Matin', maxHour: 12 },
  { key: 'apresmidi', label: 'Après-midi', maxHour: 18 },
  { key: 'soir', label: 'Soir', maxHour: 24 },
];

// L ICONE DU MOMENT (Movsar, 2026-09-17, maquette a l appui) : un lever de
// soleil, un soleil, une lune. Elle est DECORATIVE (aria-hidden) : le nom du
// moment reste ecrit a cote, jamais porte par le dessin seul.
const ANCHOR_PERIOD_ICONS = {
  matin: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 2v3"/><path d="m5.6 8.6 1.8 1.8"/><path d="m18.4 8.6-1.8 1.8"/><path d="M8 18a4 4 0 0 1 8 0"/><path d="M3 18h18"/><path d="M5 22h14"/></svg>',
  apresmidi: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4.2"/><path d="M12 2v2.2"/><path d="M12 19.8V22"/><path d="M2 12h2.2"/><path d="M19.8 12H22"/><path d="m5 5 1.6 1.6"/><path d="m17.4 17.4 1.6 1.6"/><path d="m19 5-1.6 1.6"/><path d="m6.6 17.4-1.6 1.6"/></svg>',
  soir: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.8 14.2A8.6 8.6 0 1 1 10.4 3.4a6.8 6.8 0 0 0 10.4 10.8Z"/></svg>',
};

// CE QUE LE CLIENT A DEPLIE, par activite et par moment. L etat vit ICI et
// pas dans le DOM : chaque revalidation reconstruit la grille, et un moment
// ouvert a la main ne doit pas se refermer dans le dos du client.
const anchorPeriodsOpen = {};

// PLIE / DEPLIE UN MOMENT DE LA JOURNEE (« genre pliant depliant »).
function basculerPeriodeHeures(bouton) {
  const section = bouton && bouton.closest ? bouton.closest('.slot-period') : null;
  if (!section) return;
  const cle = section.getAttribute('data-period-key') || '';
  const ouvert = !section.classList.contains('is-open');
  section.classList.toggle('is-open', ouvert);
  bouton.setAttribute('aria-expanded', ouvert ? 'true' : 'false');
  if (cle) anchorPeriodsOpen[cle] = ouvert;
}

function getAnchorPeriodKey(time) {
  const hour = Math.floor(timeToNum(time));
  return (ANCHOR_PERIODS.find(period => hour < period.maxHour) || ANCHOR_PERIODS[ANCHOR_PERIODS.length - 1]).key;
}

function groupAnchorTimes(items) {
  return ANCHOR_PERIODS
    .map(period => ({ ...period, items: items.filter(item => getAnchorPeriodKey(item.time) === period.key) }))
    .filter(period => period.items.length);
}

// L'heure qui ENCHAÎNE cette activité juste après l'autre : c'est la
// proposition que le moteur calcule tout seul. On la marque au lieu de laisser
// 27 pastilles se valoir. Rien n'est imposé : le reste reste cliquable.
function getChainedAnchorTime(activityId) {
  const activities = formulaAnchorData?.activities || [];
  const self = activities.find(activity => activity.activityId === activityId);
  if (!self) return '';
  const { times } = getCurrentFormulaAnchorSelection();
  let earliest = null;
  activities.forEach((other) => {
    if (other.activityId === activityId) return;
    const start = times[other.activityId];
    if (!start) return;
    // Fin de l autre activite, SANS marge : la pastille « Enchaine » designe
    // l heure collee. Le +5 d avant, croise a la grille de 30, la posait
    // 30 minutes plus tard : une attente vendue comme un enchainement.
    const end = timeToNum(start) * 60 + Number(other.durationMinutes || 60);
    if (earliest === null || end > earliest) earliest = end;
  });
  if (earliest === null) return '';
  const next = anchorOkTimes(self).find(item => timeToNum(item.time) * 60 >= earliest);
  return next?.time || '';
}

// Les heures d une activite qui TIENNENT pour la visite entiere. Depuis le
// 2026-09-03 le moteur rend toutes les heures de la journee et marque celles
// qui ne passent pas ({ ok:false, reason }) : elles s affichent grisees avec
// leur raison, mais aucun defaut, aucun enchainement, aucun resserrement ne
// doit les choisir.
function anchorOkTimes(activity) {
  return (activity?.times || []).filter(item => item && item.ok !== false);
}

// Ordre RÉEL de la visite : les activités se suivent dans l'ordre des heures
// choisies, pas dans l'ordre du catalogue. C'est ce qui fait qu'un client lit
// une visite et non deux réservations posées l'une sous l'autre.
function getVisitRailSteps() {
  const { times } = getCurrentFormulaAnchorSelection();
  return (formulaAnchorData?.activities || [])
    .map((activity, index) => ({
      activity,
      index,
      startMinutes: times[activity.activityId] ? timeToNum(times[activity.activityId]) * 60 : null,
    }))
    .sort((left, right) => {
      if (left.startMinutes === null && right.startMinutes === null) return left.index - right.index;
      if (left.startMinutes === null) return 1;
      if (right.startMinutes === null) return -1;
      return left.startMinutes - right.startMinutes;
    });
}

function getSlotComfortNotices() {
  const slotIndex = getCurrentFormulaAnchorSlotIndex();
  const slot = slotIndex >= 0 ? state.availableSlots[slotIndex] : null;
  return Array.isArray(slot?.opsPlan?.comfortNotices) ? slot.opsPlan.comfortNotices : [];
}

// « Enchaîner à 16:30 » : le geste que propose l'avis. Il déplace UNE ancre,
// jamais toute la visite, et passe par le chemin normal (revalidation serveur).
// L'avis SORT avant le re-rendu, vers l'activité qu'il vient de recoller :
// le mouvement dit ce qui vient de se passer au lieu de faire disparaître un
// encadré d'une image à l'autre.
async function tightenFormulaAnchorGap(activityId, time) {
  if (!activityId || !time) return;
  const advice = document.querySelector('.visit-rail-advice');
  if (advice && !prefersReducedMotion()) {
    advice.classList.add('is-leaving');
    await new Promise((resolve) => setTimeout(resolve, 150)); // = --dur-exit
  }
  await setFormulaAnchorTime(activityId, time);
}

// Le moment n'est plus un FILTRE mais un SAUT : la piste porte toute la
// journée, on se déplace dedans. Défilement natif, jamais un défilement maison.
function setFormulaAnchorPeriod(activityId, periodKey) {
  const track = document.querySelector(`.anchor-track[data-anchor="${activityId}"]`);
  const mark = track ? track.querySelector(`[data-period-start="${periodKey}"]`) : null;
  if (track && mark) {
    track.scrollTo({
      left: Math.max(0, mark.offsetLeft - track.offsetLeft - 4),
      behavior: prefersReducedMotion() ? 'auto' : 'smooth',
    });
    syncAnchorTrackState(track);
  }
}

// Fait défiler la piste d'une « page » : c'est ce qui rend le hors-champ
// atteignable à la souris et au clavier sans geste tactile.
function nudgeAnchorTrack(activityId, direction) {
  const track = document.querySelector(`.anchor-track[data-anchor="${activityId}"]`);
  if (!track) return;
  track.scrollBy({
    left: direction * Math.max(120, track.clientWidth - 72),
    behavior: prefersReducedMotion() ? 'auto' : 'smooth',
  });
}

// État visible de la piste : ce qui dépasse à gauche, ce qui dépasse à droite,
// et le moment de journée où l'on se trouve. Un défilement horizontal sans
// indicateur est un piège : on ne sait pas qu'il reste des heures.
// TOUTES LES LECTURES D ABORD, LES ECRITURES ENSUITE. Lire une geometrie
// (offsetLeft) APRES avoir ecrit dans le DOM oblige le navigateur a recalculer
// la mise en page avant de repondre, et il le refaisait a chaque appel. Profil
// DevTools du changement d etape, 2026-09-19 : 102 ms passes ici, 12 images
// perdues, une tache longue de 113 a 184 ms, alors que la meme page au repos
// n en perd aucune.
function syncAnchorTrackState(track) {
  if (!track) return;
  const max = track.scrollWidth - track.clientWidth;
  const left = track.scrollLeft;
  const trackLeft = track.offsetLeft;
  const marks = [...track.querySelectorAll('[data-period-start]')];
  const positions = marks.map((mark) => mark.offsetLeft);
  const state_ = max <= 1 ? 'none' : (left <= 1 ? 'end' : (left >= max - 1 ? 'start' : 'both'));
  if (track.dataset.overflow !== state_) track.dataset.overflow = state_;
  const shell = track.closest('.anchor-periods');
  if (!shell) return;
  // « Le apres-midi soir sert a rien si plus rien ne va » (Movsar). Sauter dans
  // la journee n'a de sens que s'il y a quelque chose hors du champ : quand la
  // piste tient entiere, les onglets occupent une ligne pour ne rien apporter.
  shell.classList.toggle('has-jumps', state_ !== 'none');
  shell.querySelectorAll('.anchor-track-nudge').forEach((button) => {
    const disabled = button.dataset.direction === '-1'
      ? (state_ === 'none' || state_ === 'end')
      : (state_ === 'none' || state_ === 'start');
    if (button.disabled !== disabled) button.disabled = disabled;
  });
  // Onglet actif = le moment réellement sous les yeux (bord gauche de la piste).
  // Les positions ont ete relevees en tete de fonction, avant toute ecriture.
  let current = marks[0]?.dataset.periodStart || '';
  marks.forEach((mark, index) => { if (positions[index] - trackLeft <= left + 8) current = mark.dataset.periodStart; });
  shell.querySelectorAll('.anchor-period-tab').forEach((tab) => {
    const active = tab.dataset.period === current;
    tab.classList.toggle('active', active);
    tab.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
}

// La position de lecture de chaque piste survit aux rendus complets : un
// client qui regardait le soir ne doit pas être ramené de force sur l'heure
// active parce qu'un rendu est passé par là. La mémoire se vide à l'arrivée
// sur l'étape (fetch avec chargement visible) : là, recentrer est un service.
const anchorTrackScrollMemory = new Map();

function snapshotAnchorTrackScroll() {
  document.querySelectorAll('.anchor-track[data-anchor]').forEach((track) => {
    anchorTrackScrollMemory.set(track.dataset.anchor, track.scrollLeft);
  });
}

// --- LE FIL SE REORDONNE SOUS LES YEUX (2026-09-07) --------------------------
// Movsar, sur la video : « ca le passe en premier, sauf qu il n y a aucune
// animation, on ne comprend rien ». Choisir pour le bowling une heure anterieure
// a celle du laser fait passer le bowling devant : le fil suit l ordre REEL de
// la visite, pas celui du catalogue. C est juste, mais invisible : l ordre
// change, donc syncFormulaAnchorUi rend false, donc le picker est reconstruit
// en entier. Les lignes ne se DEPLACENT pas : elles cessent d exister et
// reapparaissent ailleurs.
//
// Une animation d entree ne reparerait rien : un noeud qui vient d etre cree ne
// peut pas montrer d ou il vient. Il faut la position d AVANT. FLIP : relever
// les positions avant de reconstruire, comparer apres, ramener chaque ligne a
// son ancienne place, puis la laisser rejoindre la nouvelle. Le mouvement EST
// le message.
//
// L identite d une ligne, c est son activite ET son rang parmi les lignes de la
// meme activite : trois parties de laser portent le meme data-anchor, et leur
// ordre relatif ne change pas quand une autre activite les depasse.
function releverPositionsFilVisite() {
  const positions = new Map();
  const compteurs = new Map();
  // UNE ANIMATION ENCORE EN VOL FAUSSE LA MESURE : getBoundingClientRect INCLUT
  // la transformation. Un clic d heure declenche DEUX rendus (le rendu
  // « occupe », puis celui d apres la reponse du serveur) ; sans ce nettoyage,
  // le second relevait la ligne a sa position ANIMEE, croyait a un deplacement
  // de 497 px qui n existait pas, et rejouait le trajet. Mesure : le meme saut
  // joue deux fois de suite.
  document.querySelectorAll('#slotList .visit-rail-step').forEach((ligne) => {
    if (!ligne.style.transform) return;
    ligne.style.removeProperty('transition');
    ligne.style.removeProperty('transform');
    ligne.style.removeProperty('position');
    ligne.style.removeProperty('z-index');
  });
  document.querySelectorAll('#slotList .visit-rail-step').forEach((ligne) => {
    const row = ligne.querySelector('.anchor-row[data-anchor]');
    if (!row) return;
    const id = row.dataset.anchor;
    const rang = compteurs.get(id) || 0;
    compteurs.set(id, rang + 1);
    const boite = ligne.getBoundingClientRect();
    // LES DEUX AXES. Le fil est vertical sur telephone, mais au-dela de ~900 px
    // les etapes se rangent COTE A COTE : mesure a 1100 px, « passer le bowling
    // devant » echange deux colonnes, un deplacement purement horizontal. Un
    // FLIP qui ne connait que Y ne montrerait rien la ou le client regarde.
    positions.set(id + '#' + rang, { x: boite.left, y: boite.top });
  });
  return positions;
}

// L ANNONCE DU NOUVEL ORDRE (2026-09-07). Movsar, sur la premiere version du
// FLIP : « tu m as fait une animation, mais on ne comprend pas, elle est trop
// rapide [...] mets un petit texte vraiment en motion design, un truc tres bref
// qui dit OK, laser game en premier ». Le deplacement seul demande au client de
// deviner ce qui vient de se passer ; la phrase le lui DIT, pendant que ca se
// passe. Elle est en position absolue : elle ne prend aucune hauteur, donc elle
// ne peut pas faire respirer un cadre embarque.
function nommerLesEtapesDuFil() {
  const noms = [];
  document.querySelectorAll('#slotList .visit-rail-step').forEach((ligne) => {
    const titre = ligne.querySelector('.anchor-row-head strong');
    const nom = titre ? titre.textContent.trim() : '';
    // Trois parties de laser portent trois fois le meme nom : on ne repete pas.
    if (nom && nom !== noms[noms.length - 1]) noms.push(nom);
  });
  return noms;
}

function annoncerNouvelOrdre(noms) {
  if (!noms || noms.length < 2) return;
  // ELLE VIT DANS LE BODY, PAS DANS LE PICKER. Un clic d heure declenche DEUX
  // rendus : celui d avant la reponse serveur, puis celui d apres. Le second
  // remplace tout le contenu de #slotList, donc il effacait la phrase au bout
  // de quelques centaines de millisecondes, exactement quand le client
  // commencait a la lire. Mesure : absente 420 ms apres le clic.
  const hote = document.body;
  const precedente = hote.querySelector('.visit-ordre-annonce');
  if (precedente) precedente.remove();
  const texte = noms.length === 2
    ? noms[0] + " d’abord, puis " + noms[1]
    : 'Nouvel ordre : ' + noms.join(', puis ');
  const bulle = document.createElement('div');
  bulle.className = 'visit-ordre-annonce';
  // role=status : la phrase est lue par les lecteurs d ecran, qui ne voient
  // pas le deplacement.
  bulle.setAttribute('role', 'status');
  // Elle se pose sous la barre d etapes, a la meme hauteur mesuree que les
  // alertes : le seul endroit du cadre qui ne cache rien d utile.
  if (typeof poserPlafondAlerte === 'function') poserPlafondAlerte();
  bulle.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6.5 9.4 17.1l-5.4-5.4"/></svg><span></span>';
  bulle.querySelector('span').textContent = texte;
  hote.appendChild(bulle);
  const sortie = setTimeout(() => bulle.classList.add('is-leaving'), 1400);
  setTimeout(() => { clearTimeout(sortie); bulle.remove(); }, 1780);
}

function jouerFlipFilVisite(avant) {
  if (!avant || !avant.size) return;
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const compteurs = new Map();
  const gestes = [];
  document.querySelectorAll('#slotList .visit-rail-step').forEach((ligne) => {
    const row = ligne.querySelector('.anchor-row[data-anchor]');
    if (!row) return;
    const id = row.dataset.anchor;
    const rang = compteurs.get(id) || 0;
    compteurs.set(id, rang + 1);
    const depart = avant.get(id + '#' + rang);
    if (!depart) return;
    const boite = ligne.getBoundingClientRect();
    const dx = depart.x - boite.left;
    const dy = depart.y - boite.top;
    // Sous 4 px ce n est pas un deplacement, c est un arrondi de mise en page.
    // L animer ferait vibrer des lignes qui n ont pas bouge, exactement le
    // defaut qu on vient de corriger sur l ecran des activites.
    if (Math.abs(dx) < 4 && Math.abs(dy) < 4) return;
    gestes.push([ligne, dx, dy]);
  });
  if (!gestes.length) return;
  // L ORDRE DES ACTIVITES a-t-il change, ou est-ce une partie de laser qui a
  // bouge dans sa propre activite ? Seul le premier cas merite une phrase.
  const suiteAvant = [...avant.keys()].map((cle) => cle.split('#')[0]).filter((id, i, tous) => id !== tous[i - 1]);
  const suiteApres = [];
  document.querySelectorAll('#slotList .visit-rail-step').forEach((ligne) => {
    const row = ligne.querySelector('.anchor-row[data-anchor]');
    if (row && row.dataset.anchor !== suiteApres[suiteApres.length - 1]) suiteApres.push(row.dataset.anchor);
  });
  if (suiteAvant.join('>') !== suiteApres.join('>')) annoncerNouvelOrdre(nommerLesEtapesDuFil());
  for (const [ligne, dx, dy] of gestes) {
    ligne.style.transition = 'none';
    ligne.style.transform = 'translate(' + dx + 'px, ' + dy + 'px)';
    // Au-dessus des voisines pendant qu elle passe devant : sans ca, la carte
    // qui se deplace glisse SOUS l autre et on perd le trajet a mi-chemin.
    ligne.style.position = 'relative';
    ligne.style.zIndex = '2';
  }
  // FORCER LE RECALCUL DE STYLE. requestAnimationFrame NE SUFFIT PAS : les
  // callbacks rAF s executent AVANT le premier calcul de style de la frame, si
  // bien que le navigateur ne voyait jamais la position de depart : il lisait
  // directement translate(0,0) et il n y avait rien a interpoler. Mesure : la
  // ligne se teleportait quand personne ne lisait le DOM, et se deplacait
  // quand un observateur (une sonde, l inspecteur) forcait le calcul par
  // accident. Cette lecture EST le declencheur, elle ne decore pas.
  void gestes[0][0].offsetWidth;
  requestAnimationFrame(() => {
    for (const [ligne] of gestes) {
      // 620 ms et non 420 : « on ne comprend pas, elle est trop rapide ». Une
      // colonne qui traverse 500 px en 420 ms se lit comme un saut.
      ligne.style.transition = 'transform 620ms cubic-bezier(0.16, 1, 0.3, 1)';
      ligne.style.transform = 'translate(0, 0)';
    }
    setTimeout(() => {
      for (const [ligne] of gestes) {
        ligne.style.removeProperty('transition');
        ligne.style.removeProperty('transform');
        ligne.style.removeProperty('position');
        ligne.style.removeProperty('z-index');
      }
    }, 680);
  });
}

// Un seul écouteur passif par piste, calé sur la fréquence d'affichage : on ne
// touche au DOM que lorsque l'état CHANGE (voir syncAnchorTrackState).
function bindAnchorTracks() {
  document.querySelectorAll('.anchor-track').forEach((track) => {
    if (track.dataset.bound === '1') return;
    track.dataset.bound = '1';
    let queued = false;
    track.addEventListener('scroll', () => {
      if (queued) return;
      queued = true;
      requestAnimationFrame(() => { queued = false; syncAnchorTrackState(track); });
    }, { passive: true });
    // ON PLACE LA PISTE, PUIS ON LIT SON ETAT, UNE SEULE FOIS. L appel qui
    // precedait le positionnement lisait une geometrie qu on allait changer
    // juste apres : deux recalculs de mise en page pour un seul resultat.
    const remembered = anchorTrackScrollMemory.get(track.dataset.anchor);
    if (remembered != null) {
      // Rendu complet en cours de parcours : la piste reprend sa position, elle
      // ne saute pas.
      if (Math.abs(track.scrollLeft - remembered) > 1) track.scrollLeft = remembered;
    } else {
      // L'heure retenue doit être sous les yeux à l'ouverture, pas trois écrans
      // plus loin dans la piste.
      const active = track.querySelector('.anchor-chip.active');
      if (active) {
        track.scrollLeft = Math.max(0, active.offsetLeft - track.offsetLeft - track.clientWidth / 2 + active.offsetWidth / 2);
      }
    }
    syncAnchorTrackState(track);
  });
}

// LE CRENEAU EST UNE CARTE, PARTOUT.
// Movsar (2026-08-15), en comparant les deux ecrans du tunnel : « pour les
// heures regardes les cartes de la deuxieme image qui affiche comme ca cest
// bcp plus pro et beau ». La pastille ronde ne portait que l heure de debut :
// elle laissait ouvertes les deux questions qui decident (quand est-ce que ca
// finit, ce creneau vaut-il mieux qu un autre). La carte les REPOND, sur trois
// niveaux : l heure en chiffres tabulaires, la fin calculee sur la duree
// REELLE de l activite, et une qualification quand le moteur en fournit une.
// Une seule famille de composant sert les deux modes du tunnel : ce qui change
// d un contexte a l autre, c est la DONNEE portee, jamais la forme.
// AUCUNE LIGNE N EST INVENTEE : sans donnee, la ligne n existe pas.
function slotCardMarkup({ time, endTime, tag, tagTone, meta }) {
  // Trois niveaux de lecture, chacun sur sa ligne : l heure, la qualification,
  // le secondaire. La carte reste ETROITE (une ligne longue la ferait grossir
  // en largeur et chasserait les creneaux voisins hors du champ).
  return [
    `<span class="slot-card-time">${escapeHtml(time)}</span>`,
    tag ? `<span class="slot-card-tag${tagTone ? ` is-${tagTone}` : ''}">${escapeHtml(tag)}</span>` : '',
    endTime ? `<span class="slot-card-end">→ ${escapeHtml(endTime)}</span>` : '',
    meta ? `<span class="slot-card-meta">${escapeHtml(meta)}</span>` : '',
  ].join('');
}

// Le modele d une carte d heure dans le composeur de visite. Tout vient de la
// reponse du moteur : `durationMinutes` de l activite, `lanes` allouees pour
// le bowling, `remainingPlaces` / `sharedSession` pour le laser.
function anchorSlotCardModel(activity, item, { isChained, unavailable = false, decale = null } = {}) {
  const duration = Number(activity.durationMinutes || 0);
  const endTime = duration > 0 ? numToTime(timeToNum(item.time) + duration / 60) : '';
  let tag = '';
  let tagTone = '';
  if (isChained) { tag = 'Enchaîné'; tagTone = 'accent'; }
  // L heure se prend et DEPLACE l autre activite : la carte le dit avant le
  // clic, en toutes lettres, jamais par la seule couleur.
  if (decale) { tag = 'On décale'; tagTone = 'shift'; }
  const bits = [];
  if (Array.isArray(item.lanes) && item.lanes.length) {
    bits.push(`${item.lanes.length} piste${item.lanes.length > 1 ? 's' : ''}`);
  }
  if (Number.isFinite(Number(item.remainingPlaces)) && Number(item.remainingPlaces) > 0) {
    bits.push(`${Number(item.remainingPlaces)} place${Number(item.remainingPlaces) > 1 ? 's' : ''}`);
  }
  if (item.sharedSession) bits.push('session partagée');
  // Heure impossible : la raison courte du moteur REMPLACE le secondaire
  // (pistes, places), qui ne veut plus rien dire pour une heure qu on ne
  // peut pas prendre.
  const meta = decale
    ? `${decale.label} se décale`
    : unavailable ? (item.reason || 'Indisponible') : bits.join(' · ');
  const label = [
    item.time,
    endTime ? `fin ${endTime}` : '',
    isChained ? "enchaîné avec l'activité précédente" : '',
    decale ? `possible, ${decale.label} se décale` : (unavailable ? `indisponible : ${meta}` : meta),
  ].filter(Boolean).join(', ');
  return { time: item.time, endTime, tag, tagTone, meta, label };
}

// LES HEURES QU UNE PARTIE DE LASER EMPORTE AVEC ELLE.
//
// Un groupe trop nombreux pour l arene joue en plusieurs passages : 49 joueurs
// dans une arene de 30 postes, c est 25 puis 24. Le moteur place ces passages
// l un apres l autre sur la grille des departs (:00/:30) : une partie lancee a
// 10:00 occupe AUSSI 10:30. Le client, lui, ne voyait rien : il choisissait
// 10:00 puis 10:30 comme deux parties, et son second passage tombait sur sa
// propre partie suivante (mesure du 2026-09-18 sur le tunnel reel).
//
// Rend une Map heure -> { rang, total, depuis, fin } :
//   rang   : le numero du passage qui occupe cette heure (2 pour le second) ;
//   total  : en combien de passages le groupe joue ;
//   depuis : l heure retenue qui emporte celle-ci ;
//   fin    : la fin du dernier passage de cette partie.
//
// Rien n est calcule ici : `getLaserCandidateWindows` est la fonction que le
// moteur et le serveur utilisent deja, avec la capacite REELLE de l arene du
// centre affiche. On ne garde que la partie 1 (`countIndex`), parce qu on
// demande les vagues d UNE partie, pas la suite des parties achetees.
function heuresEmporteesParLeLaser(heuresRetenues, pax) {
  const emportees = new Map();
  if (typeof getBalancedLaserWaveSizes !== 'function' || typeof getLaserCandidateWindows !== 'function') return emportees;
  // Un groupe qui tient en une fois n emporte rien : pas de pointille, pas de
  // phrase, rien ne change pour la grande majorite des reservations.
  if (getBalancedLaserWaveSizes(pax).length <= 1) return emportees;
  (Array.isArray(heuresRetenues) ? heuresRetenues : []).filter(Boolean).forEach((heure) => {
    const passages = getLaserCandidateWindows(heure, 0.5, pax).filter((f) => Number(f.countIndex || 1) === 1);
    if (passages.length <= 1) return;
    const fin = numToTime(passages[passages.length - 1].end);
    passages.forEach((passage, index) => {
      // Le premier passage EST l heure cliquee : elle n est pas emportee.
      if (index === 0) return;
      const quand = numToTime(passage.start);
      if (!emportees.has(quand)) emportees.set(quand, { rang: index + 1, total: passages.length, depuis: heure, fin });
    });
  });
  return emportees;
}

// LES HEURES QU UN SECOND SERVICE DE BOWLING EMPORTE.
//
// Meme idee que pour le laser, autre ressource. Un groupe trop grand pour les
// pistes joue en plusieurs fois : une heure retenue a 10:00 pour une heure de
// jeu fait jouer le second groupe de 11:00 a 12:00. Les pastilles de cette
// tranche-la sont deja prises, par le client lui-meme.
//
// LES PASTILLES DU PREMIER SERVICE NE SONT PAS MARQUEES : 10:30 est occupee,
// mais par le groupe qui joue, pas par « l autre groupe ». Leur refus d origine
// dit deja la verite.
function heuresEmporteesParLeBowling(heuresRetenues, pax, dureeMinutes) {
  const emportees = new Map();
  if (typeof splitGroupIntoBowlingServices !== 'function') return emportees;
  const services = splitGroupIntoBowlingServices(pax);
  if (services.length <= 1) return emportees;
  const duree = Math.max(1, Math.round(Number(dureeMinutes) || 60));
  const PAS = 30;
  (Array.isArray(heuresRetenues) ? heuresRetenues : []).filter(Boolean).forEach((heure) => {
    const debut = Math.round(timeToNum(heure) * 60);
    const fin = debut + duree * services.length;
    for (let rang = 1; rang < services.length; rang += 1) {
      const debutService = debut + duree * rang;
      for (let minute = debutService; minute < debutService + duree; minute += PAS) {
        const quand = numToTime(minute / 60);
        if (!emportees.has(quand)) {
          emportees.set(quand, { rang: rang + 1, total: services.length, depuis: heure, fin: numToTime(fin / 60), lieu: 'les pistes' });
        }
      }
    }
  });
  return emportees;
}

// POURQUOI CETTE HEURE COINCE, en une phrase que le client peut agir.
// Ecrite UNE fois : le rendu initial et la mise a jour en place s en servent
// tous les deux, et le gate la lit au meme endroit.
// Une chaine vide = l heure est prenable.
function raisonHeureCoincee({ rangeeVerrouillee, listePleine, parties, indisponible, raisonCourte, vague = null, retenue = false }) {
  // UNE HEURE DEJA PRISE NE COINCE JAMAIS. Le verdict du moteur porte sur une
  // heure A PRENDRE ; celle-ci, le client l a prise, et le seul geste qui lui
  // reste dessus est de la retirer. La faire coincer lui volait ce geste : le
  // clic ouvrait une bulle au lieu de liberer l heure, pendant que le compteur
  // juste au-dessus disait « cliquez l une d elles pour la retirer »
  // (mesure du 2026-09-18 : 11:00 retenue ET « pas prenable »). Ce que le
  // moteur refuse alors, c est la COMBINAISON, et cela se dit dans le plan,
  // pas sur le bouton qui sert a en sortir.
  if (retenue) return { motif: '', texte: '' };
  // LE MOTIF, A COTE DE LA RAISON. Le rouge doit dire « il y a un obstacle »,
  // pas « vous avez choisi ca » : quand le client coche « l equipe place mes
  // parties », TOUTE la grille coince, et la peindre en rouge pointille ferait
  // une alarme pour un etat parfaitement normal.
  if (rangeeVerrouillee) {
    return { motif: 'choix', texte: 'Vous avez choisi de laisser l’équipe placer vos parties. Décochez la case juste au-dessus pour choisir une heure vous-même.' };
  }
  // CETTE HEURE EST DEJA A LUI : c est son propre second passage. Ce n est ni
  // une panne ni un refus du centre, donc ni rouge ni « indisponible ». Elle
  // passe AVANT le compteur plein : « vos 3 heures sont choisies » serait vrai
  // mais a cote de la question, le client veut savoir pourquoi CETTE heure-la.
  if (vague) {
    const rang = Math.max(2, Number(vague.rang) || 2);
    const total = Math.max(2, Number(vague.total) || 2);
    return {
      motif: 'vague',
      texte: `C’est le passage de votre ${rang}e groupe. Trop nombreux pour ${vague.lieu || 'l’arène'}, vous jouez en ${total} fois : le jeu lancé à ${vague.depuis} occupe ${vague.lieu || 'l’arène'} jusqu’à ${vague.fin}.`,
    };
  }
  if (listePleine) {
    const total = Math.max(1, Number(parties) || 1);
    return { motif: 'obstacle', texte: `Vos ${total} heures sont déjà choisies. Cliquez l’une d’elles pour la libérer, puis reprenez celle-ci.` };
  }
  if (indisponible) {
    const courte = String(raisonCourte || '').trim();
    // La raison du moteur quand il en donne une (« Complet », « Fermé »), et
    // jamais une raison inventee quand il n en donne pas.
    return {
      motif: 'obstacle',
      texte: courte
        ? `${courte}. Cette heure n’est pas prenable pour votre groupe ce jour-là.`
        : 'Cette heure n’est pas prenable pour votre groupe ce jour-là.',
    };
  }
  return { motif: '', texte: '' };
}

// Le clic d une heure qui coince : il OUVRE l explication, il ne fait pas rien.
// Une seule bulle ouverte a la fois, et un second clic la referme.
function expliquerHeureCoincee(bouton) {
  if (!bouton) return;
  const ouvert = bouton.hasAttribute('data-coince-ouvert');
  document.querySelectorAll('[data-coince-ouvert]').forEach((el) => {
    el.removeAttribute('data-coince-ouvert');
    const b = el.querySelector('.slot-card-why');
    if (b) b.style.removeProperty('--bulle-decalage');
  });
  if (ouvert) return;
  bouton.setAttribute('data-coince-ouvert', '1');
  // LA BULLE RESTE DANS L ECRAN. Centree sur sa pastille, elle debordait sur la
  // colonne voisine des que la pastille etait au bord de la grille. On la
  // recale APRES l ouverture, quand sa largeur reelle est connue : une largeur
  // devinee au rendu aurait ete fausse des que le texte change.
  const bulle = bouton.querySelector('.slot-card-why');
  if (!bulle) return;
  const marge = 8;
  const boite = bulle.getBoundingClientRect();
  // ON RECADRE SUR LA GRILLE D HEURES, PAS SUR LA FENETRE. En trois colonnes,
  // une bulle qui tient dans l ecran depassait quand meme de SA colonne et se
  // posait sur le panneau voisin. La grille est la bonne limite ; l ecran reste
  // une seconde borne, pour le telephone ou la grille prend toute la largeur.
  const grille = bouton.closest('.anchor-chip-grid') || bouton.closest('.anchor-row');
  const cadre = grille ? grille.getBoundingClientRect() : null;
  const gauche = Math.max(marge, cadre ? cadre.left : marge);
  const droite = Math.min(document.documentElement.clientWidth - marge, cadre ? cadre.right : Infinity);
  let decalage = 0;
  if (boite.right > droite) decalage = droite - boite.right;
  if (boite.left + decalage < gauche) decalage = gauche - boite.left;
  if (decalage) bulle.style.setProperty('--bulle-decalage', `${Math.round(decalage)}px`);
}

// Un clic ailleurs referme la bulle : sinon elle reste posee sur la grille
// pendant que le client continue a choisir.
document.addEventListener('click', (event) => {
  if (event.target && event.target.closest && event.target.closest('[data-coince]')) return;
  document.querySelectorAll('[data-coince-ouvert]').forEach((el) => el.removeAttribute('data-coince-ouvert'));
}, true);

function renderAnchorChipGroups(activity, { selected, disabled, chained, chosen = null, full = false }) {
  const groups = groupAnchorTimes(activity.times);
  if (!groups.length) return '';
  // Choix MULTIPLE des que la reservation porte plusieurs parties : ce sont les
  // heures retenues qui decident de l'etat des pastilles ET des onglets de
  // moment, declare ici parce que les deux s'en servent.
  const multi = Array.isArray(chosen);
  // LES HEURES QUE SES PROPRES PASSAGES EMPORTENT. Calculees UNE fois pour
  // toute la grille : une heure retenue occupe la sienne et celles de ses
  // passages suivants.
  const heuresRetenues = multi ? chosen : (selected ? [selected] : []);
  const emportees = disabled
    ? new Map()
    : activity.activityId === 'laser_game'
      ? heuresEmporteesParLeLaser(heuresRetenues, state.booking.pax)
      : activity.activityId === 'bowling'
        ? heuresEmporteesParLeBowling(heuresRetenues, state.booking.pax, Number(activity.durationMinutes) || 60)
        : new Map();
  // HORIZONTAL : une seule piste par activité qui porte TOUTE la journée. Les
  // onglets de moment cessent d'être un filtre (26 heures sur 27 masquées) et
  // deviennent des points de saut dans la piste : rien n'est plus caché.
  // PLUS D ONGLETS DE MOMENT (2026-08-24, Movsar : « ca s affiche par
  // moment mais ca sert a rien »). Ils etaient des points de saut dans une
  // piste qui defilait ; la grille montre desormais TOUTE la journee d un
  // coup, il n y a plus rien ou sauter. groupAnchorTimes reste : il ordonne
  // les heures, et data-period-start sert toujours d ancre interne.
  const tabs = '';
  // Le SECONDAIRE identique sur toutes les cartes (« 2 pistes », « 23
  // places ») est du bruit multiplie par 27 : il se dit UNE fois au-dessus
  // de la grille, et chaque carte redevient une heure qui tient sur une
  // ligne (Movsar 2026-08-24 : « trop long, on doit descendre »). Une carte
  // ne garde son secondaire que s'il DIFFERE (places reduites, partagee).
  const allAnchorItems = groups.reduce((list, group) => list.concat(group.items), []);
  // Le secondaire DOMINANT, pas seulement l'unanime (2026-08-24, Movsar,
  // capture : « 23 places » repete sur 15 cartes parce que DEUX heures de
  // fin de journee disaient « 6 places · session partagee »). La valeur
  // majoritaire se dit UNE fois au-dessus ; une carte ne parle que si elle
  // s'en ecarte. Sous la moitie des heures, pas de dominante : chacune garde
  // la sienne.
  // Les heures impossibles ne comptent pas : leur ligne porte la raison, pas
  // un secondaire.
  const okAnchorItems = allAnchorItems.filter((item) => item.ok !== false);
  const anchorMetaCounts = new Map();
  okAnchorItems.forEach((item) => {
    const meta = anchorSlotCardModel(activity, item, {}).meta;
    if (meta) anchorMetaCounts.set(meta, (anchorMetaCounts.get(meta) || 0) + 1);
  });
  let sharedAnchorMeta = '';
  let sharedAnchorCount = 0;
  anchorMetaCounts.forEach((count, meta) => {
    if (count > sharedAnchorCount) { sharedAnchorMeta = meta; sharedAnchorCount = count; }
  });
  if (sharedAnchorCount * 2 < okAnchorItems.length) sharedAnchorMeta = '';
  const sharedAnchorUniform = sharedAnchorCount === okAnchorItems.length;
  // LES HEURES SE RANGENT PAR MOMENT (2026-08-31), exactement comme la liste
  // simple de l ecran des heures. Ce ne sont PAS les anciens onglets que
  // Movsar avait fait retirer ("ca s affiche par moment mais ca sert a rien")
  // : ceux-la FILTRAIENT et cachaient 26 heures sur 27. Ici rien n est
  // masque et aucun bouton n est ajoute - juste trois intertitres dans la
  // meme liste, pour qu une colonne de 27 pastilles se balaye.
  // LE MOMENT OUVERT PAR DEFAUT : celui qui porte l heure retenue, sinon
  // celui de la proposition enchainee, sinon le premier qui a des heures
  // libres. Les autres se plient : 28 pastilles d un coup faisaient un mur
  // (Movsar : « ca fait moins de trop »). Rien n est cache : chaque moment
  // annonce combien d heures il porte, et un clic le deplie.
  const aLHeureRetenue = (group) => group.items.some((item) => (multi ? chosen.includes(item.time) : item.time === selected));
  const momentRetenu = groups.find(aLHeureRetenue) || null;
  const momentPropose = chained ? (groups.find((group) => group.items.some((item) => item.time === chained)) || null) : null;
  const momentLibre = groups.find((group) => group.items.some((item) => item.ok !== false)) || null;
  const momentParDefaut = momentRetenu || momentPropose || momentLibre;
  const chips = groups.map(group => {
    const clePeriode = `${activity.activityId}:${group.key}`;
    const libres = group.items.filter((item) => item.ok !== false).length;
    const ouvert = Object.prototype.hasOwnProperty.call(anchorPeriodsOpen, clePeriode)
      ? Boolean(anchorPeriodsOpen[clePeriode])
      : group === momentParDefaut;
    const idGrille = `heures-${activity.activityId}-${group.key}`;
    return `
    <section class="slot-period${ouvert ? ' is-open' : ''}" data-period="${escapeHtml(group.key)}" data-period-key="${escapeHtml(clePeriode)}">
      <button type="button" class="slot-period-head" aria-expanded="${ouvert ? 'true' : 'false'}" aria-controls="${escapeHtml(idGrille)}" onclick="basculerPeriodeHeures(this)">
        <span class="slot-period-icon" aria-hidden="true">${ANCHOR_PERIOD_ICONS[group.key] || ''}</span>
        <span class="slot-period-title">${escapeHtml(group.label)}</span>
        <span class="slot-period-count">${libres > 0 ? `${libres} créneau${libres > 1 ? 'x' : ''}` : 'aucun créneau libre'}</span>
        <svg class="slot-period-chevron" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="6 9 12 15 18 9"/></svg>
      </button>
      <div class="anchor-chip-grid" id="${escapeHtml(idGrille)}">${group.items.map((item, index) => {
    // Multi-choix : une heure retenue est active, et quand le compte est
    // atteint les autres cessent d'etre cliquables (le compteur dit pourquoi).
    const isActive = multi ? chosen.includes(item.time) : item.time === selected;
    // Une heure RETENUE n est jamais « emportee » : le client l a prise, c est
    // elle qui emporte les autres.
    const emportee = isActive ? null : (emportees.get(item.time) || null);
    // Une heure que le moteur juge impossible pour la visite ENTIERE reste
    // visible, grisee, avec sa raison courte : le client sait pourquoi au
    // moment de choisir, pas a la derniere etape (brief 2026-09-02).
    const unavailable = item.ok === false;
    // UNE HEURE QUI CHEVAUCHE L AUTRE ACTIVITE N EST PAS UN MUR (entretien Seb,
    // 2026-09-17 : « si qlq veut 18H30 laser game il comprend pas pq il peut
    // pas [...] fait un truc plus logique [...] mais pas empecher comme ca »).
    // Le seul obstacle est une heure retenue pour l AUTRE activite : le client
    // la prend, et l autre activite se replace autour (le moteur sait le faire,
    // c est ce qu il fait quand aucune heure n est retenue). Une capacite
    // pleine, une fermeture ou un blocage restent des refus : rien ne les
    // deplace.
    const conflit = item.conflict && item.conflict.activityId && item.conflict.activityId !== activity.activityId
      ? item.conflict
      : null;
    const decalable = unavailable && item.code === 'anchor_overlap' && Boolean(conflit);
    const isChained = !isActive && !unavailable && item.time === chained;
    const marker = index === 0 ? ` data-period-start="${escapeHtml(group.key)}"` : '';
    const justPicked = !formulaAnchorBusy && isActive && formulaJustPicked
      && formulaJustPicked.activityId === activity.activityId && formulaJustPicked.time === item.time;
    if (justPicked) formulaJustPicked = null;
    const model = anchorSlotCardModel(activity, item, { isChained, unavailable, decale: conflit && decalable ? conflit : null });
    if (!unavailable && sharedAnchorMeta && model.meta === sharedAnchorMeta) model.meta = '';
    // Le secondaire de la carte dit A QUI est cette heure, pas la mecanique du
    // moteur (« Chevauche Laser Game (partie 1) 10:00 ») : la phrase complete
    // vit dans la bulle, sous le ⓘ.
    if (emportee) model.meta = `Votre ${Math.max(2, Number(emportee.rang) || 2)}e groupe`;
    const reasonAttrs = unavailable ? ` data-reason="${escapeHtml(model.meta)}" title="${escapeHtml(model.meta)}"` : '';
    // UNE HEURE QUI COINCE RESTE CLIQUABLE, ET ELLE DIT POURQUOI (Movsar,
    // 2026-09-18 : « ya toujours des fois ou des boutons sont impossible a
    // cliquer. Non, meme si ca coince faut que ce soit cliquable, mais
    // explique alors, sous un ptit design pointille [...] avec un i en rond »).
    // Un bouton mort ne se distingue pas d un bouton casse : le client reclique,
    // croit que la page ne repond plus, et part. Il garde donc son clic, qui
    // OUVRE la raison au lieu de ne rien faire, et il reste `aria-disabled`
    // pour qu un lecteur d ecran sache que l heure n est pas prenable.
    const blocage = raisonHeureCoincee({
      rangeeVerrouillee: disabled,
      listePleine: Boolean(multi && full && !isActive),
      parties: Number(activity.count || 1),
      indisponible: Boolean(unavailable && !decalable),
      raisonCourte: model.meta,
      vague: emportee,
      retenue: isActive,
    });
    const raisonCoince = blocage.texte;
    const coince = Boolean(raisonCoince);
    const action = coince
      ? `expliquerHeureCoincee(this)`
      : `setFormulaAnchorTime('${escapeHtml(activity.activityId)}','${escapeHtml(item.time)}'${decalable ? ', true' : ''})`;
    return `<button type="button" class="anchor-chip slot-card ${isActive ? 'active' : ''} ${isChained ? 'is-chained' : ''} ${unavailable && !decalable ? 'is-unavailable' : ''} ${decalable ? 'is-shiftable' : ''} ${justPicked ? 'is-just-picked' : ''}"${marker} data-time="${escapeHtml(item.time)}"${reasonAttrs}${coince ? ` data-coince="${escapeHtml(raisonCoince)}" data-coince-motif="${escapeHtml(blocage.motif)}" aria-disabled="true"` : ''} aria-pressed="${isActive ? 'true' : 'false'}" aria-label="${escapeHtml(coince ? `${model.label}. ${raisonCoince}` : model.label)}" onclick="${action}">${slotCardMarkup(model)}${coince ? '<span class="slot-card-info" aria-hidden="true">i</span><span class="slot-card-why" role="note">' + escapeHtml(raisonCoince) + '</span>' : ''}</button>`;
      }).join('')}</div>
    </section>`;
  }).join('');
  const nudge = (direction, glyph, text) => `<button type="button" class="anchor-track-nudge" data-direction="${direction}" aria-label="${escapeHtml(text)}" onclick="nudgeAnchorTrack('${escapeHtml(activity.activityId)}',${direction})">${glyph}</button>`;
  return `
    <div class="anchor-periods">
      ${tabs}
      ${sharedAnchorMeta ? `<p class="anchor-shared-meta">${escapeHtml(sharedAnchorMeta)}${sharedAnchorUniform ? ' à chaque heure' : ', sauf mention sur l’heure'}</p>` : ''}
      <div class="anchor-track-shell">
        ${nudge(-1, '&lsaquo;', `Heures précédentes pour ${activity.label}`)}
        <div class="anchor-track" data-anchor="${escapeHtml(activity.activityId)}" data-overflow="none">
          ${chips}
        </div>
        ${nudge(1, '&rsaquo;', `Heures suivantes pour ${activity.label}`)}
      </div>
    </div>`;
}

// Un ÉTAPE de la visite : son rang, son heure retenue, et ses heures possibles.
// OU EN EST LE CLIENT DANS SES PARTIES DE LASER, ecrit UNE fois.
//
// Ce texte vivait en DEUX exemplaires, avec DEUX formulations differentes pour
// le meme etat : le rendu initial ecrivait « 1 heure choisie sur 3 · 2 placees
// par l equipe », et la mise a jour en place, quelques lignes plus bas,
// « 1 heure sur 3 · 2 parties avec l equipe ». Le client lisait donc une phrase
// au premier affichage et une autre des qu il cliquait une heure, sans que rien
// n ait change. Trouve le 2026-09-18 en relevant l ecran ligne par ligne.
//
// `poses` = heures deja retenues, `total` = parties achetees.
function etatDesPartiesLaser(poses, total) {
  const choisies = Math.max(0, Number(poses) || 0);
  const parties = Math.max(1, Number(total) || 1);
  // LE NOMBRE DE PARTIES ACHETEES OUVRE LA PHRASE, parce que c est le fait que
  // le client a decide et qu il doit retrouver. La ligne de detail qui le
  // portait a disparu : si cette phrase ne le disait pas, il disparaitrait de
  // l ecran.
  const tete = `${parties} partie${parties > 1 ? 's' : ''}`;
  if (!choisies) return `${tete} · l’équipe place vos heures, ou choisissez-les`;
  const reste = Math.max(0, parties - choisies);
  if (!reste) return `${tete} · vos ${parties} heures sont choisies, cliquez-en une pour la retirer`;
  return `${tete} · ${choisies} heure${choisies > 1 ? 's' : ''} choisie${choisies > 1 ? 's' : ''}, ${reste} placée${reste > 1 ? 's' : ''} par l’équipe`;
}

function renderVisitRailStep(step, position) {
  const activity = step.activity;
  const { preference, times } = getCurrentFormulaAnchorSelection();
  const isLaser = activity.activityId === 'laser_game';
  const laserOnSite = preference.laserPlacement === 'onsite';
  // On ne verrouille QUE si le client peut deverrouiller. Sans la case
  // « sur place » a l'ecran (visite a une seule ancre), griser la liste
  // enferme le client au lieu de l'informer.
  const disabled = isLaser && laserOnSite && Boolean(formulaAnchorData.laserOnSiteAvailable);
  // PLUSIEURS PARTIES = PLUSIEURS HEURES DANS LA MEME LISTE (2026-08-20).
  // Movsar : « fais juste le choix sur une liste ou ils peuvent choisir jusqu'a
  // 3 horaires ». Une etape par partie donnait trois pistes d'heures identiques
  // l'une sous l'autre : meme information, trois fois. Une seule liste, ou
  // chaque heure retenue se clique et se declique.
  const partCount = isLaser ? Math.max(1, Number(activity.count || 1)) : 1;
  // `chosen` VAUT NULL hors multi-choix, jamais un tableau vide : c'est lui qui
  // dit « cette liste est multiple ». Un tableau vide pour le bowling faisait
  // lire son heure retenue dans une liste toujours vide, donc plus aucune
  // pastille marquee (attrape par le gate visuel, pas par moi).
  const chosen = isLaser && partCount > 1 && !disabled ? getChosenLaserTimes(preference) : null;
  const full = Boolean(chosen && chosen.length >= partCount);
  const restantes = chosen ? Math.max(0, partCount - chosen.length) : 0;
  const selected = disabled ? '' : (chosen ? (chosen[0] || '') : (times[activity.activityId] || ''));
  const chained = disabled || (chosen && chosen.length) ? '' : getChainedAnchorTime(activity.activityId);
  // UNE SEULE LIGNE D ETAT POUR LE LASER (Movsar, 2026-09-18 : « pour laser
  // game ya 3phrases c trop et souvent ca dit la meme chose »). La ligne
  // « 3 parties · choisissez vos heures, l equipe place les autres » et le
  // compteur « 1 heure choisie sur 3 · 2 placees par l equipe » disaient la
  // MEME chose, l une sous l autre. Le compteur suffit : il porte deja le
  // nombre de parties (« sur 3 »), ou on en est, et ce que l equipe fait du
  // reste. La ligne de detail disparait donc quand il y a un compteur.
  const detail = isLaser
    ? (partCount > 1
      ? ''
      : `Session de ${activity.durationMinutes} min`)
    : `${formatDurationLabel(Number(activity.durationMinutes || 60) / 60)} de piste réservée`;
  // Le choix « sur place » est une DÉCISION sur cette activité : il vit en tête
  // de son étape, pas perdu sous 27 pastilles (plainte du 2026-08-15).
  const onSiteToggle = isLaser && formulaAnchorData.laserOnSiteAvailable ? `
      <label class="anchor-onsite ${laserOnSite ? 'active' : ''}">
        <input type="checkbox" ${laserOnSite ? 'checked' : ''} onchange="setFormulaLaserPlacement(this.checked ? 'onsite' : 'scheduled')">
        <span>${partCount > 1 ? 'Je place mes parties laser sur place, selon l’affluence' : 'Je place ma partie laser sur place, selon l’affluence'}</span>
      </label>` : '';
  const compteur = chosen ? `<p class="anchor-part-count">${escapeHtml(etatDesPartiesLaser(chosen.length, partCount))}</p>` : '';
  const picked = disabled || (chosen && !chosen.length)
    ? '<span class="anchor-row-pick anchor-row-pick-free">avec l’équipe</span>'
    : (chosen
      ? `<span class="anchor-row-pick">${escapeHtml(chosen.join(' · '))}</span>`
      : (selected ? `<span class="anchor-row-pick">${escapeHtml(selected)}</span>` : ''));
  return `
    <li class="visit-rail-step" data-mobile-index="${Number.isInteger(step.index) ? step.index : position - 1}">
      <span class="visit-rail-mark" aria-hidden="true">${position}</span>
      <div class="anchor-row ${disabled ? 'anchor-row-onsite' : ''}" data-anchor="${escapeHtml(activity.activityId)}"${chosen ? ` data-multi="${partCount}"` : ''}>
        <div class="anchor-row-head">
          <span class="anchor-row-icon" aria-hidden="true">${activityIconMarkup(activity.activityId)}</span>
          <strong>${escapeHtml(activity.label)}</strong>
          ${picked}
          <small>${escapeHtml(detail)}</small>
        </div>
        ${onSiteToggle}
        ${compteur}
        ${renderAnchorChipGroups(activity, { selected, disabled, chained, chosen, full })}
      </div>
    </li>`;
}

// LE LIEN entre deux étapes : c'est tout le sujet de l'écran (une VISITE, pas
// deux réservations). Il porte toujours l'écart réel. Quand cet écart dépasse
// ce que la visite absorbe, le serveur envoie un avis : le lien passe en état
// « avis » et propose d'enchaîner. Il n'interdit jamais rien.
function renderVisitRailLink(previousStep, nextStep, notices) {
  const { times } = getCurrentFormulaAnchorSelection();
  const previousStart = times[previousStep.activity.activityId];
  const nextStart = times[nextStep.activity.activityId];
  if (!previousStart || !nextStart) return '';
  const gap = Math.round(timeToNum(nextStart) * 60
    - (timeToNum(previousStart) * 60 + Number(previousStep.activity.durationMinutes || 60)));
  if (gap < 0) return '';
  const notice = notices.find(item => item.toActivityId === nextStep.activity.activityId
    && item.fromActivityId === previousStep.activity.activityId);
  if (!notice) {
    if (!formulaAnchorBusy) formulaAdviceSignature = '';
    // Ecart NUL : rien a dire. La pastille « Enchaine » et les heures collees
    // le montrent deja ; un mot « enchaine » orphelin sous les colonnes etait
    // du bruit (capture Movsar, 2026-08-24).
    if (gap === 0) return '';
    return `
      <li class="visit-rail-link">
        <span class="visit-rail-line" aria-hidden="true"></span>
        <span class="visit-rail-gap">${escapeHtml(formatGapText(gap))} entre les deux</span>
      </li>`;
  }
  const passLabels = (formulaAnchorData?.freePass || []).map(item => item.label);
  const note = passLabels.length
    ? `Ce temps se passe sur place : ${passLabels.join(', ')} restent accessibles.`
    : 'Ce temps se passe sur place, entre les deux activités.';
  const canTighten = Boolean(notice.tightenTime)
    && anchorOkTimes(nextStep.activity).some(item => item.time === notice.tightenTime);
  // L'avis n'entre QU'UNE FOIS, et seulement quand il est neuf : le picker se
  // re-rend à chaque choix, rejouer l'animation à chaque rendu ferait clignoter
  // l'écran (même règle que le motion d'exploitation de la console).
  const signature = `${notice.fromActivityId}>${notice.toActivityId}:${notice.gapMinutes}`;
  // « Garder cet horaire » est une DECISION : l'avis écarté ne revient pas
  // tant que l'attente n'a pas changé ; le maillon continue de dire l'écart
  // réel (l'information ne disparaît jamais, seul le conseil se tait).
  if (signature === formulaAdviceDismissed) {
    if (!formulaAnchorBusy) formulaAdviceSignature = '';
    return `
      <li class="visit-rail-link">
        <span class="visit-rail-line" aria-hidden="true"></span>
        <span class="visit-rail-gap">${escapeHtml(formatGapText(gap))} entre les deux</span>
      </li>`;
  }
  const isNew = !formulaAnchorBusy && signature !== formulaAdviceSignature;
  if (!formulaAnchorBusy) formulaAdviceSignature = signature;
  return `
    <li class="visit-rail-link is-advice">
      <span class="visit-rail-line" aria-hidden="true"></span>
      <div class="visit-rail-advice ${isNew ? 'is-appearing' : ''}" role="status">
        <strong>${escapeHtml(notice.gapLabel || formatGapText(gap))} d’attente entre ${escapeHtml(notice.fromLabel || previousStep.activity.label)} et ${escapeHtml(notice.toLabel || nextStep.activity.label)}</strong>
        <span>${escapeHtml(note)}</span>
        <div class="visit-rail-advice-actions">
          ${canTighten ? `<button type="button" class="visit-rail-advice-action" onclick="tightenFormulaAnchorGap('${escapeHtml(nextStep.activity.activityId)}','${escapeHtml(notice.tightenTime)}')">Enchaîner à ${escapeHtml(notice.tightenTime)}</button>` : ''}
          <button type="button" class="visit-rail-advice-ghost" onclick="dismissFormulaAdvice('${escapeHtml(signature)}')">Garder cet horaire</button>
        </div>
      </div>
    </li>`;
}

// Écarter l'avis de confort : le client a vu, il assume son horaire. La carte
// sort par le geste de sortie de la grammaire, puis les maillons se réécrivent
// en place (aucune reconstruction du fil).
async function dismissFormulaAdvice(signature) {
  formulaAdviceDismissed = signature;
  const advice = document.querySelector('.visit-rail-advice');
  if (advice && !prefersReducedMotion()) {
    advice.classList.add('is-leaving');
    await new Promise((resolve) => setTimeout(resolve, 150)); // = --dur-exit
  }
  const formule = state.booking.type === 'formule' ? resolveDisplayFormule(state.booking.formuleId) : null;
  if (!syncFormulaAnchorUi(formule, { busy: false })) renderSlots(formule);
}

// « 2 h 30 », « 45 min » : même lecture que côté moteur (lib/ops-engine.js).
function formatGapText(minutes) {
  const total = Math.max(0, Math.round(Number(minutes) || 0));
  const hours = Math.floor(total / 60);
  const rest = total % 60;
  if (!hours) return `${rest} min`;
  return rest ? `${hours} h ${String(rest).padStart(2, '0')}` : `${hours} h`;
}

// Formules AVEC ancres : la visite se lit comme un fil, dans l'ordre réel.
function renderFormulaAnchorRows(formule) {
  const steps = getVisitRailSteps();
  const notices = getSlotComfortNotices();
  const parts = [];
  steps.forEach((step, index) => {
    if (index > 0) parts.push(renderVisitRailLink(steps[index - 1], step, notices));
    parts.push(renderVisitRailStep(step, index + 1));
  });
  // PLUS DE BLOC SEPARE POUR LES ACTIVITES SANS HORAIRE (Movsar, 2026-09-18 :
  // « en bas ya aussi 2bloc alors que on peut en faire un bloc bcp plus beau
  // [...] genre le "sans horaire" pq a part ? »). Ce qui se vit sans horaire
  // fait partie de LA visite : c est une ligne du recapitulatif, au meme titre
  // que l arrivee et les rendez-vous, et non un second panneau qui coupe
  // l ecran en deux. Voir ligneSansHoraire().
  // Le nombre de rendez-vous à placer décide si les repères numérotés servent
  // à quelque chose : à une seule activité, « 1 » ne numérote rien.
  return `<ol class="visit-rail" data-anchors="${steps.length}">${parts.join('')}</ol>`;
}

// Le dernier maillon du fil : tout ce que le client a réservé SANS horaire.
// Pour une formule ce sont les avantages inclus ; pour une visite composée à la
// carte ce sont ses propres activités (minigolf, arcades, billards...), qui
// n'apparaissaient nulle part et donnaient un écran qui amputait sa visite.
// UNE LIGNE DU RECAPITULATIF, plus un bloc a part. Elle garde la classe
// `anchor-free-pass` : c est elle que lisent les gates, et c est bien elle qui
// porte le sujet. Elle ne contient AUCUNE heure, par construction comme avant.
function ligneSansHoraire(formule) {
  const entries = (formulaAnchorData?.freePass || []).map(item => ({
    label: item.label,
    detail: item.detail || '',
    onSitePayment: item.onSitePayment === true,
  }));
  if (!entries.length && formule) {
    entries.push(...getFormulaFreePassIds(formule).map(id => ({ label: ACTIVITY_LABELS[id] || id, detail: '', onSitePayment: false })));
  }
  const drinks = formulaAnchorData?.drinks || [];
  if (!entries.length && !drinks.length) return '';
  const included = Boolean(formule);
  // « Pass liberté » quand c est un avantage INCLUS dans une formule,
  // « Sans horaire » quand le client a mis ces activites dans son panier :
  // ce n est pas le meme fait, et le libelle ne doit pas le gommer.
  const badge = included ? 'Pass liberté' : 'Sans horaire';
  const items = entries.map(entry => `<span class="anchor-free-item">${escapeHtml(entry.label)}${entry.detail ? `<small>${escapeHtml(entry.detail)}</small>` : ''}${entry.onSitePayment ? '<em>réglé sur place</em>' : ''}</span>`)
    .concat(drinks.map(label => `<span class="anchor-free-item anchor-free-drink">${escapeHtml(label)}</span>`))
    .join('');
  return `
    <div class="visit-line anchor-free-pass">
      <span class="visit-tag free">${escapeHtml(badge)}</span>
      <span class="anchor-free-items">${items}<em class="anchor-free-note">à votre rythme</em></span>
    </div>`;
}

// La zone de statut du picker : panneau de validation quand la combinaison
// tient, refus expliqué avec les combinaisons voisines sinon. UN SEUL endroit
// écrit ce HTML : le rendu complet et la mise à jour en place s'en servent.
function renderFormulaAnchorStatus(formule) {
  const slotIndex = getCurrentFormulaAnchorSlotIndex();
  const slot = slotIndex >= 0 ? state.availableSlots[slotIndex] : null;
  if (slot) {
    return `
      <div class="formula-program-panel">
        ${renderFormulaVisitSummary(slot, formule)}
        <button type="button" class="btn-primary formula-plan-confirm" onclick="selectSlot(${slotIndex})">Valider ces horaires</button>
      </div>`;
  }
  // UN REFUS EXPLIQUE, PAS UN MUR. L'encadré disait « Cette combinaison n'est
  // pas possible » sans dire POURQUOI ni QUOI FAIRE d'autre que tout annuler
  // (Movsar, 2026-08-15 : « le rouge comme ça, c'est pas fou »). Il nomme
  // maintenant la contrainte, propose les combinaisons voisines qui marchent,
  // et ne garde le retour à la proposition automatique qu'en dernier recours.
  const suggestions = (formulaAnchorSuggestions || []).map((suggestion, index) => `
      <button type="button" class="anchor-suggestion" onclick="applyFormulaAnchorSuggestion(${index})">${escapeHtml(suggestion.label || Object.values(suggestion.times || {}).join(' · '))}</button>`).join('');
  return `
      <div class="anchor-status anchor-status-error" role="alert">
        <div class="anchor-status-copy">
          <strong>${escapeHtml(formulaAnchorMessage || 'Ces deux heures ne peuvent pas aller ensemble.')}</strong>
          <span>Vos autres choix sont conservés : il suffit de déplacer une heure.</span>
        </div>
        ${suggestions ? `<div class="anchor-suggestions"><span>Ces horaires fonctionnent :</span>${suggestions}</div>` : ''}
        <button type="button" class="formula-order-fallback-btn" onclick="resetFormulaAnchorChoices()">Repartir de la proposition automatique</button>
        ${ligneSansHoraire(formule)}
      </div>`;
}

function renderFormulaAnchorPicker(formule) {
  if (!formulaHasAnchorUi()) return renderFormulaArrivalPicker(formule);
  let statusHtml = '';
  if (formulaAnchorBusy) {
    statusHtml = `
      <div class="anchor-status anchor-status-busy" role="status" aria-live="polite">
        <span class="slot-spinner" aria-hidden="true"></span>
        <span>Vérification de votre combinaison…</span>
      </div>`;
  } else {
    statusHtml = renderFormulaAnchorStatus(formule);
  }
  // Le pass liberté est le dernier maillon du fil (renderFormulaAnchorRows) :
  // il ne se rajoute plus après le panneau, sinon la visite se lit en deux
  // morceaux alors que c'est UNE visite.
  // Plus d'en-tête interne : le titre de la carte le porte déjà, et la consigne
  // que ce paragraphe donnait ("présentez-vous 10 min avant") est dite par le
  // résumé, à l'heure près.
  // La zone de statut est un conteneur STABLE : la revalidation d'un choix la
  // met à jour en place (syncFormulaAnchorUi), elle ne reconstruit pas le fil.
  const mobilePages = getMobileAnchorActivities();
  const mobileCount = mobilePages.length;
  if (formulaAnchorMobilePage > Math.max(0, mobileCount - 1)) formulaAnchorMobilePage = 0;
  const mobileAttrs = mobileCount > 1
    ? ` data-mobile-multi="1" data-mobile-page="${formulaAnchorMobilePage}"${formulaAnchorMobilePage >= mobileCount - 1 ? ' data-mobile-last="1"' : ''}`
    : '';
  const mobileNav = mobileCount > 1 ? `
      <div class="anchor-mobile-nav">
        <button type="button" class="anchor-mobile-back" aria-label="Créneau précédent" onclick="formulaAnchorMobileBack()">&lsaquo;</button>
        <span class="anchor-mobile-title" data-role="anchor-mobile-title"><strong data-role="anchor-mobile-activity">${escapeHtml(mobilePages[formulaAnchorMobilePage]?.label || '')}</strong><small data-role="anchor-mobile-count">Activité ${formulaAnchorMobilePage + 1} sur ${mobileCount}</small></span>
        ${mobileCount === 2 ? `<div class="anchor-mobile-alt"><button type="button" onclick="formulaAnchorStartWithNext()">${escapeHtml(mobilePages[1]?.label || '')} d’abord&nbsp;?</button></div>` : ''}
      </div>` : '';
  const mobileHeroUrl = mobileCount > 1 ? getTenantActivityImage(mobilePages[formulaAnchorMobilePage]?.activityId) : '';
  const mobileHero = mobileCount > 1 ? `
      <div class="anchor-mobile-hero" data-role="anchor-mobile-hero"${mobileHeroUrl ? ` style="background-image:url('${escapeHtml(mobileHeroUrl)}')"` : ' data-empty="1"'} aria-hidden="true"></div>` : '';
  const mobileNext = mobileCount > 1 ? `
      <div class="anchor-mobile-continue">
        <button type="button" class="anchor-mobile-next" onclick="formulaAnchorMobileNext()">Continuer · <span data-role="anchor-mobile-next-label">${escapeHtml(mobilePages[formulaAnchorMobilePage + 1]?.label || '')}</span></button>
      </div>` : '';
  return `
    <div class="formula-anchor-picker"${mobileAttrs}>
      ${mobileNav}
      ${renderFormulaAnchorRows(formule)}
      ${mobileNext}
      ${mobileHero}
      <div class="formula-anchor-status-zone" data-role="anchor-status-zone">${statusHtml}</div>
    </div>`;
}

// LA REVALIDATION NE RECONSTRUIT PLUS L'ECRAN. Un clic sur une heure changeait
// trois fois tout le DOM du fil (rendu « occupé », rendu post-réseau, rendu
// final) : chaque reconstruction rejouait les pistes, remettait leur défilement
// à zéro et faisait clignoter le panneau. C'est le « plusieurs
// rafraîchissements » que Movsar voyait. Ici, seuls les éléments dont l'état a
// réellement changé sont touchés : pastilles (classes), badge d'heure retenue,
// maillons d'attente, zone de statut. Le fil, les pistes et leur défilement ne
// bougent pas. Retourne false quand la structure a changé (ordre des activités,
// liste d'heures, état d'erreur) : l'appelant repasse alors par un rendu
// complet, qui est cette fois un VRAI changement d'écran.
function syncFormulaAnchorUi(formule, { busy }) {
  const list = document.getElementById('slotList');
  const picker = list ? list.querySelector('.formula-anchor-picker') : null;
  if (!picker || !formulaHasAnchorUi()) return false;
  if (!busy && slotLoadFailed) return false;
  const steps = getVisitRailSteps();
  const rows = [...picker.querySelectorAll('.anchor-row[data-anchor]')];
  if (rows.length !== steps.length) return false;
  // L'IDENTITE D'UNE ETAPE, C'EST SON ACTIVITE **ET** SA PARTIE. Avec trois
  // parties de laser, trois lignes portent le meme `data-anchor` : sans le
  // numero, la mise a jour en place ecrivait trois fois dans la premiere, et le
  // client voyait son clic sur la partie 2 ne rien faire. Un ordre qui change
  // (une partie qui prend ou perd son heure se deplace dans le fil) rend false :
  // le rendu complet reordonne, lui.
  if (steps.some((step, index) => rows[index].dataset.anchor !== step.activity.activityId)) return false;

  const { preference, times } = getCurrentFormulaAnchorSelection();
  for (const step of steps) {
    const activity = step.activity;
    const isLaser = activity.activityId === 'laser_game';
    const row = picker.querySelector(`.anchor-row[data-anchor="${activity.activityId}"]`);
    if (!row) return false;
    const laserOnSite = preference.laserPlacement === 'onsite';
    // On ne verrouille QUE si le client peut deverrouiller. Sans la case
    // « sur place » a l'ecran (visite a une seule ancre), griser la liste
    // enferme le client au lieu de l'informer.
    const disabled = isLaser && laserOnSite && Boolean(formulaAnchorData.laserOnSiteAvailable);
    const partCount = isLaser ? Math.max(1, Number(activity.count || 1)) : 1;
    // Liste MULTI-CHOIX quand la reservation porte plusieurs parties : ce sont
    // les heures retenues qui pilotent l'etat des pastilles, pas une seule.
    const chosen = isLaser && partCount > 1 && !disabled ? getChosenLaserTimes(preference) : null;
    const full = Boolean(chosen && chosen.length >= partCount);
    const selected = disabled
      ? ''
      : (chosen ? (chosen[0] || '') : (times[activity.activityId] || ''));
    const chained = disabled || (chosen && chosen.length) ? '' : getChainedAnchorTime(activity.activityId);
    // LA MEME REGLE QU AU RENDU INITIAL (voir heuresEmporteesParLeLaser) :
    // sans elle, ce chemin effacerait le pointille du second passage des que le
    // client reclique, parce qu il ne saurait pas d ou vient le `data-coince`.
    const retenuesIci = chosen || (selected ? [selected] : []);
    const emportees = disabled
      ? new Map()
      : isLaser
        ? heuresEmporteesParLeLaser(retenuesIci, state.booking.pax)
        : activity.activityId === 'bowling'
          ? heuresEmporteesParLeBowling(retenuesIci, state.booking.pax, Number(activity.durationMinutes) || 60)
          : new Map();
    const chips = [...row.querySelectorAll('.anchor-chip')];
    if (chips.length !== (activity.times || []).length) return false;
    // Une heure qui change de verdict (possible <-> impossible, ou de raison)
    // change de carte entiere : c est un vrai changement d ecran, le rendu
    // complet s en charge.
    if (chips.some((chip, index) => {
      const item = (activity.times || [])[index];
      const unavailable = Boolean(item && item.ok === false);
      if (chip.classList.contains('is-unavailable') !== unavailable) return true;
      // Une heure qui devient (ou cesse d etre) le passage d un autre groupe
      // change de CARTE : son secondaire et sa bulle viennent du rendu complet,
      // qui les ecrit d un seul geste. Ce chemin-ci ne sait patcher qu un etat,
      // pas reecrire une carte.
      const heure = chip.dataset.time || '';
      const retenue = chosen ? chosen.includes(heure) : heure === selected;
      if ((chip.getAttribute('data-coince-motif') === 'vague') !== Boolean(!retenue && emportees.get(heure))) return true;
      return unavailable && (chip.dataset.reason || '') !== (item.reason || 'Indisponible');
    })) return false;
    chips.forEach((chip, index) => {
      const time = chip.dataset.time || '';
      const unavailable = chip.classList.contains('is-unavailable');
      const isActive = chosen ? chosen.includes(time) : time === selected;
      const isChained = !isActive && !unavailable && time === chained;
      chip.classList.toggle('active', isActive);
      chip.classList.toggle('is-chained', isChained);
      chip.setAttribute('aria-pressed', isActive ? 'true' : 'false');
      // La qualification « Enchaîné » se pose et se retire avec l etat, sans
      // reconstruire la carte : seule la ligne concernee change.
      const item = (activity.times || [])[index];
      if (item && item.time === time) {
        const model = anchorSlotCardModel(activity, item, { isChained, unavailable });
        chip.setAttribute('aria-label', model.label);
        const tag = chip.querySelector('.slot-card-tag');
        if (model.tag && !tag) {
          chip.querySelector('.slot-card-time')?.insertAdjacentHTML('afterend',
            `<span class="slot-card-tag${model.tagTone ? ` is-${model.tagTone}` : ''}">${escapeHtml(model.tag)}</span>`);
        } else if (!model.tag && tag) tag.remove();
        else if (model.tag && tag && tag.textContent !== model.tag) tag.textContent = model.tag;
      }
      // Compte atteint : les heures non retenues cessent d'etre cliquables, et
      // le compteur au-dessus dit comment en liberer une.
      // LA MEME REGLE QU AU RENDU INITIAL : une heure qui coince reste
      // cliquable et porte sa raison. Ce chemin posait `disabled`, donc le
      // client qui remplissait sa liste voyait les autres heures devenir
      // MORTES alors que le rendu initial, lui, les explique. Deux chemins,
      // deux comportements : c est ce que ce fichier a deja paye sur le
      // compteur des parties.
      const blocage = raisonHeureCoincee({
        rangeeVerrouillee: disabled,
        listePleine: Boolean(chosen && full && !isActive),
        parties: Number(activity.count || 1),
        indisponible: unavailable,
        raisonCourte: chip.getAttribute('data-reason') || '',
        vague: isActive ? null : (emportees.get(time) || null),
        retenue: isActive,
      });
      const raisonCoince = blocage.texte;
      if (chip.disabled) chip.disabled = false;
      if (raisonCoince) {
        if (chip.getAttribute('data-coince') !== raisonCoince) {
          chip.setAttribute('data-coince', raisonCoince);
          const bulle = chip.querySelector('.slot-card-why');
          if (bulle) bulle.textContent = raisonCoince;
          else chip.insertAdjacentHTML('beforeend', `<span class="slot-card-info" aria-hidden="true">i</span><span class="slot-card-why" role="note">${escapeHtml(raisonCoince)}</span>`);
        }
        if (chip.getAttribute('data-coince-motif') !== blocage.motif) chip.setAttribute('data-coince-motif', blocage.motif);
        chip.setAttribute('aria-disabled', 'true');
        chip.setAttribute('onclick', 'expliquerHeureCoincee(this)');
      } else if (chip.hasAttribute('data-coince')) {
        chip.removeAttribute('data-coince');
        chip.removeAttribute('data-coince-motif');
        chip.removeAttribute('data-coince-ouvert');
        chip.removeAttribute('aria-disabled');
        chip.querySelector('.slot-card-info')?.remove();
        chip.querySelector('.slot-card-why')?.remove();
        chip.setAttribute('onclick', `setFormulaAnchorTime('${activity.activityId}','${time}')`);
      }
      // La capsule ne ressort que sur l'heure qui VIENT d'être choisie. La
      // classe reste posée tant que l'heure est active (l'animation est finie,
      // elle ne rejoue pas) : la retirer en cours de course couperait le pop
      // quand le réseau répond plus vite que les 160 ms du geste.
      const justPicked = Boolean(formulaJustPicked && isActive
        && formulaJustPicked.activityId === activity.activityId && formulaJustPicked.time === time);
      if (justPicked) formulaJustPicked = null;
      if (justPicked) chip.classList.add('is-just-picked');
      else if (!isActive) chip.classList.remove('is-just-picked');
    });
    // L'heure retenue se lit dans le titre de l'étape, sans reconstruire la tête.
    const head = row.querySelector('.anchor-row-head');
    if (head) {
      let pick = head.querySelector('.anchor-row-pick');
      const surPlace = disabled || Boolean(chosen && !chosen.length);
      const wanted = surPlace ? 'avec l’équipe' : (chosen ? chosen.join(' · ') : selected);
      if (wanted) {
        if (!pick) {
          pick = document.createElement('span');
          head.querySelector('strong')?.insertAdjacentElement('afterend', pick);
        }
        pick.className = `anchor-row-pick${surPlace ? ' anchor-row-pick-free' : ''}`;
        if (pick.textContent !== wanted) pick.textContent = wanted;
      } else if (pick) pick.remove();
    }
    // Le compteur (« 2 heures sur 3 ») suit la liste sans rendu complet : c'est
    // lui qui explique pourquoi les autres pastilles s'eteignent.
    const compteur = row.querySelector('.anchor-part-count');
    if (compteur && chosen) {
      // LA MEME FONCTION QUE LE RENDU INITIAL : c est tout l interet. Deux
      // ecritures cote a cote avaient diverge en silence.
      const texte = etatDesPartiesLaser(chosen.length, partCount);
      if (compteur.textContent !== texte) compteur.textContent = texte;
    }
    row.classList.toggle('anchor-row-onsite', disabled);
    const onsite = row.querySelector('.anchor-onsite');
    if (onsite) {
      onsite.classList.toggle('active', laserOnSite && isLaser);
      const box = onsite.querySelector('input[type="checkbox"]');
      if (box && box.checked !== (laserOnSite && isLaser)) box.checked = laserOnSite && isLaser;
    }
    // Le point du moment qui porte l'heure retenue.
    const periodKeys = chosen
      ? new Set(chosen.map(getAnchorPeriodKey))
      : new Set(selected ? [getAnchorPeriodKey(selected)] : []);
    row.querySelectorAll('.anchor-period-tab').forEach((tab) => {
      tab.classList.toggle('has-pick', periodKeys.has(tab.dataset.period));
      if (tab.disabled !== disabled) tab.disabled = disabled;
    });
    row.querySelectorAll('.anchor-track-nudge').forEach((button) => {
      if (disabled && !button.disabled) button.disabled = true;
    });
    if (!disabled) {
      const track = row.querySelector('.anchor-track');
      if (track) syncAnchorTrackState(track);
    }
  }

  const zone = picker.querySelector('[data-role="anchor-status-zone"]');
  if (!zone) return false;
  if (busy) {
    // Pendant la vérification, RIEN n'est remplacé : la zone se met en retrait
    // et le bouton de validation se désarme. Aucun aplat ne disparaît.
    zone.classList.add('is-checking');
    zone.setAttribute('aria-busy', 'true');
    zone.querySelectorAll('button').forEach((button) => { button.disabled = true; });
    return true;
  }
  // Réponse arrivée : les maillons du fil disent le nouvel écart réel.
  const notices = getSlotComfortNotices();
  picker.querySelectorAll('.visit-rail-link').forEach((link) => link.remove());
  // Plus de filtre `:not(.visit-rail-step-free)` : cette etape n existe plus
  // depuis que ce qui se vit sans horaire est une ligne du recapitulatif
  // (2026-09-18). Un `:not` qui vise une classe morte se lit comme une regle
  // qui protege quelque chose, alors qu il ne protege plus rien.
  const stepLis = [...picker.querySelectorAll('.visit-rail-step')];
  for (let index = steps.length - 1; index >= 1; index -= 1) {
    const html = renderVisitRailLink(steps[index - 1], steps[index], notices);
    if (html) stepLis[index].insertAdjacentHTML('beforebegin', html);
  }
  zone.classList.remove('is-checking');
  zone.setAttribute('aria-busy', 'false');
  zone.innerHTML = renderFormulaAnchorStatus(formule);
  return true;
}

// Formules SANS ancre (table anniversaire + pass liberté) : le seul choix est
// l'heure d'arrivée : la table suit automatiquement.
function renderFormulaArrivalPicker(formule) {
  const slots = state.availableSlots || [];
  if (!slots.length) return '';
  if (!slots.some(slot => slot.time === formulaArrivalChoice)) formulaArrivalChoice = '';
  const activeIndex = slots.findIndex(slot => slot.time === formulaArrivalChoice);
  const activeSlot = activeIndex >= 0 ? slots[activeIndex] : null;
  // Fenetre ouverte : pas de table, des activites a volonte jusqu a la fin de
  // la periode (l heure de fin vient du plan rendu par le serveur).
  const openWindow = Boolean(formule && formule.orderPolicy === 'open_window');
  const windowEnd = openWindow ? ((slots[0] && slots[0].opsPlan && slots[0].opsPlan.endTime) || '') : '';
  const arrivalHint = openWindow
    ? `Activités à volonté${windowEnd ? ` jusqu'à ${windowEnd}` : ''}. Présentez-vous 10 min avant.`
    : "Table prête dès l'arrivée, activités à votre rythme. Présentez-vous 10 min avant.";
  const chips = slots.map(slot => `
    <button type="button" class="formula-arrival-chip ${activeSlot && slot.time === formulaArrivalChoice ? 'active' : ''}" onclick="setFormulaArrivalChoice('${escapeHtml(slot.time)}')">
      ${escapeHtml(typeof displayTime === 'function' ? displayTime(slot.time) : slot.time)}
    </button>`).join('');
  return `
    <div class="formula-arrival-picker">
      <div class="formula-arrival-head">
        <strong>Choisissez votre heure d'arrivée</strong>
        <span>${escapeHtml(arrivalHint)}</span>
      </div>
      <div class="formula-arrival-grid">${chips}</div>
      ${activeSlot ? `
        <div class="formula-program-panel">
          ${renderFormulaVisitSummary(activeSlot, formule)}
          <button type="button" class="btn-primary formula-plan-confirm" onclick="selectSlot(${activeIndex})">Choisir cette arrivée</button>
        </div>` : `
        <p class="formula-arrival-hint">Touchez une heure pour voir le résumé de votre visite.</p>
        ${ligneSansHoraire(formule)}`}
    </div>`;
}

function setFormulaArrivalChoice(time) {
  formulaArrivalChoice = time;
  renderSlots(state.booking.type === 'formule' ? resolveDisplayFormule(state.booking.formuleId) : null);
}

function renderFormulaEmptySlots(formule) {
  return `
    <div class="slot-state slot-state-empty" role="status">
      <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
      <div>
        <strong>Aucun créneau disponible</strong>
        <span>${escapeHtml(formulaAnchorMessage || 'Essayez une autre date, un autre horaire ou un groupe plus petit.')}</span>
        <div class="slot-state-actions">
          <button type="button" class="btn-secondary" onclick="openCustomRequestModal()">Demander une proposition</button>
          <small>Votre demande sera étudiée par l'équipe, sans bloquer de date.</small>
        </div>
      </div>
    </div>`;
}

// Panne serveur (P3-9) : état distinct du « zéro créneau », la disponibilité
// n'a pas pu être chargée, on propose de réessayer sans perdre les choix.
function renderSlotLoadError() {
  return `
    <div class="slot-state slot-state-error" role="alert">
      <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
      <div>
        <strong>Impossible de charger les créneaux</strong>
        <span>${escapeHtml(slotLoadFailedMessage || 'Le service ne répond pas pour le moment. Vos choix sont conservés.')}</span>
        <button type="button" class="slot-retry-btn" onclick="retryFetchSlots()">Réessayer</button>
      </div>
    </div>`;
}

function retryFetchSlots() {
  fetchSlots({ showLoading: true });
}

function renderSlots(formule) {
  const isLaser = state.booking.type === 'laser';
  const ds = parseLocalDate(state.booking.date).toLocaleDateString('fr-BE', { weekday:'long', day:'2-digit', month:'short' });
  const slotTitle = document.getElementById('slotTitle');
  // UN SEUL titre pour cet écran. « HORAIRE DISPONIBLE » en capitales suivi de
  // « Composez votre visite » deux lignes plus bas disait deux fois la même
  // chose (Movsar, 2026-08-15). Le titre de la carte porte l'intention, le
  // sous-titre porte la date, et le bloc interne n'a plus d'en-tête.
  // Des QUESTIONS, pas des intitules de rubrique : l ecran demande, le client
  // repond. « Horaire disponible » ne demandait rien.
  if (slotTitle) {
    slotTitle.textContent = formulaHasAnchorUi() ? 'Composez votre visite' : (formule ? 'Votre programme' : 'À quelle heure ?');
    // La question de cet ecran s ecrit mot a mot, comme celles des autres.
    if (typeof revelerQuestion === 'function') revelerQuestion(slotTitle);
  }
  // Le rappel de venue : meme contenu que celui de l ecran des activites, et il
  // ramene a la question precedente. Il se remplit ICI pour suivre chaque
  // changement de date ou de groupe.
  const rappelVenue = document.getElementById('s2VenueLine');
  if (rappelVenue) {
    const texte = document.getElementById('s2VenueLineText');
    if (texte && typeof venueSummaryLabel === 'function') texte.textContent = venueSummaryLabel();
    rappelVenue.hidden = !(texte && texte.textContent);
  }
  // L HORAIRE DU JOUR, ICI AUSSI. Sans lui, un client qui regarde a 11h un
  // vendredi (ouverture 14h) ne voit aucune heure du matin et croit a une
  // panne. La plage est celle deja calculee pour l ecran precedent : une
  // seule source, pas une phrase recalculee a cote.
  const creneauDate = document.getElementById('slotDate');
  if (creneauDate) {
    let plage = '';
    try {
      const sch = typeof getSchedule === 'function' ? getSchedule(state.booking.date, state.isHolidayMode) : null;
      plage = sch && sch.label ? String(sch.label) : '';
    } catch (error) {
      plage = '';
    }
    creneauDate.textContent = plage ? `${ds} · ouvert ${plage}` : ds;
  }
  const tl = document.getElementById('formTimeLimit');
  if (formule) {
    // La durée estimée et le compteur brut de programmes vivent désormais dans
    // l'en-tête du picker « heure d'arrivée » : pas de double bandeau.
    tl.innerHTML = formule.timeLimit
      ? `<div class="info-box"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg><div>Horaires limités à la formule</div></div>`
      : '';
  } else if (isLaser) {
    const option = getLaserOption(state.booking.duration);
    const waveCount = getLaserWaveCount(state.booking.pax);
    const splitText = waveCount > 1 ? ` · groupe réparti sur ${waveCount} sessions` : '';
    tl.innerHTML = `<div class="info-box"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0"><circle cx="12" cy="12" r="10"/><path d="M12 7v5l3 2"/></svg><div><b>${option.label} Laser Game</b> · ${option.price}€ / personne${splitText} · session partagée selon l'affluence</div></div>`;
  } else tl.innerHTML = '';

  const list = document.getElementById('slotList');
  if (slotLoading) {
    // \u00c9tat de chargement stable : bandeau discret + grille squelette de la
    // m\u00eame taille que les futurs cr\u00e9neaux (pas de saut de layout, pas de
    // grosse horloge flottante).
    list.innerHTML = `
      <div class="slot-state slot-state-loading" role="status" aria-live="polite">
        <span class="slot-spinner" aria-hidden="true"></span>
        <span>Recherche des cr\u00e9neaux disponibles\u2026</span>
      </div>
      <div class="slot-grid slot-grid-skeleton" aria-hidden="true">
        ${Array.from({ length: 8 }, () => '<div class="slot slot-skeleton"><span class="slot-skeleton-line"></span><span class="slot-skeleton-line short"></span></div>').join('')}
      </div>`;
    return;
  }
  if (slotLoadFailed) {
    list.innerHTML = renderSlotLoadError();
    return;
  }
  if (formulaHasAnchorUi()) {
    // Choix de l'heure PAR ACTIVITE : le picker reste affiché même sans
    // créneau composé (combinaison refusée → message + suggestions proches).
    // Il ne dépend PAS d'une formule : une visite à la carte avec plusieurs
    // activités à créneau (bowling + laser) reçoit exactement les mêmes
    // ancres du serveur. Tant que cette condition exigeait une formule, le
    // client jetait des ancres valides et affichait « Aucun créneau
    // disponible » alors que le serveur en proposait neuf.
    snapshotAnchorTrackScroll();
    // Positions d AVANT la reconstruction : c est la seule chose que le nouveau
    // DOM ne pourra plus dire.
    const positionsAvant = releverPositionsFilVisite();
    list.innerHTML = renderFormulaAnchorPicker(formule);
    bindAnchorTracks();
    jouerFlipFilVisite(positionsAvant);
    return;
  }
  if (!state.availableSlots.length) {
    list.innerHTML = renderFormulaEmptySlots(formule);
    return;
  }
  if (formule) {
    const picker = renderFormulaArrivalPicker(formule);
    list.innerHTML = picker || renderFormulaEmptySlots(formule);
    return;
  }
  // MEME FAMILLE DE COMPOSANT que le composeur de visite : `slot-card` porte
  // la forme (heure, fin, qualification, secondaire), la donnee change.
  //
  // DEUX REGLES REPRISES DU COMPOSEUR (2026-08-31). Movsar, sur cet ecran :
  // "c est vraiment moche comment tout est fait, il y a trop de boutons, on
  // comprend pas trop, il y a trop de texte, plus simple et plus direct".
  // Mesure d avant : 27 boutons d affilee, et les 27 disaient mot pour mot
  // "8 pistes libres". Le composeur de visite avait deja resolu les deux
  // problemes de son cote ; la liste simple, elle, etait restee brute.
  //
  // 1. LES HEURES SE LISENT PAR MOMENT (matin / apres-midi / soir), avec un
  //    intertitre. Trois groupes courts se balayent ; une colonne de 27 non.
  //    Ce ne sont PAS des onglets : aucun bouton de plus, aucune heure
  //    cachee, juste des reperes dans la meme liste.
  // 2. CE QUI EST VRAI PARTOUT SE DIT UNE FOIS. Une mention portee par plus
  //    de la moitie des heures monte au-dessus de la liste et quitte les
  //    cartes ; celles qui s en ecartent gardent la leur, et c est justement
  //    celles-la que le client doit voir.
  const showLanes = reservationNeedsLanes(state.booking.type, state.booking.formuleId);
  const modeles = state.availableSlots.map((s, i) => {
    const bouts = [];
    if (showLanes) bouts.push(`${s.freeCount} piste${Number(s.freeCount) > 1 ? 's' : ''} libre${Number(s.freeCount) > 1 ? 's' : ''}`);
    else if (isLaser) bouts.push(getLaserSlotCapacityText(s));
    if (isLaser) bouts.push(getLaserSlotAfterText(s));
    else if (s.opsPlan) bouts.push(describeSlotPlan(s.opsPlan));
    return {
      index: i,
      time: s.time,
      affichee: typeof displayTime === 'function' ? displayTime(s.time) : s.time,
      // LA FIN DE LA VISITE, activites libres comprises (`visitEndTime`,
      // rendue par public-availability). `opsPlan.endTime` est le plan du
      // STAFF : il ne porte que les activites planifiees.
      endTime: s.visitEndTime || (s.opsPlan && s.opsPlan.endTime) || '',
      tag: isLaser
        ? (s.sharedSession ? 'Session partagée' : s.splitGroup ? 'Groupe découpé' : 'Session ouverte')
        : (s.opsPlan ? 'Plan conseillé' : ''),
      meta: bouts.filter(Boolean).join(' · '),
    };
  });
  // La valeur MAJORITAIRE d un champ, si elle couvre plus de la moitie des
  // heures. Sous ce seuil il n y a pas de dominante : chaque carte garde la
  // sienne, sinon on effacerait une information qui distingue vraiment.
  const dominante = (lire) => {
    const comptes = new Map();
    modeles.forEach((m) => {
      const valeur = lire(m);
      if (valeur) comptes.set(valeur, (comptes.get(valeur) || 0) + 1);
    });
    let gagnante = '';
    let compte = 0;
    comptes.forEach((n, valeur) => { if (n > compte) { gagnante = valeur; compte = n; } });
    if (compte * 2 <= modeles.length) return { valeur: '', partout: false };
    return { valeur: gagnante, partout: compte === modeles.length };
  };
  const metaCommune = dominante((m) => m.meta);
  const tagCommun = dominante((m) => m.tag);
  const entete = [
    tagCommun.valeur ? `${tagCommun.valeur}${tagCommun.partout ? '' : ' pour la plupart des heures'}` : '',
    metaCommune.valeur ? `${metaCommune.valeur}${metaCommune.partout ? ' à chaque heure' : ', sauf mention sur l’heure'}` : '',
  ].filter(Boolean).join(' · ');
  const groupes = groupAnchorTimes(modeles);
  const sections = groupes.map((groupe) => `
    <section class="slot-period">
      <h3 class="slot-period-title">${escapeHtml(groupe.label)}</h3>
      <div class="slot-grid stagger">${groupe.items.map((m) => {
        const tag = m.tag === tagCommun.valeur ? '' : m.tag;
        const meta = m.meta === metaCommune.valeur ? '' : m.meta;
        return `<button class="slot slot-card" data-time="${escapeHtml(m.time)}" onclick="selectSlot(${m.index})">${slotCardMarkup({
          time: m.affichee,
          endTime: m.endTime,
          tag,
          tagTone: tag ? 'accent' : '',
          meta,
        })}</button>`;
      }).join('')}</div>
    </section>`).join('');
  list.innerHTML = `${entete ? `<p class="slot-shared-meta">${escapeHtml(entete)}</p>` : ''}${sections}`;
}

function selectSlot(i) {
  const slot = state.availableSlots[i];
  if (!slot) return;
  state.booking.startTime = slot.time;
  state.booking.allocatedLanes = slot.lanes;
  state.booking.opsPlan = slot.opsPlan || null;
  state.booking.laneCount = (slot.lanes || []).length;
  state.booking.bowlingCapacity = slot.bowlingCapacity || slot.opsPlan?.resourceBlocks?.find(block => block.resourceType === 'bowling_lane')?.bowlingCapacity || null;
  if (slot.program && Array.isArray(slot.program.items)) state.booking.serverProgram = slot.program;
  if (Number.isFinite(Number(slot.price)) && slot.price != null) state.booking.serverPrice = Number(slot.price);
  const formule = state.booking.type === 'formule' ? resolveDisplayFormule(state.booking.formuleId) : null;
  if (formule && slot.opsPlan && formulaHasAnchorUi()) {
    // Fige les ancres du créneau retenu : le serveur revalide exactement
    // cette combinaison à la confirmation (POST refusé sinon).
    const preference = createDefaultFormulaPreference(state.booking.preference || {});
    const anchorTimes = slot.opsPlan.anchorPlan?.times || {};
    ['bowling', 'laser_game'].forEach((activityId) => {
      preference.preferredTimes[activityId] = anchorTimes[activityId]
        || getFormulaSlotActivityTime(slot, activityId)
        || '';
    });
    // Le plan retenu dit l'heure de CHAQUE partie : on fige la liste complete,
    // sinon la confirmation repartirait avec une autre combinaison que celle
    // que le client vient de valider.
    const partTimes = slot.opsPlan.anchorPlan?.laserGameTimes;
    if (Array.isArray(partTimes) && partTimes.length) {
      preference.laserGameTimes = partTimes.map(time => (typeof time === 'string' ? time : ''));
      preference.preferredTimes.laser_game = preference.laserGameTimes.find(time => time) || '';
    }
    if (slot.opsPlan.anchorPlan?.laserPlacement === 'onsite') {
      preference.laserPlacement = 'onsite';
      preference.preferredTimes.laser_game = '';
      preference.laserGameTimes = getBookingLaserPartTimes(preference).map(() => '');
    }
    state.booking.preference = preference;
  }
  if (state.booking.type === 'laser' && slot.opsPlan?.totalMinutes) {
    state.booking.totalDuration = Math.max(Number(state.booking.duration) || 0.5, Math.ceil(Number(slot.opsPlan.totalMinutes) / 30) / 2);
  }
  // Une formule SANS plan d'ancres est une formule « pass liberté » : le
  // serveur ne pouvait pas savoir quelle heure d'arrivée le client retiendrait,
  // donc il n'a envoyé aucune montée. Maintenant qu'elle est choisie, on la lui
  // dit. Fail-soft, jamais bloquant pour la suite du tunnel.
  if (state.booking.type === 'formule' && !(slot.opsPlan && slot.opsPlan.anchorPlan)) {
    refreshFormulaComplements();
  }
  goStep(3);
}

function goStep4() {
  const name = document.getElementById('fName').value.trim();
  const phone = document.getElementById('fPhone').value.trim();
  const email = document.getElementById('fEmail').value.trim();
  ['fName', 'fPhone', 'fEmail'].forEach(clearFieldError);
  const fieldErrors = [];
  if (!name) fieldErrors.push(['fName', 'Indiquez votre prénom et nom.']);
  else if (name.length < 2) fieldErrors.push(['fName', 'Merci d\'indiquer votre nom complet.']);
  const phoneDigits = phone.replace(/[^0-9]/g, '');
  if (!phone) fieldErrors.push(['fPhone', 'Indiquez un numéro de téléphone.']);
  else if (phoneDigits.length < 8 || phoneDigits.length > 15) fieldErrors.push(['fPhone', 'Numéro de téléphone invalide.']);
  if (!email) fieldErrors.push(['fEmail', 'Indiquez votre email pour recevoir la confirmation.']);
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) fieldErrors.push(['fEmail', 'Adresse email invalide, vérifiez-la pour recevoir votre confirmation.']);
  if (fieldErrors.length) {
    fieldErrors.forEach(([inputId, text]) => setFieldError(inputId, text));
    // Les erreurs sont déjà annoncées et liées aux champs. Un bandeau flottant
    // recouvrait leur label sur téléphone au moment même de les corriger.
    clearAlert();
    const firstInvalid = document.getElementById(fieldErrors[0][0]);
    if (firstInvalid) firstInvalid.focus();
    return;
  }
  state.booking.name = name;
  state.booking.phone = phone;
  state.booking.email = email;
  const specialRequestInput = document.getElementById('fSpecialRequest');
  state.booking.specialRequest = specialRequestInput ? specialRequestInput.value.trim().slice(0, 500) : '';
  const occasionOtherInput = document.getElementById('fOccasionOther');
  state.booking.occasionOther = (occasionOtherInput && state.booking.occasion === 'autre')
    ? occasionOtherInput.value.trim().slice(0, 160)
    : '';
  renderRecap();
  goStep(4);
  // L OFFRE D ATTENTE arrive AVANT la confirmation, une seule fois : c est le
  // dernier moment ou le client peut encore l ajouter sans rien changer a ses
  // heures (Movsar : « ptite pop up apparait avec loffre avant confirmation »).
  if (typeof proposerOffreAttente === 'function') proposerOffreAttente();
}

// Occasion DÉCLARÉE par le client. Les six clés sont alignées sur l'enum
// serveur (OCCASION_VALUES, lib/reservation-request.js), 'evg' compris :
// chaque chip du tunnel est stockée telle quelle en base.
// '' = non précisé. Propagée au serveur → catégorisation staff déclarée.
const BOOKING_OCCASIONS = ['anniversaire', 'amis', 'entreprise', 'ecole', 'evg', 'autre'];
function setBookingOccasion(value) {
  const next = BOOKING_OCCASIONS.includes(value)
    ? (state.booking.occasion === value ? '' : value)
    : '';
  state.booking.occasion = next;
  document.querySelectorAll('#occasionChips .occasion-chip').forEach(chip => {
    const active = chip.dataset.occasion === next;
    chip.classList.toggle('active', active);
    chip.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
  // « Autre » ouvre un champ de précision libre (stocké et joint aux notes de la
  // réservation pour l'analyse direction). Toute autre valeur le referme/efface.
  const otherWrap = document.getElementById('occasionOtherWrap');
  const otherInput = document.getElementById('fOccasionOther');
  const showOther = next === 'autre';
  if (otherWrap) otherWrap.classList.toggle('hidden', !showOther);
  if (!showOther) {
    state.booking.occasionOther = '';
    if (otherInput) otherInput.value = '';
  } else if (otherInput) {
    setTimeout(() => { try { otherInput.focus(); } catch (e) {} }, 30);
  }
  save();
}

// Texte libre de l'occasion « Autre » (max 160). Conservé sur le booking et
// injecté dans les notes de la réservation à la confirmation.
function setBookingOccasionOther(value) {
  state.booking.occasionOther = String(value || '').slice(0, 160);
  save();
}

// ── Demande SUR MESURE (lead entreprise / besoin spécial) ──────────────────
// ── Champ « Demande particuliere » ─────────────────────────────────────────
// Une zone de texte vide ne dit pas quoi ecrire, et sa poignee de
// redimensionnement est le seul indice que le texte peut etre long. Ici : le
// champ grandit tout seul a la frappe (aucune poignee) et le compteur ne
// s affiche qu en approche de la limite (un compteur permanent met la pression
// pour rien). L exemple du placeholder porte le reste du travail : il montre
// une demande que le centre peut REELLEMENT traiter (deposer un gateau au
// frais), pas un service qu il ne rend pas.
const SPECIAL_REQUEST_MAX = 500;

function autoGrowSpecialRequest(field) {
  if (!field) return;
  field.style.height = 'auto';
  // Plafond : au-dela, le champ defile au lieu de pousser le bouton hors ecran.
  field.style.height = Math.min(field.scrollHeight, 220) + 'px';
}

function handleSpecialRequestInput(field) {
  autoGrowSpecialRequest(field);
  const counter = document.getElementById('specialRequestCount');
  if (!counter) return;
  const used = String(field.value || "").length;
  const showFrom = SPECIAL_REQUEST_MAX - 120;
  counter.textContent = used >= showFrom ? `${used} / ${SPECIAL_REQUEST_MAX}` : "";
  counter.classList.toggle('is-close', used >= SPECIAL_REQUEST_MAX - 20);
}

// Crée un LEAD (hors planning), pas une réservation. POST /api/custom-request.
const customRequestState = { occasion: '' };

function setCustomRequestOccasion(value) {
  const next = BOOKING_OCCASIONS.includes(value)
    ? (customRequestState.occasion === value ? '' : value)
    : '';
  customRequestState.occasion = next;
  document.querySelectorAll('#crOccasionChips .occasion-chip').forEach(chip => {
    const active = chip.dataset.occasion === next;
    chip.classList.toggle('active', active);
    chip.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
}

function openCustomRequestModal() {
  const modal = document.getElementById('customRequestModal');
  if (!modal) return;
  // Pré-remplit avec ce que le client a déjà saisi à l'étape 1 (contexte utile).
  const b = state.booking || {};
  const dateInput = document.getElementById('crDate');
  const paxInput = document.getElementById('crPax');
  // Le champ demande une PHRASE (« Ex. samedi 12 sept. ou mi-octobre ») et part
  // en texte libre au centre : le pre-remplir avec la valeur machine du tunnel
  // (« 2026-09-03 ») donnait au client une date d ordinateur a relire. Meme
  // formatage que le recapitulatif, une seule fonction pour les deux.
  if (dateInput && !dateInput.value && b.date) dateInput.value = formatBookingDateLong(b.date);
  if (paxInput && !paxInput.value && Number(b.pax) > 0) paxInput.value = b.pax;
  setCustomRequestOccasion(b.occasion || '');
  const success = document.getElementById('bespokeSuccess');
  const form = document.getElementById('bespokeForm');
  if (success) { success.classList.add('hidden'); success.textContent = ''; }
  if (form) form.classList.remove('hidden');
  const errorBox = document.getElementById('bespokeError');
  if (errorBox) errorBox.classList.add('hidden');
  modal.classList.remove('hidden');
  document.body.classList.add('modal-open');
  const nameInput = document.getElementById('crName');
  if (nameInput) setTimeout(() => nameInput.focus(), 30);
}

function closeCustomRequestModal() {
  const modal = document.getElementById('customRequestModal');
  if (!modal) return;
  modal.classList.add('hidden');
  document.body.classList.remove('modal-open');
}

function showCustomRequestError(message) {
  const errorBox = document.getElementById('bespokeError');
  if (!errorBox) return;
  errorBox.textContent = message;
  errorBox.classList.remove('hidden');
}

async function submitCustomRequest() {
  const val = id => (document.getElementById(id)?.value || '').trim();
  const name = val('crName');
  const email = val('crEmail');
  const message = val('crMessage');
  const errorBox = document.getElementById('bespokeError');
  if (errorBox) errorBox.classList.add('hidden');

  if (!name) { showCustomRequestError('Merci d\'indiquer le nom du contact.'); return; }
  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { showCustomRequestError('Un email valide est requis pour vous recontacter.'); return; }
  if (!message) { showCustomRequestError('Décrivez votre besoin en quelques mots.'); return; }

  const submitBtn = document.getElementById('crSubmit');
  const payload = {
    kind: 'custom-request',
    // LE CENTRE VIENT DE L ADRESSE PUBLIQUE, comme pour une reservation normale.
    // Ici la demande partait avec le centre STAFF memorise, avec un repli en dur
    // sur Libramont : depuis la page publique d un autre etablissement, elle
    // arrivait chez le mauvais tenant. getTunnelCenterId lit le centre affiche ;
    // le centre staff ne reste qu en dernier recours, hors tunnel public.
    centerId: String(
      (typeof getTunnelCenterId === 'function' && getTunnelCenterId())
      || (typeof getCurrentStaffCenterId === 'function' && getCurrentStaffCenterId())
      || 'libramont',
    ),
    contactName: name,
    company: val('crCompany'),
    email,
    phone: val('crPhone'),
    requestedDate: val('crDate'),
    pax: Number(document.getElementById('crPax')?.value || 0) || 0,
    occasion: customRequestState.occasion || '',
    message,
  };

  try {
    if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = 'Envoi en cours…'; }
    await apiRequest('/api/custom-request', { method: 'POST', body: JSON.stringify(payload) });
    const form = document.getElementById('bespokeForm');
    const success = document.getElementById('bespokeSuccess');
    if (form) form.classList.add('hidden');
    if (success) {
      success.innerHTML = 'Demande bien envoyée ! Vous recevez un accusé par email et notre équipe vous recontacte rapidement.';
      success.classList.remove('hidden');
    }
    ['crName', 'crCompany', 'crEmail', 'crPhone', 'crDate', 'crPax', 'crMessage'].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.value = '';
    });
    setCustomRequestOccasion('');
  } catch (error) {
    showCustomRequestError(error.message || 'Impossible d\'envoyer la demande. Réessayez.');
  } finally {
    if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = 'Envoyer ma demande'; }
  }
}

// Récap « Ancres + Liberté » d'une réservation formule.
function getFormulaRecapModel(booking) {
  const plan = booking.opsPlan || {};
  const blocks = Array.isArray(plan.resourceBlocks) ? plan.resourceBlocks : [];
  const preference = createDefaultFormulaPreference(booking.preference || {});
  const formule = resolveDisplayFormule(booking.formuleId) || null;
  const appointments = [];
  const bowlingTime = blocks.find(block => block.resourceType === 'bowling_lane')?.startTime
    || preference.preferredTimes.bowling;
  // TOUTES LES VAGUES, PAS LA PREMIERE. `find` ramenait un seul bloc d arene
  // la ou un groupe scinde en a plusieurs : cet ecran annoncait 11:00 pendant
  // que la carte de visite annoncait 11:30, pour la meme reservation.
  const passagesLaser = rendezVousLaser(blocks);
  const laserTime = passagesLaser.length
    ? ''
    : (preference.laserPlacement === 'onsite' ? '' : preference.preferredTimes.laser_game);
  if (bowlingTime) appointments.push(`Bowling ${bowlingTime}`);
  if (passagesLaser.length) appointments.push(...passagesLaser.map((item) => item.texte));
  else if (laserTime) appointments.push(`Laser Game ${laserTime}`);
  const freeLabels = (formulaAnchorData?.freePass || []).map(item => item.label);
  if (!freeLabels.length && formule) {
    freeLabels.push(...getFormulaFreePassIds(formule).map(id => ACTIVITY_LABELS[id] || id));
  }
  return {
    appointments,
    laserOnSite: preference.laserPlacement === 'onsite',
    remainingLaser: Number(plan.laserPassPlan?.remainingGames || 0),
    hasTable: blocks.some(block => block.resourceType === 'party_table') || (formule && formulaHasPartyTable(formule)),
    arrivalTime: plan.arrivalTime || '',
    freeLabels,
  };
}

// L OFFRE D ATTENTE S ANNONCE AVANT LA CONFIRMATION (Movsar, 2026-09-17 :
// « ptite pop up apparait avec loffre avant confirmation sur pinlane »). Une
// seule fois par jeu de cartes : fermee, elle ne revient pas, et les cartes
// restent dans le recapitulatif pour qui change d avis.
let offreAttenteAnnoncee = '';
function cartesDAttente() {
  return (Array.isArray(formulaComplements) ? formulaComplements : [])
    .filter((carte) => carte && carte.id && carte.kind === 'attente');
}

// La phrase qui dit POURQUOI, tiree des cartes elles-memes : elles portent
// le nombre de personnes qui attendent et la duree du temps mort.
function texteAttente() {
  const carte = cartesDAttente()[0] || null;
  if (!carte) return '';
  const personnes = Math.max(1, Number(carte.pax) || 1);
  // « en plusieurs fois » : un Fun Run de 12 joue en trois sessions, et depuis
  // le 2026-09-29 le duckpin et le Fun Run font eux aussi attendre.
  return `Votre groupe joue en plusieurs fois : ${personnes} personne${personnes > 1 ? 's' : ''} patientent pendant que les autres jouent.`;
}

function fermerOffreAttente() {
  const modale = document.getElementById('waitOfferModal');
  if (modale) modale.classList.add('hidden');
}

function proposerOffreAttente() {
  const cartes = cartesDAttente();
  const modale = document.getElementById('waitOfferModal');
  if (!modale) return;
  if (!cartes.length) { modale.classList.add('hidden'); return; }
  const signature = cartes.map((carte) => carte.id).join('|');
  if (offreAttenteAnnoncee === signature) return;
  offreAttenteAnnoncee = signature;
  const intro = document.getElementById('waitOfferIntro');
  if (intro) intro.textContent = texteAttente();
  const liste = document.getElementById('waitOfferList');
  if (liste) {
    liste.innerHTML = cartes.map((carte) => `
      <div class="complement-card">
        <span class="complement-copy">
          <strong class="complement-name">${escapeHtml(carte.name || '')}</strong>
          <small class="complement-adds">${escapeHtml(carte.addsLabel || '')}</small>
          ${carte.totalLabel ? `<small class="complement-total">${escapeHtml(carte.totalLabel)}</small>` : ''}
          ${carte.noteLabel ? `<small class="complement-note">${escapeHtml(carte.noteLabel)}</small>` : ''}
        </span>
        <span class="complement-amount">${escapeHtml(carte.amountLabel || '')}</span>
        <button type="button" class="btn-secondary complement-add" data-complement="${escapeHtml(carte.id)}"
          onclick="accepterComplement(this.dataset.complement); fermerOffreAttente();"
          aria-label="Ajouter ${escapeHtml(carte.name || '')}, ${escapeHtml(carte.amountLabel || '')}">Ajouter</button>
      </div>`).join('');
  }
  modale.classList.remove('hidden');
}

function renderRecap() {
  const b = state.booking;
  const formule = b.type === 'formule' ? resolveDisplayFormule(b.formuleId) : null;
  const isLaser = b.type === 'laser';
  const isVisit = b.type === 'visite';
  const visitProgram = isVisit && b.serverProgram && Array.isArray(b.serverProgram.items)
    ? b.serverProgram
    : null;
  const showLanes = reservationNeedsLanes(b.type, b.formuleId);
  // Pour une visite, la source de verite d'affichage est le programme normalise
  // par public-availability. getBasePrice ne connait que les types historiques
  // et renverrait donc 0 pour "visite".
  const total = visitProgram
    ? Math.max(0, Number(visitProgram.price) || 0)
    : getBasePrice(b.type, Number(b.duration), b.laneCount, Number(b.pax), b.formuleId, b.date);
  const totalDuration = getBookingTotalDuration(b);
  const formulaRecap = formule ? getFormulaRecapModel(b) : null;
  const planLine = b.opsPlan ? describeSlotPlan(b.opsPlan) : '';
  const laserOption = isLaser ? getLaserOption(b.duration) : null;
  const laserWaveCount = isLaser ? Number(b.opsPlan?.laserSharing?.waveCount || getLaserWaveCount(b.pax)) : 1;
  const totalLabel = document.getElementById('recapTotalLabel');
  const totalNote = document.getElementById('recapTotalNote');
  const totalAmount = document.getElementById('recapTotal');
  if (isVisit && visitProgram) {
    const complete = visitProgram.priceComplete === true;
    if (totalLabel) totalLabel.textContent = complete ? 'Total' : (total > 0 ? 'À partir de' : 'Tarif');
    // RIEN ne s encaisse en ligne (2026-08-25, Movsar : « tout se regle
    // sur place ») : l ancienne note laissait croire qu une partie se
    // payait maintenant.
    if (totalNote) totalNote.textContent = complete
      ? 'Tout se règle sur place'
      : (total > 0 ? 'Tout se règle sur place, certaines activités y sont tarifées' : 'Montant confirmé à votre arrivée');
    if (totalAmount) totalAmount.textContent = complete || total > 0 ? `${total}€` : 'Sur place';
  } else {
    if (totalLabel) totalLabel.textContent = 'Total estimé';
    if (totalNote) totalNote.textContent = 'À régler sur place';
    if (totalAmount) totalAmount.textContent = `${total}€`;
  }
  const dateLabel = parseLocalDate(b.date).toLocaleDateString('fr-BE', { weekday:'long', day:'numeric', month:'long' });
  // UNE LIGNE DU RECAP N EXISTE QUE SI ELLE A UNE VALEUR. Sans creneau retenu
  // (retour a l ecran des heures, contexte remis a zero, session rechargee),
  // « Horaire » s ecrivait « • 1h » sans heure de debut et « Piste assignee »
  // sortait vide : sur le dernier ecran avant confirmation, deux lignes qui ne
  // disent rien valent moins que deux lignes absentes.
  const heureRetenue = String(b.startTime || '').trim();
  const pistesAssignees = Array.isArray(b.allocatedLanes) ? b.allocatedLanes.filter(lane => lane != null && lane !== '') : [];
  const nombreEtapes = visitProgram
    ? visitProgram.items.length
    : (isLaser ? laserWaveCount : (pistesAssignees.length || 1));
  const allocationLabel = visitProgram
    ? `activité${nombreEtapes > 1 ? 's' : ''}`
    : (isLaser
      ? `session${nombreEtapes > 1 ? 's' : ''}`
      : `piste${nombreEtapes > 1 ? 's' : ''}`);
  const bookingFactsHtml = `
    <div class="booking-facts" aria-label="Synthèse de la réservation">
      <div><span>Groupe</span><strong>${Number(b.pax) || 0}</strong><small>personne${Number(b.pax) > 1 ? 's' : ''}</small></div>
      <div><span>Durée</span><strong>${escapeHtml(formatDurationLabel(totalDuration))}</strong><small>sur place</small></div>
      <div><span>Organisation</span><strong>${nombreEtapes}</strong><small>${allocationLabel}</small></div>
    </div>`;
  const visitProgramHtml = visitProgram ? `
    <div class="recap-item recap-program-row">
      <span class="recap-label">Activités</span>
      <div class="recap-value recap-program-value">
        ${visitProgram.items.map(renderVisitRecapItem).join('')}
      </div>
    </div>` : '';
  document.getElementById('recapList').innerHTML = `
    ${bookingFactsHtml}
    <div class="recap-item"><span class="recap-label">Client</span><span class="recap-value">${escapeHtml(b.name)}</span></div>
    <div class="recap-item"><span class="recap-label">Téléphone</span><span class="recap-value">${escapeHtml(b.phone)}</span></div>
    <div class="recap-item"><span class="recap-label">Date</span><span class="recap-value">${dateLabel}</span></div>
    ${heureRetenue ? `<div class="recap-item"><span class="recap-label">${formule ? 'Première activité' : 'Horaire'}</span><span class="recap-value accent">${escapeHtml(heureRetenue)} <small style="font-size:13px;color:var(--text-3);font-weight:500;">• ${b.duration}h</small></span></div>` : ''}
    ${formule && b.opsPlan?.arrivalTime ? `<div class="recap-item"><span class="recap-label">Arrivée conseillée</span><span class="recap-value">${escapeHtml(b.opsPlan.arrivalTime)} <small style="font-size:13px;color:var(--text-3);font-weight:500;">• ${avanceDArrivee(b.opsPlan) > 0 ? `accueil ${avanceDArrivee(b.opsPlan)} min avant` : 'à l’heure de la première activité'}</small></span></div>` : ''}
    <div class="recap-item"><span class="recap-label">Joueurs</span><span class="recap-value">${b.pax} personne${b.pax > 1 ? 's' : ''}</span></div>
    ${showLanes && pistesAssignees.length ? `<div class="recap-item"><span class="recap-label">Piste${pistesAssignees.length > 1 ? 's' : ''} assignée${pistesAssignees.length > 1 ? 's' : ''}</span><span class="recap-value teal">${escapeHtml(pistesAssignees.join(' & '))}</span></div>` : ''}
    ${visitProgramHtml}
    ${isLaser ? `<div class="recap-item"><span class="recap-label">Activité</span><span class="recap-value">Laser Game · ${laserOption.label}</span></div>` : ''}
    ${formule ? `<div class="recap-item"><span class="recap-label">Formule</span><span class="recap-value">${formule.name}</span></div>` : ''}
    ${formulaRecap && formulaRecap.appointments.length ? `<div class="recap-item"><span class="recap-label">Vos rendez-vous</span><span class="recap-value">${formulaRecap.appointments.map(escapeHtml).join(' · ')}</span></div>` : ''}
    ${formulaRecap && formulaRecap.hasTable ? `<div class="recap-item"><span class="recap-label">Votre table</span><span class="recap-value">Dès l'arrivée${formulaRecap.arrivalTime ? ` (${escapeHtml(formulaRecap.arrivalTime)})` : ''}</span></div>` : ''}
    ${formulaRecap && formulaRecap.freeLabels.length ? `<div class="recap-item"><span class="recap-label">À votre rythme</span><span class="recap-value">${formulaRecap.freeLabels.map(escapeHtml).join(' · ')}</span></div>` : ''}
    ${formule ? `<div class="recap-item"><span class="recap-label">Temps total estimé</span><span class="recap-value">${formatDurationLabel(totalDuration)}</span></div>` : ''}
    ${bowlingCapacityMessage(b.bowlingCapacity) ? `<div class="recap-note" role="status">${escapeHtml(bowlingCapacityMessage(b.bowlingCapacity))}</div>` : ''}
    ${isLaser && (laserWaveCount > 1 || planLine) ? `<div class="recap-note"><b>Laser Game :</b> ${laserWaveCount > 1 ? `${laserWaveCount} sessions successives. ` : ''}${planLine ? `Plan retenu : ${planLine}.` : ''}</div>` : ''}
    ${formulaRecap && (formulaRecap.remainingLaser > 0 || formulaRecap.laserOnSite) ? `<div class="recap-note"><b>Laser Game :</b> ${formulaRecap.remainingLaser > 0 ? `${formulaRecap.remainingLaser} partie${formulaRecap.remainingLaser > 1 ? 's' : ''} à placer sur place avec l'équipe.` : ''} ${formulaRecap.laserOnSite ? 'Vous placez vos parties laser librement pendant la visite.' : ''}</div>` : ''}
    ${formule ? `<div class="recap-note"><b>Pass liberté :</b> aucune heure imposée, à vivre quand vous voulez.</div>` : ''}
    ${renderComplementCards()}
  `;
}

// LES COMPLEMENTS, EN FIN DE RECAPITULATIF ET DANS #recapList.
//
// Pourquoi ici et nulle part ailleurs : #recapList est la colonne qui DEFILE
// (flex: 1 1 0 puis overflow: hidden auto sous 640 px, minmax(0, 1fr) au-dessus
// de 1100 px) et .recap-decision est en flex: none. Ce qu'on ajoute dans
// #recapList est donc physiquement incapable de pousser « Confirmer la
// réservation » hors de l'écran. Le poser dans .recap-decision casserait la
// garde mobile du tunnel, mesurée par tunnel-one-screen.
//
// Une option impossible ne s'affiche pas : le serveur ne renvoie que les
// compléments qu'il a jugés faisables au créneau déjà retenu. Si l'un meurt
// entre l'affichage et le clic, c'est la réponse du serveur au clic que le
// client lit.
//
// CE QUI NE BOUGE PAS, CE SONT LES HEURES RETENUES. Pas la durée : mesure du
// 2026-09-04, hlg vers f2 à 8 personnes garde son bowling à 14:00 et fait
// passer la visite de 1h30 à 3h. La carte porte donc le nouveau temps total
// quand il diffère, et le sous-titre ne promet que ce que le mécanisme tient.
//
// UNE CARTE PEUT AUSSI PORTER UNE NOTE DE PLACEMENT. Une partie de laser en
// plus est FACTURÉE mais pas planifiée : le moteur la marque « pending » et
// l'équipe la place sur place (mesure du 2026-09-05). La carte le dit, sinon
// elle promettrait un horaire que la réservation ne pose pas. La phrase vient
// du serveur, qui la tire du plan du moteur : elle ne se compose pas ici.
function renderComplementCards() {
  const b = state.booking;
  // DEUX TUNNELS, UN SEUL BLOC. Une formule recoit des montees de formule ; une
  // visite composee a la carte recoit un palier de laser en plus et des
  // activites libres en plus. Les cartes ont la MEME forme, donc le rendu ne
  // sait pas de quel generateur elles viennent : il lit `id`, jamais `formuleId`
  // (une carte de visite n'en a pas).
  if (b.type !== 'formule' && b.type !== 'visite') return '';
  if (b.type === 'formule' && !b.formuleId) return '';
  const toutes = (Array.isArray(formulaComplements) ? formulaComplements : [])
    .filter(card => card && card.id && (card.kind !== 'formule' || card.formuleId !== b.formuleId));
  // DEUX BESOINS, DEUX BLOCS. « Envie d un peu plus ? » propose un supplement ;
  // l offre d attente repond a une contrainte du plan (un sous-groupe attend
  // son tour pendant que l autre joue). Les melanger ferait lire la seconde
  // comme une vente de plus.
  const cartesAttente = toutes.filter(card => card.kind === 'attente');
  const cards = toutes.filter(card => card.kind !== 'attente');
  const notice = formulaComplementNotice || { text: '', tone: '' };
  // Plus aucune carte mais une phrase a dire : le bloc reste, sinon la reponse
  // au clic (« ajoutee », « plus disponible ») disparaitrait au rendu suivant.
  if (!cards.length && !cartesAttente.length && !notice.text) return '';
  const carteHtml = (card) => `
        <div class="complement-card">
          <span class="complement-copy">
            <strong class="complement-name">${escapeHtml(card.name || '')}</strong>
            <small class="complement-adds">${escapeHtml(card.addsLabel || '')}</small>
            ${card.totalLabel ? `<small class="complement-total">${escapeHtml(card.totalLabel)}</small>` : ''}
            ${card.noteLabel ? `<small class="complement-note">${escapeHtml(card.noteLabel)}</small>` : ''}
          </span>
          <span class="complement-amount">${escapeHtml(card.amountLabel || '')}</span>
          <button type="button" class="btn-secondary complement-add"
            data-complement="${escapeHtml(card.id)}"
            onclick="accepterComplement(this.dataset.complement)"
            aria-label="Ajouter ${escapeHtml(card.name || '')}, ${escapeHtml(card.amountLabel || '')}${card.totalLabel ? `, ${escapeHtml(card.totalLabel)}` : ''}${card.noteLabel ? `, ${escapeHtml(card.noteLabel)}` : ''}">Ajouter</button>
        </div>`;
  return `
    <div class="recap-complements" id="recapComplements" tabindex="-1">
      ${cartesAttente.length ? `<div class="recap-attente">
        <div class="recap-complements-head">
          <strong>Un groupe attend son tour</strong>
          <small>${escapeHtml(texteAttente())}</small>
        </div>
        ${cartesAttente.map(carteHtml).join('')}
      </div>` : ''}
      ${cards.length ? `<div class="recap-complements-head">
        <strong>Envie d'un peu plus ?</strong>
        <small>Vos heures retenues ne bougent pas.</small>
      </div>` : ''}
      ${cards.map(carteHtml).join('')}
      <div class="complement-status" id="complementStatus" role="status" aria-live="polite"
        data-tone="${escapeHtml(notice.tone || '')}">${escapeHtml(notice.text || '')}</div>
    </div>`;
}

// La phrase vit dans `formulaComplementNotice` et le DOM n'en est que le reflet :
// ecrite dans le seul noeud, elle serait effacee par le renderRecap qui suit.
function setComplementStatus(text, tone = '') {
  formulaComplementNotice = { text: text || '', tone: tone || '' };
  const zone = document.getElementById('complementStatus');
  if (!zone) return;
  zone.textContent = formulaComplementNotice.text;
  zone.dataset.tone = formulaComplementNotice.tone;
}

// REPONDRE AU CLIC SANS FAIRE PERDRE SA PLACE NI SON INFORMATION.
//
// renderRecap reconstruit #recapList par innerHTML : le bouton qui portait le
// focus disparait (mesure : focus sur « Ajouter », touche Entree, puis
// document.activeElement = BODY - un utilisateur clavier devait re-tabuler tout
// le recapitulatif pour atteindre « Confirmer la réservation »), et la region
// role="status" est RECREEE avec son texte deja dedans, ce qu'aucun lecteur
// d'ecran ne restitue : seule la MUTATION d'une region deja presente est
// annoncee.
//
// On rend donc, on repose le focus sur un point stable, puis on vide et
// re-remplit la region : la phrase devient une mutation, donc une annonce.
function renderRecapWithComplementStatus(text, tone = '') {
  formulaComplementNotice = { text: text || '', tone: tone || '' };
  renderRecap();
  const cible = document.getElementById('recapComplements') || document.getElementById('btnConfirmBooking');
  if (cible && typeof cible.focus === 'function') {
    try { cible.focus({ preventScroll: true }); } catch (error) { cible.focus(); }
  }
  const zone = document.getElementById('complementStatus');
  if (!zone || !formulaComplementNotice.text) return;
  zone.textContent = '';
  setTimeout(() => {
    const encore = document.getElementById('complementStatus');
    if (encore) encore.textContent = (formulaComplementNotice && formulaComplementNotice.text) || '';
  }, 80);
}

// LES CARTES D'UNE FORMULE SANS ANCRE SE DEMANDENT AU MOMENT DU CHOIX.
//
// Une formule « pass liberté » (table anniversaire, fenêtre ouverte) n'impose
// aucune heure : le client choisit son heure d'ARRIVÉE dans la liste, et rien
// avant ce clic ne dit laquelle. Le serveur ne peut donc pas juger la
// faisabilité d'une montée sur cette famille avant de connaître le créneau
// retenu, et il refuse de le deviner : on le lui donne ici, une fois, avec
// `retainedTime`. Sans cette requête, f6 vers f7 (+6 € par personne pour un
// Minigolf Blacklight) était structurellement invisible.
//
// Fail-soft : sans réponse, le récapitulatif est exactement celui d'avant.
let complementFetchId = 0;
async function refreshFormulaComplements() {
  const b = state.booking;
  if (b.type !== 'formule' || !b.formuleId || !b.startTime) return;
  const ticket = ++complementFetchId;
  try {
    const params = new URLSearchParams({
      date: b.date,
      type: 'formule',
      pax: String(Number(b.pax) || 1),
      centerId: String(typeof getTunnelCenterId === 'function' ? getTunnelCenterId() : 'libramont'),
      formuleId: String(b.formuleId),
      retainedTime: String(b.startTime)
    });
    const payload = await apiRequest(`${API_ENDPOINTS.publicAvailability || '/api/public-availability'}?${params.toString()}`, {
      method: 'GET'
    });
    if (ticket !== complementFetchId) return;
    formulaComplements = Array.isArray(payload.complements) ? payload.complements : [];
    state.booking.serverPrice = Number(payload.price) || state.booking.serverPrice || 0;
    if (formulaComplements.length && document.getElementById('recapList')) renderRecap();
  } catch (error) {
    if (ticket !== complementFetchId) return;
    formulaComplements = [];
  }
}

// UN SEUL BOUTON POUR LES TROIS GENERATEURS.
//
// La carte dit ce qu'elle EST (`kind`) et ce qu'il faut appliquer (`formuleId`
// pour une montée de formule, `patch` pour une visite) : le bouton n'a donc
// qu'un seul attribut, l'identité de la carte, et un générateur de plus
// n'ajoute rien au DOM. Une carte inconnue ne fait rien du tout : c'est le cas
// d'un rendu qui aurait survécu à un changement de créneau.
function accepterComplement(idCarte) {
  const carte = (formulaComplements || []).find(item => item && item.id === String(idCarte || ''));
  if (!carte) return Promise.resolve();
  if (carte.kind === 'formule') return acceptFormulaComplement(carte.formuleId);
  return accepterComplementVisite(carte);
}

// ACCEPTER UN COMPLEMENT DE VISITE, C'EST CHANGER UNE LIGNE DU PANIER.
//
// Le serveur a déjà dérivé les options de la ligne du CATALOGUE (durée, palier
// de session, nombre de parties) : le navigateur ne devine rien, il applique le
// `patch` de la carte sur une COPIE du panier. Le panier du dossier n'est
// touché qu'après un aller-retour serveur réussi, sinon un refus laisserait le
// client avec une visite qu'il n'a pas choisie et que la confirmation
// facturerait.
//
// LE PROGRAMME VERIFIE EST CELUI QUE LA CONFIRMATION ENVERRA : les deux passent
// par buildBookingProgramPayload, l'un avec le panier candidat, l'autre avec le
// panier adopté. Aucun second chemin ne peut donc composer une visite
// différente de celle dont le prix vient d'être accepté.
async function accepterComplementVisite(carte) {
  const b = state.booking;
  const cible = carte && carte.patch && carte.patch.activityId ? String(carte.patch.activityId) : '';
  if (!cible || formulaComplementBusy || b.type !== 'visite' || !b.startTime) return;

  // Une carte morte se retire ET dit pourquoi : la laisser inviterait à un
  // second clic qui échouerait pareil. LA VISITE, elle, ne bouge pas.
  const renoncer = (raison) => {
    formulaComplements = (formulaComplements || []).filter(item => item && item.id !== carte.id);
    renderRecapWithComplementStatus(raison || 'Cette option n\'est plus disponible.', 'ko');
  };

  formulaComplementBusy = carte.id;
  const bouton = document.querySelector(`#recapComplements .complement-add[data-complement="${String(carte.id).replace(/"/g, '')}"]`);
  if (bouton) bouton.disabled = true;
  setComplementStatus('Vérification en cours…', 'busy');

  try {
    const panierCourant = b.activities && typeof b.activities === 'object' ? b.activities : {};
    const panierCandidat = { ...panierCourant };
    panierCandidat[cible] = { ...(panierCourant[cible] || {}), ...(carte.patch.options || {}) };

    const params = new URLSearchParams({
      date: b.date,
      type: 'visite',
      pax: String(Number(b.pax) || 1),
      centerId: String(typeof getTunnelCenterId === 'function' ? getTunnelCenterId() : 'libramont'),
      program: JSON.stringify(buildBookingProgramPayload(panierCandidat))
    });
    // EXACTEMENT les heures déjà retenues : ce lot ne décale rien.
    const preference = createDefaultFormulaPreference(b.preference || {});
    const heuresChoisies = {};
    if (preference.preferredTimes.bowling) heuresChoisies.bowling = preference.preferredTimes.bowling;
    if (preference.preferredTimes.laser_game) heuresChoisies.laser_game = preference.preferredTimes.laser_game;
    if (Object.keys(heuresChoisies).length) params.set('preferredTimes', JSON.stringify(heuresChoisies));
    setLaserPartTimesParam(params, preference);

    const reponse = await apiRequest(`${API_ENDPOINTS.publicAvailability || '/api/public-availability'}?${params.toString()}`, {
      method: 'GET'
    });
    const creneau = (reponse.slots || []).find(item => item && item.time === b.startTime) || null;
    if (!creneau) {
      renoncer(reponse.message || '');
      return;
    }
    // LA VISITE NE BOUGE PAS : mêmes pistes, mêmes heures d'ancres que ce que le
    // client a validé. Un écart ici serait un déplacement silencieux, donc un
    // refus, pas une adoption.
    const memesPistes = JSON.stringify(Array.isArray(creneau.lanes) ? creneau.lanes : [])
      === JSON.stringify(Array.isArray(b.allocatedLanes) ? b.allocatedLanes : []);
    const heuresRendues = creneau.opsPlan?.anchorPlan?.times || {};
    const memesHeures = Object.keys(heuresChoisies).every(cle => heuresRendues[cle] === heuresChoisies[cle]);
    if (!memesPistes || !memesHeures) {
      renoncer('Cette option déplacerait votre créneau.');
      return;
    }
    // LA VISITE DURE PLUS LONGTEMPS : elle doit encore tenir dans la journée.
    // Sans ce contrôle, une option acceptée en fin de soirée renvoyait le client
    // à l'écran des créneaux au moment de confirmer, sans qu'il comprenne
    // pourquoi (confirmBooking rejoue la même règle, et elle, elle est dure).
    const nouveauTotal = Number(reponse.totalDuration || reponse.duration || 0);
    const fenetre = validateSlotWindow(b.date, b.startTime, nouveauTotal);
    if (!fenetre.ok) {
      renoncer(fenetre.message || '');
      return;
    }
    // LE MONTANT PROMIS EST-IL ENCORE CELUI DU SERVEUR ? La réponse porte
    // `price`, le prix AUTORITAIRE du programme, recalculé à l'instant ligne par
    // ligne. La carte, elle, a été chiffrée lors d'une requête antérieure : un
    // tarif d'activité enregistré depuis la console entre les deux (TTL 30 s) a
    // pu bouger. On ne facture jamais plus que ce qu'on a promis.
    const ecartServeur = Math.round(((Number(reponse.price) || 0) - (Number(b.serverPrice) || 0)) * 100) / 100;
    if (ecartServeur > (Number(carte.deltaTotal) || 0) + 0.001) {
      renoncer('Le tarif de cette option vient de changer.');
      return;
    }
    // UNE OFFRE D ATTENTE N EST ACQUISE QUE POSEE PAR LE SERVEUR : sa ligne
    // revient marquee, au tarif d attente. Sinon (le groupe ne tourne plus,
    // l offre a quitte le centre), la carte se retire : jamais « ajouté » sur
    // une ligne que le serveur n a pas faite.
    const lignesRendues = reponse.program && Array.isArray(reponse.program.items) ? reponse.program.items : [];
    if (carte.kind === 'attente' && !lignesRendues.some(item => item && item.waitOffer === true && item.activityId === cible)) {
      renoncer('Cette offre n\'est plus disponible.');
      return;
    }

    // ADOPTE. Le panier du dossier devient le panier candidat : c'est lui que
    // confirmBooking enverra (buildBookingProgramPayload le relit). Le TYPE ne se
    // recalcule pas : un complément n'enlève jamais rien du panier, donc une
    // visite reste une visite.
    b.activities = panierCandidat;
    b.serverProgram = reponse.program && Array.isArray(reponse.program.items) ? reponse.program : b.serverProgram;
    // Le prix qui vient d'être appliqué devient la nouvelle référence : un second
    // complément se confronterait sinon au prix d'avant le premier.
    b.serverPrice = Number(reponse.price) || 0;
    b.laneCount = Number(reponse.laneCount || 0);
    b.duration = Number(reponse.duration || b.duration || 0);
    b.totalDuration = Number(reponse.totalDuration || reponse.duration || b.totalDuration || 0);
    b.opsPlan = creneau.opsPlan || b.opsPlan;
    formulaAnchorData = reponse.anchors || formulaAnchorData;
    formulaComplements = Array.isArray(reponse.complements) ? reponse.complements : [];
    state.availableSlots = [creneau];
    save();
    renderRecapWithComplementStatus(`${carte.name} ajouté : ${carte.amountLabel}.`, 'ok');
  } catch (error) {
    renoncer(error && error.message ? error.message : '');
  } finally {
    formulaComplementBusy = '';
  }
}

// ACCEPTER, C'EST ECHANGER UN IDENTIFIANT DE FORMULE. Rien d'autre : ni
// program, ni extras, ni champ nouveau. Toucher `program` effacerait la formule
// (mesure connue : f8 tombait de 112 à 79 €).
//
// Et l'échange repasse OBLIGATOIREMENT par la porte serveur, celle-là même qui
// a produit le créneau retenu : une carte affichée il y a trente secondes peut
// être morte (groupe entre-temps, formule bloquée, vacances). Refusée, RIEN ne
// change dans la réservation et le client lit la raison courte du moteur.
async function acceptFormulaComplement(formuleId) {
  const b = state.booking;
  const wanted = String(formuleId || '');
  const card = (formulaComplements || []).find(item => item && item.formuleId === wanted);
  if (!card || formulaComplementBusy || b.type !== 'formule' || !b.startTime) return;

  // Une carte morte se retire ET dit pourquoi : la laisser inviterait a un
  // second clic qui echouerait pareil. La RESERVATION, elle, ne bouge pas.
  const oublier = (raison) => {
    formulaComplements = (formulaComplements || []).filter(item => item && item.formuleId !== wanted);
    renderRecapWithComplementStatus(raison || 'Cette option n\'est plus disponible.', 'ko');
  };

  formulaComplementBusy = wanted;
  const button = document.querySelector(`#recapComplements .complement-add[data-complement="${wanted.replace(/"/g, '')}"]`);
  if (button) button.disabled = true;
  setComplementStatus('Vérification en cours…', 'busy');

  try {
    const params = new URLSearchParams({
      date: b.date,
      type: 'formule',
      pax: String(Number(b.pax) || 1),
      centerId: String(typeof getTunnelCenterId === 'function' ? getTunnelCenterId() : 'libramont'),
      formuleId: wanted
    });
    // EXACTEMENT les heures déjà retenues : ce lot ne décale rien.
    const preference = createDefaultFormulaPreference(b.preference || {});
    const chosenTimes = {};
    if (preference.preferredTimes.bowling) chosenTimes.bowling = preference.preferredTimes.bowling;
    if (preference.preferredTimes.laser_game && preference.laserPlacement !== 'onsite') {
      chosenTimes.laser_game = preference.preferredTimes.laser_game;
    }
    if (Object.keys(chosenTimes).length) params.set('preferredTimes', JSON.stringify(chosenTimes));
    if (preference.laserPlacement === 'onsite') params.set('laserPlacement', 'onsite');
    else setLaserPartTimesParam(params, preference);

    const payload = await apiRequest(`${API_ENDPOINTS.publicAvailability || '/api/public-availability'}?${params.toString()}`, {
      method: 'GET'
    });
    const slot = (payload.slots || []).find(item => item && item.time === b.startTime) || null;
    if (!slot) {
      oublier(payload.message || '');
      return;
    }
    // LA VISITE NE BOUGE PAS : mêmes pistes, mêmes heures d'ancres que ce que
    // le client a validé. Un écart ici serait un déplacement silencieux, donc
    // un refus, pas une adoption.
    const memesPistes = JSON.stringify(Array.isArray(slot.lanes) ? slot.lanes : [])
      === JSON.stringify(Array.isArray(b.allocatedLanes) ? b.allocatedLanes : []);
    const heuresRendues = slot.opsPlan?.anchorPlan?.times || {};
    const memesHeures = Object.keys(chosenTimes).every(key => heuresRendues[key] === chosenTimes[key]);
    if (!memesPistes || !memesHeures) {
      oublier('Cette option déplacerait votre créneau.');
      return;
    }

    // LE MONTANT PROMIS EST-IL ENCORE CELUI DU SERVEUR ? La réponse porte
    // `price`, le prix AUTORITAIRE de la formule montée, calculé à l'instant.
    // La carte, elle, a été chiffrée lors d'une requête antérieure : entre les
    // deux, un override de catalogue enregistré depuis la console (TTL 30 s) a
    // pu déplacer le tarif. On ne facture jamais plus que ce qu'on a promis :
    // au-delà, la carte s'oublie et le client lit pourquoi.
    const deltaServeur = Math.round(((Number(payload.price) || 0) - (Number(b.serverPrice) || 0)) * 100) / 100;
    if (deltaServeur > (Number(card.deltaTotal) || 0) + 0.001) {
      oublier('Le tarif de cette option vient de changer.');
      return;
    }

    b.formuleId = wanted;
    // La réponse serveur fait autorité sur le nombre de pistes, Y COMPRIS quand
    // elle dit zéro : `|| b.laneCount` laissait des pistes fantômes au
    // récapitulatif d'une candidate qui n'en demande aucune, et laneCount entre
    // directement dans le prix d'une formule per_lane côté client. Même lecture
    // que fetchSlots, sur la même réponse et le même champ.
    b.laneCount = Number(payload.laneCount || 0);
    b.duration = Number(payload.duration || b.duration || 0);
    b.totalDuration = Number(payload.totalDuration || payload.duration || b.totalDuration || 0);
    // Le prix qui vient d'être appliqué devient la nouvelle référence : une
    // seconde montée se confronterait sinon au prix d'avant la première.
    b.serverPrice = Number(payload.price) || 0;
    b.opsPlan = slot.opsPlan || b.opsPlan;
    // Le pass liberté et les rendez-vous du récap se lisent dans le bloc
    // `anchors` du serveur : sans cette ligne, le récapitulatif continuerait de
    // décrire le contenu de l'ancienne formule.
    formulaAnchorData = payload.anchors || formulaAnchorData;
    formulaComplements = Array.isArray(payload.complements) ? payload.complements : [];
    state.availableSlots = [slot];
    save();
    renderRecapWithComplementStatus(`${card.name} ajoutée : ${card.amountLabel}.`, 'ok');
  } catch (error) {
    oublier(error && error.message ? error.message : '');
  } finally {
    formulaComplementBusy = '';
  }
}

// Une ligne du programme SERVEUR dans le recap final : nom, choix effectif et
// prix de cette ligne. Les options affichent ce qui sera reserve, jamais une
// valeur reconstruite depuis le libelle global de la reservation.
function renderVisitRecapItem(item) {
  const activityId = String(item?.activityId || '');
  let detail = '';
  if (activityId === 'bowling') {
    const option = DURATION_OPTIONS.find(entry => Number(entry.value) === Number(item.duration));
    const lanes = Math.max(1, Number(item.laneCount) || 1);
    detail = `${option?.label || `${Number(item.duration) || 1}h`} · ${lanes} piste${lanes > 1 ? 's' : ''}`;
  } else if (activityId === 'laser_game') {
    const games = Math.max(1, Number(item.games) || 1);
    detail = `${games} partie${games > 1 ? 's' : ''}${item.extraLaser ? ` + ${item.extraLaser.games - games} pour ${item.extraLaser.participants} joueurs` : ''}`;
  } else if (item.priceType === 'grid_bowling' || item.units != null || item.hours != null) {
    // Tables de billard, pistes de duckpin : leur nombre, la duree, les tours.
    // La MEME phrase que la fiche du staff (detailLigneProgramme).
    detail = detailLigneProgramme(item);
  } else if (item.dayAccess) {
    // Une entree a la journee (la plaine de jeux) : ses minutes ne sont qu une
    // estimation du planning, jamais ce que le client achete (2026-09-25).
    detail = 'Accès toute la journée';
  } else if (item.minutes) {
    detail = formatDurationLabel(Number(item.minutes) / 60);
  } else {
    detail = item.priceKnown === true ? 'Compris dans le total' : 'À régler sur place';
  }
  const remise = Number((item.extraLaser || item.upsell)?.discountAmount);
  if (remise > 0) detail += ` · remise ${formatMoneyCentimes(remise)}`;
  const price = item.priceKnown === true && Number.isFinite(Number(item.price))
    ? formatMoneyCentimes(item.price)
    : 'Sur place';
  return `<div class="recap-program-item">
    <span class="recap-program-copy">
      <strong class="recap-program-name">${escapeHtml(item.name || activityId)}</strong>
      <small class="recap-program-detail">${escapeHtml(detail)}</small>
    </span>
    <span class="recap-program-price">${escapeHtml(price)}</span>
  </div>`;
}

// LE SITE HOTE APPREND QU UNE RESERVATION VIENT D ETRE PRISE (2026-09-05).
// Dans l iframe, GA4, GTM et le Pixel Meta du site du centre ne voient rien de
// ce qui se passe ici : sans ce signal, poser le formulaire coupe la mesure des
// conversions que l agence du client suivait sur son ancien formulaire (Fun
// Galaxy compte ses demandes par un evenement Meta sur son formulaire actuel).
// Le detail ne porte AUCUNE donnee personnelle : des identifiants, un montant,
// une date, un centre. Le canal (origine cible, mode embarque seulement) est
// celui de pinlane:height, expose par la fermeture du mode embarque en fin de
// fichier ; hors iframe il n existe pas, et rien ne part.
function signalerReservationAuSite(reservation, ops) {
  if (!reservation || typeof window.pinlanePosterAuSite !== 'function') return;
  window.pinlanePosterAuSite('pinlane:booking', {
    reservationId: reservation.id != null ? String(reservation.id) : '',
    center: getTunnelCenterId() || '',
    amount: Number(reservation.price) || 0,
    currency: 'EUR',
    pax: Number(reservation.pax) || 0,
    date: String(reservation.date || ''),
    startTime: String(reservation.startTime || ''),
    type: String(reservation.type || ''),
    formuleId: String(reservation.formuleId || ''),
    label: String(reservation.label || ''),
    status: ops && ops.validationStatus === 'staff_review' ? 'received' : 'confirmed',
  });
}

async function confirmBooking() {
  if (bookingSubmitBusy) return;
  bookingSubmitBusy = true;
  setBookingSubmitBusy(true);

  const b = state.booking;
  const formule = b.type === 'formule' ? resolveDisplayFormule(b.formuleId) : null;
  const duration = Number(b.duration);
  const totalDuration = getBookingTotalDuration(b);
  const needsLanes = reservationNeedsLanes(b.type, b.formuleId);
  const laneCount = b.bowlingCapacity?.emergency && Array.isArray(b.allocatedLanes) && b.allocatedLanes.length ? b.allocatedLanes.length : getRequiredLaneCount(b.type, b.pax, b.formuleId);

  const releaseBookingSubmit = () => {
    bookingSubmitBusy = false;
    setBookingSubmitBusy(false);
  };

  const slotCheck = validateSlotWindow(b.date, b.startTime, totalDuration);
  if (!slotCheck.ok) {
    goStep(2, { alert: slotCheck.message });
    await fetchSlots({ showLoading: true });
    releaseBookingSubmit();
    return;
  }

  if (formule) {
    const availability = getFormuleAvailability(formule, b.date, Number(b.pax), b.startTime);
    if (!availability.ok) {
      goStep(2, { alert: availability.message });
      await fetchSlots({ showLoading: true });
      releaseBookingSubmit();
      return;
    }
  }

  let allocated = Array.isArray(b.allocatedLanes) ? [...b.allocatedLanes] : [];
  if (needsLanes) {
    const stillFree =
      b.opsPlan ||
      allocated.length === laneCount &&
      !lanesConflict(b.date, b.startTime, duration, allocated).length &&
      allocated.every(l => state.laneStatuses[l] !== 'maintenance');
    if (!stillFree) allocated = allocateLanes(laneCount, b.date, b.startTime, duration);
    if (!allocated) {
      goStep(2, { alert: "Le créneau vient d'être pris. Merci de choisir un autre horaire." });
      await fetchSlots({ showLoading: true });
      releaseBookingSubmit();
      return;
    }
  } else {
    allocated = [];
  }

  const isVisit = b.type === 'visite';
  // Le prix affiche reste indicatif : le serveur recalcule TOUT (grilles bowling
  // et laser, tarifs de centre des activites libres) et c'est son montant qui
  // est enregistre. On envoie le notre pour ne pas casser le payload historique.
  const basePrice = isVisit
    ? 0
    : getBasePrice(b.type, duration, needsLanes ? allocated.length : 0, Number(b.pax), b.formuleId, b.date);
  const reservation = {
    name: b.name,
    phone: b.phone,
    email: b.email,
    date: b.date,
    startTime: b.startTime,
    duration,
    totalDuration,
    lanes: allocated,
    pax: Number(b.pax),
    status: 'pending',
    basePrice,
    price: basePrice,
    type: b.type,
    formuleId: b.formuleId,
    label: formule ? formule.name : b.type === 'laser' ? 'Laser Game' : 'Bowling Classique',
    laserGames: b.type === 'laser' ? getLaserGameCount(b.duration) : 0,
    // Programme de la visite. Absent pour une reservation mono-activite : le
    // payload est alors strictement celui d'avant.
    ...(isVisit ? { program: buildBookingProgramPayload() } : {}),
    preference: b.preference || {},
    pauseMinutes: 0,
    opsPlan: b.opsPlan || null,
    // Champs ADDITIFS optionnels : occasion déclarée + demande particulière. Le
    // texte libre de l'occasion « Autre » est joint aux notes (l'enum serveur ne
    // stocke que la clé) pour rester lisible côté direction.
    occasion: b.occasion || '',
    notes: [
      (b.occasion === 'autre' && b.occasionOther) ? `Occasion : ${b.occasionOther}` : '',
      b.specialRequest || ''
    ].filter(Boolean).join('. '),
    extras: []
  };

  let dossierCree = null;
  try {
    const payload = await apiRequest(API_ENDPOINTS.publicReservations, {
      method: 'POST',
      body: JSON.stringify(buildReservationApiPayload(reservation, {
        channel: 'public',
        laneCount,
        requiresLanes: needsLanes
      }))
    });
    upsertReservationInState(payload.reservation);
    dossierCree = payload.reservation;
    save();
    allocated = payload.reservation.lanes || allocated;
    state.booking.opsResult = payload.ops || null;
    clearBookingAlternatives();
  } catch (error) {
    goStep(2);
    await fetchSlots({ showLoading: true });
    if (error.payload?.alternatives?.length) {
      showBookingAlternatives(error.message || 'Ce créneau ne tient plus.', error.payload.alternatives);
    } else {
      showAlert(error.message || 'Impossible d’enregistrer la réservation.');
    }
    releaseBookingSubmit();
    return;
  }

  document.getElementById('successName').textContent = b.name.split(' ')[0];
  // LE PARCOURS SE TERMINE COMME IL A COMMENCE : par une phrase qui s ecrit.
  // Chaque ecran du tunnel pose sa question mot a mot ; la derniere ligne,
  // celle qui annonce que c est pris, apparaissait d un bloc. Movsar :
  // "plus d animation vers la fin du programme".
  const titreFinal = document.querySelector('#step5 .success-wrap h2');
  if (titreFinal && typeof revelerQuestion === 'function') revelerQuestion(titreFinal);
  const showLanes = reservationNeedsLanes(b.type, b.formuleId);
  const isLaser = b.type === 'laser';
  document.getElementById('successHint').style.display = 'block';
  const confirmationText = state.booking.opsResult?.validationStatus === 'staff_review'
    ? 'Votre demande est reçue. On revient vers vous après vérification du scénario.'
    : 'Votre réservation est enregistrée. Le mail de confirmation arrive dans quelques minutes.';
  const laserWaveCount = isLaser ? Number(b.opsPlan?.laserSharing?.waveCount || getLaserWaveCount(b.pax)) : 1;
  const laserLine = isLaser && laserWaveCount > 1 ? ` Votre groupe est réparti sur ${laserWaveCount} sessions Laser.` : '';
  const arrivalLine = b.type === 'formule' && b.opsPlan?.arrivalTime
    ? (avanceDArrivee(b.opsPlan) > 0 ? ` Présentez-vous <b>${avanceDArrivee(b.opsPlan)} minutes avant</b> pour l'accueil (arrivée conseillée <b>${escapeHtml(b.opsPlan.arrivalTime)}</b>).` : ` Présentez-vous à <b>${escapeHtml(b.opsPlan.arrivalTime)}</b>, l'heure de votre première activité.`)
    : '';
  const successRecap = b.type === 'formule' ? getFormulaRecapModel(b) : null;
  const appointmentsLine = successRecap && successRecap.appointments.length
    ? ` Vos rendez-vous : <b>${successRecap.appointments.map(escapeHtml).join(' · ')}</b>.`
    : '';
  const tableLine = successRecap && successRecap.hasTable
    ? ` Table prête à votre arrivée${successRecap.arrivalTime ? ` (<b>${escapeHtml(successRecap.arrivalTime)}</b>)` : ''}.`
    : '';
  const freeLine = successRecap && successRecap.freeLabels.length
    ? ` En accès libre : ${successRecap.freeLabels.map(escapeHtml).join(', ')}.`
    : '';
  document.getElementById('successDetails').innerHTML = `${confirmationText} ${b.type === 'formule' ? 'Première activité' : 'Départ prévu'} à <b>${typeof displayTime === 'function' ? displayTime(b.startTime) : b.startTime}</b>${showLanes && allocated.length ? ` sur la/les piste(s) <b>${allocated.join(' & ')}</b>` : ''}.${appointmentsLine}${tableLine}${arrivalLine}${freeLine} Temps total estimé : <b>${formatDurationLabel(totalDuration)}</b>.${laserLine}`;
  signalerReservationAuSite(dossierCree, state.booking.opsResult);
  releaseBookingSubmit();
  await sealBookingSubmit();
  goStep(5);
}

function resetBooking() {
  clearBookingAlternatives();
  // Les montees de formule appartiennent au dossier qu on vient de confirmer :
  // elles ne suivent pas le client dans sa reservation suivante.
  formulaComplements = [];
  formulaComplementNotice = { text: '', tone: '' };
  // Le bouton Confirmer garde son sceau (disque + coche) tant qu on ne le
  // relache pas : « Faire une autre reservation » est la seule sortie de
  // l ecran de succes, donc l endroit ou le sceau doit tomber.
  setBookingSubmitBusy(false);
  // On garde la date que le client venait de choisir si elle est encore
  // reservable, sinon la prochaine date ouverte. Jamais aujourd hui en dur :
  // firstBookableDate lit le planning editable du centre.
  const nextBookableDate = firstBookableDate(state.booking && state.booking.date, state.isHolidayMode);
  state.booking = {
    name:'', phone:'', email:'', pax:4,
    date: nextBookableDate,
    type:'bowling', formuleId:'', duration:1, totalDuration:1, laneCount:1, startTime:'', allocatedLanes:[],
    serverProgram: null,
    preference: createDefaultFormulaPreference(),
    pauseMinutes: 0,
    occasion: '',
    occasionOther: '',
    specialRequest: '',
    opsPlan: null,
    opsResult: null
  };
  document.getElementById('fName').value = '';
  document.getElementById('fPhone').value = '';
  document.getElementById('fEmail').value = '';
  document.getElementById('fPax').value = 4;
  document.getElementById('fDate').value = nextBookableDate;
  const specialRequestInput = document.getElementById('fSpecialRequest');
  if (specialRequestInput) specialRequestInput.value = '';
  setBookingOccasion('');
  setType('bowling');
  renderDurations();
  updatePaxAlert();
  updateSchedHint();
  renderFormulaPreferences();
  goStep(1);
  save();
}

