// LES PARAMETRES DU POSTE (2026-09-25). La page etait une maquette : trois
// blocs sans style (« InterfaceThème Clair » colle, boutons bruts du
// navigateur) et un bloc « Ops » qui chargeait de la plomberie interne. Restent
// les trois reglages qu un gerant utilise vraiment, chacun dit ce qu il fait.
function renderStaffUtilitySettings() {
  const light = state.staffTheme === 'light';
  const count = getStaffUtilityReservations().length;
  const day = parseLocalDate(state.currentDate).toLocaleDateString('fr-BE', { weekday: 'long', day: 'numeric', month: 'long' });
  return `<div class="settings-list">
    <div class="settings-row">
      <div class="settings-copy">
        <h2>Apparence</h2>
        <p>Le thème de la console sur ce poste. Les autres postes gardent le leur.</p>
      </div>
      <div class="settings-seg" role="group" aria-label="Thème de la console">
        <button type="button" aria-pressed="${light ? 'true' : 'false'}" class="${light ? 'is-on' : ''}" onclick="setStaffTheme('light')">Clair</button>
        <button type="button" aria-pressed="${light ? 'false' : 'true'}" class="${light ? '' : 'is-on'}" onclick="setStaffTheme('dark')">Sombre</button>
      </div>
    </div>
    <div class="settings-row">
      <div class="settings-copy">
        <h2>Export du planning</h2>
        <p>${escapeHtml(formatStaffTerrainCount(count, 'réservation'))} le ${escapeHtml(day)}, dans un fichier tableur (CSV) : heure, client, téléphone, offre, joueurs, pistes, statut et montant.</p>
      </div>
      <button type="button" class="utility-action" onclick="exportStaffPlanningCsv('day')"${count ? '' : ' disabled'}>Exporter en CSV</button>
    </div>
    <div class="settings-row">
      <div class="settings-copy">
        <h2>Données</h2>
        <p>La console se synchronise toute seule toutes les quelques secondes. Ce bouton force un rechargement immédiat depuis le serveur.</p>
      </div>
      <button type="button" class="utility-action" onclick="refreshStaffPlanning()">Actualiser</button>
    </div>
  </div>`;
}

function getStaffUtilityPageModel(page = getStaffMenuPage()) {
  const reservations = getStaffUtilityReservations();
  // Pas de bouton secondaire par defaut : « Voir planning » s affichait sur
  // chaque page, doublon de la barre laterale, et ouvrait meme les
  // Reservations depuis Formules. Une page qui a une vraie deuxieme action
  // la declare.
  const base = {
    page,
    layout: 'default',
    eyebrow: 'Journée',
    title: 'Espace staff',
    subtitle: getStaffUtilitySyncLabel(),
    primaryLabel: 'Réservation rapide',
    primaryAction: "openQuickBook({ date: state.currentDate, type: 'bowling' })",
    secondaryLabel: '',
    secondaryAction: '',
    kpis: [],
    body: ''
  };
  if (page === 'formules') {
    const formuleRows = reservations.filter(reservation => reservation.type === 'formule' || reservation.formuleId);
    const totals = formuleRows.filter(reservationHasFormulaActivities).reduce((acc, reservation) => {
      const summary = getFormulaActivityProgressSummary(reservation);
      acc.done += summary.done;
      acc.total += summary.total;
      return acc;
    }, { done: 0, total: 0 });
    const players = formuleRows.reduce((sum, reservation) => sum + Number(reservation.pax || 0), 0);
    // Le sous-titre dit la journee en une ligne. Il ne dit plus a quoi sert la
    // page (« Cochez chaque activité au fur et à mesure... ») : les cases le
    // disent d elles-memes. « 0/8 activités faite » : le pluriel suivait le
    // nombre de coches, pas le nombre d activites qu il qualifie ; les deux
    // accords s indexent sur le meme mot. Le compte n est plus ecrit deux fois
    // (en-tete de panneau et tete de groupe) : chaque groupe dit le sien.
    const summary = formuleRows.length ? [
      formatStaffTerrainCount(formuleRows.length, 'formule'),
      formatStaffTerrainCount(players, 'joueur'),
      totals.total ? `${totals.done}/${totals.total} activité${totals.total > 1 ? 's' : ''} cochée${totals.total > 1 ? 's' : ''}` : ''
    ].filter(Boolean).join(' · ') : '';
    return {
      ...base,
      layout: 'events',
      eyebrow: 'Journée',
      // Le titre est celui de la barre laterale : une entree « Formules » qui
      // ouvre « Formules, suivi des activités » faisait croire a une autre page.
      title: 'Formules',
      subtitle: [getStaffUtilitySyncLabel(), summary].filter(Boolean).join(' · '),
      hidePanelHead: true,
      primaryLabel: 'Nouvelle formule',
      primaryAction: "openQuickBook({ date: state.currentDate, type: 'formule' })",
      body: renderStaffFormulesBoard(formuleRows)
    };
  }
  // Arrivees, En cours et Evenements ne font plus qu une page (voir
  // getStaffTerrainBoard) ; les anciennes adresses y menent par
  // STAFF_PAGE_ALIASES.
  if (page === 'arrivals') {
    const board = getStaffTerrainBoard(reservations);
    const players = reservations.reduce((sum, reservation) => sum + Number(reservation.pax || 0), 0);
    const doneCount = board.done.length;
    const summary = reservations.length ? [
      formatStaffTerrainCount(reservations.length, 'réservation'),
      formatStaffTerrainCount(players, 'joueur'),
      doneCount ? `${doneCount} terminée${doneCount > 1 ? 's' : ''} et payée${doneCount > 1 ? 's' : ''}` : ''
    ].filter(Boolean).join(' · ') : '';
    return {
      ...base,
      layout: 'terrain',
      eyebrow: 'Journée',
      title: 'Terrain',
      subtitle: [getStaffUtilitySyncLabel(), summary].filter(Boolean).join(' · '),
      hidePanelHead: true,
      body: renderStaffTerrainBoard(board)
    };
  }
  // Plus de branche « groups » : la page a disparu le 2026-07-13 (fusion
  // Clients+Groupes), tous ses chemins d'accès sont aliasés vers Clients /
  // segment « À venir » (openStaffMenuPage, renderStaffData, renderStaffUtilityPage).
  if (page === 'requests') {
    // LA PAGE DEDIEE AUX DEMANDES SUR MESURE (2026-08-18, refaite le
    // 2026-09-29). Le sous-titre dit ce qui attend l equipe en une ligne :
    // combien a traiter, combien ont depasse l heure promise au client,
    // combien attendent sa reponse. Les onglets de la file portent les memes
    // comptes : une seule definition (getStaffRequestSegments).
    const buckets = getStaffRequestSegments();
    const aTraiter = buckets.atraiter.length;
    const enRetard = buckets.atraiter.filter((item) => { const due = staffRequestDue(item); return due && due.tone === 'late'; }).length;
    const enAttente = buckets.attente.length;
    const resume = [
      aTraiter ? `${aTraiter} à traiter${enRetard ? `, dont ${enRetard} en retard` : ''}` : 'Rien à traiter',
      enAttente ? `${enAttente} en attente du client` : '',
      'réponse promise au client sous 24 heures ouvrables',
    ].filter(Boolean).join(' · ');
    return {
      ...base,
      layout: 'requests',
      eyebrow: 'Clients & marketing',
      title: 'Demandes sur mesure',
      subtitle: `${resume}.`,
      hidePanelHead: true,
      hideDateAction: true,
      primaryLabel: '',
      primaryAction: '',
      secondaryLabel: 'Actualiser',
      secondaryAction: 'loadStaffCustomRequests(true)',
      body: renderStaffRequestsBoard()
    };
  }
  if (page === 'contacts') {
    const clientRows = getStaffClientRows();
    const missing = clientRows.filter(row => !row.email || !row.phone).length;
    return {
      ...base,
      layout: 'contacts',
      eyebrow: 'Clients & marketing',
      title: 'Contacts',
      subtitle: 'Carnet client issu des réservations réelles.',
      primaryLabel: 'Exporter CSV',
      primaryAction: 'exportStaffClientsCsv()',
      kpis: [
        ['Contacts', clientRows.length, 'profils consolidés'],
        ['Téléphone', clientRows.filter(row => row.phone).length, 'renseignés'],
        ['Email', clientRows.filter(row => row.email).length, 'renseignés'],
        ['À compléter', missing, 'fiche incomplète']
      ],
      body: renderStaffUtilityContactLedger(clientRows)
    };
  }
  if (page === 'lanes') {
    // La fenetre 30 j vit dans le cache CRM : on le remplit des l arrivee
    // sur la page (le rechargement repeint via loadStaffClientData).
    if (typeof ensureStaffClientData === 'function') ensureStaffClientData();
    ensureStaffCenterConfigForPlanning();
    const laneBoard = buildStaffLaneBoardModel();
    return {
      ...base,
      layout: 'lanes',
      eyebrow: 'Activités & tarifs',
      title: 'Pistes bowling',
      subtitle: 'Fermer, replacer, vendre un creux : l’état vivant de chaque piste.',
      primaryLabel: 'Réserver une piste',
      primaryAction: "openQuickBook({ date: state.currentDate, type: 'bowling' })",
      kpis: laneBoard.kpis,
      body: renderStaffLaneBoard(laneBoard)
    };
  }
  if (page === 'laserGame') {
    if (typeof ensureStaffClientData === 'function') ensureStaffClientData();
    const laserBoard = buildStaffLaserBoardModel();
    return {
      ...base,
      layout: 'laser',
      eyebrow: 'Activités & tarifs',
      title: 'Laser Game',
      subtitle: 'Prochain lancement, sessions à compléter, bilan 30 jours.',
      primaryLabel: 'Réserver un laser',
      primaryAction: "openQuickBook({ date: state.currentDate, type: 'laser' })",
      kpis: laserBoard.kpis,
      body: renderStaffLaserBoard(laserBoard)
    };
  }
  if (page === 'secours') {
    return {
      ...base,
      layout: 'secours',
      eyebrow: 'Administration',
      title: 'Secours',
      subtitle: 'Ce qui permet d’accueillir les groupes si Pinlane ne répond plus.',
      hidePanelHead: true,
      hideDateAction: true,
      primaryAction: '',
      secondaryAction: '',
      body: renderStaffUtilitySecours()
    };
  }
  if (page === 'establishment') {
    return {
      ...base,
      layout: 'establishment',
      eyebrow: 'Administration',
      title: 'Établissement',
      subtitle: 'Configuration des centres lue par le moteur.',
      hidePanelHead: true,
      hideDateAction: true,
      primaryLabel: 'Ouvrir la direction',
      primaryAction: "setView('admin'); openAdminTab('overview')",
      body: renderStaffUtilityEstablishment()
    };
  }
  if (page === 'users') {
    const access = ensureStaffAccessControl();
    // Entete "Acces" : memes exclusions que la page (les roles/membres
    // plateforme ne sont ni affiches ni comptes).
    const visibleRoles = getVisibleStaffAccessRoles(access);
    const visibleMembers = getVisibleStaffAccessMembers(access);
    const selectedRole = getStaffAccessRole(access.selectedRoleId);
    const permissionTotal = getStaffPermissionKeys().length;
    const selectedPermissionCount = new Set(selectedRole.permissions || []).size;
    const activeMembers = visibleMembers.filter(member => member.status === 'active').length;
    const pendingMembers = visibleMembers.filter(member => member.status === 'pending').length;
    return {
      ...base,
      layout: 'users',
      eyebrow: 'Administration',
      title: 'Équipe & accès',
      subtitle: 'Rôles, codes d’accès et permissions opérationnelles du centre.',
      hidePanelHead: true,
      hideDateAction: true,
      primaryLabel: 'Créer accès staff',
      primaryAction: 'createStaffMember()',
      secondaryLabel: 'Créer rôle',
      secondaryAction: 'createStaffCustomRole()',
      kpis: [
        [visibleRoles.length > 1 ? 'Rôles' : 'Rôle', visibleRoles.length, 'du centre'],
        ['Staff actif', activeMembers, `${pendingMembers} en attente`],
        ['Permissions du rôle', `${selectedPermissionCount}/${permissionTotal}`, selectedRole.name],
        ['Codes actifs', visibleRoles.filter(role => role.accessCode).length + visibleMembers.filter(member => member.code).length, 'rôles et membres']
      ],
      body: renderStaffUtilityUsers()
    };
  }
  if (page === 'settings') {
    return {
      ...base,
      layout: 'settings',
      eyebrow: 'Compte',
      title: 'Paramètres',
      subtitle: 'Les réglages de ce poste.',
      hidePanelHead: true,
      hideDateAction: true,
      primaryLabel: '',
      primaryAction: '',
      body: renderStaffUtilitySettings()
    };
  }
  return base;
}

function renderStaffUtilityPage() {
  const root = document.getElementById('staffUtilityPage');
  if (!root) return;
  const model = getStaffUtilityPageModel();
  // La date n est plus recopiee sous le titre : le selecteur de date, a cote,
  // l affiche deja avec le jour de la semaine.
  const heroSubtitle = escapeHtml(model.subtitle || '');
  const overviewPages = new Set(['users']);
  const archivePages = new Set(['groups', 'contacts']);
  // L en-tete du panneau RECOPIAIT le titre de la page (« Pistes » sous
  // « Pistes ») et portait un « Rafraîchir » qui ne faisait que redessiner
  // les memes donnees : les deux partent. Reste une ligne, seulement si elle
  // dit quelque chose (compte propre a la page, ou connexion perdue).
  const panelSubtitle = model.panelSubtitle || getStaffUtilitySyncLabel();
  const panelHead = model.hidePanelHead || !panelSubtitle ? '' : `<p class="utility-panel-note">${escapeHtml(panelSubtitle)}</p>`;
  // Entree de page : une fois par navigation, jamais au poll ni au tic de la
  // minute (meme repere de visite que l accueil et les pages pv2).
  const pages = window.PinlaneV2;
  const active = isStaffUtilityActive();
  const arriving = active && (pages ? pages.lastPage !== model.page : !root.firstElementChild);
  if (pages && active) pages.lastPage = model.page;
  root.className = `staff-utility-page utility-page-${escapeHtml(model.page)} utility-layout-${escapeHtml(model.layout || 'default')}${arriving && !prefersReducedMotion() ? ' utility-enter' : ''}`;
  // CE QU ON ETAIT EN TRAIN DE FAIRE SURVIT AU REPAINT (2026-08-20). La page se
  // repeint entierement des qu une reponse reseau arrive (file des demandes,
  // fil de mails, changement de statut). Sans cette sauvegarde, le champ en
  // cours de saisie est recree : le curseur saute a la fin, ou pire, le focus
  // part et la frappe suivante se perd. Meme chose pour le defilement d une
  // liste laterale, qui remontait en haut toute seule.
  const focused = document.activeElement;
  const focusedId = focused && root.contains(focused) && focused.id ? focused.id : '';
  const caretStart = focused && typeof focused.selectionStart === 'number' ? focused.selectionStart : null;
  const caretEnd = focused && typeof focused.selectionEnd === 'number' ? focused.selectionEnd : null;
  const keptScroll = [];
  root.querySelectorAll('#reqRailList, [data-keep-scroll]').forEach((node) => {
    if (node.id && node.scrollTop) keptScroll.push([node.id, node.scrollTop]);
  });
  root.innerHTML = `
    <section class="utility-hero">
      <div>
        <span>${escapeHtml(model.eyebrow)}</span>
        <h1>${escapeHtml(model.title)}</h1>
        ${heroSubtitle ? `<p>${heroSubtitle}</p>` : ''}
      </div>
      <div class="utility-actions">
        ${model.hideDateAction ? '' : staffDateNavHtml()}
        ${model.secondaryAction ? `<button type="button" onclick="${model.secondaryAction}">${escapeHtml(model.secondaryLabel)}</button>` : ''}
        ${model.primaryAction ? `<button type="button" class="primary" onclick="${model.primaryAction}">${escapeHtml(model.primaryLabel)}</button>` : ''}
      </div>
    </section>
    ${overviewPages.has(model.page) ? renderStaffUtilityOverview(model) : ''}
    <section class="utility-panel ${model.hidePanelHead ? 'utility-panel-flat' : ''}">
      ${panelHead}
      ${model.body}
    </section>
  `;
  keptScroll.forEach(([id, top]) => {
    const node = document.getElementById(id);
    if (node) node.scrollTop = top;
  });
  if (focusedId) {
    const again = document.getElementById(focusedId);
    if (again && again !== document.activeElement) {
      again.focus({ preventScroll: true });
      if (caretStart !== null && typeof again.setSelectionRange === 'function') {
        try { again.setSelectionRange(caretStart, caretEnd); } catch (error) {}
      }
    }
  }
  if (archivePages.has(model.page)) ensureStaffClientData();
  if (model.page === 'groups' || model.page === 'requests') ensureStaffCustomRequests();
  // Le fil de la demande ouverte se charge tout seul : l'historique existait
  // deja, il fallait cliquer un bouton par carte pour le voir.
  if (model.page === 'requests') ensureStaffRequestThread();
  // L etude du dossier ouvert : ce que le moteur dit de sa date.
  if (model.page === 'requests') ensureStaffRequestStudy();
  if ((model.page === 'emails' || model.page === 'establishment') && !opsAdminCache.loaded && !opsAdminCache.loading) requestOpsAdminLoad(false);
}

function isStaffClientsActive() {
  return state.view === 'staff' && getStaffMenuPage() === 'clients';
}

function getPricingTypeLabel(type) {
  return type === 'bowling' ? 'Bowling'
    : type === 'laser' ? 'Laser Game'
    : type === 'special' ? 'Formule spéciale'
    : 'Formule';
}

function getPricingPriceLabel(row) {
  if (row.type === 'bowling') return `${formatMoney(row.price)} / piste`;
  if (row.type === 'laser') return `${formatMoney(row.price)} / personne`;
  return `${formatMoney(row.price)} ${row.priceType === 'per_lane' ? '/ piste' : '/ personne'}`;
}

function getPricingAsset(type) {
  if (type === 'bowling') return './assets/pricing/bowling.png';
  if (type === 'laser') return './assets/pricing/laser.png';
  if (type === 'special') return './assets/pricing/special.png';
  return './assets/pricing/formula.png';
}

function getPricingTone(type) {
  if (type === 'bowling') return 'green';
  if (type === 'laser') return 'blue';
  if (type === 'special') return 'violet';
  return 'amber';
}

// LES CHIFFRES DE LA PAGE TARIFS PORTENT SUR 30 JOURS. Ils comptaient
// « les données locales » : ce que la console avait charge, une fenetre que
// personne ne connait (le jour affiche et ses voisins). Meme fenetre que
// Pistes et Laser Game : les 30 jours revolus, annulations exclues.
// L historique vient de /api/admin-range : sans le droit de le lire, la page
// ne compte RIEN (jamais les seules reservations en memoire).
function canReadStaffReservationHistory() {
  return typeof canUseStaffPermission !== 'function'
    || ['direction.view', 'reservations.view', 'clients.view'].some(permission => canUseStaffPermission(permission));
}
if (typeof window !== 'undefined') window.canReadStaffReservationHistory = canReadStaffReservationHistory;

function getPricingReservations() {
  if (!canReadStaffReservationHistory()) return [];
  return getStaffResourceHistoryRows();
}

function getPricingUsageMap() {
  const usage = new Map();
  const register = (id, reservation) => {
    const item = usage.get(id) || { count: 0, players: 0, revenue: 0 };
    item.count += 1;
    item.players += Number(reservation.pax || 0);
    item.revenue += Number(reservation.price || 0);
    usage.set(id, item);
  };
  getPricingReservations().forEach(reservation => {
    if (reservation.formuleId) {
      register(`formula-${reservation.formuleId}`, reservation);
      return;
    }
    if (reservation.type === 'laser') {
      const option = LASER_GAME_OPTIONS.find(item => Number(item.value) === Number(reservation.duration || 0.5)) || LASER_GAME_OPTIONS[0];
      register(`laser-${option.games}`, reservation);
      return;
    }
    if (reservation.type === 'bowling') {
      register(`bowling-${Number(reservation.duration || 1)}`, reservation);
    }
  });
  return usage;
}

// LA SOURCE des formules pour les ecrans de la console (grille Tarifs,
// Etablissement > Offres) : la liste VIVE du catalogue (customs comprises,
// editions refletees, nom/prix effectifs du centre) quand elle est chargee,
// la constante FORMULES sinon. Les formules retirees du catalogue sont
// EXCLUES par defaut (elles n'existent plus pour le centre) ; la grille
// Tarifs les demande pour les montrer barrees et restaurables.
function getConsoleFormuleCatalog({ includeRemoved = false } = {}) {
  const live = typeof window !== 'undefined' && typeof window.pevLiveFormules === 'function'
    ? window.pevLiveFormules()
    : null;
  if (!Array.isArray(live) || !live.length) return getEffectiveCatalogFormules();
  return includeRemoved ? live : live.filter(formule => !formule.removed);
}

// Les jours d'un palier de tarif, ecrits comme le gerant les lit. Une plage
// continue se dit « Mercredi a jeudi » ; des jours epars se listent. La semaine
// commence LUNDI ici (l'ordre du calendrier belge), pas dimanche comme dans
// l'index JavaScript.
const PRICING_DAY_NAMES = ['Dimanche', 'Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi'];
function describePricingDays(days) {
  const list = Array.from(new Set((Array.isArray(days) ? days : [])
    .map(value => Math.trunc(Number(value)))
    .filter(value => Number.isFinite(value) && value >= 0 && value <= 6)));
  if (!list.length) return 'Tous les jours';
  if (list.length === 7) return 'Tous les jours';
  const weekOrder = value => (value === 0 ? 6 : value - 1);
  list.sort((a, b) => weekOrder(a) - weekOrder(b));
  const contiguous = list.every((value, index) => index === 0 || weekOrder(value) === weekOrder(list[index - 1]) + 1);
  if (list.length > 2 && contiguous) {
    return `${PRICING_DAY_NAMES[list[0]]} a ${PRICING_DAY_NAMES[list[list.length - 1]].toLowerCase()}`;
  }
  const names = list.map(value => PRICING_DAY_NAMES[value]);
  if (names.length === 1) return names[0];
  return `${names.slice(0, -1).join(', ')} et ${names[names.length - 1].toLowerCase()}`;
}

function getPricingRows() {
  const usage = getPricingUsageMap();
  const decorate = row => ({
    ...row,
    asset: getPricingAsset(row.type),
    tone: getPricingTone(row.type),
    ...(usage.get(row.id) || { count: 0, players: 0, revenue: 0 })
  });
  // ---- CE CENTRE VEND-IL VRAIMENT CA, ET COMMENT ? ------------------------
  //
  // Ces deux blocs etaient construits depuis les constantes du SOCLE
  // (DURATION_OPTIONS : 20/39/59/78 EUR la piste, LASER_GAME_OPTIONS :
  // 10/18/25 EUR), quel que soit le centre. C'est la grille de Fun Galaxy.
  // Mesure du 2026-08-21 (capture Movsar) : N4, qui n'a AUCUNE arene laser
  // (weaponCount 0) et vend son bowling AUX PARTIES ET PAR PERSONNE, se
  // voyait proposer les quatre durees par piste ET les trois offres laser.
  //
  // Meme regle que les onglets de la page Planning : la CLE ABSENTE veut dire
  // « on ne sait pas encore » (le repli neutre de getAdminCenter rend
  // `resources: {}`) et on n'enleve rien ; la cle PRESENTE a null ou a zero
  // dit que la ressource n'existe pas.
  const centerResources = (typeof getAdminCenter === 'function' ? (getAdminCenter() || {}).resources : null) || {};
  const knowsResource = kind => Object.prototype.hasOwnProperty.call(centerResources, kind);
  const centerLaneCount = Number(centerResources.bowling && centerResources.bowling.laneCount) || 0;
  const centerWeaponCount = Number(centerResources.laser && centerResources.laser.weaponCount) || 0;
  const sellsBowling = !knowsResource('bowling') || centerLaneCount > 0;
  const sellsLaser = !knowsResource('laser') || centerWeaponCount > 0;
  // Le tarif bowling DU CENTRE : present, il vend aux parties et par personne
  // (N4) ; absent, il vend a la grille par piste et par duree (Fun Galaxy).
  // Meme lecture que lib/booking-config.resolveBowlingPricing.
  const bowlingPricing = centerResources.bowling && centerResources.bowling.pricing
    && centerResources.bowling.pricing.mode === 'per_game_per_person'
    && Array.isArray(centerResources.bowling.pricing.tiers)
    && centerResources.bowling.pricing.tiers.length
    ? centerResources.bowling.pricing
    : null;
  const maxPerLane = knowsResource('bowling') && Number(centerResources.bowling && centerResources.bowling.normalCapacityPerLane) > 0
    ? Number(centerResources.bowling.normalCapacityPerLane)
    : MAX_PER_LANE;
  // Une carte par PALIER DE JOURS et par nombre de parties : c'est la forme
  // exacte de la donnee (tiers[].prices[i] = i+1 parties). Afficher un seul
  // prix moyen mentirait, et le gerant ne pourrait plus verifier son tarif.
  const bowlingGameCards = () => {
    const rows = [];
    (bowlingPricing.tiers || []).forEach((tier, tierIndex) => {
      const daysLabel = describePricingDays(tier.days);
      (tier.prices || []).forEach((price, index) => {
        const games = index + 1;
        const gamesLabel = games === 1 ? '1 partie' : `${games} parties`;
        rows.push(decorate({
          id: `bowling-game-${tierIndex}-${games}`,
          type: 'bowling',
          title: `Bowling ${gamesLabel}`,
          subtitle: daysLabel,
          description: `${gamesLabel} par personne, ${daysLabel.toLowerCase()}.`,
          price: Number(price),
          priceUnit: '/pers',
          durationLabel: gamesLabel,
          capacity: `${maxPerLane} joueurs / piste`,
          availability: daysLabel,
          tags: ['Piste', gamesLabel, daysLabel],
          activities: ['Bowling']
        }));
      });
    });
    return rows;
  };
  const bowlingGridCards = () => DURATION_OPTIONS.map(option => decorate({
    id: `bowling-${Number(option.value)}`,
    type: 'bowling',
    title: `Bowling ${option.label}`,
    subtitle: 'Location de piste',
    description: `${option.label} de jeu, prix par piste, jusqu'à ${maxPerLane} joueurs confort.`,
    price: option.price,
    priceUnit: '/piste',
    durationLabel: option.label,
    capacity: `${maxPerLane} joueurs / piste`,
    availability: 'Selon horaires du centre',
    tags: ['Piste', option.label, `${maxPerLane} joueurs`],
    activities: ['Bowling']
  }));
  const bowling = !sellsBowling ? [] : (bowlingPricing ? bowlingGameCards() : bowlingGridCards());
  // L arene DU CENTRE : 20 armes et six lancements a Gembloux, 30 et un seul
  // a Libramont. La constante disait 30 et 1 partout.
  const armes = getAvailabilityLaserCapacity();
  const lancements = getAvailabilityLaserParallelLaunches();
  const laser = !sellsLaser ? [] : LASER_GAME_OPTIONS.map(option => decorate({
    id: `laser-${option.games}`,
    type: 'laser',
    title: `${option.label} Laser Game`,
    subtitle: `${option.games} passage${option.games > 1 ? 's' : ''}`,
    description: `${option.durationMinutes} min estimées, session partageable selon l'affluence, ${armes} armes disponibles.`,
    price: option.price,
    durationLabel: `${option.durationMinutes} min`,
    capacity: `${armes} joueurs en même temps au plus`,
    availability: `${lancements} lancement${lancements > 1 ? 's' : ''} simultané${lancements > 1 ? 's' : ''}`,
    tags: ['Laser', `${option.games} partie${option.games > 1 ? 's' : ''}`, `${armes} armes`],
    activities: ['Laser Game']
  }));
  const formulas = getConsoleFormuleCatalog({ includeRemoved: true }).map(formule => {
    const special = formule.family !== 'Formules anniversaires';
    return decorate({
      id: `formula-${formule.id}`,
      sourceId: formule.id,
      removed: formule.removed === true,
      source: formule.source || 'seed',
      family: formule.family || '',
      type: special ? 'special' : 'formula',
      title: formule.name,
      subtitle: formule.family || 'Formule',
      description: (formule.desc || []).join(' · '),
      price: formule.price,
      oldPrice: formule.oldPrice,
      priceType: formule.type,
      durationLabel: `${formatDurationLabel(getFormuleTotalDuration(formule))} estimées`,
      capacity: `${formule.minPax || 1}+ personne${Number(formule.minPax || 1) > 1 ? 's' : ''}`,
      availability: getFormulaAvailabilityLabel(formule),
      tags: [
        formule.hasBowling ? `Bowling ${formatDurationLabel(formule.bowlingDur || 1)}` : '',
        getFormulaLaserGameCount(formule) ? `Laser x${getFormulaLaserGameCount(formule)}` : '',
        formule.noHolidays ? 'Hors congés' : '',
        ...(formule.validDays ? ['Jour limité'] : [])
      ].filter(Boolean),
      activities: formule.desc || [],
      best: !!formule.best,
      notes: formule.notes || []
    });
  });
  return [...bowling, ...laser, ...formulas];
}

function getFormulaAvailabilityLabel(formule) {
  const days = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
  const parts = [];
  if (Array.isArray(formule.validDays) && formule.validDays.length) {
    parts.push(formule.validDays.map(day => days[day] || '').filter(Boolean).join(', '));
  }
  if (formule.timeLimit?.min || formule.timeLimit?.max) {
    parts.push(`${formule.timeLimit.min ? formatClockDisplay(formule.timeLimit.min) : 'ouverture'} - ${formule.timeLimit.max ? formatClockDisplay(formule.timeLimit.max) : 'fermeture'}`);
  }
  if (formule.noHolidays) parts.push('hors vacances/jours fériés');
  return parts.length ? parts.join(' · ') : 'Tous horaires compatibles';
}

// Les deux familles du socle ont leur onglet cable (« Anniversaires » et
// « Speciales ») ; toute autre categorie est une categorie CREEE, et elle a
// droit au sien. La cle ignore accents et casse : le socle fichier ecrit
// « Formules spéciales », le catalogue servi « Formules speciales ».
const PRICING_BIRTHDAY_FAMILY = 'formules anniversaires';
const PRICING_SPECIAL_FAMILY = 'formules speciales';
function normalizePricingFamilyKey(family) {
  return String(family == null ? '' : family)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .trim().toLowerCase();
}
// Les categories creees, dans l ordre d apparition du catalogue.
function getPricingCustomFamilies(rows) {
  const seen = new Map();
  (rows || []).forEach(row => {
    if (row.type !== 'formula' && row.type !== 'special') return;
    const key = normalizePricingFamilyKey(row.family);
    if (!key || key === PRICING_BIRTHDAY_FAMILY || key === PRICING_SPECIAL_FAMILY) return;
    if (!seen.has(key)) seen.set(key, { key, label: row.family, count: 0 });
    seen.get(key).count += 1;
  });
  return [...seen.values()];
}

function getPricingRowsFiltered() {
  const filter = state.staffPricingFilter || 'all';
  const query = String(state.staffPricingQuery || '').trim().toLowerCase();
  const filtered = getPricingRows().filter(row => {
    // Une categorie creee par le gerant se filtre par son NOM (« family:... »).
    // Les quatre cles historiques restent des TYPES : sans cette branche, une
    // categorie inedite n'avait aucun onglet et ses formules etaient comptees
    // avec les speciales.
    if (filter.startsWith('family:')) {
      if (normalizePricingFamilyKey(row.family) !== filter.slice('family:'.length)) return false;
    } else if (filter !== 'all' && row.type !== filter) return false;
    if (!query) return true;
    return `${row.title} ${row.subtitle} ${row.description} ${row.tags.join(' ')}`.toLowerCase().includes(query);
  });
  return sortPricingRows(filtered);
}

// Classement rentabilité/demande : agrégats réels des réservations (count,
// revenue, players déjà portés par chaque ligne du catalogue).
function sortPricingRows(rows) {
  const ranking = state.staffPricingSort || 'default';
  if (ranking === 'default') return rows;
  const basket = row => (Number(row.count) ? Number(row.revenue || 0) / Number(row.count) : 0);
  const keyFn = {
    demand: row => Number(row.count || 0),
    revenue: row => Number(row.revenue || 0),
    players: row => Number(row.players || 0),
    basket,
  }[ranking] || (row => 0);
  return [...rows].sort((a, b) => keyFn(b) - keyFn(a) || Number(b.revenue || 0) - Number(a.revenue || 0));
}

function setStaffPricingSort(ranking) {
  state.staffPricingSort = state.staffPricingSort === ranking ? 'default' : ranking;
  save();
  renderStaffPricingPage();
}

function getPricingMetrics(rows = getPricingRows()) {
  const revenue = rows.reduce((sum, row) => sum + Number(row.revenue || 0), 0);
  const reservations = rows.reduce((sum, row) => sum + Number(row.count || 0), 0);
  const formulaRows = rows.filter(row => row.type === 'formula' || row.type === 'special');
  const activeOffers = rows.length;
  const topRow = [...rows].sort((a, b) => Number(b.count || 0) - Number(a.count || 0))[0] || null;
  return { revenue, reservations, activeOffers, formulaRows: formulaRows.length, topRow };
}

function setStaffPricingQuery(value) {
  state.staffPricingQuery = value || '';
  renderStaffPricingPage();
}

function getSelectedPricingRow(rows = getPricingRowsFiltered()) {
  return rows.find(row => row.id === state.staffPricingSelectedId) || rows[0] || getPricingRows()[0] || null;
}

function openStaffPricingBooking(id) {
  const row = getPricingRows().find(item => item.id === id);
  if (!row) return;
  if (row.type === 'laser') {
    const option = LASER_GAME_OPTIONS.find(item => `laser-${item.games}` === row.id) || LASER_GAME_OPTIONS[0];
    openQuickBook({ date: state.currentDate || todayStr(), type: 'laser', duration: option.value });
    return;
  }
  if (row.type === 'formula' || row.type === 'special') {
    openQuickBook({ date: state.currentDate || todayStr(), type: 'formule', formuleId: row.sourceId });
    return;
  }
  const option = DURATION_OPTIONS.find(item => `bowling-${Number(item.value)}` === row.id) || DURATION_OPTIONS[1];
  openQuickBook({ date: state.currentDate || todayStr(), type: 'bowling', duration: option.value });
}

// C14 : utilitaires d'export partagés staff/direction, vivaient dans
// admin-console.js, désormais ici car ce fichier est chargé pour tous les
// profils alors que la console admin est injectée à la demande.
function downloadTextFile(filename, content, mime = 'text/plain;charset=utf-8') {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function csvCell(value) {
  const text = String(value ?? '');
  return `"${text.replace(/"/g, '""')}"`;
}

// C14 : sélection d'onglet admin sûre même pendant l'injection des consoles 
// l'onglet est mémorisé et setView('admin') le rend une fois le script chargé.
function openAdminTab(tab) {
  if (typeof setAdminTab === 'function') {
    setAdminTab(tab);
    return;
  }
  state.adminTab = tab || 'overview';
  save();
}

// C14 : sélection de centre sûre pendant l'injection, le centre est mémorisé
// et le .then() de setView('admin') rend le dashboard avec (sans ce garde, le
// premier switch de centre était perdu, setAdminCenter n'existant pas encore).
function openAdminCenter(centerId) {
  if (typeof setAdminCenter === 'function') {
    setAdminCenter(centerId);
    return;
  }
  state.adminCenterId = centerId || 'libramont';
  save();
}


// ---- GARDES DE PERMISSION COTE ECRAN (2026-08-19) ---------------------------
// Six permissions etaient DECORATIVES : declarees, affichees dans l editeur de
// roles, et ne gardant rien (audit scripts/permissions-audit-check.js). Les
// decocher ne changeait rien, et pire : le bouton restait la pour mener a un
// refus serveur. Cette garde les rend vraies. Elle vit DANS les fonctions, pas
// seulement sur les boutons : un bouton masque ne protege pas une fonction qui
// reste appelable. Le serveur reste la seule autorite, ceci evite le refus.
function requireClientPermission(permission, message) {
  if (typeof canUseStaffPermission !== 'function' || canUseStaffPermission(permission)) return true;
  if (typeof toast === 'function') toast(message || 'Votre rôle ne permet pas cette action.');
  return false;
}

// 'planning.past' nommait « Modifier une date passee » sans rien garder : la
// restriction n'existait pas. Elle existe desormais, et elle porte sur l'ACTE
// (ecrire sur un jour deja passe), pas sur la lecture : consulter l'historique
// reste ouvert a qui voit le planning.
function requirePastDatePermission(dateStr) {
  const date = String(dateStr || '').slice(0, 10);
  if (!date || typeof isPastBusinessDate !== 'function' || !isPastBusinessDate(date)) return true;
  return requireClientPermission('planning.past', 'Votre rôle ne permet pas de modifier une date passée.');
}

// 'payments.view' nommait « Voir les montants » sans rien masquer. Les surfaces
// de caisse passent par ici : sans le droit, le chiffre cede la place a un
// tiret, jamais a un zero (un zero est un FAIT, et il serait faux).
function moneyForRole(amount) {
  if (typeof canUseStaffPermission === 'function' && !canUseStaffPermission('payments.view')) return '···';
  return typeof formatMoney === 'function' ? formatMoney(amount) : String(amount);
}

function exportStaffPricingCsv() {
  if (!requireClientPermission('exports.download', 'Votre rôle ne permet pas de télécharger les exports.')) return;
  const rows = getPricingRowsFiltered();
  const header = ['Type', 'Nom', 'Prix', 'Capacité', 'Disponibilité', 'Réservations (30 j)', 'Joueurs (30 j)', 'Chiffre (30 j)', 'Détails'];
  const body = rows.map(row => [
    getPricingTypeLabel(row.type),
    row.title,
    getPricingPriceLabel(row),
    row.capacity,
    row.availability,
    row.count || 0,
    row.players || 0,
    row.revenue || 0,
    row.description
  ].map(csvCell).join(','));
  downloadTextFile(`${getCurrentStaffCenterId()}-tarifs-formules-${state.currentDate || todayStr()}.csv`, [header.map(csvCell).join(','), ...body].join('\n'), 'text/csv;charset=utf-8');
}

function copyStaffPricingSummary() {
  const rows = getPricingRowsFiltered();
  const summary = rows.map(row => `${row.title}: ${getPricingPriceLabel(row)} (${row.availability})`).join('\n');
  navigator.clipboard?.writeText(summary).then(() => toast('Tarifs copiés.')).catch(() => toast(summary));
}

function getStaffEmailId(item, index = 0) {
  return String(item.id || item.communicationId || item.queueId || [
    item.templateId || 'mail',
    item.recipient || 'recipient',
    item.createdAt || item.scheduledAt || 'time',
    index
  ].join(':'));
}

function getStaffEmailStatusKind(item = {}) {
  const status = String(item.status || 'draft').toLowerCase();
  if (status === 'sent' || status === 'delivered') return 'sent';
  if (status === 'failed' || status === 'error') return 'failed';
  if (status === 'queued' || status === 'pending') return 'queued';
  if (status === 'skipped') return 'paused';
  return 'draft';
}

function getStaffEmailStatusLabel(item = {}) {
  const kind = getStaffEmailStatusKind(item);
  const labels = {
    sent: 'Envoyé',
    failed: 'À corriger',
    queued: 'En file',
    paused: 'En pause',
    draft: 'Brouillon'
  };
  return labels[kind] || 'Message';
}

function getStaffEmailRows() {
  // C14 : ops-console.js est injecté à la demande, avant son arrivée, la page
  // Emails rend son état vide (le chargement est déjà déclenché par la page).
  if (typeof getVisibleOpsCommunications !== 'function') return [];
  return getVisibleOpsCommunications()
    .map((item, index) => ({
      ...item,
      uid: getStaffEmailId(item, index),
      sourceIndex: index,
      statusKind: getStaffEmailStatusKind(item),
      templateLabel: getOpsTemplateLabel(item.templateId)
    }));
}

// ── Origine d'une communication : QUI l'a déclenchée ─────────────────────────
// Classifieur ancré sur les champs payload RÉELLEMENT posés par chaque chemin
// d'envoi serveur (vérifiés un à un sur les enqueue de lib/ops-communications.js,
// lib/ops-jobs.js et lib/email-agent.js) :
//   'inbound' : mail REÇU (ingestInboundEmail : direction='inbound', status
//               'received'). Ni auto ni manuel : c'est le client qui écrit.
//   'manual'  : une action humaine directe a déclenché CET envoi :
//               payload.direct/directEmail → sendDirectEmail (composer, studio_*)
//               payload.relance            → sendClientRelance (relance 1-clic, relance_*)
//               payload.clientMessage      → sendClientMessage (message depuis une résa, client_*)
//               payload.test               → sendAutomationTest (test au staff connecté, test_*)
//               payload.campaignId         → enqueueCampaign (campagne lancée par l'équipe, campaign_*)
//   'auto'    : tout le reste, parti tout seul (worker/cron/séquences) :
//               request_received, confirmation, reminder_48h, reminder_day_sms,
//               staff_review_request, delay_change, post_visit_followup,
//               birthday_j30, reactivation, custom_* et les rangées de
//               simulation. AUCUN de ces chemins ne pose les flags ci-dessus.
function getStaffEmailOrigin(row = {}) {
  if (row.direction === 'inbound' || row.status === 'received') return 'inbound';
  const payload = row.payload && typeof row.payload === 'object' ? row.payload : {};
  const flag = (value) => value === true || value === 'true';
  if (flag(payload.direct) || flag(payload.directEmail)) return 'manual';
  if (flag(payload.relance)) return 'manual';
  if (flag(payload.clientMessage)) return 'manual';
  if (flag(payload.test)) return 'manual';
  if (payload.campaignId) return 'manual';
  return 'auto';
}

function getStaffEmailOriginLabel(row = {}) {
  const origin = getStaffEmailOrigin(row);
  if (origin === 'inbound') return 'Reçu';
  return origin === 'manual' ? 'Envoi manuel' : 'Automatique';
}

function getStaffEmailText(row = {}) {
  const payload = row.payload || {};
  return [
    row.subject,
    row.recipient,
    row.templateLabel || getOpsTemplateLabel(row.templateId),
    row.channel,
    row.status,
    row.lastError,
    payload.textBody,
    payload.validationMode,
    payload.customerName,
    payload.phone
  ].filter(Boolean).join(' ').toLowerCase();
}

function getStaffEmailRowsFiltered() {
  const filter = state.staffEmailFilter || 'all';
  const template = state.staffEmailTemplateFilter || 'all';
  // Origine (auto/manuel) COMBINABLE avec les statuts : les deux filtres se
  // cumulent (ex. « Envois manuels » + « Échecs »). 'inbound' est géré par la
  // page (pv2EmailFilter), pas ici.
  const origin = ['auto', 'manual'].includes(state.staffEmailOriginFilter) ? state.staffEmailOriginFilter : 'all';
  const query = String(state.staffEmailQuery || '').trim().toLowerCase();
  return getStaffEmailRows().filter(row => {
    if (origin !== 'all' && getStaffEmailOrigin(row) !== origin) return false;
    if (filter === 'review' && row.templateId !== 'staff_review_request') return false;
    if (filter !== 'all' && filter !== 'review' && row.statusKind !== filter) return false;
    if (template !== 'all' && row.templateId !== template) return false;
    if (query && !getStaffEmailText(row).includes(query)) return false;
    return true;
  });
}

function getStaffEmailMetrics(rows = getStaffEmailRows()) {
  const sent = rows.filter(row => row.statusKind === 'sent').length;
  const queued = rows.filter(row => row.statusKind === 'queued').length;
  const failed = rows.filter(row => row.statusKind === 'failed').length;
  const review = rows.filter(row => row.templateId === 'staff_review_request').length;
  const due = rows.filter(row => row.statusKind === 'queued' && (!row.scheduledAt || new Date(row.scheduledAt).getTime() <= Date.now())).length;
  const reminders = rows.filter(row => row.templateId === 'reminder_48h').length;
  const attempted = rows.reduce((sum, row) => sum + Number(row.attempts || 0), 0);
  const deliveryBase = sent + failed;
  // AUCUN ENVOI, AUCUN TAUX. La valeur par defaut etait 100, donc le bandeau
  // affichait « 0 Envoye » surmontant « 100 % de reussite » : un taux de
  // reussite calcule sur rien, qui se lit comme un fait. Un taux sans base
  // n existe pas ; on renvoie l absence, et l affichage n ecrit rien.
  const deliveryRate = deliveryBase ? Math.round((sent / deliveryBase) * 100) : null;
  return { sent, queued, failed, review, due, reminders, attempted, deliveryRate, total: rows.length };
}

function setStaffEmailQuery(query = '') {
  state.staffEmailQuery = String(query || '');
  state.staffEmailSelectedId = '';
  save();
  renderStaffEmailsPage();
}

function getSelectedStaffEmailRow(rows = getStaffEmailRowsFiltered()) {
  if (!rows.length) return null;
  const selected = rows.find(row => row.uid === state.staffEmailSelectedId);
  return selected || rows[0];
}

// `rows` optionnel : la section Envoyés exporte exactement la file qu'elle
// affiche (ses filtres Remis/Ouverts n'existent pas dans le filtre historique).
function exportStaffEmailsCsv(rowsAffichees = null) {
  if (!requireClientPermission('exports.download', 'Votre rôle ne permet pas de télécharger les exports.')) return;
  const rows = Array.isArray(rowsAffichees) ? rowsAffichees : getStaffEmailRowsFiltered();
  const header = ['Statut', 'Origine', 'Modele', 'Sujet', 'Destinataire', 'Canal', 'Planifie', 'Envoye', 'Tentatives', 'Erreur'];
  const body = rows.map(row => [
    getStaffEmailStatusLabel(row),
    getStaffEmailOriginLabel(row),
    getOpsTemplateLabel(row.templateId),
    row.subject || '',
    row.recipient || '',
    row.channel || 'email',
    row.scheduledAt || '',
    row.sentAt || '',
    Number(row.attempts || 0),
    row.lastError || ''
  ].map(csvCell).join(','));
  downloadTextFile(`${getCurrentStaffCenterId()}-mails-${state.currentDate || todayStr()}.csv`, [header.map(csvCell).join(','), ...body].join('\n'), 'text/csv;charset=utf-8');
}

function getStaffClientInitials(name = '') {
  const parts = String(name || 'Client')
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2);
  return (parts.map(part => part[0]).join('') || 'CL').toUpperCase();
}

function staffClientJs(value) {
  // escapeHtml sur le littéral JSON : sans ça les guillemets doubles de
  // JSON.stringify cassent l'attribut onclick="..." (double quotes) et le
  // handler devient un no-op silencieux (boutons fantômes Terrain/Groupes).
  // Encodé en entités, l'argument est valable dans onclick="" comme onclick=''.
  return escapeHtml(JSON.stringify(String(value || '')).replace(/</g, '\\u003c'));
}

