// Recherche une réservation par id dans TOUTES les sources chargées, pas
// seulement la source de la page Réservations. Indispensable depuis Terrain
// et Groupes où la résa provient du cache clients (historique) et pas de
// state.reservations. Comparaison en String : les ids d'état sont numériques
// alors que les onclick passent des chaînes.
function findStaffReservationById(id) {
  if (id == null || id === '') return null;
  const key = String(id);
  const local = (state.reservations || []).find(item => item && String(item.id) === key);
  if (local) return local;
  const sources = [];
  if (typeof getStaffClientSourceReservations === 'function') sources.push(getStaffClientSourceReservations());
  if (typeof getStaffReservationsSourceReservations === 'function') sources.push(getStaffReservationsSourceReservations());
  for (const list of sources) {
    const match = (list || []).find(item => item && String(item.id) === key);
    if (match) return match;
  }
  return null;
}

function openStaffReservationDetail(id) {
  const reservation = findStaffReservationById(id);
  if (!reservation) {
    toast('Réservation introuvable ou non chargée.');
    return;
  }
  upsertReservationInState(reservation);
  state.currentDate = reservation.date || state.currentDate;
  state.selectedRes = reservation;
  state.activeTab = 'details';
  state.editState = etatEditionDepuis(reservation);
  save();
  renderPos();
}

// LE DEFILEMENT SE LIT AVANT LE RENDU ET SE REPOSE APRES (2026-10-07).
// Chaque grille memorisait sa position au milieu du rendu (`wrap.scrollTop`)
// puis la reposait juste apres son innerHTML. Une lecture de geometrie qui suit
// une ecriture oblige le navigateur a recalculer TOUTE la page sur le champ :
// mesure sur tablette (processeur ralenti 4x, journee chargee), un rendu du
// planning payait trois mises en page completes de plus que l image elle-meme
// (renderPlanning lecture 144 ms, renderPlanning repose 92 ms, renderTable
// repose 113 ms). Les positions se lisent donc une fois, AVANT la premiere
// ecriture, et se reposent toutes a la fin : une seule mise en page, celle que
// l image aurait faite de toute facon. Une position nulle ne se repose pas :
// remplacer le contenu ne fait jamais defiler un conteneur qui etait en haut.
var defilementsDuRendu = null; // var : renderStaffData peut tourner avant cette ligne au chargement
function ouvrirLotDefilement() {
  if (defilementsDuRendu) return false;
  const lus = new Map();
  if (state.view === 'staff' && isStaffPlanningPageActive()) {
    const laser = document.getElementById('laserPlanningGridWrap');
    [
      document.getElementById('planningGridWrap'),
      laser,
      laser && laser.querySelector('.laser-agenda'),
      laser && laser.querySelector('.laser-pass-queue'),
      document.getElementById('resList'),
    ].forEach((el) => { if (el) lus.set(el, [el.scrollTop, el.scrollLeft]); });
  }
  defilementsDuRendu = { lus, aPoser: new Map() };
  return true;
}
function fermerLotDefilement() {
  const lot = defilementsDuRendu;
  defilementsDuRendu = null;
  if (!lot) return;
  lot.aPoser.forEach(([top, left], el) => {
    if (!el.isConnected || (!top && !left)) return;
    el.scrollTop = top;
    el.scrollLeft = left;
  });
}
function lireDefilementRendu(el) {
  if (!el) return [0, 0];
  const lot = defilementsDuRendu;
  // Un conteneur deja reconstruit dans ce lot rend la position qu il attend.
  const connu = lot && (lot.aPoser.get(el) || lot.lus.get(el));
  return connu ? [connu[0], connu[1]] : [el.scrollTop, el.scrollLeft];
}
function poserDefilementRendu(el, top, left) {
  if (!el) return;
  if (defilementsDuRendu) { defilementsDuRendu.aPoser.set(el, [top || 0, left || 0]); return; }
  if (!top && !left) return;
  el.scrollTop = top;
  el.scrollLeft = left;
}
function avecLotDefilement(rendre) {
  const ouvert = ouvrirLotDefilement();
  try { return rendre(); } finally { if (ouvert) fermerLotDefilement(); }
}

function renderStaff() {
  if (!hasSavedAuth()) {
    renderStaffShell(todaysReservations());
    applyAuthState();
    return;
  }
  guardStaffPage();
  return avecLotDefilement(renderStaffPage);
}

function renderStaffPage() {
  const dayReservations = todaysReservations();
  queueMicrotask(() => window.PinlaneStaffNotes?.prefetch(dayReservations));
  renderStaffShell(dayReservations);
  // Les pages v2 vivent dans staff-pages-v2.js, un defer charge APRES ce
  // fichier. Depuis que la vue est appliquee AVANT les attentes reseau
  // (correctif anti-flash du 2026-08-06), ce dispatcher peut tourner pendant
  // que leur script se parse encore : sans garde, ReferenceError et la page
  // restait NOIRE jusqu'a un rechargement (bug rapporte le jour meme). Chaque
  // page absente est simplement sautee ; le filet post-chargement (listener
  // load, plus bas) re-rend la vue des que tous les scripts sont la.
  const pageReady = (fn) => typeof window[fn] === 'function';
  if (isStaffDashboardActive()) {
    document.body.style.overflow = '';
    renderStaffDashboard(dayReservations);
    return;
  }
  if (isStaffReservationsActive()) {
    document.body.style.overflow = '';
    if (pageReady('renderStaffReservationsPage')) renderStaffReservationsPage();
    return;
  }
  if (isStaffClientsActive()) {
    document.body.style.overflow = '';
    if (pageReady('renderStaffClientsPage')) renderStaffClientsPage();
    return;
  }
  if (isStaffPricingActive()) {
    document.body.style.overflow = '';
    if (pageReady('renderStaffPricingPage')) renderStaffPricingPage();
    return;
  }
  if (isStaffEmailsActive()) {
    document.body.style.overflow = '';
    if (pageReady('renderStaffEmailsPage')) renderStaffEmailsPage();
    return;
  }
  if (isStaffCampaignsActive()) {
    document.body.style.overflow = '';
    if (pageReady('renderStaffCampaignsPage')) renderStaffCampaignsPage();
    return;
  }
  if (isStaffCockpitActive()) {
    document.body.style.overflow = '';
    const cockpitHost = document.getElementById('staffCockpitPage');
    const cockpitPage = getStaffMenuPage();
    // Les surfaces de GESTION (Centres, Equipe) sont des modules dedies ; les
    // pages d'observation (cockpit, agents, incidents, clients) restent servies
    // par founder-cockpit.js.
    if (cockpitPage === 'cockpit-clients-platform' && typeof window.renderPlatformClientsPage === 'function') {
      window.renderPlatformClientsPage(cockpitHost);
    } else if (cockpitPage === 'cockpit-centres' && typeof window.renderFounderCentresPage === 'function') {
      window.renderFounderCentresPage(cockpitHost);
    } else if (typeof renderStaffFounderCockpitPage === 'function') {
      renderStaffFounderCockpitPage(cockpitHost, cockpitPage);
    }
    return;
  }
  if (isStaffUtilityActive()) {
    document.body.style.overflow = '';
    if (pageReady('renderStaffUtilityPage')) renderStaffUtilityPage();
    return;
  }
  document.getElementById('searchInput').value = state.searchTerm || '';
  const planningBox = document.getElementById('planningBox');
  const laserPlanningBox = document.getElementById('laserPlanningBox');
  if (planningBox) planningBox.classList.toggle('expanded', !!state.staffPlanningExpanded);
  if (laserPlanningBox) laserPlanningBox.classList.toggle('expanded', !!state.staffLaserPlanningExpanded);
  const staffTableBox = document.getElementById('staffTableBox');
  if (staffTableBox) staffTableBox.classList.toggle('expanded', !!state.staffTableExpanded);
  const globalPlanningBox = document.getElementById('globalPlanningBox');
  if (globalPlanningBox) globalPlanningBox.classList.toggle('expanded', !!state.staffGlobalExpanded);
  syncExpandedPlanningControls();
  const planningToggle = document.getElementById('planningToggle');
  if (planningToggle) planningToggle.textContent = state.staffPlanningExpanded ? 'Réduire' : 'Agrandir';
  const laserPlanningToggle = document.getElementById('laserPlanningToggle');
  if (laserPlanningToggle) laserPlanningToggle.textContent = state.staffLaserPlanningExpanded ? 'Réduire' : 'Agrandir';
  const tableToggle = document.getElementById('tableToggle');
  if (tableToggle) tableToggle.textContent = state.staffTableExpanded ? 'Réduire' : 'Agrandir';
  const globalPlanningToggle = document.getElementById('globalPlanningToggle');
  if (globalPlanningToggle) globalPlanningToggle.textContent = state.staffGlobalExpanded ? 'Réduire' : 'Agrandir';
  document.body.style.overflow = state.view === 'staff' && (state.staffPlanningExpanded || state.staffLaserPlanningExpanded || state.staffTableExpanded || state.staffGlobalExpanded) ? 'hidden' : '';
  attachPlanningFullscreenResize();
  renderKpis();
  renderPlanning();
  renderLaserPlanning();
  renderGlobalPlanningSurface();
  renderTable();
}

// Recalcule le planning quand la fenêtre change de taille. Ce n'était attaché
// QUE pendant le plein écran, et c'était un trou : hors plein écran aussi, des
// décisions de rendu sont prises en pixels au moment du render (hauteur de
// ligne tactile sous 768px, hauteur des cartes). Redimensionner ou zoomer sans
// re-render laissait donc une grille calculée pour l'ancienne taille. Un seul
// écouteur, posé une fois, qui ne travaille que si le planning est à l'écran.
let planningFullscreenResizeHandler = null;

function attachPlanningFullscreenResize() {
  if (planningFullscreenResizeHandler) return;
  let raf = 0;
  planningFullscreenResizeHandler = () => {
    if (raf) cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => {
      raf = 0;
      if (state.view !== 'staff') return;
      if (state.staffLaserPlanningExpanded) { renderLaserPlanning(); return; }
      if (state.staffPlanningExpanded) { renderPlanning(); return; }
      if (document.getElementById('planningGridWrap')) renderPlanning();
      if (document.getElementById('laserPlanningGridWrap')) renderLaserPlanning();
    });
  };
  window.addEventListener('resize', planningFullscreenResizeHandler, { passive: true });
}

function detachPlanningFullscreenResize() {
  // Volontairement conservé : l'écouteur reste posé pour couvrir aussi le mode
  // fenêtre. Il se contente de ne rien faire quand le planning n'est pas visible.
}

function togglePlanningExpanded() {
  const next = !state.staffPlanningExpanded;
  state.staffPlanningExpanded = next;
  state.staffLaserPlanningExpanded = false;
  state.staffTableExpanded = false;
  state.staffGlobalExpanded = false;
  // « Des qu on repart sur le planning, on fait agrandir et ca revient
  // directement » (Movsar 2026-08-25) : le filtre repart sur Tout.
  state.staffStatusFilter = 'all';
  if (next) attachPlanningFullscreenResize();
  else detachPlanningFullscreenResize();
  save();
  renderStaff();
}

// L EN-TETE DU PLEIN ECRAN SUR UNE LIGNE (Movsar, 2026-10-08 : « l endroit
// pour changer la date et la reservation rapide sont en dessous de l entete,
// ca cree une entete super grosse, met tout sur une ligne »). La date se range
// a cote du titre, dans sa pile ; « + Réserver » rejoint les actions, avant
// « Réduire ». Le planning Laser a deja le sien (le prochain depart) : un
// second bouton y ferait doublon.
function syncExpandedPlanningControls() {
  for (const id of ['planningBox', 'laserPlanningBox', 'staffTableBox', 'globalPlanningBox']) {
    const box = document.getElementById(id);
    const head = box?.querySelector('.planning-head, .table-head');
    const pile = head?.querySelector('.planning-title-stack');
    const actions = head?.querySelector('.planning-actions, .table-actions');
    if (!pile || !actions) continue;
    let date = pile.querySelector(':scope > .pec-date');
    if (!date) { date = document.createElement('div'); date.className = 'pec-date'; pile.appendChild(date); }
    poserHtmlSurface(date, staffDateNavHtml({ court: true }));
    let creer = actions.querySelector(':scope > .planning-expanded-create');
    const avecCreer = id !== 'laserPlanningBox' && canUseStaffPermission('reservations.quick');
    if (avecCreer && !creer) {
      creer = document.createElement('button');
      creer.type = 'button';
      creer.className = 'btn-primary planning-expanded-create';
      creer.textContent = '+ Réserver';
      creer.setAttribute('onclick', "openQuickBook({date:state.currentDate,type:getStaffResourceView()==='laser'?'laser':'bowling'})");
      actions.insertBefore(creer, actions.querySelector(':scope > .planning-toggle'));
    }
    if (!avecCreer && creer) creer.remove();
  }
}

// La fermeture ne supprime pas des dossiers déjà enregistrés. Cette plage
// sert uniquement à les dessiner ; la disponibilité publique reste fermée.
function planningDisplayWindow(view) {
  const config = getPlanningWindow(state.currentDate);
  if (!config.closed) return config;
  const windows = todaysReservations().flatMap(r => view === 'laser' ? getLaserWindowsFromReservation(r) : getBowlingWindowsFromReservation(r));
  if (!windows.length) return config;
  return { ...config, open: Math.max(0, Math.floor(Math.min(...windows.map(w=>w.start)) * 2) / 2 - .5), close: Math.ceil(Math.max(...windows.map(w=>w.end)) * 2) / 2 + .5, closed: true, showExisting: true };
}

function planningClosedNotice(config) {
  return config.closed && config.showExisting ? '<div class="planning-closed-notice" role="status">Centre fermé ce jour · réservations existantes à contrôler. Aucun nouveau créneau disponible.</div>' : '';
}

function toggleLaserPlanningExpanded() {
  const next = !state.staffLaserPlanningExpanded;
  state.staffLaserPlanningExpanded = next;
  state.staffPlanningExpanded = false;
  state.staffTableExpanded = false;
  state.staffGlobalExpanded = false;
  state.staffStatusFilter = 'all';
  if (next) attachPlanningFullscreenResize();
  else detachPlanningFullscreenResize();
  save();
  renderStaff();
}

function collapseStaffPlanningFullscreen() {
  if (!state.staffPlanningExpanded && !state.staffLaserPlanningExpanded && !state.staffTableExpanded && !state.staffGlobalExpanded) return false;
  state.staffPlanningExpanded = false;
  state.staffLaserPlanningExpanded = false;
  state.staffTableExpanded = false;
  state.staffGlobalExpanded = false;
  state.staffStatusFilter = 'all';
  detachPlanningFullscreenResize();
  save();
  renderStaff();
  return true;
}

// PASSER D UNE SURFACE PLEIN ECRAN A UNE AUTRE SANS EN SORTIR (2026-08-26).
// Movsar : « ajoute une section en haut qu on puisse passer directement d un
// planning a l autre... comme ca on peut pager pour chaque ». Les trois
// surfaces sont exclusives : une seule porte .expanded a la fois, et la vue
// de ressource suit, sinon la boite ouverte serait masquee par
// syncStaffResourceTabs (qui cache planningBox des que la vue n est pas
// 'bowling').
function goFullscreenResource(cible) {
  const surface = ['bowling', 'laser', 'all'].includes(cible) ? cible : 'bowling';
  if (surface === 'bowling' && !canUseStaffPermission('planning.bowling')) { toast('Planning bowling non autorise.'); return; }
  if (surface === 'laser' && !canUseStaffPermission('planning.laser')) { toast('Planning laser non autorise.'); return; }
  state.staffResourceView = surface;
  state.staffPlanningExpanded = surface === 'bowling';
  state.staffLaserPlanningExpanded = surface === 'laser';
  // « Toutes » est le planning global (2026-10-12) : la liste garde son
  // propre « Agrandir ».
  state.staffTableExpanded = false;
  state.staffGlobalExpanded = surface === 'all';
  state.staffStatusFilter = 'all';
  save();
  renderStaff();
}

// « Toutes les reservations » s agrandit comme les plannings : plein ecran,
// liste seule, pour tout voir d un coup (review manager 2026-08-25).
function toggleTableExpanded() {
  const next = !state.staffTableExpanded;
  state.staffTableExpanded = next;
  state.staffPlanningExpanded = false;
  state.staffLaserPlanningExpanded = false;
  state.staffGlobalExpanded = false;
  state.staffStatusFilter = 'all';
  save();
  renderStaff();
}

// LE PLANNING GLOBAL (2026-10-12) : toutes les activites du jour dans la
// grille d heures du bowling, une colonne par activite
// (assets/pinlane-planning-global.js). Il s agrandit comme les deux autres,
// une seule surface plein ecran a la fois, et ne se dessine que sous son
// onglet : cache, il ne coute rien.
function toggleGlobalPlanningExpanded() {
  const next = !state.staffGlobalExpanded;
  state.staffGlobalExpanded = next;
  state.staffPlanningExpanded = false;
  state.staffLaserPlanningExpanded = false;
  state.staffTableExpanded = false;
  state.staffStatusFilter = 'all';
  save();
  renderStaff();
}

// LA LISTE SUIT LA TAILLE DU PLANNING AU-DESSUS D ELLE (2026-10-12). Sa
// hauteur se calcule sur sa position dans la page (ajusterHauteurListe).
// Rendue avant que le planning global ait pris sa taille, elle gardait un
// plafond de 480 px et defilait en elle-meme ; le rendu suivant la remettait
// a la hauteur de l ecran et la carte qu on venait de toucher sautait de
// 38 px (rush-status). Chaque changement de taille de la boite la recale.
let observateurPlanningGlobal = null;
function renderGlobalPlanningSurface() {
  const box = document.getElementById('globalPlanningBox');
  const wrap = document.getElementById('globalPlanningGridWrap');
  if (!box || !wrap || box.classList.contains('hidden') || typeof window.renderGlobalPlanning !== 'function') return;
  window.renderGlobalPlanning(wrap);
  ajusterHauteurListe();
  if (typeof ResizeObserver !== 'function' || (observateurPlanningGlobal && observateurPlanningGlobal.cible === box)) return;
  if (observateurPlanningGlobal) observateurPlanningGlobal.disconnect();
  observateurPlanningGlobal = new ResizeObserver(() => ajusterHauteurListe());
  observateurPlanningGlobal.cible = box;
  observateurPlanningGlobal.observe(box);
}

// La liste du jour vit sous le planning, comme sous les deux autres : « Voir
// la liste » y descend (en quittant le plein ecran s il le faut).
function voirListeDuJour() {
  closeStaffFloatingMenus();
  if (state.staffGlobalExpanded) toggleGlobalPlanningExpanded();
  document.getElementById('staffTableBox')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function toggleGlobalPlanningActionsMenu(event) {
  showStaffFloatingMenu(event, `
    <div class="staff-action-popover-title">Actions planning</div>
    <button type="button" onclick="toggleGlobalPlanningExpanded(); closeStaffFloatingMenus();">${state.staffGlobalExpanded ? 'Réduire le planning' : 'Agrandir le planning'}</button>
    <button type="button" onclick="voirListeDuJour()">Voir la liste des réservations</button>
    <button type="button" onclick="telechargerSecours('feuille'); closeStaffFloatingMenus();">Feuille de secours (PDF)</button>
    <button type="button" onclick="refreshStaffPlanning()">Actualiser les données</button>
    <button type="button" onclick="exportStaffPlanningCsv()">Exporter le jour en CSV</button>
    <button type="button" onclick="openQuickBook({ date: state.currentDate, type: 'bowling' }); closeStaffFloatingMenus();">Nouvelle réservation ici</button>
  `);
}

function setStaffStatusFilter(filter) {
  state.staffStatusFilter = normaliserFiltreListe(filter);
  save();
  repaintKeepingScroll(document.getElementById('staffView'), () => {
    renderPlanning();
    renderLaserPlanning();
    renderGlobalPlanningSurface();
    renderTable();
  });
}

function getPlanningVisibleReservations(view = getStaffResourceView()) {
  let reservations = todaysReservations().filter(r => reservationMatchesStaffResource(r, view));
  releaseDeadNoteFilter();
  reservations = filterReservationsForStaff(reservations, state.staffStatusFilter || 'all');
  const query = String(state.searchTerm || '').trim().toLowerCase();
  if (query) {
    reservations = reservations.filter(r => {
      const label = `${r.name || ''} ${r.phone || ''} ${getReservationLabel(r)} ${r.email || ''}`.toLowerCase();
      return label.includes(query);
    });
  }
  return reservations;
}

// Recherche planning/liste unifiée. Root cause du bug : les champs de recherche
// n'appelaient que renderTable() : le PLANNING (grille) et le planning Laser ne
// se re-filtraient jamais à la frappe (il fallait recharger), et l'effacement ne
// re-remplissait pas la grille (elle restait figée). On centralise ici : un seul
// state.searchTerm, on synchronise les champs jumeaux (bowling/laser/liste) sans
// voler le focus, puis on re-render planning + planning laser + liste. Débounce
// léger pour rester fluide à la frappe ; effacement = ré-affichage immédiat.
let staffSearchDebounceTimer = null;
function applyStaffSearch(value, opts = {}) {
  state.searchTerm = value;
  ['searchInput', 'planningSearchInput', 'laserPlanningSearchInput', 'globalPlanningSearchInput'].forEach(id => {
    const el = document.getElementById(id);
    if (el && el !== document.activeElement && el.value !== value) el.value = value;
  });
  const run = () => {
    save();
    if (state.view !== 'staff') return;
    renderPlanning();
    renderLaserPlanning();
    renderGlobalPlanningSurface();
    renderTable();
  };
  clearTimeout(staffSearchDebounceTimer);
  // Effacer (champ vide) = ré-affichage instantané du planning complet, sans délai.
  if (opts.immediate || !String(value || '').trim()) {
    run();
    return;
  }
  staffSearchDebounceTimer = setTimeout(run, 120);
}

function closeStaffFloatingMenus() {
  document.querySelectorAll('.staff-action-popover').forEach(menu => menu.remove());
}

function showStaffFloatingMenu(event, html) {
  event?.preventDefault?.();
  event?.stopPropagation?.();
  const current = document.querySelector('.staff-action-popover');
  if (current && current.dataset.anchor === event?.currentTarget?.className) {
    current.remove();
    return;
  }
  closeStaffFloatingMenus();
  const menu = document.createElement('div');
  menu.className = 'staff-action-popover';
  menu.dataset.anchor = event?.currentTarget?.className || 'staff-action';
  menu.innerHTML = html;
  document.body.appendChild(menu);
  const rect = event?.currentTarget?.getBoundingClientRect?.();
  if (rect) {
    const width = Math.min(260, Math.max(menu.offsetWidth || 220, 220));
    const left = Math.min(window.innerWidth - width - 12, Math.max(12, rect.right - width));
    const top = Math.min(window.innerHeight - 12, rect.bottom + 8);
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
  }
  setTimeout(() => document.addEventListener('click', closeStaffFloatingMenus, { once: true }), 0);
}

function applyPlanningStatusFilter(filter) {
  state.staffStatusFilter = normaliserFiltreListe(filter);
  save();
  closeStaffFloatingMenus();
  repaintKeepingScroll(document.getElementById('staffView'), () => renderStaff());
}

// LE MÊME FILTRE, DONC LES MÊMES MOTS ET LE MÊME CLASSEMENT QUE LA LISTE.
// Ce menu pilote `state.staffStatusFilter`, exactement comme les puces de la
// liste du jour : il nommait pourtant « Payées » ce que la liste appelle
// « Terminées », et rangeait « À gérer » entre deux états comme s'il en était
// un troisième. Un même filtre qui porte deux noms selon l'endroit où on le
// touche, c'est la même classe d'erreur que les compteurs qui ne se
// recomposent pas. Depuis le 2026-10-08 : les sections de la liste, dans son
// ordre et sous ses mots (STAFF_LISTE_MOTS).
function togglePlanningFilterMenu(event) {
  const active = normaliserFiltreListe(state.staffStatusFilter);
  const bouton = ([key, label]) => `<button type="button" class="${active === key ? 'active' : ''}" onclick="applyPlanningStatusFilter('${key}')">${label}</button>`;
  const etats = [['all', 'Toutes'], ...STAFF_LISTE_SECTIONS.map(cle => [cle, STAFF_LISTE_MOTS[cle]])];
  showStaffFloatingMenu(event, `
    <div class="staff-action-popover-title">Filtrer le planning</div>
    ${etats.map(bouton).join('')}
  `);
}

function refreshStaffPlanning() {
  closeStaffFloatingMenus();
  syncDateReservations(state.currentDate, { silent: true });
  renderStaff();
}

// scope « day » : toute la journee, hors annulations, quel que soit l onglet
// ou le filtre laisse sur le planning (l export des Parametres). Sans scope :
// ce que le planning montre.
function exportStaffPlanningCsv(scope = '') {
  if (!requireClientPermission('exports.download', 'Votre rôle ne permet pas de télécharger les exports.')) return;
  const source = scope === 'day' ? getStaffUtilityReservations() : getPlanningVisibleReservations();
  const rows = source.map(reservation => [
    reservation.date,
    reservation.startTime,
    reservation.name,
    reservation.phone || '',
    getReservationLabel(reservation),
    reservation.pax || 0,
    getStaffResourceWindows(reservation, 'all').map(window => window.resourceType === 'laser_arena'
      ? `Laser ${formatClockDisplay(window.start)}-${formatClockDisplay(window.end)}`
      : `Pistes ${(window.lanes || []).join(' ')} ${formatClockDisplay(window.start)}-${formatClockDisplay(window.end)}`).join(' / '),
    getStaffReservationStateLabel(reservation),
    reservation.price || 0
  ]);
  const header = ['Date', 'Heure', 'Client', 'Téléphone', 'Offre', 'Joueurs', 'Ressources', 'Statut', 'Montant'];
  downloadTextFile(`${getCurrentStaffCenterId()}-planning-${state.currentDate || todayStr()}.csv`, [header.map(csvCell).join(','), ...rows.map(row => row.map(csvCell).join(','))].join('\n'), 'text/csv;charset=utf-8');
  closeStaffFloatingMenus();
}

function togglePlanningActionsMenu(event) {
  showStaffFloatingMenu(event, `
    <div class="staff-action-popover-title">Actions planning</div>
    <button type="button" onclick="togglePlanningExpanded(); closeStaffFloatingMenus();">${state.staffPlanningExpanded ? 'Réduire le planning' : 'Agrandir le planning'}</button>
    <button type="button" onclick="refreshStaffPlanning()">Actualiser les données</button>
    <button type="button" onclick="exportStaffPlanningCsv()">Exporter le jour en CSV</button>
    <button type="button" onclick="openQuickBook({ date: state.currentDate, type: getStaffResourceView() === 'laser' ? 'laser' : 'bowling' }); closeStaffFloatingMenus();">Nouvelle réservation ici</button>
  `);
}

function setStaffResourceView(view) {
  state.staffResourceView = ['all', 'bowling', 'laser'].includes(view) ? view : 'all';
  state.staffMenuPage = 'planning';
  setStaffRouteHash('planning', state.staffResourceView);
  syncOpsSidebar();
  save();
  renderStaff();
}

// Calendrier custom (popover) : remplace le picker natif <input type=date>
// dont showPicker() ancrait la surface au coin haut-gauche quand l'input etait
// masque sur les pages Terrain. Ici la position est calculee et CONTROLEE
// (positionStaffCalendar : ancree sous le declencheur, maintenue dans le
// viewport), la surface est stylee aux tokens, clavier + aria.
let staffCalTrigger = null;
let staffCalAnchor = null;
let staffCalMonth = null;
// Contexte quand ce calendrier sert une AUTRE surface que la date staff :
// { value, min, onPick }. null = comportement historique (state.currentDate).
// C'est ce qui permet au tunnel client de reutiliser ce composant au lieu d'en
// avoir un deuxieme a maintenir.
let staffCalContext = null;

const STAFF_CAL_CHEVRON_LEFT = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="15 18 9 12 15 6"/></svg>';
const STAFF_CAL_CHEVRON_RIGHT = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="9 18 15 12 9 6"/></svg>';

// Widget date reutilisable : navigation jour (fleches), label cliquable qui
// ouvre le calendrier custom, bouton Aujourd'hui. Le MEME controle sur toutes
// les surfaces staff (planning, dashboard, pages Terrain).
// `court` : l annee de l annee en cours se tait (l en-tete du plein ecran,
// ou chaque pixel compte) ; celle d une autre annee reste dite.
function staffDateNavHtml({ court = false } = {}) {
  const d = parseLocalDate(state.currentDate || todayStr());
  const autreAnnee = d.getFullYear() !== parseLocalDate(todayStr()).getFullYear();
  const shortText = d.toLocaleDateString('fr-BE', { weekday: 'short', day: 'numeric', month: 'short', ...(court && !autreAnnee ? {} : { year: 'numeric' }) }).replace(',', '');
  const label = shortText.charAt(0).toUpperCase() + shortText.slice(1);
  return `<div class="staff-date-widget">
      <div class="date-nav">
        <button type="button" aria-label="Jour précédent" onclick="shiftDate(-1)">${STAFF_CAL_CHEVRON_LEFT}</button>
        <button type="button" class="staff-date-label" aria-haspopup="dialog" title="Choisir une date" onclick="openStaffCalendar(event)">${escapeHtml(label)}</button>
        <button type="button" aria-label="Jour suivant" onclick="shiftDate(1)">${STAFF_CAL_CHEVRON_RIGHT}</button>
      </div>
      <button type="button" class="staff-today-btn" onclick="setStaffToday()">Aujourd'hui</button>
    </div>`;
}

function getStaffCalendarValue() {
  if (staffCalContext) return staffCalContext.value || todayStr();
  return state.currentDate || todayStr();
}

function renderStaffCalendar(dateISO) {
  const selected = dateISO || getStaffCalendarValue();
  const min = staffCalContext && staffCalContext.min ? String(staffCalContext.min) : '';
  const view = staffCalMonth || getMonthKey(selected);
  const [vy, vm] = view.split('-').map(Number);
  const today = todayStr();
  const months = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];
  const title = `${months[vm - 1]} ${vy}`;
  const first = new Date(vy, vm - 1, 1);
  const startOffset = (first.getDay() + 6) % 7; // grille lundi -> dimanche
  const daysInMonth = new Date(vy, vm, 0).getDate();
  const dows = ['Lu', 'Ma', 'Me', 'Je', 'Ve', 'Sa', 'Di'];
  const cells = [];
  for (let i = 0; i < startOffset; i += 1) cells.push('');
  for (let day = 1; day <= daysInMonth; day += 1) cells.push(day);
  const dayCells = cells.map(day => {
    if (day === '') return '<span class="staff-cal-day is-out" aria-hidden="true"></span>';
    const iso = `${vy}-${String(vm).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const classes = ['staff-cal-day'];
    if (iso === today) classes.push('is-today');
    if (iso === selected) classes.push('is-selected');
    // Un jour hors bornes se DESACTIVE au lieu de disparaitre : le mois garde
    // sa forme, et le refus est lisible avant le clic (le tunnel n'accepte pas
    // une date passee, la console n'a pas de borne).
    const blocked = Boolean(min) && iso < min;
    if (blocked) classes.push('is-blocked');
    const current = iso === selected ? ' aria-current="date"' : '';
    const guard = blocked ? ' disabled aria-disabled="true"' : '';
    return `<button type="button" class="${classes.join(' ')}"${current}${guard} onclick="staffCalendarPick('${iso}')">${day}</button>`;
  }).join('');
  return `<div class="staff-cal-head">
      <button type="button" class="staff-cal-nav" aria-label="Mois précédent" onclick="staffCalendarShiftMonth(-1)">${STAFF_CAL_CHEVRON_LEFT}</button>
      <div class="staff-cal-title">${escapeHtml(title.charAt(0).toUpperCase() + title.slice(1))}</div>
      <button type="button" class="staff-cal-nav" aria-label="Mois suivant" onclick="staffCalendarShiftMonth(1)">${STAFF_CAL_CHEVRON_RIGHT}</button>
    </div>
    <div class="staff-cal-grid" role="grid">
      ${dows.map(dow => `<div class="staff-cal-dow" role="columnheader">${dow}</div>`).join('')}
      ${dayCells}
    </div>
    <div class="staff-cal-foot">
      <button type="button" class="staff-cal-today-btn" onclick="staffCalendarPickToday()">Aujourd'hui</button>
    </div>`;
}

// Positionnement FIABLE : ancre sous le declencheur (rect capture a l'ouverture)
// et reste dans le viewport (rabat a gauche/au-dessus si ca deborde).
function positionStaffCalendar(pop, anchor) {
  const margin = 8;
  const gap = 6;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const width = pop.offsetWidth || 300;
  const height = pop.offsetHeight || 320;
  let left = anchor.left;
  if (left + width > vw - margin) left = vw - margin - width;
  if (left < margin) left = margin;
  let top = anchor.bottom + gap;
  if (top + height > vh - margin && anchor.top - gap - height >= margin) {
    top = anchor.top - gap - height;
  }
  if (top + height > vh - margin) top = Math.max(margin, vh - margin - height);
  if (top < margin) top = margin;
  pop.style.left = `${Math.round(left)}px`;
  pop.style.top = `${Math.round(top)}px`;
}

function openStaffCalendar(ev, options = null) {
  ev?.preventDefault?.();
  ev?.stopPropagation?.();
  const trigger = ev && (ev.currentTarget || ev.target);
  const existing = document.querySelector('.staff-calendar-pop');
  if (existing) {
    const sameTrigger = staffCalTrigger === trigger;
    closeStaffCalendar();
    if (sameTrigger) return; // re-clic sur le meme declencheur = fermer
  }
  const rect = trigger && typeof trigger.getBoundingClientRect === 'function' ? trigger.getBoundingClientRect() : null;
  staffCalTrigger = trigger || null;
  staffCalContext = options && typeof options.onPick === 'function' ? { ...options } : null;
  staffCalAnchor = rect
    ? { left: rect.left, right: rect.right, top: rect.top, bottom: rect.bottom }
    : { left: 12, right: 12, top: 12, bottom: 12 };
  staffCalMonth = getMonthKey(getStaffCalendarValue());
  const pop = document.createElement('div');
  pop.className = 'staff-calendar-pop';
  pop.setAttribute('role', 'dialog');
  pop.setAttribute('aria-modal', 'false');
  pop.setAttribute('aria-label', 'Choisir une date');
  pop.innerHTML = renderStaffCalendar(getStaffCalendarValue());
  document.body.appendChild(pop);
  positionStaffCalendar(pop, staffCalAnchor);
  const focusTarget = pop.querySelector('.staff-cal-day.is-selected')
    || pop.querySelector('.staff-cal-day.is-today')
    || pop.querySelector('.staff-cal-day');
  if (focusTarget) focusTarget.focus();
  setTimeout(() => {
    document.addEventListener('click', staffCalendarOutside, true);
    document.addEventListener('keydown', staffCalendarKeydown, true);
  }, 0);
}

function staffCalendarShiftMonth(delta) {
  const view = staffCalMonth || getMonthKey(getStaffCalendarValue());
  const [vy, vm] = view.split('-').map(Number);
  const moved = new Date(vy, vm - 1 + delta, 1);
  staffCalMonth = `${moved.getFullYear()}-${String(moved.getMonth() + 1).padStart(2, '0')}`;
  const pop = document.querySelector('.staff-calendar-pop');
  if (!pop) return;
  pop.innerHTML = renderStaffCalendar(getStaffCalendarValue());
  if (staffCalAnchor) positionStaffCalendar(pop, staffCalAnchor);
}

function staffCalendarPick(dateISO) {
  const handoff = staffCalContext && staffCalContext.onPick;
  closeStaffCalendar();
  if (handoff) { handoff(dateISO); return; }
  setStaffDateFromPicker(dateISO); // logique existante : currentDate + save + renderStaff + sync
}

function staffCalendarPickToday() {
  staffCalendarPick(todayStr());
}

function staffCalendarOutside(ev) {
  const pop = document.querySelector('.staff-calendar-pop');
  if (!pop) return;
  if (pop.contains(ev.target)) return;
  if (staffCalTrigger && staffCalTrigger.contains && staffCalTrigger.contains(ev.target)) return;
  closeStaffCalendar();
}

function staffCalendarKeydown(ev) {
  if (ev.key !== 'Escape' && ev.key !== 'Esc') return;
  ev.preventDefault();
  const trigger = staffCalTrigger;
  closeStaffCalendar();
  if (trigger && typeof trigger.focus === 'function') trigger.focus();
}

function closeStaffCalendar() {
  document.querySelectorAll('.staff-calendar-pop').forEach(pop => pop.remove());
  document.removeEventListener('click', staffCalendarOutside, true);
  document.removeEventListener('keydown', staffCalendarKeydown, true);
  staffCalTrigger = null;
  staffCalAnchor = null;
  staffCalContext = null;
}

// ---- LE CALENDRIER DU TUNNEL CLIENT ---------------------------------------
//
// showPicker() JETTE dans une iframe cross-origin. Ce n'est pas un incident,
// c'est la specification : « showPicker() called from cross-origin iframe ».
// Or le tunnel vit EXACTEMENT la : mesure faite le 2026-08-21 sur le vrai site
// de N4 (n4-bowling.vercel.app embarque app.pinlane.be), le clic sur le bouton
// calendrier levait SecurityError et le repli focus() ne montrait rien sur
// ordinateur. Le bouton existait, il ne faisait rien : « on peut pas cliquer ».
//
// On ouvre donc le calendrier MAISON, celui qui sert deja la console : une
// seule implementation a maintenir, elle ne depend d'aucune API du navigateur,
// et elle prend les couleurs du centre (les jetons de marque sont poses sur
// :root par boot-view.js). Le champ reste un input[type=date] : la saisie au
// clavier ne bouge pas. AU DOIGT (pointer: coarse), le bouton n existe plus
// (CSS, bloc mobile v2) : tout le champ ouvre le selecteur natif du telephone,
// en UN geste. Avant, le bouton ouvrait le calendrier maison PUIS focalisait
// le champ, et iOS ouvrait le sien par-dessus (Movsar : « on doit choisir
// deux fois »).
function openClientDateCalendar(ev) {
  const input = document.getElementById('fDate');
  if (!input) return;
  const floor = input.min || todayStr();
  openStaffCalendar(ev, {
    value: input.value || floor,
    min: floor,
    onPick: (iso) => {
      input.value = iso;
      // Meme evenement que la saisie clavier : tout ce qui ecoute la date
      // (horaires du jour, creneaux, garde anti-date-passee) part d'ici.
      input.dispatchEvent(new Event('change', { bubbles: true }));
      // Jamais de focus au doigt : sur iPhone il rouvrait le selecteur natif
      // par-dessus le jour deja choisi (« on doit choisir deux fois »).
      if (pointeurFin()) input.focus();
    },
  });
}
if (typeof window !== 'undefined') window.openClientDateCalendar = openClientDateCalendar;

function setStaffDateFromPicker(value) {
  if (!value) return;
  state.currentDate = value;
  state.staffStatusFilter = 'all';
  save();
  renderStaff();
  syncDateReservations(state.currentDate, { silent: true });
}

function shiftDate(delta) {
  const nextDate = addDays(state.currentDate, delta);
  state.currentDate = nextDate;
  // Changer de jour = repartir sur « Tout » : le filtre d hier ne doit pas
  // vider la journee d aujourd hui en silence.
  state.staffStatusFilter = 'all';
  save();
  renderStaff();
  syncDateReservations(state.currentDate, { silent: true });
}

function todaysReservations() {
  return state.reservations.filter(r => r.date === state.currentDate && r.status !== 'cancelled');
}

function getStaffResourceView() {
  return state.staffResourceView === 'laser' ? 'laser' : state.staffResourceView === 'all' ? 'all' : 'bowling';
}

function getStaffResourceWindows(reservation, view = getStaffResourceView()) {
  if (view === 'all') {
    return [...getBowlingWindowsFromReservation(reservation), ...getLaserWindowsFromReservation(reservation)]
      .sort((left, right) => Number(left.start) - Number(right.start));
  }
  return view === 'laser'
    ? getLaserWindowsFromReservation(reservation)
    : getBowlingWindowsFromReservation(reservation);
}

function reservationMatchesStaffResource(reservation, view = getStaffResourceView()) {
  if (view === 'all') return true;
  return getStaffResourceWindows(reservation, view).length > 0;
}

// « Hors planning » : la reservation n'occupe NI piste bowling NI zone laser,
// donc elle n'apparait sur AUCUNE des deux grilles. C'est le cas des formules
// table + plaine de jeux (f6/f7/f8) et du Kids Fun Day : le staff ne les voyait
// nulle part, noyees dans la liste du jour. Elles ont maintenant leur zone en
// tete de l'onglet « Toutes les reservations ».
// Exception VOULUE : une partie laser non encore placee n'est pas hors planning,
// elle attend deja dans le tiroir « a placer » du planning laser.
function isOffPlanningReservation(reservation) {
  if (!reservation) return false;
  if (getBowlingWindowsFromReservation(reservation).length) return false;
  if (getLaserWindowsFromReservation(reservation).length) return false;
  return getLaserGameCountForReservation(reservation) === 0;
}

function scopedStaffReservations(view = getStaffResourceView()) {
  return todaysReservations().filter(r => reservationMatchesStaffResource(r, view));
}

// UN SEUL endroit qui synchronise la bande d'onglets (onglet actif, compteurs,
// alerte hors planning, visibilite des grilles). renderStaffShell et
// renderStaffData en tenaient chacun une copie : deux verites qui pouvaient
// diverger en silence au premier changement de regle.
// Regle de visibilite : une grille ne s'affiche que sur SON onglet. « Toutes les
// reservations » n'est plus un empilement des deux plannings mais la liste du
// jour, hors planning en tete.
// LES BLOCS DU PLANNING SUIVAIENT LE VISITEUR PARTOUT (2026-08-14, 2e passe).
// Movsar : « j'ai toujours cette colonne qui s'affiche partout sur toutes les
// categories ». Le premier correctif etait bon mais il etait ANNULE : ce
// parametre valait `false` par defaut, et l'appelant de `renderStaffDay` ne le
// passait pas. Un appelant qui oublie l'argument re-affichait donc les trois
// blocs sur n'importe quelle page.
//
// La regle : une fonction qui doit connaitre l'etat de l'application le DEDUIT,
// elle ne l'accepte pas d'un appelant qui peut l'oublier. Un defaut permissif
// transforme chaque oubli futur en bug visible par l'utilisateur.
function isStaffPlanningPageActive() {
  return !(isStaffDashboardActive() || isStaffReservationsActive() || isStaffClientsActive()
    || isStaffPricingActive() || isStaffEmailsActive() || isStaffCampaignsActive()
    || isStaffUtilityActive() || isStaffCockpitActive());
}

function syncStaffResourceTabs(dayReservations = todaysReservations(), view = getStaffResourceView()) {
  const hiddenByPage = !isStaffPlanningPageActive();
  const bowlingCount = dayReservations.filter(r => getBowlingWindowsFromReservation(r).length > 0).length;
  const laserCount = dayReservations.filter(r => getLaserWindowsFromReservation(r).length > 0).length;
  const offPlanningCount = dayReservations.filter(isOffPlanningReservation).length;
  const allTab = document.getElementById('staffTabAll');
  allTab?.classList.toggle('active', view === 'all');
  allTab?.classList.toggle('has-alert', offPlanningCount > 0);
  document.getElementById('staffTabBowling')?.classList.toggle('active', view === 'bowling');
  document.getElementById('staffTabLaser')?.classList.toggle('active', view === 'laser');
  const allSub = document.getElementById('staffAllSub');
  if (allSub) {
    allSub.textContent = offPlanningCount
      ? `${offPlanningCount} hors planning`
      : 'Le jour au complet';
    allSub.classList.toggle('is-alert', offPlanningCount > 0);
  }
  const allCountEl = document.getElementById('staffAllCount');
  const bowlingCountEl = document.getElementById('staffBowlingCount');
  const laserCountEl = document.getElementById('staffLaserCount');
  if (allCountEl) allCountEl.textContent = dayReservations.length;
  if (bowlingCountEl) bowlingCountEl.textContent = bowlingCount;
  if (laserCountEl) laserCountEl.textContent = laserCount;
  // ---- UN ONGLET DE RESSOURCE QUE LE CENTRE N'A PAS EST UNE PROMESSE VIDE --
  //
  // Ces deux onglets etaient ecrits en dur dans index.html, sous-titres
  // compris : « 8 pistes » et « 2 zones », c'est-a-dire l'installation de Fun
  // Galaxy annoncee a tous les centres. N4 n'a AUCUNE arene laser
  // (weaponCount 0) et voyait quand meme son planning laser.
  const centerResources = (typeof getAdminCenter === 'function' ? (getAdminCenter() || {}).resources : null) || {};
  const laneCount = Number(centerResources.bowling && centerResources.bowling.laneCount) || 0;
  const weaponCount = Number(centerResources.laser && centerResources.laser.weaponCount) || 0;
  // La CLE ABSENTE veut dire « on ne sait pas encore » : le repli neutre de
  // getAdminCenter rend `resources: {}`, et le prendre pour « ce centre n'a
  // rien » masquait les deux onglets d'un centre parfaitement equipe. La cle
  // presente a null, elle, dit bien que la ressource n'existe pas.
  const knows = (kind) => Object.prototype.hasOwnProperty.call(centerResources, kind);
  const hasBowling = !knows('bowling') || laneCount > 0;
  const hasLaser = !knows('laser') || weaponCount > 0;
  document.getElementById('staffTabBowling')?.classList.toggle('hidden', hiddenByPage || !hasBowling);
  document.getElementById('staffTabLaser')?.classList.toggle('hidden', hiddenByPage || !hasLaser);
  const bowlingSub = document.getElementById('staffBowlingSub');
  if (bowlingSub && knows('bowling')) bowlingSub.textContent = laneCount ? `${laneCount} piste${laneCount > 1 ? 's' : ''}` : '';
  const laserSub = document.getElementById('staffLaserSub');
  if (laserSub && knows('laser')) laserSub.textContent = weaponCount ? `${weaponCount} arme${weaponCount > 1 ? 's' : ''}` : '';
  // Rester sur la vue d'une ressource absente afficherait une grille vide sans
  // rien dire : on retombe sur la journee complete, qui existe toujours.
  if (view === 'laser' && !hasLaser) view = 'all';
  if (view === 'bowling' && !hasBowling) view = 'all';
  document.getElementById('planningBox')?.classList.toggle('hidden', hiddenByPage || view !== 'bowling');
  document.getElementById('laserPlanningBox')?.classList.toggle('hidden', hiddenByPage || view !== 'laser');
  // « Toutes » montre le planning global (2026-10-12), la liste du jour en dessous.
  document.getElementById('globalPlanningBox')?.classList.toggle('hidden', hiddenByPage || view !== 'all');
  // LA LISTE DU JOUR SUIVAIT LE VISITEUR PARTOUT (2026-08-14). Movsar :
  // « le truc reservations s'affiche sur toutes les categories ». Les deux
  // plannings etaient masques au changement de page ; la boite de la liste
  // n'entrait pas dans la regle et n'avait meme pas d'identifiant, donc elle
  // restait peinte sous Vue d'ensemble, Reservations, Terrain, Clients...
  // Regle a retenir : tout bloc de la page Planning se masque par la MEME
  // decision. Un bloc qu'on oublie de rattacher a cette decision est visible
  // par defaut, et personne ne le voit en relisant le code.
  document.getElementById('staffTableBox')?.classList.toggle('hidden', hiddenByPage);
  // La barre du plein ecran porte les MEMES compteurs que les onglets : en
  // plein ecran, ils sont la seule facon de voir ce que contiennent les deux
  // autres surfaces avant d y aller.
  const comptes = {
    bowling: document.getElementById('staffBowlingCount')?.textContent || '',
    laser: document.getElementById('staffLaserCount')?.textContent || '',
    all: document.getElementById('staffAllCount')?.textContent || '',
  };
  document.querySelectorAll('[data-fs-count]').forEach((el) => {
    const valeur = comptes[el.dataset.fsCount];
    el.textContent = valeur && valeur !== '0' ? valeur : '';
  });
}

function getReservationFirstResourceStart(reservation, view = getStaffResourceView()) {
  const windows = getStaffResourceWindows(reservation, view);
  if (!windows.length) return timeToNum(reservation.startTime);
  return Math.min(...windows.map(window => Number(window.start)));
}

function getFormulaLaserGameCount(formule) {
  if (!formule) return 0;
  return (formule.desc || []).reduce((max, line) => {
    const text = normalizeActivityText(line);
    if (!text.includes('laser game')) return max;
    const match = text.match(/(\d+)\s*part/);
    return Math.max(max, match ? Number(match[1]) : 1);
  }, 0);
}

// COMBIEN DE PARTIES DE LASER CE GROUPE A-T-IL ACHETEES.
// Movsar, 2026-08-20 : « on met laser et on choisit plusieurs parties, ça
// affiche que 1 partie dans les réservations et sur le planning ». Une VISITE
// (plusieurs activites dans une reservation) porte son laser dans
// `program.items`, pas dans un id de formule : son type vaut 'bowling' des
// qu'elle contient du bowling, donc les deux branches ci-dessous rendaient
// zero. Le compte tombait a 0, la « x3 » disparaissait, les parties non placees
// n'entraient pas dans la file d'attente, et deux parties payees devenaient
// invisibles pour le comptoir.
// Le PROGRAMME fait foi (c'est ce qui a ete vendu), puis la formule.
function getLaserGameCountForReservation(reservation) {
  const programGames = getProgramLaserGameCount(reservation);
  if (programGames) return programGames;
  if (reservation.type === 'laser') return getLaserGameCount(Number(reservation.duration) || 0.5);
  const formule = reservation.formuleId ? resolveDisplayFormule(reservation.formuleId) : null;
  return getFormulaLaserGameCount(applyReservationFormulaChoice(formule, reservation));
}

// La duree d UN BLOC de bowling (le premier). C est ce que demandent les
// chemins qui MANIPULENT un bloc : le glisser-deposer du planning replace un
// bloc, pas la somme de la visite. Sa semantique n a jamais change ; la somme
// vit dans getBowlingTotalHoursForReservation, juste en dessous.
function getBowlingDurationForReservation(reservation) {
  const windows = getBowlingWindowsFromReservation(reservation);
  if (windows.length) return Number(windows[0].duration) || 0;
  const formule = reservation.formuleId ? resolveDisplayFormule(reservation.formuleId) : null;
  if (formule) return formule.hasBowling ? Number(formule.bowlingDur || 1) : 0;
  if (reservation.type !== 'bowling') return 0;
  return Number(reservation.duration || 0);
}

// Le TEMPS DE JEU VENDU : la somme des fenetres DISTINCTES dans le temps (une
// meme fenetre sur deux pistes reste un seul bloc). C est ce qu on ECRIT au
// comptoir (Movsar 2026-08-26 : « ca met 1 heure alors que ca donne 2 heures
// de bowling ») ; jamais ce qu on donne a un calcul de placement.
function getBowlingTotalHoursForReservation(reservation) {
  const windows = getBowlingWindowsFromReservation(reservation);
  if (!windows.length) return getBowlingDurationForReservation(reservation);
  const vues = new Set();
  let total = 0;
  windows.forEach(w => {
    const cle = `${w.start}-${w.end}`;
    if (vues.has(cle)) return;
    vues.add(cle);
    total += Number(w.duration) || 0;
  });
  return total;
}

// Palier d'emphase effectif selon la taille du groupe. Escalade en niveaux de
// gris + graisse (grp-l/grp-xl deviennent des pastilles pleines) pour repérer
// un gros groupe d'un coup d'œil, sans introduire une 2e couleur vive à côté de
// la durée (design system : un seul accent chaud = ambre pour la durée).
//   ≤6 neutre · 7-14 semi-gras · 15-29 pastille · 30+ pastille inversée.
function getGroupSizeClass(pax) {
  const n = Number(pax) || 0;
  if (n >= 30) return 'grp-xl';
  if (n >= 15) return 'grp-l';
  if (n >= 7) return 'grp-m';
  return 'grp-s';
}

// Durée bowling « standard » = 1h (neutre). Toute autre durée (30 min, 1h30,
// 2h…) est signalée pour attirer l'œil du staff.
function isSpecialBowlingDuration(duration) {
  const d = Number(duration) || 0;
  return d > 0 && Math.abs(d - 1) > 0.01;
}

// Densité d'info d'une carte bowling dérivée de sa HAUTEUR réelle (durée × zoom
// du planning). Une seule classe pilote l'affichage responsive côté CSS :
//   dens-xs : très petite (≈30 min) → nom tronqué + effectif + durée, 1 ligne.
//   dens-md : moyenne (≈1h)         → nom + activité + effectif + durée.
//   dens-lg : grande (1h30/2h+)     → tout, aéré (+ tags en plein écran).
// En plein écran les cellules sont plus hautes ET les polices plus grandes :
// on ne descend jamais sous dens-md pour afficher davantage de détail.
function getBookingDensityClass(height, expanded) {
  if (expanded) {
    // Polices plus grandes en plein écran : une cellule très courte (≈30 min)
    // ne tient toujours pas 2 lignes → ligne unique essentielle. Les créneaux
    // plus longs profitent de la hauteur pour afficher davantage de détail.
    // LES SEUILS SE MESURENT SUR LES POLICES DU PLEIN ECRAN (2026-10-09). Ils
    // valaient 54 et 108 px : sur un ecran de 950 px une heure fait 50 px de
    // carte, et chaque reservation d une heure tombait sur UNE ligne de 11 px,
    // une carte de 2 h sur deux, au milieu d un vide (Movsar : « les cartes du
    // planning bowling, a ameliorer »). Deux lignes demandent nom 17,25 +
    // gouttiere 2 + pied 14,4 + marges 11 + bordures 2 = 46,65 px ; trois,
    // avec le nom sur deux lignes (34,8) et l offre (15,4), 79,6 px.
    if (height < 47) return 'dens-xs';
    return height >= 80 ? 'dens-lg' : 'dens-md';
  }
  // LE SEUIL D'UNE LIGNE EST CELUI OU DEUX LIGNES NE TIENNENT PLUS, et il se
  // MESURE. Il valait 40px, choisi avant que la carte porte son contenu actuel :
  // deux lignes (nom 13,8px + gouttiere 2px + chiffres 12px + 11px de calage
  // vertical) en demandent 43. Une carte de 42px partait donc en deux lignes et
  // son contenu sortait par le bas, a 4 pistes et 150 % de zoom. 46px laisse
  // 44px utiles, soit un pixel de marge sur les 43 mesures.
  if (height < 46) return 'dens-xs';
  if (height < 66) return 'dens-md';
  return 'dens-lg';
}

// ÉTAT DE LA RÉSERVATION SUR LA CARTE, ET IL NE TIENT PLUS À LA COULEUR SEULE.
// Le fond et la barre de gauche disaient l'état à eux seuls : bleu = confirmé,
// ambre = arrivé, vert = payé, avec une légende en haut du panneau. DESIGN.md §7
// l'interdit (« pas d'info portée par la couleur seule »), et un gérant
// deutéranope confond exactement ces deux-là, l'ambre et le vert.
// Le repère porte donc une FORME distincte par état, plus un libellé lu par la
// synthèse vocale. « Confirmé » est l'état par défaut : il ne reçoit aucun
// repère, parce qu'un écran où tout est marqué est un écran où rien ne ressort.
const BOOKING_STATE_MARKS = {
  // Arrivé : la flèche qui entre. C'est la question du comptoir.
  arr: { label: 'Arrivé', path: '<path d="M3 12h10"/><path d="M9 8l4 4-4 4"/><path d="M17 4v16"/>' },
  // Payé : la coche. Le dossier est clos.
  paid: { label: 'Payé', path: '<path d="M20 6 9 17l-5-5"/>' },
};
function renderBookingStateMark(cls) {
  const mark = BOOKING_STATE_MARKS[cls];
  if (!mark) return '';
  return `<span class="bk-state" role="img" aria-label="${mark.label}" title="${mark.label}">`
    + `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${mark.path}</svg>`
    + `</span>`;
}

// Durée d'une carte de planning : forme COMPACTE et de largeur BORNÉE (`0h30`,
// `1h`, `1h30`), là où `formatDurationLabel` rend « 30 min » pour la demi-heure.
// Deux raisons, et la seconde n'est pas cosmétique.
// (1) La grille est un tableau de données : DESIGN.md §4 veut du Geist Mono
//     tabulaire, or « 30 min » mélange chiffres, lettre et espace et ne
//     s'aligne avec rien dans la colonne.
// (2) Surtout, sa largeur DÉCIDE : c'est elle qui fixe le plancher en dessous
//     duquel la durée doit céder la place au nom sur une carte d'une seule
//     ligne. Mesuré : « 30 min » occupe 51,6px contre 38,4px au pire pour la
//     forme compacte. Une largeur bornée rend ce plancher CALCULABLE au lieu
//     d'être deviné, et c'est tout l'objet de la correction du 2026-08-13.
// Le libellé long reste dans l'infobulle : aucune information ne se perd.
function formatCardDurationLabel(hours) {
  const totalMinutes = Math.max(0, Math.round((Number(hours) || 0) * 60));
  const h = Math.floor(totalMinutes / 60);
  const m = totalMinutes % 60;
  return m ? `${h}h${String(m).padStart(2, '0')}` : `${h}h`;
}

// ON N'AFFICHE JAMAIS UN FRAGMENT DE MOT DANS UNE ÉTIQUETTE.
// Movsar, 2026-08-13, en regardant la prod : « tu as encore tout qui est coupé
// même en agrandi, genre "Bowling Classique" c'est coupé. Des petits trucs qui
// font cheap. » Un mot coupé en deux est PIRE qu'un mot absent : il oblige à
// deviner, et il signe un logiciel qu'on n'a pas fini.
//
// La cause n'était pas un seuil de mise en page : c'était la LONGUEUR du texte.
// Le défaut métier d'une réservation bowling est « Bowling Classique », dix-sept
// caractères, soit environ 84px là où une piste de 127px en offre quarante.
// Aucune règle de mise en page ne fait tenir ça : il fallait raccourcir le
// texte, pas ruser avec la place. On coupe donc par MOTS ENTIERS, jamais au
// milieu d'un mot, et le libellé complet reste dans l'infobulle et dans la
// fiche, où on a la place de le lire.
// ET LA COUPE PAR MOTS NE SUFFISAIT PAS : LA CSS RECOUPAIT DERRIERE.
// Movsar, 2026-08-14, capture en fenetre AGRANDIE : « Camille Laurent · Bowl…
// · ✓ · 6j · 1h ». Le raccourcissement ci-dessous marchait pourtant : il rend
// « Bowling », sept lettres entieres. C'est `text-overflow: ellipsis` qui
// recoupait ce mot deja court des que la place manquait. Raccourcir le TEXTE
// et laisser la mise en page le retailler, c'est deux regles qui se
// contredisent, et c'est toujours la seconde qui gagne.
//
// La regle est donc devenue binaire : ENTIER OU ABSENT. Le texte vit dans un
// enfant que le CSS n'affiche que si la place qui RESTE peut le contenir en
// entier ; sinon il n'y a rien du tout, et jamais un morceau. La classe de
// longueur (`lab-s` / `lab-m` / `lab-l`) porte le seul chiffre dont le CSS a
// besoin pour trancher : combien de caracteres il doit loger. Le libelle
// complet reste dans l'infobulle et dans la fiche.
function renderCardActivityTag(reservation, view = 'bowling') {
  // L infobulle dit l offre entiere, sa variante comprise (nomDeLaFormuleAchetee).
  const complet = nomDeLaFormuleAchetee(reservation, String(getReservationLabel(reservation) || '').trim());
  const texte = getPlanningCardOfferLabel(reservation, view);
  // La boite reste, meme vide : c'est elle qui absorbe la place libre et
  // repousse les chiffres a droite. Sans elle, le pied se recollerait au nom.
  // L'offre a maintenant sa propre ligne : quand il n'y a rien a dire, la ligne
  // n'existe pas du tout, au lieu de reserver un vide. Le pied n'a plus besoin
  // d'une boite fantome pour repousser les chiffres, il ne partage plus sa ligne.
  if (!texte) return '';
  return `<span class="b-tag lab-${planningLabelWidthUnits(texte)}" title="${escapeHtml(complet)}"><span class="b-tag-text">${escapeHtml(texte)}</span></span>`;
}

// LARGEUR D UN LIBELLE, EN UNITES DE CARACTERE MOYEN.
// Le CSS a besoin d un seul chiffre pour trancher : combien de place ce texte
// PRECIS reclame. Compter les caracteres ne suffit pas, « Mini-golf » (neuf
// signes) est plus etroit que « Laser x2 » (huit) : mesure au navigateur,
// 41,5 px contre 40,2 px a police egale, et « WWWW » vaut deux fois « iiii ».
// Un comptage brut obligerait donc a reserver la largeur du pire cas pour
// tout le monde, c est-a-dire a masquer des libelles qui tenaient - le defaut
// exact que Movsar avait signale la veille.
// Trois familles suffisent, calibrees sur des mesures reelles a 10 px :
// majuscules et chiffres 1,3 ; signes etroits 0,6 ; le reste 1. L unite vaut
// 0,58 em cote CSS, et le gate mesure les deux sens sur 324 combinaisons.
const PLANNING_LABEL_NARROW = new Set(['i', 'l', 'j', 't', 'f', 'r', '.', ',', '-', ' ', "'"]);
function planningLabelWidthUnits(texte) {
  let unites = 0;
  for (const caractere of String(texte)) {
    if (PLANNING_LABEL_NARROW.has(caractere)) unites += 0.6;
    else if (caractere === caractere.toUpperCase() && caractere !== caractere.toLowerCase()) unites += 1.3;
    else if (caractere >= '0' && caractere <= '9') unites += 1.3;
    else unites += 1;
  }
  // LE PLAFOND MENTAIT DES QUE LE LIBELLE A GRANDI. Il valait 16 unites, ce qui
  // suffisait a « Bowling » (7) mais pas a « FORMULE 4 · Laser x2 » (23) : au-dela
  // du plafond, la classe posee reclamait moins de place que le texte n'en prend,
  // donc le CSS l'affichait sur une piste trop etroite et il debordait de 12px.
  // Un plafond n'est pas un detail de calibration : c'est un MENSONGE des que le
  // contenu le depasse. Il suit maintenant la longueur reelle de l'offre.
  return Math.min(28, Math.max(1, Math.ceil(unites)));
}

const PLANNING_CARD_LABEL_MAX = 12;
// UNE CARTE DIT CE QU'ON NE PEUT PAS DEVINER, PAS CE QU'ON VOIT DEJA.
// Movsar, 2026-08-14 : « les cartes du planning sont super nul pas complet, on
// voit pas formule ». L'information EXISTAIT (`renderReservationTags` fabrique
// bien « FORMULE 5 », « Laser x2 », « Note a lire ») mais deux regles CSS la
// masquaient partout : les etiquettes ne s'affichaient qu'en plein ecran, et
// au-dessus de 190px de piste, alors qu'une piste en fait 147 a huit pistes.
// Elle etait donc rendue dans le DOM et invisible a l'ecran, toujours.
//
// Pendant ce temps le libelle, lui, ecrivait « Bowling » sur un planning DE
// BOWLING : la seule chose que la colonne dit deja. La carte depensait sa
// derniere ligne pour une evidence et taisait ce que le client a achete.
//
// La regle est donc : le libelle porte L'OFFRE, dans l'ordre de ce qui surprend
// un gerant. Une formule d'abord (c'est elle qui commande la soiree), le
// nombre de parties laser ensuite (c'est lui qui contraint l'arene). Quand il
// n'y a ni l'un ni l'autre, la reservation EST l'activite de la colonne, et on
// n'ecrit rien.
function getPlanningCardOfferLabel(reservation, view = 'bowling') {
  const morceaux = [];
  const formule = reservation?.formuleId ? resolveDisplayFormule(reservation.formuleId) : null;
  if (formule || reservation?.type === 'formule') {
    // « FORMULE 5 » tient, « CRAZY STUDENT STRIKE » non : on garde le nom quand
    // il est court, et on retombe sur la NATURE de l'offre, vraie et entiere.
    const nom = String(formule?.name || '').trim();
    morceaux.push(nom && nom.length <= 12 ? nom : 'Formule');
  }
  // LE LASER N'EST PLUS DANS LE TEXTE, IL EST DEVENU UN MARQUEUR.
  // « FORMULE 5 · Laser x2 » fait 20 caracteres : sur une piste de 147px la
  // regle « entier ou absent » le jugeait trop long et n'affichait RIEN, donc
  // on reperdait la formule pour avoir voulu dire deux choses. La formule seule
  // (« FORMULE 5 ») tient des 64px de piste. Le nombre de parties laser part
  // dans les marqueurs, ou il coute 13px au lieu de 60.
  if (morceaux.length) return morceaux.join(' · ');
  // Ni formule ni laser multiple : la colonne dit deja l'activite. On ne repete
  // pas « Bowling » sur le planning bowling.
  if (view === 'bowling' || view === 'laser') return '';
  return getPlanningCardLabel(reservation);
}

function getPlanningCardLabel(reservation) {
  const complet = String(getReservationLabel(reservation) || '').trim();
  if (!complet || complet.length <= PLANNING_CARD_LABEL_MAX) return complet;
  // Une formule porte un nom commercial qui peut faire vingt caractères
  // (« CRAZY STUDENT STRIKE »). Son premier mot n'en dit rien de juste : on
  // nomme la NATURE de l'offre, qui est vraie et entière.
  if (reservation && (reservation.type === 'formule' || reservation.formuleId)) return 'Formule';
  const premier = complet.split(/\s+/).filter(Boolean)[0] || '';
  return premier.length <= PLANNING_CARD_LABEL_MAX ? premier : '';
}

// LA FORMULE ACHETEE, NOMMEE AVEC SA VARIANTE (lib/formula-choice, la Formule
// 4 « 60 min d'arcades » a la place des deux parties de laser) : « FORMULE 4 ·
// 60 min d'arcades ». L infobulle de la carte du planning, l encadre du
// groupe et les puces d une carte payee la lisent ici. Sans variante, le nom tel
// quel. Le texte de la carte du planning reste le nom seul : entier ou absent,
// il disparaitrait des pistes etroites (regle plus haut).
function nomDeLaFormuleAchetee(reservation, nom) {
  const base = String(nom || '').trim();
  const variante = getReservationFormulaChoice(reservation);
  return base && variante ? `${base} · ${variante.label}` : base;
}

// Bloc effectif + durée commun aux cartes bowling ET laser. Le libellé texte
// porte toujours l'info (accessibilité : jamais de sens porté par la couleur
// seule) ; la couleur/pastille ne fait que renforcer.
function renderCardStats(pax, durationLabel, options = {}) {
  const special = Boolean(options.special);
  const paxNum = Math.max(0, Number(pax) || 0);
  const grp = getGroupSizeClass(paxNum);
  const durClass = special ? 'bk-dur dur-special' : 'bk-dur';
  const durTitle = options.durationTitle || durationLabel;
  return `<span class="booking-stats">`
    + `<span class="bk-pax ${grp}" title="${escapeHtml(`${paxNum} joueur${paxNum > 1 ? 's' : ''}${bowlingCapacityMessage(options.bowlingCapacity) ? ' · ' + bowlingCapacityMessage(options.bowlingCapacity) : ''}`)}">${paxNum}${options.bowlingCapacity?.emergency ? '<span aria-label="Capacité de secours">⚠</span>' : ''}<span class="u"><span class="u-short">j</span><span class="u-long">&nbsp;joueurs</span></span></span>`
    + `<span class="bk-sep" aria-hidden="true">·</span>`
    + `<span class="${durClass}" title="Durée ${escapeHtml(durTitle)}">${escapeHtml(durationLabel)}</span>`
    + `</span>`;
}

function getReservationHighlightClasses(reservation) {
  const classes = [];
  // Ce qui vient de tomber du site pendant le service se signale DANS la liste
  // et DANS le planning, pas seulement dans le bandeau du coin qu'on rate quand
  // on a la tete au comptoir. Le bloc `.booking` et la ligne `.res-row` passent
  // tous les deux par ici : un seul branchement couvre les deux vues.
  // Le marquage se perime tout seul au bout de trois minutes - un ecran ou tout
  // brille est un ecran ou plus rien ne ressort.
  if (typeof PinlaneMotion !== 'undefined' && PinlaneMotion.estNeuve(reservation.id)) {
    // Le signal dure trois minutes, l ANIMATION ne joue qu une fois : sinon
    // chaque re-rendu de la liste relancait le halo et l entree de la ligne,
    // et l ecran clignotait sans que personne n ait touche a rien.
    const anime = typeof PinlaneMotion.animationNeuveDue === 'function'
      ? PinlaneMotion.animationNeuveDue(reservation.id)
      : true;
    classes.push(anime ? 'is-neuve' : 'is-neuve-calme');
  }
  if (reservation.type === 'formule' || reservation.formuleId) classes.push('is-formula');
  const bowlingDuration = getBowlingDurationForReservation(reservation);
  if (bowlingDuration && Math.abs(bowlingDuration - 1) > 0.01) classes.push('is-special-duration');
  if (getLaserGameCountForReservation(reservation) > 1) classes.push('is-laser-multi');
  return classes.join(' ');
}

// `notes` MÉLANGE plusieurs sources : demande particulière du client, libellé
// libre d'une occasion « autre », note staff saisie au QuickBook, ajouts
// serveur (noteAppend) et marqueurs de simulation [SIM:<runId>]. Le libellé
// affiché dit donc « Note », jamais « Demande du client » : l'UI n'affirme que
// ce que la donnée prouve. Les marqueurs de simulation sont retirés, sinon une
// réservation simulée compterait comme une vraie demande.
function getReservationNoteText(reservation = {}) {
  // `[ops:xxx]` marque les traces posees par le moteur (retard, decalage) pour
  // qu'elles puissent etre RETIREES quand l'operation est annulee. Le marqueur
  // est une mecanique interne : il ne se lit jamais a l'ecran.
  // Les notes DE L EQUIPE (`[equipe] {...}`) vivent dans la meme colonne mais
  // se lisent a part (getReservationNotesEquipe) : ce texte-ci est le mot
  // ecrit avec la reservation, jamais une note interne.
  return String(reservation.notes || '')
    .split('\n')
    .filter(ligne => !lireNoteEquipeLigne(ligne))
    .join('\n')
    .replace(/\[SIM:[^\]]*\]/g, '')
    .replace(/\[ops:[^\]]*\]\s*/g, '')
    .trim();
}

// LES NOTES DE L EQUIPE (2026-10-01, Movsar : « ajouter une note cote staff,
// une note du staff en interne, visible en bien »). Une ligne par note dans la
// colonne `notes`, derriere le marqueur que le serveur pose
// (lib/database noterReservationEquipe) : le texte, qui l a ecrite, quand.
const NOTE_EQUIPE_TAG = '[equipe] ';
function lireNoteEquipeLigne(ligne) {
  const brute = String(ligne || '').trimStart();
  if (!brute.startsWith(NOTE_EQUIPE_TAG)) return null;
  try {
    const note = JSON.parse(brute.slice(NOTE_EQUIPE_TAG.length));
    return note && typeof note.t === 'string' ? note : null;
  } catch (e) {
    return null;
  }
}

function getReservationNotesEquipe(reservation = {}) {
  return String(reservation.notes || '').split('\n').map(lireNoteEquipeLigne).filter(Boolean);
}

// Le mot ecrit avec la reservation, separe des traces du moteur (retard,
// decalage : lignes `[ops:...]`) : sous « Mot du client », seul ce que le
// client a ecrit ; les traces se lisent a part, comme un suivi.
function getReservationNoteParts(reservation = {}) {
  const lignes = String(reservation.notes || '').split('\n').filter(ligne => !lireNoteEquipeLigne(ligne));
  const nettoyer = ligne => ligne.replace(/\[SIM:[^\]]*\]/g, '').replace(/\[ops:[^\]]*\]\s*/g, '').trim();
  return {
    mot: lignes.filter(ligne => !/^\s*\[ops:/.test(ligne)).map(nettoyer).filter(Boolean).join('\n'),
    suivi: lignes.filter(ligne => /^\s*\[ops:/.test(ligne)).map(nettoyer).filter(Boolean),
  };
}

// « Avec note » : le mot du client OU une note de l equipe.
function hasReservationNote(reservation) {
  return !!getReservationNoteText(reservation) || getReservationNotesEquipe(reservation).length > 0 || !!window.PinlaneStaffNotes?.text(reservation);
}

// Le mot ecrit avec la reservation : en ligne, c est le client qui l a ecrit.
function getReservationNoteTitre(reservation = {}) {
  return reservation.channel === 'public' ? 'Mot du client' : 'Note';
}

function formatNoteEquipeQuand(le) {
  const d = new Date(le);
  if (Number.isNaN(d.getTime())) return '';
  const heure = d.toLocaleTimeString('fr-BE', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Brussels' });
  const jour = d.toLocaleDateString('fr-CA', { timeZone: 'Europe/Brussels' });
  const aujourdhui = new Date().toLocaleDateString('fr-CA', { timeZone: 'Europe/Brussels' });
  if (jour === aujourdhui) return heure;
  return `${d.toLocaleDateString('fr-BE', { day: 'numeric', month: 'short', timeZone: 'Europe/Brussels' })} · ${heure}`;
}

// ---- LE PRIX AJUSTE : UNE SEULE REGLE, LUE PAR TOUS LES ECRANS ------------
// Movsar, 2026-09-03 : « si on affichait le prix modifie de cette facon ca
// serait plus visible ». Le defaut n etait pas une pastille manquante sur un
// ecran : c est que la REGLE vivait au milieu du rendu de la liste du planning
// et que les autres surfaces ne la connaissaient pas. Trois copies existaient
// deja, et DEUX D ENTRE ELLES DIVERGEAIENT : la liste comparait au seul
// `basePrice` ecrit sur le dossier (donc ne signalait RIEN quand ce champ
// manquait), la caisse retombait sur le catalogue quand il manquait. Meme
// dossier, deux verdicts, selon l ecran regarde.
// Une seule fonction rend maintenant l ETAT COMPLET du prix - montant facture,
// reference, ecart, verdict - et chaque ecran le CONSOMME. Le seuil n est
// ecrit qu ici : il absorbe les arrondis au centime, pas un geste commercial.
// UNIFIER N EST PAS CHOISIR LA COPIE LA PLUS BAVARDE. La premiere version de
// cette fonction a pris le repli catalogue de la CAISSE et l a donne aux sept
// surfaces d affichage : mesure sur la fixture QA 9005 (prix 180, aucune base
// ecrite), la liste passait de « aucun marqueur » a « Prix ajuste 180 EUR,
// reference 324 EUR » pour un dossier que personne n avait touche. Le repli
// est donc revenu la ou il a un sens - le chemin d ECRITURE - et l affichage
// a repris la regle de la liste, qui etait la bonne.
const PRIX_AJUSTE_SEUIL_EUR = 0.5;

// `options.repliCatalogue` : reserve au chemin d ECRITURE (getReservationPriceGap).
function getReservationPriceState(reservation, options = {}) {
  const dossier = reservation || {};
  const extras = typeof sumExtras === 'function'
    ? sumExtras(dossier.extras || [])
    : (dossier.extras || []).reduce((somme, extra) => somme + (Number(extra.price) || 0), 0);
  // LA REFERENCE ECRITE SUR LE DOSSIER, LUE COMME UN CHAMP ET NON COMME UNE
  // VERITE JAVASCRIPT. « champ absent » et « base a zero » ne sont pas le meme
  // fait : lib/database.js ramene une colonne `base_price` vide a 0, et
  // lib/reservation-request.js a deja tranche en toutes lettres qu un prix
  // envoye a 0 n est pas un prix absent. Un `||` confondait les deux, donc
  // confondait « on ne sait pas » avec « c est offert ».
  const brut = dossier.basePrice;
  const baseEcrite = (brut === null || brut === undefined || brut === '' || !Number.isFinite(Number(brut)))
    ? null
    : Number(brut);
  // LE CATALOGUE DU JOUR N EST PAS LA REFERENCE DU DOSSIER. Il porte les tarifs
  // d AUJOURD HUI et du centre CHARGE dans la session ; un dossier ancien, ou
  // celui d un autre centre, n a pas ete pris a ce tarif-la. Mesure : fixture
  // 9001, base ecrite 60 EUR contre catalogue du jour 20 EUR, facteur 3.
  // Il ne sert donc qu au chemin d ECRITURE, qui REPOSE une valeur au lieu d en
  // conclure quelque chose, et qui le faisait deja avant ce lot : addExtra et
  // removeExtra recomposent le prix avec exactement la meme formule.
  const base = options.repliCatalogue && !baseEcrite
    ? (typeof getBasePriceForReservation === 'function' ? (Number(getBasePriceForReservation(dossier)) || 0) : 0)
    : (baseEcrite || 0);
  const reference = base + extras;
  const price = Number(dossier.price) || 0;
  const ecart = price - reference;
  // LE VERDICT SE GARDE SUR LA BASE, PAS SUR LA SOMME. `reference` vaut
  // base + extras : garder l ecart sur elle laissait un seul cafe a 6 EUR
  // ouvrir la porte a « Prix ajuste 200 EUR (reference 6 EUR) » sur un dossier
  // dont la base n est pas ecrite. Sans reference ECRITE et non nulle, il n y a
  // rien a comparer : on ne CLAME PAS un ajustement qu aucune donnee ne porte.
  const aReference = baseEcrite !== null && baseEcrite > 0;
  return {
    price,
    reference,
    ecart,
    aReference,
    ajuste: aReference && Math.abs(ecart) > PRIX_AJUSTE_SEUIL_EUR,
  };
}

// L INFOBULLE DIT LA REFERENCE, PAS SEULEMENT « AJUSTE ». Savoir qu un prix a
// bouge sans savoir de combien ne permet ni de l expliquer au client ni de le
// verifier en caisse.
function getReservationPriceAdjustmentTitle(reservation) {
  const etat = getReservationPriceState(reservation);
  if (!etat.ajuste) return '';
  return `Prix ajusté par l'équipe (référence ${formatMoneyCentimes(etat.reference)})`;
}

// UNE SEULE PASTILLE, QUATRE LONGUEURS. La forme suit la place de l ecran,
// jamais une regle differente : c est le meme verdict partout.
//   'complet'   « Prix ajusté 40 € »               listes, cartes d accueil
//   'reference' « Prix ajusté (référence 60 €) »   quand le montant est deja dit
//   'montant'   « 40 € »                            cartes du planning
//   'signal'    une etiquette SVG, montant en infobulle et nom accessible
//   'mot'       « Prix ajusté »                     tableaux a colonne Montant
// RIEN NE S AFFICHE QUAND LE PRIX EGALE LA REFERENCE : un marqueur toujours
// present ne signale plus rien.
function renderReservationPriceMark(reservation, options = {}) {
  const etat = getReservationPriceState(reservation);
  if (!etat.ajuste) return '';
  const forme = options.forme || 'complet';
  const base = options.base || 'res-state-pill custom-price';
  const montant = formatMoneyCentimes(etat.price);
  // 'encadre' : l encadre « Prix ajusté » des cartes de groupe (2026-10-01),
  // dont le titre dit deja le mot : « 280 € · référence 495 € ».
  const texte = forme === 'signal'
    ? ''
    : forme === 'montant'
      ? montant
    : forme === 'mot'
      ? 'Prix ajusté'
      : forme === 'reference'
        ? `Prix ajusté (référence ${formatMoneyCentimes(etat.reference)})`
        : forme === 'encadre'
          ? `${montant} · référence ${formatMoneyCentimes(etat.reference)}`
          : `Prix ajusté ${montant}`;
  // LE VERDICT NE VIT PAS QUE DANS LA TEINTE. En forme « montant » le texte
  // visible est un montant NU : « 40 € » en ambre se lit comme un prix
  // ordinaire des que l ambre ne se distingue plus (plein soleil sur la
  // tablette du comptoir, contraste eleve, deuteranopie), et sur la carte du
  // planning c est le SEUL montant affiche. L etiquette de prix donne a la
  // pastille une silhouette qu on reconnait sans lire la couleur ; elle est
  // decorative, c est le libelle qui porte l information.
  const icone = forme === 'montant' || forme === 'signal'
    ? '<svg class="pl-price-icon" viewBox="0 0 24 24" width="9" height="9" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.6 13.2 12.8 21a2 2 0 0 1-2.8 0l-7-7a2 2 0 0 1-.6-1.4V4.6a2 2 0 0 1 2-2h8a2 2 0 0 1 1.4.6l6.8 6.8a2 2 0 0 1 0 2.8z"/><path d="M7.3 7.3h.01"/></svg>'
    : '';
  // LE LIBELLE VOCAL SUIT LA FORME. En « mot » et en « reference », l ecran
  // porte deja le montant a cote : le redire faisait entendre « 40 € Prix
  // ajusté 40 €, référence 60 € » a chaque ligne du tableau de la Direction.
  // Le montant n est annonce que la ou l ecran ne le dit pas deja.
  const vocal = (forme === 'mot' || forme === 'reference')
    ? `Prix ajusté, référence ${formatMoneyCentimes(etat.reference)}`
    : `Prix ajusté ${montant}, référence ${formatMoneyCentimes(etat.reference)}`;
  // `role="img"` : un `<span>` a le role implicite `generic`, sur lequel un nom
  // d auteur est INTERDIT par ARIA in HTML et n est pas expose. Mesure de
  // l arbre AX avant correction : la carte du planning s annoncait
  // « Entreprise Ardenne · 15:00 - 16:30 : ... 290 € », sans le mot « ajusté ».
  // La marque de note de la page Evenements porte deja `role="img"` : meme
  // geste, meme fichier.
  return `<span class="${base} pl-price-adjusted"${forme === 'signal' ? ' style="color:var(--warning);background:none;border:0"' : ''} role="img" title="${escapeHtml(forme === 'signal' ? vocal : getReservationPriceAdjustmentTitle(reservation))}" aria-label="${escapeHtml(vocal)}">${forme === 'signal' ? icone.replace('class="pl-price-icon"', 'class="pl-price-icon" style="margin-right:0"') : icone}${escapeHtml(texte)}</span>`;
}

// UNE NOTE QU ON NE PEUT PAS LIRE N EST PAS UNE NOTE, C EST UN RAPPEL D OUBLI.
// Movsar, 2026-08-14 : « il y a aussi les notes a lire qui s affichent nulle
// part, on sait pas lire la note ». L etiquette « Note a lire » etait posee sur
// la ligne depuis toujours, et le TEXTE n apparaissait sur aucune surface de
// liste : il fallait ouvrir la fiche pour decouvrir de quoi il s agissait, donc
// ouvrir chaque dossier marque pour savoir si la consigne concernait ce
// service. Dans une table, la colonne « Réservation » a la largeur pour la dire.
// Elle est ecrite en entier jusqu a 90 caracteres, coupee au MOT au-dela, et le
// texte complet reste dans l infobulle et dans la fiche.
// LES ORBES DE REFLEXION : « chargement » ne dit pas ce qui se passe.
// Toutes les surfaces d'agent affichaient le meme mot, « Chargement… », que la
// machine soit en train de lire la base, d'appeler un modele ou de composer un
// texte. Or ces trois attentes n'ont ni la meme duree ni la meme raison, et
// c'est justement ce qu'un gerant veut savoir quand il regarde un ecran qui ne
// bouge pas. Cinq etats, chacun avec son mouvement (voir le bloc `.pl-orbs`
// dans la feuille de style).
// Les orbes sont DECORATIVES (`aria-hidden`) : c'est le libelle qui porte
// l'information, et une synthese vocale lit « L'agent rédige », pas trois
// points qui bougent.
// NEUF ETATS, PAS UN SEUL « chargement ». Chacun correspond a un etat du
// moteur `thinking-orbs` (voir `assets/thinking-orbs.js` pour l'attribution et
// ce qui est repris tel quel). Le libelle FRANCAIS dit ce que la machine fait ;
// l'animation dit qu'elle le fait encore. Les deux ensemble evitent la question
// « est-ce que c'est bloque ? », qui est la seule que pose un ecran fige.
const PL_THINKING_LABELS = {
  breathing: 'L’agent réfléchit',
  composing: 'L’agent rédige',
  searching: 'Lecture des données',
  solving: 'Analyse en cours',
  connecting: 'Envoi en cours',
  working: 'Traitement en cours',
  weaving: 'Assemblage des données',
  listening: 'Écoute des réponses',
  shaping: 'Mise en forme',
};

// UNE ATTENTE LONGUE MONTRE OU ELLE EN EST.
// `renderThinking` dit « ca travaille » ; celle-ci dit « voila ce qui est fait,
// voila ce qui reste ». Les etapes nomment le travail REEL du cycle marketing
// (lire les donnees du centre, les croiser, rediger, verifier ce qu'on avance) :
// une progression inventee serait un mensonge anime. La barre ne revient jamais
// en arriere et la derniere etape reste affichee jusqu'a la reponse : voir une
// barre se vider fait conclure que ca a echoue.
function renderThinkingSteps(etapes, options = {}) {
  const liste = (etapes || []).filter((etape) => etape && etape.state && etape.label);
  if (!liste.length) return renderThinking('breathing', options);
  const premiere = liste[0];
  const cadence = Number(options.stepMs) || 1600;
  return `<div class="pl-progress" role="status" aria-live="polite"`
    + ` data-orb-steps="${escapeHtml(JSON.stringify(liste))}" data-orb-step-ms="${cadence}">`
    + `<canvas class="pl-orb-canvas" data-orb-state="${escapeHtml(premiere.state)}" data-orb-size="64" aria-hidden="true"></canvas>`
    + `<div class="pl-progress-body">`
    + `<span class="pl-progress-label" data-orb-step-label>${escapeHtml(premiere.label)}</span>`
    + `<span class="pl-progress-track"><span class="pl-progress-bar" data-orb-step-bar style="width:${Math.round(100 / liste.length)}%"></span></span>`
    + `</div></div>`;
}
window.renderThinkingSteps = renderThinkingSteps;

function renderThinking(etat = 'breathing', options = {}) {
  const cle = PL_THINKING_LABELS[etat] ? etat : 'breathing';
  const libelle = options.label || PL_THINKING_LABELS[cle];
  // Deux tailles, celles du moteur : 20 en ligne dans un texte, 64 quand
  // l'attente occupe un panneau entier et qu'il n'y a rien d'autre a regarder.
  const taille = Number(options.size) === 64 ? 64 : 20;
  return `<span class="pl-thinking" role="status" aria-live="polite">`
    + `<canvas class="pl-orb-canvas" data-orb-state="${cle}" data-orb-size="${taille}" aria-hidden="true"></canvas>`
    + `<span>${escapeHtml(libelle)}</span></span>`;
}
window.renderThinking = renderThinking;

// LA NOTE SE LIT AUSSI QUAND ON OUVRE LE DOSSIER.
// Movsar, 2026-08-14 : « la note, on doit pouvoir la lire aussi quand on clique
// sur la carte, ou on voit les infos ». La fiche « Infos » affichait le plan
// automatique, le contact, le retard, mais pas la consigne du client : le seul
// endroit ou on ouvre un dossier pour comprendre ce qu'il a de particulier ne
// disait pas ce qu'il a de particulier. Elle se place juste apres l'action,
// avant le programme : c'est ce qui change la maniere de servir.
function renderPosNoteBlock(reservation) {
  const note = getReservationNoteText(reservation);
  if (!note) return '';
  return `<section class="info-block pos-note-block">
    <span class="info-label">Note du dossier</span>
    <p class="pos-note-text">${escapeHtml(note)}</p>
  </section>`;
}

function renderReservationNoteLine(reservation) {
  const note = getReservationNoteText(reservation);
  if (!note) return '';
  let affiche = note;
  if (note.length > 90) {
    const coupe = note.slice(0, 90);
    const dernierEspace = coupe.lastIndexOf(' ');
    affiche = `${(dernierEspace > 40 ? coupe.slice(0, dernierEspace) : coupe).trim()}…`;
  }
  return `<span class="res-note-line" title="${escapeHtml(note)}">`
    + `<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.5 14.4a2 2 0 0 1-2 2H8.2L4 20.4V5.6a2 2 0 0 1 2-2h12.5a2 2 0 0 1 2 2z"/></svg>`
    + `<span>${escapeHtml(affiche)}</span></span>`;
}

// MARQUEURS DE CARTE : ce qui change la maniere de servir, en une forme.
// Une note et un anniversaire ne se lisent pas comme un chiffre : ce sont des
// consignes. Sur 147px de piste, les ecrire en toutes lettres coute la ligne
// entiere de l'offre ; en icone titree, ils coutent 13px et restent lisibles
// par la synthese vocale. Le texte complet vit dans la fiche, ou on l'ouvre
// justement pour le lire.
// `partiesEcrites` : la carte laser ecrit deja « Partie 1/2 » sous le nom. Y
// remettre le marqueur « x2 », c est ecrire deux fois le meme fait sur la meme
// carte, ce qui est exactement le defaut que `contexteSeul` corrige plus bas
// pour les etiquettes. Restent l occasion et la note, qui n ont aucune autre
// place sur le planning laser.
// L ORDRE DES MARQUEURS EST UN ORDRE DE PRIORITE, PAS UN ORDRE D ECRITURE.
// Sur la carte d une seule ligne, la piste de reference (1440px, 8 pistes,
// 134,2px de piste) ne laisse la place qu a UN marqueur : la CSS fait donc
// ceder les suivants (`.bk-flag:nth-child(n+2)`), et `nth-child` compte la
// position dans le DOM. Le premier ecrit est donc le seul qui survit a la
// carte serree, et ce doit etre celui qui change la maniere de servir : la
// note d abord (un gateau, une allergie), l occasion ensuite, le decompte des
// parties en dernier, parce qu il se relit sur le planning laser et dans la
// fiche alors que la note ne se lit nulle part ailleurs sur le planning.
function renderCardFlags(reservation, options = {}) {
  const marques = [];
  if (hasReservationNote(reservation)) {
    marques.push({
      cls: 'flag-note',
      label: 'Note à lire',
      // UNE BULLE, PAS UN ROND D'ALERTE. Movsar, 2026-08-14 : « le petit badge
      // attention est proche de celui qui montre la piste en retard, donc
      // relou ». Les deux etaient un cercle : a 12px, un cercle avec un point
      // ressemble a tous les autres cercles avec un point. Une bulle de message
      // ne peut se confondre avec rien, et elle dit ce qu'elle est.
      path: '<path d="M20.5 14.4a2 2 0 0 1-2 2H8.2L4 20.4V5.6a2 2 0 0 1 2-2h12.5a2 2 0 0 1 2 2z"/><path d="M8.4 8.6h7.6M8.4 11.8h4.8"/>',
    });
  }
  // DEUX VOCABULAIRES, PAS UN. `getReservationOccasion` rend une OCCASION
  // declaree (`anniversaire`, `entreprise`, `ecole`...), pendant que `birthday`
  // etait la CATEGORIE staff que l ancienne page Groupes en deduisait. La
  // comparaison portait sur la categorie : aucune occasion ne pouvait jamais
  // l egaler, donc le marqueur anniversaire n a jamais atteint une seule carte,
  // meme sur les pistes assez larges pour l afficher.
  if (getReservationOccasion(reservation) === 'anniversaire') {
    marques.push({
      cls: 'flag-birthday',
      label: 'Anniversaire',
      path: '<path d="M5 21h14M6 21v-6h12v6M12 9V6"/><path d="M6 15a2.4 2.4 0 0 0 3 0 2.4 2.4 0 0 1 3 0 2.4 2.4 0 0 0 3 0 2.4 2.4 0 0 1 3 0"/><circle cx="12" cy="4.4" r="1.1"/>',
    });
  }
  // TOUT GROUPE QUI JOUE AU LASER LE DIT, PAS SEULEMENT A DEUX PARTIES
  // (2026-10-09, Movsar : « des petits badges en fonction de ce qu ils ont,
  // super complet, super bien relié »). Une visite bowling + une partie de
  // laser ne portait aucun marqueur : le comptoir ne savait pas qu elle
  // passait a l arene. Le marqueur nu dit « laser », le chiffre n apparait
  // qu a partir de deux parties ; l heure des departs, celle du planning
  // Laser, est dans son titre et sur le badge du pied quand il a la place.
  const parties = getLaserGameCountForReservation(reservation);
  if (parties >= 1 && !options.partiesEcrites) {
    const departs = getCardLaserDeparts(reservation);
    const quand = departs.heures.length ? ` : ${departs.heures.join(', ')}` : '';
    const reste = departs.aPlacer ? `, ${departs.aPlacer} à placer` : '';
    marques.push({
      cls: parties > 1 ? 'flag-laser' : 'flag-laser flag-laser-seul',
      label: `${parties > 1 ? `${parties} parties de laser` : 'Laser'}${quand}${reste}`,
      texte: parties > 1 ? `x${parties}` : '',
      path: '<circle cx="12" cy="12" r="6.4"/><path d="M12 2.6v3M12 18.4v3M2.6 12h3M18.4 12h3"/>',
    });
  }
  if (!marques.length) return '';
  // La boite dont le seul marqueur est le laser part avec lui quand le badge
  // du pied le reprend (feuille de style) : sinon elle garderait sa gouttiere.
  const seulLaser = marques.length === 1 && /flag-laser/.test(marques[0].cls);
  return `<span class="bk-flags${seulLaser ? ' is-laser-seul' : ''}">${marques.map(m => `<span class="bk-flag ${m.cls}" role="img" aria-label="${m.label}" title="${m.label}">`
    + `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${m.path}</svg>`
    + (m.texte ? `<span class="bk-flag-num">${escapeHtml(m.texte)}</span>` : '')
    + `</span>`).join('')}</span>`;
}

// LES DEPARTS LASER D UN GROUPE, TELS QUE LE PLANNING LASER LES POSE
// (2026-10-09). Les memes fenetres que le tableau des departs
// (getLaserWindowsFromReservation) : la carte bowling ne peut pas dire une
// autre heure que lui. Une partie ou une vague = une heure ; les parties pas
// encore posees se comptent a part.
function getCardLaserDeparts(reservation) {
  const minutes = [...new Set(getLaserWindowsFromReservation(reservation).map(w => Math.round(Number(w.start) * 60)))].sort((a, b) => a - b);
  return {
    heures: minutes.map(m => formatClockDisplay(m / 60)),
    aPlacer: getPendingLaserPassesForReservation(reservation).length,
  };
}

// LE BADGE LASER DU PIED : l heure du premier depart, « +1 » pour tout ce qui
// suit au laser (une autre partie, une autre vague, une partie a placer), ou
// « à placer » quand rien n est pose. Il vit dans la PLACE LIBRE du pied, une
// boite de conteneur qui prend ce que les chiffres laissent (le meme mecanisme
// « entier ou absent » que l offre) : complet s il y tient, sinon reduit a
// son pictogramme, sinon absent. Aucun seuil de largeur choisi d avance, donc
// rien a recalibrer quand le pied change. Le marqueur laser de la tete se
// retire des que la carte a ce badge (feuille de style, `a-laser-pied`).
function renderCardLaserBadge(reservation) {
  if (getLaserGameCountForReservation(reservation) < 1) return '';
  const departs = getCardLaserDeparts(reservation);
  if (!departs.heures.length && !departs.aPlacer) return '';
  const autres = departs.heures.length - 1 + (departs.heures.length ? departs.aPlacer : 0);
  const texte = departs.heures.length
    ? `${departs.heures[0]}${autres > 0 ? ` +${autres}` : ''}`
    : 'à placer';
  const titre = `Laser${departs.heures.length ? ` : ${departs.heures.join(', ')}` : ''}${departs.aPlacer ? `${departs.heures.length ? ',' : ' :'} ${departs.aPlacer} partie${departs.aPlacer > 1 ? 's' : ''} à placer` : ''}`;
  const picto = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="6.4"/><path d="M12 2.6v3M12 18.4v3M2.6 12h3M18.4 12h3"/></svg>';
  const etat = departs.heures.length ? '' : ' is-a-placer';
  // La classe de longueur dit au CSS quelle place reclame le texte. Les
  // chiffres sont tabulaires : chaque motif a UNE largeur, mesuree une fois
  // (feuille de style) : « 17:00 » (lc-5), « 17:30 +1 » (lc-8), « 17:30 +10 »
  // (lc-9), « à placer » (lc-p).
  return `<span class="b-tag bk-reste lc-${departs.heures.length ? Math.min(9, texte.length) : 'p'}">`
    + `<span class="bk-laser${etat}" role="img" aria-label="${escapeHtml(titre)}" title="${escapeHtml(titre)}">${picto}<span class="bk-laser-t">${escapeHtml(texte)}</span></span>`
    + `<span class="bk-laser is-compact${etat}" role="img" aria-label="${escapeHtml(titre)}" title="${escapeHtml(titre)}">${picto}</span>`
    + '</span>';
}

// `contexteSeul` : ne rend QUE ce que la ligne ne dit pas deja ailleurs.
// Dans la liste refaite, la formule est ecrite dans sa colonne, la duree dans
// la colonne de gauche et les parties laser dans les marqueurs : les repeter en
// etiquettes, c'est ecrire trois fois le meme fait, ce qui etait exactement le
// defaut signale. Restent l'occasion et la note, qui n'ont aucune autre place.
function renderReservationTags(reservation, options = {}) {
  const tags = [];
  const contexteSeul = Boolean(options.contexteSeul);
  const formule = reservation.formuleId ? resolveDisplayFormule(reservation.formuleId) : null;
  if (!contexteSeul && (reservation.type === 'formule' || formule)) tags.push({ cls: 'formula', label: formule?.name || 'Formule' });
  // L etiquette dit le temps de jeu VENDU (somme des blocs) : c est ce que le
  // client a paye et ce que le comptoir doit lire.
  const bowlingDuration = getBowlingTotalHoursForReservation(reservation);
  if (!contexteSeul && bowlingDuration && Math.abs(bowlingDuration - 1) > 0.01) {
    tags.push({ cls: 'duration', label: `Bowling ${formatDurationLabel(bowlingDuration)}` });
  }
  const laserGames = getLaserGameCountForReservation(reservation);
  if (!contexteSeul && laserGames > 1) tags.push({ cls: 'laser-plus', label: `Laser x${laserGames}` });
  // Occasion + note : sans ça, la liste dense du jour n'affiche RIEN d'une
  // réservation qui porte une demande particulière.
  const occasion = getReservationOccasion(reservation);
  if (occasion) tags.push({ cls: 'occasion', label: (STAFF_OCCASION_LABELS[occasion] || '').split(' / ')[0] });
  if (hasReservationNote(reservation)) tags.push({ cls: 'note', label: 'Note à lire' });
  if (!tags.length) return '';
  return `<div class="reservation-tags">${tags.map(tag => `<span class="reservation-tag ${tag.cls}">${tag.label}</span>`).join('')}</div>`;
}

// Flag d'affichage « retard » posé par l'application d'un plan de retard
// (opsPlan.delayFlag). Actif tant qu'il n'a pas été retiré (cleared) par le
// staff depuis la carte. Purement visuel : n'affecte pas l'horaire appliqué.
function getReservationDelayFlag(reservation) {
  const flag = reservation && reservation.opsPlan && reservation.opsPlan.delayFlag;
  if (!flag || flag.cleared) return null;
  return flag;
}

// Petit indicateur horloge « +X min » sur la carte planning, avec tooltip
// (« retardée de X min, 15:00→15:15 »). Cliquable pour retirer l'indicateur.
function renderDelayIndicator(reservation) {
  const flag = getReservationDelayFlag(reservation);
  if (!flag) return '';
  const mins = Math.round(Number(flag.minutes) || 0);
  const range = flag.from && flag.to ? ` ${flag.from}→${flag.to}` : '';
  const tip = `Retardée de ${mins} min${range ? ` (${flag.from}→${flag.to})` : ''}, cliquer pour retirer le retard et remettre à l'heure d'origine`;
  return `<button type="button" class="delay-indicator" title="${escapeHtml(tip)}" aria-label="${escapeHtml(tip)}" onmousedown="event.stopPropagation()" onclick="revertDelay(event, ${reservation.id})">`
    + `<svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><polyline points="12 7 12 12 16 14"/></svg>`
    + `<span class="delay-indicator-label">+${mins}</span></button>`;
}

// Retire l'indicateur de retard directement depuis la carte planning. Le
// serveur passe opsPlan.delayFlag.cleared = true SANS toucher à l'horaire.
async function clearDelayFlag(ev, id) {
  if (ev) { ev.stopPropagation(); ev.preventDefault(); }
  const reservation = state.reservations.find(item => Number(item.id) === Number(id));
  const centerId = (reservation && reservation.centerId) || state.adminCenterId || 'libramont';
  try {
    const payload = await apiRequest(API_ENDPOINTS.ops, {
      method: 'POST',
      body: JSON.stringify({ action: 'delayClear', centerId, reservationId: Number(id) })
    });
    if (payload.reservation) upsertReservationInState(payload.reservation);
    if (state.selectedRes && Number(state.selectedRes.id) === Number(id) && payload.reservation) {
      state.selectedRes = payload.reservation;
    }
    save();
    renderStaffData();
    renderPos();
    toast(payload.cleared === false ? 'Aucun indicateur à retirer.' : 'Indicateur de retard retiré.');
  } catch (error) {
    toast(error.message || 'Impossible de retirer l\'indicateur de retard.');
  }
}

// Retire le retard d'une réservation ET restaure son créneau d'origine (heure +
// plan + pistes) via l'action serveur delayRevert (snapshot pré-décalage). Si
// l'origine n'est pas restaurable (retard legacy / résa cascadée), le serveur se
// contente de masquer l'indicateur et le signale dans le message.
async function revertDelay(ev, id) {
  if (ev) { ev.stopPropagation(); ev.preventDefault(); }
  const reservation = state.reservations.find(item => Number(item.id) === Number(id));
  const centerId = (reservation && reservation.centerId) || state.adminCenterId || 'libramont';
  try {
    const payload = await apiRequest(API_ENDPOINTS.ops, {
      method: 'POST',
      body: JSON.stringify({ action: 'delayRevert', centerId, reservationId: Number(id) })
    });
    if (payload.reservation) upsertReservationInState(payload.reservation);
    // Les groupes que ce retard avait pousses reviennent aussi : on les pose
    // tout de suite a l ecran.
    (Array.isArray(payload.reservations) ? payload.reservations : []).forEach(item => { if (item && item.id) upsertReservationInState(item); });
    if (state.selectedRes && Number(state.selectedRes.id) === Number(id) && payload.reservation) {
      state.selectedRes = payload.reservation;
    }
    save();
    renderStaffData();
    if (state.selectedRes) renderPos();
    if (payload.reverted) toast(payload.restaurees ? `Retard retiré : ce groupe et ${payload.restaurees} groupe${payload.restaurees > 1 ? 's' : ''} décalé${payload.restaurees > 1 ? 's' : ''} reviennent à leur heure.` : 'Retard retiré : créneau d\'origine restauré.');
    else if (payload.message) toast(payload.message);
    else toast('Aucun retard à retirer.');
  } catch (error) {
    toast(error.message || 'Impossible de retirer le retard.');
  }
}

function getReservationCommercialStore(reservation) {
  return reservation?.opsPlan?.guestOps && typeof reservation.opsPlan.guestOps === 'object'
    ? reservation.opsPlan.guestOps
    : {};
}

// SUPPRIMÉ le 2026-08-13 : `getReservationCheckInCode`, qui fabriquait un code
// du genre « FG-260813-0930 » (enseigne en dur + date + 4 derniers chiffres de
// l'identifiant). Movsar, verbatim : « pourquoi il y a des trucs genre FG chais
// pas quoi, ça sert à rien ici ». Il avait raison, et pour une raison plus dure
// que l'encombrement : ce code N'EXISTAIT NULLE PART AILLEURS. Il n'était ni
// stocké en base, ni envoyé dans un email, ni accepté par la recherche du staff
// (`getPlanningVisibleReservations` cherche sur nom / téléphone / offre / email),
// ni affiché dans le détail du dossier. Personne ne pouvait donc retrouver une
// réservation avec. C'est exactement ce que la Product Rule de DESIGN.md §9
// interdit : donner l'illusion d'une donnée que le backend ne fournit pas.
// Le préfixe « FG » était en prime codé en dur : un 2e client aurait vu la
// marque de Fun Galaxy sur ses propres dossiers.
// LA VRAIE RÉFÉRENCE EXISTE, et c'est l'identifiant de la réservation : il est
// stocké, unique, stable. Il est désormais montré là où une référence sert
// vraiment : l'en-tête du dossier et l'export.
function reservationRequiresGuestWaiver(reservation) {
  return reservation?.type === 'laser'
    || getLaserGameCountForReservation(reservation) > 0
    || getLaserWindowsFromReservation(reservation).length > 0;
}

function getReservationGuestOps(reservation) {
  const stored = getReservationCommercialStore(reservation);
  const waiverRequired = Boolean(stored.waiverRequired ?? reservationRequiresGuestWaiver(reservation));
  const checkInDone = Boolean(stored.checkInDone || reservation.status === 'arrived' || reservation.status === 'paid');
  const waiverDone = Boolean(stored.waiverDone);
  const missing = [];
  if (waiverRequired && !waiverDone) missing.push('consignes laser');
  if (!checkInDone) missing.push('check-in');
  const scoreBase = [!waiverRequired || waiverDone, checkInDone];
  const readinessScore = Math.round((scoreBase.filter(Boolean).length / scoreBase.length) * 100);
  return {
    waiverRequired,
    waiverDone,
    checkInDone,
    reminderSent: Boolean(stored.reminderSent),
    lastUpdatedAt: stored.updatedAt || '',
    missing,
    readinessScore,
  };
}

function getGuestOpsChips(reservation) {
  const guest = getReservationGuestOps(reservation);
  const chips = [];
  // LA NOTE PASSE EN TETE. Le tableau Direction se presente comme exhaustif
  // (« Toutes les lignes exploitables par la direction ») en ignorant
  // l information la plus contextuelle du dossier. La console staff a un filtre
  // « Avec note » depuis longtemps : c est la meme aide qui repond ici, le
  // texte complet dans l infobulle.
  if (hasReservationNote(reservation)) {
    chips.push({ cls: 'note', label: 'Note', title: getReservationNoteText(reservation) });
  }
  if (guest.waiverRequired) {
    chips.push({
      cls: guest.waiverDone ? 'ok' : 'warn',
      label: guest.waiverDone ? 'Consignes OK' : 'Consignes laser',
    });
  }
  // La pastille dit l'ÉTAT, pas un code. Un code qu'on ne peut chercher nulle
  // part mangeait la ligne à la place de l'information qui sert au comptoir.
  chips.push({
    cls: guest.checkInDone ? 'ok' : 'danger',
    label: guest.checkInDone ? 'Check-in OK' : 'Check-in à faire',
  });
  return chips;
}

// Une pastille peut porter un TEXTE COMPLET en infobulle (la note), la ou le
// libelle ne tient qu un mot : le rendu est le meme pour toutes.
function renderGuestOpsChip(chip) {
  const titre = chip.title ? ` title="${escapeHtml(chip.title)}"` : '';
  return `<span class="guest-chip ${escapeHtml(chip.cls)}"${titre}>${escapeHtml(chip.label)}</span>`;
}

function renderGuestOpsMini(reservation) {
  const chips = getGuestOpsChips(reservation).slice(0, 3);
  return `<div class="guest-mini">${chips.map(renderGuestOpsChip).join('')}</div>`;
}

function renderAdminGuestOpsCell(reservation) {
  const chips = getGuestOpsChips(reservation);
  return `<div class="engagement-cell">${chips.map(renderGuestOpsChip).join('')}</div>`;
}

function getOpsPlanFixedCommitments(plan) {
  return Array.isArray(plan?.entitlements?.fixedCommitments) ? plan.entitlements.fixedCommitments : [];
}

function getOpsPlanFlexibleEntitlements(plan) {
  return Array.isArray(plan?.entitlements?.flexibleEntitlements) ? plan.entitlements.flexibleEntitlements : [];
}

function formatOpsCommitment(item) {
  if (!item) return '';
  const label = item.type === 'bowling'
    ? `Bowling${Array.isArray(item.lanes) && item.lanes.length ? ` pistes ${item.lanes.join(', ')}` : ''}`
    : item.type === 'laser_game'
      ? `Laser${item.countIndex ? ` partie ${item.countIndex}` : ''}`
      : item.label || item.type || 'Ressource';
  const time = item.startTime ? `${item.startTime}${item.endTime ? `-${item.endTime}` : ''}` : '';
  return [label, time].filter(Boolean).join(' · ');
}

function getOpsPlanPrimarySignal(plan) {
  const warnings = Array.isArray(plan?.marketIntelligence?.warnings) ? plan.marketIntelligence.warnings : [];
  if (warnings.length) return { cls: 'warn', text: warnings[0] };
  const checklist = Array.isArray(plan?.operationsChecklist) ? plan.operationsChecklist : [];
  if (checklist.length) return { cls: 'fixed', text: checklist[0] };
  const commitments = Array.isArray(plan?.customerCommitment) ? plan.customerCommitment : [];
  if (commitments.length) return { cls: '', text: commitments[0] };
  return null;
}

function renderStaffOpsMini(reservation) {
  const plan = reservation?.opsPlan;
  if (!plan) return '';
  const signal = getOpsPlanPrimarySignal(plan);
  const fixed = getOpsPlanFixedCommitments(plan).slice(0, 2).map(formatOpsCommitment).filter(Boolean);
  const lines = [];
  if (fixed.length) lines.push(`<span class="res-ops-line fixed">${escapeHtml(fixed.join(' · '))}</span>`);
  if (signal?.text) lines.push(`<span class="res-ops-line ${escapeHtml(signal.cls)}">${escapeHtml(signal.text)}</span>`);
  if (!lines.length) return '';
  return `<div class="res-ops-mini">${lines.join('')}</div>`;
}

// UNE VISITE COMMENCE QUAND LA PAGE CHANGE, quel que soit le chemin (barre
// laterale, lien, adresse, retour arriere). Le repere des entrees de page
// (window.PinlaneV2.lastPage) n etait tenu que par les pages qui s animent :
// passer par le Planning, qui n en a pas, le laissait sur la page quittee, et
// y revenir ne rejouait plus son entree. `var` et pas `let` : la coquille peut
// se dessiner avant que le script ait fini de s evaluer.
var staffShellVisitPage = '';
function renderStaffShell(dayReservations = todaysReservations()) {
  const normalizedPage = normalizeStaffMenuPage(state.staffMenuPage);
  if (state.staffMenuPage !== normalizedPage) {
    state.staffMenuPage = normalizedPage;
    save();
  }
  if (staffShellVisitPage !== normalizedPage) {
    staffShellVisitPage = normalizedPage;
    if (window.PinlaneV2) window.PinlaneV2.lastPage = '';
  }
  const setPageVisibility = (id, active) => {
    const element = document.getElementById(id);
    if (!element) return;
    element.classList.toggle('hidden', !active);
    element.setAttribute('aria-hidden', active ? 'false' : 'true');
    if (active) element.removeAttribute('inert');
    else element.setAttribute('inert', '');
  };
  const dashboardActive = isStaffDashboardActive();
  const reservationsActive = isStaffReservationsActive();
  const clientsActive = isStaffClientsActive();
  const pricingActive = isStaffPricingActive();
  const emailsActive = isStaffEmailsActive();
  const campaignsActive = isStaffCampaignsActive();
  const utilityActive = isStaffUtilityActive();
  const cockpitActive = isStaffCockpitActive();
  setPageVisibility('staffDashboardPage', dashboardActive);
  setPageVisibility('staffReservationsPage', reservationsActive);
  setPageVisibility('staffClientsPage', clientsActive);
  setPageVisibility('staffPricingPage', pricingActive);
  setPageVisibility('staffEmailsPage', emailsActive);
  setPageVisibility('staffCampaignsPage', campaignsActive);
  setPageVisibility('staffUtilityPage', utilityActive);
  setPageVisibility('staffCockpitPage', cockpitActive);
  ['.staff-head', '.kpi-grid', '.staff-resource-tabs', '#planningBox', '#laserPlanningBox', '.table-box'].forEach(selector => {
    document.querySelectorAll(`#staffView ${selector}`).forEach(element => element.classList.toggle('hidden', dashboardActive || reservationsActive || clientsActive || pricingActive || emailsActive || campaignsActive || utilityActive || cockpitActive));
  });
  const d = parseLocalDate(state.currentDate);
  const view = getStaffResourceView();
  const scopedReservations = dayReservations.filter(r => reservationMatchesStaffResource(r, view));
  const now = currentTimeDecimal();
  const activeWindows = scopedReservations
    .flatMap(r => getStaffResourceWindows(r, view).map(window => ({ ...window, reservation: r })))
    .filter(window => window.start <= now && now < window.end);
  const activeReservationIds = new Set(activeWindows.map(window => window.reservation.id));
  const activeSessions = view === 'laser' ? activeWindows.length : activeReservationIds.size;
  const activeLaserPlayers = activeWindows.reduce((sum, window) => sum + (Number(window.players || window.reservation?.pax) || 0), 0);
  const activeLanes = new Set(activeWindows.flatMap(window => window.lanes || [])).size;
  const nextArrival = [...scopedReservations]
    .filter(r => getReservationFirstResourceStart(r, view) >= now && r.status !== 'paid')
    .sort((a, b) => getReservationFirstResourceStart(a, view) - getReservationFirstResourceStart(b, view))[0];
  const activeLabel = view === 'all'
    ? `${scopedReservations.length} réservation${scopedReservations.length > 1 ? 's' : ''} au total`
    : view === 'laser'
    ? `${activeSessions} lancement${activeSessions > 1 ? 's' : ''} en cours · ${activeLaserPlayers} joueurs laser`
    : `${activeSessions} session${activeSessions > 1 ? 's' : ''} en cours · ${activeLanes} piste${activeLanes > 1 ? 's' : ''} occupée${activeLanes > 1 ? 's' : ''}`;
  const nextLabel = nextArrival
    ? ` · prochaine ${view === 'laser' ? 'session' : 'arrivée'} ${formatClockDisplay(getReservationFirstResourceStart(nextArrival, view))}`
    : '';
  const dateLabel = document.getElementById('staffDateLabel');
  if (dateLabel) {
    const dateText = d.toLocaleDateString('fr-BE', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
    dateLabel.textContent = dateText.charAt(0).toUpperCase() + dateText.slice(1);
    dateLabel.dataset.now = new Date().toLocaleTimeString('fr-BE', { hour: '2-digit', minute: '2-digit' });
  }
  const dateShort = document.getElementById('staffDateShort');
  if (dateShort) {
    const shortDateText = d.toLocaleDateString('fr-BE', { weekday:'short', day:'numeric', month:'short', year:'numeric' }).replace(',', '');
    dateShort.textContent = shortDateText.charAt(0).toUpperCase() + shortDateText.slice(1);
  }
  const prevBtn = document.getElementById('staffPrevDateBtn');
  if (prevBtn) prevBtn.disabled = false;

  const planningSearchInput = document.getElementById('planningSearchInput');
  if (planningSearchInput && planningSearchInput !== document.activeElement) planningSearchInput.value = state.searchTerm || '';
  const laserPlanningSearchInput = document.getElementById('laserPlanningSearchInput');
  if (laserPlanningSearchInput && laserPlanningSearchInput !== document.activeElement) laserPlanningSearchInput.value = state.searchTerm || '';
  syncStaffResourceTabs(dayReservations, view);
}

function renderKpis() {
  const view = getStaffResourceView();
  const res = scopedStaffReservations(view);
  // La capacite DU CENTRE. Les armes se partagent entre les lancements
  // paralleles (le serveur compte les joueurs de tous les lancements qui se
  // chevauchent contre le nombre d armes) : six lancements a Gembloux ne font
  // pas six fois 20 places, et les multiplier divisait l occupation par six.
  const laneCount = getAvailabilityLaneCount();
  const armes = getAvailabilityLaserCapacity();
  let pax = 0, bookedUnits = 0;
  res.forEach(r => {
    pax += Number(r.pax) || 0;
    if (view === 'laser') {
      bookedUnits += getLaserWindowsFromReservation(r).reduce((sum, window) => sum + (Number(window.players || r.pax) || 0), 0);
    } else if (view === 'all') {
      bookedUnits += getBowlingWindowsFromReservation(r).reduce((sum, window) => sum + ((Number(window.duration) || 0) * Math.max((window.lanes || []).length, 1)), 0);
      bookedUnits += getLaserWindowsFromReservation(r).reduce((sum, window) => sum + ((Number(window.players || r.pax) || 0) / Math.max(armes, 1)), 0);
    } else {
      bookedUnits += getBowlingWindowsFromReservation(r).reduce((sum, window) => sum + ((Number(window.duration) || 0) * Math.max((window.lanes || []).length, 1)), 0);
    }
  });
  const windowCfg = getPlanningWindow(state.currentDate);
  // Sur la journee complete, une ressource que le centre n a pas n ajoute pas
  // de capacite : N4 (aucune arene) voyait son occupation diluee par un laser
  // fantome. Cle absente = on ne sait pas encore, on garde les deux.
  const ressources = (typeof getAdminCenter === 'function' ? (getAdminCenter() || {}).resources : null) || {};
  const connait = (kind) => Object.prototype.hasOwnProperty.call(ressources, kind);
  const avecPistes = !connait('bowling') || Number(ressources.bowling?.laneCount) > 0;
  const avecArene = !connait('laser') || Number(ressources.laser?.weaponCount) > 0;
  const heuresOuvertes = Math.max(windowCfg.close - windowCfg.open, 1);
  const lancementsDuJour = Math.max((windowCfg.close - windowCfg.open) * 2, 1);
  const totalAvail = windowCfg.closed
    ? 0
    : view === 'all'
      ? (avecPistes ? laneCount * heuresOuvertes : 0) + (avecArene ? lancementsDuJour : 0)
      : view === 'laser'
        ? armes * lancementsDuJour
        : laneCount * heuresOuvertes;
  const occ = totalAvail > 0 ? Math.round((bookedUnits / totalAvail) * 100) : 0;
  // LE BANDEAU DU PLANNING NE RECOPIE PLUS L ACCUEIL (2026-09-30). Ses quatre
  // cases redisaient reservations, joueurs, chiffre d affaires et occupation a
  // un autre perimetre que la Vue d ensemble (« 17, 2 057 EUR » sur l onglet
  // bowling, « 24, 3 437 EUR » sur l accueil) sans dire lequel ; le journal le
  // notait des le 2026-09-23 (« le planning qui repete les tuiles de
  // l accueil »). Il garde ce qui sert a planifier, perimetre dans le libelle :
  // l occupation de la ressource, ses reservations et joueurs, et le jour
  // meme, les pistes libres maintenant. L argent vit sur l accueil et la page
  // Reservations. Aucune case ne dit « aujourd hui » : l en-tete dit la date.
  const grid = document.querySelector('#staffView .kpi-grid');
  if (!grid) return;
  const ressource = view === 'laser' ? 'laser' : view === 'all' ? '' : 'bowling';
  const tiles = [
    {
      key: 'occupation',
      label: view === 'laser' ? 'Occupation de l’arène' : view === 'all' ? 'Occupation' : 'Occupation des pistes',
      id: 'kpiOcc',
      value: `${occ}%`,
      hint: view === 'all' ? 'pistes et arène, sur la journée' : 'sur la journée'
    },
    {
      key: 'reservations',
      label: ressource ? `Réservations ${ressource}` : 'Réservations',
      id: 'kpiRes',
      value: String(res.length),
      hint: `${pax} joueur${pax > 1 ? 's' : ''}`
    }
  ];
  const libres = view === 'laser' ? null : getStaffBowlingLanesFreeNow();
  if (libres) tiles.push({ key: 'libres', label: 'Libres maintenant', id: 'kpiFree', ...describeStaffLanesFreeNow(libres) });
  // Mise a jour EN PLACE quand les cases sont les memes : le bandeau porte
  // l animation d entree (.stagger), et le reconstruire a chaque sondage la
  // rejouerait toutes les quelques secondes.
  const signature = tiles.map(tile => tile.key).join('|');
  if (grid.dataset.tiles !== signature) {
    grid.dataset.tiles = signature;
    grid.innerHTML = tiles.map(tile => `<div class="kpi" data-kpi="${tile.key}"><div class="label"></div><div class="value" id="${tile.id}"></div><div class="hint"></div></div>`).join('');
  }
  tiles.forEach(tile => {
    const card = grid.querySelector(`[data-kpi="${tile.key}"]`);
    if (!card) return;
    card.querySelector('.label').textContent = tile.label;
    card.querySelector('.value').textContent = tile.value;
    const hint = card.querySelector('.hint');
    hint.textContent = tile.hint;
    hint.title = tile.hint;
    if (tile.title) card.title = tile.title; else card.removeAttribute('title');
  });
}

// LES PISTES LIBRES MAINTENANT, lues sur les memes sources que la grille :
// les reservations du jour (filtres et recherche ignores), les horaires
// retenus en ligne, les blocages de disponibilite et les pistes en
// maintenance. Le jour meme seulement, pendant l ouverture, et seulement une
// fois les blocages charges : avant, une piste fermee se dirait libre.
function getStaffBowlingLanesFreeNow() {
  if (state.currentDate !== todayStr()) return null;
  if (!availabilityBlocksCache.loaded) return null;
  const config = getPlanningWindow(state.currentDate);
  const now = currentTimeDecimal();
  if (config.closed || now < config.open || now >= config.close) return null;
  const laneCount = getAvailabilityLaneCount();
  if (!laneCount) return null;
  const prises = new Map();
  const prendre = (lane, start, end) => {
    const cle = Number(lane);
    if (!prises.has(cle)) prises.set(cle, []);
    prises.get(cle).push({ start: Number(start), end: Number(end) });
  };
  const poser = source => source.forEach(item => getBowlingWindowsFromReservation(item)
    .forEach(window => (window.lanes || []).forEach(lane => prendre(lane, window.start, window.end))));
  poser(todaysReservations());
  poser(getBlocagesEnLigne(state.currentDate));
  Object.entries(getBowlingBlockWindows(state.currentDate, config.open, config.close))
    .forEach(([lane, fenetres]) => fenetres.forEach(fenetre => prendre(lane, fenetre.startH, fenetre.endH)));
  const libres = [];
  const occupees = [];
  for (let lane = 1; lane <= laneCount; lane += 1) {
    if (state.laneStatuses[lane] === 'maintenance') continue;
    const fenetres = prises.get(lane) || [];
    const enCours = fenetres.filter(fenetre => fenetre.start <= now && fenetre.end > now);
    if (enCours.length) {
      occupees.push({ lane, until: Math.max(...enCours.map(fenetre => fenetre.end)) });
      continue;
    }
    const suivantes = fenetres.filter(fenetre => fenetre.start > now).map(fenetre => fenetre.start);
    libres.push({ lane, until: suivantes.length ? Math.min(...suivantes) : config.close });
  }
  return { libres, occupees, close: config.close };
}

function describeStaffLanesFreeNow({ libres, occupees, close }) {
  const liste = lanes => lanes.length > 1 ? `${lanes.slice(0, -1).join(', ')} et ${lanes[lanes.length - 1]}` : String(lanes[0]);
  if (!libres.length) {
    const prochaine = [...occupees].sort((left, right) => left.until - right.until)[0];
    return {
      value: 'Aucune',
      // Aucune piste prise et aucune libre : elles sont toutes en maintenance.
      hint: prochaine ? `la ${prochaine.lane} se libère à ${formatClockDisplay(prochaine.until)}` : 'toutes en maintenance'
    };
  }
  const bientot = [...libres].filter(item => item.until < close).sort((left, right) => left.until - right.until)[0];
  const pistes = libres.map(item => item.lane);
  return {
    value: `${libres.length} piste${libres.length > 1 ? 's' : ''}`,
    hint: bientot
      ? `${liste(pistes)} · la ${bientot.lane} jusqu’à ${formatClockDisplay(bientot.until)}`
      : `${liste(pistes)} · jusqu’à la fermeture`,
    title: libres.map(item => `Piste ${item.lane} libre jusqu’à ${item.until < close ? formatClockDisplay(item.until) : 'la fermeture'}`).join('\n')
  };
}

// La tete du planning ne redit pas les comptes des tuiles juste au-dessus
// (reservations, joueurs) : elle dit ce qu elles ne disent pas, les
// horaires du jour. Son titre compte les pistes que la grille dessine
// vraiment (getAvailabilityLaneCount), plus un « 8 » ecrit dans la page.
//
// ELLE SE DESSINE AVEC SA GRILLE, JAMAIS A PART. Elle etait posee par
// renderStaffShell et la grille par renderPlanning : quand la configuration du
// centre arrivait apres le premier rendu, les blocages redessinaient la grille
// (6 pistes) et le titre gardait la valeur par defaut (« Planning 8 pistes »),
// vu le 2026-09-25 dans la suite complete. Horaires et pistes viennent de la
// meme configuration : un seul chemin pour la tete et la grille.
function renderPlanningHead() {
  const planningWindow = getPlanningWindow(state.currentDate);
  const planningSub = document.getElementById('planningSub');
  if (planningSub) planningSub.textContent = planningWindow.closed ? 'Centre fermé ce jour-là' : `Ouvert ${planningWindow.label}`;
  const planningLaneTitle = document.getElementById('planningLaneTitle');
  if (planningLaneTitle) {
    const laneCount = getAvailabilityLaneCount();
    planningLaneTitle.textContent = `Planning ${laneCount} piste${laneCount > 1 ? 's' : ''}`;
  }
}

// UNE SURFACE IDENTIQUE NE SE RECONSTRUIT PAS (2026-10-07). Le sondage, le
// tic de l horloge et chaque geste re-rendent les deux plannings et la liste ;
// le plus souvent l une des trois (la grille cachee, celle que le geste n a
// pas touchee) ressort au caractere pres. La reconstruire coutait quand meme
// l analyse du HTML, le style, la mise en page, l accessibilite et la peinture
// de centaines d elements : sur tablette (processeur ralenti 4x, journee
// chargee), un re-rendu sans changement prenait plus d une demi-seconde.
// La surface n est gardee que si son HTML est identique ET si personne n a
// touche a son contenu depuis (classe posee par un geste, texte reecrit) : un
// observateur le note, et dans le doute on reconstruit. Au repos, l ecran est
// donc toujours celui d un rendu complet.
//
// CE QUE LE MOTION ECRIT N EST PAS UN ETAT. Ses classes d animation (pl-in de
// la cascade, pl-arrive, pl-pop, la couleur d un compteur qui monte ou
// descend), le delai de la cascade, le fantome d une carte partie et le texte
// d un compteur en course (data-pl-anim) changent la facon dont la surface
// S ANIME, pas ce qu elle montre : au repos, une carte qui les porte s affiche
// exactement comme une carte neuve. Les compter comme une retouche
// reconstruisait la liste au sondage suivant chaque cascade, et coupait au
// passage une animation en cours. Toute autre ecriture (classe d un geste,
// texte reecrit, noeud ajoute) reste une retouche.
var CLASSES_DU_MOTION = ['pl-in', 'pl-arrive', 'pl-pop', 'pl-num-up', 'pl-num-down'];
var rendusDeSurface = typeof WeakMap === 'function' ? new WeakMap() : null;
function sansDelaiDeCascade(style) {
  return String(style || '').replace(/(^|;)\s*animation-delay\s*:[^;]*;?/g, '$1').replace(/[\s;]+$/, '').trim();
}
function ecritureDuMotion(m) {
  const cible = m.target && m.target.nodeType === 1 ? m.target : m.target && m.target.parentNode;
  if (cible && cible.closest && cible.closest('[data-pl-anim]')) return true;
  if (m.type === 'attributes') {
    if (m.attributeName === 'data-pl-anim') return true;
    if (m.attributeName === 'class') {
      const avant = String(m.oldValue || '').split(/\s+/).filter(Boolean);
      const apres = String(m.target.getAttribute('class') || '').split(/\s+/).filter(Boolean);
      const change = avant.filter((c) => !apres.includes(c)).concat(apres.filter((c) => !avant.includes(c)));
      return change.every((c) => CLASSES_DU_MOTION.includes(c));
    }
    if (m.attributeName === 'style') return sansDelaiDeCascade(m.oldValue) === sansDelaiDeCascade(m.target.getAttribute('style'));
    return false;
  }
  if (m.type === 'childList') {
    const noeuds = [...m.addedNodes, ...m.removedNodes];
    return noeuds.length > 0 && noeuds.every((n) => n.nodeType === 1 && n.classList.contains('pl-fantome'));
  }
  return false;
}
function surfaceTouchee(conteneur, mutations) {
  return mutations.some((m) => !ecritureDuMotion(m) && (m.type === 'childList' || m.target !== conteneur));
}
function poserHtmlSurface(conteneur, html) {
  if (!conteneur) return false;
  if (!rendusDeSurface || typeof MutationObserver !== 'function') { conteneur.innerHTML = html; return true; }
  let suivi = rendusDeSurface.get(conteneur);
  if (suivi) {
    if (surfaceTouchee(conteneur, suivi.observateur.takeRecords())) suivi.touchee = true;
    if (!suivi.touchee && suivi.html === html) return false;
  } else {
    suivi = { html: '', touchee: false, observateur: null };
    suivi.observateur = new MutationObserver((mutations) => { if (surfaceTouchee(conteneur, mutations)) suivi.touchee = true; });
    suivi.observateur.observe(conteneur, { childList: true, subtree: true, attributes: true, attributeOldValue: true, characterData: true });
    rendusDeSurface.set(conteneur, suivi);
  }
  conteneur.innerHTML = html;
  suivi.observateur.takeRecords();
  suivi.html = html;
  suivi.touchee = false;
  return true;
}
// Une variable de style reecrite a l identique invalide quand meme le style de
// toute la boite : on ne l ecrit que si elle change.
function poserVariableSiChange(el, nom, valeur) {
  if (el && el.style.getPropertyValue(nom) !== valeur) el.style.setProperty(nom, valeur);
}

function renderPlanning() {
  ensureAvailabilityBlocksForPlanning();
  ensureStaffCenterConfigForPlanning();
  renderPlanningHead();
  const wrap = document.getElementById('planningGridWrap');
  const planningBox = document.getElementById('planningBox');
  // Le re-render (polling 4s / 60s) reconstruit innerHTML et remet le scroll à 0.
  // On mémorise la position pour ne pas faire sauter la vue en mode plein écran.
  // Lue avant le rendu, reposée après (voir ouvrirLotDefilement).
  const [prevScrollTop, prevScrollLeft] = lireDefilementRendu(wrap);
  const config = planningDisplayWindow('bowling');
  if (config.closed && !config.showExisting) {
    poserHtmlSurface(wrap, '<div class="empty-state"><div class="e-title">Centre fermé ce jour</div><div class="e-sub">Aucun nouveau créneau disponible.</div></div>');

    return;
  }

  const startHour = config.open;
  const closeHour = config.close;
  const totalHours = Math.max(closeHour - startHour, 1);
  const halfSlots = totalHours * 2;
  // P1-11 : mobile : cellules plus hautes pour des cibles tactiles correctes
  // (slot 30 min = HH/2 = 44px). Le zoom horizontal vient du CSS (largeur de
  // piste lisible + scroll du wrap), la hauteur vient d'ici (positions px JS).
  const compactTouch = !state.staffPlanningExpanded
    && typeof window.matchMedia === 'function'
    && window.matchMedia('(max-width: 768px)').matches;
  const verticalInset = state.staffPlanningExpanded ? 3 : 1;
  // INVARIANT DE NON-CHEVAUCHEMENT, et c'est la cause racine du « bug graphique
  // avec les cartes » : la hauteur MINIMALE d'une carte ne doit JAMAIS dépasser
  // la hauteur du plus petit créneau que la grille sait produire (30 min, soit
  // HH/2, moins les deux marges verticales). Le plein écran violait cet
  // invariant : il laissait la ligne d'heure tomber à 34px (créneau de 30 min =
  // 17px) tout en imposant 40px de hauteur minimale à chaque carte. Résultat,
  // deux réservations qui ne se croisent PAS dans le temps se croisaient à
  // l'écran. On pose donc la hauteur de carte lisible d'abord, et on en DÉDUIT
  // le plancher de la ligne d'heure.
  const MIN_CARD_H = compactTouch ? 42 : 22;
  const MIN_HOUR_H = (MIN_CARD_H + verticalInset * 2) * 2;
  let HH = state.staffPlanningExpanded ? 52 : compactTouch ? 88 : 48;
  // Les réglages restent dans l'en-tête : leur cible fait 44 px + 2 px de marge.
  // Les cartes et l'aperçu de déplacement utilisent la même hauteur.
  const HEADER_H = compactTouch ? 38 : 46;
  if (state.staffPlanningExpanded) {
    // Plein écran comptoir : toutes les heures d'ouverture doivent tenir d'une
    // traite, sans scroll vertical. La hauteur de ligne n'est donc PAS fixe :
    // on la calcule pour remplir la hauteur disponible.
    // Hauteur totale de la grille = HEADER_H (ligne d'en-tête pistes)
    //   + totalHours * HH (les heures pleines)
    //   + HH/2 (la cellule de fin) => facteur (totalHours + 0.5).
    // On retire une marge de sécurité pour l'éventuelle scrollbar horizontale
    // (pistes larges) afin de ne jamais déborder verticalement.
    // Quand la fenêtre est trop courte pour ça (zoom 200 %, petit écran), la
    // grille défile verticalement : mieux vaut faire défiler que superposer.
    const SCROLLBAR_SAFETY = 14;
    const availableHeight = wrap.clientHeight
      || (window.innerHeight - HEADER_H - 64);
    const usableHeight = availableHeight - HEADER_H - SCROLLBAR_SAFETY;
    const computedHeight = Math.floor(usableHeight / (totalHours + 0.5));
    HH = Math.max(MIN_HOUR_H, computedHeight);
  }
  if (planningBox) {
    poserVariableSiChange(planningBox, '--planning-header-h', `${HEADER_H}px`);
    poserVariableSiChange(planningBox, '--planning-hour-h', `${HH}px`);
    poserVariableSiChange(planningBox, '--planning-hour-col', state.staffPlanningExpanded ? '76px' : '54px');
  }
  const res = getPlanningVisibleReservations('bowling').filter(r => getBowlingWindowsFromReservation(r).length > 0);
  const isToday = state.currentDate === todayStr();
  const curH = currentTimeDecimal();
  const curPos = isToday && curH >= startHour && curH <= closeHour ? (curH - startHour) * HH + HEADER_H : -1;

  // L ETIQUETTE QUE LE BADGE DE L HEURE COURANTE RECOUVRE S EFFACE. Chaque
  // etiquette est centree dans sa demi-heure ; a 23:56, « 23:30 » depassait a
  // moitie au-dessus du badge et « 00:00 » en dessous. Mesure : demi-badge
  // 9 px, demi-etiquette 7 px (8 en plein ecran), plus 2 px d air. Une
  // etiquette dont le centre tombe a moins de 19 px du badge laisse la place a
  // l heure exacte, qui la remplace.
  const sousLeBadge = (centre) => curPos >= HEADER_H && Math.abs(centre - curPos) < 19;
  let hoursHtml = '';
  for (let slot = 0; slot < halfSlots; slot++) {
    const timeValue = startHour + (slot * 0.5);
    const isHalf = slot % 2 === 1;
    const cache = sousLeBadge(HEADER_H + ((slot + 0.5) * (HH / 2)));
    hoursHtml += `<div class="hour-cell ${isHalf ? 'minor' : 'major'}${cache ? ' is-under-now' : ''}">
      <span class="${isHalf ? 'hour-label-half' : 'hour-label-hour'}">${formatClockDisplay(timeValue)}</span>
    </div>`;
  }
  const finCachee = sousLeBadge(HEADER_H + ((halfSlots + 0.5) * (HH / 2)));
  hoursHtml += `<div class="hour-cell end${finCachee ? ' is-under-now' : ''}"><span class="hour-label-end">${formatClockDisplay(closeHour)}</span></div>`;

  const laneBlockWindows = getBowlingBlockWindows(state.currentDate, startHour, closeHour);
  // Nombre de pistes REEL du centre affiche (config staff chargee), avec repli sur
  // la constante historique quand la config n'est pas encore disponible. Corrige le
  // planning qui affichait 8 pistes en dur meme pour un centre a 6 pistes. Ne touche
  // QUE le nombre de lignes rendues : l'allocation et le drag-drop restent inchanges.
  const planningLaneCount = getAvailabilityLaneCount();
  const blocagesDuJour = getBlocagesEnLigne(state.currentDate)
    .flatMap(b => getBowlingWindowsFromReservation(b).map(window => ({ blocage: b, window })));
  let lanesHtml = '';
  for (let i = 1; i <= planningLaneCount; i++) {
    const maint = state.laneStatuses[i] === 'maintenance';
    const bookings = res.flatMap(r => getBowlingWindowsFromReservation(r)
      .filter(window => window.lanes.includes(i))
      .map(window => ({ reservation: r, window })));
    let cells = '';
    for (let slot = 0; slot < halfSlots; slot++) {
      const cellTime = startHour + (slot * 0.5);
      const halfClass = slot % 2 === 1 ? ' half' : '';
      cells += maint || config.closed
        ? `<div class="slot-cell${halfClass}"></div>`
        : `<div class="slot-cell clickable${halfClass}" role="button" tabindex="0" aria-label="Réserver la piste ${i} à ${formatClockDisplay(cellTime)}" data-bowling-drop-lane="${i}" data-bowling-drop-start="${cellTime}" onclick="quickFromCell(${i},${cellTime})" title="Nouvelle réservation"></div>`;
    }
    cells += `<div class="slot-cell end"></div>`;
    let bkHtml = '';
    bookings.forEach(item => {
      const r = item.reservation;
      const st = item.window.start;
      if (st < startHour || st >= closeHour) return;
      const top = (st - startHour) * HH + HEADER_H + verticalInset;
      const rawHeight = (Number(item.window.duration) * HH) - (verticalInset * 2);
      // MIN_CARD_H tient par construction dans un créneau de 30 min (cf.
      // l'invariant plus haut) : ce plancher ne peut donc plus faire mordre
      // une carte sur la suivante.
      const height = Math.max(rawHeight, MIN_CARD_H);
      const end = formatClockDisplay(item.window.end);
      let cls = 'conf';
      if (r.status === 'arrived') cls = 'arr';
      if (r.status === 'paid') cls = 'paid';
      const densClass = getBookingDensityClass(height, state.staffPlanningExpanded);
      const displayName = getPlanningBookingDisplayName(r);
      const fullName = String(r.name || 'Client');
      const delayedClass = getReservationDelayFlag(r) ? ' is-delayed' : '';
      const bowlingDuration = Number(item.window.duration) || 0;
      const statsHtml = renderCardStats(Number(item.window.players) || getReservationActivityPlayers(r, 'bowling'), formatCardDurationLabel(bowlingDuration), { special: isSpecialBowlingDuration(bowlingDuration), durationTitle: formatDurationLabel(bowlingDuration), bowlingCapacity: item.window.bowlingCapacity });
      // L'OFFRE N'A SA PROPRE LIGNE QUE SI LA CARTE A LA HAUTEUR DE L'OFFRIR.
      // Mesure : une carte d'1h fait 46px, dont 44 utiles ; trois lignes (nom,
      // offre, chiffres) en demandent 56. L'offre partage donc la ligne des
      // chiffres sur les cartes courtes, exactement comme le libelle d'activite
      // le faisait avant, avec le mecanisme qui la fait ceder toute seule quand
      // la place manque. Sur une carte de 1h30 et plus, elle a la place et la
      // prend : c'est la hauteur reelle qui decide, pas une preference.
      const offreHtml = renderCardActivityTag(r, 'bowling');
      const offreSurSaLigne = densClass === 'dens-lg';
      // LE PRIX NEGOCIE SE VOIT SUR LA CARTE, PAS SEULEMENT DANS LA LISTE.
      // La carte n affichait aucun montant : un geste commercial de 20 EUR ne
      // se decouvrait qu en descendant dans la liste du bas. Le montant y
      // apparait maintenant, mais UNIQUEMENT quand il s ecarte de la
      // reference : un prix catalogue n a rien a signaler.
      // DEUX DENSITES, PAS UNE. La premiere version ne posait la pastille que
      // sur les cartes `dens-lg` (1h30 et plus) : le dossier meme que la demande
      // cite en exemple, une partie de 30 minutes arrangee a 40 EUR au lieu de
      // 60, restait muet. La carte d une heure (`dens-md`) a son pied a elle et
      // la porte donc aussi. La carte de 30 minutes ne l a pas, et c est mesure,
      // pas choisi : en `dens-xs` la tete et le pied passent en
      // `display: contents` (feuille de style, .booking.dens-xs), donc nom,
      // marqueurs, retard, etat, offre, effectif et duree se disputent UNE seule
      // ligne qui a deja son echelle de cession complete. Le montant y reste
      // lisible dans la liste du meme ecran, une ligne plus bas.
      // LE PLANCHER DE PLACE SUIT LA LONGUEUR DU MONTANT, PAS LE PIRE CAS. Un
      // plancher unique calcule sur trois chiffres retirait « 40 € » de pistes
      // ou il tenait largement : mesure, 0 pastille a 1280 px comme a 390 px
      // alors que la carte avait 19 px de rab. La classe dit la longueur, la
      // feuille de style pose un plancher par longueur.
      const etatPrix = getReservationPriceState(r);
      const chiffresPrix = String(Math.abs(Math.round(etatPrix.price))).length;
      const classeLongueur = chiffresPrix <= 2 ? 'bk-price-c2' : chiffresPrix === 3 ? 'bk-price-c3' : 'bk-price-c4';
      const prixHtml = (densClass === 'dens-lg' || densClass === 'dens-md')
        ? renderReservationPriceMark(r, { forme: 'montant', base: `bk-price ${classeLongueur}` })
        : '';
      // Le badge laser prend la place libre d un pied qui n a pas deja l offre
      // (renderCardLaserBadge) ; une formule d une heure, dont l offre occupe
      // cette place, garde son marqueur laser dans la tete : l offre passe
      // avant. Pas de badge sur une carte d une seule ligne.
      const progressionHtml = renderActivityProgressPill(r);
      const laserHtml = densClass === 'dens-xs' || (!offreSurSaLigne && offreHtml) ? '' : renderCardLaserBadge(r);
      const casLaser = laserHtml ? ' a-laser-pied' : '';
      bkHtml += `<div class="booking ${cls} ${densClass} ${getReservationHighlightClasses(r)}${delayedClass}${activitiesCompleteClass(r)}${casLaser}" data-booking-res-id="${r.id}" data-booking-lane="${i}" data-booking-start="${st}" data-range="${formatClockDisplay(st)} - ${end}" data-extra="${cls === 'paid' ? 'payé' : cls === 'arr' ? 'sur place' : 'confirmé'}" role="button" tabindex="0" aria-label="${escapeHtml(r.name || 'Client')} · ${formatClockDisplay(st)} - ${end}" style="top:${top}px;height:${height}px;--bk-order:${i};" aria-keyshortcuts="M" onkeydown="planningMoveKey(event,'bowling',${r.id},${i},${st})" onmousedown="startBowlingBookingPointerDrag(event, ${r.id}, ${i}, ${st})" ${planningTouchAttrs(`startBowlingBookingTouchDrag(event, ${r.id}, ${i}, ${st})`)} onclick="if(shouldIgnoreBowlingDragClick(event)) return; event.stopPropagation();openPos(${r.id})">
        <div class="booking-head">
          <span class="bk-time">${formatClockDisplay(st)}</span>
          <span class="booking-name" title="${escapeHtml(fullName)}">${escapeHtml(displayName)}</span>
          ${renderCardFlags(r)}
          ${/* LA PUCE DE RETARD PREND SA PLACE AU LIEU DE FLOTTER DESSUS. Elle
               etait posee en position absolue en haut a droite de la carte, donc
               par-dessus la tete : mesure, une puce de 42 px de large recouvrait
               le nom (105 px de tete) et les icones d activite. Movsar,
               2026-08-26 : « le logo pour laser game est cache par le logo en
               retard ». Elle entre donc dans la ligne, apres les marques, et
               cede son libelle toute seule quand la carte est trop courte
               (regle .booking.dens-xs deja en place). */''}
          ${renderDelayIndicator(r)}
          ${renderBookingStateMark(cls)}
        </div>
        ${offreSurSaLigne ? `<div class="booking-offer">${offreHtml}</div>` : ''}
        <div class="booking-foot">
          ${offreSurSaLigne ? '' : offreHtml}
          ${laserHtml}
          ${statsHtml}
          ${prixHtml}
          ${progressionHtml}
        </div>
      </div>`;
    });
    // LES HORAIRES RETENUS PAR UN CLIENT EN LIGNE : la piste est prise, pas
    // encore reservee. Une carte en attente, sans nom (le client n en a pas
    // encore donne) et sans action : elle recouvre les cases de la piste pour
    // qu aucune reservation n y soit lancee, le serveur la refuserait.
    let holdHtml = '';
    blocagesDuJour.forEach(item => {
      if (!item.window.lanes.includes(i)) return;
      const st = item.window.start;
      if (st < startHour || st >= closeHour) return;
      const top = (st - startHour) * HH + HEADER_H + verticalInset;
      const height = Math.max((Number(item.window.duration) * HH) - (verticalInset * 2), MIN_CARD_H);
      const heure = heureLiberationBlocage(item.blocage);
      const texte = texteBlocageEnLigne(item.blocage);
      holdHtml += `<div class="planning-hold" data-hold-lane="${i}" data-hold-start="${st}" style="top:${top}px;height:${height}px;" role="note" aria-label="${escapeHtml(`Piste ${i}, ${formatClockDisplay(st)} - ${formatClockDisplay(item.window.end)} : ${texte}`)}" title="${escapeHtml(texte)}">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg>
        <span class="planning-hold__txt"><b>En ligne</b>${heure ? ` <small>libre à ${escapeHtml(heure)}</small>` : ''}</span>
      </div>`;
    });
    const laneWins = laneBlockWindows[i] || [];
    let blockHtml = '';
    laneWins.forEach(w => {
      const blkTop = (w.startH - startHour) * HH + HEADER_H;
      const blkHeight = Math.max((w.endH - w.startH) * HH, 16);
      const blkReason = w.reason ? w.reason : (w.full ? 'Bloqué toute la journée' : 'Créneau bloqué');
      blockHtml += `<div class="planning-blocked${w.full ? ' full' : ''}" data-blocked-lane="${i}" style="top:${blkTop}px;height:${blkHeight}px;" title="${escapeHtml(blkReason)}"><span>${escapeHtml(blkReason)}</span></div>`;
    });
    lanesHtml += `<div class="lane-col ${maint ? 'maint' : ''}${laneWins.length ? ' has-block' : ''}" data-lane="${i}"${laneWins.length ? ' data-blocked="1"' : ''}>
      <div class="lane-header">
        <span class="pl">Piste</span>
        <span class="num">${i}</span>
        <button class="settings" onclick="toggleMaint(${i}, event)" title="Maintenance" aria-label="Parametres piste ${i}">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>
        </button>
      </div>
      ${cells}
      ${bkHtml}
      ${holdHtml}
      ${blockHtml}
    </div>`;
  }

  // L'HEURE COURANTE EN DEUX MORCEAUX, et c'est voulu : la barre traverse les
  // pistes, l'étiquette vit DANS la colonne d'heures. La colonne d'heures est
  // collante à gauche : l'étiquette reste donc lisible même quand on fait
  // glisser un planning à 40 pistes vers la droite. Avant, elle était posée sur
  // la barre elle-même et sortait du cadre au premier défilement.
  const nowBadge = curPos >= HEADER_H
    ? `<div class="current-badge" style="top:${curPos}px" aria-hidden="true">${formatClockDisplay(curH)}</div>`
    : '';
  poserHtmlSurface(wrap, `
    ${planningClosedNotice(config)}
    <div class="planning-grid">
      ${curPos >= HEADER_H ? `<div class="current-line" style="top:${curPos}px"></div>` : ''}
      <div class="hour-col">
        <div class="hour-header">Heure</div>
        ${hoursHtml}
        ${nowBadge}
      </div>
      <div class="lanes-row">${lanesHtml}</div>
    </div>`);
  poserDefilementRendu(wrap, prevScrollTop, prevScrollLeft);
  markPlanningGridFresh(wrap, state.currentDate);
  refreshPlanningMoveHighlights();
}

// L'ANIMATION D'ENTREE NE JOUE QU'AU CHANGEMENT DE JOURNEE.
// Le planning se redessine au sondage reseau toutes les 60 secondes : une
// animation posee sans condition rejouerait a chaque tour, et un ecran qui
// clignote toutes les minutes derriere un comptoir n'est pas anime, il est
// casse. On compare donc la journee rendue a la precedente et on ne marque la
// grille que quand elle a vraiment change de jour. La classe se retire des la
// derniere carte arrivee, pour qu'un re-rendu suivant ne la retrouve pas posee.
function markPlanningGridFresh(wrap, dateKey) {
  if (!wrap) return;
  const precedente = wrap.dataset.renderedDate || '';
  wrap.dataset.renderedDate = String(dateKey || '');
  if (precedente === String(dateKey || '')) return;
  wrap.classList.add('is-fresh');
  const cartes = wrap.querySelectorAll('.booking').length;
  window.setTimeout(() => wrap.classList.remove('is-fresh'), 320 + cartes * 22);
}

function getPlanningBookingDisplayName(reservation) {
  const fullName = String(reservation?.name || 'Client').trim();
  if (fullName.length <= 26) return fullName;
  const id = fullName.match(/#\d+\b/)?.[0] || '';
  const activityMatch = fullName.match(/\s+(?:formule|bowling|laser(?: game)?)(?:\s|$)/i);
  let base = activityMatch ? fullName.slice(0, activityMatch.index).trim() : fullName;
  if (!base) base = fullName;
  base = base.replace(/^Anniversaire\b/i, 'Anniv.');
  let candidate = id && !base.includes(id) ? `${base} ${id}` : base;
  if (candidate.length <= 26) return candidate;
  // Un mot generique en tete (Visite, Famille, Groupe...) ne dit pas QUI :
  // c est lui qui saute, jamais le nom propre. Garder le premier mot
  // affichait « Visite » pour « Visite Collège Saint-Joseph » (2026-10-08).
  // Ce qui reste trop long, la carte le coupe a l ellipse, ou sur deux lignes
  // quand elle est haute.
  const propre = base.replace(/^(?:visite|famille|groupe|soir[ée]e|team|f[êe]te|sortie|classe|anniv\.)\s+/i, '').trim() || base;
  return id && !propre.includes(id) ? `${propre} ${id}` : propre;
}

// ── LE PLANNING LASER : LE TABLEAU DES DEPARTS (lot I3, 2026-10-08) ─────────
// Maquette E validee par Movsar le 08/10 (« ça va », a rendre plus pro). Un
// rang par depart (:00 et :30), la jauge des armes du centre remplie par les
// groupes ; en tete le prochain depart et ses armes a preparer, la partie en
// jeu et les groupes en retard avec le geste qui les decale ; en bas les
// parties a placer. Toucher un groupe du jour ouvre sa fiche ; le deplacer :
// le glisser, aussi loin qu il faut (la page defile toute seule), ou le
// prendre (appui long au doigt, M au clavier) puis toucher son depart. Une
// partie a placer : la toucher puis son depart. Les departs possibles
// s allument, toucher un autre dit pourquoi il ne va pas.
// Le moteur ne change pas : memes unites (partie.vague), meme PATCH
// activityMove (scheduleLaserPass / unscheduleLaserPass), meme verdict du
// serveur. L ecran explique d avance ce que le serveur dirait.

const lpEtat = { choisi: null, raison: '', geste: null, glisse: null, enCours: null, joues: true, journeeScope: null, differe: false, ignorerClicJusqua: 0, defile: null };

function lpMinutes() {
  const activite = (typeof getCenterActivities === 'function' ? getCenterActivities() : []).find(a => a && a.id === 'laser_game') || {};
  return {
    jeu: Number(activite.gameMinutes || activite.defaultMinutes) || 22,
    briefing: Number(activite.briefingMinutes) || 8,
    bloc: LASER_GAME_ARENA_MINUTES,
  };
}

function lpHeure(t) { return formatClockDisplay(t); }
function lpDuree(minutes) {
  const m = Math.max(0, Math.round(minutes));
  if (m < 60) return `${m} min`;
  const h = Math.floor(m / 60);
  const reste = m % 60;
  return reste ? `${h} h ${String(reste).padStart(2, '0')}` : `${h} h`;
}
function lpPluriel(n, mot) { return `${n} ${mot}${Math.abs(n) > 1 ? 's' : ''}`; }
function lpCourt(nom) { return String(nom || 'Groupe').replace(/^Famille\s+/i, ''); }
function lpRang(k) { return Number(k) === 1 ? '1re' : `${Number(k)}e`; }

// Les joueurs qu une fenetre RETIENT sur l arene (30 quand le groupe la
// privatise) et ceux du GROUPE (ce que l equipe compte et equipe).
function lpArene(w) { return Math.max(0, Number(w.players || w.reservation?.pax || 0)); }
function lpGroupe(w) { return Math.max(1, Number(w.joueursReels ?? w.players) || Number(w.reservation?.pax) || 1); }

function lpBlocages(jour) {
  if (typeof availabilityBlocksCache === 'undefined' || !availabilityBlocksCache.loaded) return [];
  return getAvailabilityBlocksForDate(jour)
    .filter(b => b.scopeType === 'center' || (b.scopeType === 'activity' && b.scopeRef === 'laser_game'))
    .map(b => {
      const a = availabilityBlockStartMin(b);
      const z = availabilityBlockEndMin(b);
      return { debut: a == null ? 0 : a / 60, fin: z == null ? 24 : z / 60, raison: b.reason || '', centre: b.scopeType === 'center' };
    });
}

// LA COULEUR D UN GROUPE EST CELLE DE SON ETAT (Movsar, 2026-10-09 : huit
// teintes, « trop de couleurs comme ca, ca fait pas pro » ; choix « Couleur de
// l etat » sur maquettes). La legende du planning bowling, la meme sur les
// deux ecrans : bleu confirme, ambre arrive, vert paye ; un groupe pas venu
// passe au gris. Deux groupes voisins d un meme depart dans le meme etat
// s alternent en deux tons (is-alt), pour qu on voie ou l un finit.
function lpTeinte(r) {
  if (r.absentAt && r.status !== 'paid') return 'st-absent';
  if (r.status === 'paid') return 'st-paid';
  if (r.status === 'arrived') return 'st-arr';
  return 'st-conf';
}
// LES PICTOS DES CARTES BOWLING, APRES LE NOM (2026-10-09, Movsar : « Pictos
// du bowling »). Les memes marques que la tete d une carte bowling : la note a
// lire, l anniversaire, et le prix ajuste en signal (l etiquette de prix que
// la carte bowling pose devant son montant). Le marqueur laser n a rien a dire
// sur un planning ou tout le monde joue au laser : `partiesEcrites` le retire.
// Chaque marque est titree et vocalisee (role="img") et ne porte aucun texte :
// le nom et le compte du groupe se lisent comme avant.
function lpPictos(r) {
  const marques = renderCardFlags(r, { partiesEcrites: true }) + renderReservationPriceMark(r, { forme: 'signal', base: 'bk-flag flag-prix' });
  return marques ? `<span class="lp-pictos">${marques}</span>` : '';
}
function lpTeintesDuDepart(d) {
  const teintes = new Map();
  let avant = '';
  let alt = false;
  d.ici.forEach(w => {
    const t = lpTeinte(w.reservation);
    alt = t === avant ? !alt : false;
    avant = t;
    teintes.set(w, alt ? `${t} is-alt` : t);
  });
  return teintes;
}

// LA JOURNEE EN DONNEES : chaque depart avec ses groupes, ce qu il reste,
// ce qui le ferme ; le prochain depart, la partie en jeu, les retards ; les
// parties a placer. Tous les dossiers comptent (la recherche ne fait que
// griser) : une jauge ne ment jamais sur les armes.
function lpModele() {
  const jour = state.currentDate;
  const config = planningDisplayWindow('laser');
  const capacite = getAvailabilityLaserCapacity();
  const lancements = getAvailabilityLaserParallelLaunches();
  const minutes = lpMinutes();
  const bloc = minutes.bloc / 60;
  const aujourdHui = jour === todayStr();
  const maintenant = aujourdHui ? currentTimeDecimal() : (jour < todayStr() ? 48 : -1);
  const resas = todaysReservations();
  const fenetres = resas.flatMap(r => getLaserWindowsFromReservation(r).map(w => ({ ...w, reservation: r })));
  const enLigne = getBlocagesEnLigne(jour).flatMap(b => getLaserWindowsFromReservation(b).map(w => ({ ...w, reservation: b, enLigne: true })));
  const attente = getPendingLaserPasses(jour)
    .slice()
    .sort((a, b) => timeToNum(a.reservation.startTime || '00:00') - timeToNum(b.reservation.startTime || '00:00') || a.countIndex - b.countIndex || a.waveIndex - b.waveIndex);
  // UNE PARTIE HORS GRILLE SE RANGE AU DEPART LE PLUS PROCHE (2026-10-09). A
  // la demi-heure inferieure, la vague de 17:25 comptait au depart de 17:00
  // en plus de celle de 16:55 encore en jeu : « 45, 15 de trop » pour 23
  // armes au plus, et 16:30 se disait pris par une partie qui ne commence
  // qu a 16:55. Au plus proche (a egalite, le plus tot), une partie de 25 min
  // chevauche toujours son depart, et chaque rang compte ce qui chevauche
  // [t, t + bloc), comme ensureLaserCapacity cote serveur.
  const creneau = (debut) => config.open + Math.round((Number(debut) - config.open) * 2 - 0.001) / 2;
  const blocages = lpBlocages(jour);
  const recherche = String(state.searchTerm || '').trim().toLowerCase();
  const trouve = (r) => !recherche || `${r.name || ''} ${r.phone || ''} ${r.email || ''}`.toLowerCase().includes(recherche);

  const cles = new Set();
  for (let t = config.open; t < config.close - 0.001; t += 0.5) cles.add(Math.round(t * 60));
  fenetres.concat(enLigne).forEach(w => cles.add(Math.round(creneau(w.start) * 60)));
  const departs = [...cles].sort((a, b) => a - b).map(m => {
    const t = m / 60;
    const fin = t + bloc;
    const dedans = (w) => Math.abs(creneau(w.start) - t) < 0.001;
    const ici = fenetres.filter(dedans).sort((a, b) => Number(a.reservation.id) - Number(b.reservation.id) || Number(a.countIndex || 1) - Number(b.countIndex || 1));
    const holds = enLigne.filter(dedans);
    const chevauche = fenetres.concat(enLigne).filter(w => !dedans(w) && w.start < fin - 0.001 && w.end > t + 0.001);
    const occupe = [...ici, ...holds, ...chevauche].reduce((s, w) => s + lpArene(w), 0);
    const ferme = blocages.find(b => b.debut < fin - 0.001 && b.fin > t + 0.001) || null;
    const hors = t < config.open - 0.001 || t > config.close - 0.5 + 0.001;
    return {
      t, fin, ici, holds, chevauche, occupe,
      places: capacite - occupe,
      ferme, hors,
      joue: maintenant >= t + minutes.jeu / 60,
      enJeu: maintenant >= t && maintenant < t + minutes.jeu / 60,
    };
  });

  // Le prochain depart est celui de l horloge (le suivant, ouvert), qu il ait
  // des groupes ou non, comme la maquette : la liste reprend APRES lui.
  const prochain = aujourdHui ? departs.find(d => d.t > maintenant + 0.0001 && !d.ferme && !d.hors) || null : null;
  const enJeu = aujourdHui ? departs.find(d => d.enJeu && d.ici.length) || null : null;

  // LES RETARDS : le meme mot que la liste (« En retard », lot I1), pour un
  // groupe dont le depart laser est passe. « Decaler a » vise le premier
  // depart ou toutes ses parties suivantes tiennent, du meme ecart.
  let retards = [];
  if (aujourdHui && typeof getStaffReservationMoments === 'function') {
    const moments = getStaffReservationMoments(resas, jour);
    retards = resas
      .filter(r => getStaffListeSection(moments, r) === 'late')
      .map(r => {
        const siennes = fenetres.filter(w => Number(w.reservation.id) === Number(r.id)).sort((a, b) => a.start - b.start);
        const manquee = siennes.find(w => w.start <= maintenant + 0.0001);
        if (!manquee) return null;
        return { reservation: r, fenetre: manquee, cible: lpCibleDecalage({ departs, capacite, lancements, maintenant, bloc }, r, siennes.filter(w => w.start >= manquee.start - 0.0001), manquee.start) };
      })
      .filter(Boolean)
      .sort((a, b) => a.fenetre.start - b.fenetre.start);
  }

  return { jour, config, capacite, lancements, minutes, bloc, aujourdHui, maintenant, resas, fenetres, enLigne, attente, departs, prochain, enJeu, retards, trouve, creneau };
}

function lpCibleDecalage(modele, reservation, siennes, depuis) {
  const id = Number(reservation.id);
  const libre = (t, fenetre) => {
    const d = modele.departs.find(x => Math.abs(x.t - t) < 0.001);
    if (!d || d.ferme || d.hors) return false;
    const autres = [...d.ici, ...d.holds, ...d.chevauche].filter(w => Number(w.reservation?.id) !== id);
    if (autres.some(w => w.arene === 'seuls') || (fenetre.arene === 'seuls' && autres.length)) return false;
    const sessions = new Set(autres.map(w => `${Math.round(w.start * 60)}-${Math.round(w.end * 60)}`));
    const cle = `${Math.round(t * 60)}-${Math.round((t + fenetre.end - fenetre.start) * 60)}`;
    if (sessions.size + (sessions.has(cle) ? 0 : 1) > modele.lancements) return false;
    return autres.reduce((s, w) => s + lpArene(w), 0) + lpArene(fenetre) <= modele.capacite;
  };
  const candidats = modele.departs.filter(d => d.t > modele.maintenant + 0.0001 && d.t > depuis);
  for (const d of candidats) {
    const ecart = d.t - depuis;
    if (siennes.every(w => libre(w.start + ecart, w))) return d.t;
  }
  return null;
}

// Le groupe choisi, s il existe encore ce jour, dans ce centre.
function lpChoisiValide(modele) {
  const c = lpEtat.choisi;
  if (!c) return null;
  if (c.date !== state.currentDate || c.centre !== getCurrentStaffCenterId()) { lpEtat.choisi = null; return null; }
  const reservation = modele.resas.find(r => Number(r.id) === c.id);
  if (!reservation) { lpEtat.choisi = null; return null; }
  const placee = modele.fenetres.find(w => Number(w.reservation.id) === c.id && laserBlockUnitKey(w) === c.unitKey) || null;
  const enAttente = modele.attente.find(p => Number(p.reservation.id) === c.id && p.unitKey === c.unitKey) || null;
  if (!placee && !enAttente) { lpEtat.choisi = null; return null; }
  const unite = laserUnitInfo(reservation, c.unitKey);
  // Le choix sauvegarde reste valable quand aucune partie n est placee.
  // buildActivityMove retient alors toute l arene, pas seulement le groupe.
  const prive = placee ? placee.arene === 'seuls' : reservation.opsPlan?.arene === 'seuls';
  return {
    id: c.id,
    unitKey: c.unitKey,
    reservation,
    placee,
    countIndex: unite.countIndex,
    waveIndex: unite.waveIndex,
    waveCount: unite.waveCount,
    arene: placee ? lpArene(placee) : prive ? modele.capacite : Math.max(1, Number(unite.players) || 1),
    groupe: placee ? lpGroupe(placee) : Math.max(1, Number(enAttente?.players || unite.players) || 1),
    prive,
  };
}

function lpNomUnite(c) {
  const parts = [];
  if (Number(c.countIndex || 1) > 1) parts.push(`${lpRang(c.countIndex)} partie`);
  if (Number(c.waveCount || c.groupWaveCount || 1) > 1) parts.push(`vague ${Number(c.waveIndex || c.groupWaveIndex || 1)}/${Number(c.waveCount || c.groupWaveCount || 1)}`);
  return parts.join(' · ');
}

// CE DEPART PEUT-IL LA PRENDRE ? Les regles du serveur, dites d avance :
// ouvert, pas passe, le groupe n y joue pas deja, ses parties restent dans
// l ordre, son autre activite ne tombe pas dessus, les armes et les
// lancements tiennent.
function lpVerdict(modele, choisi, d) {
  const h = lpHeure(d.t);
  if (choisi.placee && Math.abs(modele.creneau(choisi.placee.start) - d.t) < 0.001) return { ok: false, ici: true, raison: `Elle est déjà à ${lpHeure(choisi.placee.start)}.` };
  if (modele.config.closed) return { ok: false, raison: 'Centre fermé ce jour.' };
  if (d.ferme) return { ok: false, raison: `${h} : ${d.ferme.centre ? 'centre fermé' : 'Laser Game bloqué'}${d.ferme.raison ? ` (${d.ferme.raison})` : ''}.` };
  if (d.hors) return { ok: false, raison: `${h} : hors des horaires du jour.` };
  if (modele.aujourdHui && d.t <= modele.maintenant + 0.0001) return { ok: false, raison: `${h} : ce départ est déjà parti.` };
  const id = choisi.id;
  const siennes = modele.fenetres.filter(w => Number(w.reservation.id) === id && laserBlockUnitKey(w) !== choisi.unitKey);
  const fin = d.t + modele.bloc;
  const dessus = siennes.find(w => w.start < fin - 0.001 && w.end > d.t + 0.001);
  if (dessus) return { ok: false, raison: `${h} : ce groupe y joue déjà${lpNomUnite(dessus) ? ` (${lpNomUnite(dessus)})` : ''}.` };
  const avant = siennes.filter(w => Number(w.countIndex || 1) < choisi.countIndex && w.start >= d.t - 0.001).sort((a, b) => b.start - a.start)[0];
  if (avant) return { ok: false, raison: `${h} : avant sa ${lpRang(avant.countIndex)} partie (${lpHeure(avant.start)}).` };
  const apres = siennes.filter(w => Number(w.countIndex || 1) > choisi.countIndex && w.start <= d.t + 0.001).sort((a, b) => a.start - b.start)[0];
  if (apres) return { ok: false, raison: `${h} : après sa ${lpRang(apres.countIndex)} partie (${lpHeure(apres.start)}).` };
  const pax = Math.max(1, Number(choisi.reservation.pax) || 1);
  const bowling = getBowlingWindowsFromReservation(choisi.reservation).find(w => w.start < fin - 0.001 && w.end > d.t + 0.001);
  if (bowling && choisi.groupe + Math.max(0, Number(bowling.players) || pax) > pax) {
    return { ok: false, raison: `${h} : son bowling est de ${lpHeure(bowling.start)} à ${lpHeure(bowling.end)}.` };
  }
  const autres = [...d.ici, ...d.holds, ...d.chevauche].filter(w => !(Number(w.reservation?.id) === id && laserBlockUnitKey(w) === choisi.unitKey));
  const occupe = autres.reduce((s, w) => s + lpArene(w), 0);
  const prive = autres.find(w => w.arene === 'seuls');
  if (prive) return { ok: false, raison: `${h} : arène privatisée par ${prive.reservation?.name || 'un groupe'}.` };
  if (choisi.prive && autres.length) return { ok: false, raison: `${h} : ce groupe a l’arène pour lui seul, il lui faut un départ vide.` };
  if (occupe + choisi.arene > modele.capacite) {
    const reste = Math.max(0, modele.capacite - occupe);
    return { ok: false, raison: reste ? `${h} : il reste ${lpPluriel(reste, 'place')}, il en faut ${choisi.arene}.` : `${h} : complet.` };
  }
  const sessions = new Set(autres.map(w => `${Math.round(w.start * 60)}-${Math.round(w.end * 60)}`));
  const cle = `${Math.round(d.t * 60)}-${Math.round(fin * 60)}`;
  if (sessions.size + (sessions.has(cle) ? 0 : 1) > modele.lancements) {
    return { ok: false, raison: modele.lancements > 1 ? `${h} : l’arène tourne déjà ${modele.lancements} lancements.` : `${h} : un autre lancement tourne déjà à cette heure.` };
  }
  return { ok: true, apres: occupe + choisi.arene };
}

// ── LE RENDU ──────────────────────────────────────────────────────────────
function lpCases(modele, d, choisi, verdict) {
  const cases = [];
  const pousser = (n, classe, attrs = '') => { for (let i = 0; i < n; i += 1) cases.push(`<i${classe ? ` class="${classe}"` : ''}${attrs}></i>`); };
  const teintes = lpTeintesDuDepart(d);
  d.ici.forEach(w => {
    const k = teintes.get(w);
    const groupe = lpGroupe(w);
    const estChoisi = choisi && Number(w.reservation.id) === choisi.id && laserBlockUnitKey(w) === choisi.unitKey;
    // Les cases du groupe le portent : on les attrape pour le deplacer.
    const attrs = ` data-lp-id="${Number(w.reservation.id)}" data-lp-unit="${escapeHtml(laserBlockUnitKey(w))}"`;
    pousser(groupe, `${k}${estChoisi ? ' is-choisi' : ''}`, attrs);
    if (w.arene === 'seuls') pousser(Math.max(0, lpArene(w) - groupe), `${k} is-prive`, attrs);
  });
  d.holds.forEach(w => pousser(lpArene(w), 'is-enligne'));
  d.chevauche.forEach(w => pousser(lpArene(w), 'is-chevauche'));
  if (choisi && verdict && verdict.ok) pousser(choisi.arene, 'is-fantome');
  const vides = Math.max(0, modele.capacite - cases.length);
  pousser(vides, '');
  return cases.slice(0, Math.max(modele.capacite, 1)).join('');
}

// Un groupe du jour : le toucher ouvre sa fiche, le glisser le deplace
// (Movsar, 2026-10-08 : « Ouvrir sa fiche ») ; au doigt, un appui long sans
// bouger le prend aussi, et au clavier la touche M. Une partie a placer : la
// toucher la prend, puis on touche son depart (la maquette).
function lpAttrsGroupe(id, unitKey, { fiche = false } = {}) {
  const toucher = fiche ? `lpToucherGroupe(${id}, event)` : `lpChoisir(${id}, '${unitKey}', event)`;
  const clavier = fiche ? ` onkeydown="lpClavierGroupe(event, ${id}, '${unitKey}')" aria-keyshortcuts="M"` : '';
  return `data-laser-res-id="${id}" data-laser-unit="${unitKey}" onclick="${toucher}"${clavier} onmousedown="lpSouris(event, ${id}, '${unitKey}')" ${planningTouchAttrs(`lpDoigt(event, ${id}, '${unitKey}')`)}`;
}

// Les armes d un lancement parti plus tot (place a la main hors de la grille)
// et encore en jeu a ce depart : la jauge les hachure, le texte dit pourquoi.
function lpEncore(d) {
  const enJeu = d.chevauche.filter(w => !w.enLigne);
  if (!enJeu.length) return '';
  return `${enJeu.reduce((s, w) => s + lpArene(w), 0)} en jeu jusqu’à ${lpHeure(Math.max(...enJeu.map(w => w.end)))}`;
}

function lpLegende(modele, d, choisi) {
  const encore = lpEncore(d);
  if (!d.ici.length && !d.holds.length) {
    if (d.ferme) {
      const label = `${d.ferme.centre ? 'Centre fermé' : 'Laser Game bloqué'}${d.ferme.raison ? ` · ${d.ferme.raison}` : ''}`;
      return `<span class="lp-libre" title="${escapeHtml(label)}">${escapeHtml(label)}</span>`;
    }
    if (d.hors) return '<span class="lp-libre" title="Hors des horaires">Hors des horaires</span>';
    if (d.joue) return `<span class="lp-libre" title="${escapeHtml(encore || 'Personne')}">${encore || 'Personne'}</span>`;
    return `<span class="lp-libre" title="${escapeHtml(`${encore || 'Libre'} · toucher pour réserver`)}">${encore || 'Libre'} · toucher pour réserver</span>`;
  }
  const teintes = lpTeintesDuDepart(d);
  const groupes = d.ici.map(w => {
    const r = w.reservation;
    const id = Number(r.id);
    const unitKey = laserBlockUnitKey(w);
    const k = teintes.get(w);
    const suite = [lpNomUnite(w), w.arene === 'seuls' ? 'arène pour eux seuls' : '', Math.abs(w.start - d.t) > 0.001 ? `à ${lpHeure(w.start)}` : '']
      .filter(Boolean).join(' · ');
    const etat = r.absentAt && r.status !== 'paid' ? ' is-absent' : (r.status === 'arrived' || r.status === 'paid') ? ' is-la' : '';
    const choisiIci = choisi && choisi.id === id && choisi.unitKey === unitKey ? ' is-choisi' : '';
    const grise = modele.trouve(r) ? '' : ' is-grise';
    const titre = `${r.name || 'Groupe'} : ${lpPluriel(lpGroupe(w), 'joueur')}${suite ? `, ${suite}` : ''}. Toucher : sa fiche. Glisser : le déplacer.`;
    const statut = r.status === 'paid' ? 'Payé' : r.absentAt ? 'Pas venu' : r.status === 'arrived' ? 'Arrivé' : 'Confirmé';
    const partie = Number(w.countIndex || 1);
    const totalParties = getLaserGameCountForReservation(r);
    const vague = Number(w.waveIndex || w.groupWaveIndex || 1);
    const vagues = Number(w.waveCount || w.groupWaveCount || 1);
    const infos = `${lpGroupe(w)} j · P${partie}/${totalParties}${vagues > 1 ? ` · V${vague}/${vagues}` : ''} · fin ${lpHeure(w.end)}${w.arene === 'seuls' ? ' · privée' : ''}${Math.abs(w.start - d.t) > 0.001 ? ` · à ${lpHeure(w.start)}` : ''}`;
    return `<button type="button" class="lp-g ${k}${etat}${choisiIci}${grise}" ${lpAttrsGroupe(id, unitKey, { fiche: true })} title="${escapeHtml(`${titre} ${infos} · ${statut}`)}"><i aria-hidden="true"></i><b>${escapeHtml(r.name || 'Groupe')}</b>${lpPictos(r)}<span class="lp-card-status">${statut}</span><span class="lp-card-info">${escapeHtml(infos)}</span></button>`;
  });
  // Un client retient ces armes en ligne : la carte dit quand elles se
  // liberent (comme la carte du planning bowling) et ne lance rien au toucher.
  d.holds.forEach(w => {
    const libre = heureLiberationBlocage(w.reservation);
    groupes.push(`<span class="lp-g is-enligne" title="${escapeHtml(texteBlocageEnLigne(w.reservation))}" onclick="event.stopPropagation()"><i aria-hidden="true"></i><b>En ligne</b> <span>${lpArene(w)} · ${libre ? `libre à ${escapeHtml(libre)}` : 'en cours'}</span></span>`);
  });
  if (encore) groupes.push(`<span class="lp-libre">+ ${encore}</span>`);
  return groupes.join('');
}

function lpCompte(modele, d, verdict) {
  if (verdict && verdict.ok) return `<b class="is-plus">${verdict.apres}</b> <small>après</small>`;
  if (d.places < 0) return `<b class="is-trop">${d.occupe}</b> <small class="is-trop">${-d.places} de trop</small>`;
  if (!d.occupe) return `<b>0</b> <small>${lpPluriel(modele.capacite, 'place')}</small>`;
  return `<b>${d.occupe}</b> <small${d.places === 0 ? ' class="is-plein"' : ''}>${d.places === 0 ? 'complet' : lpPluriel(d.places, 'place')}</small>`;
}

function lpRangDepart(modele, d, choisi) {
  const verdict = choisi ? lpVerdict(modele, choisi, d) : null;
  const classes = ['lp-dep'];
  if (d.joue && modele.aujourdHui) classes.push('is-joue');
  if (d.enJeu) classes.push('is-enjeu');
  if (modele.prochain && modele.prochain.t === d.t) classes.push('is-prochain');
  if (!d.ici.length && !d.holds.length) classes.push('is-vide');
  if (d.ferme || d.hors) classes.push('is-ferme');
  if (d.places < 0) classes.push('is-trop');
  if (verdict) classes.push(verdict.ok ? 'is-cible' : verdict.ici ? 'is-ici' : 'is-terne');
  if (lpEtat.enCours && Math.abs(lpEtat.enCours.t - d.t) < 0.001) classes.push('is-pose');
  const h = lpHeure(d.t);
  const qui = [
    ...d.ici.map(w => `${w.reservation.name || 'Groupe'} ${lpGroupe(w)}`),
    ...d.holds.map(w => {
      const libre = heureLiberationBlocage(w.reservation);
      return `En ligne ${lpArene(w)}${libre ? `, libre à ${libre}` : ''}`;
    }),
  ].join(', ');
  const encore = lpEncore(d);
  const reste = d.places < 0 ? `, ${-d.places} de trop` : `, ${lpPluriel(Math.max(0, d.places), 'place')}`;
  const toucher = d.places > 0 && !d.joue && !d.ferme && !d.hors ? ` Toucher pour réserver à ${h}.` : '';
  const etiquette = verdict
    ? (verdict.ok ? `Placer ici, à ${h} : ${verdict.apres} sur ${modele.capacite} après.` : verdict.raison)
    : d.ici.length || d.holds.length || d.occupe
      ? `${h} : ${d.occupe} sur ${modele.capacite}${reste}.${qui ? ` ${qui}.` : ''}${encore ? ` ${encore}.` : ''}${toucher}`
      : `${h} : libre, ${lpPluriel(modele.capacite, 'place')}.${toucher}`;
  return `<div class="${classes.join(' ')}" data-laser-time-start="${d.t}" data-lp-t="${d.t}" onclick="lpToucherDepart(${d.t}, event)">
    <span class="lp-dep__h">${h}</span>
    <button type="button" class="lp-dep__jauge" data-lp-t="${d.t}" aria-label="${escapeHtml(etiquette)}" onclick="lpToucherDepart(${d.t}, event)" onmousedown="lpSourisJauge(event)" ${planningTouchAttrs('lpDoigtJauge(event)')}><span class="lp-cases" aria-hidden="true">${lpCases(modele, d, choisi, verdict)}</span></button>
    <span class="lp-dep__n">${lpCompte(modele, d, verdict)}</span>
    <div class="lp-qui">${lpLegende(modele, d, choisi)}</div>
  </div>`;
}

function lpProchainHtml(modele) {
  const d = modele.prochain;
  if (!modele.aujourdHui) return '';
  if (!d) {
    return '<section class="lp-prochain is-calme" aria-label="Prochain départ"><div class="lp-prochain__quand"><span class="lp-lbl">Prochain départ</span> <span class="lp-prochain__d">Plus aucun départ aujourd’hui.</span></div></section>';
  }
  const maintenantMin = modele.maintenant * 60;
  const briefing = d.t * 60 - modele.minutes.briefing;
  const quand = maintenantMin >= briefing ? 'briefing en cours' : `briefing dans ${lpDuree(briefing - maintenantMin)}`;
  if (!d.ici.length) {
    return `<section class="lp-prochain is-calme" data-lp-t="${d.t}" aria-label="Prochain départ, ${lpHeure(d.t)}">
      <div class="lp-prochain__quand"><span class="lp-lbl">Prochain départ</span> <span class="lp-prochain__t">${lpHeure(d.t)}</span> <span class="lp-prochain__d">Personne pour l’instant</span></div>
      <span class="lp-prochain__g"><b>${Math.max(0, d.places)}</b> <small>place${Math.max(0, d.places) > 1 ? 's' : ''} libre${Math.max(0, d.places) > 1 ? 's' : ''}</small></span>
    </section>`;
  }
  const armes = d.ici.reduce((s, w) => s + (w.reservation.absentAt && w.reservation.status !== 'paid' ? 0 : lpGroupe(w)), 0);
  const groupes = d.ici.map(w => {
    const r = w.reservation;
    const unitKey = laserBlockUnitKey(w);
    const k = lpTeinte(r);
    const la = r.status === 'arrived' || r.status === 'paid';
    const absent = r.absentAt && r.status !== 'paid';
    const detail = [lpPluriel(lpGroupe(w), 'joueur'), lpNomUnite(w), w.arene === 'seuls' ? 'arène pour eux seuls' : ''].filter(Boolean).join(' · ');
    const action = absent
      ? '<span class="lp-etat lp-etat--absent">Pas venus</span>'
      : la
        ? `<span class="lp-etat lp-etat--la"><svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3.5 8.5l3 3 6-7"/></svg>Arrivés</span>`
        : `<button type="button" class="lp-etat lp-etat--marquer" onclick="lpIlsSontLa(${Number(r.id)}, event)">Ils sont là</button>`;
    return `<div class="lp-groupe ${k}"><button type="button" class="lp-groupe__sel" ${lpAttrsGroupe(Number(r.id), unitKey, { fiche: true })} title="${escapeHtml(`${r.name || 'Groupe'} : toucher pour sa fiche, glisser pour le déplacer`)}"><span class="lp-pastille" aria-hidden="true"></span> <span class="lp-groupe__t"><span class="lp-nom"><b>${escapeHtml(r.name || 'Groupe')}</b>${lpPictos(r)}</span> <span class="lp-n">${escapeHtml(detail)}</span></span></button>${action}</div>`;
  }).join('');
  return `<section class="lp-prochain" data-lp-t="${d.t}" aria-label="Prochain départ, ${lpHeure(d.t)}">
    <div class="lp-prochain__quand"><span class="lp-lbl">Prochain départ</span> <span class="lp-prochain__t">${lpHeure(d.t)}</span> <span class="lp-prochain__d">${quand}</span></div>
    <div class="lp-groupes">${groupes}</div>
    <span class="lp-prochain__g"><b>${armes}</b> <small>arme${armes > 1 ? 's' : ''} à préparer</small></span>
  </section>`;
}

function lpBandeHtml(modele) {
  if (!modele.aujourdHui) return '';
  const e = modele.enJeu;
  const jeu = e
    ? (() => {
      const fait = Math.min(1, Math.max(0, (modele.maintenant - e.t) * 60 / modele.minutes.jeu));
      const reste = Math.max(0, e.t * 60 + modele.minutes.jeu - modele.maintenant * 60);
      return `<div class="lp-jeu"><span class="lp-lbl">En jeu</span> <b>${lpHeure(e.t)}</b> <span class="lp-prog" role="progressbar" aria-label="Partie de ${lpHeure(e.t)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(fait * 100)}"><i style="width:${Math.round(fait * 100)}%"></i></span> <span class="lp-fin">fin dans ${lpDuree(reste)}</span></div>`;
    })()
    : `<div class="lp-jeu is-libre"><span class="lp-lbl">Arène</span> <b>Libre</b>${modele.prochain ? `<span class="lp-fin">jusqu’à ${lpHeure(modele.prochain.t)}</span>` : ''}</div>`;
  const alertes = modele.retards.slice(0, 3).map(a => {
    const r = a.reservation;
    const id = Number(r.id);
    const ecart = a.cible == null ? null : Math.round((a.cible - a.fenetre.start) * 60);
    const decaler = a.cible == null
      ? '<span class="lp-alerte__rien">Aucun départ libre pour eux aujourd’hui</span>'
      : `<button type="button" class="lp-btn lp-btn--rouge" onclick="lpDecaler(${id}, ${ecart}, event)">Décaler à ${lpHeure(a.cible)}</button>`;
    return `<div class="lp-alerte" role="status"><svg width="18" height="18" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="8" cy="8" r="6.2"/><path d="M8 4.6v4M8 11.2v.2"/></svg><span class="lp-alerte__t"><b>${escapeHtml(lpCourt(r.name))}</b> pas venus à ${lpHeure(a.fenetre.start)}</span>${decaler}<button type="button" class="lp-lien" onclick="lpPasVenus(${id}, event)">Pas venus</button></div>`;
  }).join('');
  return `<div class="lp-bande${alertes ? '' : ' is-seule'}">${jeu}${alertes ? `<div class="lp-alertes">${alertes}</div>` : ''}</div>`;
}

// La journee affiche toute la grille d ouverture, meme les departs vides et
// le prochain depart resume en tete. L operateur peut masquer le passe pour
// cette journee ; le choix d un groupe ne decale plus les lignes sous le doigt.
function lpJourneeHtml(modele, choisi) {
  const scope = `${state.currentDate}|${getCurrentStaffCenterId()}`;
  if (lpEtat.journeeScope !== scope) {
    lpEtat.journeeScope = scope;
    lpEtat.joues = true;
  }
  const parti = (d) => modele.aujourdHui && d.t <= modele.maintenant + 0.0001;
  // Le compte dit les departs JOUES (la partie finie) ; la grille inclut aussi
  // les anciens creneaux vides et la partie encore en jeu.
  const jouesAvecGroupes = modele.departs.filter(d => modele.aujourdHui && d.joue && d.ici.length).length;
  const montres = modele.departs.filter(d => {
    if (!modele.aujourdHui) return true;
    if (parti(d)) return lpEtat.joues;
    return true;
  });
  const tete = jouesAvecGroupes
    ? `<button type="button" class="lp-passe" onclick="lpBasculerJoues(event)" aria-expanded="${lpEtat.joues ? 'true' : 'false'}">${lpPluriel(jouesAvecGroupes, 'départ')} joué${jouesAvecGroupes > 1 ? 's' : ''} · ${lpEtat.joues ? 'Masquer' : 'Afficher'}</button>`
    : '';
  const rangs = montres.map(d => lpRangDepart(modele, d, choisi)).join('');
  return `<section class="lp-journee" aria-label="La journée">
    <div class="lp-journee__h"><span class="lp-lbl">La journée</span>${tete}</div>
    ${rangs || `<div class="lp-vide">${modele.aujourdHui && !lpEtat.joues && modele.departs.some(parti) ? 'Les départs passés sont masqués.' : 'Aucun départ ce jour.'}</div>`}
  </section>`;
}

function lpFileHtml(modele, choisi) {
  const jetons = modele.attente.map(p => {
    const r = p.reservation;
    const id = Number(r.id);
    const k = lpTeinte(r);
    const sous = p.countIndex > 1 || p.waveCount > 1
      ? lpNomUnite({ countIndex: p.countIndex, waveIndex: p.waveIndex, waveCount: p.waveCount })
      : `arrive vers ${escapeHtml(String(r.startTime || '').slice(0, 5))}`;
    const choisiIci = choisi && choisi.id === id && choisi.unitKey === p.unitKey ? ' is-choisi' : '';
    const grise = modele.trouve(r) ? '' : ' is-grise';
    return `<button type="button" class="lp-jeton ${k}${choisiIci}${grise}" ${lpAttrsGroupe(id, p.unitKey)} title="${escapeHtml(`${r.name || 'Groupe'} : ${lpPluriel(p.players, 'joueur')}, ${sous}. Toucher, puis toucher son départ.`)}"><span class="lp-jeton__n">${p.players}</span> <span class="lp-jeton__t"><span class="lp-nom"><b>${escapeHtml(r.name || 'Groupe')}</b>${lpPictos(r)}</span> <small>${sous}</small></span></button>`;
  }).join('');
  let bandeau = '';
  if (choisi) {
    const nom = `<b>${escapeHtml(choisi.reservation.name || 'Groupe')} (${choisi.groupe})</b>${lpNomUnite(choisi) ? ` · ${escapeHtml(lpNomUnite(choisi))}` : ''}`;
    const texte = lpEtat.enCours
      ? `Placement de ${nom} à ${lpHeure(lpEtat.enCours.t)}…`
      : lpEtat.raison
        ? escapeHtml(lpEtat.raison)
        : choisi.placee
          ? `Déplacer ${nom}, à ${lpHeure(choisi.placee.start)} ? Touchez un départ en bleu.`
          : `Où placer ${nom} ? Touchez un départ en bleu.`;
    const retirer = choisi.placee && !lpEtat.enCours ? '<button type="button" class="lp-btn" onclick="lpRetirer(event)">Retirer du planning</button>' : '';
    bandeau = `<div class="lp-placer${lpEtat.raison ? ' is-raison' : ''}" role="status" aria-live="polite"><span class="lp-placer__t">${texte}</span> <span class="lp-placer__a"><button type="button" class="lp-btn" onclick="lpFiche(event)">Fiche</button>${retirer}<button type="button" class="lp-btn" onclick="lpAnnuler(event)">Annuler</button></span></div>`;
  }
  const n = modele.attente.length;
  return `<div class="lp-file${n ? '' : ' is-vide'}${choisi ? ' is-choix' : ''}" aria-label="Parties à placer">
    ${bandeau}
    <div class="lp-file__h"><span class="lp-lbl">À placer</span> <span class="lp-file__n">${n}</span> <span class="lp-aide">${n ? 'Touchez un groupe, puis son départ' : choisi && choisi.placee ? 'Glissez un groupe ici pour le retirer du planning' : 'Toutes les parties sont placées'}</span></div>
    ${n ? `<div class="lp-jetons">${jetons}</div>` : ''}
  </div>`;
}

function lpHtml(modele) {
  const choisi = lpChoisiValide(modele);
  return `<div class="lp lp-compact${choisi ? ' is-choix' : ''}" style="--lp-cases:${Math.max(1, modele.capacite)};--lp-departs:${Math.max(1, modele.departs.length)}">
    ${planningClosedNotice(modele.config)}
    ${modele.aujourdHui ? `<div class="lp-synthese">${lpProchainHtml(modele)}${lpBandeHtml(modele)}</div>` : ''}
    ${lpJourneeHtml(modele, choisi)}
    ${lpFileHtml(modele, choisi)}
  </div>`;
}

// Les joueurs se comptent une fois par dossier, comme la case « Réservations
// laser » juste au-dessus (renderKpis : la somme des pax) : un groupe qui joue
// deux parties n est pas deux fois plus de monde (139 contre 114 sur la meme
// page, 2026-10-08).
function lpSousTitre(modele) {
  const lancements = modele.departs.filter(d => d.ici.length).length;
  const dossiers = new Map();
  [...modele.fenetres, ...modele.attente].forEach(x => dossiers.set(Number(x.reservation.id), x.reservation));
  const joueurs = [...dossiers.values()].reduce((s, r) => s + (Number(r.pax) || 0), 0);
  const attente = modele.attente.length;
  const enLigne = new Set(modele.enLigne.map(w => w.reservation.id)).size;
  return [
    lpPluriel(lancements, 'départ'),
    lpPluriel(joueurs, 'joueur'),
    attente ? `${attente} à placer` : '',
    enLigne ? `${enLigne} en ligne en cours` : '',
  ].filter(Boolean).join(' · ');
}

// Le focus survit au repeint : meme groupe (dossier et partie), sinon meme
// depart. Sans ca, le clavier retombait sur la page a chaque sondage.
function lpFocusAvant(wrap) {
  const actif = document.activeElement;
  if (!actif || !wrap.contains(actif)) return null;
  if (actif.dataset.laserResId) return `[data-laser-res-id="${actif.dataset.laserResId}"][data-laser-unit="${actif.dataset.laserUnit}"]`;
  if (actif.dataset.lpT) return `.lp-dep__jauge[data-lp-t="${actif.dataset.lpT}"]`;
  const onclick = actif.getAttribute('onclick');
  return onclick ? `[onclick="${onclick.replace(/"/g, '\\"')}"]` : null;
}

function renderLaserPlanning() {
  ensureAvailabilityBlocksForPlanning();
  ensureStaffCenterConfigForPlanning();
  const wrap = document.getElementById('laserPlanningGridWrap');
  const sub = document.getElementById('laserPlanningSub');
  if (!wrap) return;
  // Pendant un glisser, rien ne se repeint sous le doigt : le sondage et le
  // tic attendent le lacher, puis le repeint se fait (rien n est perdu).
  if (lpEtat.glisse) { lpEtat.differe = true; return; }
  const [prevScrollTop, prevScrollLeft] = lireDefilementRendu(wrap);
  const focus = lpFocusAvant(wrap);
  const modele = lpModele();
  if (sub) sub.textContent = modele.config.closed && !modele.config.showExisting ? 'Centre fermé' : lpSousTitre(modele);
  if (modele.config.closed && !modele.config.showExisting) {
    poserHtmlSurface(wrap, '<div class="empty-state"><div class="e-title">Centre fermé ce jour</div><div class="e-sub">Aucun nouveau créneau disponible.</div></div>');
    return;
  }
  poserHtmlSurface(wrap, lpHtml(modele));
  lpAjusterJournee(wrap);
  poserDefilementRendu(wrap, prevScrollTop, prevScrollLeft);
  if (focus && !wrap.contains(document.activeElement)) {
    const cible = wrap.querySelector(focus);
    if (cible) cible.focus({ preventScroll: true });
  }
}

// Meme principe que le Bowling : la hauteur suit la place disponible, sans
// comprimer les noms au-dessous du plancher lisible. Seul le rendu change.
function lpAjusterJournee(wrap) {
  const lp = wrap.querySelector('.lp-compact');
  const journee = lp && lp.querySelector('.lp-journee');
  if (!journee || window.innerWidth <= 900) return;
  const rows = journee.querySelectorAll('.lp-dep').length;
  if (!rows) return;
  const file = lp.querySelector('.lp-file');
  const head = journee.querySelector('.lp-journee__h');
  // Le stock garde une seule ligne ; le bandeau de placement utilise cette
  // reserve constante. Une file vide ne reserve pas la hauteur de jetons.
  const fileReserve = file && file.querySelector('.lp-jeton') ? 108 : 80;
  const dayTop = journee.getBoundingClientRect().top;
  const available = window.innerHeight - dayTop
    - (head ? head.getBoundingClientRect().height : 0) - fileReserve - 24;
  const columns = window.innerWidth >= 1100 ? 2 : 1;
  journee.classList.toggle('is-two-columns', columns > 1);
  const columnRows = Math.ceil(rows / columns);
  const rowHeight = Math.max(22, Math.floor(available / columnRows));
  lp.classList.toggle('lp-cards-tight', rowHeight < 38);
  poserVariableSiChange(lp, '--lp-row-height', `${rowHeight}px`);
  poserVariableSiChange(lp, '--lp-group-font', rowHeight >= 26 ? '14px' : '13px');
  poserVariableSiChange(lp, '--lp-hour-font', rowHeight >= 26 ? '16px' : '14px');
  poserVariableSiChange(lp, '--lp-hour-column', rowHeight >= 26 ? '60px' : '44px');
  poserVariableSiChange(lp, '--lp-count-font', rowHeight >= 26 ? '14px' : '12px');
  poserVariableSiChange(lp, '--lp-unit-font', rowHeight >= 26 && columns < 3 ? '12px' : '10px');
  poserVariableSiChange(lp, '--lp-count-width', rowHeight >= 26 && columns < 3 ? '92px' : '70px');
  poserVariableSiChange(lp, '--lp-column-rows', String(columnRows));
  poserVariableSiChange(lp, '--lp-columns', String(columns));
  const heading = journee.querySelector('.lp-journee__h .lp-lbl');
  if (heading) heading.textContent = columns > 1 ? 'La journée · lecture de gauche à droite' : 'La journée';
}

let lpResizeFrame = 0;
window.addEventListener('resize', () => {
  if (lpResizeFrame) cancelAnimationFrame(lpResizeFrame);
  lpResizeFrame = requestAnimationFrame(() => {
    lpResizeFrame = 0;
    const wrap = document.getElementById('laserPlanningGridWrap');
    if (wrap && !lpEtat.glisse) lpAjusterJournee(wrap);
  });
});
document.addEventListener('focusin', event => {
  const alertAction = event.target && event.target.closest ? event.target.closest('.lp-compact .lp-alertes button') : null;
  if (alertAction) requestAnimationFrame(() => {
    if (document.activeElement !== alertAction) return;
    const scroller = alertAction.closest('.lp-alertes');
    const item = alertAction.getBoundingClientRect();
    const frame = scroller.getBoundingClientRect();
    if (item.right > frame.right) scroller.scrollLeft += item.right - frame.right + 2;
    else if (item.left < frame.left) scroller.scrollLeft -= frame.left - item.left + 2;
  });
  const group = event.target && event.target.closest ? event.target.closest('.lp-compact .lp-qui .lp-g') : null;
  if (!group) return;
  const scroller = group.closest('.lp-qui');
  const item = group.getBoundingClientRect();
  const frame = scroller.getBoundingClientRect();
  if (item.right > frame.right) scroller.scrollLeft += item.right - frame.right + 2;
  else if (item.left < frame.left) scroller.scrollLeft -= frame.left - item.left + 2;
});

// ── LES GESTES ─────────────────────────────────────────────────────────────
function lpChoisir(id, unitKey, ev) {
  if (ev) { ev.preventDefault(); ev.stopPropagation(); }
  if (Date.now() < lpEtat.ignorerClicJusqua || lpEtat.enCours) return;
  const meme = lpEtat.choisi && lpEtat.choisi.id === Number(id) && lpEtat.choisi.unitKey === String(unitKey);
  lpEtat.choisi = meme ? null : { id: Number(id), unitKey: String(unitKey), date: state.currentDate, centre: getCurrentStaffCenterId() };
  lpEtat.raison = '';
  renderLaserPlanning();
}

function lpToucherGroupe(id, ev) {
  if (ev) { ev.preventDefault(); ev.stopPropagation(); }
  // Le clic qui suit un glisser lache n est pas un toucher.
  if (Date.now() < lpEtat.ignorerClicJusqua || lpEtat.enCours) return;
  // Pendant un placement, toute la rangee vise son depart, ses groupes
  // compris : on ne tombe pas dans une fiche en plein geste.
  const rang = lpEtat.choisi && ev && ev.currentTarget && ev.currentTarget.closest ? ev.currentTarget.closest('[data-lp-t]') : null;
  if (rang) { lpViser(Number(rang.dataset.lpT)); return; }
  openPos(Number(id));
}

function lpClavierGroupe(ev, id, unitKey) {
  if ((ev.key !== 'm' && ev.key !== 'M') || ev.ctrlKey || ev.metaKey || ev.altKey) return;
  lpChoisir(id, unitKey, ev);
}

function lpAnnuler(ev) {
  if (ev) { ev.preventDefault(); ev.stopPropagation(); }
  if (lpEtat.enCours) return;
  lpEtat.choisi = null;
  lpEtat.raison = '';
  renderLaserPlanning();
}

function lpFiche(ev) {
  if (ev) { ev.preventDefault(); ev.stopPropagation(); }
  const c = lpEtat.choisi;
  if (c) openPos(c.id);
}

function lpBasculerJoues(ev) {
  if (ev) { ev.preventDefault(); ev.stopPropagation(); }
  lpEtat.joues = !lpEtat.joues;
  renderLaserPlanning();
}

// « Voir au planning » depuis la fiche : un groupe dont toutes les parties
// placees sont jouees (ou en jeu) est dans le pli des departs joues. On
// l ouvre, sinon le planning dirait qu il n a aucune partie placee.
function lpRevelerGroupe(id) {
  if (state.currentDate !== todayStr()) return;
  const modele = lpModele();
  const siens = modele.departs.filter(d => d.ici.some(w => Number(w.reservation.id) === Number(id)));
  if (siens.length && siens.every(d => d.t <= modele.maintenant + 0.0001)) lpEtat.joues = true;
}

function lpReserver(t, places) {
  const pax = Math.max(1, Math.min(4, Number(places) || 4));
  openQuickBook({ date: state.currentDate, startTime: numToTime(t), type: 'laser', duration: 0.5, totalDuration: 0.5, pax, allowPastStart: true, pastStartDate: state.currentDate, pastStartTime: numToTime(t) });
}

// « + Réserver » de la tete : le premier depart encore ouvert qui a de la
// place (aujourd hui, apres maintenant), sinon la fenetre a son heure a elle.
function lpReserverAuProchain(ev) {
  if (ev) ev.stopPropagation();
  const modele = lpModele();
  const d = modele.departs.find(x => !x.joue && !x.ferme && !x.hors && x.places > 0 && (!modele.aujourdHui || x.t > modele.maintenant + 0.0001));
  if (d) lpReserver(d.t, d.places);
  else openQuickBook({ date: state.currentDate, type: 'laser', duration: 0.5, totalDuration: 0.5 });
}

// LES CASES D UN GROUPE SE PRENNENT COMME SON NOM (Movsar, 2026-10-08 : « il
// faut qu on puisse drag and drop les activites deja placees ») : les cases
// colorees SONT le groupe a l ecran, c est elles qu on attrape. Les glisser
// deplace le groupe, les toucher ouvre sa fiche ; une case vide garde son
// geste (reserver a cette heure).
function lpCaseDuGroupe(ev) {
  const c = ev && ev.target && ev.target.closest ? ev.target.closest('[data-lp-id]') : null;
  return c ? { id: Number(c.dataset.lpId), unitKey: c.dataset.lpUnit } : null;
}
function lpSourisJauge(ev) {
  const c = lpCaseDuGroupe(ev);
  if (c) lpSouris(ev, c.id, c.unitKey);
}
function lpDoigtJauge(ev) {
  const c = lpCaseDuGroupe(ev);
  if (c) lpDoigt(ev, c.id, c.unitKey);
}

async function lpToucherDepart(t, ev) {
  if (ev) { ev.preventDefault(); ev.stopPropagation(); }
  // Le clic que le navigateur envoie apres un glisser lache ici n est pas un
  // second geste : le depot l a deja traite.
  if (Date.now() < lpEtat.ignorerClicJusqua) return;
  const c = lpCaseDuGroupe(ev);
  if (c && !lpEtat.choisi && !lpEtat.enCours) { openPos(c.id); return; }
  await lpViser(t);
}

async function lpViser(t) {
  if (lpEtat.enCours) return;
  const modele = lpModele();
  const d = modele.departs.find(x => Math.abs(x.t - Number(t)) < 0.001);
  if (!d) return;
  const choisi = lpChoisiValide(modele);
  if (!choisi) {
    if (modele.config.closed || d.ferme || d.hors || d.joue) return;
    if (d.places <= 0) { toast(`${lpHeure(d.t)} : complet.`); return; }
    lpReserver(d.t, d.places);
    return;
  }
  const verdict = lpVerdict(modele, choisi, d);
  if (!verdict.ok) {
    lpEtat.raison = verdict.raison;
    renderLaserPlanning();
    return;
  }
  await lpPoser(choisi, d.t);
}

async function lpPoser(choisi, t) {
  lpEtat.enCours = { id: choisi.id, unitKey: choisi.unitKey, t };
  lpEtat.raison = '';
  renderLaserPlanning();
  let resultat;
  try {
    resultat = await scheduleLaserPass(choisi.id, choisi.unitKey, t);
  } finally {
    lpEtat.enCours = null;
    if (resultat === true) { lpEtat.choisi = null; lpEtat.raison = ''; }
    else lpEtat.raison = `${lpHeure(t)} : ce départ n’a pas été pris, le message dit pourquoi. Rien n’a bougé.`;
    renderLaserPlanning();
  }
}

async function lpRetirer(ev) {
  if (ev) { ev.preventDefault(); ev.stopPropagation(); }
  const c = lpEtat.choisi;
  if (!c || lpEtat.enCours) return;
  lpEtat.enCours = { id: c.id, unitKey: c.unitKey, t: -1 };
  let ok = false;
  try { ok = await unscheduleLaserPass(c.id, c.unitKey); }
  finally {
    lpEtat.enCours = null;
    if (ok) { lpEtat.choisi = null; lpEtat.raison = ''; }
    renderLaserPlanning();
  }
}

function lpIlsSontLa(id, ev) {
  if (ev) ev.stopPropagation();
  setReservationStatusDirect(id, 'arrived', ev);
}

function lpDecaler(id, minutes, ev) {
  if (ev) ev.stopPropagation();
  openDelayImpact(id, minutes, ev);
}

function lpPasVenus(id, ev) {
  if (ev) ev.stopPropagation();
  basculerAbsence(id, true, ev);
}

// Le glisser : a la souris des 5 px, au doigt apres un appui de 280 ms
// (assets/pinlane-touch-drag.js). Prendre et poser en un seul geste.
function lpSouris(ev, id, unitKey) {
  if (ev.button !== 0 || lpEtat.enCours) return;
  ev.stopPropagation();
  lpEtat.geste = { id: Number(id), unitKey: String(unitKey), source: ev.currentTarget, x0: ev.clientX, y0: ev.clientY, x: ev.clientX, y: ev.clientY, glisse: false, doigt: false };
  document.addEventListener('mousemove', lpSourisBouge, true);
  document.addEventListener('mouseup', lpSourisLache, true);
}

function lpSourisBouge(ev) {
  const g = lpEtat.geste;
  if (!g || g.doigt) return;
  g.x = ev.clientX;
  g.y = ev.clientY;
  if (!g.glisse) {
    if (Math.hypot(g.x - g.x0, g.y - g.y0) < 5) return;
    lpLever(g);
  }
  ev.preventDefault();
  lpSuivre();
}

function lpSourisLache(ev) {
  document.removeEventListener('mousemove', lpSourisBouge, true);
  document.removeEventListener('mouseup', lpSourisLache, true);
  const g = lpEtat.geste;
  if (!g || g.doigt) return;
  lpEtat.geste = null;
  if (!g.glisse) return;
  ev.preventDefault();
  ev.stopPropagation();
  lpEtat.ignorerClicJusqua = Date.now() + 350;
  lpDeposer(g, ev.clientX, ev.clientY);
}

function lpDoigt(ev, id, unitKey) {
  if (!window.PinlaneTouchDrag || lpEtat.enCours) return;
  const source = ev.currentTarget;
  window.PinlaneTouchDrag.demarrer(ev, {
    lever(p) {
      lpEtat.geste = { id: Number(id), unitKey: String(unitKey), source, x0: p.clientX, y0: p.clientY, x: p.clientX, y: p.clientY, glisse: false, doigt: true };
      lpLever(lpEtat.geste);
    },
    bouger(p) {
      const g = lpEtat.geste;
      if (!g) return;
      g.x = p.clientX;
      g.y = p.clientY;
      lpSuivre();
    },
    deposer(p) {
      const g = lpEtat.geste;
      lpEtat.geste = null;
      if (!g) return;
      lpEtat.ignorerClicJusqua = Date.now() + 350;
      lpDeposer(g, p.clientX, p.clientY);
    },
    annuler(etaitLeve) {
      const g = lpEtat.geste;
      lpEtat.geste = null;
      if (g && etaitLeve) lpFinGlisse(g);
    },
  }, { maintienMs: 280 });
}

function lpLever(g) {
  g.glisse = true;
  lpEtat.choisi = { id: g.id, unitKey: g.unitKey, date: state.currentDate, centre: getCurrentStaffCenterId() };
  lpEtat.raison = '';
  renderLaserPlanning();
  lpEtat.glisse = g;
  const modele = lpModele();
  const choisi = lpChoisiValide(modele);
  g.verdicts = new Map(choisi ? modele.departs.map(d => [Math.round(d.t * 60), lpVerdict(modele, choisi, d)]) : []);
  g.placee = Boolean(choisi && choisi.placee);
  const nom = state.reservations.find(r => Number(r.id) === g.id)?.name || 'Groupe';
  const fantome = document.createElement('div');
  fantome.className = 'lp-fantome';
  const source = document.querySelector(`#laserPlanningGridWrap [data-laser-res-id="${g.id}"][data-laser-unit="${g.unitKey}"]`) || g.source;
  const k = [...(source?.classList || [])].find(c => /^st-/.test(c)) || 'st-conf';
  fantome.classList.add(k);
  fantome.innerHTML = `<i aria-hidden="true"></i><b>${escapeHtml(nom)}</b> <small class="lp-fantome__vers">Choisissez un départ</small>`;
  document.body.appendChild(fantome);
  g.fantome = fantome;
  g.fl = fantome.offsetWidth;
  g.fh = fantome.offsetHeight;
  document.body.classList.add('lp-glisse');
  lpSuivre();
  lpDefilerDemarrer();
}

// La cible sous le pointeur : un depart, ou la file (retirer du planning).
function lpCibleSous(x, y) {
  const el = document.elementFromPoint(x, y);
  if (!el) return null;
  const file = el.closest('#laserPlanningGridWrap .lp-file');
  if (file) return { file };
  const rang = el.closest('#laserPlanningGridWrap .lp-dep, #laserPlanningGridWrap .lp-prochain[data-lp-t]');
  return rang ? { rang, t: Number(rang.dataset.lpT) } : null;
}

function lpSuivre() {
  const g = lpEtat.glisse;
  if (!g || !g.fantome) return;
  const haut = g.doigt ? Math.max(4, g.y - g.fh - 24) : g.y + 14;
  const gauche = g.doigt ? g.x - g.fl / 2 : g.x + 14;
  g.fantome.style.transform = `translate3d(${Math.round(gauche)}px, ${Math.round(haut)}px, 0)`;
  const cible = lpCibleSous(g.x, g.y);
  document.querySelectorAll('#laserPlanningGridWrap .is-survol').forEach(el => el.classList.remove('is-survol'));
  const vers = g.fantome.querySelector('.lp-fantome__vers');
  g.fantome.classList.remove('is-ok', 'is-non');
  if (cible && cible.rang) {
    cible.rang.classList.add('is-survol');
    // Le verdict de chaque depart est calcule une fois, au lever : le planning
    // ne se repeint pas pendant le glisser, ses donnees non plus.
    const verdict = g.verdicts ? g.verdicts.get(Math.round(cible.t * 60)) : null;
    g.fantome.classList.add(verdict && verdict.ok ? 'is-ok' : 'is-non');
    if (vers) vers.textContent = verdict ? (verdict.ok ? `Vers ${lpHeure(cible.t)} · ${verdict.apres} après` : verdict.raison) : 'Choisissez un départ';
  } else if (cible && cible.file) {
    cible.file.classList.add('is-survol');
    g.fantome.classList.add(g.placee ? 'is-ok' : 'is-non');
    if (vers) vers.textContent = g.placee ? 'Lâcher : retirer du planning' : 'Elle attend déjà ici';
  } else if (vers) {
    vers.textContent = 'Choisissez un départ';
  }
}

function lpFinGlisse(g) {
  lpDefilerArreter();
  document.body.classList.remove('lp-glisse');
  if (g && g.fantome) g.fantome.remove();
  document.querySelectorAll('#laserPlanningGridWrap .is-survol').forEach(el => el.classList.remove('is-survol'));
  lpEtat.glisse = null;
  if (lpEtat.differe) { lpEtat.differe = false; }
  renderLaserPlanning();
}

async function lpDeposer(g, x, y) {
  const cible = lpCibleSous(x, y);
  lpFinGlisse(g);
  if (!cible) return;
  const modele = lpModele();
  const choisi = lpChoisiValide(modele);
  if (cible.file) {
    if (choisi && choisi.placee) await lpRetirer();
    return;
  }
  // Lache sur son propre depart. Au doigt, c est l appui long sans bouger :
  // le groupe reste pris, le bandeau dit de toucher un depart. A la souris,
  // c est un glisser rendu : il ne s est rien passe. Jamais une erreur.
  const d = modele.departs.find(x2 => Math.abs(x2.t - cible.t) < 0.001);
  if (choisi && d && lpVerdict(modele, choisi, d).ici) {
    if (!g.doigt) lpEtat.choisi = null;
    lpEtat.raison = '';
    renderLaserPlanning();
    return;
  }
  await lpViser(cible.t);
}

// LE DEFILEMENT DU BORD : la page (ou le planning en plein ecran) defile
// pres du haut et du bas de ce qu on voit, plus vite pres du bord, au temps
// reel (pas a la frequence de l ecran), aussi loin qu il faut : un groupe de
// 15:00 se depose a 21:00 sans lacher. La file en bas n est pas une zone de
// defilement : elle reste la cible « retirer du planning ».
function lpDefileur() {
  let el = document.getElementById('laserPlanningGridWrap');
  while (el && el !== document.body) {
    const style = getComputedStyle(el);
    if (/(auto|scroll)/.test(style.overflowY) && el.scrollHeight > el.clientHeight + 1) return el;
    el = el.parentElement;
  }
  return document.scrollingElement || document.documentElement;
}

function lpDefilerDemarrer() {
  if (lpEtat.defile) return;
  const wrap = document.getElementById('laserPlanningGridWrap');
  const rows = wrap ? [...wrap.querySelectorAll('.lp-compact .lp-dep')] : [];
  // Une journee qui tient deja ne bouge pas sous le pointeur. Le grand bord
  // de defilement reste utile sur mobile et dans une grille qui deborde.
  if (window.innerWidth > 900 && rows.length && wrap.scrollHeight <= wrap.clientHeight + 1
    && rows.every(row => { const rect = row.getBoundingClientRect(); return rect.top >= 0 && rect.bottom <= window.innerHeight; })) return;
  const etat = { avant: 0, raf: 0 };
  lpEtat.defile = etat;
  const pas = (instant) => {
    if (lpEtat.defile !== etat || !lpEtat.glisse) return;
    const dt = etat.avant ? Math.min(64, instant - etat.avant) : 16;
    etat.avant = instant;
    const g = lpEtat.glisse;
    const defileur = lpDefileur();
    if (defileur.scrollHeight <= defileur.clientHeight + 1) {
      etat.raf = requestAnimationFrame(pas);
      return;
    }
    const page = defileur === document.scrollingElement || defileur === document.documentElement;
    const cadre = page ? { top: 0, bottom: window.innerHeight } : defileur.getBoundingClientRect();
    const file = document.querySelector('#laserPlanningGridWrap .lp-file');
    const basFile = file ? file.getBoundingClientRect().top : Infinity;
    const haut = Math.max(0, cadre.top);
    const bas = Math.min(window.innerHeight, cadre.bottom, basFile);
    const bord = 96;
    let vitesse = 0;
    if (g.y < haut + bord && g.y >= haut - 40) vitesse = -Math.pow(Math.min(1, (haut + bord - g.y) / bord), 1.6) * 1400;
    else if (g.y > bas - bord && g.y <= bas + 4) vitesse = Math.pow(Math.min(1, (g.y - (bas - bord)) / bord), 1.6) * 1400;
    if (vitesse) {
      const avantPos = defileur.scrollTop;
      defileur.scrollTop = avantPos + vitesse * dt / 1000;
      if (defileur.scrollTop !== avantPos) lpSuivre();
    }
    etat.raf = requestAnimationFrame(pas);
  };
  etat.raf = requestAnimationFrame(pas);
}

function lpDefilerArreter() {
  const etat = lpEtat.defile;
  lpEtat.defile = null;
  if (etat && etat.raf) cancelAnimationFrame(etat.raf);
}

document.addEventListener('keydown', ev => {
  if (ev.key === 'Escape' && lpEtat.choisi && !lpEtat.enCours && !document.querySelector('.qb-overlay.open, #posOverlay.open')) {
    ev.preventDefault();
    lpAnnuler();
  }
});

// Maintenance datée : fenêtre [du, au], la piste reste réservable hors
// fenêtre et se libère automatiquement après (résolution par date côté
// serveur, y compris dans le chemin d'écriture des réservations).
// L ENTRETIEN SE PLANIFIE DANS LA RANGEE (2026-08-25, Movsar devant le
// prompt() navigateur : « pas possible de faire un truc comme ca »). Un
// petit formulaire produit (du/au + motif) s ouvre sous le statut de la
// piste ; Planifier envoie le meme PATCH staff-lanes qu avant. Les champs
// type=date garantissent le format, le serveur revalide de toute facon.
let laneMaintFormLane = null;

function openLaneMaintForm(lane, ev) {
  if (ev) ev.stopPropagation();
  laneMaintFormLane = laneMaintFormLane === Number(lane) ? null : Number(lane);
  renderStaffUtilityPage();
}

function closeLaneMaintForm() {
  laneMaintFormLane = null;
  renderStaffUtilityPage();
}

function renderLaneMaintForm(lane) {
  const today = todayStr();
  return `<div class="lane-maint-form" data-role="lane-maint-form">
    <div class="lane-maint-fields">
      <label>Du <input type="date" id="laneMaintFrom-${lane}" value="${today}"></label>
      <label>au <input type="date" id="laneMaintUntil-${lane}" value=""></label>
      <input type="text" id="laneMaintNote-${lane}" maxlength="120" placeholder="Motif visible par l’équipe : huilage, pin-setter…">
    </div>
    <div class="lane-maint-actions">
      <button type="button" class="is-primary" onclick="submitLaneMaintForm(${lane})">Planifier</button>
      <button type="button" onclick="closeLaneMaintForm()">Annuler</button>
      <small>Sans fin : jusqu’à réouverture manuelle. Début vidé : dès maintenant.</small>
    </div>
  </div>`;
}

async function submitLaneMaintForm(lane) {
  const from = (document.getElementById(`laneMaintFrom-${lane}`)?.value || '').trim();
  const until = (document.getElementById(`laneMaintUntil-${lane}`)?.value || '').trim();
  const note = (document.getElementById(`laneMaintNote-${lane}`)?.value || '').trim();
  if (from && until && until < from) { toast('La fin précède le début.'); return; }
  const today = todayStr();
  try {
    const payload = await apiRequest(API_ENDPOINTS.staffLanes, {
      method: 'PATCH',
      body: JSON.stringify({ lane, status: 'maintenance', maintenanceFrom: from || '', maintenanceUntil: until || '', note }),
    });
    const laneInfo = payload.lane || {};
    state.laneMaintenance = state.laneMaintenance || {};
    state.laneMaintenance[lane] = { from: laneInfo.maintenanceFrom || '', until: laneInfo.maintenanceUntil || '', note: laneInfo.maintenanceNote || '' };
    const applies = (!laneInfo.maintenanceFrom || today >= laneInfo.maintenanceFrom) && (!laneInfo.maintenanceUntil || today <= laneInfo.maintenanceUntil);
    state.laneStatuses[lane] = applies ? 'maintenance' : 'active';
    laneMaintFormLane = null;
    save();
    renderStaff();
    if (isStaffUtilityActive()) renderStaffUtilityPage();
    toast(`Piste ${lane} : maintenance ${laneInfo.maintenanceFrom || 'immédiate'} → ${laneInfo.maintenanceUntil || 'sans fin'}${applies ? '' : ' (programmée)'}`);
  } catch (error) {
    toast(error.message || 'Impossible de programmer la maintenance.');
  }
}
async function toggleMaint(i, ev) {
  if (ev) ev.stopPropagation();
  const previousStatus = state.laneStatuses[i];
  const nextStatus = state.laneStatuses[i] === 'maintenance' ? 'active' : 'maintenance';
  state.laneStatuses[i] = nextStatus;
  save();
  renderPlanning();
  // La bascule se fait depuis la page Pistes aussi : elle doit SE VOIR la
  // ou le doigt est (2026-08-25, atrape par lanes-laser-pages-check).
  if (isStaffUtilityActive()) renderStaffUtilityPage();
  try {
    const payload = await apiRequest(API_ENDPOINTS.staffLanes, {
      method: 'PATCH',
      body: JSON.stringify({ lane: i, status: nextStatus })
    });
    const confirmedStatus = payload.lane?.status || nextStatus;
    const changedOnConfirm = state.laneStatuses[i] !== confirmedStatus;
    state.laneStatuses[i] = confirmedStatus;
    if (state.laneMaintenance) {
      if (confirmedStatus === 'maintenance') state.laneMaintenance[i] = { from: payload.lane?.maintenanceFrom || '', until: payload.lane?.maintenanceUntil || '', note: payload.lane?.maintenanceNote || '' };
      else delete state.laneMaintenance[i];
    }
    save();
    if (changedOnConfirm) renderPlanning();
    toast(`Piste ${i} ${state.laneStatuses[i] === 'maintenance' ? 'en maintenance' : 'active'}`);
  } catch (error) {
    state.laneStatuses[i] = previousStatus;
    save();
    renderPlanning();
    if (isStaffUtilityActive()) renderStaffUtilityPage();
    toast(error.message || 'Impossible de mettre la piste à jour.');
  }
}

// La puce « Avec note » n'apparaît que s'il y a des notes. Sans ce relâchement,
// un changement de date laisserait le filtre actif sur une puce disparue de
// l'écran : le planning et la liste sembleraient vides sans raison visible.
// Le verdict porte sur LA JOURNÉE ENTIÈRE, jamais sur la ressource affichée :
// bowling, laser et table sont peints dans le même tick, et un scope laser vide
// relâcherait le filtre que le staff vient de poser depuis la table bowling.
function releaseDeadNoteFilter() {
  if (state.staffStatusFilter === 'notes' && !todaysReservations().some(hasReservationNote)) {
    state.staffStatusFilter = 'all';
  }
}

// UN DOSSIER « A VENIR », C EST DEUX CLES DE STATUT. La base ne connait que
// pending / arrived / paid / cancelled (lib/database.js) : 'pending' y est une
// reservation confirmee, pas encore arrivee. Les donnees de simulation
// (lib/ops-simulation.js) ecrivent aussi 'confirmed'. Les deux disent « le
// groupe n est pas encore arrive » : trier sur la seule cle 'pending' comptait
// les dossiers 'confirmed' dans « Tout » sans les rendre dans aucune section.
// Une seule definition, partagee par tout ce qui trie ou allume l etat.
function isUpcomingReservationStatus(status) {
  return status === 'pending' || status === 'confirmed';
}

// LA LECTURE ET L ECRITURE PARTAGENT LA MEME DEFINITION D ETAT. Le bouton
// « Confirme » s allume pour 'pending' comme pour 'confirmed' (une seule idee :
// le groupe n est pas encore arrive), mais son clic ecrivait toujours
// 'pending' : sur un dossier deja 'confirmed', un bouton DEJA enfonce changeait
// la donnee sans que rien ne bouge a l ecran. On ne reecrit pas une donnee qui
// dit deja la bonne chose : on rend l ECRITURE idempotente. Un bouton deja
// enfonce n ecrit rien.
function reservationAlreadyInStatus(reservation, status) {
  const courant = reservation && reservation.status;
  if (isUpcomingReservationStatus(status)) return isUpcomingReservationStatus(courant);
  return courant === status;
}

// UNE DEMANDE A VERIFIER NE SE DIT PAS « CONFIRMÉ » (audit du 2026-09-28 : une
// Formule 4 lisait « demande envoyée, vérifiée sous 24 h » cote client et
// « Confirmé » dans la liste comme dans la fiche). La base la garde `pending` ;
// l attente vit dans validationStatus, que le Terrain lisait deja. Une seule
// definition pour la liste, la fiche, le tableau de bord et les pages v2.
// POURQUOI L EQUIPE EST APPELEE, ET CE QUI EST A SURVEILLER (2026-10-05) :
// la decision que le serveur a posee dans le plan (lib/reservation-ops), dite
// avec les memes mots que l ecran Etablissement et le mail.
function getReservationValidationTexte(reservation) {
  const v = reservation && reservation.opsPlan && reservation.opsPlan.validation;
  // La phrase ecrite par le moteur ; un ancien dossier sans phrase garde le mot.
  const phrase = (liste) => (Array.isArray(liste) ? liste : []).map(d => d.phrase || (d.detail ? `${d.mot}, ${d.detail}.` : `${d.mot}.`)).join(' ');
  if (!v || typeof v !== 'object') return { raison: '', surveiller: '' };
  const declencheurs = phrase(v.declencheurs);
  return {
    raison: declencheurs || (v.raison ? 'Cette formule est réglée pour toujours passer par l’équipe.' : ''),
    surveiller: phrase(v.aSurveiller),
  };
}

function isReservationAwaitingReview(reservation) {
  return Boolean(reservation)
    && reservation.validationStatus === 'staff_review'
    && isUpcomingReservationStatus(reservation.status);
}

// Le premier bouton du selecteur d etat. Tant que la demande attend, il porte
// l action qui leve le doute, « Valider » ; ensuite, « Confirmé » comme avant.
// `suivant` : ce bouton est le geste que la fiche attend (ficheGesteSuivant).
function renderReservationFirstStatusButton(r, { fiche = false, suivant = false } = {}) {
  const marque = suivant ? ' is-suivant' : '';
  if (isReservationAwaitingReview(r)) {
    return `<button type="button" class="res-status-btn${marque} review active review" aria-pressed="false" title="Cette demande attend votre validation : Valider la confirme" onclick="validateReservationDirect(${r.id}, event)">Valider</button>`;
  }
  const actif = isUpcomingReservationStatus(r.status);
  return fiche
    ? `<button type="button" class="res-status-btn${marque} pending ${actif ? 'active pending' : ''}" aria-pressed="${actif}" onclick="setReservationStatusDirect(${r.id}, 'pending')">Confirmé</button>`
    : `<button class="res-status-btn ${actif ? 'active pending' : ''}" onclick="setReservationStatusDirect(${r.id}, 'pending', event)">Confirmé</button>`;
}

// LE MOMENT D UN DOSSIER, LE MEME SUR TOUTES LES PAGES (2026-09-30). La liste
// du planning rangeait par STATUT sous les mots du Terrain : « Sur place »
// voulait dire « pointe arrive », meme fini depuis une heure, et le groupe en
// retard restait « À venir » sans le dire, pendant que le Terrain et l accueil
// disaient « À clôturer » et « En retard ». Liste, puces, compteurs et filtre
// du planning lisent maintenant le meme partage (getStaffTerrainBoard,
// splitStaffTerrainOnsite) :
//   upcoming : pas commence et pas pointe ; le retard en fait partie, marque ;
//   onsite   : pointe arrive, ou paye, pendant sa fenetre ;
//   closing  : fini, pas paye ;
//   done     : fini et paye ;
//   absent   : note « Pas venu » dans la fiche (0056), sorti du travail.
//
// LA LISTE, SES PUCES ET LE FILTRE DES PLANNINGS RANGENT PAR SECTION
// (2026-10-08). Les puces comptaient les moments pendant que la liste montrait
// ses sections : « À venir 7 » au-dessus de « En retard 2 » et « À venir 5 »,
// « Sur place » qui comptait les payes ranges plus bas dans « Payées ». Une
// puce = une section, avec le meme nombre ; elles sont exclusives et se
// totalisent (la regle du 2026-08-14 tient). « À gérer » (tout sauf les
// payes) part : « Tout » le montre deja, les payes replies en bas.
const STAFF_LISTE_SECTIONS = ['late', 'upcoming', 'onsite', 'closing', 'paid', 'absent'];
const STAFF_LISTE_MOTS = { late: 'En retard', upcoming: 'À venir', onsite: 'Sur place', closing: 'À clôturer', paid: 'Terminées', absent: 'Pas venus' };

function getStaffReservationMoments(reservations, jour = state.currentDate) {
  const board = getStaffTerrainBoard(reservations, jour);
  const partage = splitStaffTerrainOnsite(board);
  const moments = new Map();
  const poser = (items, etat, late = false) => items.forEach(item => {
    moments.set(String(item.reservation.id), { etat, late, item, now: board.now });
  });
  poser(board.upcoming, 'upcoming');
  poser(partage.late, 'upcoming', true);
  poser(partage.due, 'upcoming');
  poser(partage.present, 'onsite');
  poser(board.closing, 'closing');
  poser(board.done, 'done');
  poser(board.absent, 'absent');
  // Encaisser ne termine aucune activité. Seules les coches du programme
  // permettent de ranger un dossier payé parmi les visites terminées.
  reservations.forEach(r => {
    const moment = moments.get(String(r.id));
    if (r.status === 'paid' && moment && moment.etat !== 'absent') {
      moment.etat = groupeToutFait(r) ? 'done' : 'onsite';
      moment.late = false;
    }
  });
  return moments;
}

function getStaffReservationMomentState(moments, reservation) {
  const entry = moments.get(String(reservation.id));
  return entry ? entry.etat : 'upcoming';
}

// La section suit la visite : un paiement ne termine pas le programme.
// Le paiement ET les activités faites autorisent seuls le rangement en bas.
function getStaffListeSection(moments, r) {
  const m = moments.get(String(r.id));
  const etat = m ? m.etat : 'upcoming';
  if (etat === 'absent') return 'absent';
  if (etat === 'done') return 'paid';
  if (etat === 'upcoming' && m && m.late) return 'late';
  return etat;
}

// Un filtre garde par un poste d avant le 2026-10-08 (« open », « done »)
// retrouve sa section, ou « Tout ».
function normaliserFiltreListe(filter) {
  if (filter === 'done') return 'paid';
  return filter === 'notes' || STAFF_LISTE_SECTIONS.includes(filter) ? filter : 'all';
}

function filterReservationsForStaff(reservations, filter) {
  const cle = normaliserFiltreListe(filter);
  if (cle === 'notes') return reservations.filter(hasReservationNote);
  if (cle === 'all') return reservations;
  const moments = getStaffReservationMoments(reservations);
  return reservations.filter(r => getStaffListeSection(moments, r) === cle);
}

function getStaffStatusCounts(reservations) {
  const moments = getStaffReservationMoments(reservations);
  const counts = { all: reservations.length, notes: reservations.filter(hasReservationNote).length };
  STAFF_LISTE_SECTIONS.forEach(cle => { counts[cle] = 0; });
  reservations.forEach(r => { counts[getStaffListeSection(moments, r)] += 1; });
  return counts;
}

// LES JOUEURS D UN DOSSIER, ET CEUX QUI LES ACCOMPAGNENT (migration 0048) :
// un Kids Fun Day de 6 enfants venus avec 2 adultes se lit « 6 joueurs +
// 2 accompagnants ». Les adultes ne jouent pas et ne paient pas l offre.
function dossierAvecEffectifsDistincts(r) {
  const items = Array.isArray(r && r.program) ? r.program : r && r.program && r.program.items;
  return Array.isArray(items) && items.some(item => Number(item.participants) > 0 && Number(item.participants) !== Number(r.pax));
}

function joueursDuDossier(r) {
  const pax = Math.max(0, Number(r && r.pax) || 0);
  const avec = Math.max(0, Math.trunc(Number(r && r.companions) || 0));
  const effectif = dossierAvecEffectifsDistincts(r) ? `${pax} personne${pax > 1 ? 's' : ''} présente${pax > 1 ? 's' : ''}` : `${pax} joueur${pax > 1 ? 's' : ''}`;
  return `${effectif}${avec ? ` + ${avec} accompagnant${avec > 1 ? 's' : ''}` : ''}`;
}

// LA CARTE D UN GROUPE, A LA CAISSE (Movsar, 2026-10-01, captures de la liste
// « Toutes les réservations » et de la fiche) : « c est le truc qui sera
// affiche a cote de la caisse », « on doit avoir toutes les infos direct
// visibles instant », « les infos utiles sont en tout petit », « le truc en
// retard doit etre visible d office », « tout simplifie a mort ». Decisions
// prises avec lui le meme jour :
//   - une carte par groupe, rangee par moment, le RETARD en tete, en rouge ;
//   - la carte dit le prix, les activites dans l ordre avec leur heure, et
//     une aide par activite (« À lancer maintenant », « En cours · fin
//     15:30 », « Dans 20 min », « Fini ») ; le prix par personne et le detail
//     par activite vivent dans la fiche ;
//   - un ENCADRE pour ce qui change la facon de servir : a valider, prix
//     ajuste, anniversaire ou formule, note du client ;
//   - Payé demande Carte ou Espèces.
// La ligne d avant (colonnes Heure, Client, Réservation, Ressources, État)
// disait les pistes en pastilles sans dire lesquelles servaient a quoi, et
// rangeait le prix et le retard en pastilles de 11 px au milieu du texte.

// LE PROGRAMME D UN GROUPE, DANS L ORDRE OU IL LE VIT. Les heures viennent des
// blocs que le planning dessine (getStaffResourceWindows : le bowling et le
// laser deplaces a la main y sont), celles des autres activites d une formule
// du plan du moteur (getStaffFormulaTimedItems), et les activites libres d une
// visite (minigolf, arcades, billard) n ont pas d heure : elles se font a la
// guise du groupe. Une partie de laser sans heure au planning est « à placer ».
function getGroupeProgramme(r) {
  const etapes = [];
  const effectifActivite = id => participantsLigneProgramme(((r.program && r.program.items) || []).find(item => item.activityId === id), r.pax);
  const progression = r && r.activityProgress && typeof r.activityProgress === 'object' ? r.activityProgress : {};
  const faite = (cle) => Boolean(progression[cle] && progression[cle].done);
  const fenetres = getStaffResourceWindows(r, 'all');
  const bowling = fenetres.filter(f => f.resourceType === 'bowling_lane');
  const laser = fenetres.filter(f => f.resourceType === 'laser_arena');
  const parties = Math.max(1, getLaserGameCountForReservation(r) || 1);
  // Une formule se suit en cochant ses activites (activityProgress) : chaque
  // etape porte la cle de sa coche, la meme que le suivi de la page Formules.
  const formuleSuivie = typeof reservationHasFormulaActivities === 'function' && reservationHasFormulaActivities(r);
  bowling.forEach((f, index) => {
    const pistes = (f.lanes || []).filter(Number.isFinite);
    etapes.push({
      cle: `bowling-${index + 1}`,
      activityId: 'bowling',
      nom: 'Bowling',
      quoi: `${Number(f.players) || effectifActivite('bowling')} joueurs · ${formatDurationLabel(f.duration)}${bowlingCapacityMessage(f.bowlingCapacity) ? ' · ' + bowlingCapacityMessage(f.bowlingCapacity) : ''}`,
      ou: pistes.length ? `piste${pistes.length > 1 ? 's' : ''} ${joindrePistes(pistes)}` : 'pistes à attribuer',
      groupe: bowling.length > 1 ? `groupe ${index + 1}/${bowling.length}${f.players ? ` · ${f.players} joueurs` : ''}` : '',
      start: f.start,
      end: f.end,
      fait: faite(bowling.length === 1 ? 'bowling-1' : `bowling-g${index + 1}`),
      coche: bowling.length === 1 ? 'bowling-1' : `bowling-g${index + 1}`,
      exige: formuleSuivie && bowling.length === 1,
    });
  });
  laser.forEach(f => {
    const partie = Math.max(1, Number(f.countIndex) || 1);
    const vagues = Math.max(1, Number(f.groupWaveCount) || 1);
    etapes.push({
      cle: `laser-${partie}-${Number(f.groupWaveIndex) || 1}`,
      activityId: 'laser_game',
      nom: 'Laser Game',
      quoi: `${Number(f.joueursReels ?? f.players) || effectifActivite('laser_game')} joueurs · ${parties > 1 ? `partie ${partie}/${parties}` : '1 partie'}`,
      ou: '',
      groupe: vagues > 1 ? `groupe ${Number(f.groupWaveIndex) || 1}/${vagues}${f.players ? ` · ${Number(f.joueursReels ?? f.players)} joueurs` : ''}` : '',
      start: f.start,
      end: f.end,
      fait: faite(vagues === 1 ? `laser_game-${partie}` : `laser_game-${partie}-g${Number(f.groupWaveIndex) || 1}`),
      coche: vagues === 1 ? `laser_game-${partie}` : `laser_game-${partie}-g${Number(f.groupWaveIndex) || 1}`,
      exige: formuleSuivie && vagues === 1,
    });
  });
  getStaffFormulaTimedItems(r)
    .filter(item => item.activityId !== 'bowling' && item.activityId !== 'laser_game')
    .forEach(item => etapes.push({
      cle: item.key,
      activityId: item.activityId,
      nom: item.label,
      quoi: '',
      ou: '',
      groupe: '',
      start: item.start,
      end: item.end,
      fait: Boolean(item.done),
      coche: item.key,
      exige: true,
    }));
  // Une activite de formule sans heure au plan reste au programme, cochable.
  if (formuleSuivie) {
    getFormulaActivityProgressSummary(r).items
      .filter(item => !item.startTime && item.activityId !== 'bowling' && item.activityId !== 'laser_game')
      .forEach(item => etapes.push({
        cle: item.key, activityId: item.activityId, nom: item.label, quoi: '', ou: '', groupe: '',
        start: null, end: null, libre: true, fait: Boolean(item.done), coche: item.key, exige: true,
      }));
  }
  [...new Set(getPendingLaserPassesForReservation(r).map(unit => Number(unit.countIndex) || 1))]
    .sort((a, b) => a - b)
    .forEach(partie => etapes.push({
      cle: `laser-a-placer-${partie}`,
      activityId: 'laser_game',
      nom: 'Laser Game',
      quoi: `${effectifActivite('laser_game')} joueurs · ${parties > 1 ? `partie ${partie}/${parties}` : '1 partie'}`,
      ou: '',
      groupe: '',
      start: null,
      end: null,
      aPlacer: true,
      fait: faite(`laser_game-${partie}`),
      coche: `laser_game-${partie}`,
    }));
  const items = r && r.program && Array.isArray(r.program.items) ? r.program.items : [];
  items.filter(item => !item.planned && !item.waitOffer).forEach((item, index) => etapes.push({
    cle: `libre-${index}`,
    activityId: item.activityId,
    nom: nomActivite(item),
    quoi: detailLigneProgramme(item, r),
    ou: '',
    groupe: '',
    start: null,
    end: null,
    libre: true,
    fait: faite(`libre-${item.activityId}`),
    coche: `libre-${item.activityId}`,
  }));
  const rang = e => (e.start !== null && e.start !== undefined ? 0 : e.aPlacer ? 1 : 2);
  return etapes.sort((a, b) => rang(a) - rang(b) || (a.start || 0) - (b.start || 0) || (a.end || 0) - (b.end || 0));
}

// « 1, 2 », « 1 à 4 » : des pistes qui se suivent se lisent en plage.
function joindrePistes(pistes) {
  const liste = [...new Set(pistes.map(Number))].sort((a, b) => a - b);
  const suivies = liste.length > 2 && liste.every((p, i) => i === 0 || p === liste[i - 1] + 1);
  return suivies ? `${liste[0]} à ${liste[liste.length - 1]}` : liste.join(', ');
}

// L AIDE D UNE ACTIVITE, LUE A L HEURE, LE JOUR MEME SEULEMENT (une autre date
// n a pas de « maintenant »). Cinq minutes de part et d autre du depart, c est
// « À lancer » : l equipe lance la piste ou la partie. Tant que le groupe n est
// pas pointe arrive, une activite dont l heure est la ne dit pas « en cours »
// (il n est pas la) mais « Groupe pas arrivé ».
const GROUPE_FENETRE_LANCEMENT_H = 5 / 60;
function getGroupeEtapePhase(etape, contexte) {
  if (etape.fait) return { cle: 'fait', mot: 'Fait' };
  if (etape.libre) return { cle: 'libre', mot: 'À leur rythme' };
  if (etape.aPlacer) return { cle: 'aplacer', mot: 'Heure à placer' };
  if (!contexte.aujourdhui) return { cle: 'prevu', mot: '' };
  const now = contexte.now;
  // Une activite de formule passee sans coche n est pas « finie » : personne
  // n a dit qu elle a eu lieu (meme mot que la page Formules).
  if (now >= etape.end) return etape.exige ? { cle: 'noncoche', mot: 'Non coché' } : { cle: 'fini', mot: 'Fini' };
  // Le groupe n est pas pointe : son heure est la, rien ne se lance. En
  // retard, le bandeau de la carte le dit deja ; avant, « Attendu ».
  if (now >= etape.start - GROUPE_FENETRE_LANCEMENT_H && !contexte.present) return contexte.late ? { cle: 'prevu', mot: '' } : { cle: 'attente', mot: 'Attendu' };
  if (now >= etape.start - GROUPE_FENETRE_LANCEMENT_H && now < etape.start + GROUPE_FENETRE_LANCEMENT_H) {
    return { cle: 'lancer', mot: now < etape.start ? `À lancer à ${formatClockDisplay(etape.start)}` : 'À lancer maintenant' };
  }
  if (now >= etape.start) return { cle: 'encours', mot: `En cours · fin ${formatClockDisplay(etape.end)}` };
  const dans = etape.start - now;
  return dans <= 1 ? { cle: 'bientot', mot: `Dans ${formatStaffTerrainDelay(dans)}` } : { cle: 'prevu', mot: '' };
}

function getGroupeContexte(r, moment) {
  const aujourdhui = (r.date || state.currentDate) === todayStr();
  return {
    aujourdhui,
    now: moment && Number.isFinite(moment.now) ? moment.now : currentTimeDecimal(),
    // Une activite cochee prouve que le groupe est venu, pointe ou pas.
    present: r.status === 'arrived' || r.status === 'paid' || groupeAJoue(r),
    late: Boolean(moment && moment.late),
  };
}

// TOUT EST FAIT : chaque activite du programme cochee. Le groupe a fini, meme
// avant l heure prevue : il passe a « À clôturer » (ou « Terminées » s il a
// paye), comme a la fin de son heure.
function groupeAJoue(r) {
  return Boolean(r) && getGroupeProgramme(r).some(etape => etape.coche && etape.fait);
}
function groupeToutFait(r) {
  if (!r || r.status === 'cancelled') return false;
  const etapes = getGroupeProgramme(r).filter(etape => etape.coche);
  return etapes.length > 0 && etapes.every(etape => etape.fait);
}

// « Tout est fait » : coche d un geste ce qui reste. Une coche a la fois vers
// le serveur (le meme chemin que la case), jamais le suivi entier.
function terminerGroupe(reservationId, ev) {
  if (ev) ev.stopPropagation();
  const r = state.reservations.find(x => String(x.id) === String(reservationId)) || findStaffReservationById(reservationId);
  if (!r) return;
  getGroupeProgramme(r).filter(etape => etape.coche && !etape.fait).forEach(etape => toggleFormulaActivity(reservationId, etape.coche));
}

// En tete du programme de la fiche : « Tout est fait » quand il reste au
// moins deux activites a cocher (une seule : sa case suffit, un bouton de plus
// serait du bruit), le mot seul une fois tout coche.
function renderGroupeTerminer(r) {
  const etapes = getGroupeProgramme(r).filter(etape => etape.coche);
  if (!etapes.length || r.status === 'cancelled') return '';
  const reste = etapes.filter(etape => !etape.fait).length;
  if (!reste) return '<span class="gc-done-all">Tout est fait</span>';
  // Cocher demande le droit de changer un statut (activityToggle, serveur).
  if (reste < 2 || !(typeof canUseStaffPermission !== 'function' || canUseStaffPermission(['reservations.status', 'reservations.edit']))) return '';
  return `<button type="button" class="gc-btn gc-finish" data-pl-focus="fiche.terminer.${Number(r.id)}" onclick="terminerGroupe(${Number(r.id)}, event)">Tout est fait${reste < etapes.length ? ` (${reste} restante${reste > 1 ? 's' : ''})` : ''}</button>`;
}

function renderGroupeEtapes(r, moment, options = {}) {
  const etapes = getGroupeProgramme(r);
  if (!etapes.length) return '';
  const contexte = getGroupeContexte(r, moment);
  const phases = etapes.map(etape => getGroupeEtapePhase(etape, contexte));
  // L etape a regarder : celle qui se lance, qui tourne ou qui vient, la
  // premiere qui n est pas finie. Elle porte le contour.
  const vivantes = ['lancer', 'encours', 'attente', 'bientot', 'prevu'];
  const focus = contexte.aujourdhui ? phases.findIndex(p => vivantes.includes(p.cle)) : -1;
  const prix = options.prix ? getGroupePrixParActivite(r) : null;
  // Une case ne se coche que si le role peut l ecrire (activityToggle :
  // reservations.status ou .edit) ; sinon l etape se lit sans se toucher.
  const peutCocher = typeof canUseStaffPermission !== 'function' || canUseStaffPermission(['reservations.status', 'reservations.edit']);
  // LES ACTIVITES LIBRES, EN UNE LIGNE SUR LA CARTE (2026-10-01, Movsar :
  // « quand y aura une trentaine de reservations ca va etre super galere »).
  // Six activites sans heure prenaient six rangees ; la carte les range en
  // puces sur une ligne, chacune cochable d un toucher. La fiche garde une
  // rangee par activite.
  const enLigne = !options.coches;
  const libres = enLigne ? etapes.filter(etape => etape.libre) : [];
  const ligneLibres = () => {
    const toutFait = libres.every(etape => etape.fait);
    const puces = libres.map(etape => {
      const cochable = Boolean(etape.coche) && r.status !== 'cancelled' && peutCocher;
      const appel = cochable ? `toggleFormulaActivity(${Number(r.id)}, '${escapeHtml(etape.coche)}', event)` : '';
      return `<button type="button" class="gc-libre${etape.fait ? ' is-fait' : ''}" ${cochable ? `onclick="${appel}" aria-pressed="${etape.fait}" aria-label="${escapeHtml(etape.nom)}${etape.quoi ? ` ${escapeHtml(etape.quoi)}` : ''} : ${etape.fait ? 'fait, annuler' : 'marquer comme fait'}" data-pl-focus="carte.activite.${Number(r.id)}.${escapeHtml(etape.coche)}"` : 'disabled'}>${etape.fait ? ACTIVITY_CHECK_SVG : ''}<span>${escapeHtml(etape.nom)}</span>${etape.quoi ? `<small>${escapeHtml(etape.quoi)}</small>` : ''}</button>`;
    }).join('');
    // « Libre » dit deja « a leur rythme » : la ligne laisse toute la place
    // aux puces (le mot reste pour les lecteurs d ecran).
    return `<li class="gc-step gc-step-libres is-${toutFait ? 'fait' : 'libre'}">
      <span class="gc-step-time is-free">Libre<span class="visually-hidden">, ${toutFait ? 'tout est fait' : 'à leur rythme'}</span></span>
      <span class="gc-libres">${puces}</span>
    </li>`;
  };
  // BOWLING ET LASER MENENT A LEUR PLANNING (2026-10-01, Movsar : « qu on
  // puisse cliquer dessus et que ca nous dirige direct vers la reservation
  // des plannings »). Dans la fiche, le nom de l activite est un lien : il
  // ferme la fiche, ouvre le planning de la ressource au jour du dossier et
  // montre le groupe. Le reste de la ligne coche toujours l activite.
  const lienPlanning = (etape) => {
    const ressource = etape.activityId === 'bowling' ? 'bowling' : etape.activityId === 'laser_game' ? 'laser' : '';
    if (!options.coches || !ressource) return `<b>${escapeHtml(etape.nom)}</b>`;
    const mot = ressource === 'bowling' ? 'le planning bowling' : 'le planning laser';
    return `<button type="button" class="gc-step-link" data-pl-focus="fiche.planning.${Number(r.id)}.${escapeHtml(etape.coche || etape.cle || ressource)}" aria-label="${escapeHtml(etape.nom)} : voir ${mot}" title="Voir ${mot}" onclick="voirAuPlanning(${Number(r.id)}, '${ressource}', event)"><b>${escapeHtml(etape.nom)}</b><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 17 17 7"/><path d="M8 7h9v9"/></svg></button>`;
  };
  return `<ol class="gc-steps">${etapes.map((etape, index) => {
    if (enLigne && etape.libre) return etape === libres[0] ? ligneLibres() : '';
    const phase = phases[index];
    const quand = etape.start !== null && etape.start !== undefined
      ? `<span class="gc-step-time">${formatClockDisplay(etape.start)}<small>${formatClockDisplay(etape.end)}</small></span>`
      : `<span class="gc-step-time is-free">${etape.aPlacer ? '--:--' : 'Libre'}</span>`;
    const details = [etape.quoi, etape.ou, etape.groupe].filter(Boolean).join(' · ');
    const montant = prix && prix.has(etape.cle) ? `<span class="gc-step-price">${escapeHtml(prix.get(etape.cle))}</span>` : '';
    // CHAQUE ACTIVITE SE COCHE, SUR LA CARTE COMME DANS LA FICHE (Movsar,
    // 2026-10-01 : « il faut qu on puisse cliquer sur les activites pour dire
    // que ca a ete fait, et terminer »). La case remplace l icone ; toute la
    // ligne coche au toucher (la case porte le nom pour le clavier et les
    // lecteurs d ecran). Sur la carte, la ligne coche au lieu d ouvrir la fiche.
    const cochable = Boolean(etape.coche) && r.status !== 'cancelled' && peutCocher;
    const appel = cochable ? `toggleFormulaActivity(${Number(r.id)}, '${escapeHtml(etape.coche)}', event)` : '';
    const repere = cochable
      ? `<button type="button" class="gc-check${etape.fait ? ' is-on' : ''}" data-pl-focus="${options.coches ? 'fiche' : 'carte'}.activite.${Number(r.id)}.${escapeHtml(etape.coche)}" aria-pressed="${etape.fait}" aria-label="${escapeHtml(etape.nom)}${etape.quoi ? ` ${escapeHtml(etape.quoi)}` : ''} : ${etape.fait ? 'fait, annuler' : 'marquer comme fait'}" onclick="${appel}">${etape.fait ? ACTIVITY_CHECK_SVG : `<span class="gc-check-icon" aria-hidden="true">${renderActivityIcon(etape.activityId)}</span>`}</button>`
      : `<span class="gc-step-icon" aria-hidden="true">${renderActivityIcon(etape.activityId)}</span>`;
    return `<li class="gc-step is-${phase.cle}${index === focus ? ' is-focus' : ''}${cochable ? ' is-cochable' : ''}"${cochable ? ` onclick="${appel}"` : ''}>
      ${quand}
      ${repere}
      <span class="gc-step-what">${lienPlanning(etape)}${details ? `<small>${escapeHtml(details)}</small>` : ''}</span>
      ${phase.mot ? `<span class="gc-step-state">${escapeHtml(phase.mot)}</span>` : ''}
      ${montant}
    </li>`;
  }).join('')}</ol>`;
}

// CE QUI CHANGE LA FACON DE SERVIR, EN ENCADRES : chacun sa couleur et son
// mot, jamais la couleur seule. Rien ne s affiche quand rien ne change.
function getGroupeEncadres(r) {
  const encadres = [];
  const pourquoi = getReservationValidationTexte(r);
  if (isReservationAwaitingReview(r)) {
    // « À vérifier » : le meme mot que le Terrain, le tableau de bord et l export.
    encadres.push({ ton: 'review', titre: 'À vérifier', texte: `${pourquoi.raison ? `${pourquoi.raison} ` : ''}Pas encore confirmée au client : validez-la ou appelez-le.` });
  } else if (pourquoi.surveiller && isUpcomingReservationStatus(r.status)) {
    // Vu par le planning mais sous le niveau du centre : pas de mail, une ligne.
    encadres.push({ ton: 'suivi', titre: 'À surveiller', texte: pourquoi.surveiller });
  }
  // Le prix ajuste passe par LE marqueur partage (renderReservationPriceMark,
  // la regle unique des neuf surfaces) : l encadre n existe que s il parle.
  const marquePrix = renderReservationPriceMark(r, { forme: 'encadre', base: 'gc-price-mark' });
  if (marquePrix) encadres.push({ ton: 'price', titre: 'Prix ajusté', html: marquePrix });
  const formule = r.formuleId ? resolveDisplayFormule(r.formuleId) : null;
  // Le nom de la formule vient du catalogue du centre ; s il n est pas encore
  // charge, le libelle ecrit sur le dossier (« FORMULE 7 ») le dit. Sa
  // variante le suit (nomDeLaFormuleAchetee).
  const nomFormule = nomDeLaFormuleAchetee(r, formule ? formule.name : (r.type === 'formule' || r.formuleId ? getReservationLabel(r) : ''));
  const occasion = getReservationOccasion(r);
  const libelleOccasion = occasion ? (STAFF_OCCASION_LABELS[occasion] || '').split(' / ')[0] : '';
  if (libelleOccasion || nomFormule) {
    const accompagnants = Math.max(0, Math.trunc(Number(r.companions) || 0));
    encadres.push({
      ton: 'occasion',
      titre: [libelleOccasion, nomFormule].filter(Boolean).join(' · '),
      texte: accompagnants ? `${accompagnants} accompagnant${accompagnants > 1 ? 's' : ''} en plus des joueurs` : '',
    });
  }
  // Une seule regle dit si un dossier porte une note (hasReservationNote) :
  // la puce « Avec note », le filtre et ces encadres la lisent tous.
  const aUneNote = hasReservationNote(r);
  const parts = aUneNote ? getReservationNoteParts(r) : { mot: '', suivi: [] };
  if (parts.mot) encadres.push({ ton: 'note', titre: getReservationNoteTitre(r), texte: parts.mot });
  if (parts.suivi.length) encadres.push({ ton: 'suivi', titre: parts.suivi.some(t => /retard/i.test(t)) ? 'Retard' : 'Suivi', texte: parts.suivi.join(' · ') });
  // La note de l equipe, la plus recente, sur la carte : les autres se lisent
  // dans la fiche.
  const notesEquipe = aUneNote ? getReservationNotesEquipe(r) : [];
  const noteClientPermanente = window.PinlaneStaffNotes?.text(r);
  if (noteClientPermanente) encadres.push({ ton: 'equipe', titre: 'Note client · permanente', texte: noteClientPermanente.length > 180 ? noteClientPermanente.slice(0, 177) + '…' : noteClientPermanente });
  if (notesEquipe.length) {
    const derniere = notesEquipe[notesEquipe.length - 1];
    encadres.push({
      ton: 'equipe',
      titre: notesEquipe.length > 1 ? `Note équipe · ${notesEquipe.length}` : 'Note équipe',
      texte: `${derniere.t}${derniere.par ? ` (${derniere.par})` : ''}`,
    });
  }
  return encadres;
}

function renderGroupeEncadres(r, options = {}) {
  // Dans la fiche, « à valider » est deja dit dans le bloc d etat, a cote du
  // bouton qui valide : l encadre le redirait.
  // Dans la fiche, les notes ont leur bloc (renderGroupeNotes) : l encadre
  // les redirait.
  const encadres = getGroupeEncadres(r).filter(e => !(options.sansValidation && e.ton === 'review')
    && !(options.sansNotes && ['note', 'equipe', 'suivi'].includes(e.ton)));
  if (!encadres.length) return '';
  return `<div class="gc-flags${options.large ? ' is-large' : ''}">${encadres.map(e => `<div class="gc-flag tone-${e.ton}"${e.texte ? ` title="${escapeHtml(`${e.titre} : ${e.texte}`)}"` : ''}>
    <b>${escapeHtml(e.titre)}</b>${e.html ? e.html : e.texte ? `<span>${escapeHtml(e.texte)}</span>` : ''}
  </div>`).join('')}</div>`;
}

// LE MOYEN DE PAIEMENT ECRIT. « Comptoir » est ce que Payé ecrivait avant le
// 2026-10-01 sans rien demander : il ne dit pas comment le client a paye.
const GROUPE_MOYENS = [
  { valeur: 'Carte Bancaire', mot: 'Carte' },
  { valeur: 'Espèces', mot: 'Espèces' },
];
function getMoyenPaiementLabel(valeur) {
  const v = String(valeur || '').trim();
  if (/^carte/i.test(v) || v === 'card') return 'Carte';
  if (/^esp[eè]ces$/i.test(v) || v === 'cash') return 'Espèces';
  return '';
}

function prixDossierConnu(r) {
  if (!r || r.price == null || String(r.price).trim() === '') return false;
  const montant = Number(r.price);
  if (!Number.isFinite(montant) || montant < 0) return false;
  if (montant > 0 || Number(r.basePrice) > 0) return true;
  const programme = r.program;
  const items = Array.isArray(programme) ? programme : programme && programme.items;
  return Boolean(programme && programme.priceComplete === true)
    || (Array.isArray(items) && items.length > 0 && items.every(item => item.priceKnown === true && item.price != null && Number.isFinite(Number(item.price))));
}

function renderGroupePrix(r, moment) {
  const paye = r.status === 'paid';
  const moyen = getMoyenPaiementLabel(r.paymentMethod);
  const etat = paye
    ? `<small class="is-paid">Payé${moyen ? ` · ${moyen}` : ''}</small>`
    : moment && moment.etat === 'closing'
      ? '<small class="is-due">À encaisser</small>'
      : '';
  // Sans montant connu (activites tarifees au comptoir), la carte ne montre
  // pas « 0 € » : elle dit ou se fait le prix.
  const montant = prixDossierConnu(r) ? `<b>${formatMoneyCentimes(r.price)}</b>` : '<b class="is-none">Prix sur place</b>';
  return `<div class="gc-price${paye ? ' is-paid' : ''}">${montant}${etat}</div>`;
}

// LES GESTES, UN SEUL A LA FOIS : ce que la carte attend maintenant. Valider
// une demande, pointer l arrivee, encaisser (Carte ou Espèces). Revenir en
// arriere, modifier, annuler : dans la fiche.
// Chaque geste de la carte suit le role, comme dans la fiche (ficheDroits) :
// Valider demande la modification, Arrivé un statut, Encaisser l encaissement.
function renderGroupeActions(r, moment) {
  if (r.status === 'paid' || r.status === 'cancelled') return '';
  const boutons = [];
  const aValider = isReservationAwaitingReview(r) && (typeof canUseStaffPermission !== 'function' || canUseStaffPermission('reservations.edit'));
  if (aValider) {
    boutons.push(`<button type="button" class="gc-btn is-review" onclick="validateReservationDirect(${r.id}, event)">Valider</button>`);
  }
  const fini = moment && (moment.etat === 'closing' || moment.etat === 'done');
  if (isUpcomingReservationStatus(r.status) && !fini && !groupeAJoue(r)) {
    if (typeof canUseStaffPermission !== 'function' || canUseStaffPermission(['reservations.status', 'reservations.edit'])) {
      boutons.push(`<button type="button" class="gc-btn ${aValider ? '' : 'is-primary'}" onclick="setReservationStatusDirect(${r.id}, 'arrived', event)">Arrivé</button>`);
    }
  } else if (typeof canUseStaffPermission !== 'function' || canUseStaffPermission('payments.markPaid')) {
    // Le groupe est la, ou il a fini : la carte attend l encaissement.
    const montant = prixDossierConnu(r) ? ` ${formatMoneyCentimes(r.price)}` : '';
    boutons.push(`<span class="gc-pay" role="group" aria-label="Encaisser${escapeHtml(montant)}">
      <span class="gc-pay-label">Encaisser${escapeHtml(montant)}</span>
      ${GROUPE_MOYENS.map(m => `<button type="button" class="gc-btn is-primary" onclick="encaisserReservation(${r.id}, '${m.valeur}', event)">${m.mot}</button>`).join('')}
    </span>`);
  }
  if (moment && moment.late && r.phone) {
    boutons.push(`<a class="gc-call" href="tel:${escapeHtml(String(r.phone).replace(/\s+/g, ''))}" onclick="event.stopPropagation()">Appeler ${escapeHtml(r.phone)}</a>`);
  }
  if (!boutons.length) return '';
  return `<div class="gc-actions" onclick="event.stopPropagation()">${boutons.join('')}</div>`;
}

// LE BANDEAU DU MOMENT : ce qui ne va pas, en haut de la carte, en mots.
function renderGroupeAlerte(r, moment) {
  if (moment && moment.late) {
    const depuis = formatStaffTerrainDelay(moment.now - moment.item.start);
    // « Appeler » vit avec les gestes de la carte (renderGroupeActions), sur la
    // meme ligne qu « Arrivé » : dans le bandeau il passait a la ligne et
    // allongeait chaque carte en retard (2026-10-05).
    return `<div class="gc-alert is-late"><b>En retard · ${escapeHtml(depuis)}</b><span>Attendu à ${formatClockDisplay(moment.item.start)}, pas encore arrivé</span></div>`;
  }
  if (moment && moment.etat === 'closing' && isUpcomingReservationStatus(r.status) && !groupeAJoue(r)) {
    return '<div class="gc-alert is-unmarked"><b>Non pointé</b><span>Fini sans être pointé arrivé : peut-être pas venu</span></div>';
  }
  return '';
}

// LES ACTIVITES D UNE CARTE PAYEE, EN PUCES (2026-10-02, Movsar : « les
// cartes deja payees sont moches ») : le nom seul, quatre au plus, puis
// « +N ». Le detail (durees, pistes, tours) reste dans la fiche.
function renderActivitesCourtes(r) {
  const items = r && r.program && Array.isArray(r.program.items) ? r.program.items : [];
  let noms = items.map(item => `${typeof nomActivite === 'function' ? nomActivite(item) : item.activityId} · ${participantsLigneProgramme(item, r.pax)}`).filter(Boolean);
  if (!noms.length) {
    const formule = r && r.formuleId ? resolveDisplayFormule(r.formuleId) : null;
    noms = [nomDeLaFormuleAchetee(r, formule ? formule.name : getReservationLabel(r))].filter(Boolean);
  }
  noms = [...new Set(noms)];
  const vus = noms.slice(0, 4);
  const reste = noms.length - vus.length;
  return `<span class="gc-acts">${vus.map(n => `<i>${escapeHtml(n)}</i>`).join('')}${reste > 0 ? `<i class="is-plus" title="${escapeHtml(noms.slice(4).join(', '))}">+${reste}</i>` : ''}</span>`;
}

function renderReservationRow(r, moment = null, options = {}) {
  const span = moment && moment.item ? moment.item : getStaffTerrainSpan(r);
  const termine = (moment && moment.etat === 'done') || Boolean(options.compacte);
  const classes = [
    'res-row', 'gc', r.status,
    moment && moment.late ? 'is-late' : '',
    termine ? 'is-done' : '',
    isReservationAwaitingReview(r) ? 'is-review' : '',
    getReservationHighlightClasses(r),
  ].filter(Boolean).join(' ');
  // LE LISERE DIT L ETAT, la regle du planning Laser (lpTeinte) : bleu
  // confirme, ambre arrive, vert paye, gris pas venu (2026-10-09, « B »).
  const etat = lpTeinte(r).slice(3);
  // UN GROUPE SUR AUCUNE GRILLE (table et plaine d un anniversaire, Kids Fun
  // Day) se dit sur sa carte : c est ici ou nulle part qu on le voit (decision
  // du 2026-07, off-planning-check). L onglet porte aussi « N hors planning ».
  const horsPlanning = getStaffResourceView() === 'all' && isOffPlanningReservation(r);
  const suivi = moment?.late ? 'En retard' : ({ upcoming: 'À venir', onsite: 'Sur place', closing: 'À clôturer' }[moment?.etat] || '');
  // Une carte terminee et payee tient sur sa tete : il n y a plus rien a faire.
  if (termine) {
    return `<article class="${classes}" data-res-row-id="${r.id}" data-etat="${etat}" onclick="openPos(${r.id})" tabindex="0" onkeydown="if(event.key==='Enter'){openPos(${r.id})}">
      <div class="gc-head">
        <div class="gc-when"><b>${formatClockDisplay(span.start)}</b><small>${formatClockDisplay(span.end)}</small></div>
        <div class="gc-who"><h4 class="res-row-name">${escapeHtml(r.name)}</h4><span>${options.encore ? `<b class="gc-tag is-${escapeHtml(options.encore.cle)}">${escapeHtml(options.encore.mot)}</b> · ` : ''}${escapeHtml(joueursDuDossier(r))}${renderReservationPriceMark(r, { forme: 'mot', base: 'gc-price-mark is-word' }) ? ` · ${renderReservationPriceMark(r, { forme: 'mot', base: 'gc-price-mark is-word' })}` : ''}</span>${renderActivitesCourtes(r)}</div>
        ${renderGroupePrix(r, moment)}
      </div>
    </article>`;
  }
  return `<article class="${classes}" data-res-row-id="${r.id}" data-etat="${etat}" onclick="openPos(${r.id})" tabindex="0" onkeydown="if(event.key==='Enter'&&event.target===this){openPos(${r.id})}">
    <div class="gc-head">
      <div class="gc-when"><b>${formatClockDisplay(span.start)}</b><small>${formatClockDisplay(span.end)}</small></div>
      <div class="gc-who"><h4 class="res-row-name">${escapeHtml(r.name)}</h4><span>${escapeHtml(joueursDuDossier(r))}${horsPlanning ? ' · <b class="gc-tag">Hors planning</b>' : ''}</span>${suivi ? `<small class="gc-visit-state">${escapeHtml(suivi)}</small>` : ''}</div>
      ${renderGroupePrix(r, moment)}
    </div>
    ${renderGroupeAlerte(r, moment)}
    ${renderGroupeEtapes(r, moment)}
    ${renderGroupeEncadres(r)}
    ${renderGroupeActions(r, moment)}
  </article>`;
}

// Encaisser = payer AVEC le moyen. Le statut et le moyen partent ensemble.
// CE QUI A ETE ENCAISSE, ET LE GROUPE QUI N EST PAS VENU (2026-10-06, 0056).
// Paye : la somme reellement encaissee, corrigeable (remise, geste, joueur en
// moins), la raison obligatoire si elle differe du prix. Pas encore venu et
// l heure passee : « Pas venu », qui sort le groupe des visites et du chiffre
// de la Direction. Un serveur pas encore migre le dit, rien ne casse.
function groupeHeurePassee(r) {
  if (!r || !r.date) return false;
  if (r.date < todayStr()) return true;
  return r.date === todayStr() && Math.round(currentTimeDecimal() * 60) >= Math.round(timeToNum(r.startTime) * 60);
}
function renderGroupeEncaisseAbsence(r) {
  if (!r) return '';
  const peutEncaisser = canUseStaffPermission(['payments.markPaid']);
  const peutStatut = canUseStaffPermission(['reservations.status', 'reservations.edit']);
  if (r.status === 'paid' && prixDossierConnu(r)) {
    const montant = r.amountPaid != null ? Number(r.amountPaid) : Number(r.price) || 0;
    // La regle du serveur (noterEncaisseOuAbsence) : un encaisse egal au prix,
    // au centime, n est pas une remise et ne dit pas « sur ».
    const remise = r.amountPaid != null && Math.round(Number(r.amountPaid) * 100) !== Math.round((Number(r.price) || 0) * 100);
    return `<div class="pos-encaisse">
      <span class="pos-encaisse-ligne">Encaissé <strong>${escapeHtml(formatMoneyCentimes(montant))}</strong>${remise ? ` sur ${escapeHtml(formatMoneyCentimes(r.price))}${r.discountReason ? `, ${escapeHtml(r.discountReason)}` : ''}` : ''}</span>
      ${peutEncaisser && Object.prototype.hasOwnProperty.call(r, 'amountPaid') ? `<details class="pos-encaisse-corriger">
        <summary>Corriger le montant</summary>
        <div class="pos-encaisse-form">
          <label>Montant encaissé<input type="number" id="encaisse-montant-${r.id}" min="0" step="0.01" inputmode="decimal" value="${montant}"></label>
          <label>Pourquoi il diffère<input type="text" id="encaisse-raison-${r.id}" maxlength="200" placeholder="Remise, geste, joueur en moins…" value="${escapeHtml(r.discountReason || '')}"></label>
          <button type="button" class="gc-btn is-primary" onclick="noterEncaisse(${r.id}, event)">Enregistrer</button>
        </div>
      </details>` : ''}
    </div>`;
  }
  if (!peutStatut || !Object.prototype.hasOwnProperty.call(r, 'absentAt')) return '';
  if (r.absentAt) {
    return `<div class="pos-absent is-on"><span>Noté absent : le groupe n’est pas venu.</span><button type="button" class="gc-btn" onclick="basculerAbsence(${r.id}, false, event)">Annuler</button></div>`;
  }
  return '';
}
// « Pas venu » vit dans le pli « Client en retard » : c est la suite de la
// meme question (il arrive, ou il ne viendra pas), et la fiche garde son
// plafond de boutons visibles.
function renderGroupePasVenu(r) {
  if (!r || r.absentAt || !Object.prototype.hasOwnProperty.call(r, 'absentAt')) return '';
  if (!canUseStaffPermission(['reservations.status', 'reservations.edit'])) return '';
  if (!['pending', 'confirmed'].includes(r.status) || !groupeHeurePassee(r)) return '';
  return `<div class="pos-absent"><span>Le groupe ne viendra pas ?</span><button type="button" class="gc-btn" onclick="basculerAbsence(${r.id}, true, event)">Pas venu</button></div>`;
}
async function ecrireGesteGroupe(id, geste, ev) {
  const r = (state.reservations || []).find(x => String(x.id) === String(id)) || state.selectedRes;
  if (!r) { toast('Réservation introuvable.'); return; }
  const bouton = ev?.target?.closest?.('button');
  if (bouton) { bouton.disabled = true; bouton.setAttribute('aria-busy', 'true'); }
  try {
    const payload = await apiRequest(API_ENDPOINTS.staffReservations, { method: 'PATCH', body: JSON.stringify({ id: r.id, centerId: r.centerId || r.center_id || getCurrentStaffCenterId(), baseUpdatedAt: r.updatedAt, ...geste }) });
    if (!payload?.ok || !payload.reservation) throw new Error('Le serveur n’a pas confirmé. Actualisez le dossier.');
    applyOptimisticReservation(payload.reservation, { preserveEditState: true });
  } catch (error) {
    const fresh = error.reservation || (error.status === 409 && error.payload?.reservation);
    if (fresh) applyOptimisticReservation(fresh, { preserveEditState: true });
    toast(error.message || 'Impossible d’enregistrer.');
  } finally {
    if (bouton?.isConnected) { bouton.disabled = false; bouton.removeAttribute('aria-busy'); }
  }
}
function noterEncaisse(id, ev) {
  const montant = Number(String((document.getElementById(`encaisse-montant-${id}`) || {}).value || '').replace(',', '.'));
  const raison = String((document.getElementById(`encaisse-raison-${id}`) || {}).value || '').trim();
  if (!Number.isFinite(montant) || montant < 0) { toast('Indiquez le montant encaissé.'); return; }
  return ecrireGesteGroupe(id, { encaissement: { montant, raison } }, ev);
}
function basculerAbsence(id, absent, ev) {
  return ecrireGesteGroupe(id, { absent: Boolean(absent) }, ev);
}

function encaisserReservation(id, moyen, ev) {
  setReservationStatusDirect(id, 'paid', ev, { paymentMethod: moyen });
}

// LE PRIX DE CHAQUE ACTIVITE, pour la fiche : celui que le programme d une
// visite enregistre (bowling, laser, duckpin...), pose sur la premiere ligne
// de l activite. Une formule se paie en entier : pas de prix par ligne.
function getGroupePrixParActivite(r) {
  const prix = new Map();
  const items = r && r.program && Array.isArray(r.program.items) ? r.program.items : [];
  if (!items.length || r.formuleId) return prix;
  const etapes = getGroupeProgramme(r);
  items.forEach(item => {
    const montant = item.priceKnown && Number.isFinite(Number(item.price)) ? formatMoneyCentimes(item.price) : 'sur place';
    const cible = item.planned
      ? etapes.find(e => e.activityId === item.activityId && !prix.has(e.cle))
      : etapes.find(e => e.cle === `libre-${items.filter(x => !x.planned && !x.waitOffer).indexOf(item)}`);
    if (cible) prix.set(cible.cle, montant);
  });
  return prix;
}

function renderReservationSection(statusKey, title, subtitle, reservations, moments = null, options = {}) {
  // L ORDRE DU COMPTOIR, lu sur les vraies heures du groupe (premiere et
  // derniere activite), pas sur l heure du dossier : a venir et en retard,
  // celui qui commence le premier ; sur place et a cloturer, celui qui finit
  // le premier, c est lui qui arrive a la caisse ; terminees, la plus recente.
  const span = r => {
    const entry = moments ? moments.get(String(r.id)) : null;
    return entry && entry.item ? entry.item : getStaffTerrainSpan(r);
  };
  const ordered = [...reservations].sort((a, b) => {
    if (statusKey === 'done' && !options.repliable) return span(b).start - span(a).start;
    if (statusKey === 'onsite' || statusKey === 'closing') return span(a).end - span(b).end || span(a).start - span(b).start;
    return span(a).start - span(b).start || String(a.id).localeCompare(String(b.id));
  });
  // LES CATEGORIES SE VOIENT (2026-10-02, Movsar : « categorisation moche »,
  // « un beau truc pour categoriser par heure, par chose cloturee »). Chaque
  // section porte un bandeau : son icone et sa couleur, son titre, son compte,
  // et UNE ligne qui se recompose avec les cartes (joueurs, argent).
  const joueurs = ordered.reduce((n, r) => n + (Number(r.pax) || 0), 0);
  const montant = ordered.reduce((n, r) => n + (Number(r.price) || 0), 0);
  const resume = {
    late: `${formatStaffTerrainCount(joueurs, 'joueur')} attendu${joueurs > 1 ? 's' : ''}`,
    upcoming: `${formatStaffTerrainCount(joueurs, 'joueur')}`,
    onsite: `${formatStaffTerrainCount(joueurs, 'joueur')} sur place`,
    closing: montant > 0 ? `${formatMoney(montant)} à encaisser` : `${formatStaffTerrainCount(joueurs, 'joueur')}`,
    done: montant > 0 ? `${formatMoney(montant)} encaissés` : '',
  }[statusKey] || '';
  const tete = (balise, extra = '') => `<${balise} class="res-section-head gc-band" title="${escapeHtml(subtitle)}">
      <span class="gc-band-icon" aria-hidden="true">${GC_BAND_ICONS[statusKey === 'active' ? 'upcoming' : statusKey] || ''}</span>
      <span class="label">${title}</span>
      <span class="count" data-pl-num="liste.section.${escapeHtml(statusKey)}">${ordered.length}</span>
      ${resume ? `<span class="gc-band-sum">${escapeHtml(resume)}</span>` : ''}
      ${extra}
    </${balise}>`;
  const carte = (r, opts) => renderReservationRow(r, moments ? moments.get(String(r.id)) : null, opts);
  if (options.repliable) {
    // LES DOSSIERS DEJA PAYES, TOUT EN BAS ET REPLIES (2026-10-01, Movsar :
    // « ceux qui sont payes, encaisses, tu peux les mettre tout en bas pour ne
    // voir plus que ceux qui restent »). Paye = arrive (le paiement ne se fait
    // que sur place, 2026-10-02) : un paye joue encore (« Sur place ») ou a fini.
    // Les absents (2026-10-08) se replient de la meme facon, sous les payes :
    // on les rouvre seulement pour annuler un « Pas venu » note par erreur.
    const payees = statusKey === 'done';
    const encore = payees ? ordered.filter(r => { const m = moments ? moments.get(String(r.id)) : null; return m && m.etat !== 'done'; }).length : 0;
    const motDe = r => { const m = moments ? moments.get(String(r.id)) : null; if (!payees || !m || m.etat === 'done') return null; return { cle: 'onsite', mot: 'Sur place' }; };
    return `<details class="res-section gc-section ${statusKey} is-repliable"${options.ouvert ? ' open' : ''} ontoggle="state.${payees ? 'staffPayeesOuvertes' : 'staffAbsentsOuverts'} = this.open">
      ${tete('summary', `${encore ? `<span class="gc-section-note">dont ${encore} encore sur place</span>` : ''}<span class="gc-section-toggle" aria-hidden="true"></span>`)}
      <div class="res-dense-list gc-grid is-compacte" data-pl-stagger="resa.liste.${escapeHtml(statusKey)}">${ordered.map(r => carte(r, { compacte: true, encore: motDe(r) })).join('')}</div>
    </details>`;
  }
  // « À VENIR » PAR HEURE, QUAND IL Y A DU MONDE (Movsar : « quand y aura une
  // trentaine de reservations »). A partir de 7 groupes sur au moins deux
  // heures, une rangee par heure : l heure a gauche, ses groupes a droite. En
  // dessous, la grille seule range deja tout par heure sans trous.
  const heureDe = r => Math.floor(span(r).start);
  const heures = [...new Set(ordered.map(heureDe))];
  const parHeure = statusKey === 'upcoming' && ordered.length >= 7 && heures.length > 1;
  if (parHeure) {
    const rangees = heures.map(h => {
      const groupe = ordered.filter(r => heureDe(r) === h);
      const pax = groupe.reduce((t, r) => t + (Number(r.pax) || 0), 0);
      return `<div class="gc-hour-row">
        <div class="gc-hour"><span>${String(h).padStart(2, '0')}h</span><small><span>${formatStaffTerrainCount(groupe.length, 'groupe')}</span><span>${formatStaffTerrainCount(pax, 'joueur')}</span></small></div>
        <div class="res-dense-list gc-grid" data-pl-stagger="resa.liste.${escapeHtml(statusKey)}.${h}">${groupe.map(r => carte(r)).join('')}</div>
      </div>`;
    }).join('');
    return `<section class="res-section gc-section ${statusKey} is-par-heure">
    ${tete('div')}
    <div class="gc-hours">${rangees}</div>
  </section>`;
  }
  const corps = ordered.map(r => carte(r)).join('');
  return `<section class="res-section gc-section ${statusKey}">
    ${tete('div')}
    ${ordered.length ? `<div class="res-dense-list gc-grid" data-pl-stagger="resa.liste.${escapeHtml(statusKey)}">${corps}</div>` : `<div class="res-empty-inline">Aucune réservation dans cette zone.</div>`}
  </section>`;
}

// Les icones des bandeaux : une forme par categorie (jamais la couleur seule).
const GC_BAND_ICONS = {
  late: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="13" r="8"/><path d="M12 9v4l2 2"/><path d="M5 3 2 6"/><path d="m22 6-3-3"/></svg>',
  upcoming: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',
  onsite: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>',
  closing: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20"/></svg>',
  done: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>',
  absent: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="m17 8 5 5"/><path d="m22 8-5 5"/></svg>',
};

function renderTable() {
  const view = getStaffResourceView();
  const res = scopedStaffReservations(view);
  releaseDeadNoteFilter();
  const counts = getStaffStatusCounts(res);
  const moments = getStaffReservationMoments(res);
  let filtered = res;
  if (state.searchTerm) {
    const q = state.searchTerm.toLowerCase();
    filtered = res.filter(r => r.name.toLowerCase().includes(q) || (r.phone || '').includes(q) || getReservationLabel(r).toLowerCase().includes(q));
  }
  filtered = filterReservationsForStaff(filtered, state.staffStatusFilter);
  const tableTitle = document.getElementById('tableTitleText');
  if (tableTitle) tableTitle.textContent = view === 'all' ? 'Toutes les réservations' : view === 'laser' ? 'Réservations Laser Game' : 'Réservations Bowling';
  document.getElementById('tableCount').textContent = res.length;
  const list = document.getElementById('resList');
  // La liste garde SA position, comme les deux plannings le font depuis
  // toujours : innerHTML la remet a zero, et un poll toutes les quelques
  // secondes renverrait le comptoir en haut de liste au milieu d une lecture.
  // Lue avant le rendu, reposée après (voir ouvrirLotDefilement).
  const [listScrollTop, listScrollLeft] = lireDefilementRendu(list);
  const resourceName = view === 'all' ? 'pour ce jour' : view === 'laser' ? 'Laser Game pour ce jour' : 'Bowling pour ce jour';
  const planningName = view === 'all' ? 'sur un planning' : view === 'laser' ? 'Laser Game' : 'Bowling';
  // LES ONGLETS NE DISAIENT PAS TOUS LA MÊME CHOSE, ET RIEN NE LE DISAIT.
  // Movsar, 2026-08-14 : « ça apparaît dans toutes les catégories, ça va pas du
  // tout ». Sa capture : Tout 9 · À gérer 6 · Sur place 0 · À venir 6 ·
  // Terminées 3. Rien n'était cassé dans le filtrage : les six puces étaient
  // peintes à l'identique alors qu'elles répondent à TROIS questions
  // différentes.
  //   - « Tout » = absence de filtre ;
  //   - « Sur place / À venir / Terminées » = l'ÉTAT, trois valeurs exclusives
  //     qui se totalisent (8 + 8 + 8 = 24) ;
  //   - « À gérer » = l'UNION de deux états (tout sauf terminé), donc chaque
  //     réservation non terminée y apparaît EN PLUS de son état ;
  //   - « Avec note » = un ATTRIBUT, vrai dans n'importe quel état.
  // Alignées sur une seule rangée, elles se lisent comme cinq cases d'un même
  // classement, et un gérant qui additionne tombe sur 40 pour 24 dossiers.
  // Le recoupement reste : « tout ce qui n'est pas fini », c'est la liste de
  // travail d'un comptoir. Mais il est désormais VISIBLE et NOMMÉ : deux
  // groupes séparés par un filet, les recoupements marqués d'un repère et dits
  // dans leur infobulle.
  // LA PHRASE-FORMULE EST PARTIE (lot C, 2026-09-30). « 17 réservations =
  // 4 sur place + 10 à venir + 3 terminées · « À gérer » réunit les 14 non
  // terminées » expliquait l'écran au lieu de le montrer : les puces portent
  // déjà leurs comptes, et le groupe séparé dit le recoupement. Le « N hors
  // planning » qui la précédait est le titre de la première section.
  const crossHint = (label, text) => ` title="${escapeHtml(text)}" aria-label="${escapeHtml(`${label} : ${text}`)}"`;
  const crossMark = `<svg class="chip-cross-mark" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="9" cy="12" r="6"/><circle cx="15" cy="12" r="6"/></svg>`;
  const notesHint = 'recoupe les sections : les réservations qui portent une note, quelle que soit leur section';
  // UNE PUCE PAR SECTION, AVEC LE NOMBRE DE SA SECTION (2026-10-08, voir
  // STAFF_LISTE_SECTIONS). « En retard » et « Pas venus » ne se montrent que
  // s il y en a, ou si le filtre est pose dessus.
  const filtreActif = normaliserFiltreListe(state.staffStatusFilter);
  const puce = (cle, mot, n) => `<button class="status-chip ${filtreActif === cle ? `active ${cle}` : ''}${cle === 'late' ? ' is-late' : ''}" onclick="setStaffStatusFilter('${cle}')">${mot} <span>${n}</span></button>`;
  const pucesVues = STAFF_LISTE_SECTIONS.filter(cle => !['late', 'absent'].includes(cle) || counts[cle] > 0 || filtreActif === cle);
  const toolbar = `<div class="table-toolbar">
    <div class="status-filters">
      <div class="status-group" role="group" aria-label="Filtrer par section. Les sections ne se recoupent pas et se totalisent.">
        ${puce('all', 'Tout', counts.all)}
        ${pucesVues.map(cle => puce(cle, STAFF_LISTE_MOTS[cle], counts[cle])).join('')}
      </div>
      ${(counts.notes || filtreActif === 'notes') ? `<div class="status-group status-group-cross" role="group" aria-label="Vue qui recoupe les sections">
        <button class="status-chip is-cross ${filtreActif === 'notes' ? 'active notes' : ''}" onclick="setStaffStatusFilter('notes')"${crossHint('Avec note', notesHint)}>${crossMark}Avec note <span>${counts.notes}</span></button>
      </div>` : ''}
    </div>
  </div>`;
  if (!filtered.length) {
    poserHtmlSurface(list, `${toolbar}<div class="empty-state">
      <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
      <div class="e-title">${state.searchTerm ? 'Aucun résultat' : `Aucune réservation ${resourceName}`}</div>
      <div class="e-sub">${state.searchTerm ? 'Essayez un autre mot-clé' : `Cliquez sur "Réservation rapide" ou ${planningName} pour en créer une`}</div>
    </div>`);
    poserDefilementRendu(list, listScrollTop, listScrollLeft);
    return;
  }
  // LES SECTIONS DU COMPTOIR (2026-10-01). Le RETARD sort d « À venir » et
  // passe en tete, en rouge : c est la premiere chose a voir. Les dossiers
  // « hors planning » (ni piste ni arene) ne forment plus une section a part :
  // la carte dit leurs activites, ils vivent dans leur moment comme les autres.
  // Les dossiers terminés ET payés se replient. Un groupe qui a réglé avant
  // de jouer garde son programme complet parmi les visites à suivre.
  const parSection = cle => filtered.filter(r => getStaffListeSection(moments, r) === cle);
  const sousTitres = {
    late: 'Heure passée, pas encore pointés arrivés',
    upcoming: 'Pas encore arrivés, par heure',
    onsite: 'Arrivés, pendant leur visite',
    closing: 'Visite finie, pas encore payée',
  };
  const sections = ['late', 'upcoming', 'onsite', 'closing']
    .map(cle => ({ key: cle, title: STAFF_LISTE_MOTS[cle], subtitle: sousTitres[cle], rows: parSection(cle) }))
    .filter(section => section.rows.length > 0);
  // Le comptoir garde les groupes à leur heure : pointer ou encaisser ne
  // déplace plus la carte au milieu du service. Les puces restent des filtres.
  if (filtreActif === 'all' || filtreActif === 'notes') {
    const visites = sections.flatMap(section => section.rows);
    sections.splice(0, sections.length, ...(visites.length ? [{ key: 'active', title: 'Visites à suivre', subtitle: 'Par heure de début · les paiements ne terminent pas les activités', rows: visites }] : []));
  }
  const payes = parSection('paid');
  const absents = parSection('absent');
  // Une section repliee choisie par sa puce s ouvre d elle-meme, comme la
  // seule qui reste a montrer.
  const payesOuverts = filtreActif === 'paid' || (!sections.length && payes.length > 0) || Boolean(state.staffPayeesOuvertes);
  const absentsOuverts = filtreActif === 'absent' || (!sections.length && !payes.length) || Boolean(state.staffAbsentsOuverts);

  poserHtmlSurface(list, `${toolbar}
  <div class="res-sections gc-sections">
    ${sections.map(section => renderReservationSection(section.key, section.title, section.subtitle, section.rows, moments)).join('')}
    ${payes.length ? renderReservationSection('done', 'Terminées et payées', 'Toutes les activités sont cochées comme faites et le dossier est payé', payes, moments, { repliable: true, ouvert: payesOuverts }) : ''}
    ${absents.length ? renderReservationSection('absent', STAFF_LISTE_MOTS.absent, 'Notés « Pas venu » dans la fiche', absents, moments, { repliable: true, ouvert: absentsOuverts }) : ''}
  </div>`);
  poserDefilementRendu(list, listScrollTop, listScrollLeft);
  ajusterHauteurListe();
  suivreBarreDeLaListe(list);
}

// LES TITRES DE SECTION COLLENT SOUS LES FILTRES, JAMAIS DESSOUS (Movsar,
// 2026-10-08 : « j aime pas quand le truc avec a venir, cloturer etc passe
// au-dessus des categories »). La barre des filtres et les bandeaux de
// section collaient tous deux en haut de la liste : le bandeau passait sous
// la barre. Les bandeaux collent desormais a la hauteur de la barre, mesuree
// ici (elle passe sur deux lignes quand l ecran se resserre).
let observateurBarreListe = null;
function suivreBarreDeLaListe(list) {
  const barre = list && list.querySelector(':scope > .table-toolbar');
  if (!barre) return;
  const poser = () => {
    const valeur = `${Math.ceil(barre.getBoundingClientRect().height)}px`;
    if (list.style.getPropertyValue('--liste-barre-h') !== valeur) list.style.setProperty('--liste-barre-h', valeur);
  };
  poser();
  if (typeof ResizeObserver !== 'function') return;
  if (observateurBarreListe && observateurBarreListe.cible === barre) return;
  if (observateurBarreListe) observateurBarreListe.disconnect();
  observateurBarreListe = new ResizeObserver(poser);
  observateurBarreListe.cible = barre;
  observateurBarreListe.observe(barre);
}

// LA LISTE DESCEND JUSQU AU BAS DE L ECRAN (2026-10-08) : sa boite fait la
// hauteur de l ecran moins ce qui la precede et ce qui la suit (les marges
// du bas de page), soit --liste-haut, lu par pinlane-staff.css : la page ne
// defile pas, seule la liste defile. Quand elle commence sous la moitie de
// l ecran (telephone, en-tete empile), elle prend l ecran entier : on y
// arrive en faisant defiler la page, puis elle le remplit.
function ajusterHauteurListe() {
  const box = document.getElementById('staffTableBox');
  if (!box || box.classList.contains('hidden') || box.classList.contains('expanded')) return;
  const haut = Math.round(box.getBoundingClientRect().top + window.scrollY);
  const enDessous = haut > window.innerHeight * 0.55;
  const valeur = `${enDessous ? 0 : haut + espaceSousLaListe(box)}px`;
  if (box.style.getPropertyValue('--liste-haut') !== valeur) box.style.setProperty('--liste-haut', valeur);
  // Sous un planning, elle garde la hauteur de l ecran meme quand elle se
  // vide : une carte qui raccourcit (un paiement retire sa rangee de boutons)
  // raccourcissait la page, le navigateur la remontait et la carte touchee
  // sautait (rush-status, 52 px).
  if (box.classList.contains('is-plein-ecran') !== enDessous) box.classList.toggle('is-plein-ecran', enDessous);
}
// Ce qui suit la boite dans la page : les marges basses de ses parents et
// leurs freres suivants dans le flux. Mesure sur les styles, pas sur la
// hauteur du document, qui vaut au moins l ecran et ferait tourner le calcul
// en rond (la boite retrecie laisserait du vide compte comme une marge).
function espaceSousLaListe(box) {
  let bas = parseFloat(getComputedStyle(box).marginBottom) || 0;
  for (let el = box; el.parentElement && el !== document.body; el = el.parentElement) {
    for (let suivant = el.nextElementSibling; suivant; suivant = suivant.nextElementSibling) {
      const cs = getComputedStyle(suivant);
      if (cs.display === 'none' || cs.position === 'fixed' || cs.position === 'absolute') continue;
      bas += suivant.getBoundingClientRect().height + (parseFloat(cs.marginTop) || 0) + (parseFloat(cs.marginBottom) || 0);
    }
    const parent = getComputedStyle(el.parentElement);
    bas += (parseFloat(parent.paddingBottom) || 0) + (parseFloat(parent.borderBottomWidth) || 0);
  }
  return Math.round(bas);
}
window.addEventListener('resize', () => ajusterHauteurListe());

function quickAction(id, status) {
  setReservationStatusDirect(id, status);
}

async function setReservationStatusDirect(id, status, ev, options = {}) {
  if (ev) ev.stopPropagation();
  const key = String(id);
  const filtreAvant = state.staffStatusFilter;
  let current = state.reservations.find(r => String(r.id) === key);
  if (!current) {
    // Depuis Terrain/Groupes la résa peut ne pas être dans state.reservations
    // (autre date/source). On la récupère et on l'injecte pour que la mise à
    // jour optimiste et le re-render fonctionnent.
    const external = findStaffReservationById(id);
    if (external) {
      upsertReservationInState(external);
      current = state.reservations.find(r => String(r.id) === key) || external;
    }
  }
  if (!current) {
    toast('Réservation introuvable.');
    return;
  }
  // LE MOYEN DE PAIEMENT (2026-10-01) : « Payé » demande Carte ou Espèces.
  // Un dossier deja paye dont on corrige le moyen s ecrit quand meme.
  const moyenDemande = status === 'paid' ? String(options.paymentMethod || '').trim() : '';
  const corrigeMoyen = Boolean(moyenDemande) && current.status === 'paid' && moyenDemande !== current.paymentMethod;
  // Le dossier est deja dans l etat que le bouton demande : rien a ecrire.
  // Un autre poste l a deja fait (2026-10-08) : le clic sortait sans un mot
  // et le bouton restait la. On le dit, et l ecran se remet a jour.
  if (reservationAlreadyInStatus(current, status) && !corrigeMoyen) {
    if (ev) {
      toast({ arrived: 'Ce groupe est déjà pointé arrivé.', paid: 'Ce dossier est déjà payé.' }[status] || 'C’est déjà fait.');
      renderStaffData();
      repeindreFicheSiChangee();
    }
    return;
  }
  // Anti double-envoi : même statut déjà en vol → on ignore. La résa affiche
  // déjà la valeur voulue (optimiste), inutile de re-PATCH.
  if (isReservationMutationInFlight(id, 'status', status)) return;
  const requestKey = Number(id);
  const requestSeq = ++statusSaveSeq;
  statusSaveLatestSeqByReservation[requestKey] = requestSeq;
  const isLatestRequest = () => statusSaveLatestSeqByReservation[requestKey] === requestSeq;
  setReservationMutationInFlight(id, 'status', status);
  const clicked = ev?.target?.closest?.('button') || ev?.currentTarget;
  const previousLabel = clicked?.textContent;
  if (clicked?.tagName === 'BUTTON') { clicked.disabled = true; clicked.setAttribute('aria-busy','true'); clicked.textContent = 'Enregistrement…'; }
  // La version sur laquelle le geste s ecrit : c est elle que « Annuler »
  // remet (un « Payé » enchaine sur un « Arrivé » se defait en « Arrivé »).
  let versionEcrite = current;
  return enchainerEcritureReservation(id, async derniere => {
    const base = derniere && String(derniere.id) === key ? derniere : current;
    versionEcrite = base;
    const payload = await apiRequest(API_ENDPOINTS.staffReservations, { method: 'PATCH', body: JSON.stringify({ id: base.id, centerId: base.centerId || base.center_id || getCurrentStaffCenterId(), baseUpdatedAt: base.updatedAt, status, ...(moyenDemande ? { paymentMethod: moyenDemande } : {}) }) });
    if (!payload?.ok || !payload.reservation || String(payload.reservation.id) !== key || String(payload.reservation.centerId || payload.reservation.center_id) !== String(base.centerId || base.center_id || getCurrentStaffCenterId()) || payload.reservation.status !== status || (moyenDemande && payload.reservation.paymentMethod !== moyenDemande)) throw new Error('Le serveur n’a pas confirmé ce statut. Actualisez le dossier.');
    return payload;
  }).then(payload => {
    if (!isLatestRequest()) return;
    // Mesuré à la réponse : on respecte aussi un défilement fait pendant
    // l'enregistrement, et aucune ancre n'est posée si l'on a quitté la liste.
    const ancreY = document.querySelector(`[data-res-row-id="${Number(id)}"]`)?.getBoundingClientRect().top;
    // Un filtre ciblé ne doit pas faire disparaître le groupe que l'on sert.
    // On rejoint la vue complète seulement si ce dossier quitte le filtre.
    if (state.staffStatusFilter === filtreAvant && !['all', 'notes'].includes(normaliserFiltreListe(filtreAvant))
      && !filterReservationsForStaff([payload.reservation], filtreAvant).length) state.staffStatusFilter = 'all';
    applyOptimisticReservation(payload.reservation, { preserveEditState: true });
    if (Number.isFinite(ancreY)) requestAnimationFrame(() => {
      const carte = document.querySelector(`[data-res-row-id="${Number(id)}"]`);
      if (!carte) return;
      let parent = carte.parentElement;
      while (parent && parent !== document.body) {
        if (parent.scrollHeight > parent.clientHeight && /auto|scroll/.test(getComputedStyle(parent).overflowY)) {
          parent.scrollTop += carte.getBoundingClientRect().top - ancreY;
          return;
        }
        parent = parent.parentElement;
      }
      window.scrollBy(0, carte.getBoundingClientRect().top - ancreY);
    });
    // Ré-ancre la protection sur la valeur confirmée par le serveur et repousse
    // le délai de grâce : les lectures (staff-state) peuvent encore être en
    // retard sur l'écriture qui vient d'être committée.
    markReservationMutation(id, payload.reservation, ['status', 'paymentMethod']);
    // UN SEUL RETOUR POUR UNE SEULE ACTION. La pastille qui bascule EST le
    // retour : le bouton passe en `active`, la ligne change de section. Un
    // message qui arrive 300 ms plus tard raconte une DEUXIEME fois ce que
    // l'ecran a deja dit, et c'est ce troisieme signal (rendu optimiste, puis
    // re-rendu a l'echo, puis message) qui donnait l'impression d'un double
    // clic. L'echec, lui, garde son message : il dit quelque chose de neuf.
    // ANNULER UN GESTE (2026-10-12) dit aussi quelque chose de neuf : le
    // chemin du retour. « Arrivé » et « Payé » laissent quelques secondes un
    // toast qui porte « Annuler » ; c est le seul message d un statut reussi.
    if (!options.sansAnnulation && ['arrived', 'paid'].includes(status)) proposerAnnulationGeste(versionEcrite, payload.reservation);
  }).catch(error => {
    if (!isLatestRequest()) return;
    const fresh = error.reservation || (error.status === 409 && error.payload?.reservation);
    if (fresh) applyOptimisticReservation(fresh, { preserveEditState: true });
    const message = error.message || 'Impossible de mettre à jour le statut.';
    if (state.selectedRes && String(state.selectedRes.id) === key) setEditError(message);
    if (typeof showPlanningMoveNotice === 'function') showPlanningMoveNotice('Statut non enregistré', message, 'warning');
    toast(message);
  }).finally(() => {
    clearReservationMutationInFlight(id, 'status');
    if (clicked?.isConnected) { clicked.disabled = false; clicked.removeAttribute('aria-busy'); clicked.textContent = previousLabel; }
    if (isLatestRequest()) delete statusSaveLatestSeqByReservation[requestKey];
  });
}

function quickPay(id) {
  setReservationStatusDirect(id, 'paid');
}

// Coche/décoche une activité de formule comme « faite ». PATCH MINIMAL
// { id, centerId, activityProgress } → chemin permission-light (reservations.status,
// staff comptoir/terrain OK) + AUCUN replan (activityProgress hors REPLAN_FIELDS) →
// l'opsPlan reste intact, seule la colonne activity_progress change. Optimiste +
// rollback + protection anti-poll (markReservationMutation) comme le statut.
function toggleFormulaActivity(reservationId, key, ev) {
  if (ev) ev.stopPropagation();
  const idKey = String(reservationId);
  let current = state.reservations.find(r => String(r.id) === idKey);
  if (!current) {
    const external = findStaffReservationById(reservationId);
    if (external) {
      upsertReservationInState(external);
      current = state.reservations.find(r => String(r.id) === idKey) || external;
    }
  }
  if (!current) { toast('Réservation introuvable.'); return; }
  const progress = current.activityProgress && typeof current.activityProgress === 'object'
    ? { ...current.activityProgress }
    : {};
  const wasDone = !!(progress[key] && progress[key].done);
  if (wasDone) {
    delete progress[key];
  } else {
    progress[key] = { done: true, doneAt: new Date().toISOString(), by: state.staffAuthSession?.member?.name || 'Staff' };
  }
  const nextReservation = { ...current, activityProgress: progress };
  const requestKey = Number(reservationId);
  const requestSeq = ++activitySaveSeq;
  activitySaveLatestSeqByReservation[requestKey] = requestSeq;
  const isLatestRequest = () => activitySaveLatestSeqByReservation[requestKey] === requestSeq;
  // La surface courante et la fiche ouverte se repeignent, sauf ce que
  // applyOptimisticReservation vient deja de repeindre : depuis le 2026-10-08
  // ses signatures comptent les coches, et la fiche se peignait deux fois.
  const refreshSurfaces = (deja = {}) => {
    if (state.view === 'staff' && !deja.liste) { try { renderStaffData(); } catch (e) { /* page peut ne plus être montée */ } }
    if (state.selectedRes && Number(state.selectedRes.id) === Number(reservationId) && !deja.fiche) { try { renderPos(); } catch (e) { /* overlay fermé */ } }
  };
  // CE QUI EST DEJA A L ECRAN NE SE REPEINT PAS (2026-08-26, Movsar : « quand
  // on coche ou decoche ca rafraichit 2 fois »). Le clic peint l etat optimiste ;
  // l echo du serveur porte la MEME progression et ne changeait donc rien a
  // l ecran, mais reconstruisait quand meme la fiche et la liste entieres. On
  // compare ce que le serveur DIT a ce qu on a deja peint, et on ne repeint que
  // s il dit autre chose (refus, normalisation, coche d un collegue).
  const empreinteProgression = (p) => JSON.stringify(
    Object.keys(p || {}).filter((cle) => p[cle] && p[cle].done).sort()
  );
  const empreinteOptimiste = empreinteProgression(progress);
  markReservationMutation(reservationId, nextReservation, ['activityProgress']);
  refreshSurfaces(applyOptimisticReservation(nextReservation, { preserveEditState: true }));
  // UNE COCHE, PAS TOUT LE SUIVI (2026-09-25) : le serveur ajoute ou retire
  // CETTE cle sur ce qui est en base (setReservationActivityDone). Envoyer le
  // suivi entier effacait la coche qu un autre poste venait de poser sur une
  // autre activite du meme dossier.
  const coche = progress[key] || null;
  enchainerEcritureReservation(reservationId, () => apiRequest(API_ENDPOINTS.staffReservations, {
    method: 'PATCH',
    body: JSON.stringify({
      id: Number(reservationId),
      centerId: current.centerId || (typeof getCurrentStaffCenterId === 'function' ? getCurrentStaffCenterId() : 'libramont'),
      activityToggle: { key, done: !wasDone, doneAt: coche ? coche.doneAt : '', by: coche ? coche.by : '' },
    })
  })).then(payload => {
    if (!isLatestRequest()) return;
    if (payload?.reservation) {
      const empreinteServeur = empreinteProgression(payload.reservation.activityProgress);
      const peint = applyOptimisticReservation(payload.reservation, { preserveEditState: true });
      markReservationMutation(reservationId, payload.reservation, ['activityProgress']);
      if (empreinteServeur !== empreinteOptimiste) refreshSurfaces(peint);
    }
  }).catch(error => {
    if (!isLatestRequest()) return;
    const peint = applyOptimisticReservation(current, { preserveEditState: true });
    clearReservationMutation(reservationId);
    refreshSurfaces(peint);
    toast(error.message || "Impossible d'enregistrer l'activité.");
  }).finally(() => {
    if (isLatestRequest()) delete activitySaveLatestSeqByReservation[requestKey];
  });
}

async function cancelRes(id, ev) {
  if (ev) ev.stopPropagation();
  if (!(await staffConfirm({ title: 'Annuler cette réservation ?', body: 'Le dossier reste au journal, le créneau se libère.', confirmLabel: 'Annuler la résa', danger: true }))) return;
  const current = state.reservations.find(r => String(r.id) === String(id)) || findStaffReservationById(id);
  if (!current) {
    toast('Réservation introuvable.');
    return;
  }
  applyOptimisticReservation({ ...current, status: 'cancelled' }, { preserveEditState: true });
  try {
    const payload = await envoyerModificationReservation(current, (dossier) => ({ ...dossier, status: 'cancelled' }));
    applyOptimisticReservation(payload.reservation, { preserveEditState: true });
    if (state.selectedRes && state.selectedRes.id === id) closePos();
    toast('Réservation annulée');
  } catch (error) {
    applyOptimisticReservation(error.reservation || current, { preserveEditState: true });
    toast(error.message || 'Impossible d’annuler la réservation.');
  }
}

async function deleteRes(id, ev) {
  if (ev) ev.stopPropagation();
  const current = state.reservations.find(r => r.id === id);
  if (!current) return;
  // La confirmation NOMME ce qu'elle détruit. « Supprimer cette réservation ? »
  // ne dit pas laquelle : on clique dessus en pensant à une autre. Elle dit
  // aussi que c'est définitif, parce que ça l'est : il n'y a pas d'annulation.
  const quoi = `${current.name || 'Client'} · ${current.startTime || ''} · ${current.pax || 0} joueur${(current.pax || 0) > 1 ? 's' : ''}`;
  if (!(await staffConfirm({ title: `Supprimer définitivement la réservation #${id} ?`, body: `${quoi}\n\nCette action est irréversible. Pour garder la trace du dossier, utilisez plutôt « Annuler réservation ».`, confirmLabel: 'Supprimer', danger: true }))) return;
  removeOptimisticReservation(id);
  // La fiche se ferme : elle décrivait un dossier qui n'existe plus. Elle
  // restait ouverte, avec ses boutons « Enregistrer » et « Arrivé » actifs sur
  // une réservation supprimée.
  if (state.selectedRes && state.selectedRes.id === id) closePos();
  try {
    await apiRequest(API_ENDPOINTS.staffReservations, {
      method: 'DELETE',
      body: JSON.stringify({ id })
    });
    toast('Réservation supprimée');
  } catch (error) {
    applyOptimisticReservation(current, { preserveEditState: true });
    toast(error.message || 'Impossible de supprimer la réservation.');
  }
}

function editRes(id, ev) {
  if (ev) ev.stopPropagation();
  state.selectedRes = state.reservations.find(r => r.id === id);
  if (!state.selectedRes) return;
  state.activeTab = 'modifier';
  state.editState = etatEditionDepuis(state.selectedRes);
  syncEditLaneAssignment();
  renderPos();
}

function openPos(id) {
  posPriceEditOpen = false;
  plisRetardOuverts.clear();
  const reservation = findStaffReservationById(id);
  if (!reservation) {
    toast('Réservation introuvable ou non chargée.');
    return;
  }
  upsertReservationInState(reservation);
  state.selectedRes = reservation;
  state.activeTab = 'details';
  state.editState = etatEditionDepuis(reservation);
  renderPos();
}

// DE LA FICHE AU PLANNING : la ressource ouverte au jour du dossier, filtres
// leves (le groupe doit s y voir), et son bloc amene au centre puis souligne.
function voirAuPlanning(reservationId, ressource, ev) {
  if (ev) ev.stopPropagation();
  const r = findStaffReservationById(reservationId);
  if (!r) { toast('Réservation introuvable.'); return; }
  const cible = ressource === 'laser' ? 'laser' : 'bowling';
  if (cible === 'bowling' && !canUseStaffPermission('planning.bowling')) { toast('Planning bowling non autorisé.'); return; }
  if (cible === 'laser' && !canUseStaffPermission('planning.laser')) { toast('Planning laser non autorisé.'); return; }
  if (!canUseStaffPage('planning')) { toast('Accès planning non autorisé.'); return; }
  closePos();
  state.searchTerm = '';
  state.staffPlanningExpanded = false;
  state.staffLaserPlanningExpanded = false;
  state.staffTableExpanded = false;
  state.staffGlobalExpanded = false;
  const autreJour = r.date && r.date !== state.currentDate;
  if (autreJour) state.currentDate = r.date;
  if (cible === 'laser') lpRevelerGroupe(r.id);
  openStaffPlanningResource(cible);
  if (state.staffMenuPage !== 'planning') return;
  if (autreJour) syncDateReservations(r.date, { silent: true });
  montrerAuPlanning(r.id, cible, 16);
}

function montrerAuPlanning(reservationId, ressource, essais) {
  window.setTimeout(() => {
    const id = CSS.escape(String(reservationId));
    const blocs = [...document.querySelectorAll(ressource === 'laser'
      ? `[data-laser-res-id="${id}"]`
      : `[data-booking-res-id="${id}"]`)];
    if (!blocs.length) {
      if (essais > 1) montrerAuPlanning(reservationId, ressource, essais - 1);
      else toast(ressource === 'laser' ? 'Ce groupe n’a pas encore de partie placée au planning laser.' : 'Ce groupe n’est pas au planning bowling ce jour-là.');
      return;
    }
    blocs[0].scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' });
    blocs.forEach(bloc => {
      bloc.classList.remove('is-called');
      void bloc.offsetWidth;
      bloc.classList.add('is-called');
      window.setTimeout(() => bloc.classList.remove('is-called'), 2600);
    });
    try { blocs[0].focus({ preventScroll: true }); } catch (e) { /* bloc non focalisable */ }
  }, 150);
}

function closePos() {
  state.selectedRes = null;
  ficheFaitsPeints = '';
  const overlay = document.getElementById('posOverlay');
  overlay.classList.add('hidden');
  overlay.classList.remove('centered');
  overlay.innerHTML = '';
  // Le focus revient d'où il venait : la ligne ou la carte qu'on avait ouverte.
  if (posReturnFocus && document.contains(posReturnFocus)) {
    try { posReturnFocus.focus({ preventScroll: true }); } catch (e) { /* élément disparu entre-temps */ }
  }
  posReturnFocus = null;
}

// LE GARDE-FOU DE « MODIFIER » (2026-10-12). Fermer la fiche (croix, Échap,
// clic dehors, « Fermer ») ou revenir a « Infos » avec une saisie non
// enregistree demande confirmation ; elle se perdait sans un mot. La saisie
// se compare au formulaire tel qu il s est ouvert (pistes deja proposees
// comprises), et le contenu d une formule a sa propre empreinte.
function empreinteFormulaireEdition(etat) {
  return valeurReservationComparable(['name', 'phone', 'email', 'date', 'startTime', 'duration', 'pax', 'status', 'lanesStr', 'price', 'prixFige'].map(champ => etat[champ]));
}

function noterFormulaireEdition() {
  const edition = state.editState && departsEdition().get(state.editState);
  if (edition) edition.formulaire = empreinteFormulaireEdition(state.editState);
}

function ficheEditionModifiee() {
  const es = state.editState;
  if (state.activeTab !== 'modifier' || !es || !state.selectedRes) return false;
  if (editProgramAChange()) return true;
  const edition = departsEdition().get(es);
  if (edition && edition.formulaire) return empreinteFormulaireEdition(es) !== edition.formulaire;
  // Apres un conflit, la reference est le dossier d origine.
  const origine = (edition && edition.origine) || state.selectedRes;
  return empreinteFormulaireEdition(es) !== empreinteFormulaireEdition({ ...origine, lanesStr: (origine.lanes || []).join(', ') });
}

function confirmerAbandonEdition() {
  return staffConfirm({
    title: 'Quitter sans enregistrer ?',
    body: 'Les changements de ce dossier ne sont pas enregistrés.',
    confirmLabel: 'Quitter sans enregistrer',
    cancelLabel: 'Continuer la saisie',
    danger: true,
  });
}

// Fermer la fiche a la demande de la personne. Les fermetures du code
// (apres un enregistrement, une annulation, vers le planning) gardent closePos.
function fermerFiche() {
  if (!ficheEditionModifiee()) { closePos(); return; }
  confirmerAbandonEdition().then(ok => { if (ok && state.selectedRes) closePos(); });
}

function setTab(t) {
  const cible = t === 'caisse' ? 'details' : t;
  if (cible === 'modifier' && !ficheDroits().modifier) return;
  // Re-toucher « Modifier » remettait le formulaire a zero, saisie comprise.
  if (cible === 'modifier' && state.activeTab === 'modifier' && ficheEditionModifiee()) return;
  if (cible !== 'modifier' && ficheEditionModifiee()) {
    confirmerAbandonEdition().then(ok => { if (ok && state.selectedRes) ouvrirOngletFiche(cible); });
    return;
  }
  ouvrirOngletFiche(cible);
}

function ouvrirOngletFiche(cible) {
  state.activeTab = cible;
  if (state.activeTab === 'modifier') {
    state.editState = etatEditionDepuis(state.selectedRes);
    syncEditLaneAssignment();
    noterFormulaireEdition();
  }
  renderPos();
}

// Classe « toutes les activités faites » pour styliser (griser) une carte planning.
function activitiesCompleteClass(r) {
  if (typeof reservationHasFormulaActivities !== 'function' || !reservationHasFormulaActivities(r)) return '';
  return getFormulaActivityProgressSummary(r).allDone ? ' activities-complete' : '';
}

// Pill compacte « faites/total » pour les cartes planning (formules uniquement).
function renderActivityProgressPill(r) {
  if (typeof reservationHasFormulaActivities === 'function' && !reservationHasFormulaActivities(r)) return '';
  const summary = getFormulaActivityProgressSummary(r);
  if (!summary.total) return '';
  // UNE PROGRESSION SE VOIT, ELLE NE SE LIT PAS.
  // Movsar, 2026-08-14 : « le 0/4, le design je le trouve pas fou ». Deux
  // chiffres separes d'une barre oblique demandent une LECTURE pour dire une
  // chose qu'une jauge dit d'un coup d'oeil, et ils prenaient la place d'une
  // donnee sur une carte qui en manque. Le compte exact reste dans l'infobulle
  // et dans le texte lu par la synthese vocale : rien n'est perdu, seule la
  // forme change.
  // UN SEGMENT PAR ACTIVITE. A zero, la jauge continue n etait qu un trait
  // gris sans rien dedans : elle se lisait comme un emplacement vide, pas
  // comme « 0 sur 4 ». Quatre traits dont aucun n est plein disent le compte
  // d un coup d oeil. Au-dela de six, les segments deviendraient des points :
  // la jauge continue reprend.
  const part = Math.max(0, Math.min(1, summary.total ? summary.done / summary.total : 0));
  const jauge = summary.total <= 6
    ? `<span class="activity-bar is-seg">${Array.from({ length: summary.total }, (_, index) => `<span class="activity-seg${index < summary.done ? ' on' : ''}"></span>`).join('')}</span>`
    : `<span class="activity-bar"><span class="activity-bar-fill" style="width:${Math.round(part * 100)}%"></span></span>`;
  return `<span class="activity-pill${summary.allDone ? ' done' : ''}" role="img"`
    + ` title="Activités faites : ${summary.done}/${summary.total}"`
    + ` aria-label="${summary.done} activité${summary.done > 1 ? 's' : ''} faite${summary.done > 1 ? 's' : ''} sur ${summary.total}">`
    + `<span class="visually-hidden">${summary.done}/${summary.total}</span>`
    + jauge
    + `</span>`;
}

function formatActivityDoneTime(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return d.toLocaleTimeString('fr-BE', { hour: '2-digit', minute: '2-digit' });
}

